local probe = {
    lines = {},
    type_name = "app.ItemManager",
}

-- Everything said here also goes to reframework/data/re7mp/debug.json, so it can simply be sent as a file.
local dbg = { lines = {}, pinned = {}, events = {}, pin = false, dirty = false, last_flush = 0 }

local function say(msg)
    local text = "[re7mp] " .. tostring(msg)
    if log and log.info then
        pcall(log.info, text)
    else
        print(text)
    end
    local line = string.format("%.1f  %s", os.clock(), tostring(msg))
    if dbg.pin and #dbg.pinned < 6000 then dbg.pinned[#dbg.pinned + 1] = line end -- survives the flood of trace lines
    -- the journal: everything except the tracer's lines, kept apart so a trace cannot push give/drop/death/menu lines out of the file
    -- ...nor the indented lines of the collectors (a method list of 400 lines pushed the whole journal out of the 0.7 file)
    if not tostring(msg):find("^%[trace%]") and not tostring(msg):find("^%s") then
        dbg.events[#dbg.events + 1] = line
        if #dbg.events > 1200 then table.remove(dbg.events, 1) end -- (9.22: 600 before)
    end
    dbg.lines[#dbg.lines + 1] = line
    if #dbg.lines > 4800 then -- (9.22: 3200 before; the file is about 140 bytes a line)
        local keep = {}
        for i = 601, #dbg.lines do keep[#keep + 1] = dbg.lines[i] end
        dbg.lines = keep
    end
    dbg.dirty = true
end

----------------------------------------------------------------------------------------------
-- 9.36: THE HITCHING. The tester's 9.35 session "kept hitching" and then closed. The debug file is the whole report (about 380 KB of data, 657 KB
-- on disk): it is built and written in ONE go on the render thread. Until 9.35 that happened (a) every 2 s whenever any journal line had been
-- written (Ethan's friend's pose loop, the item journal and the weapon lines write one every second or two) and (b) at once for every line of
-- the item "trail" (221 of them in that session). Now:
--   * the file is written at most every `play_s` seconds while playing, and every `ui_s` seconds while the REFramework menu or a game menu is open
--     (nobody feels a hitch there, and the file is fresh when you look), never because of a trail line;
--   * the gap also grows with what the last write cost: at least `cost_x` times as long (so a 100 ms write waits 10 s), so the file can never take
--     more than about 1 % of the play time however large it gets;
--   * "Save the debug file now" in the panel writes it at once.
-- Every line is still in REFramework's own log the moment it is said, and the item trail has its own small file, so a crash loses nothing that matters.
-- CFG.perf below measures the rest of the script's time per frame (the next file says which part was slow).
----------------------------------------------------------------------------------------------
CFG.dbgf = { play_s = tonumber(rawget(_G, "RE7MP_TEST_FLUSH_S")) or 30, ui_s = 2, cost_x = 100, cost_max_s = 60, n = 0, total = 0, max = 0, last = 0, interval = 0, forced = 0, last_build = 0, last_dump = 0 } -- (RE7MP_TEST_FLUSH_S: only the test harness sets it)

CFG.perf = {
    on = true, SLOW = 0.008, MAX_WORST = 12,
    marks = {},                       -- label -> { total, max, calls, slow } seconds
    frames = 0, total = 0, max = 0,
    over = { ms4 = 0, ms8 = 0, ms16 = 0, ms33 = 0, ms66 = 0 },
    worst = {},                       -- the slowest frames: { at, ms, top, top_ms }
    t = 0, t0 = 0, top = nil, top_dt = 0,
    -- 10.20: the time BETWEEN frames. The parts above time only the script, so a hitch the game makes (an autosave, a load, a streaming stall) shows in them as nothing:
    -- it is a long wait between two frames with almost no script time in it. Every frame start is compared with the one before: gap = the wall time between them,
    -- ours = what the script used in the earlier frame (its parts plus the game-phase callbacks), other = the rest (the game, the graphics driver, other programs).
    -- Gaps of 60 ms and more are listed in time order with what the game was doing (loading, a menu open, saving). The game's saving flag is looked at on every frame.
    gap = { prev = nil, last_total = 0, last_top = nil, acc = 0, frames = 0, MIN = 0.06, MAX_RECENT = 30, MAX_WORST = 12,
        over = { ms50 = 0, ms100 = 0, ms250 = 0, ms500 = 0, ms1000 = 0 }, not_ours_100 = 0, ours_100 = 0, recent = {}, worst = {},
        saving = { supported = nil, polls = 0, errors = 0, now = false, since = nil, began = 0, events = {}, sm = nil, sm_at = -100, last_error = nil } },
}

function CFG.perf.begin()
    local P = CFG.perf
    if not P.on then return end
    P.t = os.clock()
    P.t0 = P.t
    P.top, P.top_dt = nil, 0
    pcall(CFG.perf.gap_note, P.t0) -- (10.20: the recorder must never break a frame)
end

-- 10.20: is the game saving right now? (app.SaveDataManager.get_NowSaving, read on every frame; five answers that are not true / false in a row and it is given up)
function CFG.perf.poll_saving(t)
    local S = CFG.perf.gap.saving
    if S.supported == false then return end
    if S.sm == nil or t - S.sm_at > 5 then
        local okm, sm = pcall(sdk.get_managed_singleton, "app.SaveDataManager")
        S.sm, S.sm_at = (okm and sm) or nil, t
    end
    if S.sm == nil then return end
    local ok, v = pcall(function() return S.sm:call("get_NowSaving") end)
    S.polls = S.polls + 1
    if not ok or type(v) ~= "boolean" then
        S.errors = S.errors + 1
        S.last_error = ok and ("answered " .. type(v)) or tostring(v):sub(1, 80)
        S.sm = nil
        if S.supported == nil and S.errors >= 5 then S.supported = false end
        return
    end
    S.supported = true
    if v ~= S.now then
        S.now = v
        if v then S.since, S.began = t, S.began + 1 else S.ended = t end -- (10.27: S.ended = when the save finished, for saving_quiet below)
        local ev = S.events
        ev[#ev + 1] = { at = math.floor(t * 10) / 10, what = v and "saving began" or "saving ended",
            secs = (not v and S.since) and math.floor((t - S.since) * 100) / 100 or nil }
        while #ev > 30 do table.remove(ev, 1) end
    end
end

-- 10.27: is the game writing a save right now (or did it only just finish)? The autosave, the script's slot questions (isExistData) and the debug file all go to the same disk. In the
-- 10.26 file four of the twelve worst frames (626, 499, 266 and 222 ms, every one of them 0.7 to 2.7 s after "saving began") were the script's slot watch or its debug-file write landing
-- inside the game's own save of about 2.7 s. Work that can wait asks this first and tries again on a later frame; `what` names the caller so the debug file says how long each one waited
-- (saving_flag.waits). It is false when the flag is not supported (nothing ever waits then) and false after 15 s of "saving" (a stuck flag must never stop anything for good).
CFG.perf.SAVE_AFTER_S, CFG.perf.SAVE_STUCK_S = 1.5, 15
CFG.perf.waits = {}
function CFG.perf.saving_quiet(now, what)
    local P = CFG.perf
    local S = P.gap.saving
    local busy = false
    if S.supported == true then
        if S.now then
            busy = not (S.since and now - S.since > P.SAVE_STUCK_S)
        else
            busy = S.ended ~= nil and now - S.ended < P.SAVE_AFTER_S
        end
    end
    if what then
        local w = P.waits[what]
        if w == nil then w = { times = 0, total_s = 0, longest_s = 0, since = nil } P.waits[what] = w end
        if busy then
            if w.since == nil then w.since = now end
        elseif w.since ~= nil then -- it can run again: how long did it wait?
            local waited = now - w.since
            w.since, w.times, w.total_s = nil, w.times + 1, w.total_s + waited
            if waited > w.longest_s then w.longest_s = waited end
        end
    end
    return busy
end

-- 10.20: called at the start of every frame (see CFG.perf.gap above).
function CFG.perf.gap_note(t)
    local P = CFG.perf
    local G = P.gap
    local prev = G.prev
    G.prev = t
    local ours = G.last_total + G.acc
    G.acc = 0
    P.poll_saving(t)
    if not prev then return end
    local gap = t - prev
    G.frames = G.frames + 1
    if gap < 0.05 then return end
    local O = G.over
    O.ms50 = O.ms50 + 1
    if gap > 0.1 then O.ms100 = O.ms100 + 1 end
    if gap > 0.25 then O.ms250 = O.ms250 + 1 end
    if gap > 0.5 then O.ms500 = O.ms500 + 1 end
    if gap > 1 then O.ms1000 = O.ms1000 + 1 end
    local other = gap - ours
    if gap > 0.1 then
        if other > gap * 0.75 then G.not_ours_100 = G.not_ours_100 + 1 else G.ours_100 = G.ours_100 + 1 end
    end
    if gap < G.MIN then return end
    local S = G.saving
    local rec = { at = math.floor(prev * 10) / 10, gap_ms = math.floor(gap * 10000) / 10, ours_ms = math.floor(ours * 10000) / 10,
        other_ms = math.floor(other * 10000) / 10, ours_top = G.last_top, saving = S.now or nil,
        saving_began_s_ago = (S.since and t - S.since < 10) and math.floor((t - S.since) * 10) / 10 or nil,
        loading = (CFG.busy and CFG.busy.busy) or nil, menu = (CFG.menu and CFG.menu.open) or nil }
    local R = G.recent
    R[#R + 1] = rec
    while #R > G.MAX_RECENT do table.remove(R, 1) end
    local W = G.worst
    W[#W + 1] = rec
    table.sort(W, function(a, b) return a.gap_ms > b.gap_ms end)
    while #W > G.MAX_WORST do table.remove(W) end
end

function CFG.perf.gap_report()
    local G = CFG.perf.gap
    local S = G.saving
    return { about = "10.20: the wall time between frames. gap_ms = since the last frame started; ours_ms = what the script used in that earlier frame; other_ms = the rest (the game, the driver, other programs). "
            .. "A long gap with a small ours_ms is not the script. saving = the game's get_NowSaving was true when the frame after the gap started (unverified: see saving_flag).",
        frames_seen = G.frames, gaps_over = { ["50ms"] = G.over.ms50, ["100ms"] = G.over.ms100, ["250ms"] = G.over.ms250, ["500ms"] = G.over.ms500, ["1000ms"] = G.over.ms1000 },
        over_100ms_mostly_not_the_script = G.not_ours_100, over_100ms_mostly_the_script = G.ours_100,
        recent = G.recent, worst = G.worst,
        saving_flag = { supported = S.supported, polls = S.polls, errors = S.errors, last_error = S.last_error, times_began = S.began, now = S.now, events = S.events,
            -- 10.27: what was held back while the game saved (times it waited, seconds in all, the longest wait; "since" = waiting right now)
            waits = CFG.perf.waits_report() } }
end

function CFG.perf.waits_report()
    local out = { about = "10.27: slot_watch (the save-slot questions) and debug_write (this file) wait while the game is saving and for 1.5 s after; a wait of a few seconds here is the fix working" }
    for what, w in pairs(CFG.perf.waits) do
        out[what] = { times = w.times, total_s = math.floor(w.total_s * 10) / 10, longest_s = math.floor(w.longest_s * 10) / 10, waiting_now = w.since ~= nil or nil }
    end
    return out
end

-- The time since the last mark (or the start of the frame) is charged to `label`.
function CFG.perf.mark(label)
    local P = CFG.perf
    if not P.on then return end
    local t = os.clock()
    local dt = t - P.t
    P.t = t
    local m = P.marks[label]
    if not m then m = { total = 0, max = 0, calls = 0, slow = 0 } P.marks[label] = m end
    m.total, m.calls = m.total + dt, m.calls + 1
    if dt > m.max then m.max = dt end
    if dt > P.SLOW then m.slow = m.slow + 1 end
    if dt > P.top_dt then P.top, P.top_dt = label, dt end
end

-- Time spent outside the frame callback (the game-phase callbacks): added to a label of its own.
function CFG.perf.add(label, dt, nested)
    local P = CFG.perf
    if not P.on then return end
    local m = P.marks[label]
    if not m then m = { total = 0, max = 0, calls = 0, slow = 0 } P.marks[label] = m end
    m.total, m.calls = m.total + dt, m.calls + 1
    if dt > m.max then m.max = dt end
    if dt > P.SLOW then m.slow = m.slow + 1 end
    if not nested then P.gap.acc = P.gap.acc + dt end -- (10.20: the game-phase callbacks count as the script's own time between two frames; a lap inside one is already in it)
end

-- 10.20: inside a game-phase tick: the time since the last lap (or the tick's start, CFG.perf.lap_t) is charged to `label`.
function CFG.perf.lap(label)
    local P = CFG.perf
    if not P.on then return end
    local t = os.clock()
    P.add(label, t - (P.lap_t or t), true)
    P.lap_t = t
end

function CFG.perf.finish()
    local P = CFG.perf
    if not P.on then return end
    local total = os.clock() - P.t0
    P.gap.last_total, P.gap.last_top = total, P.top
    P.frames, P.total = P.frames + 1, P.total + total
    if total > P.max then P.max = total end
    local O = P.over
    if total > 0.004 then O.ms4 = O.ms4 + 1 end
    if total > 0.008 then O.ms8 = O.ms8 + 1 end
    if total > 0.016 then O.ms16 = O.ms16 + 1 end
    if total > 0.033 then O.ms33 = O.ms33 + 1 end
    if total > 0.066 then O.ms66 = O.ms66 + 1 end
    if total > 0.008 then
        local W = P.worst
        local rec = { at = math.floor(P.t0 * 10) / 10, ms = math.floor(total * 10000) / 10, top = P.top, top_ms = math.floor(P.top_dt * 10000) / 10 }
        W[#W + 1] = rec
        table.sort(W, function(a, b) return a.ms > b.ms end)
        while #W > P.MAX_WORST do table.remove(W) end
    end
end

function CFG.perf.report()
    local P, F = CFG.perf, CFG.dbgf
    local rows = {}
    for label, m in pairs(P.marks) do
        rows[#rows + 1] = { part = label, total_ms = math.floor(m.total * 1000 + 0.5), calls = m.calls, avg_ms = m.calls > 0 and math.floor(m.total / m.calls * 10000) / 10 or 0,
            max_ms = math.floor(m.max * 10000) / 10, over_8ms = m.slow }
    end
    table.sort(rows, function(a, b) return a.total_ms > b.total_ms end)
    while #rows > 48 do table.remove(rows) end -- (10.20: 24 before; the parts are finer now)
    return {
        about = "how long the script's own work took on the render thread: per part (totals over the session), the slowest frames, and what writing this very file cost",
        frame_gaps = CFG.perf.gap_report(), -- 10.20: the time between frames (is a hitch the script's or the game's?)
        on = P.on, frames = P.frames, avg_ms = P.frames > 0 and math.floor(P.total / P.frames * 10000) / 10 or 0, max_ms = math.floor(P.max * 10000) / 10,
        frames_over = { ["4ms"] = P.over.ms4, ["8ms"] = P.over.ms8, ["16ms"] = P.over.ms16, ["33ms"] = P.over.ms33, ["66ms"] = P.over.ms66 },
        slowest_frames = P.worst, parts = rows,
        debug_file = { writes = F.n, forced_by_button = F.forced, avg_ms = F.n > 0 and math.floor(F.total / F.n * 10000) / 10 or 0, last_ms = math.floor(F.last * 10000) / 10,
            max_ms = math.floor(F.max * 10000) / 10, last_build_ms = math.floor(F.last_build * 10000) / 10, last_write_ms = math.floor(F.last_dump * 10000) / 10,
            gap_now_s = math.floor(F.interval * 10) / 10, play_s = F.play_s, menu_s = F.ui_s, gap_per_ms_of_cost = F.cost_x },
    }
end

local function flush_debug(now, force)
    local F = CFG.dbgf
    if not (dbg.dirty or force) then return end
    if not force then
        local ui = state.ui_at ~= nil and now - state.ui_at < 1.5            -- the REFramework menu is open
        local menu = CFG.menu ~= nil and CFG.menu.open == true                -- a game menu is open
        local need = math.max((ui or menu) and F.ui_s or F.play_s, math.min(F.cost_max_s, F.cost_x * F.last))
        F.interval = need
        if now - dbg.last_flush < need then return end
        -- (10.27) not while the game writes a save (a write of this file took 266 ms inside one in the 10.26 file): the file stays dirty, so it is written a moment after the save.
        -- The button's write (force) is the owner asking, so it goes ahead.
        if CFG.perf.saving_quiet(now, "debug_write") then return end
    else
        F.forced = F.forced + 1
    end
    dbg.dirty = false
    local t0 = os.clock()
    local extra
    if dbg.extra then
        local okx, v = pcall(dbg.extra)
        if okx then extra = v end
    end
    local t1 = os.clock()
    pcall(json.dump_file, FILES.path("debug"), { script = "re7mp v" .. CFG.BUILD, release = CFG.RELEASE, build = CFG.BUILD, alpha = tonumber(CFG.ALPHA) or 0, -- (10.26) which alpha of the release this is (0 = a normal release)
        channel = CFG.chan and CFG.chan.value, exe_build = CFG.chan and CFG.chan.exe_build, -- (10.24) "alpha" / "stable" and re7mp.exe's own build, nil when the exe has not said
        exe = state.exe_version, exe_protocol = state.exe_proto, other_player_version = CFG.ver.summary,
        data_folder = { used = FILES.folder_ok, note = FILES.folder_note }, -- (9.30: false = the game refused the re7mp folder; the old flat file names are used)
        health = extra, events = dbg.events, pinned = dbg.pinned, lines = dbg.lines })
    local t2 = os.clock()
    F.n, F.total, F.last, F.last_build, F.last_dump = F.n + 1, F.total + (t2 - t0), t2 - t0, t1 - t0, t2 - t1
    if F.last > F.max then F.max = F.last end
    dbg.last_flush = t2
end

-- Hide the other player for a while (opening cutscene after a new game), or show them again with 0.
local function hide_remote(seconds, why)
    state.hidden_until = os.clock() + seconds
    if seconds > 0 then say("other player hidden for " .. tostring(seconds) .. " s (" .. tostring(why) .. ")") end
end

----------------------------------------------------------------------------------------------
-- RE7 adapter: the game-specific code. Filled in from the probe of app.GameManager:
--   get_gameDifficulty / set_gameDifficulty   read and set the difficulty
--   newGameRequest                            runs when a new game is requested (our trigger)
--   newGameInitParam, newGameRequest_Chapter7, setGamemode, SaveDataManager.newGameInit
--                                             only logged ("trace") for now; their arguments are unknown
-- Difficulty ids on the wire: 0 = Easy, 1 = Normal, 2 = Madhouse. The game's enum values are
-- read from the game at runtime (see build_difficulty_map) instead of being assumed.
----------------------------------------------------------------------------------------------
local RE7 = {
    captured_gm = nil,       -- app.GameManager instance seen by a hook (fallback if the singleton lookup fails)
    trace_on = true,
    trace_lines = {},
    replaying = false,       -- true while WE call newGameRequest, so our hook lets it through
    can_block = false,       -- can a pre-hook skip the original call? (set below)
    last_set_wire = nil,     -- last difficulty the game was set to, as 0/1/2
    mode_map_built = false,
    mode_names = {},         -- GameMode value -> member name
    death_value = nil,       -- the GameMode member that looks like game over / death, if any
    death_name = nil,
    replaying_mode = false,  -- true while WE call setGamemode, so our hook ignores it
    on_gamemode = nil,       -- set by the death sync below: function(value)
    map_built = false,
    to_game = {},            -- wire id -> the game's difficulty value
    from_game = {},          -- the game's difficulty value -> wire id
}

local function trace(text)
    if not RE7.trace_on then return end
    RE7.trace_lines[#RE7.trace_lines + 1] = string.format("%.1f  %s", os.clock(), text)
    if #RE7.trace_lines > 60 then table.remove(RE7.trace_lines, 1) end
    say("[trace] " .. text)
end

local function game_manager()
    local ok, gm = pcall(sdk.get_managed_singleton, "app.GameManager")
    if ok and gm then return gm end
    return RE7.captured_gm
end

-- Finds the game's difficulty enum (the return type of get_gameDifficulty) and maps its member
-- names (Easy/Assist..., Normal..., Madhouse...) onto 0/1/2. Falls back to 0/1/2 as-is.
-- The mapping it found is written to the console so it can be checked.
local function build_difficulty_map()
    if RE7.map_built then return end
    RE7.map_built = true
    for i = 0, 2 do
        RE7.to_game[i] = i
        RE7.from_game[i] = i
    end
    local ok, err = pcall(function()
        local td = sdk.find_type_definition("app.GameManager")
        local m = td and td:get_method("get_gameDifficulty")
        local rt = (m and m:get_return_type()) or sdk.find_type_definition("app.GameManager.Difficulty")
        if not rt then return end
        say("difficulty type: " .. tostring(rt:get_full_name()))
        local found = {}
        for _, f in ipairs(rt:get_fields()) do
            if f:is_static() then
                local value = f:get_data(nil)
                if type(value) == "number" then
                    local low = f:get_name():lower()
                    local wire
                    if low:find("assist") or low:find("easy") or low:find("casual") then wire = 0
                    elseif low:find("normal") or low:find("standard") then wire = 1
                    elseif low:find("mad") or low:find("hard") then wire = 2 end
                    say("  " .. f:get_name() .. " = " .. tostring(value)
                        .. (wire and (" -> " .. DIFFICULTY[wire]) or " (not mapped)"))
                    if wire ~= nil then found[wire] = value end
                end
            end
        end
        for wire, value in pairs(found) do
            RE7.to_game[wire] = value
            RE7.from_game[value] = wire
        end
    end)
    if not ok then say("could not read the difficulty enum, assuming 0/1/2: " .. tostring(err)) end
end

-- The difficulty currently selected in the game as 0/1/2, or nil if it can't be read.
function RE7.current_difficulty()
    build_difficulty_map()
    local gm = game_manager()
    if not gm then return nil end
    local ok, v = pcall(function() return gm:call("get_gameDifficulty") end)
    if ok and type(v) == "number" then
        local wire = RE7.from_game[v]
        if wire ~= nil then return wire end
        if v >= 0 and v <= 2 then return v end
    end
    return nil
end

local function wire_from_game(v)
    if type(v) ~= "number" then return nil end
    local wire = RE7.from_game[v]
    if wire ~= nil then return wire end
    if v >= 0 and v <= 2 then return v end
    return nil
end

local function log_enum(type_name)
    pcall(function()
        local td = sdk.find_type_definition(type_name)
        if not td then
            say(type_name .. ": type not found")
            return
        end
        local parts = {}
        for _, f in ipairs(td:get_fields()) do
            if f:is_static() then
                local value = f:get_data(nil)
                if type(value) == "number" then parts[#parts + 1] = f:get_name() .. "=" .. tostring(value) end
            end
        end
        say(type_name .. ": " .. table.concat(parts, ", "))
    end)
end

do
    local okp, skip_const = pcall(function() return sdk.PreHookResult.SKIP_ORIGINAL end)
    RE7.can_block = okp and skip_const ~= nil
end

-- Reads the GameMode enum so values can be shown by name, and finds the member that means game over / death
-- (a name containing gameover, game_over, dead or death). Logged to the console and the debug file.
local function build_mode_map()
    if RE7.mode_map_built then return end
    RE7.mode_map_built = true
    local ok, err = pcall(function()
        local td = sdk.find_type_definition("app.GameManager.GameMode")
        if not td then
            say("GameMode enum not found")
            return
        end
        local parts = {}
        for _, f in ipairs(td:get_fields()) do
            if f:is_static() then
                local v = f:get_data(nil)
                if type(v) == "number" then
                    local name = f:get_name()
                    RE7.mode_names[v] = name
                    parts[#parts + 1] = name .. "=" .. tostring(v)
                    local low = name:lower()
                    if RE7.death_value == nil and (low:find("gameover", 1, true) or low:find("game_over", 1, true)
                        or low:find("dead", 1, true) or low:find("death", 1, true)) then
                        RE7.death_value, RE7.death_name = v, name
                    end
                end
            end
        end
        say("GameMode values: " .. table.concat(parts, ", "))
        if RE7.death_value ~= nil then
            say("death detection uses GameMode." .. RE7.death_name .. " = " .. tostring(RE7.death_value))
        else
            say("death detection: no game-over-like member in GameMode, so deaths can't be detected yet")
        end
    end)
    if not ok then say("could not read the GameMode enum: " .. tostring(err)) end
end

-- Puts the local game into its game-over mode, as if the player had died. Returns true, or false plus a message.
function RE7.kill_local_player()
    build_mode_map()
    if RE7.death_value == nil then return false, "no game-over-like value in the GameMode enum" end
    local gm = game_manager()
    if not gm then return false, "app.GameManager not found" end
    RE7.replaying_mode = true
    local ok, err = pcall(function() gm:call("setGamemode", RE7.death_value) end)
    RE7.replaying_mode = false
    if not ok then return false, tostring(err) end
    return true
end

-- Sets the game's difficulty. Returns true, or false plus a message.
function RE7.apply_difficulty(difficulty_id)
    build_difficulty_map()
    local gm = game_manager()
    if not gm then return false, "app.GameManager not found" end
    local value = RE7.to_game[difficulty_id] or difficulty_id
    local ok, err = pcall(function() gm:call("set_gameDifficulty", value) end)
    if not ok then return false, tostring(err) end
    return true
end

-- Starts a new game on the given difficulty: sets the difficulty, then calls newGameRequest() (it takes no
-- arguments, per the signature probe). Returns true, or false plus a message.
function RE7.start_new_game(difficulty_id)
    local ok, err = RE7.apply_difficulty(difficulty_id)
    if not ok then return false, err end
    local gm = game_manager()
    if not gm then return false, "app.GameManager not found" end
    RE7.replaying = true -- our own hook must let this call through
    local okc, errc = pcall(function() gm:call("newGameRequest") end)
    RE7.replaying = false
    if not okc then return false, tostring(errc) end
    return true
end

-- Hooks the new-game request. on_new_game(difficulty_id) is called when the player starts a new game; if it
-- returns true the original request is SKIPPED (blocked) and is replayed later by RE7.start_new_game.
-- The other new-game methods are only logged (Start together > "Log new-game calls").
function RE7.install_new_game_hook(on_new_game)
    build_difficulty_map()
    log_enum("app.GameManager.Difficulty")
    log_enum("app.GameManager.GameMode")
    local pre_result = sdk.PreHookResult
    local CALL_ORIGINAL = pre_result and pre_result.CALL_ORIGINAL
    local SKIP_ORIGINAL = pre_result and pre_result.SKIP_ORIGINAL
    local installed = 0

    -- handler(args) may return true to skip the original call (only honoured if the game supports it).
    local function hook(type_name, method_name, handler)
        local td = sdk.find_type_definition(type_name)
        local m = td and td:get_method(method_name)
        if not m then
            say("hook: " .. type_name .. "." .. method_name .. " not found")
            return
        end
        sdk.hook(m, function(args)
            local ok, skip = pcall(handler, args)
            if not ok then
                say("hook error in " .. method_name .. ": " .. tostring(skip))
                return CALL_ORIGINAL
            end
            if skip == true and SKIP_ORIGINAL ~= nil then return SKIP_ORIGINAL end
            return CALL_ORIGINAL
        end, function(retval) return retval end)
        installed = installed + 1
    end

    local function remember_this(args)
        local ok, obj = pcall(sdk.to_managed_object, args[2])
        if ok and obj then RE7.captured_gm = obj end
    end
    local function raw(args, i)
        local ok, v = pcall(sdk.to_int64, args[i])
        return ok and string.format("0x%x", v or 0) or "?"
    end
    local function raw_bool(args, i)
        local ok, v = pcall(sdk.to_int64, args[i])
        return ok and tostring((v or 0) % 256) or "?"
    end

    hook("app.GameManager", "set_gameDifficulty", function(args)
        remember_this(args)
        local ok, v = pcall(sdk.to_int64, args[3])
        if ok and v then RE7.last_set_wire = wire_from_game(v % 4294967296) end
        trace("set_gameDifficulty(" .. raw(args, 3) .. ")")
    end)
    hook("app.GameManager", "newGameRequest", function(args)
        remember_this(args)
        if RE7.replaying then
            trace("newGameRequest() [replayed by us]")
            return false
        end
        trace("newGameRequest()")
        return on_new_game(RE7.current_difficulty() or RE7.last_set_wire) == true
    end)
    hook("app.GameManager", "newGameRequest_Chapter7", function(args)
        trace("newGameRequest_Chapter7()")
    end)
    hook("app.GameManager", "newGameInitParam", function(args)
        trace("newGameInitParam(" .. raw_bool(args, 3) .. ")")
    end)
    hook("app.GameManager", "setGamemode", function(args)
        build_mode_map()
        local ok, v = pcall(sdk.to_int64, args[3])
        local value = ok and v and (v % 4294967296) or nil
        trace("setGamemode(" .. (value and (RE7.mode_names[value] or tostring(value)) or "?") .. ")")
        if value and not RE7.replaying_mode and RE7.on_gamemode then RE7.on_gamemode(value) end
    end)
    hook("app.SaveDataManager", "newGameInit", function(args)
        trace("SaveDataManager.newGameInit()")
    end)
    return installed > 0
end

----------------------------------------------------------------------------------------------
-- Small helpers
----------------------------------------------------------------------------------------------
local function has(flags, bit) -- is this power-of-two bit set?
    return math.floor(flags / bit) % 2 == 1
end

local function flags_diff(flags)
    return math.floor(flags / 2) % 4
end

local function normalize3(x, y, z)
    local l = math.sqrt(x * x + y * y + z * z)
    if l < 1e-6 then return 0, 0, 1 end
    return x / l, y / l, z / l
end

-- Rotates vector v = {x, y, z} by unit quaternion q = {x, y, z, w}.
local function rotate(q, v)
    local qx, qy, qz, qw = q.x, q.y, q.z, q.w
    local tx = 2 * (qy * v[3] - qz * v[2])
    local ty = 2 * (qz * v[1] - qx * v[3])
    local tz = 2 * (qx * v[2] - qy * v[1])
    return {
        v[1] + qw * tx + (qy * tz - qz * ty),
        v[2] + qw * ty + (qz * tx - qx * tz),
        v[3] + qw * tz + (qx * ty - qy * tx),
    }
end

local function forward_of(q)
    local l = math.sqrt(q.x * q.x + q.y * q.y + q.z * q.z + q.w * q.w)
    local u = { x = 0, y = 0, z = 0, w = 1 }
    if l > 1e-6 then u = { x = q.x / l, y = q.y / l, z = q.z / l, w = q.w / l } end
    local f = rotate(u, CFG.FORWARD)
    return normalize3(f[1], f[2], f[3])
end

-- The other player's flags, or 0 if we haven't heard from them lately.
local function remote_flags_now(now)
    if now - state.remote_changed_at > CFG.STALE_AFTER then return 0 end
    local f = state.remote_flags or 0
    local FB = CFG.friend and CFG.friend.body
    if FB and FB.own_on() then -- (10.7) Ethan's friend acts for itself: your pose bits are not its own
        local ok, v = pcall(FB.own_flags, f, now)
        if ok and type(v) == "number" then return v end
    end
    return f
end

----------------------------------------------------------------------------------------------
-- Holding the game while we wait (global game speed, same mechanism as REFramework's timescale)
----------------------------------------------------------------------------------------------
local function hold_game()
    if held.active then return end
    local ok, err = pcall(function()
        local app = sdk.get_native_singleton("via.Application")
        local td = sdk.find_type_definition("via.Application")
        local cur = sdk.call_native_func(app, td, "get_GlobalSpeed")
        held.prev_speed = (type(cur) == "number" and cur > 0.05) and cur or 1.0
        sdk.call_native_func(app, td, "set_GlobalSpeed", CFG.HOLD_SPEED)
    end)
    if ok then
        held.active = true
    else
        lobby.hold_kind = nil
        say("could not freeze the game: " .. tostring(err))
    end
end

local function release_game()
    if not held.active then return end
    held.active = false
    local ok, err = pcall(function()
        local app = sdk.get_native_singleton("via.Application")
        local td = sdk.find_type_definition("via.Application")
        sdk.call_native_func(app, td, "set_GlobalSpeed", held.prev_speed)
    end)
    if not ok then say("could not unfreeze the game: " .. tostring(err)) end
end

----------------------------------------------------------------------------------------------
-- Ready check ("Start together")
----------------------------------------------------------------------------------------------
local function set_message(text, seconds)
    lobby.message = text
    lobby.message_until = os.clock() + (seconds or 8)
    say(text)
end

-- from_hook = true when the game itself asked for a new game (so we may block or freeze it).
local function start_ready(difficulty, from_hook)
    if lobby.phase ~= "idle" then return end
    local now = os.clock()
    lobby.phase = "waiting"
    lobby.difficulty = difficulty
    lobby.started_at = now
    lobby.mismatch_diff = nil
    lobby.hold_kind = nil
    if from_hook then
        if lobby.freeze_instead or not RE7.can_block then
            lobby.hold_kind = "freeze"
            hold_game() -- clears hold_kind again if the freeze fails
        else
            lobby.hold_kind = "block"
        end
    end
    set_message("Ready on " .. (DIFFICULTY[difficulty] or "?") .. ". Waiting for the other player...", 60)
end

local function cancel_ready(text)
    local was_blocking = lobby.hold_kind == "block"
    release_game()
    lobby.hold_kind = nil
    lobby.phase = "idle"
    lobby.latch_until = 0
    lobby.mismatch_diff = nil
    lobby.need_clear = true
    set_message(text or (was_blocking and "Cancelled. Press New Game again when you're ready." or "Cancelled."), 6)
end

-- Called by the RE7 adapter's hook when the game receives a new-game request. Returns true to make
-- the hook BLOCK that request until both players are ready.
local function on_local_new_game(difficulty_id)
    local now = os.clock()
    if state.auto_hide then hide_remote(CFG.HIDE_AFTER_NEW_GAME, "new game pressed") end
    if now < lobby.suppress_until then return false end -- we started it ourselves
    if lobby.phase == "idle" and now - state.remote_changed_at > CFG.STALE_AFTER then
        say("New game started with nobody connected: not waiting for anyone.")
        return false
    end
    start_ready(difficulty_id or lobby.difficulty, true)
    -- Already waiting from the panel's "I'm ready" and the game now asks for a new game: block it too.
    if lobby.phase == "waiting" and lobby.hold_kind == nil and RE7.can_block and not lobby.freeze_instead then
        lobby.hold_kind = "block"
    end
    return lobby.hold_kind == "block"
end

-- The flags we send with every position packet.
local function local_flags(now)
    local f = 0
    local active = lobby.phase == "waiting" or lobby.phase == "go"
        or (lobby.phase == "done" and now < lobby.latch_until)
    if active then f = f + FLAG_READY + lobby.difficulty * 2 end
    if has(remote_flags_now(now), FLAG_READY) then f = f + FLAG_SEES end
    if lobby.phase == "go" or (lobby.phase == "done" and now < lobby.latch_until) then f = f + FLAG_GO end
    -- what my body is doing (block / heal) rides along in the same field
    local lp = state.local_pose
    lp.guard, lp.heal, lp.crouch, lp.gun, lp.aim, lp.shoot = false, false, false, false, false, false
    -- in the inventory or the item box: the stand-in on the other side looks down at its hands
    lp.menu = CFG.menu and CFG.menu.in_inventory() or false
    if lp.menu then f = f + CFG.POSE_MENU end
    if state.pose_source then
        local okp, g, h, c, gn, am, sh = pcall(state.pose_source, now)
        if okp then
            lp.guard, lp.heal, lp.crouch = g == true, h == true, c == true
            lp.gun, lp.aim, lp.shoot = gn == true, am == true, sh == true
            if lp.guard then f = f + CFG.POSE_GUARD end
            if lp.heal then f = f + CFG.POSE_HEAL end
            if lp.crouch then f = f + CFG.POSE_CROUCH end
            if lp.gun then f = f + CFG.POSE_GUN end
            if lp.aim then f = f + CFG.POSE_AIM end
            if lp.shoot then f = f + CFG.POSE_SHOOT end
        end
    end
    -- (10.12) running (not crouched): my own speed against the middle of the walk and run speeds, with a lower bar to stay running than to start
    local okr, run = pcall(CFG.run.mine, now, lp.crouch == true)
    lp.run = okr and run == true
    if lp.run then f = f + CFG.POSE_RUN end
    return f
end

local function update_lobby(now)
    local rf = remote_flags_now(now)
    local who = state.remote_name or CFG.DEFAULT_NAME
    local diff_name = DIFFICULTY[lobby.difficulty] or "?"

    if lobby.phase == "idle" then
        -- Don't react to a ready state left over from a game that just started or that we cancelled.
        if lobby.need_clear then
            if not has(rf, FLAG_READY) then lobby.need_clear = false end
            lobby.join_diff = nil
            return
        end
        if has(rf, FLAG_READY) then
            lobby.join_diff = flags_diff(rf)
            if lobby.auto_join then
                start_ready(lobby.join_diff, false)
            else
                lobby.message = string.format("%s is ready to start a new game on %s. Press New Game, or click Join in the Insert menu.",
                    who, DIFFICULTY[lobby.join_diff] or "?")
                lobby.message_until = now + 1
            end
        else
            lobby.join_diff = nil
        end

    elseif lobby.phase == "waiting" then
        if now - lobby.started_at > CFG.READY_TIMEOUT then
            cancel_ready("Timed out waiting for " .. who .. ".")
            return
        end
        if has(rf, FLAG_READY) then
            local theirs = flags_diff(rf)
            if theirs ~= lobby.difficulty then
                lobby.mismatch_diff = theirs
                lobby.message = string.format("%s picked %s but you picked %s. They must match.",
                    who, DIFFICULTY[theirs] or "?", diff_name)
            else
                lobby.mismatch_diff = nil
                if has(rf, FLAG_SEES) or has(rf, FLAG_GO) then
                    lobby.phase = "go"
                    lobby.go_at = now
                    lobby.latch_until = now + CFG.GO_LATCH
                else
                    lobby.message = "Both ready, confirming with " .. who .. "..."
                end
            end
        else
            lobby.mismatch_diff = nil
            lobby.message = "Ready on " .. diff_name .. ". Waiting for " .. who .. "..."
        end

    elseif lobby.phase == "go" then
        -- Everyone counts down together so the starts line up, whatever started the ready check.
        local left = CFG.COUNTDOWN - (now - lobby.go_at)
        if left > 0 then
            lobby.message = string.format("Both ready! Starting in %d...", math.ceil(left))
        else
            local kind = lobby.hold_kind
            lobby.hold_kind = nil
            lobby.phase = "done"
            lobby.need_clear = true
            lobby.suppress_until = now + 20 -- don't treat our own start as a new request
            if state.auto_hide then hide_remote(CFG.HIDE_AFTER_NEW_GAME, "new game starting") end

            if kind == "freeze" then
                release_game() -- the game's own request was never blocked: just let it carry on
                set_message("Both ready: continuing on " .. diff_name .. ".", 6)

            elseif kind == "block" then
                -- Replay the New Game request we blocked, on the agreed difficulty.
                local ok, res, err = pcall(RE7.start_new_game, lobby.difficulty)
                if ok and res == true then
                    set_message("Both ready: starting the new game on " .. diff_name .. ".", 8)
                else
                    set_message("Both ready on " .. diff_name .. ", but the new game could not be started ("
                        .. tostring(ok and err or res) .. "). Press New Game again.", 12)
                end

            elseif lobby.auto_start then -- started from the panel
                local ok, res, err = pcall(RE7.start_new_game, lobby.difficulty)
                if ok and res == true then
                    set_message("New game requested on " .. diff_name .. ". If nothing happens, press New Game.", 10)
                else
                    set_message("GO! Press New Game now (" .. diff_name .. "). " .. tostring(ok and err or res), 10)
                end

            else
                pcall(RE7.apply_difficulty, lobby.difficulty)
                set_message("GO! Difficulty set to " .. diff_name .. ". Press New Game now.", 10)
            end
        end

    elseif lobby.phase == "done" then
        if now >= lobby.latch_until then
            lobby.phase = "idle"
            lobby.need_clear = true
        end
    end
end

----------------------------------------------------------------------------------------------
-- Local player -> engine
----------------------------------------------------------------------------------------------
-- The camera is the player's eyes in first-person RE7, so it stands in for the player.
local function get_local_pose()
    local cam = sdk.get_primary_camera()
    if not cam then return nil end
    local go = cam:call("get_GameObject")
    if not go then return nil end
    local xf = go:call("get_Transform")
    if not xf then return nil end
    local p = xf:call("get_Position")
    if not p then return nil end
    local q = xf:call("get_Rotation")
    local quat = { x = 0, y = 0, z = 0, w = 1 }
    if q then quat = { x = q.x, y = q.y, z = q.z, w = q.w } end
    return { x = p.x, y = p.y, z = p.z }, quat
end

local function send_local(now)
    state.last_send = now
    local ok, pos, quat = pcall(get_local_pose)
    if not ok then
        state.last_error = tostring(pos)
        pos = nil
    end
    local flags = local_flags(now)
    if pos then
        state.local_pos = pos
        state.local_quat = quat
        local FB = CFG.friend and CFG.friend.body
        if FB then pcall(FB.note_player, pos, state.local_pose and state.local_pose.crouch) end -- (10.7) the places you walked (the friend's ground)
    else
        -- No camera yet (menus, loading): still send the ready-check flags, but mark the pose invalid.
        flags = flags + FLAG_NOPOSE
        pos = state.local_pos or { x = 0, y = 0, z = 0 }
        quat = { x = 0, y = 0, z = 0, w = 1 }
    end
    CFG.perf.mark("net: pose gather") -- (10.27: the camera, the pose flags (health / gun / run reads) and the friend's ground notes, apart from the file write below)
    state.seq = state.seq + 1
    json.dump_file(FILES.OUT_FILE, {
        seq = state.seq,
        x = pos.x, y = pos.y, z = pos.z,
        qx = quat.x, qy = quat.y, qz = quat.z, qw = quat.w,
        flags = flags,
    })
end

----------------------------------------------------------------------------------------------
-- Engine -> remote player state
----------------------------------------------------------------------------------------------
-- (9.33) A bridge file that comes back empty or unreadable (the leftover of an exe that was killed in the middle of a write, or no exe at
-- all) used to be read again every 30 ms, and REFramework writes a line to its log for every failed read: 7,300 of them in 4 minutes
-- of one test. After a failed read the next one waits 0.1 s, then 0.25, 0.5, 1 and 2 s; one good read starts the pace over.
CFG.bridge = { slots = {}, STEPS = { 0.1, 0.25, 0.5, 1, 2 },
    -- (10.15) The message inbox (re7mp_msg_in.json) is a file read on the render thread, and nearly every read finds nothing new. In the 10.13 session the script's "net send/read" was its
    -- biggest part (0.7 ms a frame on average, 1263 frames over 8 ms) and the reads are most of it: 33 a second for the pose file and 33 for this one. While the inbox is quiet it is read
    -- about ten times a second; for ACTIVE_S seconds after a message arrives it is read as often as before. (RE7MP_TEST_QUIET_S: only the test harness sets it.)
    --
    -- (10.20) In the 10.15 files the HOST's inbox was in active mode 98.5 % of the time (145,309 reads in 5,480 s, 2,237 left out): messages come all the time there, and "active" read
    -- it on every pose read (about 28 a second), a file of up to 32 messages each time. The most the inbox can wait now is ACTIVE_GAP_S (0.07 s) in active mode, for ACTIVE_S = 1 s after
    -- a message. (RE7MP_TEST_ACTIVE_GAP and RE7MP_TEST_ACTIVE_S: only the test harness sets them; the older checks keep the old 0 s and 2 s.)
    msg = { QUIET_S = tonumber(rawget(_G, "RE7MP_TEST_QUIET_S")) or 0.1, ACTIVE_S = tonumber(rawget(_G, "RE7MP_TEST_ACTIVE_S")) or 1,
        ACTIVE_GAP_S = tonumber(rawget(_G, "RE7MP_TEST_ACTIVE_GAP")) or 0.07, heard_at = -100, next_at = 0, reads = 0, throttled = 0 } }

function CFG.bridge.read(slot, path, now)
    local s = CFG.bridge.slots[slot]
    if s == nil then
        s = { fails = 0, wait_until = 0, skipped = 0, total_fails = 0, longest = 0 }
        CFG.bridge.slots[slot] = s
    end
    if now < s.wait_until then
        s.skipped = s.skipped + 1
        return nil
    end
    local d = json.load_file(path)
    if type(d) == "table" then
        s.fails = 0
        s.wait_until = 0
        return d
    end
    s.fails = s.fails + 1
    s.total_fails = s.total_fails + 1
    if s.fails > s.longest then s.longest = s.fails end
    s.wait_until = now + CFG.bridge.STEPS[math.min(s.fails, #CFG.bridge.STEPS)]
    return nil
end

function CFG.bridge.report()
    local out = {}
    for slot, s in pairs(CFG.bridge.slots) do
        out[slot] = { failed_reads = s.total_fails, reads_skipped_while_waiting = s.skipped, longest_run_of_failures = s.longest }
    end
    local m = CFG.bridge.msg
    out.message_inbox_poll = { about = "10.15: the message inbox is read every quiet_s seconds while nothing arrives, and as often as the pose file for active_s seconds after a message",
        quiet_s = m.QUIET_S, active_s = m.ACTIVE_S, active_gap_s = m.ACTIVE_GAP_S, reads = m.reads, reads_left_out = m.throttled }
    return out
end

local function read_remote(now)
    state.last_read = now
    local data = CFG.bridge.read("exe_state_file", FILES.IN_FILE, now)
    if type(data) ~= "table" or data.seq == nil or data.x == nil then return end
    if type(data.name) == "string" and data.name ~= "" then state.remote_name = data.name end
    state.remote_count = data.recv_count or state.remote_count
    state.remote_flags = tonumber(data.flags) or 0
    if type(data.transport) == "string" then state.transport = data.transport end
    if type(data.role) == "string" then state.role = data.role end
    -- re7mp.exe's release number. The file is only written while packets arrive, so the one found when the script loads may be
    -- the leftover of an exe that is not running (or is an older release): it counts once it has been seen to CHANGE.
    if state.exe_file_seq == nil then
        state.exe_file_seq = data.seq
    elseif data.seq ~= state.exe_file_seq or state.exe_version then
        if type(data.exe) == "string" then state.exe_version = data.exe end
        if tonumber(data.proto) then state.exe_proto = tonumber(data.proto) end
    end
    if data.seq == state.remote_seq then return end
    state.remote_seq = data.seq
    state.remote_changed_at = now
    if has(state.remote_flags, FLAG_NOPOSE) then return end -- they have no camera yet

    local target = { x = data.x, y = data.y, z = data.z }
    local quat = { x = data.qx or 0, y = data.qy or 0, z = data.qz or 0, w = data.qw or 1 }
    local FB = CFG.friend and CFG.friend.body
    if FB and FB.own_on() then pcall(FB.adjust, target, now) end -- (10.7) the friend's height from your trail, the way it last moved
    if CFG.carsync then pcall(CFG.carsync.ride_offset, target, now) end -- (10.19) in the garage car the other player is drawn at the second seat

    if state.prev_target then
        local dt = now - state.prev_target_time
        local dx, dz = target.x - state.prev_target.x, target.z - state.prev_target.z
        local dist = math.sqrt(dx * dx + dz * dz)
        if dist > CFG.TELEPORT_DISTANCE then
            state.render_pos = nil -- snap instead of gliding across the map
            state.speed = 0
        elseif dt > 0.001 then
            state.speed = state.speed + (dist / dt - state.speed) * 0.3
        end
    end
    state.prev_target = target
    state.prev_target_time = now
    state.remote = { pos = target, quat = quat }
end

-- Smooths the 25 Hz network updates into per-frame motion and advances the walk cycle.
local function update_remote(now, dt)
    local r = state.remote
    if not r then return end
    local fx, fy, fz = forward_of(r.quat)
    local FB = CFG.friend and CFG.friend.body
    if FB and FB.own_on() then -- (10.7) Ethan's friend faces the way it last moved (an enemy at a block), not the way your camera points
        local okf, hx, hz = pcall(FB.facing, r.pos)
        if okf and hx then fx, fy, fz = hx, 0, hz end
    end
    if CFG.face_me and state.local_pos and r.pos then -- 9.28: look at me (sideways only; a body does not tip over to look up)
        local dx, dz = state.local_pos.x - r.pos.x, state.local_pos.z - r.pos.z
        local len = math.sqrt(dx * dx + dz * dz)
        if len > 0.05 then fx, fy, fz = dx / len, 0, dz / len end
    end
    if not state.render_pos then
        state.render_pos = { x = r.pos.x, y = r.pos.y, z = r.pos.z }
        state.render_fwd = { fx, fy, fz }
    else
        local a = 1 - math.exp(-CFG.SMOOTHING * dt)
        local p = state.render_pos
        p.x = p.x + (r.pos.x - p.x) * a
        p.y = p.y + (r.pos.y - p.y) * a
        p.z = p.z + (r.pos.z - p.z) * a
        local f = state.render_fwd
        local nx, ny, nz = normalize3(f[1] + (fx - f[1]) * a, f[2] + (fy - f[2]) * a, f[3] + (fz - f[3]) * a)
        state.render_fwd = { nx, ny, nz }
    end
    if now - state.remote_changed_at > 0.3 then
        state.speed = state.speed * math.exp(-5 * dt) -- no fresh data: wind the walk down
    end
    state.walk_phase = state.walk_phase + state.speed * dt * 4.2 -- ~1.5 m per full gait cycle

    -- Poses: what their flags say (or the panel's preview), eased in and out so the body does not snap.
    local P = state.pose
    local rf = remote_flags_now(now)
    -- "Bob used a Remedy" also lifts the heal pose for 2.4 s: the hands animation is not a reliable sign of a heal
    -- (hands 16 / 17 play when the inventory is looked at too), the item use itself is
    local tg, th, tc = has(rf, CFG.POSE_GUARD) and 1 or 0, (has(rf, CFG.POSE_HEAL) or now < (state.remote_heal_until or 0)) and 1 or 0,
        has(rf, CFG.POSE_CROUCH) and 1 or 0
    local tm = has(rf, CFG.POSE_MENU) and 1 or 0
    local tgn, tam, tsh = has(rf, CFG.POSE_GUN) and 1 or 0, has(rf, CFG.POSE_AIM) and 1 or 0, has(rf, CFG.POSE_SHOOT) and 1 or 0
    local pv = state.pose_preview
    if pv == 2 then
        tg, th, tc, tm = 1, 0, 0, 0
    elseif pv == 3 then
        tg, th, tc, tm = 0, 1, 0, 0
    elseif pv == 5 then
        tg, th, tc, tm = 0, 0, 1, 0
    elseif pv == 6 then
        tg, th, tc, tm = 0, 0, 0, 1
    elseif pv == 7 then -- (9.28) gun out
        tg, th, tc, tm, tgn, tam, tsh = 0, 0, 0, 0, 1, 0, 0
    elseif pv == 8 then -- aiming
        tg, th, tc, tm, tgn, tam, tsh = 0, 0, 0, 0, 1, 1, 0
    elseif pv == 9 then -- firing
        tg, th, tc, tm, tgn, tam, tsh = 0, 0, 0, 0, 1, 1, 1
    elseif pv == 4 then -- cycle: block 2.5 s, heal 2.5 s, crouch 2.5 s, stand 1.5 s
        local c = now % 9.0
        tg, th, tc = (c < 2.5) and 1 or 0, (c >= 2.5 and c < 5) and 1 or 0, (c >= 5 and c < 7.5) and 1 or 0
    end
    local pa = 1 - math.exp(-CFG.POSE_BLEND * dt)
    P.guard = P.guard + (tg - P.guard) * pa
    P.heal = P.heal + (th - P.heal) * pa
    local pac = pa
    local FBc = CFG.friend and CFG.friend.body
    if FBc and FBc.own_on() then pac = 1 - math.exp(-CFG.friend.CROUCH_BLEND * dt) end -- (10.9) "it takes a second": the friend gets down at once
    P.crouch = (P.crouch or 0) + (tc - (P.crouch or 0)) * pac
    P.menu = (P.menu or 0) + (tm - (P.menu or 0)) * pa
    P.gun = (P.gun or 0) + (tgn - (P.gun or 0)) * pa
    P.aim = (P.aim or 0) + (tam - (P.aim or 0)) * pa
    P.shoot = (P.shoot or 0) + (tsh - (P.shoot or 0)) * pa
    P.t = now
    if state.occ then pcall(state.occ.update, now) end
end

----------------------------------------------------------------------------------------------
-- Drawing: a 3D body made of shaded boxes, plus a line skeleton for debugging.
-- Both are projected onto the screen as an overlay, so they show through walls (no depth test against
-- the level). That is expected until the other player gets a real in-game avatar.
----------------------------------------------------------------------------------------------
local function project(p)
    local sp = draw.world_to_screen(Vector3f.new(p[1], p[2], p[3]))
    -- Never hand NaN or huge coordinates to the renderer.
    if sp and sp.x == sp.x and sp.y == sp.y and math.abs(sp.x) < 20000 and math.abs(sp.y) < 20000 then return sp end
    return nil
end

local function line3(a, b, color)
    local sa, sb = project(a), project(b)
    if sa and sb then draw.line(sa.x, sa.y, sb.x, sb.y, color) end
end

local function vadd(a, b) return { a[1] + b[1], a[2] + b[2], a[3] + b[3] } end
local function vsub(a, b) return { a[1] - b[1], a[2] - b[2], a[3] - b[3] } end
local function vscale(a, k) return { a[1] * k, a[2] * k, a[3] * k } end
local function vdot(a, b) return a[1] * b[1] + a[2] * b[2] + a[3] * b[3] end
local function vcross(a, b)
    return { a[2] * b[3] - a[3] * b[2], a[3] * b[1] - a[1] * b[3], a[1] * b[2] - a[2] * b[1] }
end
local function vnorm(a)
    local l = math.sqrt(vdot(a, a))
    if l < 1e-6 then return { 0, 1, 0 } end
    return { a[1] / l, a[2] / l, a[3] / l }
end

-- Packed as 0xAABBGGRR, which is what the draw functions take (green looks the same either way).
local function rgba(r, g, b, a)
    return math.floor(a) * 16777216 + math.floor(b) * 65536 + math.floor(g) * 256 + math.floor(r)
end

-- Joint positions for the current pose. `pos` is the camera (eyes), fwd the look direction.
local function lerp3(a, b, w) return { a[1] + (b[1] - a[1]) * w, a[2] + (b[2] - a[2]) * w, a[3] + (b[3] - a[3]) * w } end

local function compute_joints(pos, fwd, amp, phase, pz)
    local hx, hz = fwd[1], fwd[3]
    local hl = math.sqrt(hx * hx + hz * hz)
    if hl < 1e-3 then hx, hz = 0, 1 else hx, hz = hx / hl, hz / hl end
    local rx, rz = hz, -hx -- "right" on the ground plane
    local H0 = CFG.EYE_HEIGHT
    local cr = pz and pz.crouch or 0 -- 9.9: 0 standing .. 1 fully crouched
    if cr < 0 then cr = 0 elseif cr > 1 then cr = 1 end
    local H = H0 - CFG.CROUCH_DROP * cr -- where their eyes are above the floor right now
    local lean = 0.10 * cr              -- the crouching body leans forward
    local ox, oy, oz = pos.x, pos.y - H, pos.z -- point on the floor below the camera
    local function J(r, u, f) -- right / up / forward offsets from the feet -> world point
        return { ox + rx * r + hx * f, oy + u, oz + rz * r + hz * f }
    end
    local j = {
        frame = { right = { rx, 0, rz }, fwd = { hx, 0, hz }, up = { 0, 1, 0 } },
        head = { pos.x, pos.y, pos.z },
        neck = J(0, H - 0.18, lean),
        pelvis = J(0, H0 * 0.56 - 0.40 * cr, -0.05 * cr),
        shoulder = {}, hip = {}, elbow = {}, hand = {}, knee = {}, foot = {},
    }
    local sh_u = H - 0.28
    local drop_e, drop_h = H0 - 0.28 - H0 * 0.72, H0 - 0.28 - H0 * 0.55 -- elbow / hand hang this far below the shoulder
    amp = amp * (1 - 0.5 * cr) -- a crouch-walk is shorter strides
    for _, k in ipairs({ 1, -1 }) do
        local ph = phase + (k > 0 and 0 or math.pi) -- legs and arms swing in opposition
        local stride = amp * 0.32 * math.sin(ph)
        local lift = amp * 0.14 * math.max(0, math.cos(ph))
        j.shoulder[k] = J(k * 0.2, sh_u, lean * 0.8)
        j.hip[k] = J(k * 0.1, H0 * 0.56 - 0.40 * cr, -0.05 * cr)
        j.knee[k] = J(k * 0.1, H0 * 0.28 + lift * 0.5, stride * 0.6 + amp * 0.05)
        j.foot[k] = J(k * 0.1, lift, stride)
        j.elbow[k] = J(k * 0.23, sh_u - drop_e, lean * 0.8 - stride * 0.5)
        j.hand[k] = J(k * 0.23, sh_u - drop_h, lean * 0.8 - stride)
    end

    -- Poses . A pose pulls the arms to a target and settles the legs; the weights come from state.pose.
    --   guard: both forearms up in front of the face, elbows down and forward (a boxer's cover)
    --   heal:  the left forearm lies across the chest and the right hand brings the item to it, with a small pressing motion
    -- These are stand-ins for the real animations: the shapes are guesses until button 11's recording says what the game does.
    local g, h = pz and pz.guard or 0, pz and pz.heal or 0
    if g > 0.01 or h > 0.01 then
        local stand = math.max(g, h)
        for _, k in ipairs({ 1, -1 }) do
            -- legs settle to a standing stance (a slight bend for the guard)
            j.knee[k] = lerp3(j.knee[k], J(k * 0.1, H * 0.28, 0.05 + g * 0.06), stand)
            j.foot[k] = lerp3(j.foot[k], J(k * 0.1 + k * g * 0.04, 0, g * 0.05), stand)
            if g > 0.01 then
                local w = g * (1 - h)
                j.elbow[k] = lerp3(j.elbow[k], J(k * 0.19, H - 0.50, 0.17), w)
                j.hand[k] = lerp3(j.hand[k], J(k * 0.08, H - 0.10, 0.30), w)
            end
            if h > 0.01 then
                local press = 0.03 * math.sin((pz.t or 0) * 10)
                if k < 0 then -- left arm: forearm across the chest
                    j.elbow[k] = lerp3(j.elbow[k], J(-0.20, H - 0.52, 0.12), h)
                    j.hand[k] = lerp3(j.hand[k], J(0.05, H - 0.47, 0.26), h)
                else -- right arm: brings the item to the left forearm
                    j.elbow[k] = lerp3(j.elbow[k], J(0.22, H - 0.50, 0.15), h)
                    j.hand[k] = lerp3(j.hand[k], J(0.02, H - 0.40 + press, 0.29), h)
                end
            end
        end
        if h > 0.5 then j.item = j.hand[1] end -- the thing in their right hand
    end

    -- Inventory : both forearms come up in front of the belt, the hands side by side as if holding the pouch open, and
    -- the body leans a little toward them while the hands shuffle. A guess at the shape until the game's own animation is recorded.
    local mn = pz and pz.menu or 0
    mn = mn * (1 - math.max(g, h))
    if mn > 0.01 then
        local fid = 0.02 * math.sin((pz.t or 0) * 3.1)
        for _, k in ipairs({ 1, -1 }) do
            j.knee[k] = lerp3(j.knee[k], J(k * 0.1, H * 0.28, 0.04), mn * (1 - cr))
            j.foot[k] = lerp3(j.foot[k], J(k * 0.1, 0, 0), mn * (1 - cr))
            j.elbow[k] = lerp3(j.elbow[k], J(k * 0.21, H - 0.52, 0.10), mn)
            j.hand[k] = lerp3(j.hand[k], J(k * 0.07, H - 0.62 + fid * k, 0.30 + fid), mn)
        end
        j.neck = lerp3(j.neck, J(0, H - 0.18, lean + 0.05), mn)
    end

    -- Crouch : both legs fold into a squat. The knee is the point of a two-bone leg (thigh = shin = H0*0.28) that
    -- bends forward, so the bones keep their length; blended in by how far into the crouch they are, over whatever the legs
    -- were doing (walking, or settled for a block / heal).
    if cr > 0.01 then
        local L = H0 * 0.28
        local hu, hf, ff = H0 * 0.56 - 0.40 * cr, -0.05 * cr, 0.06 * cr
        local wf, wu = ff - hf, -hu
        local d = math.sqrt(wf * wf + wu * wu)
        local half = math.min(d / 2, L)
        local off = math.sqrt(math.max(L * L - half * half, 0))
        local kf, ku = (hf + ff) / 2 + (hu / d) * off, hu / 2 + (wf / d) * off
        for _, k in ipairs({ 1, -1 }) do
            j.knee[k] = lerp3(j.knee[k], J(k * 0.1, ku, kf), cr)
            j.foot[k] = lerp3(j.foot[k], J(k * 0.1, 0, ff), cr)
        end
    end
    return j
end

-- Debug skeleton: just lines between the joints, plus the look direction.
local function draw_skeleton(j, fwd3, color)
    line3(j.neck, j.head, color)
    line3(j.neck, j.pelvis, color)
    line3(j.shoulder[1], j.shoulder[-1], color)
    line3(j.hip[1], j.hip[-1], color)
    for _, k in ipairs({ 1, -1 }) do
        line3(j.shoulder[k], j.elbow[k], color)
        line3(j.elbow[k], j.hand[k], color)
        line3(j.hip[k], j.knee[k], color)
        line3(j.knee[k], j.foot[k], color)
    end
    line3(j.head, vadd(j.head, vscale(fwd3, 0.45)), 0xFFFFFFFF)
end

-- ---- 3D body: oriented boxes, back-face culled, sorted far to near, flat shaded ----
local PERIM = { { -1, -1 }, { 1, -1 }, { 1, 1 }, { -1, 1 } }
local function corner_index(s1, s2, s3)
    return (s1 > 0 and 4 or 0) + (s2 > 0 and 2 or 0) + (s3 > 0 and 1 or 0) + 1
end
local FACES = {} -- each face: which axis it is perpendicular to, which side, and its 4 corner indices
for axis = 1, 3 do
    local a2, a3 = (axis % 3) + 1, ((axis + 1) % 3) + 1
    for _, sign in ipairs({ 1, -1 }) do
        local idx = {}
        for _, pq in ipairs(PERIM) do
            local sgn = { 0, 0, 0 }
            sgn[axis], sgn[a2], sgn[a3] = sign, pq[1], pq[2]
            idx[#idx + 1] = corner_index(sgn[1], sgn[2], sgn[3])
        end
        FACES[#FACES + 1] = { axis = axis, sign = sign, idx = idx }
    end
end
local LIGHT = vnorm({ 0.35, 0.85, 0.4 })

local function make_box(center, ax, ay, az, hx, hy, hz)
    local corners = {}
    for _, s1 in ipairs({ -1, 1 }) do
        for _, s2 in ipairs({ -1, 1 }) do
            for _, s3 in ipairs({ -1, 1 }) do
                local c = vadd(center, vadd(vscale(ax, s1 * hx), vadd(vscale(ay, s2 * hy), vscale(az, s3 * hz))))
                corners[corner_index(s1, s2, s3)] = c
            end
        end
    end
    return { center = center, axes = { ax, ay, az }, half = { hx, hy, hz }, corners = corners }
end

-- A thick bar from a to b (arms, legs); `side` is a hint for which way its width points.
local function limb_box(a, b, half_width, side)
    local d = vsub(b, a)
    local len = math.sqrt(vdot(d, d))
    local ay = vnorm(d)
    local ax = vnorm(vsub(side, vscale(ay, vdot(side, ay))))
    local az = vcross(ax, ay)
    return make_box(vscale(vadd(a, b), 0.5), ax, ay, az, half_width, math.max(len / 2, 0.01), half_width)
end

local function draw_box(box, cam, base, alpha, outline)
    local projected = {}
    local function P(i)
        local v = projected[i]
        if v == nil then
            v = project(box.corners[i]) or false
            projected[i] = v
        end
        return v
    end
    for _, f in ipairs(FACES) do
        local n = vscale(box.axes[f.axis], f.sign)
        local face_center = vadd(box.center, vscale(n, box.half[f.axis]))
        if vdot(n, vsub(cam, face_center)) > 0 then -- the face points at the camera
            local a, b, c, d = P(f.idx[1]), P(f.idx[2]), P(f.idx[3]), P(f.idx[4])
            if a and b and c and d then
                if draw.filled_quad then
                    local br = 0.40 + 0.60 * math.max(0, vdot(n, LIGHT))
                    draw.filled_quad(a.x, a.y, b.x, b.y, c.x, c.y, d.x, d.y,
                        rgba(base[1] * br, base[2] * br, base[3] * br, alpha))
                end
                draw.line(a.x, a.y, b.x, b.y, outline)
                draw.line(b.x, b.y, c.x, c.y, outline)
                draw.line(c.x, c.y, d.x, d.y, outline)
                draw.line(d.x, d.y, a.x, a.y, outline)
            end
        end
    end
end

local function draw_body(j, fwd3, cam, tint)
    local R, F, U = j.frame.right, j.frame.fwd, j.frame.up
    local function tinted(r, g, b) return { r * tint[1] / 255, g * tint[2] / 255, b * tint[3] / 255 } end
    local skin, shirt, trousers, shoe = tinted(240, 240, 240), tinted(200, 230, 210), tinted(150, 170, 200), tinted(110, 110, 110)
    local visor = tinted(255, 255, 255)
    local parts = {}
    local function add(box, color) parts[#parts + 1] = { box = box, color = color } end

    -- torso
    local torso_len = math.sqrt(vdot(vsub(j.neck, j.pelvis), vsub(j.neck, j.pelvis)))
    local ty = vnorm(vsub(j.neck, j.pelvis)) -- (tilts forward when they crouch)
    local tz = vcross(R, ty)
    add(make_box(vscale(vadd(j.neck, j.pelvis), 0.5), R, ty, tz, 0.2, torso_len / 2 + 0.03, 0.11), shirt)

    -- head, turned and tilted to the look direction, with a bright visor on its front
    local right = vnorm(vcross({ 0, 1, 0 }, fwd3))
    if math.abs(fwd3[2]) > 0.97 then right = R end
    local up = vcross(fwd3, right)
    local hc = vsub(j.head, vscale(fwd3, 0.05))
    add(make_box(hc, right, up, fwd3, 0.095, 0.12, 0.11), skin)
    add(make_box(vadd(vadd(hc, vscale(fwd3, 0.105)), vscale(up, 0.015)), right, up, fwd3, 0.07, 0.03, 0.012), visor)

    -- a healing item in the right hand while they heal
    if j.item then add(make_box(vadd(j.item, vscale(F, 0.03)), R, U, F, 0.025, 0.045, 0.025), tinted(120, 255, 120)) end

    -- arms, legs, feet
    for _, k in ipairs({ 1, -1 }) do
        add(limb_box(j.shoulder[k], j.elbow[k], 0.055, R), shirt)
        add(limb_box(j.elbow[k], j.hand[k], 0.05, R), skin)
        add(limb_box(j.hip[k], j.knee[k], 0.085, R), trousers)
        add(limb_box(j.knee[k], j.foot[k], 0.065, R), trousers)
        add(make_box(vadd(vadd(j.foot[k], vscale(F, 0.07)), vscale(U, 0.035)), R, U, F, 0.06, 0.04, 0.13), shoe)
    end

    -- far to near, so nearer parts cover farther ones
    for _, p in ipairs(parts) do
        local d = vsub(p.box.center, cam)
        p.d2 = vdot(d, d)
    end
    table.sort(parts, function(a, b) return a.d2 > b.d2 end)
    local outline = rgba(10, 30, 15, 200)
    for _, p in ipairs(parts) do draw_box(p.box, cam, p.color, CFG.BODY_ALPHA, outline) end
end

local function draw_tag(pos, label, color)
    local tag = project({ pos.x, pos.y + 0.32, pos.z })
    if tag then draw.text(label, tag.x - #label * 3.5, tag.y - 14, color) end
end

-- Why the other player is not being drawn right now, or nil if they should be.
local function remote_hidden(now)
    if now < state.hidden_until then return "hidden after the new game (" .. math.ceil(state.hidden_until - now) .. " s)" end
    local lp, rp = state.local_pos, state.render_pos
    if lp and rp then
        local dx, dy, dz = rp.x - lp.x, rp.y - lp.y, rp.z - lp.z
        if dx * dx + dy * dy + dz * dz < CFG.HIDE_NEAR_DISTANCE ^ 2 then return "too close to your camera" end
    end
    return nil
end

----------------------------------------------------------------------------------------------
-- Walls . The stand-in is drawn on top of the picture, so it showed through walls and doors. This asks the game's physics
-- (a ray from your camera to four points of their body) whether something solid is in the way, and does not draw them while
-- all four points are covered. Nothing here is a hook: it only asks. If the physics calls do not work in this game, the
-- status says why, the stand-in stays visible as before, and the debug file lists what the game offers.
-- A real model (the "cloned model" route) is hidden by the game's own depth test, so this only applies to the overlay.
-- Which collision layer finds the level is not known, so the first time it casts a ray straight down in front of you for each
-- layer 0..31 and keeps (at most three of) the layers that hit the floor.
----------------------------------------------------------------------------------------------
state.occ = {
    status = "not tried yet", ready = false, setup_done = false, dead = false, dead_at = nil, blocked = false,
    layers = {}, variant = 1, calibrated = false, calib_round = 0, retry_at = 0, retries = 0, recalibrations = 0,
    steps = nil, cal_i = 0, floor_hits = { {}, {}, {}, {} }, hit_names = {}, hit_names_n = 0,
    retry_delay = 3, fail_pos = nil, scene_way_dead = false, scene_way_error = nil,
    rays = 0, checks = 0, blocked_checks = 0, errors = 0, last_err = nil, check_at = -10, streak = 0, api = {}, methods = {},
    blocked_since = nil, blocked_from = nil, ignored = {}, ignored_n = 0,
    clear_streak = 0, skip_names = {}, skip_n = 0, blockers = {}, blockers_n = 0, last_blocker = nil, solid_name = nil,
}
-- 4 tests a second (it was 10): steadier, and cheaper. A change needs two tests in a row both ways (about half a second).
state.occ.CHECK_EVERY = 0.25
state.occ.RECAL_AFTER, state.occ.RECAL_WALK2 = 60, 225 -- "behind a wall" for 60 s while walking 15 m (it was 30 s and 8 m: 16 recalibrations in one session)

-- What the wall rays hit is not always a wall. The debug files list the names of the things the rays hit, and the top ones
-- are door SENSORS (CloseSensor 43,648 hits, KnockSensor 20,356, PushSensor, PassSensor: trigger volumes around every door that
-- are not solid but are found by a ray), safe-room volumes (SafeRoomCollider_*, SafeZone_*), a forbidden-zone trigger
-- (Mold_Acthion_Kinshi_Zone_*), 400_HardMode_ActivateObject, a water plane and effects (Garden_largewater, Dust_camera,
-- Outside_shaftsmoke01). They hid the other player behind "walls" that were doors and doorways. You asked that doors never be a
-- reason to hide them (and that an opened door must not hide them), so anything named like a door or a gate does not count either:
-- a closed door no longer hides them either (the game's real door state is not read; no door PANEL has appeared in a debug file yet,
-- only door sensors, so a panel with an unexpected name can still count: the debug file lists what counted as a wall).
-- The words are matched in lower case; "Door" and "Gate" as written (so "MainDoor" and "Door_1F" match but "Outdoor_Wall"
-- and "Indoor_Wall" do not), and a lower-case "door" only at the start of a word. "saferoom" alone is not a word: the debug file
-- has a "c03_TrailerHouse_saferoom" that may be a real wall, while "SafeRoomCollider_*" is the trigger volume.
-- The 9.17 file adds: Em3000 (an enemy, 1,006 hits: it moves, and standing behind Jack should not hide anyone), NewZoneGroup
-- (1,840) and InMainHall (524), which are area volumes. So: enemies (Em plus four digits), "zonegroup", and "In" + a capital letter at
-- the start of a name (InMainHall, but not InnerWall) are not walls either.
-- 9.27 (the 0.9 file, 692 blocked checks): "VFX_c03_OldHouse" 153 and "VFX_c03_MainHouseArea" 9 were hiding the other player. They are effect
-- volumes, not walls, and you asked that anything with VFX in its name is not a wall: "vfx" anywhere in the name (any case) is not.
state.occ.NOT_WALL_WORDS = { "sensor", "safezone", "saferoomcollider", "kinshi_zone", "activateobject", "dust_", "water", "smoke", "zonegroup", "stair", "vfx" }
state.occ.NOT_WALL_CASE_WORDS = { "Gate", "Door" }
function state.occ.is_wall(name)
    if name:match("^Pl%d%d%d%d") ~= nil then return false end -- (your own body)
    if name:match("^Em%d%d%d%d") ~= nil then return false end -- an enemy
    if name:match("^In%u") ~= nil then return false end -- an area volume such as InMainHall
    if state.occ.skip_names[name] then return false end -- a collider you told me is not a wall (panel button)
    local low = name:lower()
    for _, w in ipairs(state.occ.NOT_WALL_WORDS) do
        if low:find(w, 1, true) then return false end
    end
    for _, w in ipairs(state.occ.NOT_WALL_CASE_WORDS) do
        if name:find(w, 1, true) then return false end
    end
    if low:match("^door") or low:match("[^a-z]door") then return false end
    return true
end

function state.occ.setup()
    local O = state.occ
    O.setup_done = true
    local ok, err = pcall(function()
        O.physics = sdk.get_native_singleton("via.physics.System")
        O.ptype = sdk.find_type_definition("via.physics.System")
        if not O.physics or not O.ptype then error("via.physics.System was not found") end
        O.query = sdk.create_instance("via.physics.CastRayQuery")
        O.result = sdk.create_instance("via.physics.CastRayResult")
        if not O.query or not O.result then error("CastRayQuery / CastRayResult could not be created") end
        pcall(function() O.query:add_ref() end)
        pcall(function() O.result:add_ref() end)
    end)
    for _, tn in ipairs({ "via.physics.System", "via.physics.CastRayQuery", "via.physics.CastRayResult" }) do
        pcall(function()
            local names = {}
            for _, m in ipairs(sdk.find_type_definition(tn):get_methods() or {}) do
                if #names < 70 then
                    local nm = m:get_name()
                    -- with the parameter types, so the two setRay and the three castRay can be told apart
                    if tn ~= "via.physics.System" or nm:find("^castRay") then
                        pcall(function()
                            local ps = {}
                            for _, pt in ipairs(m:get_param_types() or {}) do ps[#ps + 1] = pt:get_full_name() end
                            nm = nm .. "(" .. table.concat(ps, ", ") .. ")"
                        end)
                    end
                    names[#names + 1] = nm
                end
            end
            O.methods[tn] = names
        end)
    end
    if ok then
        O.ready = true
        O.status = "ray test ready: finding the collision layer"
    else
        O.dead, O.dead_at = true, os.clock()
        O.status = "unavailable (" .. tostring(err) .. "): the stand-in is not hidden behind walls"
    end
end

-- The first debug file (build 9.9) showed no layer hit the floor, 96 rays in all. So the calibration now tries three ways
-- of casting (1: options cleared then all hits on; 2: the options left alone; 3: all hit kinds on and the filter left alone)
-- on every layer, and keeps the first way that finds the floor.
function state.occ.new_round()
    local O = state.occ
    O.steps, O.cal_i, O.floor_hits = {}, 0, { {}, {}, {}, {} }
    for v = 1, 2 do
        for l = 0, 31 do O.steps[#O.steps + 1] = { v, l } end
    end
    O.steps[#O.steps + 1] = { 3, 0 }
    -- Way 4: the same as way 1 but through castRay(via.Scene, query, result) with the current scene. Tried only from the second
    -- round on (a round that found nothing), so where the first three ways work nothing changes. The 9.18 file from the trailer house:
    -- 211 rays in three rounds, no layer found the floor, the only thing ever hit was SafeRoomCollider_TrailerHouse (a trigger volume).
    if O.calib_round >= 1 and not O.scene_way_dead then
        for l = 0, 31 do O.steps[#O.steps + 1] = { 4, l } end
    end
end

-- Casts one ray; true = something solid is on it, false = clear, nil = the call failed.
-- A hit on the player's own body (Pl0000 ...) does not count: the ray starts next to the camera.
-- 9.26, wall probe only: what KIND of thing is a collider the rays hit? The 0.8 files' top "walls" were named like rooms and areas
-- (Garden00 400 hits, Cube_Collider 351, MainHouse1F 188, c03_MainHouse1FHallway_id15C 122, hall_passage 120, "1F", "B1"), and the
-- name filter can only guess. Once per name (80 names at most): the collidable's type, a few yes/no properties if the type has them
-- (static, kinematic, trigger, layer, group ...), the shape's type, and once per type (4 at most) the NAMES of its methods, so the
-- next build can ask for the one that tells a solid wall from a trigger volume. Nothing is called that the type does not list.
state.occ.cinfo, state.occ.cinfo_n, state.occ.ctypes, state.occ.ctypes_n = {}, 0, {}, 0
function state.occ.note_collidable(name, col)
    local O = state.occ
    if col == nil or O.cinfo[name] ~= nil or O.cinfo_n >= 80 then return end
    O.cinfo_n = O.cinfo_n + 1
    local info = {}
    O.cinfo[name] = info
    pcall(function()
        local td = col:get_type_definition()
        local tn = td:get_full_name()
        info.type = tn
        if O.ctypes[tn] == nil and O.ctypes_n < 4 then
            O.ctypes_n = O.ctypes_n + 1
            local names = {}
            for _, m in ipairs(td:get_methods()) do
                if #names < 120 then names[#names + 1] = m:get_name() end
            end
            O.ctypes[tn] = names
        end
        for _, getter in ipairs({ "get_Static", "get_IsStatic", "get_Kinematic", "get_IsKinematic", "get_Trigger", "get_IsTrigger", "get_Enabled",
            "get_Layer", "get_Group", "get_Mode", "get_Attribute", "get_ShapeType", "get_Type" }) do
            if td:get_method(getter) then
                local okv, v = pcall(function() return col:call(getter) end)
                if okv and (type(v) == "number" or type(v) == "boolean" or type(v) == "string") then info[getter:sub(5)] = v end
            end
        end
        if td:get_method("get_Shape") then
            local oks, sh = pcall(function() return col:call("get_Shape") end)
            if oks and sh ~= nil then info.shape = sh:get_type_definition():get_full_name() end
        end
    end)
end

function state.occ.cast(layer, ax, ay, az, bx, by, bz, variant, probe)
    local O = state.occ
    variant = variant or O.variant or 1
    local q, r = O.query, O.result
    O.solid_name = nil
    local ok, res = pcall(function()
        q:call("setRay(via.vec3, via.vec3)", Vector3f.new(ax, ay, az), Vector3f.new(bx, by, bz))
        if variant == 1 or variant == 4 then
            O.api.clear = pcall(q.call, q, "clearOptions")
            pcall(q.call, q, "enableAllHits")
            pcall(q.call, q, "enableNearSort")
        elseif variant == 3 then
            for _, m in ipairs({ "enableAllHits", "enableNearSort", "enableFrontFacingTriangleHits", "enableBackFacingTriangleHits",
                "enableInsideHits" }) do
                pcall(q.call, q, m)
            end
        end
        if variant ~= 3 then
            O.api.filter = pcall(function()
                local fi = q:call("get_FilterInfo")
                fi:call("set_Group", 0)
                fi:call("set_MaskBits", 4294967295)
                fi:call("set_Layer", layer)
                q:call("set_FilterInfo", fi)
            end)
        end
        if variant == 4 then
            local scene = sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
            if scene == nil then error("no current scene") end -- (fetched for every ray: a scene kept from before a load could be gone)
            sdk.call_native_func(O.physics, O.ptype, "castRay(via.Scene, via.physics.CastRayQuery, via.physics.CastRayResult)", scene, q, r)
        else
            sdk.call_native_func(O.physics, O.ptype, "castRay(via.physics.CastRayQuery, via.physics.CastRayResult)", q, r)
        end
        local n = tonumber(r:call("get_NumContactPoints")) or 0
        if n == 0 then return false end
        local solid = false
        for i = 0, math.min(n, 4) - 1 do
            local name, col
            pcall(function() col = r:call("getContactCollidable", i); name = col:call("get_GameObject"):call("get_Name") end)
            if probe ~= nil and type(name) == "string" then
                probe[name] = (probe[name] or 0) + 1 -- the wall probe wants every name
                O.note_collidable(name, col)
            end
            if type(name) == "string" then
                if O.hit_names[name] == nil and O.hit_names_n < 120 then
                    O.hit_names_n = O.hit_names_n + 1
                    O.hit_names[name] = 0
                end
                if O.hit_names[name] then O.hit_names[name] = O.hit_names[name] + 1 end
            end
            if type(name) ~= "string" then
                solid = true -- (a hit with no readable name stays a wall, as before)
            elseif O.is_wall(name) then
                solid = true
                if O.solid_name == nil then O.solid_name = name end -- the nearest wall-like thing on the ray (the hits are sorted near to far)
            elseif not name:match("^Pl%d%d%d%d") then
                if O.ignored[name] == nil and O.ignored_n < 30 then O.ignored_n = O.ignored_n + 1 O.ignored[name] = 0 end
                if O.ignored[name] then O.ignored[name] = O.ignored[name] + 1 end
            end
        end
        return solid
    end)
    O.rays = O.rays + 1
    if not ok and variant == 4 then
        -- the scene overload is optional: if it fails it is given up on its own and never counts toward "the ray test is dead"
        O.scene_way_dead, O.scene_way_error = true, tostring(res):sub(1, 100)
        return nil
    end
    if not ok then
        O.errors = O.errors + 1
        O.last_err = tostring(res)
        O.err_run = (O.err_run or 0) + 1
        if O.err_run >= 8 then
            O.dead, O.dead_at, O.blocked = true, os.clock(), false
            O.status = "unavailable (" .. O.last_err .. "): the stand-in is not hidden behind walls"
        end
        return nil
    end
    O.err_run = 0
    return res
end

-- The wall probe. The walls work in the main house but not by Ethan's car or in the guest house (your notes 1 and 8), and the
-- test only casts on the two or three layers its calibration found, so a wall on any other layer is invisible to it. This casts
-- 8 horizontal rays of 6 m from where the camera is, on EVERY layer 0 to 31, and keeps for each layer the names it hit (with how
-- many rays, and whether the script counts that name as a wall). Stand next to a wall, a door and the car and press the button;
-- the result is in the debug file (health.occlusion.layer_probe) and in the journal. It changes nothing else.
function state.occ.probe()
    local O = state.occ
    local lp = state.local_pos
    if not O.ready or O.dead then
        O.probe_note = "the ray test is not available (" .. tostring(O.status) .. ")"
        say("walls probe: " .. O.probe_note)
        return
    end
    if not lp then
        O.probe_note = "no camera position yet"
        say("walls probe: " .. O.probe_note)
        return
    end
    local res = { at = { math.floor(lp.x * 100) / 100, math.floor(lp.y * 100) / 100, math.floor(lp.z * 100) / 100 }, layers = {}, rays_per_layer = 8, length = 6,
        layers_in_use = O.layers }
    local lines, y = {}, lp.y - 0.4
    for layer = 0, 31 do
        local hits = {}
        for k = 0, 7 do
            local a = k * math.pi / 4
            O.cast(layer, lp.x, y, lp.z, lp.x + math.cos(a) * 6, y, lp.z + math.sin(a) * 6, O.variant, hits)
        end
        local list = {}
        for nm, c in pairs(hits) do list[#list + 1] = { name = nm, rays = c, counts_as_wall = O.is_wall(nm) } end
        table.sort(list, function(a, b) if a.rays ~= b.rays then return a.rays > b.rays end return a.name < b.name end)
        while #list > 8 do table.remove(list) end
        if #list > 0 then
            res.layers[tostring(layer)] = list
            local parts = {}
            for i = 1, math.min(#list, 4) do parts[#parts + 1] = string.format("%s x%d%s", list[i].name, list[i].rays, list[i].counts_as_wall and "" or " (not a wall)") end
            lines[#lines + 1] = string.format("layer %d%s: %s", layer, (O.layers and (layer == O.layers[1] or layer == O.layers[2] or layer == O.layers[3])) and " [in use]" or "", table.concat(parts, ", "))
        end
    end
    -- The 9.18 file from the trailer house: no layer found the floor by any of the three ways, in three rounds. So the probe also
    -- casts one ray straight down (from 0.2 m above the camera to 4 m below) on every layer by EVERY way, 4 being the scene overload,
    -- and lists for each way the layers that hit anything at all and what (wall or not). "No floor by any way" means this area's
    -- collision is not reachable by these calls at all; a way that finds it is what the next build should use.
    res.floor_by_way = {}
    local floor_any = false
    for way = 1, 4 do
        local per, n_found = {}, 0
        if way == 4 and O.scene_way_dead then
            res.floor_by_way["4"] = "failed: " .. tostring(O.scene_way_error)
        else
            for layer = 0, (way == 3 and 0 or 31) do
                local hits = {}
                local r = O.cast(layer, lp.x, lp.y + 0.2, lp.z, lp.x, lp.y - 4.0, lp.z, way, hits)
                if r == nil and way == 4 then res.floor_by_way["4"] = "failed: " .. tostring(O.scene_way_error) break end
                local names = {}
                for nm in pairs(hits) do names[#names + 1] = nm end
                table.sort(names)
                while #names > 3 do table.remove(names) end
                if #names > 0 or r == true then
                    per[tostring(layer)] = names
                    n_found = n_found + 1
                end
            end
            if res.floor_by_way[tostring(way)] == nil then res.floor_by_way[tostring(way)] = per end
        end
        if n_found > 0 then
            floor_any = true
            local parts = {}
            for layer = 0, 31 do
                local names = per[tostring(layer)]
                if names then parts[#parts + 1] = string.format("%d (%s)", layer, #names > 0 and table.concat(names, ", ") or "unnamed") end
            end
            lines[#lines + 1] = string.format("straight down, way %d: %d layers hit something: %s", way, n_found, table.concat(parts, "; "):sub(1, 220))
        end
    end
    res.floor_found_by_any_way = floor_any
    res.collidables = O.cinfo       -- 9.26: what kind of thing each named collider is (type, flags, shape)
    res.collidable_methods = O.ctypes -- 9.26: the method names of the collider types seen
    O.probe_result = res
    O.probe_note = string.format("probed at (%.1f, %.1f, %.1f): %d lines; %s", lp.x, lp.y, lp.z, #lines,
        floor_any and "something is under your feet for at least one way" or "NOTHING under your feet on any layer by any of the four ways")
    say("walls probe: " .. O.probe_note)
    for _, l in ipairs(lines) do say("walls probe:   " .. l) end
    if #lines == 0 then say("walls probe: nothing within 6 m on any layer (an open place, or the rays do not work here)") end
end

function state.occ.update(now)
    local O = state.occ
    if not state.occlude then
        O.blocked, O.status = false, "switched off"
        return
    end
    local lp, rp = state.local_pos, state.render_pos
    if O.dead and O.dead_at and now - O.dead_at > 60 and O.retries < 5 then -- not for good: a new scene may work
        O.dead, O.dead_at, O.err_run, O.retries = false, nil, 0, O.retries + 1
        if not O.ready then O.setup_done = false end -- (the singleton / types were missing: look for them again too)
        O.status = "ray test ready: trying again"
    end
    if not lp or not rp or not state.remote or O.dead then
        O.blocked = false
        return
    end
    if now - O.check_at < (O.calibrated and O.CHECK_EVERY or 0.1) then return end -- (calibrating stays at 10 a second so the layers are found quickly)
    O.check_at = now
    if not O.setup_done then O.setup() end
    if not O.ready or O.dead then
        O.blocked = false
        return
    end
    local dx, dy, dz = rp.x - lp.x, rp.y - lp.y, rp.z - lp.z
    local dist = math.sqrt(dx * dx + dy * dy + dz * dz)
    if dist < 1.2 then -- right next to you: nothing can be between you
        O.blocked, O.streak, O.blocked_since = false, 0, nil
        return
    end
    local hl = math.sqrt(dx * dx + dz * dz)
    if hl < 0.5 then hl = 1 end
    if not O.calibrated then
        O.blocked = false
        if now < O.retry_at then
            -- another spot may have another floor: after 3 m of walking it does not wait any longer
            local fp = O.fail_pos
            if fp and (lp.x - fp[1]) ^ 2 + (lp.z - fp[2]) ^ 2 > 9 then
                O.retry_at, O.fail_pos = now, nil
            else
                return
            end
        end
        if not O.steps then O.new_round() end
        -- a few rays per test so the game does not hitch: from 0.8 m toward them, 0.2 m up, 4.2 m straight down
        local sx, sz = lp.x + dx / hl * 0.8, lp.z + dz / hl * 0.8
        local n = 0
        while O.cal_i < #O.steps and n < 4 do
            n = n + 1
            local st = O.steps[O.cal_i + 1]
            local hit = O.cast(st[2], sx, lp.y + 0.2, sz, sx, lp.y - 4.0, sz, st[1])
            if hit == nil then
                if st[1] ~= 4 then return end
                O.cal_i = #O.steps -- (the scene overload failed: the rest of the round is the same call, skip it)
                break
            end
            O.cal_i = O.cal_i + 1
            if hit then
                local fh = O.floor_hits[st[1]]
                fh[#fh + 1] = st[2]
            end
        end
        if O.cal_i >= #O.steps then
            O.calib_round = O.calib_round + 1
            local pv
            for v = 1, 4 do
                if #O.floor_hits[v] > 0 then pv = v break end
            end
            if pv then
                local picked = {}
                for _, l in ipairs(O.floor_hits[pv]) do
                    if #picked < 3 then picked[#picked + 1] = l end
                end
                O.layers, O.variant, O.calibrated = picked, pv, true
                O.retry_delay, O.fail_pos = 3, nil
                O.status = "working (collision layers " .. table.concat(picked, ", ") .. ")" .. (pv ~= 1 and (", way " .. pv) or "")
            else
                O.steps = nil -- the next try starts from scratch (maybe there was no floor under that spot)
                -- It waited 45 s every time ("takes too long to find a collision", your note 2). Now 3 s, 6, 12, 24, then 45, and at once
                -- after 3 m of walking.
                local delay = O.retry_delay or 3
                O.retry_at, O.fail_pos = now + delay, { lp.x, lp.z }
                O.retry_delay = math.min(delay * 2, 45)
                O.status = string.format("unavailable (no collision layer found the floor): the stand-in is not hidden behind walls (trying again in %d s, or after you walk 3 m)", delay)
            end
        end
        return
    end
    -- four points of their body, eyes down to the feet
    local crouch = (state.pose and state.pose.crouch) or 0
    local he = CFG.EYE_HEIGHT - CFG.CROUCH_DROP * crouch
    local offsets = { 0.05, he * 0.40, he * 0.75, math.max(he - 0.2, 0.3) }
    local clear, first_name = false, nil
    for _, off in ipairs(offsets) do
        local tx, ty, tz = rp.x, rp.y - off, rp.z
        local vx, vy, vz = tx - lp.x, ty - lp.y, tz - lp.z
        local vl = math.sqrt(vx * vx + vy * vy + vz * vz)
        if vl < 0.7 then
            clear = true
            break
        end
        vx, vy, vz = vx / vl, vy / vl, vz / vl
        local ax, ay, az = lp.x + vx * 0.3, lp.y + vy * 0.3, lp.z + vz * 0.3 -- start outside your own body
        local bx, by, bz = tx - vx * 0.12, ty - vy * 0.12, tz - vz * 0.12   -- and stop short of the floor / wall behind them
        local covered = false
        for _, layer in ipairs(O.layers) do
            if O.cast(layer, ax, ay, az, bx, by, bz, O.variant) == true then
                covered = true
                if not first_name then first_name = O.solid_name end
                break
            end
        end
        if not covered then
            clear = true
            break
        end
    end
    O.checks = O.checks + 1
    if clear then
        O.streak = 0
        O.clear_streak = O.clear_streak + 1
        if O.clear_streak >= 2 then O.blocked = false end -- two clear tests in a row to show them again
    else
        O.clear_streak = 0
        O.streak = O.streak + 1
        O.blocked_checks = O.blocked_checks + 1
        if O.streak >= 2 then O.blocked = true end -- (twice in a row: one odd frame does not make them blink)
        -- which collider is hiding them: shown in the panel (with a button to say it is not a wall) and counted in the debug file
        local bn = first_name or "(no readable name)"
        O.last_blocker = bn
        if O.blockers[bn] == nil and O.blockers_n < 60 then O.blockers_n = O.blockers_n + 1 O.blockers[bn] = 0 end
        if O.blockers[bn] then O.blockers[bn] = O.blockers[bn] + 1 end
    end
    -- a wall does not follow you: "behind a wall" for 30 s while you walk 8 m means the layers are wrong. Calibrate again.
    if O.blocked then
        if not O.blocked_since then O.blocked_since, O.blocked_from = now, { lp.x, lp.z } end
        local mx, mz = lp.x - O.blocked_from[1], lp.z - O.blocked_from[2]
        if now - O.blocked_since > O.RECAL_AFTER and mx * mx + mz * mz > O.RECAL_WALK2 then
            O.calibrated, O.layers, O.steps, O.blocked, O.streak, O.blocked_since = false, {}, nil, false, 0, nil
            O.retry_delay, O.retry_at = 3, 0
            O.recalibrations = O.recalibrations + 1
            O.status = "ray test ready: they stayed 'behind a wall' while you walked 15 m, calibrating again"
            say("walls: calibrating again (they stayed behind a wall while I walked 15 m)")
        end
    else
        O.blocked_since = nil
    end
end

function state.occ.skip_list()
    local t = {}
    for n in pairs(state.occ.skip_names) do t[#t + 1] = n end
    table.sort(t)
    return t
end

-- "This is not a wall": remembered in the settings file. At most 40 names.
function state.occ.skip_add(name)
    local O = state.occ
    if type(name) ~= "string" or name == "" or name == "(no readable name)" then return false end
    if O.skip_names[name] then return true end
    if O.skip_n >= 40 then return false end
    O.skip_names[name], O.skip_n = true, O.skip_n + 1
    O.blocked, O.streak = false, 0
    return true
end

function state.occ.skip_clear()
    state.occ.skip_names, state.occ.skip_n = {}, 0
end

function state.occ.report()
    local O = state.occ
    local fh = {}
    for v = 1, 4 do fh[tostring(v)] = O.floor_hits[v] end
    local names = {}
    for nm, c in pairs(O.hit_names) do names[#names + 1] = { name = nm, hits = c } end
    table.sort(names, function(a, b) return a.hits > b.hits end)
    while #names > 15 do table.remove(names) end
    -- the things that were hit and NOT counted as walls (door sensors, doors, safe-room volumes ...)
    local skipped = {}
    for nm, c in pairs(O.ignored) do skipped[#skipped + 1] = { name = nm, hits = c } end
    table.sort(skipped, function(a, b) return a.hits > b.hits end)
    while #skipped > 15 do table.remove(skipped) end
    return { status = O.status, layer_probe = O.probe_result, probe_note = O.probe_note, not_walls_hit = skipped, not_wall_words = O.NOT_WALL_WORDS, not_wall_words_as_written = O.NOT_WALL_CASE_WORDS, ready = O.ready, calibrated = O.calibrated, layers = O.layers, way_used = O.variant,
        floor_hit_layers_by_way = fh, calibration_rounds = O.calib_round, retry_delay_next = O.retry_delay, scene_way = O.scene_way_dead and ("gave up: " .. tostring(O.scene_way_error)) or "not failed", retries = O.retries, recalibrations = O.recalibrations,
        rays = O.rays, checks = O.checks, blocked_checks = O.blocked_checks, errors = O.errors, last_error = O.last_err,
        api_ok = O.api, hidden_now = O.blocked, things_the_rays_hit = names, methods = O.methods,
        hidden_by = O.blocked and O.last_blocker or nil, last_blocker = O.last_blocker, blockers_counted = O.blockers, names_you_said_are_not_walls = O.skip_list(), check_every_s = O.CHECK_EVERY }
end

-- Why the OVERLAY (not a cloned model) should not be drawn right now, or nil.
state.overlay_hidden = function(now)
    local why = remote_hidden(now)
    if why then return why end
    local M = CFG.menu
    if state.menu_hide and M and M.open then return "a game menu is open (" .. tostring(M.which) .. ")" end
    if state.occlude and state.occ.blocked then return "behind a wall" end
    return nil
end

local function draw_remote(now)
    if not state.remote or not state.render_pos then return end
    -- The debug skeleton is never hidden while it is ticked: not by a wall, an open menu, the wait after a new game, being too
    -- close, the "Show other player" switch or a cloned model. Then only the body and the name are held back (the tag says why).
    local held_back
    if not state.show_figure then
        held_back = "Show other player is off"
    else
        held_back = state.overlay_hidden(now)
    end
    if held_back and not state.show_skeleton then return end
    local stale = (now - state.remote_changed_at) > CFG.STALE_AFTER
    local color = stale and 0xFF888888 or 0xFF00FF00
    local label = state.remote_name or CFG.DEFAULT_NAME
    if stale then label = label .. " (no signal)" end
    if held_back then label = label .. " [body held back: " .. held_back .. "]" end
    local is_down = false
    if state.tag_extra and not stale then -- health module: " HP 65%" or " [downed]"
        local okx, extra, xcolor, down = pcall(state.tag_extra)
        if okx and type(extra) == "string" then
            label = label .. extra
            if xcolor then color = xcolor end
            is_down = down == true
        end
    end
    local amp = math.max(0, math.min(1, (state.speed - 0.15) / 1.8))
    local pos, fwd = state.render_pos, state.render_fwd
    local P = state.pose
    if not stale and not is_down then -- (nobody is "healing" or "blocking" while down: the tag says [downed])
        if P.heal > 0.5 then
            label = label .. " [healing]"
        elseif P.guard > 0.5 then
            label = label .. " [blocking]"
        elseif (P.crouch or 0) > 0.5 then
            label = label .. " [crouching]"
        end
        if (P.shoot or 0) > 0.5 then -- (9.28)
            label = label .. " [shooting]"
        elseif (P.aim or 0) > 0.5 then
            label = label .. " [aiming]"
        elseif (P.gun or 0) > 0.5 and P.heal <= 0.5 and P.guard <= 0.5 then
            label = label .. " [gun out]"
        end
    end
    amp = amp * (1 - 0.85 * math.max(P.guard, P.heal)) -- no walking legs while they block or heal
    local j = compute_joints(pos, fwd, amp, state.walk_phase, P)
    -- (9.29) while the real body stands in, the debug model (green man) is not drawn, unless "Also show the debug model" is ticked
    local okg, real_up = pcall(CFG.real.hides_green)
    if not held_back and state.show_body and state.local_pos and not (okg and real_up == true) then
        local cam = { state.local_pos.x, state.local_pos.y, state.local_pos.z }
        draw_body(j, fwd, cam, stale and { 150, 150, 150 } or { 90, 255, 130 })
    end
    if state.show_skeleton then draw_skeleton(j, fwd, color) end
    draw_tag(pos, label, color)
end

----------------------------------------------------------------------------------------------
-- Messages: a reliable channel to the other player (chat, pings; item events will use it too).
-- Messages go through re7mp.exe, which resends them until the other side confirms and delivers each
-- one once. Kinds: 1 = chat text, 2 = ping "x;y;z".
----------------------------------------------------------------------------------------------

local netmsg = {
    outbox = {},   -- ring of our most recent messages: { id, k, p }
    next_id = math.floor(os.time and os.time() or (os.clock() * 1000)) * 1000,
    dirty = false,
    last_flush = 0,
    handlers = {}, -- kind -> function(payload)
    epoch = nil,   -- which engine run the inbox belongs to
    last_n = 0,    -- last inbox entry we handled
}

local function net_on(kind, handler)
    netmsg.handlers[kind] = handler
end

local function net_send(kind, payload)
    payload = tostring(payload):gsub("%c", " ")
    if #payload > 180 then payload = payload:sub(1, 180) end
    pcall(function() -- never leave half of a multi-byte character at the end
        while #payload > 0 and not utf8.len(payload) do payload = payload:sub(1, -2) end
    end)
    netmsg.next_id = netmsg.next_id + 1
    netmsg.outbox[#netmsg.outbox + 1] = { id = netmsg.next_id, k = kind, p = payload }
    while #netmsg.outbox > 32 do table.remove(netmsg.outbox, 1) end
    netmsg.dirty = true
end

local function flush_messages(now)
    if netmsg.dirty and now - netmsg.last_flush >= 0.05 then
        netmsg.dirty = false
        netmsg.last_flush = now
        json.dump_file(FILES.MSG_OUT_FILE, { msgs = netmsg.outbox })
    end
end

-- Remember what is already in the inbox so old messages are not replayed after a script reload.
local function prime_messages()
    local d = json.load_file(FILES.MSG_IN_FILE)
    if type(d) ~= "table" or type(d.msgs) ~= "table" then return end
    netmsg.epoch = d.epoch
    for _, m in ipairs(d.msgs) do
        if type(m) == "table" and type(m.n) == "number" and m.n > netmsg.last_n then netmsg.last_n = m.n end
    end
end

local function read_messages()
    local now = os.clock()
    local P = CFG.bridge.msg
    if now < P.next_at then P.throttled = P.throttled + 1 return end
    P.next_at = now + ((now - P.heard_at < P.ACTIVE_S) and P.ACTIVE_GAP_S or P.QUIET_S) -- (10.15: see CFG.bridge.msg; 10.20: active mode has a gap too)
    P.reads = P.reads + 1
    local d = CFG.bridge.read("exe_message_file", FILES.MSG_IN_FILE, now)
    if type(d) ~= "table" or type(d.msgs) ~= "table" then return end
    if d.epoch ~= netmsg.epoch then -- the engine restarted: its numbering starts again
        netmsg.epoch = d.epoch
        netmsg.last_n = 0
    end
    for _, m in ipairs(d.msgs) do
        if type(m) == "table" and type(m.n) == "number" and m.n > netmsg.last_n then
            netmsg.last_n = m.n
            P.heard_at = now
            local handler = netmsg.handlers[m.k]
            if handler then
                local ok, err = pcall(handler, tostring(m.p or ""))
                if not ok then say("message handler error: " .. tostring(err)) end
            end
        end
    end
end

-- Chat
local chat = { lines = {}, input = "" }

local function chat_add(who, text)
    chat.lines[#chat.lines + 1] = { who = who, text = text, at = os.clock() }
    while #chat.lines > 40 do table.remove(chat.lines, 1) end
end

local function chat_send(text)
    text = text:gsub("^%s+", ""):gsub("%s+$", "")
    if text == "" then return end
    net_send(1, text)
    chat_add("You", text)
end

net_on(1, function(payload)
    chat_add(state.remote_name or CFG.DEFAULT_NAME, payload)
end)

-- Pings: "look here" markers at a world position
local pings = {}

net_on(2, function(payload)
    local x, y, z = payload:match("^(-?[%d%.]+);(-?[%d%.]+);(-?[%d%.]+)$")
    x, y, z = tonumber(x), tonumber(y), tonumber(z)
    if not (x and y and z) then return end
    pings[#pings + 1] = { x = x, y = y, z = z, who = state.remote_name or CFG.DEFAULT_NAME, at = os.clock() }
    while #pings > 8 do table.remove(pings, 1) end
end)

local function ping_here()
    local p = state.local_pos
    if not p then return end
    -- one ping a second and a half at most: a held key or a double click must not flood the other player
    local now = os.clock()
    if now - (pings.last_sent or -100) < 1.5 then return end
    pings.last_sent = now
    net_send(2, string.format("%.2f;%.2f;%.2f", p.x, p.y, p.z))
    chat_add("You", "(pinged your position)")
end

-- Find the other player (9.27, your idea: "ping the other player's position to tell where they are if you lose them").
-- "Ping my position" shows THEM where I am. This shows ME where THEY are: a marker and a beam at their live position, and when
-- they are off screen an arrow at the edge of the screen that points the way, with the distance, the direction as seen from where
-- you look ("behind left") and the height ("1 floor above"). It lasts 10 s (or until switched off; 9.32: was 15 s). Nothing is sent: their
-- position is already here. F9 does what the choice in the panel says: my position to them / their position on my screen / both.
pings.finder = { until_t = 0, keep = false, shown = 0, last = "Not used yet.", started = 0, SECONDS = 10 }
pings.modes = { "My position to them (they see a marker)", "Their position on my screen (marker or arrow)", "Both" }
pings.mode = 3

pings.directions = { "ahead", "ahead right", "right", "behind right", "behind", "behind left", "left", "ahead left" }

-- Where is the other player, seen from here? Returns a table, or nil plus the reason.
function pings.finder.where()
    local r = state.remote
    local rp = state.render_pos or (r and r.pos)
    if not (r and rp) then return nil, "I have no position of the other player yet" end
    local lp = state.local_pos
    if not lp then return nil, "I can't read your own position" end
    local dx, dy, dz = rp.x - lp.x, rp.y - lp.y, rp.z - lp.z
    local flat = math.sqrt(dx * dx + dz * dz)
    local res = { dx = dx, dy = dy, dz = dz, dist = math.sqrt(dx * dx + dy * dy + dz * dz), flat = flat }
    local lq = state.local_quat
    if lq and flat > 0.5 then
        local fx, _, fz = forward_of(lq)
        local hl = math.sqrt(fx * fx + fz * fz)
        if hl > 1e-3 then
            fx, fz = fx / hl, fz / hl
            -- right of (fx, fz) in this engine is (-fz, fx) (9.32: the 9.27 guess (fz, -fx) pointed the arrow the wrong way; the same
            -- mistake put the body on the LEFT in the 9.23 real-game test and was fixed in CFG.body.place)
            local rx, rz = -fz, fx
            res.angle = math.atan((dx * rx + dz * rz) / flat, (dx * fx + dz * fz) / flat) -- 0 ahead, + to the right
            local idx = math.floor((res.angle + math.pi / 8) / (math.pi / 4))
            res.direction = pings.directions[((idx % 8) + 8) % 8 + 1]
        end
    end
    if dy >= 2 then
        res.height = string.format("%d floor%s above", math.max(1, math.floor(dy / 3 + 0.5)), math.floor(dy / 3 + 0.5) > 1 and "s" or "")
    elseif dy <= -2 then
        res.height = string.format("%d floor%s below", math.max(1, math.floor(-dy / 3 + 0.5)), math.floor(-dy / 3 + 0.5) > 1 and "s" or "")
    end
    local parts = { string.format("%.0f m", res.dist) }
    if res.direction then parts[#parts + 1] = res.direction end
    if res.height then parts[#parts + 1] = res.height end
    res.text = table.concat(parts, ", ")
    return res
end

function pings.finder.start(now)
    now = now or os.clock()
    local w, why = pings.finder.where()
    if not w then
        pings.finder.last = "Can't find them: " .. why
        chat_add("Find", pings.finder.last)
        say("find: " .. pings.finder.last)
        return false
    end
    pings.finder.until_t = now + pings.finder.SECONDS
    pings.finder.started = now
    pings.finder.shown = pings.finder.shown + 1
    pings.finder.last = (state.remote_name or CFG.DEFAULT_NAME) .. ": " .. w.text
    chat_add("Find", pings.finder.last)
    say("find: " .. pings.finder.last)
    return true
end

function pings.finder.stop()
    pings.finder.until_t = 0
    pings.finder.keep = false
end

function pings.finder.active(now)
    return pings.finder.keep or now < pings.finder.until_t
end

-- Drawn every frame while active. Marker and beam when they are on screen, an arrow at the screen's edge when they are not.
function pings.finder.draw(now)
    if not pings.finder.active(now) then return end
    local who = state.remote_name or CFG.DEFAULT_NAME
    local w, why = pings.finder.where()
    local gold = 0xFF40FF40
    if not w then
        pcall(draw.text, "Finding " .. who .. ": " .. tostring(why), 24, 120, gold)
        return
    end
    local rp = state.render_pos or state.remote.pos
    local left = pings.finder.keep and "until you switch it off" or string.format("%.0f s", math.max(0, pings.finder.until_t - now))
    pcall(draw.text, string.format("%s: %s  (%s)", who, w.text, left), 24, 120, gold)
    local sz = { x = 1920, y = 1080 }
    pcall(function() local d = imgui.get_display_size() if d and d.x and d.x > 100 then sz = d end end)
    local top = project({ rp.x, rp.y + 0.9, rp.z })
    local foot = project({ rp.x, rp.y - 1.7, rp.z })
    local on_screen = top and top.x > 0 and top.x < sz.x and top.y > 0 and top.y < sz.y
    if on_screen then
        local r = 11
        draw.line(top.x, top.y - r, top.x + r, top.y, gold)
        draw.line(top.x + r, top.y, top.x, top.y + r, gold)
        draw.line(top.x, top.y + r, top.x - r, top.y, gold)
        draw.line(top.x - r, top.y, top.x, top.y - r, gold)
        if foot then draw.line(top.x, top.y + r, foot.x, foot.y, gold) end -- the beam down to their feet
        draw.text(string.format("%s  %.0f m", who, w.dist), top.x + 16, top.y - 8, gold)
    elseif w.angle then
        local cx, cy = sz.x / 2, sz.y / 2
        local ux, uy = math.sin(w.angle), -math.cos(w.angle) -- on the screen: ahead is up, right is right
        local px, py = cx + ux * (cx - 80), cy + uy * (cy - 80)
        local len = 26
        local tx, ty = px + ux * len, py + uy * len
        draw.line(px - ux * len, py - uy * len, tx, ty, gold)
        local hx, hy = math.cos(0.5), math.sin(0.5)
        draw.line(tx, ty, tx - (ux * hx - uy * hy) * 16, ty - (uy * hx + ux * hy) * 16, gold)
        draw.line(tx, ty, tx - (ux * hx + uy * hy) * 16, ty - (uy * hx - ux * hy) * 16, gold)
        draw.text(string.format("%s  %.0f m%s", who, w.dist, w.height and (", " .. w.height) or ""), px - 60, py + 8, gold)
    end
end

-- What F9 / the "Ping" button does, by the choice in the panel.
function pings.by_mode(mode)
    mode = mode or pings.mode
    if mode == 1 or mode == 3 then ping_here() end
    if mode == 2 or mode == 3 then pings.finder.start() end
end

-- Ping and quick messages without typing: F9 pings, and the panel has one-click phrases (they are ordinary chat messages).
chat.quick = { "Wait for me", "Come here", "Help!", "Found something", "Going ahead" }
chat.hotkey = 0x78 -- F9
function chat.update(now)
    local okk, down = pcall(function() return reframework:is_key_down(chat.hotkey) end)
    down = okk and down == true
    if down and not chat.key_was_down and state.remote then pings.by_mode() end
    chat.key_was_down = down
end

-- On-screen chat and ping markers
local function draw_hud(now)
    local y = 64
    for i = math.max(1, #chat.lines - 5), #chat.lines do
        local l = chat.lines[i]
        if now - l.at < 12 then
            pcall(draw.text, l.who .. ": " .. l.text, 24, y, 0xFFFFFFFF)
            y = y + 16
        end
    end
    for i = #pings, 1, -1 do
        local p = pings[i]
        if now - p.at > 12 then
            table.remove(pings, i)
        else
            local sp = project({ p.x, p.y, p.z })
            if sp then
                local c = 0xFF00D7FF
                local r = 9
                draw.line(sp.x, sp.y - r, sp.x + r, sp.y, c)
                draw.line(sp.x + r, sp.y, sp.x, sp.y + r, c)
                draw.line(sp.x, sp.y + r, sp.x - r, sp.y, c)
                draw.line(sp.x - r, sp.y, sp.x, sp.y - r, c)
                local lp = state.local_pos
                local dist = 0
                if lp then dist = math.sqrt((p.x - lp.x) ^ 2 + (p.y - lp.y) ^ 2 + (p.z - lp.z) ^ 2) end
                draw.text(string.format("%s (%.0f m)", p.who, dist), sp.x + 14, sp.y - 8, c)
            end
        end
    end
    pcall(pings.finder.draw, now)
    pcall(CFG.mprobe.draw, now)
end

----------------------------------------------------------------------------------------------
-- Probe: lists a type's methods (with signatures) so the adapter can be extended
----------------------------------------------------------------------------------------------
local PROBE_CANDIDATES = {
    "app.GameManager", "app.SaveDataManager", "app.ItemManager",
    "app.Inventory", "app.Item", "app.ItemData", "app.SupplyBoxData",
    "app.EnemyManager", "app.EventManager", "app.MapManager", "app.GimmickManager",
}
local PROBE_KEYWORDS = { "difficult", "newgame", "new_game", "gamemode", "rank", "startgame", "gamestart" }
local NEW_GAME_METHODS = {
    { "app.GameManager", "newGameRequest" }, { "app.GameManager", "newGameInitParam" },
    { "app.GameManager", "newGameRequest_Chapter7" }, { "app.GameManager", "setGamemode" },
    { "app.GameManager", "set_gameDifficulty" }, { "app.GameManager", "get_gameDifficulty" },
    { "app.SaveDataManager", "newGameInit" },
}

local function probe_add(text)
    probe.lines[#probe.lines + 1] = text
    say(text)
end

local function method_signature(m)
    local ok, text = pcall(function()
        local params = {}
        for i, t in ipairs(m:get_param_types() or {}) do params[i] = t:get_full_name() end
        local ret = m:get_return_type()
        return "(" .. table.concat(params, ", ") .. ") -> " .. (ret and ret:get_full_name() or "?")
    end)
    return ok and text or ""
end

local function probe_type(name, list_all, keywords, limit)
    keywords = keywords or PROBE_KEYWORDS
    limit = limit or 80
    local ok, err = pcall(function()
        local td = sdk.find_type_definition(name)
        if not td then
            probe_add(name .. ": not found")
            return
        end
        probe_add(name .. ": found")
        local shown = 0
        for _, m in ipairs(td:get_methods() or {}) do
            local mname = m:get_name()
            local match = list_all
            if not match then
                local low = mname:lower()
                for _, kw in ipairs(keywords) do
                    if low:find(kw, 1, true) then
                        match = true
                        break
                    end
                end
            end
            if match and shown < limit then
                shown = shown + 1
                probe_add("    " .. mname .. method_signature(m))
            end
        end
        if shown == 0 then probe_add("    (no methods matched)") end
    end)
    if not ok then probe_add(name .. ": error " .. tostring(err)) end
end

local function probe_signatures()
    for _, entry in ipairs(NEW_GAME_METHODS) do
        local ok, err = pcall(function()
            local td = sdk.find_type_definition(entry[1])
            local m = td and td:get_method(entry[2])
            probe_add(entry[1] .. "." .. entry[2] .. (m and method_signature(m) or ": not found"))
        end)
        if not ok then probe_add(entry[2] .. ": error " .. tostring(err)) end
    end
end

----------------------------------------------------------------------------------------------
-- Tracer: hooks every method of a type (rate limited) and logs the calls with their arguments, so you can
-- see which methods fire when you pick up or drop an item. Hooks last until the scripts are reloaded.
----------------------------------------------------------------------------------------------
local function field_label(name)
    return (name:gsub("^<(.-)>k__BackingField$", "%1"))
end

-- Methods the 2026-11 item trace showed firing thousands of times a second (every frame, per item).
local TRACE_SKIP = {
    set_weapon = true, set_ItemSlotManager = true, set_ItemData = true, itemMegusuriDisp = true,
    getTotalStackNum = true, getItemDataId = true, hasWeaponInQuickslot = true, isDisplayShotGun = true,
    set_ItemBoxData = true,
    -- called every frame (a debug file measured 16000 and 284 calls a second): hooking them only costs frames
    set_eventSetting = true, set_eventRoot = true, findItemDataInternal = true,
    findCombineDataByResultItem = true, findCombineDataBySourceItem = true,
    -- measured in the 9.5 door trace: 13066, 3219, 1250, 588 and 355 calls a second. Hooking them only costs frames.
    set_timelineKickers = true, waitFsmExecuteCheck = true, isMotionJack = true, existNear = true, notifyInKnockArea = true,
}
-- Called hundreds of times a second with the same arguments (the UI flags CanOpenMap, CanOpenInventory ... are set every
-- frame): a call is only logged when its arguments differ from the call before.
local TRACE_CHANGED = { setFsmGlobalBoolValue = true, setFsmGlobalIntValue = true }
-- Object arguments of these types are written out field by field (numbers, flags, text only), so a traced
-- damage call shows how much damage, from which weapon, to which part.
local TRACE_EXPAND = {
    ["app.DamageController.DamageRecord"] = true,
    ["app.Collision.HitController.DamageInfo"] = true,
    ["app.HealthInfo"] = true,
}

local function compact_fields(o, limit)
    local parts = {}
    pcall(function()
        local t = o:get_type_definition()
        while t and #parts < limit do
            local tn = t:get_full_name()
            if tn:find("^System%.") or tn:find("^via%.Component") then break end
            for _, f in ipairs(t:get_fields() or {}) do
                if #parts >= limit then break end
                if not f:is_static() then
                    local ok, v = pcall(function() return o:get_field(f:get_name()) end)
                    if ok and (type(v) == "number" or type(v) == "boolean") then
                        parts[#parts + 1] = field_label(f:get_name()) .. "=" .. tostring(v)
                    elseif ok and type(v) == "string" then
                        parts[#parts + 1] = field_label(f:get_name()) .. "=\"" .. v:sub(1, 30) .. "\""
                    end
                end
            end
            t = t:get_parent_type()
        end
    end)
    return table.concat(parts, " ")
end

local tracer = {
    enabled = true,
    type_name = "app.ItemManager",
    filter = "",
    include_getters = false,
    hooked = {},
    hook_count = 0,
    rate = {},
    lines = {},
}

local function tracer_add(text)
    tracer.lines[#tracer.lines + 1] = text
    while #tracer.lines > 60 do table.remove(tracer.lines, 1) end
    say("[trace] " .. text)
end

-- Breadcrumb for crashes. The debug file is only written every two seconds, so the last traced calls before a crash are
-- never in it. This tiny file is rewritten around every traced call instead:
--   "hooking X"  the game stopped while the hook on X was being installed (the hook is the suspect)
--   "enter X"    the game stopped while this script was reading X's arguments (the script is the suspect)
--   "done X"     the game stopped after the script had finished with X (the game itself, or a call that is not traced)
-- The next session reads it back and says what it found (tracer.report_previous).
tracer.session = os.time()
tracer.crumb_t, tracer.crumb_n = 0, 0
function tracer.crumb(stage, key)
    local now = os.clock()
    if now - tracer.crumb_t >= 1 then tracer.crumb_t, tracer.crumb_n = now, 0 end
    tracer.crumb_n = tracer.crumb_n + 1
    -- a burst (a chapter loading): at most 400 writes a second. Only the per-call "enter" / "done" crumbs are held back: a
    -- "clean" or "hooking" written in a burst used to be dropped, and the file then blamed a hook that had long been installed.
    if tracer.crumb_n > 400 and (stage == "enter" or stage == "done") then return end
    tracer.last_stage = stage
    pcall(json.dump_file, FILES.path("lastcall"), { stage = stage, call = key, clock = now, time = os.time(), session = tracer.session })
end

-- (10.18) a crumb for a call that is made again and again (the story flow, the targets): written only when no other module's marker is waiting for its "clean" (the file holds one
-- crumb, so this one would overwrite it). Returns true when it was written; the caller then writes the "clean" itself.
function tracer.crumb_idle(stage, key)
    if tracer.last_stage ~= nil and tracer.last_stage ~= "clean" then return false end
    tracer.crumb(stage, key)
    return true
end

function tracer.report_previous()
    local d = FILES.read("lastcall")
    if type(d) ~= "table" or d.session == tracer.session or type(d.call) ~= "string" then return end
    local age = type(d.time) == "number" and math.max(0, os.time() - d.time) or nil
    local when = age and string.format(" (%d min ago)", math.floor(age / 60)) or ""
    local text
    if d.stage == "hooking" then
        text = "The last session ended while the trace was installing its hook on " .. d.call .. when .. ". If the game crashed, that hook is the suspect."
    elseif d.stage == "enter" then
        text = "The last session ended while the trace was reading the arguments of " .. d.call .. when .. ". If the game crashed, that call is the suspect."
    elseif d.stage == "done" then
        text = "The last traced call of the last session was " .. d.call .. when .. " and it had finished. If the game crashed, it was in the game or in a call that is not traced."
    elseif d.stage == "recorder" then
        text = "The last session ended while the recorder (button 11) was at: " .. d.call .. when .. ". If the game crashed, that is the suspect: tell me."
    elseif d.stage == "give" then
        text = "The last session ended while the script was handling an item: " .. d.call .. when .. ". If the game crashed, that call is the suspect: tell me."
    elseif d.stage == "story" then
        text = "The last session ended while the script was handling a story event: " .. d.call .. when .. ". If the game crashed, that is the suspect: tell me."
    elseif d.stage == "force" then
        tracer.force_id = d.call:match("^forcing ([%w_]+)")
        text = "The last session ended while the script was playing a cutscene here for the other player: " .. d.call .. when .. ". If the game crashed, that is the suspect: tell me. That cutscene is on the not-played list for this session."
    elseif d.stage == "loader" then
        text = "The last session ended while the script was loading a model file by its path: " .. d.call .. when .. ". If the game crashed, that is the suspect: tell me. Loading by path is switched off this time (tick it again in 'Who I am' to try again)."
        tracer.loader_suspect = true
    elseif d.stage == "puppet" then
        text = "The last session ended while the script was making an enemy model: " .. d.call .. when .. ". If the game crashed, that is the suspect: tell me. Enemy models are switched off this time (tick the box again to try)."
        tracer.puppet_suspect = true
    elseif d.stage == "journal" or d.stage == "scan" then
        text = "The last session ended while the item journal was " .. (d.stage == "scan" and "looking at the objects near a pickup: " or "hooking: ") .. d.call .. when .. ". If the game crashed, that is the suspect: tell me. The journal is switched off this time (tick it again to try)."
        tracer.journal_suspect = true
    elseif d.stage == "idata" then
        text = "The last session ended while the script was reading the item data for the debug file: " .. d.call .. when .. ". If the game crashed, that is the suspect: tell me. The item data is switched off this time."
        tracer.idata_suspect = true
    elseif d.stage == "face" then
        text = "The last session ended while the script was switching the layers of Mia's head: " .. d.call .. when .. ". If the game crashed, that is the suspect: tell me. Switching the layers is off this time (tick the box again to try)."
        tracer.face_suspect = true
    elseif d.stage == "verify" then
        text = "The last session ended while the script was checking a model it made (the every-5-seconds check): " .. d.call .. when .. ". If the game crashed, that is the suspect: tell me. The check is switched off this time (tick its box again to try)."
        tracer.verify_suspect = true
    elseif d.stage == "motion" then
        text = "The last session ended while the script was reading the animation lists (.motlist) of an object: " .. d.call .. when .. ". If the game crashed, that is the suspect: tell me. (The Enemy animations probe only reads; it does nothing until its button or F3 is pressed.)"
        tracer.motion_suspect = true
    elseif d.stage == "mbank" then
        text = "The last session ended while the motion bank detector was reading Ethan's own animation: " .. d.call .. when .. ". If the game crashed, that is the suspect: tell me. The detector is switched off this time (it only reads); the other player's body keeps using the pose flags and the recorded clips."
        tracer.mbank_suspect = true
    elseif d.stage == "gmot" then
        text = "The last session ended while the script was setting up or playing the game's own animations on the other player's body: " .. d.call .. when .. ". If the game crashed, that is the suspect: tell me. The game's animations are switched off this time (the recorded clips play); tick the box in 'Other player's body' to try again."
        tracer.gmot_suspect = true
    elseif d.stage == "jack" then
        text = "The last session ended while the script was sharing a scripted move (the van door, a ladder ...) or the animation banks the game adds to a body: " .. d.call .. when .. ". If the game crashed, that is the suspect: tell me. Sharing them is switched off this time; the rest of the animation sync is not."
        tracer.jack_suspect = true
    elseif d.stage == "molded" then
        text = "The last session ended while the script was moving a copy of the host's Molded in this game (or bringing one out, or letting one go): " .. d.call .. when .. ". If the game crashed, that is the suspect: tell me. The Molded copies are switched off this time (tick the box in the enemy section to try again); the ghosts and the shooting are not."
        tracer.molded_suspect = true
    elseif d.stage == "pool" then
        text = "The last session ended while the script was writing a health number into its own copy of the host's enemy (or hitting it): " .. d.call .. when .. ". If the game crashed, that is the suspect: tell me. The health pool is switched off this time (tick its box to try again)."
        tracer.pool_suspect = true
    elseif d.stage == "wmesh" then
        text = "The last session ended while the script was putting the other player's weapon model on their body: " .. d.call .. when .. ". If the game crashed, that is the suspect: tell me. The weapon model is switched off this time (tick the box in 'Other player's body' to try again)."
        tracer.wmesh_suspect = true
    elseif d.stage == "revive" then
        text = "The last session ended while the script was finishing an F8 revive: " .. d.call .. when .. ". If the game crashed, that is the suspect: tell me."
    elseif d.stage == "flow" then
        text = "The last session ended while the script was reading or stepping the story flow (the game's numbered story steps): " .. d.call .. when .. ". If the game crashed, that is the suspect: tell me. The story-point probe and the matching are switched off this time (tick their boxes in 'Story points' to try again)."
        tracer.flow_suspect = true
    elseif d.stage == "own" then
        text = "The last session ended while the script was handing an enemy to a player (or taking it back): " .. d.call .. when .. ". If the game crashed, that is the suspect: tell me. The enemy hand-over is switched off this time (tick its box in the enemy section to try again)."
        tracer.own_suspect = true
    elseif d.stage == "car" then
        text = "The last session ended while the script was working on the garage car (getting the other player in, putting the car where theirs is, breaking a window, a hit from the car): " .. d.call .. when .. ". If the game crashed, that is the suspect: tell me. The garage car sync is switched off until its box is ticked again."
        tracer.car_suspect = true
    elseif d.stage == "kill" then
        text = "The last session ended while the script was killing an enemy for the other player (or finishing its own copy of one): " .. d.call .. when .. ". If the game crashed, that is the suspect: tell me. Kill sharing is switched off this time (tick its box to try again)."
        tracer.kill_suspect = true
    elseif d.stage == "limb" then
        text = "The last session ended while the script was reading or applying the lost parts (head, arms, legs) of a Molded: " .. d.call .. when .. ". If the game crashed, that is the suspect: tell me. Limb sharing is switched off this time (tick its box to try again)."
        tracer.limb_suspect = true
    elseif d.stage == "tgt" then
        text = "The last session ended while the script was reading who an enemy is targeting: " .. d.call .. when .. ". If the game crashed, that is the suspect: tell me. The targeting log is switched off this time (tick its box to try again)."
        tracer.tgt_suspect = true
    else
        return -- "clean": the scripts were reset normally
    end
    tracer.previous = text
    say("previous session: " .. text)
end

-- Reference types are read as objects; value types (numbers, enums, structs) are only shown as raw numbers,
-- because treating a plain number as an object pointer could crash the game.
local function describe_arg(pt, args, idx)
    local ok, text = pcall(function()
        local n = pt.name
        -- args[1] is the thread, args[2] the object, args[3] and args[4] the first two parameters (a float uses up its slot).
        -- Anything after that is not in a register: it reads as garbage (a 1962800054277 where an EaseType should be), and
        -- treating garbage as an object pointer can crash the game, so a late object is never opened.
        local late = idx > 4
        if pt.ref and late then return "<" .. n .. ": not readable>" end
        if pt.ref then
            local o = sdk.to_managed_object(args[idx])
            if o == nil then return "null" end
            if n == "System.String" then
                local ok2, str = pcall(function() return o:call("ToString()") end)
                if ok2 and type(str) == "string" then return "\"" .. str .. "\"" end
                return "<string>"
            end
            if n == "via.GameObject" then
                local ok3, nm = pcall(function() return o:call("get_Name") end)
                if ok3 then return "GameObject(" .. tostring(nm) .. ")" end
            end
            if TRACE_EXPAND[n] then return "<" .. n .. " " .. compact_fields(o, 16) .. ">" end
            return "<" .. n .. ">"
        end
        if n == "System.Boolean" then return tostring(sdk.to_int64(args[idx]) % 256 ~= 0) .. (late and "?" or "") end
        -- floats travel in a floating-point register, not in args: reading them gave garbage (3e27) in the 2026-11 trace
        if n == "System.Single" then return "<float: can't be read in a hook>" end
        local v = sdk.to_int64(args[idx])
        if n == "System.Int32" or n:find("^app%.") then
            v = v % 4294967296
            if v >= 2147483648 then v = v - 4294967296 end
        end
        return tostring(v) .. (late and "?" or "") -- a "?" marks a value from past the registers: not trustworthy
    end)
    return ok and text or ("<" .. tostring(pt.name) .. ">") -- can't read it: show its type instead
end

local function trace_method(type_name, m)
    local mname = m:get_name()
    local ptypes, names = {}, {}
    pcall(function()
        for i, t in ipairs(m:get_param_types() or {}) do
            local okv, isval = pcall(function() return t:is_value_type() end)
            ptypes[i] = { name = t:get_full_name(), ref = okv and isval == false }
            names[i] = ptypes[i].name
        end
    end)
    local is_static = false
    pcall(function() is_static = m:is_static() == true end)
    local key = type_name .. "." .. mname .. "(" .. table.concat(names, ",") .. ")"
    if tracer.hooked[key] then return false, "already" end
    tracer.hooked[key] = true

    local CALL_ORIGINAL = sdk.PreHookResult and sdk.PreHookResult.CALL_ORIGINAL
    local changed_only = TRACE_CHANGED[mname] == true
    local function render(args)
        local parts = {}
        for i, pt in ipairs(ptypes) do parts[i] = describe_arg(pt, args, i + (is_static and 1 or 2)) end
        return parts
    end
    sdk.hook(m, function(args)
        pcall(function()
            if not tracer.enabled then return end
            local now = os.clock()
            local e = tracer.rate[key] or { t = 0, n = 0, dropped = 0, muted = false }
            tracer.rate[key] = e
            if e.muted then return end
            local parts
            if changed_only then -- read the arguments first: only a call that differs from the one before is counted
                if not e.crumbed then
                    e.crumbed = true
                    tracer.crumb("enter", key)
                end
                parts = render(args)
                local shown = table.concat(parts, ", ")
                if shown == e.last_shown then return end
                e.last_shown = shown
            end
            if now - e.t > 1 then
                if e.dropped > 200 then -- fires every frame: say so once and stop logging it
                    e.muted = true
                    tracer_add(type_name .. "." .. mname .. ": fires " .. e.dropped .. "+ times a second, muted")
                    return
                elseif e.dropped > 0 then
                    tracer_add(type_name .. "." .. mname .. ": " .. e.dropped .. " more calls in the last second")
                end
                e.t, e.n, e.dropped = now, 0, 0
            end
            e.n = e.n + 1
            if e.n > 3 then
                e.dropped = e.dropped + 1
                return
            end
            tracer.crumb("enter", key)
            if not e.sig_logged then -- the full signature, once, so unreadable arguments can be identified
                e.sig_logged = true
                tracer_add("signature: " .. key)
            end
            parts = parts or render(args)
            -- which GameObject the call is on (for components: "[on Em3100]"), so a damage call says whom it hit
            local owner = ""
            if not is_static then
                pcall(function()
                    local so = sdk.to_managed_object(args[2])
                    local go = so and so:call("get_GameObject")
                    local nm = go and go:call("get_Name")
                    if type(nm) == "string" then owner = "  [on " .. nm .. "]" end
                end)
                -- plain objects have no GameObject: the health module can still say "this is the player's HealthInfo"
                if owner == "" and tracer.owner_hint then
                    local okh, hint = pcall(tracer.owner_hint, args)
                    if okh and type(hint) == "string" then owner = hint end
                end
            end
            tracer_add(string.format("%s.%s(%s)%s", type_name, mname, table.concat(parts, ", "), owner))
            tracer.crumb("done", key)
        end)
        return CALL_ORIGINAL
    end, function(retval) return retval end)
    return true
end

local function trace_type(type_name, filter, include_getters)
    local ok, err = pcall(function()
        local td = sdk.find_type_definition(type_name)
        if not td then
            tracer_add(type_name .. ": not found")
            return
        end
        local added, skipped, already = 0, 0, 0
        -- filter: one piece of text, or a list of words (a method matches if its name contains any of them)
        -- a word starting with "=" is an exact method name (any other word matches part of a name)
        local words, exact, has_exact = {}, {}, false
        if type(filter) == "table" then
            for _, w in ipairs(filter) do
                if w:sub(1, 1) == "=" then
                    exact[w:sub(2):lower()] = true
                    has_exact = true
                else
                    words[#words + 1] = w:lower()
                end
            end
        elseif filter and filter ~= "" then
            words[1] = filter:lower()
        end
        for _, m in ipairs(td:get_methods() or {}) do
            local name = m:get_name()
            local low = name:lower()
            local wanted = #words == 0 and not has_exact
            if exact[low] then wanted = true end
            for _, w in ipairs(words) do
                if low:find(w, 1, true) then wanted = true break end
            end
            local skip = low:find("update", 1, true) ~= nil or name == ".ctor" or name == ".cctor" or name == "doAwake"
                or low == "doondestroy" or low == "finalize" or low == "dispose" -- objects being taken apart: never touched
                or TRACE_SKIP[name] == true
                or (not include_getters and low:sub(1, 4) == "get_")
                or not wanted
            local hooked, why = false, nil
            if not skip and tracer.hook_count < 600 then
                tracer.crumb("hooking", type_name .. "." .. name)
                hooked, why = trace_method(type_name, m)
            end
            if hooked then
                added = added + 1
                tracer.hook_count = tracer.hook_count + 1
            elseif why == "already" then
                already = already + 1
            else
                skipped = skipped + 1
            end
        end
        tracer_add(string.format("%s: tracing %d new methods (%d were already traced, %d skipped)", type_name, added, already, skipped))
    end)
    if not ok then tracer_add(type_name .. ": error " .. tostring(err)) end
end

----------------------------------------------------------------------------------------------
-- Avatar: clone an in-game model instead of drawing the skeleton (EXPERIMENTAL, unverified).
-- RE7 is first person, so a full-body Ethan may not even be loaded. The scanner shows what is.
----------------------------------------------------------------------------------------------
local function scene_object()
    return sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"),
        sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
end

-- Walks every GameObject in the current scene. visit(go, path) may return true to stop early.
local function each_gameobject(visit, max_nodes)
    local scene = scene_object()
    if not scene then return end
    local count = 0
    local function walk(xf, path, depth)
        while xf and count < max_nodes do
            count = count + 1
            local go = xf:call("get_GameObject")
            local okn, name = pcall(function() return go and go:call("get_Name") end)
            local p = path .. "/" .. tostring(okn and name or "?")
            if go and visit(go, p) then return true end
            if depth < 8 then
                local child = xf:call("get_Child")
                if child and walk(child, p, depth + 1) then return true end
            end
            xf = xf:call("get_Next")
        end
        return false
    end
    walk(scene:call("get_FirstTransform"), "", 0)
end

local function component_names(go)
    local names = {}
    local comps = go:call("get_Components")
    if comps then
        for _, c in ipairs(comps:get_elements()) do
            local td = c:get_type_definition()
            names[#names + 1] = td and td:get_full_name():gsub("^via%.", "") or "?"
        end
    end
    return names
end

----------------------------------------------------------------------------------------------
-- "Send me this": one-click collectors. Everything is saved to reframework/data/re7mp/debug.json.
----------------------------------------------------------------------------------------------
local COLLECT_TYPES = {
    "app.GameManager", "app.SaveDataManager", "app.Inventory", "app.Item", "app.ItemData", "app.ItemManager", "app.SupplyBoxData",
    "app.EnemyManager", "app.EventManager", "app.PlayerManager", "app.CharacterManager", "app.MapManager",
}

local function pinned(fn)
    dbg.pin = true
    local ok, err = pcall(fn)
    dbg.pin = false
    if not ok then say("collector error: " .. tostring(err)) end
end

local function collect_info()
    pinned(function()
        probe.lines = {}
        say("=== collect: new-game method signatures ===")
        probe_signatures()
        for _, n in ipairs(COLLECT_TYPES) do
            say("=== collect: " .. n .. " ===")
            probe_type(n, true, nil, 250)
        end
        say("=== collect: done ===")
    end)
end

-- Lists GameObjects that look like enemies (a component type containing "enemy" or starting with app.Em, or a
-- name like em1234), then every component type present in the scene with a count. The second list shows what
-- the game calls its characters even if the first guess misses.
local function scan_enemies()
    pinned(function()
        say("=== enemy scan ===")
        local found, seen = 0, 0
        local census = {}
        local ok, err = pcall(each_gameobject, function(go, path)
            seen = seen + 1
            local name_hit = path:lower():find("/em%d%d%d%d") ~= nil
            local okc, comps = pcall(component_names, go)
            local comp_hit = false
            if okc then
                for _, c in ipairs(comps) do
                    census[c] = (census[c] or 0) + 1
                    local low = c:lower()
                    if low:find("enemy", 1, true) or low:find("^app%.em") then comp_hit = true end
                end
            end
            if (name_hit or comp_hit) and found < 80 then
                found = found + 1
                local pos = ""
                pcall(function()
                    local p = go:call("get_Transform"):call("get_Position")
                    pos = string.format("  at %.1f, %.1f, %.1f", p.x, p.y, p.z)
                end)
                say(path .. "  [" .. (okc and table.concat(comps, ", ") or "?") .. "]" .. pos)
            end
        end, 20000)
        if not ok then say("enemy scan error: " .. tostring(err)) end
        say(string.format("=== enemy scan done: %d candidates among %d objects ===", found, seen))
        say("=== component types in the scene (name x count) ===")
        local names = {}
        for n in pairs(census) do names[#names + 1] = n end
        table.sort(names)
        for _, n in ipairs(names) do
            if n:find("^app%.") then say(n .. " x" .. census[n]) end
        end
        say("=== component census done ===")
    end)
end

----------------------------------------------------------------------------------------------
-- Item sync, version 1: an item one player picks up from the world disappears for the other player.
--
-- Based on the item trace: picking something up runs app.Inventory.addItem(app.Item, ...) on the item that
-- lies in the world, and the game then removes that item with app.Item.disableFromScene(). Crafting and
-- restoring an inventory also call addItem, but on items created under the player object "Pl0000", which
-- is how those are told apart from world pickups. The message carries the item's id, its object name and its
-- position; the other game finds the object with that name near that position and removes it the same way.
-- Not synced yet: items that come out of drawers/containers, ammo use, "both players get the item".
----------------------------------------------------------------------------------------------
-- Ethan is Pl0000 but Mia's chapters have Pl2000 (the first debug file lists both): any Pl followed by four digits is a player.
-- The early game (the car, the forest, the guest house) names the player "Pl0000_Chapter1": the 9.17 debug file lists
-- "[on Pl0000_Chapter1]" for the player's own components there, and the script found no player at all in those parts (the recorder,
-- the health and pose hooks and the item owner all depend on finding it). "Pl0000_Chapter" and a number is a player too.
local function is_player_name(n)
    if type(n) ~= "string" then return false end
    return n:match("^Pl%d%d%d%d$") ~= nil or n:match("^Pl%d%d%d%d_Chapter%d+$") ~= nil
end

local ITEM_MSG = 3
local items = {
    -- (9.44) ON, but only consumables and weapons are shared (safe_only, below). A pickup that vanishes from the other player's world, or is taken
    -- twice, could take a key item (the fuse, the bolt cutters) out of one game, which then can't be finished: those stay in each game.
    enabled = true,
    safe_only = true, cat_cache = {}, not_shared = 0, unreadable = 0, weapons_taken = 0,
    sent = 0, received = 0, removed = 0, missed = 0,
    suppress_until = 0,
    last = "No item events yet.",
    hooked = false,
    -- (9.32) The 9.31 file had no "you picked up" line at all, although items were picked up (a ShotgunBullet pickup, +4). The hook was on
    -- td:get_method("addItem"), and addItem has several overloads: the game's own pickup uses the 4-parameter one (the trace shows
    -- addItem(<app.Item>, <via.GameObject>, false?, <List>)), and the name alone can hand back another overload. So the hook is now on EVERY
    -- addItem overload, and every call it sees is written down (the ring: what the item was, what it hung under, what was done with it).
    mode = "take",          -- "take": a pickup vanishes on the other screen (the first one to pick it up gets it); "both": it stays, each of you can pick it up
    hooked_sigs = {}, calls = 0, by_overload = {}, ring = {}, RING_MAX = 40, errors = 0, duplicates = 0, kept = 0,
    last_addr = nil, last_call_at = -100, DUP_WINDOW = 0.3, DETAIL_FIRST = 8, last_error = nil, id_of = nil, drop_check = nil,
}

function items.push(rec)
    rec.t = math.floor(os.clock() * 100 + 0.5) / 100
    items.ring[#items.ring + 1] = rec
    if #items.ring > items.RING_MAX then table.remove(items.ring, 1) end
end

local function item_note(text)
    items.last = text
    say("item sync: " .. text)
end

-- Is this GameObject the player or one of its children (an inventory item rather than a world item)?
local function is_under_player(go)
    local node = go
    for _ = 1, 10 do
        if not node then return false end
        if is_player_name(node:call("get_Name")) then return true end
        local xf = node:call("get_Transform")
        local parent = xf and xf:call("get_Parent")
        node = parent and parent:call("get_GameObject") or nil
    end
    return false
end

-- (9.44) WHICH ITEMS MAY BE SHARED. The game's own record of an item (app.ItemData, reached through app.Item.get_ItemData or its field _ItemData)
-- has a Category (app.Item.ItemCategoryType in the enum dump: 0 other, 1 weapon, 2 shell (ammo), 3 drug (heals), 4 key item, 5 file, 6 map,
-- 7 material, 8 stack weapon, 9 usable key item, 10 discardable key item, 11 supply box). Only the consumables and the weapons are shared; a
-- key item, a file, a map or an item whose category can't be read stays in each game (fail closed). A weapon always goes to whoever picks it up
-- first, even in 'both' mode, so one of you can have the double barrel and the other the second shotgun.
items.CATEGORY = { [0] = "other item", "weapon", "ammo", "heal", "key item", "file", "map", "material", "stack weapon", "usable key item", "discardable key item", "supply box" }
items.SHARE = { [1] = true, [2] = true, [3] = true, [7] = true, [8] = true }
items.WEAPONS = { [1] = true, [8] = true }

-- The category number of an app.Item (the answer is remembered per item id), or nil with the reason.
function items.category_of(item, id)
    if id ~= nil and items.cat_cache[id] ~= nil then return items.cat_cache[id] end
    local data, why
    local ok, d = pcall(function() return item:call("get_ItemData") end)
    if ok and d ~= nil and type(d) ~= "number" and type(d) ~= "string" then data = d end
    if data == nil then
        local okf, f = pcall(function() return item:get_field("_ItemData") end)
        if okf and f ~= nil and type(f) ~= "number" and type(f) ~= "string" then data = f else why = "the item has no readable record (get_ItemData / _ItemData)" end
    end
    if data == nil then return nil, why end
    local okc, v = pcall(function() return data:get_field("Category") end)
    local n = okc and tonumber(v) or nil
    if n == nil or n ~= n or n < 0 or n > 64 then return nil, "the record has no readable Category" end
    n = math.floor(n)
    if id ~= nil then items.cat_cache[id] = n end
    return n
end

function items.category_name(n) return n and (items.CATEGORY[n] or ("category " .. tostring(n))) or "unknown" end

-- (10.12) "EntranceHallKey can be shared since only one person needs it to open the door for both": the door the key opens is opened in both games (CFG.door), so
-- the key is taken from the other game when one of you picks it up, like a herb. Only the keys listed here; every other key item stays in each game.
items.SHARE_NAMES = { entrancehallkey = true }
function items.name_shared(id)
    if type(id) ~= "string" then return false end
    return items.SHARE_NAMES[(id:lower():gsub("[^%w]", ""))] == true
end

-- May this item be shared? (true / false, and the words for the log)
function items.may_share(item, id)
    local n, why = items.category_of(item, id)
    if items.safe_only and items.name_shared(id) then return true, n, "a key that opens a door for both of you" end
    if not items.safe_only then return true, n, "all kinds are shared (the box is unticked)" end
    if n == nil then return false, nil, why or "its category can't be read" end
    if items.SHARE[n] then return true, n, items.category_name(n) end
    return false, n, items.category_name(n)
end

-- Runs just before the game adds an item to the inventory (through any of addItem's overloads: `which` says which one).
local function on_item_added(args, which)
    items.calls = items.calls + 1
    which = which or "?"
    items.by_overload[which] = (items.by_overload[which] or 0) + 1
    if not items.enabled then return end
    local now = os.clock()
    local rec = { via = which }
    local item = sdk.to_managed_object(args[3])
    if not item then
        rec.action = "not sent: no item in the call"
        items.push(rec)
        return
    end
    -- one pickup that goes through two overloads (one calling the other) is one pickup
    local addr
    pcall(function() addr = item:get_address() end)
    if addr ~= nil and addr == items.last_addr and now - items.last_call_at < items.DUP_WINDOW then
        items.duplicates = items.duplicates + 1
        return
    end
    items.last_addr, items.last_call_at = addr, now
    local go = item:call("get_GameObject")
    rec.object = go and tostring(go:call("get_Name")) or nil
    local id = items.id_of and items.id_of(item) or nil
    if not id and (items.callable == nil or items.callable(item, "getItemDataId")) then
        local okd, v = pcall(function() return tostring(item:call("getItemDataId")) end)
        id = okd and v or nil
    end
    rec.id = id
    pcall(function() rec.state = item:call("getItemState") end)
    pcall(function() rec.stack = item:call("getStackNum") end)
    if not go then
        rec.action = "not sent: the item has no object"
        items.push(rec)
        return
    end
    pcall(function() -- (what the pickup is made of: for the first few only)
        if #items.ring < items.DETAIL_FIRST then rec.components = component_names(go) end
    end)
    local okp, under = pcall(is_under_player, go)
    rec.under_player = okp and under or nil
    local okx, p = pcall(function() return go:call("get_Transform"):call("get_Position") end)
    if okx and p then rec.at = { math.floor(p.x * 10 + 0.5) / 10, math.floor(p.y * 10 + 0.5) / 10, math.floor(p.z * 10 + 0.5) / 10 } end
    if items.drop_check then -- (9.32) is this an item the script itself put on the ground? (then the game's own pickup works on it)
        local okc, hit = pcall(items.drop_check, rec.object, okx and p or nil)
        if okc and hit then rec.script_drop = hit end
    end
    if now < items.suppress_until then
        rec.action = "not sent: the script itself was adding an item just now"
        items.push(rec)
        return
    end
    if rec.under_player then
        rec.action = "not sent: the item sits under the player (crafting, or the inventory being restored)"
        items.push(rec)
        return
    end
    if not (id and rec.object and p) or tostring(id):find("|", 1, true) or rec.object:find("|", 1, true) then
        rec.action = "not sent: the item's name or place can't be read"
        items.push(rec)
        return
    end
    local share, cat, catwhy = items.may_share(item, id)
    rec.category = cat
    if not share then -- (9.44) a key item, a file, a map or an unreadable category stays in each game
        if cat == nil then items.unreadable = items.unreadable + 1 else items.not_shared = items.not_shared + 1 end
        rec.action = "not sent: " .. tostring(catwhy) .. (cat ~= nil and " (not shared: it stays in each game)" or " (nothing is shared that can't be classified)")
        items.push(rec)
        item_note(string.format("you picked up %s: %s, so it is not shared", id, tostring(catwhy)))
        return
    end
    net_send(ITEM_MSG, string.format("%s|%s|%.2f|%.2f|%.2f", id, rec.object, p.x, p.y, p.z))
    items.sent = items.sent + 1
    rec.action = "sent"
    items.push(rec)
    item_note(string.format("you picked up %s (%s) at %.1f, %.1f, %.1f", id, rec.object, p.x, p.y, p.z))
end

-- (9.32) The object called `name` nearest to (x, y, z) within `radius` metres, found by walking the scene. No pointer is kept between frames
-- (a stale one can crash the game), so whatever looks at an object later finds it again this way. Returns the object and its distance, or nil and why.
function items.find_near(name, x, y, z, radius)
    if not (name and x and y and z) then return nil, "no name or place to look for" end
    local best, best_d2
    local ok, err = pcall(each_gameobject, function(go)
        local okn, n = pcall(function() return go:call("get_Name") end)
        if not (okn and n == name) then return end
        local okp, p = pcall(function() return go:call("get_Transform"):call("get_Position") end)
        if not (okp and p) then return end
        local d2 = (p.x - x) ^ 2 + (p.y - y) ^ 2 + (p.z - z) ^ 2
        if d2 < radius ^ 2 and (best_d2 == nil or d2 < best_d2) then best, best_d2 = go, d2 end
    end, 30000)
    if not ok then return nil, "the walk of the scene failed: " .. tostring(err):sub(1, 60) end
    if not best then return nil, "not found" end
    return best, math.sqrt(best_d2)
end

local function remove_world_item(id, name, x, y, z)
    local best, best_d2
    local ok, err = pcall(each_gameobject, function(go)
        local okn, n = pcall(function() return go:call("get_Name") end)
        if not (okn and n == name) then return end
        local okp, p = pcall(function() return go:call("get_Transform"):call("get_Position") end)
        if not (okp and p) then return end
        local d2 = (p.x - x) ^ 2 + (p.y - y) ^ 2 + (p.z - z) ^ 2
        if d2 < 0.75 ^ 2 and (best_d2 == nil or d2 < best_d2) then
            best, best_d2 = go, d2
            if d2 < 0.05 ^ 2 then return true end -- an exact match: stop searching
        end
    end, 30000)
    if not ok then
        item_note("search failed: " .. tostring(err))
        return
    end
    if not best then
        items.missed = items.missed + 1
        item_note(string.format("%s picked up %s (%s) but I can't find it near %.1f, %.1f, %.1f",
            state.remote_name or CFG.DEFAULT_NAME, id, name, x, y, z))
        return
    end
    -- (9.44) what is lying here is checked again (the other player's script may be older and send everything): a key item stays, and with
    -- 'both players get it' only a weapon is taken away (so each of you can have a different weapon of a kind)
    local okc, lying = pcall(function() return best:call("getComponent(System.Type)", sdk.typeof("app.Item")) end)
    local lcat, lwhy
    if okc and lying ~= nil then lcat, lwhy = items.category_of(lying, id) end
    if items.safe_only and not (lcat ~= nil and items.SHARE[lcat]) and not items.name_shared(id) then
        if lcat == nil then items.unreadable = items.unreadable + 1 else items.not_shared = items.not_shared + 1 end
        item_note(string.format("%s took %s (%s): it stays here, it is not shared", state.remote_name or CFG.DEFAULT_NAME, id, lcat ~= nil and items.category_name(lcat) or tostring(lwhy or "category unknown")))
        return
    end
    if items.mode == "both" and not (lcat ~= nil and items.WEAPONS[lcat]) and not items.name_shared(id) then
        items.kept = items.kept + 1
        item_note(string.format("%s took %s: it stays here too, so you can take it as well (both players get it)", state.remote_name or CFG.DEFAULT_NAME, id))
        return
    end
    if lcat ~= nil and items.WEAPONS[lcat] then items.weapons_taken = items.weapons_taken + 1 end
    items.suppress_until = os.clock() + 1
    local removed, how = pcall(function()
        local comp = lying
        if not comp then error("no app.Item component") end
        comp:call("disableFromScene") -- what the game itself calls on a picked-up world item
    end), "disableFromScene"
    if not removed then
        how = "destroy"
        removed = pcall(function() best:call("destroy", best) end)
    end
    if removed then
        items.removed = items.removed + 1
        item_note(string.format("%s took %s: removed it here (%s)", state.remote_name or CFG.DEFAULT_NAME, id, how))
    else
        items.missed = items.missed + 1
        item_note(string.format("%s took %s: found it but could not remove it", state.remote_name or CFG.DEFAULT_NAME, id))
    end
end

net_on(ITEM_MSG, function(payload)
    local id, name, x, y, z = payload:match("^([^|]*)|([^|]*)|(-?[%d%.]+)|(-?[%d%.]+)|(-?[%d%.]+)$")
    x, y, z = tonumber(x), tonumber(y), tonumber(z)
    if not (id and name and x and y and z) then return end
    items.received = items.received + 1
    if not items.enabled then return end
    if items.mode == "both" and not items.safe_only then
        -- (9.32) both players get the item: it stays on my screen, and I pick it up myself with the game's own pickup
        items.kept = items.kept + 1
        item_note(string.format("%s took %s: it stays here too, so you can take it as well (both players get it)", state.remote_name or CFG.DEFAULT_NAME, id))
        return
    end
    remove_world_item(id, name, x, y, z)
end)

local function install_item_hooks()
    local td = sdk.find_type_definition("app.Inventory")
    if not td then
        say("item sync: app.Inventory not found, item sync is off")
        return false
    end
    local CALL_ORIGINAL = sdk.PreHookResult and sdk.PreHookResult.CALL_ORIGINAL
    local function hook_one(m, label)
        sdk.hook(m, function(args)
            local ok, err = pcall(on_item_added, args, label)
            if not ok then
                items.errors = items.errors + 1
                items.last_error = tostring(err):sub(1, 120)
                if items.errors <= 3 then say("item sync hook error: " .. items.last_error) end
            end
            return CALL_ORIGINAL
        end, function(retval) return retval end)
        items.hooked_sigs[#items.hooked_sigs + 1] = label
    end
    -- every overload of addItem (the tracer hooks them all too, and it is how the 4-parameter one was seen)
    local list = {}
    pcall(function()
        for _, m in ipairs(td:get_methods() or {}) do
            if m:get_name() == "addItem" then list[#list + 1] = m end
        end
    end)
    for _, m in ipairs(list) do
        local names = {}
        pcall(function()
            for _, t in ipairs(m:get_param_types() or {}) do
                names[#names + 1] = (t:get_full_name():gsub("^System%.Collections%.Generic%.", ""):gsub("^System%.", ""))
            end
        end)
        hook_one(m, "addItem(" .. table.concat(names, ", ") .. ")")
    end
    if #items.hooked_sigs == 0 then
        local m = td:get_method("addItem")
        if m then hook_one(m, "addItem") end
    end
    if #items.hooked_sigs == 0 then
        say("item sync: app.Inventory.addItem not found, item sync is off")
        return false
    end
    return true
end

function items.report()
    return { on = items.enabled, mode = items.mode, hooked = items.hooked, hooked_overloads = items.hooked_sigs, calls_seen = items.calls,
        calls_by_overload = items.by_overload, same_call_twice_ignored = items.duplicates, hook_errors = items.errors, last_hook_error = items.last_error,
        sent = items.sent, received = items.received, removed_here = items.removed, kept_here_both_mode = items.kept, not_found_here = items.missed,
        only_consumables_and_weapons = items.safe_only, not_shared_key_items_and_the_like = items.not_shared, category_unreadable = items.unreadable,
        weapons_taken_for_the_other_player = items.weapons_taken, categories_seen = (function()
            local out = {}
            for id, n in pairs(items.cat_cache) do out[id] = items.category_name(n) end
            return out
        end)(), last = items.last, ring = items.ring }
end

----------------------------------------------------------------------------------------------
-- Finding the game's managers and calling it with strings.
-- RE7's managers are not always reachable as singletons, so the hooks below also remember the instances
-- they see. Everything here is wrapped in pcall by its callers: a failure is reported, never thrown.
----------------------------------------------------------------------------------------------
local mgr = { item_manager = nil, inventory = nil, player = nil, player_checked = 0 }

local function managed_string(s)
    local ok, ms = pcall(function() return sdk.create_managed_string(s) end)
    if ok and ms ~= nil then return ms end
    return s
end

-- obj:call(method, ...) where some arguments are Lua strings: tries plain strings first, then managed ones.
-- Returns true plus the result, or false plus the error text.
local function call_str(obj, method, ...)
    local n = select("#", ...)
    local args = { ... }
    local ok, res = pcall(function() return obj:call(method, table.unpack(args, 1, n)) end)
    if ok then return true, res end
    local conv = {}
    for i = 1, n do
        local a = args[i]
        conv[i] = type(a) == "string" and managed_string(a) or a
    end
    local ok2, res2 = pcall(function() return obj:call(method, table.unpack(conv, 1, n)) end)
    if ok2 then return true, res2 end
    return false, tostring(res2)
end

local function hook_method(type_name, method_name, pre, post)
    local td = sdk.find_type_definition(type_name)
    local m = td and td:get_method(method_name)
    if not m then
        say("hook: " .. type_name .. "." .. method_name .. " not found")
        return false
    end
    local CALL_ORIGINAL = sdk.PreHookResult and sdk.PreHookResult.CALL_ORIGINAL
    local SKIP_ORIGINAL = sdk.PreHookResult and sdk.PreHookResult.SKIP_ORIGINAL
    local errors = 0
    sdk.hook(m, function(args)
        local ok, err = pcall(pre, args)
        if not ok then
            errors = errors + 1
            if errors <= 3 then say("hook error in " .. method_name .. ": " .. tostring(err)) end -- (9.13: three times, not for ever)
        elseif err == "skip" and SKIP_ORIGINAL ~= nil then
            return SKIP_ORIGINAL -- (10.23) only the downed player's healing-item block (H.item_blocked) returns "skip"; every other callback returns nothing
        end
        return CALL_ORIGINAL
    end, function(retval)
        if post then
            local ok, err = pcall(post, retval)
            if not ok then
                errors = errors + 1
                if errors <= 3 then say("hook error after " .. method_name .. ": " .. tostring(err)) end
            end
        end
        return retval
    end)
    return true
end

local function find_named_object(name, max_nodes)
    local found
    pcall(each_gameobject, function(go)
        local ok, n = pcall(function() return go:call("get_Name") end)
        if ok and n == name then
            found = go
            return true
        end
    end, max_nodes)
    return found
end

-- WHICH copy of the item manager? In the 0.7 and 0.8 files the one sdk.get_managed_singleton gives was an empty shell:
-- findItemData("Herb"), get_ItemDataIDNames and every create call answered nil, so no item could be created or dropped. The
-- game's real manager sits on the object "SystemObject" (the older traces show findItemDataInternal "[on SystemObject]"). So the
-- copies are collected (components in the scene, the one on SystemObject, the singleton) and the first that knows an item wins.
function mgr.im_knows(c)
    for _, id in ipairs({ "Herb", "HandgunBullet", "Knife" }) do
        local ok, d = pcall(function() return c:call("findItemData", id) end)
        if ok and d ~= nil then return true end
    end
    return false
end

function mgr.im_candidates(walk)
    local out = {}
    local function add(how, obj)
        if obj ~= nil then out[#out + 1] = { how = how, obj = obj } end
    end
    local scene = scene_object()
    if scene then
        pcall(function()
            local arr = scene:call("findComponents(System.Type)", sdk.typeof("app.ItemManager"))
            for i, c in ipairs(arr:get_elements() or {}) do
                if i > 4 then break end
                add("a component found in the scene", c)
            end
        end)
    end
    if walk and #out == 0 then
        pcall(function()
            local go = find_named_object("SystemObject", 4000)
            if go then add("the component on SystemObject", go:call("getComponent(System.Type)", sdk.typeof("app.ItemManager"))) end
        end)
    end
    local ok, s = pcall(sdk.get_managed_singleton, "app.ItemManager")
    if ok then add("the managed singleton", s) end
    -- The game's own copy is a candidate only if it knows items: in the 9.13 file it did not (findItemData -> nil), it
    -- replaced the good copy at the next craft, and every creation after that failed.
    if mgr.captured_im and mgr.im_knows(mgr.captured_im) then add("the one the game's own createItemInstance call used", mgr.captured_im) end
    return out
end

local function item_manager()
    local now = os.clock()
    if mgr.item_manager and mgr.item_manager_ok then return mgr.item_manager end
    if mgr.item_manager and now < (mgr.item_manager_next or 0) then return mgr.item_manager end
    -- (until one that knows items turns up the search repeats, further and further apart: a walk of the scene is not free)
    mgr.item_manager_wait = math.min((mgr.item_manager_wait or 7.5) * 2, 120)
    mgr.item_manager_next = now + mgr.item_manager_wait
    local list, best, first = {}, nil, nil
    for _, c in ipairs(mgr.im_candidates(true)) do
        local knows = mgr.im_knows(c.obj)
        list[#list + 1] = { how = c.how, knows_items = knows }
        if knows and not best then best = c end
        first = first or c
    end
    mgr.item_manager_list = list
    local pick = best or first
    if pick then
        local key = pick.how .. tostring(best ~= nil)
        mgr.item_manager, mgr.item_manager_how, mgr.item_manager_ok = pick.obj, pick.how, best ~= nil
        if mgr.item_manager_said ~= key then
            mgr.item_manager_said = key
            say(string.format("item manager: using %s (%s); %d copies looked at", pick.how,
                best and "it knows the items" or "NONE of the copies knows an item, so creating items will fail", #list))
        end
    end
    return mgr.item_manager
end

-- The player's GameObject (Pl0000 for Ethan, Pl2000 for Mia ...): remembered from hooks, or searched for (at most every 3
-- seconds). When there are several, the one nearest the camera is the one being played. A single one is looked for again
-- only once a minute (the scan walks the whole scene), several every 5 seconds.
-- (10.11) "every 10 seconds there is a 10 fps frame dip": the walk of the scene (up to 20000 objects, a name read for each) cost 27 to 34 ms in the user's debug file
-- (slowest frames at 225.5 s, 245.5 s, 265.5 s, 295.5 s ... all in "menu/who/weapon/inventory") and the Play-as module forced it every 10 s. The walk is only needed when the
-- remembered player object may be the wrong one, and the wrong one is not where the camera is (RE7 is first person: the camera is the player's eyes). So the remembered object
-- is looked at first (one position read): while it is within 3.5 m of the camera it is kept and the scene is NOT walked. A walk because the object is elsewhere (a cutscene
-- camera, a swapped object) is repeated at most every 30 s (60, 120 ... 300 s while it keeps finding the same object). Counters: mgr.player_walks (health.who.player_search in the debug file).
mgr.player_walks = { walks = 0, kept = 0, last_ms = 0, max_ms = 0, last_at = -1000, far_at = -1000, ON_CAMERA_M = 3.5, FAR_EVERY = 30, FAR_MAX = 300, far_every = 30 }
function mgr.player_on_camera()
    local cam = state.local_pos
    if not mgr.player or not cam then return true end -- no camera reading to compare with: the object answers to its name, so it is kept
    local ok, p = pcall(function() return mgr.player:call("get_Transform"):call("get_Position") end)
    if not ok or not p then return false end
    local W = mgr.player_walks
    local dx, dy, dz = p.x - cam.x, p.y - cam.y, p.z - cam.z
    local d2 = dx * dx + dy * dy + dz * dz
    W.last_d = math.floor(math.sqrt(d2) * 100 + 0.5) / 100
    return d2 <= W.ON_CAMERA_M * W.ON_CAMERA_M
end

local function player_object()
    local now = os.clock()
    local PW = mgr.player_walks
    local far_walk = false
    if mgr.player then
        local ok, n = pcall(function() return mgr.player:call("get_Name") end)
        if ok and is_player_name(n) then
            if now - (mgr.player_scan_at or -1000) < (mgr.player_multi and 5 or 60) then return mgr.player end
            -- (10.11) a look is due: the object stays when it is where the camera is, and a walk because it is not is repeated at most every FAR_EVERY s
            if mgr.player_on_camera() then
                mgr.player_scan_at = now
                PW.kept = PW.kept + 1
                PW.far_every = PW.FAR_EVERY
                return mgr.player
            end
            if now - PW.far_at < PW.far_every then return mgr.player end
            far_walk = true
        else
            mgr.player = nil
        end
    end
    if now - mgr.player_checked < 3 then return mgr.player end
    mgr.player_checked = now
    if far_walk then PW.far_at, PW.had = now, mgr.player_name end -- (a walk that finds the same kind of player object again doubles the wait for the next one: the camera is simply somewhere else)
    local cands = {}
    local t0 = os.clock()
    pcall(each_gameobject, function(go)
        local okn, n = pcall(function() return go:call("get_Name") end)
        if okn and is_player_name(n) then cands[#cands + 1] = go end
    end, 20000)
    PW.walks, PW.last_at = PW.walks + 1, now
    PW.last_ms = math.floor((os.clock() - t0) * 10000 + 0.5) / 10
    if PW.last_ms > PW.max_ms then PW.max_ms = PW.last_ms end
    mgr.player_scan_at, mgr.player_multi, mgr.player_cands = now, #cands > 1, #cands
    local best
    if #cands == 1 then
        best = cands[1]
    elseif #cands > 1 then
        local cam, bd = state.local_pos, nil
        if not cam then -- (no camera position yet: take the first for now and look again in a second)
            mgr.player_scan_at, mgr.player_checked = now - 4, now - 2
        end
        for _, go in ipairs(cands) do
            local okp, p = pcall(function() return go:call("get_Transform"):call("get_Position") end)
            local d = (okp and p and cam) and ((p.x - cam.x) ^ 2 + (p.y - cam.y) ^ 2 + (p.z - cam.z) ^ 2) or 1e18
            if bd == nil or d < bd then best, bd = go, d end
        end
    end
    if best then
        local okn, n = pcall(function() return best:call("get_Name") end)
        n = okn and n or nil
        if n ~= mgr.player_name then say("player object: " .. tostring(n) .. " (" .. #cands .. " found)") end
        if PW.had ~= nil then
            PW.far_every = (n == PW.had) and math.min(PW.far_every * 2, PW.FAR_MAX) or PW.FAR_EVERY
            PW.had = nil
        end
        mgr.player_name = n
        mgr.player = best
    end
    return mgr.player
end

-- THE INVENTORY OBJECT (9.30: it is looked for again whenever the one in hand stops answering).
-- Before 9.30 the object was found once and kept for good. The Logs 1 file (a session that gave an item in the guest house at 1399 s and
-- tried to receive one in the main house at 3146 s, after the dinner cutscene) shows what that does: at 3146 s the object was still
-- "there" but dead (isAddItem raised an error, addItem answered "Invoke threw an exception", the list could not be read), most likely
-- because the game builds a new player object (and a new inventory component with it) when the story moves on. So now: the one in hand
-- is checked twice a second (does its list still read?), every 3 s it is compared with the component on the CURRENT player object, and
-- when it fails a new one is looked for: the player's own component, then every app.Inventory component in the scene, then the
-- singleton, then one the game's own hook handed over. What was tried is kept (mgr.inv_log) for the debug file and the panel.
mgr.inv_log = { found = 0, lost = 0, switched = 0, searches = 0, failed_searches = 0, how = nil, why = nil, tried = {}, lines = 0 }
mgr.inv_note = function(text) say(text) end -- (the item trail is added once it exists, further down)

-- (the item trail, which flushes the debug file at once, only gets the events that matter for a failure: a loss, a switch, a failed search)
function mgr.inv_say(text, to_trail)
    local L = mgr.inv_log
    L.lines = L.lines + 1
    if L.lines > 24 then return end
    if to_trail then pcall(mgr.inv_note, "inventory: " .. text) else say("inventory: " .. text) end
end

-- Does this inventory still answer? Returns true, or false plus why.
function mgr.inv_alive(inv)
    if inv == nil then return false, "there is none" end
    local ok, list = pcall(function() return inv:get_field("_ItemList") end)
    if not ok then return false, "reading its _ItemList raised an error" end
    if list == nil then return false, "its _ItemList is nil" end
    return true
end

function mgr.inv_address(obj)
    local ok, a = pcall(function() return obj:get_address() end)
    if ok and type(a) == "number" then return a end
    return nil
end

-- Looks for a working inventory. Returns the object and how it was found, or nil and the list of what was tried.
function mgr.inv_find()
    local tried = {}
    local function try(how, obj)
        if obj == nil then return nil end
        local alive, why = mgr.inv_alive(obj)
        if alive then return obj end
        tried[#tried + 1] = how .. ": " .. tostring(why)
    end
    local player = player_object()
    if player then
        local ok, comp = pcall(function() return player:call("getComponent(System.Type)", sdk.typeof("app.Inventory")) end)
        if ok and comp ~= nil then
            local inv = try("the component on the player object", comp)
            if inv then return inv, "the component on the player object", tried end
        else
            tried[#tried + 1] = "the component on the player object: " .. (ok and "none there" or "the call raised an error")
        end
    else
        tried[#tried + 1] = "the player object was not found"
    end
    local okS, scene = pcall(scene_object)
    if okS and scene then
        local okc, arr = pcall(function() return scene:call("findComponents(System.Type)", sdk.typeof("app.Inventory")) end)
        local els = okc and arr and select(2, pcall(function() return arr:get_elements() end)) or nil
        if type(els) == "table" and #els > 0 then
            -- (when several answer, the one on the player's object wins; the first that answers otherwise)
            local first
            for i, c in ipairs(els) do
                if i > 6 then break end
                local alive = mgr.inv_alive(c)
                if alive then
                    local okg, go = pcall(function() return c:call("get_GameObject") end)
                    local okn, nm = pcall(function() return go and go:call("get_Name") end)
                    if okg and okn and is_player_name(nm) then return c, "a component in the scene, on the player", tried end
                    first = first or c
                end
            end
            if first then return first, "a component found in the scene", tried end
            tried[#tried + 1] = "the scene's " .. #els .. " app.Inventory component(s): none answered"
        else
            tried[#tried + 1] = "the scene has no app.Inventory component" .. (okc and "" or " (the search raised an error)")
        end
    else
        tried[#tried + 1] = "no scene"
    end
    local okg, single = pcall(sdk.get_managed_singleton, "app.Inventory")
    if okg and single ~= nil then
        local inv = try("the managed singleton", single)
        if inv then return inv, "the managed singleton", tried end
    else
        tried[#tried + 1] = "no managed singleton"
    end
    if mgr.captured_inv then
        local inv = try("the one a game call handed over", mgr.captured_inv)
        if inv then return inv, "the one a game call handed over", tried end
    end
    return nil, nil, tried
end

-- The one in hand stopped answering (or the caller saw it fail): forget it, so the next lookup searches.
function mgr.inv_lost(why)
    local L = mgr.inv_log
    if mgr.inventory == nil then return end
    mgr.inventory = nil
    mgr.inv_checked_at, mgr.inv_compared_at, mgr.inv_failed_at, mgr.inv_relost = nil, nil, nil, true
    L.lost = L.lost + 1
    L.why = why
    mgr.inv_say(string.format("the inventory object in hand stopped answering (%s); looking for it again", tostring(why)), true)
end

local function inventory_object()
    local now = os.clock()
    local L = mgr.inv_log
    local inv = mgr.inventory
    if inv then
        if now - (mgr.inv_checked_at or -1e9) < 0.5 then return inv end
        mgr.inv_checked_at = now
        local alive, why = mgr.inv_alive(inv)
        if not alive then
            mgr.inv_lost(why)
            inv = nil
        elseif now - (mgr.inv_compared_at or -1e9) >= 3 then
            -- still answering, but is it the one on the player we have now? (a dead component can keep answering from old memory)
            mgr.inv_compared_at = now
            local player = player_object()
            local okc, comp = false, nil
            if player then okc, comp = pcall(function() return player:call("getComponent(System.Type)", sdk.typeof("app.Inventory")) end) end
            if okc and comp ~= nil then
                local a, b = mgr.inv_address(comp), mgr.inv_address(inv)
                if a and b and a ~= b and mgr.inv_alive(comp) then
                    mgr.inventory = comp
                    L.switched, L.how = L.switched + 1, "the component on the player object (it changed)"
                    mgr.inv_say("the player's inventory component is a different object from the one in hand: switched to it", true)
                    return comp
                end
            end
        end
        if inv then return inv end
    end
    if now - (mgr.inv_failed_at or -1e9) < 1.0 then return nil end -- (a search that found nothing is repeated once a second at most)
    L.searches = L.searches + 1
    local found, how, tried = mgr.inv_find()
    L.tried = tried
    if found then
        mgr.inventory, mgr.inv_checked_at, mgr.inv_compared_at, mgr.inv_failed_at = found, now, now, nil
        if L.found == 0 or mgr.inv_relost then
            mgr.inv_say("found the inventory: " .. how .. (L.found > 0 and " (again)" or ""), L.found > 0)
        end
        mgr.inv_relost = nil
        L.found, L.how, L.why = L.found + 1, how, nil
        return found
    end
    mgr.inv_failed_at = now
    L.failed_searches = L.failed_searches + 1
    if L.failed_searches == 1 or L.failed_searches % 30 == 0 then
        mgr.inv_say("no inventory object found (" .. table.concat(tried, "; ") .. ")", L.failed_searches == 1 and L.found > 0)
    end
    return nil
end

local function peer_present(now)
    return state.remote ~= nil and (now or os.clock()) - state.remote_changed_at < CFG.STALE_AFTER
end

-- Compact text for a value read from a field, for the debug file.
local function dump_value(v)
    local t = type(v)
    if t == "number" or t == "boolean" then return tostring(v) end
    if t == "string" then return "\"" .. v:sub(1, 60) .. "\"" end
    if t == "nil" then return "nil" end
    if t == "userdata" then
        local ok, s = pcall(function()
            if v.x ~= nil and v.y ~= nil and v.z ~= nil then return string.format("(%.2f, %.2f, %.2f)", v.x, v.y, v.z) end
            local td = v:get_type_definition()
            return td and ("<" .. td:get_full_name() .. ">") or tostring(v)
        end)
        return ok and s or "<object>"
    end
    return "<" .. t .. ">"
end

-- Writes every instance field of a component (and of its app.* parent types) with its current value.
local function dump_fields(obj, indent, limit)
    local shown = 0
    local ok, err = pcall(function()
        local t = obj:get_type_definition()
        while t and shown < limit do
            local tname = t:get_full_name()
            if tname:find("^System%.") or tname:find("^via%.Component") or tname:find("^via%.Behavior") then break end
            for _, f in ipairs(t:get_fields() or {}) do
                if shown >= limit then break end
                if not f:is_static() then
                    shown = shown + 1
                    local fname = f:get_name()
                    local ft = f:get_type()
                    local okv, v = pcall(function() return obj:get_field(fname) end)
                    say(string.format("%s%s : %s = %s", indent, fname, ft and ft:get_full_name() or "?",
                        okv and dump_value(v) or "(unreadable)"))
                end
            end
            t = t:get_parent_type()
        end
    end)
    if not ok then say(indent .. "(field dump failed: " .. tostring(err) .. ")") end
end

-- Fields of obj (with parents) whose declared type is type_name: returns { {name, value}, ... }.
local function fields_of_type(obj, type_name)
    local out = {}
    pcall(function()
        local t = obj:get_type_definition()
        while t do
            local tn = t:get_full_name()
            if tn:find("^System%.") or tn:find("^via%.Component") or tn:find("^via%.Behavior") then break end
            for _, f in ipairs(t:get_fields() or {}) do
                local ft = f:get_type()
                if not f:is_static() and ft and ft:get_full_name() == type_name then
                    local okv, v = pcall(function() return obj:get_field(f:get_name()) end)
                    if okv and v ~= nil then out[#out + 1] = { f:get_name(), v } end
                end
            end
            t = t:get_parent_type()
        end
    end)
    return out
end

----------------------------------------------------------------------------------------------
-- Item transfer. Two ways to hand things to the other player:
--   A. "Give": a hotkey (F7) or the panel button hands over the item highlighted in the inventory. It leaves
--      your inventory (app.Inventory.reduceItem) and is created in theirs (createItemInstance + addItem, the
--      same calls the game makes when you craft). If their inventory is full, or the direct add fails, it
--      appears on the ground at their feet instead, so nothing is ever lost.
--   B. "Discard drops it": discarding in the inventory runs app.Item.reduceNum(count, player) (seen in the
--      item trace). With this option on, the item is also spawned on the ground at your feet
--      (app.ItemManager.createDropItemInstance, what drawers use) and the other player sees it appear
--      at the same spot. Picking it up is then ordinary item sync.
-- Messages: 5 = give "id|count", 6 = world drop "id|count|x|y|z".
-- All of this is built from the trace, not yet tried in the game: the panel says which path was used.
----------------------------------------------------------------------------------------------
local GIVE_MSG, DROP_MSG, GIVE_ACK_MSG = 5, 6, 10
local dump_focused_item -- defined further down (the debug collectors)
local give = {
    drop_on_discard = true,
    hint = true,
    hotkey = 0x76, -- F7
    key_was_down = false,
    focus = nil,   -- the item highlighted in the inventory: { item, id, count, at }
    pending_drop = nil,
    hover_seen = 0,
    want_dump = nil, auto_dump_at = -1e9, -- set when something unreadable should be written to the debug file by itself
    inv_list = nil, inv_note = nil, inv_at = -10, inv_dirty = false,
    hooked = false,
    sent = 0, received = 0, dropped = 0, failed = 0,
    out = {},    -- what I sent and have no answer for yet: { kind = "g"/"d", id, n, at }
    inbox = {},  -- gifts that arrived while the game could not take them yet (no player object): { id, n, tries, next_at }
    last = "Nothing given or dropped yet.",
    -- (9.33) Nothing is created for the inventory any more: createItemInstance + addItem (and the item lab built around it) crashed the real game
    -- every time it produced an object, and was taken out. A gift of a kind I already hold makes my stack bigger (proven in the real game); every
    -- other gift, and a discard, is a drop on the ground (createDropItemInstance, see `ground` below).
    refused = 0,         -- gifts / drops refused because the ground route is switched off
    -- Taking out a WHOLE inventory entry (the last unit of a kind) with reduceItem(id, n, true) crashed the game every time it was
    -- tried (a script-made ChemicalS twice, a FlameBulletS you gave away one by one: the first four gave fine, the fifth was the last).
    -- Taking some of a stack never did. So a give that would empty an entry is refused unless this is ticked, and then it uses the
    -- other value of the third argument, the one crafting uses. (9.35: ON at the start and remembered: the owner asked for the last item to be
    -- giveable, and the crafting way is the one that worked in the real game; the box under Items: give and drop switches it off.)
    last_ok = true, refused_last = 0, reopen_seen = 0, reopen_after_ours = 0, last_call_at = -100, whole_entry_removals = 0,
    -- (9.32) The 3 m rule (the owner's): an item changes hands only when the other player is within 3 m, so a key item can't be passed across
    -- the map (or from one floor to another) and break the story. A downed player can still open the inventory and give: the live player is the
    -- one who may need what the downed one carries. The receiver checks again with a little more room (4 m): the other player may have
    -- walked a step while the message travelled.
    RANGE = 3.0, RANGE_RECV = 4.0, refused_far = 0, refused_far_recv = 0, last_far = nil, skip_range = false,
    -- THE GROUND ROUTE (9.32, the default from 9.33 and remembered): a gift of a kind I don't hold, and a discard, become a drop on the ground
    -- (createDropItemInstance, the call the game itself uses for what lies on the ground; addItem is never called and nothing is made for the
    -- inventory). The other player picks it up with the game's own pickup, which the pickup hook sees and syncs. The real game showed it works
    -- (the 9.32 files: Herb, HandgunBullet, ShotgunBullet drops, all alive seconds later). Growing a stack of a kind already held stays the first way.
    drops_refused = 0, last_refused_drop = nil, -- (10.12) key items / weapons are never made for the ground (createDropItemInstance made bare objects for them and crashed the game)
    ground = true, ground_drops = {}, GROUND_KEEP = 8, GROUND_LOOK_AFTER = 2.0, ground_made = 0, ground_failed = 0, ground_picked = 0, ground_gone = 0,
}

local function give_note(text)
    give.last = text
    say("give: " .. text)
    chat_add("Items", text)
end

-- (9.32) The panel's receive tests run the real receive code on yourself: the 3 m rule is not applied to them (the bot is not next to you).
function give.test_receive(payload)
    give.skip_range = true
    local ok, err = pcall(netmsg.handlers[GIVE_MSG], payload)
    give.skip_range = false
    if not ok then say("give: the test failed: " .. tostring(err)) end
end

-- (9.32) How far the other player is from me in metres: my camera to theirs, in 3D (nil when it can't be told).
function give.distance()
    local lp, r = state.local_pos, state.remote
    if not (lp and r and r.pos) then return nil end
    local p = r.pos
    local d = math.sqrt((p.x - lp.x) ^ 2 + (p.y - lp.y) ^ 2 + (p.z - lp.z) ^ 2)
    if d ~= d then return nil end
    return d
end

-- A string coming back from the game may be a Lua string or a managed System.String object.
local function as_text(v)
    if type(v) == "string" then return v end
    if v == nil or type(v) == "number" or type(v) == "boolean" then return nil end
    local ok, t = pcall(function() return v:call("ToString()") end)
    if ok and type(t) == "string" then return t end
    return nil
end

----------------------------------------------------------------------------------------------
-- Model probe. Read-only, one press: finds the characters in the scene that carry a mesh (Ethan, Mia, Jack, the enemies, the
-- headless Mia of the shipwreck) and writes down for each one its object name, its mesh file, how many joints it has, how far it
-- is from you and where; for Ethan's own model and the biggest character models also the whole joint list (name, parent, and where
-- each joint is relative to the object). That is what is needed to choose a real model for the other player, to map its skeleton
-- onto the stand-in's, and to stand a real enemy model in for the red boxes. Nothing is cloned, moved or hidden. The result is in
-- the debug file as health.model_probe and in the journal.
-- A second button lists the engine's methods for making, copying and drawing a mesh object (health.model_types): the next step
-- (a second Ethan body of my own, not a copy of yours) can only be written against what the engine really has.
----------------------------------------------------------------------------------------------
CFG.mprobe = { filter = "pl;em;mia;ethan;jack;marguerite;lucas;zoe;clancy;chara", characters_only = true, result = nil, types = nil,
    status = "Not used yet.", types_status = "Not used yet.", last_at = -100,
    MAX_FOUND = 90,      -- entries kept
    MAX_MATCHED = 600,   -- objects with a mesh that matched the words, looked at in all (a scene can hold thousands of plants)
    PER_MESH = 3,        -- the same mesh file is listed at most this many times (the rest are only counted in mesh_counts)
    LISTS = 6,           -- how many models get their whole joint list
    LISTS_PLAIN = 3,     -- ...when none of them is a player or a big character model: the nearest three, as before
    BIG_MODEL = 40,      -- joints; a "big" character model has at least this many
    MAX_JOINTS = 280,    -- joints written per model (the enemies' heads have about 250)
    MAX_TYPE_LINES = 760 }
CFG.mprobe.TYPES = { -- the engine types that decide how a model can be made and posed: { name, words in the method name, limit }
    { "via.GameObject", { "create", "destroy", "clone", "instantiate", "copy", "draw", "update", "active" }, 40 },
    { "via.Scene", { "find", "create", "instantiate", "clone", "prefab", "folder", "load" }, 50 },
    { "via.Prefab", nil, 40 },
    { "via.Folder", { "load", "instantiate", "create", "prefab", "folder", "active" }, 30 },
    { "via.render.Mesh", { "mesh", "material", "enabled", "draw", "joint", "resource", "shadow", "lod", "skin" }, 70 },
    { "via.render.MeshResource", nil, 30 },
    { "via.motion.Motion", { "joint", "pose", "copy", "mirror", "skeleton", "layer", "bank", "play", "dummy" }, 70 },
    { "via.motion.JointMap", nil, 30 },
    { "via.Transform", { "joint", "parent", "child", "position", "rotation", "scale", "same", "copy" }, 60 },
    { "via.Joint", nil, 60 },
    -- (what the 9.23 file left out of the 70-line limit: the setters a new mesh object is given, and the holders they take)
    { "via.render.Mesh", { "set" }, 130 },
    { "via.GameObject", nil, 60 },
    { "via.render.MeshResourceHolder", nil, 30 },
    { "via.render.MeshMaterialResourceHolder", nil, 30 },
    { "via.ResourceHolder", nil, 30 },
    { "via.Component", nil, 30 },
    -- (9.24: what playing the game's own motions on a body of my own would need: a layer's setters, the banks, the holder)
    { "via.motion.TreeLayer", { "motion", "bank", "frame", "speed", "change", "set", "weight", "play" }, 60 },
    { "via.motion.MotionBank", nil, 30 },
    { "via.motion.DynamicMotionBank", nil, 30 },
    { "via.motion.MotionBankResourceHolder", nil, 20 },
    { "via.motion.Motion", { "set", "change", "play" }, 50 },
}
function CFG.mprobe.try(obj, names, ...)
    for _, n in ipairs(names) do
        local ok, v = pcall(obj.call, obj, n, ...)
        if ok and v ~= nil then return v, n end
    end
    return nil, nil
end
function CFG.mprobe.text(v)
    if v == nil then return nil end
    local t = type(v)
    if t == "string" then return v end
    if t == "number" or t == "boolean" then return tostring(v) end
    for _, m in ipairs({ "get_ResourcePath", "getResourcePath", "ToString()", "ToString" }) do
        local ok, r = pcall(v.call, v, m)
        if ok and type(r) == "string" and r ~= "" then return r end
    end
    return nil
end
function CFG.mprobe.words()
    local out = {}
    for w in tostring(CFG.mprobe.filter or ""):lower():gmatch("[^;,%s]+") do out[#out + 1] = w end
    return out
end
-- Does an object match the words? A word of one or two letters ("pl", "em") must start the name of the object or of a parent and be
-- followed by a digit (Pl0000_Chapter1, Em2000), or every "Plants" and "Emitter" in the scene would match; a longer word ("mia",
-- "ethan") matches anywhere in the names.
function CFG.mprobe.matches(words, path, name)
    local low = (tostring(path) .. "/" .. tostring(name)):lower()
    for _, w in ipairs(words) do
        if #w <= 2 then
            local pat = "^" .. (w:gsub("%p", "%%%0")) .. "%d"
            for seg in low:gmatch("[^/]+") do
                if seg:find(pat) then return true end
            end
        elseif low:find(w, 1, true) then
            return true
        end
    end
    return false
end
-- (10.27) The cheaper walk the scan uses. The 10.26 file has the scan at 105 to 180 ms every 20 s (5,165 objects), with 70 to 90 ms more lost in the next frame, and these are
-- the 71 of the 73 gaps over 100 ms in that file. each_gameobject made a path string for every object and `matches` lower-cased the WHOLE path again for each one, then, for
-- the two short words ("pl", "em"), built a pattern and tried every part of the path. A name decides a match on its own and a match is inherited by everything under it (the path
-- is the parents' names plus its own, the words never contain "/"), so this reads each object's OWN name once, lower-cases only that, makes the path text only for an object that
-- matched (from a list of the names on the way down) and makes no closure per object. The same objects are visited (8 levels, `max_nodes`), the same ones match.
function CFG.mprobe.compile(words)
    local short, long = {}, {}
    for _, w in ipairs(words) do
        if #w <= 2 then short[#short + 1] = "^" .. (w:gsub("%p", "%%%0")) .. "%d" else long[#long + 1] = w end
    end
    return { short = short, long = long }
end
-- Does this one name (lower case) match? The short words must start a part of the name (split at "/", as the old path was) and be followed by a digit.
function CFG.mprobe.name_hit(cw, low)
    for _, w in ipairs(cw.long) do
        if low:find(w, 1, true) then return true end
    end
    if #cw.short > 0 then
        for seg in low:gmatch("[^/]+") do
            for _, pat in ipairs(cw.short) do
                if seg:find(pat) then return true end
            end
        end
    end
    return false
end
-- visit(go, name, hit, names, depth) for every object that has a GameObject: `hit` is true when the name, or the name of any parent, matched; the path of the object is
-- "/" .. table.concat(names, "/", 1, depth + 1). Returns how many objects were looked at.
function CFG.mprobe.walk(cw, visit, max_nodes)
    local scene = scene_object()
    if not scene then return 0 end
    local MP = CFG.mprobe
    local count = 0
    local names = {}
    local function walk(xf, depth, inherited)
        while xf and count < max_nodes do
            count = count + 1
            local go = xf:call("get_GameObject")
            local name = "?"
            if go then
                local okn, n = pcall(go.call, go, "get_Name")
                if okn and n ~= nil then name = tostring(n) end
            end
            names[depth + 1] = name
            local hit = inherited or MP.name_hit(cw, name:lower())
            if go and visit(go, name, hit, names, depth) then return true end
            if depth < 8 then
                local child = xf:call("get_Child")
                if child and walk(child, depth + 1, hit) then return true end
            end
            xf = xf:call("get_Next")
        end
        return false
    end
    walk(scene:call("get_FirstTransform"), 0, false)
    return count
end
-- The joint objects of a transform (an array), or nil and a note.
function CFG.mprobe.joint_els(xf)
    local arr = CFG.mprobe.try(xf, { "get_Joints", "getJoints" })
    if arr == nil then return nil, "no joint list from the transform" end
    local els
    pcall(function() els = arr:get_elements() end)
    if not els then return nil, "joint list is not an array" end
    return els
end
-- The joints written out: names ("name<parent") and, parallel to them, where each joint is in centimetres relative to the object
-- ("x y z"; "-" when the engine gave no position). At most MAX_JOINTS.
function CFG.mprobe.describe_joints(els, origin)
    local MP = CFG.mprobe
    local names, cm, any = {}, {}, false
    for i, j in ipairs(els) do
        if i > MP.MAX_JOINTS then break end
        local nm = MP.text(MP.try(j, { "get_Name", "getName" })) or "?"
        local par = MP.try(j, { "get_Parent", "getParent" })
        local pn = par and MP.text(MP.try(par, { "get_Name", "getName" })) or nil
        names[#names + 1] = pn and (nm .. "<" .. pn) or nm
        local where = "-"
        pcall(function()
            local p = MP.try(j, { "get_Position", "getPosition" })
            if p and origin and type(p.x) == "number" then
                where = string.format("%d %d %d", math.floor((p.x - origin.x) * 100 + 0.5), math.floor((p.y - origin.y) * 100 + 0.5),
                    math.floor((p.z - origin.z) * 100 + 0.5))
                any = true
            end
        end)
        cm[#cm + 1] = where
    end
    return names, any and cm or nil
end

function CFG.mprobe.scan()
    local MP = CFG.mprobe
    local words = MP.words()
    local lp = state.local_pos
    local res = { filter = MP.filter, characters_only = MP.characters_only, build = CFG.BUILD, found = {}, mesh_counts = {},
        scanned = 0, matched = 0, left_out = 0, repeated = 0, unreadable = 0, errors = 0, at_s = math.floor(os.clock()) }
    MP.last_at = os.clock()
    local per_mesh = {}
    local cw = MP.compile(words)
    local ok, err = pcall(MP.walk, cw, function(go, name, hit, names, depth) -- (10.27: the cheaper walk, see CFG.mprobe.walk; it used each_gameobject and MP.matches on the whole path)
        res.scanned = res.scanned + 1
        if not hit then return false end
        if res.matched >= MP.MAX_MATCHED then return false end
        local path = "/" .. table.concat(names, "/", 1, depth + 1)
        local okc, comps = pcall(component_names, go)
        local mesh_comp
        if okc then
            for _, cn in ipairs(comps) do
                if cn == "render.Mesh" then mesh_comp = true end
            end
        end
        if not mesh_comp then return false end -- only things that are drawn with a mesh: not triggers, sensors or logic objects
        res.matched = res.matched + 1
        local e = { name = name, path = path:sub(1, 160), components = comps }
        pcall(function()
            local mc = go:call("getComponent(System.Type)", sdk.typeof("via.render.Mesh"))
            if mc then
                local mres, via = MP.try(mc, { "getMesh", "get_Mesh", "get_MeshResource" })
                e.mesh = MP.text(mres)
                e.mesh_call = via
                if mres == nil then e.mesh_note = "no mesh resource from getMesh / get_Mesh" end
                local mats = MP.try(mc, { "get_MaterialNum", "getMaterialNum" })
                if type(mats) == "number" then e.materials = mats end
                -- (9.31) the material file too: the loader by path (CFG.load) has to guess it from the mesh's name until a real one is seen
                local okm, mdf = pcall(function() return MP.text((MP.try(mc, { "get_Material", "getMaterial" }))) end)
                if okm and type(mdf) == "string" and mdf ~= "" then e.mdf = mdf:sub(1, 160) end
                local drawn = MP.try(mc, { "get_DrawDefault", "get_Enabled" })
                if drawn ~= nil then e.enabled = drawn == true end
            end
        end)
        -- plants, props and the like: their mesh is not under Character/ (a mesh we cannot read is kept, up to ten of them)
        local is_char = (e.mesh or ""):lower():find("character/", 1, true) ~= nil
        if e.mesh == nil then
            res.unreadable = res.unreadable + 1
            if res.unreadable > 10 then res.left_out = res.left_out + 1 return false end
        elseif MP.characters_only and not is_char then
            res.left_out = res.left_out + 1
            return false
        end
        local key = e.mesh or ("?" .. name)
        res.mesh_counts[key] = (res.mesh_counts[key] or 0) + 1
        per_mesh[key] = (per_mesh[key] or 0) + 1
        if per_mesh[key] > MP.PER_MESH then res.repeated = res.repeated + 1 return false end
        if #res.found >= MP.MAX_FOUND then res.left_out = res.left_out + 1 return false end
        pcall(function()
            local xf = go:call("get_Transform")
            local p = xf:call("get_Position")
            e.pos = { math.floor(p.x * 100 + 0.5) / 100, math.floor(p.y * 100 + 0.5) / 100, math.floor(p.z * 100 + 0.5) / 100 }
            if lp then e.dist = math.floor(math.sqrt((p.x - lp.x) ^ 2 + (p.y - lp.y) ^ 2 + (p.z - lp.z) ^ 2) * 10 + 0.5) / 10 end
            e.origin = { x = p.x, y = p.y, z = p.z }
            local els, note = MP.joint_els(xf)
            e.els = els
            e.joint_count = els and #els or nil
            e.joint_note = note
        end)
        res.found[#res.found + 1] = e
        return false
    end, 20000)
    if not ok then res.errors = res.errors + 1 res.error = tostring(err):sub(1, 160) end
    res.scan_capped = res.scanned >= 20000
    table.sort(res.found, function(a, b)
        local da, db = a.dist or 1e9, b.dist or 1e9
        if da ~= db then return da < db end
        return a.name < b.name
    end)
    -- The whole joint list goes to: the player's own model first (Character/Player, nearest first), then the big character models
    -- (at least BIG_MODEL joints), one per mesh file, up to LISTS; when there is none of those, the three nearest.
    local chosen, seen = {}, {}
    local function consider(limit, pred)
        for _, e in ipairs(res.found) do
            if #chosen >= limit then return end
            local key = e.mesh or e.name
            if e.els and not seen[key] and pred(e) then
                seen[key] = true
                chosen[#chosen + 1] = e
            end
        end
    end
    consider(MP.LISTS, function(e) return (e.mesh or ""):lower():find("character/player", 1, true) ~= nil end)
    consider(MP.LISTS, function(e) return (e.mesh or ""):lower():find("character/", 1, true) ~= nil and (e.joint_count or 0) >= MP.BIG_MODEL end)
    consider(MP.LISTS_PLAIN, function() return true end)
    for _, e in ipairs(chosen) do
        local okj, names, cm = pcall(MP.describe_joints, e.els, e.origin)
        if okj then e.joint_list, e.joint_cm = names, cm else e.joint_note = "joint list failed: " .. tostring(names):sub(1, 80) end
    end
    for _, e in ipairs(res.found) do e.els, e.origin = nil, nil end
    MP.result = res
    MP.status = string.format("Scanned %d objects: %d with a mesh matched \"%s\"; %d shown (%d with the whole joint list)%s%s.",
        res.scanned, res.matched, MP.filter, #res.found, #chosen,
        res.left_out > 0 and string.format(", %d left out%s", res.left_out, MP.characters_only and " (their mesh is not under Character/)" or "") or "",
        res.repeated > 0 and string.format(", %d repeats of the same mesh only counted", res.repeated) or "")
    if not MP.quiet then say("model probe: " .. MP.status .. (res.error and (" (stopped: " .. res.error .. ")") or "")) end
    for i, e in ipairs(res.found) do
        if i <= 25 and not MP.quiet then
            say(string.format("model probe: %s | mesh %s | %s joints | %s m | %s", e.name, tostring(e.mesh), tostring(e.joint_count or "?"),
                tostring(e.dist or "?"), e.path or "?"))
        end
    end
end

----------------------------------------------------------------------------------------------
-- Model collection (9.27, your idea: "I will get other model data during cutscenes or events as long as this is labelled in the gui").
-- The scan above only remembers the LAST press. This keeps every model it has ever seen, one entry per mesh file (the object names
-- that use it, joints, materials, how many times and where it was seen, your note, the cutscene id when the story hook knows it, and
-- the whole joint list the first time), in reframework/data/re7mp/models.json. The file survives restarts and adds up over the whole
-- game: send it once, not after every scene. F11 collects without the menu (cutscenes), the box below can collect by itself every 20 s.
----------------------------------------------------------------------------------------------
CFG.mprobe.collected, CFG.mprobe.collected_n = {}, 0
CFG.mprobe.note, CFG.mprobe.auto, CFG.mprobe.auto_every, CFG.mprobe.auto_at = "", false, 20, -100
CFG.mprobe.hotkey, CFG.mprobe.key_was_down = 0x7A, false -- F11
CFG.mprobe.COLLECT_MAX, CFG.mprobe.COLLECT_LISTS, CFG.mprobe.NAMES_PER, CFG.mprobe.NOTES_PER = 250, 24, 6, 4 -- (9.28: 250, not 70: the list was full)
CFG.mprobe.stats = { presses = 0, scans = 0, added = 0, dropped = 0, no_mesh = 0, last = "Nothing collected yet.", saved = false, save_error = nil,
    loaded = 0, shown_at = -100 }
-- What to collect: { label, words that must appear in the object name, mesh file or path, where to find it }
-- (9.30: the ids come from the community file list, residentevilmodding.boards.net thread 20058: players are stm/character/player/plNNNN and
-- enemies stm/character/enemy/emNNNN. pl0000 Ethan, pl2000 Mia (flashback), pl2100 Mia (uncorrupted), pl3000 Clancy Jarvis, pl3100 Clancy
-- (the 21 card game), pl3400 Zoe (Daughters DLC); em2000 Mia (corrupted; 9.29 had it under Jack by mistake), em2200 / em2300 other Mias,
-- em3000 Jack, em3100 Marguerite, em3200 Lucas, em3400 Zoe Baker, em3600 Marguerite (Beegina), em3700 / em3800 / em3900 the pre-infection
-- Daughters Jack / Marguerite / Lucas, em4000 / em4100 / em4200 Molded (normal / crawler / fat), em8000 Jack (chainsaw), em8100 and em8500
-- Jack (mutated). The ids are also searched for in the mesh path, so a model is found by its file even when the object has another name.)
CFG.mprobe.TARGETS = {
    { "Ethan (the player)", { "pl0000" }, "any time he is in the world (his joint list is the one we already have)" },
    { "Clancy Jarvis (pl3000)", { "clancy", "pl3000", "pl3100" }, "the VHS tape of the derelict house (play the tape and press F11 while he is in view)" },
    { "Mia", { "mia", "pl2000", "pl2100", "em2000", "em2200", "em2300" }, "her cutscenes, the fight with the axe, the headless Mia on the shipwreck, the flashback" },
    { "Jack Baker", { "jack", "em3000", "em3700", "em8000", "em8100", "em8500" }, "the garage fight, the chainsaw fight, any Jack cutscene" },
    { "Marguerite Baker", { "marguerite", "em3100", "em3600", "em3800" }, "her cutscenes and the fight against her" },
    { "Lucas Baker", { "lucas", "em3200", "em3900" }, "his cutscenes and the places he talks to you from" },
    { "Zoe", { "zoe", "em3400", "pl3400" }, "her cutscenes" },
    { "Joe Baker (End of Zoe, pl9000)", { "joe", "pl9000", "pl9100", "pl9200", "ch9" }, "End of Zoe: play as Joe and press F11 while his hands are in view (the files of his hands are then used for him)" },
    { "Chris (Not a Hero, pl1000)", { "chris", "pl1000", "ch8" }, "Not a Hero: play as Chris and press F11 while his hands are in view" },
    { "Molded (the black-mould enemies)", { "molded", "em4000", "em4100", "em4200" }, "stand near one: every kind you meet (the smallest, the big ones)" },
}

function CFG.mprobe.hay(c)
    return ((c.mesh or "") .. "|" .. (c.path or "") .. "|" .. table.concat(c.names or {}, "|")):lower()
end

-- How many collected models match a target, and how many of those have the whole joint list.
function CFG.mprobe.target_hits(words)
    local n, lists = 0, 0
    for _, c in pairs(CFG.mprobe.collected) do
        local hay = CFG.mprobe.hay(c)
        for _, w in ipairs(words) do
            if hay:find(w, 1, true) then
                n = n + 1
                if c.joint_list then lists = lists + 1 end
                break
            end
        end
    end
    return n, lists
end

-- Names of collected models that none of the targets above claims (other enemies and characters), for the checklist.
function CFG.mprobe.other_names()
    local MP = CFG.mprobe
    local out, seen = {}, {}
    for _, c in pairs(MP.collected) do
        local hay = MP.hay(c)
        local claimed = false
        for _, t in ipairs(MP.TARGETS) do
            for _, w in ipairs(t[2]) do if hay:find(w, 1, true) then claimed = true end end
        end
        if not claimed then
            for _, nm in ipairs(c.names or {}) do
                if not seen[nm] then seen[nm] = true out[#out + 1] = nm end
            end
        end
    end
    table.sort(out)
    return out
end

-- The newest cutscene id the story hook has seen in the last three minutes (it only knows them while "Story sync" is on).
function CFG.mprobe.cutscene_note()
    local best, at
    for id, t in pairs(CFG.story and CFG.story.recent or {}) do
        if type(t) == "number" and (not at or t > at) then best, at = id, t end
    end
    if best and os.clock() - at < 180 then return string.format("cutscene %s (%.0f s ago)", best, os.clock() - at) end
    return nil
end

function CFG.mprobe.save()
    local MP = CFG.mprobe
    local list = {}
    for _, c in pairs(MP.collected) do list[#list + 1] = c end
    table.sort(list, function(a, b) return tostring(a.mesh or (a.names and a.names[1]) or "") < tostring(b.mesh or (b.names and b.names[1]) or "") end)
    local ok, err = pcall(json.dump_file, FILES.path("models"), { build = CFG.BUILD, count = #list, models = list,
        about = "re7mp: every model the Model collection has seen; send this file" })
    MP.stats.saved = ok == true
    MP.stats.save_error = (not ok) and tostring(err):sub(1, 100) or nil
end

function CFG.mprobe.load()
    local MP = CFG.mprobe
    local d = FILES.read("models")
    if type(d) ~= "table" or type(d.models) ~= "table" then return end
    for _, m in ipairs(d.models) do
        -- (9.28: an entry with no mesh file - World_Collidable_capsule and the like - is not a model and is left out)
        if type(m) == "table" and MP.collected_n < MP.COLLECT_MAX and type(m.names) == "table" and type(m.names[1]) == "string" and type(m.mesh) == "string" then
            local c = { mesh = type(m.mesh) == "string" and m.mesh or nil, path = type(m.path) == "string" and m.path:sub(1, 160) or nil,
                names = {}, notes = {}, joints = tonumber(m.joints), materials = tonumber(m.materials), seen = tonumber(m.seen) or 1,
                first_s = tonumber(m.first_s), last_s = tonumber(m.last_s), nearest = tonumber(m.nearest),
                mdf = type(m.mdf) == "string" and m.mdf:sub(1, 160) or nil }
            for i, nm in ipairs(m.names) do if type(nm) == "string" and i <= MP.NAMES_PER then c.names[#c.names + 1] = nm:sub(1, 60) end end
            if type(m.notes) == "table" then
                for i, nt in ipairs(m.notes) do if type(nt) == "string" and i <= MP.NOTES_PER then c.notes[#c.notes + 1] = nt:sub(1, 120) end end
            end
            if type(m.joint_list) == "table" and #m.joint_list <= MP.MAX_JOINTS then
                c.joint_list, c.joint_cm = m.joint_list, type(m.joint_cm) == "table" and m.joint_cm or nil
            end
            local key = c.mesh or ("?" .. c.names[1])
            if MP.collected[key] == nil then
                MP.collected[key] = c
                MP.collected_n = MP.collected_n + 1
                MP.stats.loaded = MP.stats.loaded + 1
            end
        end
    end
end

-- Adds what a scan found. Returns how many models were new.
function CFG.mprobe.merge(res)
    local MP = CFG.mprobe
    local now_s = os.time and os.time() or math.floor(os.clock())
    local tags = {}
    if MP.note ~= "" then tags[#tags + 1] = MP.note end
    local cs = MP.cutscene_note()
    if cs then tags[#tags + 1] = cs end
    local tag = table.concat(tags, "; "):sub(1, 120)
    local lists = 0
    for _, c in pairs(MP.collected) do if c.joint_list then lists = lists + 1 end end
    local added = 0
    for _, e in ipairs(res.found) do
        local key = e.mesh or ("?" .. e.name)
        local c = MP.collected[key]
        if e.mesh == nil then
            MP.stats.no_mesh = MP.stats.no_mesh + 1 -- (9.28) no mesh file: a collider or a marker, not a model
        elseif c == nil and MP.collected_n >= MP.COLLECT_MAX then
            MP.stats.dropped = MP.stats.dropped + 1
        else
            if c == nil then
                c = { mesh = e.mesh, path = e.path, names = {}, notes = {}, joints = e.joint_count, materials = e.materials, seen = 0, first_s = now_s }
                MP.collected[key] = c
                MP.collected_n = MP.collected_n + 1
                added = added + 1
            end
            c.seen = c.seen + 1
            c.last_s = now_s
            if e.mdf and not c.mdf then c.mdf = e.mdf end
            if e.dist and (not c.nearest or e.dist < c.nearest) then c.nearest = e.dist end
            local have = false
            for _, nm in ipairs(c.names) do if nm == e.name then have = true end end
            if not have and #c.names < MP.NAMES_PER then c.names[#c.names + 1] = e.name end
            have = false
            for _, nt in ipairs(c.notes) do if nt == tag then have = true end end
            if tag ~= "" and not have and #c.notes < MP.NOTES_PER then c.notes[#c.notes + 1] = tag end
            if e.joint_list and not c.joint_list and lists < MP.COLLECT_LISTS then
                c.joint_list, c.joint_cm = e.joint_list, e.joint_cm
                lists = lists + 1
            end
        end
    end
    return added
end

-- Scan, add, save. why: "F11", "button" or "auto".
function CFG.mprobe.collect(why)
    local MP = CFG.mprobe
    local st = MP.stats
    st.presses = st.presses + 1
    MP.quiet = why == "auto"
    local t0 = os.clock()
    local ok, err = pcall(MP.scan)
    MP.quiet = false
    local ms = (os.clock() - t0) * 1000 -- (10.27) what one scan costs, for the panel and the debug file (the 10.26 file's scans took 105 to 180 ms each)
    st.last_ms, st.total_ms, st.max_ms = ms, (st.total_ms or 0) + ms, math.max(st.max_ms or 0, ms)
    st.timed = (st.timed or 0) + 1
    if not ok or not MP.result then
        st.last = "the scan failed: " .. tostring(err):sub(1, 100)
        st.shown_at = os.clock()
        say("model collection: " .. st.last)
        return
    end
    local added = MP.merge(MP.result)
    st.scans = st.scans + 1
    st.added = st.added + added
    st.last = string.format("%s: %d model(s) in view, %d new, %d collected in all%s", why, #MP.result.found, added, MP.collected_n,
        st.dropped > 0 and (" (" .. st.dropped .. " not kept: the list is full)") or "")
    if added > 0 or why ~= "auto" then
        MP.save()
        st.shown_at = os.clock()
        say("model collection: " .. st.last)
    end
end

function CFG.mprobe.clear()
    local MP = CFG.mprobe
    MP.collected, MP.collected_n = {}, 0
    MP.stats.last = "Cleared."
    MP.save()
    say("model collection: cleared")
end

-- (10.27) The automatic mode only scans at a calm moment. A scan is a stop of about a tenth of a second (a hundred milliseconds in the 10.26 file, plus the game's own clean-up in the
-- frame after): hardly seen when you stand in a menu or watch a cutscene, a hitch every 20 s while you run or fight. A moment is calm when a menu is open, when my Ethan is in a scripted
-- move (the game is playing one of its own scenes with him), or when I have stood still for 1.5 s (less than 25 cm in half a second, over and over). If none of those comes for
-- AUTO_FORCE_S (two minutes) it scans anyway, so a long run still collects. It never scans while the game is saving or loading. F11 and the button always scan at once.
CFG.mprobe.AUTO_FORCE_S, CFG.mprobe.STILL_S = 120, 1.5
CFG.mprobe.track = { at = -100, x = nil, y = nil, z = nil, still_since = nil }
function CFG.mprobe.watch_still(now)
    local T = CFG.mprobe.track
    if now - T.at < 0.5 then return end
    T.at = now
    local p = state.local_pos
    if p == nil then T.still_since = nil T.x = nil return end
    if T.x ~= nil and (p.x - T.x) ^ 2 + (p.y - T.y) ^ 2 + (p.z - T.z) ^ 2 < 0.0625 then -- under 25 cm since the sample half a second ago
        T.still_since = T.still_since or now
    else
        T.still_since = nil
    end
    T.x, T.y, T.z = p.x, p.y, p.z
end
-- true, why: a calm moment; false, why: not now.
function CFG.mprobe.calm(now)
    local MP = CFG.mprobe
    if (CFG.menu and CFG.menu.open == true) or (state.ui_at ~= nil and now - state.ui_at < 1.5) then return true, "a menu is open" end
    local J = CFG.jack and CFG.jack.s
    if J and J.path and J.t and now - J.t < 1.0 then return true, "in a scripted move" end
    local T = MP.track
    if T.still_since and now - T.still_since >= MP.STILL_S then return true, "standing still" end
    return false, "moving"
end

-- F11 (no menu needed in a cutscene) and the automatic mode.
function CFG.mprobe.update(now)
    local MP = CFG.mprobe
    local okk, down = pcall(function() return reframework:is_key_down(MP.hotkey) end)
    down = okk and down == true
    if down and not MP.key_was_down then MP.collect("F11") end
    MP.key_was_down = down
    if not MP.auto then MP.stats.waiting = nil return end
    pcall(MP.watch_still, now)
    local due = now - MP.auto_at - MP.auto_every
    if due < 0 then MP.stats.waiting = nil return end
    -- due: the game must not be saving or loading, and the moment must be calm (or the two minutes must be up)
    if (CFG.perf and CFG.perf.saving_quiet(now, "model_scan")) or (CFG.busy and CFG.busy.busy) then
        MP.stats.waiting = "waiting: the game is saving or loading"
        return
    end
    local calm, why = MP.calm(now)
    if not calm and now - MP.auto_at < MP.AUTO_FORCE_S then
        MP.stats.waiting = "waiting for a calm moment (" .. why .. "); it scans anyway after " .. MP.AUTO_FORCE_S .. " s"
        return
    end
    MP.stats.waiting = nil
    MP.auto_at = now
    MP.stats.auto_calm, MP.stats.auto_forced = (MP.stats.auto_calm or 0) + (calm and 1 or 0), (MP.stats.auto_forced or 0) + (calm and 0 or 1)
    MP.collect("auto")
end

-- A line on screen for a few seconds after a collection, so a press in a cutscene can be seen to have worked.
function CFG.mprobe.draw(now)
    local MP = CFG.mprobe
    if now - MP.stats.shown_at < 6 then pcall(draw.text, "Model collection: " .. MP.stats.last, 24, 150, 0xFF40D0FF) end
end

function CFG.mprobe.report()
    local MP = CFG.mprobe
    local models = {}
    for _, c in pairs(MP.collected) do
        models[#models + 1] = { names = c.names, mesh = c.mesh, joints = c.joints, seen = c.seen, whole_joint_list = c.joint_list ~= nil, notes = c.notes }
    end
    table.sort(models, function(a, b) return tostring(a.mesh or (a.names and a.names[1])) < tostring(b.mesh or (b.names and b.names[1])) end)
    local checklist = {}
    for _, t in ipairs(MP.TARGETS) do
        local n, l = MP.target_hits(t[2])
        checklist[#checklist + 1] = { who = t[1], models = n, with_joint_list = l }
    end
    return { file = FILES.path("models"), collected = MP.collected_n, max = MP.COLLECT_MAX, presses = MP.stats.presses, scans = MP.stats.scans,
        added = MP.stats.added, not_kept = MP.stats.dropped, loaded_from_file = MP.stats.loaded, saved = MP.stats.saved,
        save_error = MP.stats.save_error, auto = MP.auto, last = MP.stats.last, checklist = checklist, other = MP.other_names(), models = models,
        -- 10.27: what a scan costs and when the automatic mode scans (calm = a menu, a scripted move or standing still; forced = two minutes without one)
        scan_cost = { scans_timed = MP.stats.timed or 0, last_ms = MP.stats.last_ms and math.floor(MP.stats.last_ms * 10) / 10 or nil,
            avg_ms = (MP.stats.timed or 0) > 0 and math.floor(MP.stats.total_ms / MP.stats.timed * 10) / 10 or nil,
            max_ms = MP.stats.max_ms and math.floor(MP.stats.max_ms * 10) / 10 or nil },
        auto_scans = { at_a_calm_moment = MP.stats.auto_calm or 0, forced_after_waiting = MP.stats.auto_forced or 0, waiting = MP.stats.waiting } }
end

-- Lists the engine's methods for making, copying, posing and drawing a mesh object (read-only): health.model_types.
function CFG.mprobe.dump_types()
    local MP = CFG.mprobe
    local lines, total = {}, 0
    for _, spec in ipairs(MP.TYPES) do
        local name, words, limit = spec[1], spec[2], spec[3] or 60
        local ok, err = pcall(function()
            local td = sdk.find_type_definition(name)
            if not td then lines[#lines + 1] = name .. ": not found" return end
            local found = {}
            for _, m in ipairs(td:get_methods() or {}) do found[#found + 1] = m end
            table.sort(found, function(a, b) return tostring(a:get_name()) < tostring(b:get_name()) end)
            lines[#lines + 1] = name .. ":"
            local shown = 0
            for _, m in ipairs(found) do
                local mname = tostring(m:get_name())
                local hit = words == nil
                if not hit then
                    local low = mname:lower()
                    for _, w in ipairs(words) do
                        if low:find(w, 1, true) then hit = true break end
                    end
                end
                if hit and shown < limit and total < MP.MAX_TYPE_LINES then
                    shown = shown + 1
                    total = total + 1
                    lines[#lines + 1] = "    " .. mname .. method_signature(m)
                end
            end
            lines[#lines + 1] = string.format("    (%d of %d methods shown)", shown, #found)
        end)
        if not ok then lines[#lines + 1] = name .. ": error " .. tostring(err):sub(1, 100) end
    end
    MP.types = { build = CFG.BUILD, at_s = math.floor(os.clock()), lines = lines }
    MP.types_status = string.format("Listed %d methods of %d types (in the debug file as health.model_types).", total, #MP.TYPES)
    say("model probe: " .. MP.types_status)
end

----------------------------------------------------------------------------------------------
-- Body lab (9.23, experimental): a second Ethan of my own. The game's own shadow objects (ShadowBody, ShadowHandL ...) show that a
-- plain object holding a Transform and a render.Mesh component is enough to carry one of his meshes, so this makes such an object
-- and puts Ethan's own mesh and material on it. It never copies the player object (that would copy his controls and camera too).
-- Every step is a button, every step goes to the black box (the item trail file) BEFORE its engine call, and the engine calls run
-- in the game phase chosen in the panel (the item lab suggests the render frame is the dangerous place to touch objects). If the
-- game dies, the next start names the step. Nothing here runs unless the box is ticked.
----------------------------------------------------------------------------------------------
CFG.body = { enabled = false, lines = {}, queue = {}, go = nil, xf = nil, mc = nil, kids = {}, scene = nil, follow = false,
    joint = "R_UpperArm", axis = 1, deg = 0, hold = false, base = nil, joint_obj = nil, joint_name = nil,
    phase = 1, ticks = 0, errors = 0, dropped = 0, registered = false,
    model_src = "Pl0000_Chapter1", -- 9.25: the object whose mesh is copied (SRC stays Ethan's, for the recorder); any scene object, e.g. an enemy "Em2000"
    NAME = "re7mp_body", SRC = "Pl0000_Chapter1", ETHAN_NAMES = { Pl0000_Chapter1 = true, Pl0000 = true }, PHASES = { "UpdateBehavior", "LockScene", "UI frame" }, AXES = { "X", "Y", "Z" },
    WAIT = 8 }  -- seconds a queued step may wait for its game phase
-- 9.28: the lab's body can be scaled (Mia's copy is shorter than Ethan) and each part can be hidden (her hair is cloth, which a mesh copy lacks)
CFG.body.scale, CFG.body.hidden, CFG.body.SCALE_MIN, CFG.body.SCALE_MAX, CFG.body.MAIN = 1.0, {}, 0.5, 1.5, "(main body)"
-- (9.38) "the crouch still goes into the floor a bit": the body is stood this much higher than the camera's drop in a full crouch (metres; a slider in the body lab)
-- (10.8) 0.08 -> 0.20: the 14 Nov screenshot-test had the crouched body in the ground up to the knees (the slider is under Ethan's friend, and in the body lab box)
CFG.body.crouch_extra, CFG.body.CROUCH_EXTRA_MAX, CFG.body.CROUCH_EXTRA_OLD = 0.20, 0.4, 0.08
-- (10.9) the slider goes down to -2 m ("make the crouch slider also do negatives all the way to -2"); CROUCH_EXTRA_TOP is the friend's slider top
CFG.body.CROUCH_EXTRA_MIN, CFG.body.CROUCH_EXTRA_TOP = -2.0, 0.6

-- A line in the panel, the journal and the debug file; risky = also written to the black box before anything else happens.
function CFG.body.note(text, risky)
    local B = CFG.body
    text = tostring(text):gsub("[\r\n]+", " "):sub(1, 240)
    B.lines[#B.lines + 1] = text
    if #B.lines > 60 then table.remove(B.lines, 1) end
    if risky then give.trail("body lab: " .. text) else say("body lab: " .. text) end
end

-- Which scene we are in: objects made in one are gone with it, and a reference to them must not be used again.
function CFG.body.scene_key()
    local ok, k = pcall(function()
        local s = scene_object()
        if not s then return nil end
        local oka, a = pcall(function() return s:get_address() end)
        return oka and tostring(a) or tostring(s)
    end)
    return ok and k or nil
end

-- One object with a mesh: its name, mesh file, the mesh and material holders (to put on my own object), joints, whether drawn.
function CFG.body.part(go, path)
    local MP = CFG.mprobe
    local p = { go = go, path = path }
    local okn, nm = pcall(function() return go:call("get_Name") end)
    p.name = okn and tostring(nm) or "?"
    pcall(function()
        local mc = go:call("getComponent(System.Type)", sdk.typeof("via.render.Mesh"))
        if mc then
            p.mc = mc
            p.holder = MP.try(mc, { "getMesh", "get_Mesh" })
            p.mesh = MP.text(p.holder)
            p.material = MP.try(mc, { "get_Material", "getMaterial" })
            local en = MP.try(mc, { "get_Enabled" })
            if en ~= nil then p.enabled = en == true end
            local mats = MP.try(mc, { "get_MaterialNum" })
            if type(mats) == "number" then p.materials = mats end
        end
    end)
    pcall(function()
        p.xf = go:call("get_Transform")
        local els = MP.joint_els(p.xf)
        p.joints = els and #els or nil
    end)
    return p
end

-- The object to copy (Ethan's, or since 9.25 any object by name: an enemy "Em2000") and the parts of it that are drawn (body, hands, lower
-- body; not the shadow-only copies, not the codex). out.object = the object itself; out.root = the part that carries the body mesh (the
-- object itself when it has a mesh, as Ethan's does; otherwise its drawn part with the most joints); out.kids = the other drawn parts of the
-- same kind of model (the same first two folders of the mesh file: "character/player", "character/enemy").
-- 9.27: Ethan's object is "Pl0000_Chapter1" in the car, the forest and the guest house, and plain "Pl0000" in the main house (the 0.9 file).
-- For Ethan the name Pl0000_Chapter1 is tried first, then Pl0000; the result is still called B.SRC so the rest of the lab treats him as Ethan.
-- 9.32: the scene comes first, under BOTH of his names, and the files (CFG.load) only after that. 9.31 asked the file loader inside the first
-- lookup ("Pl0000_Chapter1"), so in the main house, where he is called "Pl0000", the loader answered before the second name was tried:
-- Ethan's body was made from his FILE (which the game would not take: "fails at step mesh", 8 times in the 9.31 file) when the real,
-- loaded object stood right there. A model that is in the scene is always used from the scene.
function CFG.body.find()
    local B = CFG.body
    local want = B.model_src
    if type(want) ~= "string" or want == "" then want = B.SRC end
    -- 10.1: the full model pack's files come first (also for a character that IS in the scene: the pack's bodies have their heads)
    if B.allow_load and CFG.pack and CFG.pack.active(want) then
        local okp, packed = pcall(CFG.load.find, want)
        if okp and packed then
            CFG.pack.used[CFG.ids.family(want)] = (CFG.pack.used[CFG.ids.family(want)] or 0) + 1
            packed.from_pack = true
            return packed
        end
    end
    if B.ETHAN_NAMES[want] == true then
        local function usable(o) return o.object ~= nil and o.root ~= nil and o.root.holder ~= nil end
        local out = B.find_one(B.SRC, true)
        if usable(out) then return out end
        local alt = B.find_one("Pl0000", true)
        if usable(alt) then
            alt.name, alt.actual_name = B.SRC, "Pl0000"
            return alt
        end
        -- 9.35: Ethan is only ever copied from the scene. The 9.31..9.34 fallback made him from his FILES when he was not in the scene, and that body
        -- "spawned with no textures"; a copy of the scene's own Ethan (which shares its loaded textures) "seems to consistently work". Not in the
        -- scene (Mia's flashback, a tape, the opening): nothing is made, and the caller (CFG.real) looks again every few seconds.
        -- the objects exist but have no mesh to copy, or nothing is there: say what the first look found
        if out.object then return out end
        if alt.object then
            alt.name, alt.actual_name = B.SRC, "Pl0000"
            return alt
        end
        return out
    end
    return B.find_one(want)
end

-- no_load: the scene only (find() asks the files itself, last).
function CFG.body.find_one(want, no_load)
    local B = CFG.body
    local out = { kids = {}, scanned = 0, name = want }
    local prefix
    local parts = {}
    pcall(each_gameobject, function(go, path)
        out.scanned = out.scanned + 1
        if prefix == nil then
            local okn, nm = pcall(function() return go:call("get_Name") end)
            if okn and nm == want then
                prefix = path .. "/"
                out.object = B.part(go, path)
            end
            return false
        end
        if path:sub(1, #prefix) ~= prefix then return true end -- left the subtree
        parts[#parts + 1] = B.part(go, path)
        return false
    end, 20000)
    local obj = out.object
    if not obj then
        -- (9.31) not in this scene: a known model can be made from its files (CFG.load, when switched on). Only the callers that MAKE something say so
        -- (B.allow_load): Look, the recorder and the rest of the lab must go on saying that a model is not here.
        if B.allow_load and not no_load then
            local okl, alt = pcall(CFG.load.find, want)
            if okl and alt then alt.scanned = out.scanned return alt end
        end
        return out
    end
    local function usable(p)
        local nl = p.name:lower()
        -- 9.30: never a weapon ("no gun models for the other player, empty hand"). Ethan's weapons are not in the same mesh folder as his
        -- body, so they were never copied; this makes it a rule instead of a coincidence of the folder names.
        local is_weapon = nl:find("^wp%d") or nl:find("weapon", 1, true) or nl:find("handgun", 1, true) or (p.mesh or ""):lower():find("/weapon", 1, true)
        return p.mc ~= nil and p.holder ~= nil and p.enabled ~= false and not nl:find("^shadow") and not nl:find("codex", 1, true) and not is_weapon
    end
    local main
    if obj.mc and obj.holder ~= nil then
        main = obj
    else
        for _, p in ipairs(parts) do
            if usable(p) and (not main or (p.joints or 0) > (main.joints or 0)) then main = p end
        end
    end
    out.root = main or obj
    local family = ((main and main.mesh) or ""):lower():match("^([^/]+/[^/]+)/")
    for _, p in ipairs(parts) do
        if p ~= main and usable(p) and (not family or (p.mesh or ""):lower():find(family, 1, true) == 1) then
            out.kids[#out.kids + 1] = p
        end
    end
    if B.allow_load and not no_load and not (out.root and out.root.holder) then
        -- (9.31) an object of that name is here but has no mesh (a placeholder): the model can still come from its files
        local okl, alt = pcall(CFG.load.find, want)
        if okl and alt then alt.scanned = out.scanned return alt end
    end
    return out
end

-- 9.25: the enemy object (a root named Em####) nearest to you becomes the object to copy. Placeholders (at the world origin, or with
-- no app.Em####Status component: Em6190, Em3300 in the dumps) are only used when nothing else is there.
function CFG.body.nearest_enemy()
    local B = CFG.body
    local lp = state.local_pos
    local best, best_d, live, live_d, seen = nil, nil, nil, nil, 0
    pcall(each_gameobject, function(go, path)
        local okn, nm = pcall(function() return go:call("get_Name") end)
        if okn and type(nm) == "string" and nm:match("^Em%d%d%d%d$") and path == "/" .. nm then
            seen = seen + 1
            local d, at_origin = 0, false
            pcall(function()
                local p = go:call("get_Transform"):call("get_Position")
                if lp then d = math.sqrt((p.x - lp.x) ^ 2 + (p.y - lp.y) ^ 2 + (p.z - lp.z) ^ 2) end
                at_origin = math.abs(p.x) < 0.01 and math.abs(p.y) < 0.01 and math.abs(p.z) < 0.01
            end)
            local has_status = false
            local okc, names = pcall(component_names, go)
            if okc then
                for _, cn in ipairs(names) do if cn:find("Status", 1, true) then has_status = true end end
            end
            if not best_d or d < best_d then best, best_d = nm, d end
            if has_status and not at_origin and (not live_d or d < live_d) then live, live_d = nm, d end
        end
        return false
    end, 20000)
    if not best then
        B.note("Nearest enemy: no object named Em#### in this scene (are you where an enemy is?)")
        return
    end
    local pick, pick_d = live or best, live and live_d or best_d
    B.model_src = pick
    B.note(string.format("Nearest enemy: %s, %.1f m away (%d enemy object(s) in the scene%s). It is now the object to copy; press 1 to look at it.", pick, pick_d or 0, seen,
        live and "" or "; none of them looks active, so this is just the nearest"))
end

-- Step 1 (read-only).
function CFG.body.look()
    local B = CFG.body
    local src = B.find()
    local r = src.root
    if not r then
        B.note(string.format("Look: no object named %s in this scene (%d objects looked at). Are you in the game, not in a menu?", src.name, src.scanned))
        return
    end
    if src.object and src.object ~= r then
        B.note(string.format("Look: %s has no mesh of its own (%s joints); its body is the part below", src.object.name, tostring(src.object.joints or "?")))
    end
    B.note(string.format("Look: %s | mesh %s | %s materials | %s joints | drawn %s", r.name, tostring(r.mesh), tostring(r.materials or "?"),
        tostring(r.joints or "?"), tostring(r.enabled)))
    for _, k in ipairs(src.kids) do
        B.note(string.format("Look:   part %s | mesh %s | %s joints | material holder %s", k.name, tostring(k.mesh), tostring(k.joints or "?"),
            k.material ~= nil and "yes" or "no"))
    end
    B.note(string.format("Look: %d drawn parts under %s object; mesh holder %s; material holder %s", #src.kids,
        src.name == B.SRC and "his" or (src.name .. "'s"), r.holder ~= nil and "yes" or "NO", r.material ~= nil and "yes" or "NO"))
    do -- (9.28) the cloth that hair is made of
        local list = { r }
        if src.object and src.object ~= r then list[#list + 1] = src.object end
        for _, k in ipairs(src.kids) do list[#list + 1] = k end
        pcall(B.cloth_probe, list)
    end
end

-- Put a mesh or material holder on my component: tries the setter names in turn and reads the result back. Returns the name that worked.
-- soft (9.32): the holder was made from a FILE. Such a holder reads back nothing until the game has loaded the file (9.31: Ethan's "neither
-- setMesh nor set_Mesh took the mesh", Clancy's "reads back nil"), so a call that did not throw counts (third answer: true = unconfirmed);
-- whether the mesh really arrived is B.ready()'s question, asked again and again until it does or the wait is over.
function CFG.body.give_resource(mc, setters, holder, getters, soft)
    local MP = CFG.mprobe
    local want = MP.text(holder)
    local first_ok
    for _, n in ipairs(setters) do
        local ok = pcall(function() mc:call(n, holder) end)
        local got = MP.text((MP.try(mc, getters)))
        if ok and (want == nil or got == want) then return n, got end
        if ok and soft and not first_ok then first_ok = n end
    end
    if first_ok then return first_ok, nil, true end
    return nil, nil
end

-- 9.32: is the body I made a body yet? A mesh made from a file is loaded by the game in its own time: right after setMesh the component says
-- MeshReady=false and has no joints (the 9.31 Clancy test), and parts attached to it THEN took the game down a frame later. Parts, the size
-- and the clips wait for this; a body made from the scene is ready at once (the Mia copy: MeshReady=true, 156 joints).
CFG.body.MIN_JOINTS = 10
function CFG.body.ready()
    local B, MP = CFG.body, CFG.mprobe
    if not (B.go and B.mc and B.xf) then return false, "there is no body", 0 end
    local mr = MP.try(B.mc, { "get_MeshReady" })
    local els = MP.joint_els(B.xf)
    local n = els and #els or 0
    if mr == false then return false, "the game has not finished loading the mesh (MeshReady is false)", n end
    if n < B.MIN_JOINTS then return false, "the mesh has no joints yet (" .. n .. ")", n end
    return true, nil, n
end

-- 9.32: is this part's mesh loaded? (A part with no readable MeshReady counts as ready: the scene's own parts always were.)
function CFG.body.part_ready(mc)
    local mr = CFG.mprobe.try(mc, { "get_MeshReady" })
    return mr ~= false
end

-- A new empty object (the first, the static create(System.String)).
function CFG.body.create(name)
    local go
    local ok, err = pcall(function()
        go = sdk.find_type_definition("via.GameObject"):get_method("create(System.String)"):call(nil, name)
    end)
    if not ok then return nil, tostring(err):sub(1, 120) end
    if go == nil then return nil, "the game answered nothing" end
    return go
end

-- Where I put it: 1 m to my right, on the floor where Ethan's feet are, facing the way I face.
function CFG.body.place(src_root, near_me)
    local B = CFG.body
    local okp, pos, quat = pcall(get_local_pose)
    local feet = src_root and src_root.xf and src_root.xf:call("get_Position")
    -- (9.25) a copy of something that is not me (an enemy) stands next to ME, not on top of the original
    if near_me and okp and pos then feet = { x = pos.x, y = pos.y - CFG.EYE_HEIGHT, z = pos.z } end
    if not (okp and pos and quat and feet) then B.note("Place: I can't read where you are") return false end
    local fx, _, fz = forward_of(quat)
    local l = math.sqrt(fx * fx + fz * fz)
    if l < 1e-3 then fx, fz = 0, 1 else fx, fz = fx / l, fz / l end
    -- right of (fx, fz) in this engine is (-fz, fx): the first try used (fz, -fx) and the body stood on the LEFT in the real game (9.23 test)
    local x, y, z = feet.x - fz * 1.0, feet.y, feet.z + fx * 1.0
    B.xf:call("set_Position", Vector3f.new(x, y, z))
    B.xf:call("set_EulerAngle", Vector3f.new(0, math.atan(fx, fz) + CFG.MODEL_YAW_OFFSET, 0))
    local back = B.xf:call("get_Position")
    B.note(string.format("Place: asked for %.2f %.2f %.2f; it reads %s", x, y, z,
        back and string.format("%.2f %.2f %.2f", back.x, back.y, back.z) or "nothing"))
    return true
end

-- Steps 2 and 3: make the object, give it a mesh component, Ethan's mesh and material, and stand it beside me.
function CFG.body.make()
    local B, MP = CFG.body, CFG.mprobe
    if B.go then B.note("Make: the body is already made (remove it first)") return true end
    local src = B.find()
    local r = src.root
    local other = src.name ~= B.SRC
    local who = other and (src.name .. "'s") or "Ethan's"
    if not (r and r.holder) then B.note("Make: " .. who .. " body mesh was not found, so nothing was made (press 1 and read the lines)") return false, "missing" end
    B.scene = B.scene_key()
    B.from_file = r.loaded_by_path == true and src.name or nil -- 9.32: this body is made from model FILES (CFG.load), not from an object of the scene
    if B.from_file then CFG.load.stand(B.from_file) end -- (written to loadstate.json now: a crash while it stands switches loading by path off at the next start)
    B.note("Make 1/4: creating an empty object named " .. B.NAME .. " (via.GameObject.create(System.String))", true)
    local go, why = B.create(B.NAME)
    if not go then B.note("Make 1/4 failed: " .. tostring(why), true) return false, "create" end
    B.go = go
    B.scale_applied, B.main_shown = nil, nil
    pcall(function() B.xf = go:call("get_Transform") end)
    B.note("Make 2/4: it exists" .. (B.xf and "" or " (no Transform read)") .. "; adding a render.Mesh component (createComponent)", true)
    local ok, err = pcall(function() B.mc = go:call("createComponent", sdk.typeof("via.render.Mesh")) end)
    if not ok or B.mc == nil then B.note("Make 2/4 failed: " .. (ok and "the game answered nothing" or tostring(err):sub(1, 120)), true) return false, "component" end
    B.note("Make 3/4: giving the component " .. (other and (src.name .. "'s") or "Ethan's") .. " mesh " .. tostring(r.mesh) .. (B.from_file and " (made from its file)" or ""), true)
    local used, got, unconfirmed = B.give_resource(B.mc, { "setMesh", "set_Mesh" }, r.holder, { "getMesh", "get_Mesh" }, B.from_file ~= nil)
    if used and unconfirmed then
        B.note("Make 3/4: " .. used .. " took it, but a mesh made from a file reads back nothing until the game has loaded it: waiting for that before anything is attached", true)
    else
        B.note(used and ("Make 3/4: " .. used .. " worked; it reads back " .. tostring(got)) or "Make 3/4: neither setMesh nor set_Mesh took the mesh", true)
    end
    if r.material ~= nil then
        local usedm, gotm = B.give_resource(B.mc, { "setMaterial", "set_Material" }, r.material, { "get_Material", "getMaterial" }, B.from_file ~= nil)
        B.note(usedm and ("Make 3/4: " .. usedm .. " took the material; it reads back " .. tostring(gotm)) or "Make 3/4: neither setMaterial nor set_Material took the material", true)
    end
    B.note("Make 4/4: standing it beside you", true)
    if B.xf then pcall(B.place, other and src.object or r, other) end
    local info = {}
    for _, g in ipairs({ "get_MeshReady", "get_MaterialReady", "get_Enabled", "get_DrawDefault", "get_HasJoint", "get_MaterialNum" }) do
        local v = MP.try(B.mc, { g })
        info[#info + 1] = g:gsub("^get_", "") .. "=" .. tostring(v)
    end
    local els = B.xf and MP.joint_els(B.xf)
    info[#info + 1] = "joints=" .. tostring(els and #els or "none")
    B.note("Make: the new mesh component says " .. table.concat(info, ", "), true)
    if not used then return false, "mesh" end
    return true
end

-- Step 4: the hands and the lower body, as children whose joints follow the body's.
CFG.body.PART_WAIT = 10 -- seconds a part made from a file may take to load before it is given up (9.32)
CFG.body.PART_RETRY = 5 -- (9.39) a part still not loaded after this many seconds is made again, once (as the enemy models' parts are since 9.37)

-- 9.32: the three calls that make a part a part of the body (parent, place, same joints). Only ever on a PARENT with joints and a part whose
-- own mesh is loaded: the 9.31 Clancy crash came a frame after these three ran on a body whose mesh was not loaded.
function CFG.body.join_part(rec)
    local B = CFG.body
    if rec.donor then -- 9.35: a part of Mia's corrupted model: only when its skeleton shares joints with the body (else it is taken away)
        if not B.donor_check(rec) then return end
        B.donor.joined = B.donor.joined + 1
    end
    local okp = pcall(function() rec.xf:call("set_Parent", B.xf) end)
    pcall(function() rec.xf:call("set_LocalPosition", Vector3f.new(0, 0, 0)) end)
    local okc = pcall(function() rec.xf:call("set_SameJointsConstraint", true) end)
    rec.joined = true
    B.note(string.format("Parts: %s: mesh %s, parent %s, same-joints %s", rec.name, rec.used or "NOT SET", okp and "set" or "NOT SET", okc and "set" or "NOT SET"), true)
    if rec.fallback and B.face then -- (9.32) Mia's own head is on the body
        B.face.joined = B.face.joined + 1
        B.face.last = "her own head is on the body (the game had loaded it)"
    end
end

-- Every frame (B.apply): the parts made from files join when their meshes are loaded, or are taken away again after PART_WAIT seconds.
function CFG.body.join_pending(now)
    local B = CFG.body
    if not B.go then return end
    for i = #B.kids, 1, -1 do
        local rec = B.kids[i]
        if rec.waiting and rec.mc and rec.xf then
            if B.part_ready(rec.mc) then
                rec.waiting = nil
                B.join_part(rec)
            elseif not rec.retried and not rec.fallback and rec.spec and now - rec.waiting > B.PART_RETRY then -- (Mia's own head keeps its 10 s: the scene's head is its fallback)
                -- (9.39) the same as for the enemy models (9.37): a part that is not loaded after PART_RETRY s is made again once; the game has the file cached by then.
                -- (9.38 test: Mia's chain hair was "not loaded after 10 s" and taken away, so she stood with no hair.)
                B.part_retried = (B.part_retried or 0) + 1
                B.note("Parts: " .. rec.name .. ": its mesh was not loaded after " .. B.PART_RETRY .. " s; made it again (once)", true)
                pcall(function() sdk.find_type_definition("via.GameObject"):get_method("destroy(via.GameObject)"):call(nil, rec.go) end)
                table.remove(B.kids, i)
                local nr = B.make_part(rec.spec, now, nil, rec.donor_spec)
                if nr then nr.retried = true end
            elseif now - rec.waiting > B.PART_WAIT then
                B.note("Parts: " .. rec.name .. ": its mesh was not loaded after " .. B.PART_WAIT .. " s, so it is taken away again (the body goes on without it)", true)
                pcall(function() sdk.find_type_definition("via.GameObject"):get_method("destroy(via.GameObject)"):call(nil, rec.go) end)
                table.remove(B.kids, i)
                -- (10.7) a part of the full model pack that is not from the pack (a hand, or a guess at one) and never loads: left out for the session, not tried at every make
                if CFG.pack and CFG.real and CFG.real.model then pcall(CFG.pack.drop, CFG.real.model, tostring(rec.name), "its mesh was not loaded after " .. B.PART_WAIT .. " s") end
                -- (9.32) Mia's own head that never loaded: the head the scene has (the corrupted one) is made instead, so she is not headless
                if rec.fallback then pcall(B.face_failed, rec.fallback, "its mesh was not loaded after " .. B.PART_WAIT .. " s", now) end
            end
        end
    end
    -- (10.10) every hand guess of a side was left out: the body is made again once so that it wears the borrowed hand for that side (CFG.pack.parts_of)
    local P = CFG.pack
    if P and P.remake_for then
        local fam = P.remake_for
        P.remake_for = nil
        local R = CFG.real
        if R and R.on and CFG.ids.family(R.model) == fam then
            B.note("Parts: " .. tostring(R.model) .. ": none of the hand files guessed for a side loaded; making the body again with the borrowed hand", true)
            pcall(R.retry)
        end
    end
end

-- (9.32) MIA'S OWN FACE ("Mia has the evil Mia face when she should have her own"). The 9.31 file shows her stand-in is a copy of the scene's Em2000,
-- the CORRUPTED Mia, with its head em2050. The playable Mia (Pl2000) has a head of her own, pl2050, with the same skeleton below the neck (253 joints
-- like em2050; the game keeps it as her "ShadowHead"). With this box ticked (the start: ticked) the corrupted head is not copied: the playable Mia's head
-- is loaded from its FILE (CFG.load) and joins the body when the game has loaded it, like any part made from a file. Nothing is risked for it: the head
-- (mesh AND material) has to load, or the scene's head is made as before; a head that is not loaded after PART_WAIT seconds is taken away and the
-- scene's head made instead; after one failure it is not tried again in this session. Whether pl2050 shows a proper face is for the owner's eyes
-- (unverified in the real game). face_scan is read-only: the heads of the scene with their mesh, material file and material names, and the engine's
-- material methods, for the next file.
--
-- (9.33) "thats mias head": her own head from her file (pl2050) drew BLACK in 9.32 (it is her "shadow head", the way Ethan's pl0050 is), so the box
-- for it (`on`) now starts UNticked and the scene's head (em2050) is used again. That head is one mesh with several "materials", the layers the game
-- switches between (the 9.32 file: em2050_Eye_Blend, em2050_Skin_Blend, em2050_Skin_Evil, em2050_Skin_Mia, Eye_Shadow, em2050_Hair, eye_Tear). The
-- copy shows what the scene's head showed (the corrupted skin), so here the layers are switched BY NAME with the engine's setMaterialsEnable: the
-- corrupted skin (Skin_Evil) and the blend between the two (Skin_Blend) off, her own skin (Skin_Mia) on, the rest as the game has them. `mats` is
-- the box for all of it; every layer has a tick box in the panel (saved by name in `shown`), and the debug file lists each layer's state before and
-- after, and the scene's own head's states, so the next build can be right. Unverified in the real game.
CFG.body.face = {
    on = false,
    MAP = { em2050 = { mesh = "Character/Player/pl2000/pl2050/pl2050.mesh", name = "Pl2000Head" } }, -- the corrupted head's mesh folder -> the head to use
    wanted = 0, made = 0, joined = 0, kept = 0, fell_back = 0, failed = 0, broken = nil, last = "not used yet",
    heads = {}, scanned = 0, scan_walked = 0, methods = nil, MAX_HEADS = 8, MAX_METHODS = 70,
    -- (9.33) the layers
    mats = true,                                  -- switch the layers of the scene's head (a box in the panel; off for good after a crash in it)
    LAYERED = { em2050 = true, pl2002 = true, pl2102 = true }, -- the heads (mesh folders) that have layers worth switching (10.4: the full model pack's Mia heads carry the em2050 layers too)
    vr_off = true,                                -- (10.4) the VR hands layer (a material named ..._VR) is hidden on a body that has hand parts of its own (a box in the panel)
    MAT_DEFAULT = { em2050_Skin_Evil = false, em2050_Skin_Blend = false, em2050_Skin_Mia = true }, -- layer name -> shown? (nothing else is touched)
    shown = {},                                   -- the player's own choices by layer name (saved), they win over MAT_DEFAULT
    mat_ver = 1,                                  -- raised when a choice changes: every head is put right again
    RECHECK = 3, TRIES = 120, MAX_LAYERS = 16, MAX_CHOICES = 16,
    seen = {}, rows = {}, rows_now = {}, writes = 0, set_errors = 0, mismatch = 0, errors = 0, mats_broken = nil, last_layers = "not used yet", last_error = nil,
}

-- Mia's own head instead of this scene head? Returns the part record (made from the head's file) or nil (the scene's head stays).
function CFG.body.face_for(k)
    local F = CFG.body.face
    local token = tostring(k.mesh or ""):lower():match("/(em%d%d50)/")
    local def = token and F.MAP[token]
    if not def then return nil end
    if not F.on then
        F.kept = F.kept + 1
        F.last = "her own head from her file is off (it drew black in 9.32): the head the scene has (" .. tostring(k.name) .. ") is copied and its layers are switched"
        return nil
    end
    if F.broken then
        F.kept = F.kept + 1
        F.last = "not tried again: " .. F.broken
        return nil
    end
    if not (CFG.load and CFG.load.on) then
        F.kept = F.kept + 1
        F.last = "loading models by path is off, so the scene's head (" .. tostring(k.name) .. ") is copied"
        return nil
    end
    F.wanted = F.wanted + 1
    local part, why = CFG.load.part(def.mesh, def.name)
    if not part then
        F.failed, F.broken = F.failed + 1, "her head's file did not load (" .. tostring(why) .. ")"
        F.last = F.broken .. ": the scene's head is copied"
        return nil
    end
    if part.material == nil then
        F.failed, F.broken = F.failed + 1, "her head's material file did not load (" .. tostring(part.material_path) .. ")"
        F.last = F.broken .. ": the scene's head is copied"
        return nil
    end
    return part
end

-- Her own head did not work: the scene's head is made instead (and her own is not tried again in this session).
function CFG.body.face_failed(orig, why, now)
    local B, F = CFG.body, CFG.body.face
    F.fell_back, F.broken = F.fell_back + 1, tostring(why):sub(1, 100)
    F.last = "her own head did not work (" .. F.broken .. "): the scene's head is used instead"
    B.note("Parts: Mia's own head did not work (" .. F.broken .. "): making the scene's head (" .. tostring(orig.name) .. ") instead", true)
    return B.make_part(orig, now or os.clock())
end

-- One part of the body: an object with a mesh component carrying the part's mesh and material, a child of the body whose joints follow the body's.
-- `fallback` (Mia's own head only): the scene part to make instead when this one can't be.
function CFG.body.make_part(k, now, fallback, donor)
    local B = CFG.body
    B.note("Parts: making " .. k.name .. " (" .. tostring(k.mesh) .. ") as a child of the body" .. (fallback and " (Mia's own head, made from its file)" or "")
        .. (donor and (" (Mia's " .. tostring(donor.role) .. " for her playable body)") or ""), true)
    local kg, why2 = B.create(B.NAME .. "_" .. k.name)
    if not kg then
        B.note("Parts: " .. k.name .. " not made: " .. tostring(why2), true)
        if fallback then B.face_failed(fallback, "the game made no object for it (" .. tostring(why2) .. ")", now) end
        return nil
    end
    local rec = { go = kg, name = k.name, shown = true, fallback = fallback, mesh = k.mesh, layered = B.face_layered(k.mesh), spec = k, donor_spec = donor }
    if donor then -- (9.35) a part of Mia's corrupted model on her playable body: its skeleton is checked before it joins
        rec.donor, rec.hair_role = donor, donor.role == "hair" -- (10.23: the part is a still mesh; the chain physics that used rec.orig_go was removed)
    end
    B.kids[#B.kids + 1] = rec
    pcall(function() rec.xf = kg:call("get_Transform") end)
    pcall(function() rec.mc = kg:call("createComponent", sdk.typeof("via.render.Mesh")) end)
    if rec.mc then
        rec.used = B.give_resource(rec.mc, { "setMesh", "set_Mesh" }, k.holder, { "getMesh", "get_Mesh" }, k.loaded_by_path == true)
        if k.material ~= nil then B.give_resource(rec.mc, { "setMaterial", "set_Material" }, k.material, { "get_Material", "getMaterial" }, k.loaded_by_path == true) end
        if fallback and not rec.used then -- the game took no mesh: this head is useless, take it away and make the scene's
            pcall(function() sdk.find_type_definition("via.GameObject"):get_method("destroy(via.GameObject)"):call(nil, kg) end)
            table.remove(B.kids)
            B.face_failed(fallback, "the game would not take the head's mesh", now)
            return nil
        end
        if rec.xf then
            if k.loaded_by_path == true and not B.part_ready(rec.mc) then
                rec.waiting = now -- joins in B.join_pending when the game has loaded its mesh
                B.note("Parts: " .. k.name .. ": mesh set; it joins the body when the game has loaded it", true)
            else
                B.join_part(rec)
            end
        end
    else
        B.note("Parts: " .. k.name .. " got no mesh component", true)
        if fallback then
            pcall(function() sdk.find_type_definition("via.GameObject"):get_method("destroy(via.GameObject)"):call(nil, kg) end)
            table.remove(B.kids)
            B.face_failed(fallback, "the head object got no mesh component", now)
            return nil
        end
    end
    if fallback then
        B.face.made = B.face.made + 1
        B.face.last = "her own head (" .. tostring(k.mesh) .. ") is made and waits for the game to load it; the scene's head is the fallback"
    end
    return rec
end

-- Read-only: the heads of this scene (an object called ...Head with a mesh): its mesh and material file, how many materials and their names, and
-- (once) the engine's material methods of the mesh component. Written to the debug file as health.body_lab.face.
function CFG.body.face_scan()
    local B, F, MP = CFG.body, CFG.body.face, CFG.mprobe
    local found, walked, sample = {}, 0, nil
    local ok, err = pcall(each_gameobject, function(go, path)
        walked = walked + 1
        if #found >= F.MAX_HEADS then return true end
        local okn, nm = pcall(function() return go:call("get_Name") end)
        if okn and type(nm) == "string" and nm:match("Head$") then
            local p = B.part(go, path)
            if p.mc and p.holder ~= nil then
                sample = sample or p.mc
                local e = { name = p.name, path = path:sub(1, 120), mesh = p.mesh, mdf = MP.text(p.material), materials = p.materials, enabled = p.enabled, material_names = {} }
                if type(p.materials) == "number" then
                    for i = 0, math.min(p.materials, 12) - 1 do
                        local mn = MP.try(p.mc, { "getMaterialName" }, i)
                        e.material_names[#e.material_names + 1] = mn ~= nil and (as_text(mn) or tostring(mn)) or "?"
                    end
                    -- (9.33) which layers the game itself shows on this head (read-only): the pattern to copy for her own face
                    e.material_enabled = {}
                    for i = 0, math.min(p.materials, 12) - 1 do
                        local en = MP.try(p.mc, { "getMaterialsEnable" }, i)
                        if type(en) ~= "boolean" then en = "?" end
                        e.material_enabled[#e.material_enabled + 1] = en
                    end
                end
                found[#found + 1] = e
            end
        end
        return false
    end, 20000)
    F.heads, F.scanned, F.scan_walked = found, F.scanned + 1, walked
    if not ok then F.scan_error = tostring(err):sub(1, 100) end
    if not F.methods then
        F.methods = {}
        pcall(function()
            local td = sdk.find_type_definition("via.render.Mesh")
            local list = {}
            for _, m in ipairs(td and td:get_methods() or {}) do
                local mname = tostring(m:get_name())
                if mname:lower():find("material", 1, true) then list[#list + 1] = mname .. method_signature(m) end
            end
            table.sort(list)
            for i = 1, math.min(#list, F.MAX_METHODS) do F.methods[i] = list[i] end
            if #list > F.MAX_METHODS then F.methods[#F.methods + 1] = string.format("(%d of %d shown)", F.MAX_METHODS, #list) end
        end)
    end
    B.note(string.format("Face scan: %d head object(s) with a mesh read (%d objects walked)", #found, walked))
    return #found
end

function CFG.body.face_line()
    local F = CFG.body.face
    return string.format("Mia's face: %s (own head made %d, joined %d, scene head used instead %d, kept as copied %d). Layers: %s%s", F.last, F.made, F.joined,
        F.fell_back, F.kept, F.last_layers, F.mats_broken and (" (switched off: " .. F.mats_broken .. ")") or "")
end

function CFG.body.face_report()
    local F = CFG.body.face
    return { on = F.on, last = F.last, own_head_file = F.MAP.em2050.mesh, wanted = F.wanted, made = F.made, joined = F.joined, scene_head_kept = F.kept,
        fell_back_to_the_scene_head = F.fell_back, failed_to_load = F.failed, not_tried_again_because = F.broken,
        heads_in_the_scene = F.heads, scans = F.scanned, objects_walked = F.scan_walked, scan_error = F.scan_error, engine_material_methods = F.methods,
        layers = { on = F.mats, switched_off_because = F.mats_broken, default = F.MAT_DEFAULT, my_choices = F.shown, last = F.last_layers, writes = F.writes,
            set_errors = F.set_errors, readback_differs = F.mismatch, errors = F.errors, last_error = F.last_error, seen = F.seen, per_head = F.rows, per_head_latest = F.rows_now,
            previous_session_ended_inside = tracer.face_suspect == true } }
end

-- (9.33) Is this mesh a head whose layers are switched? ("Character/Enemy/em2000/em2050/em2050.mesh": the scene's Mia head)
function CFG.body.face_layered(mesh)
    -- (10.4) every part is read for layers now (a head's skins, the VR hands that a body mesh carries as a material); a layer is only WRITTEN when there is a
    -- choice for it (the panel's boxes, the head defaults, the VR rule), so a part with none of those is only read
    return true
end

-- Shown (true), hidden (false) or left as the game has it (nil): the player's own choice for this layer, else the default.
function CFG.body.face_wanted(name)
    local F = CFG.body.face
    if F.shown[name] ~= nil then return F.shown[name] end
    if F.MAT_DEFAULT[name] ~= nil then return F.MAT_DEFAULT[name] end
    if F.vr_off and CFG.body.is_vr_layer(name) and not CFG.body.vr_layer_kept(name) and CFG.body.has_hand_parts() then return false end -- (10.4)
    -- (10.10 hid the pack's hand layer pl2020_Lhand once pl2020_hand had joined, and the 10.10 test showed Mia with NO left hand and a codex: the game's pl2020 (Pl2000HandL,
    -- 69 joints + the codex socket Codex_s, 2 materials) is her left ARM holding the codex, it has no hand of its own, and the hand is that layer. 10.11 keeps the layer shown.)
    return nil
end

-- (10.10) Has this part (by its name) joined the body? (made, loaded and attached: not still waiting)
function CFG.body.part_joined(part_name)
    for _, rec in ipairs(CFG.body.kids or {}) do
        if rec.name == part_name and rec.go ~= nil and not rec.waiting then return true end
    end
    return false
end

-- (10.4) THE VR HANDS. The player models carry a second set of hands as a MATERIAL of the body mesh (Ethan's pl0001 has pl0000_VR, Mia's pl2023 pl2000_VR),
-- drawn for VR mode. On a body that also has hand parts of its own (pl3010 / pl3020 ...) they are drawn OVER the normal hands: Clancy's hands looked wrong
-- ("the VR hands trying to display over the normal ones"). So a layer named ..._VR is switched off while the body has hand parts; a box per layer in
-- the panel says otherwise, and one box switches the rule off.
function CFG.body.is_vr_layer(name)
    local n = tostring(name or ""):lower()
    return n:match("_vr$") ~= nil or n:match("_vr_") ~= nil or n:match("^vr_") ~= nil
end

-- (10.9) A layer named ..._VR that is NOT a pair of VR hands, so the rule above leaves it alone: Joe's legs (pl9002_Leg_VR_m, "legs") and Mia's pl2000_VR,
-- which sits in her pl2023 part and is where her CHEST is (the other developer: "without pl2023 her chest and left hand were missing"; the 10.8 test
-- hid it with this rule and she had "a hole in her chest"). Your own box for a layer still wins.
function CFG.body.vr_layer_kept(name)
    local n = tostring(name or ""):lower()
    return n:find("leg", 1, true) ~= nil or n == "pl2000_vr"
end

function CFG.body.has_hand_parts()
    for _, rec in ipairs(CFG.body.kids or {}) do
        if tostring(rec.name or ""):lower():match("^pl%d%d[12]0$") and rec.go ~= nil then return true end
    end
    return false
end

-- A choice made in the panel or read from the settings: every head is put right again.
function CFG.body.face_set_layer(name, on)
    local F = CFG.body.face
    if type(name) ~= "string" or name == "" or #name > 60 or type(on) ~= "boolean" then return false end
    if F.shown[name] == nil then
        local n = 0
        for _ in pairs(F.shown) do n = n + 1 end
        if n >= F.MAX_CHOICES then return false end
    end
    F.shown[name] = on
    F.mat_ver = F.mat_ver + 1
    return true
end

-- The choices as a sorted text (the settings key) and as a copy (the settings file).
function CFG.body.face_choice_text()
    local list = {}
    for n, v in pairs(CFG.body.face.shown) do list[#list + 1] = n .. "=" .. tostring(v) end
    table.sort(list)
    return table.concat(list, ",")
end

function CFG.body.face_choice_copy()
    local out = {}
    for n, v in pairs(CFG.body.face.shown) do out[n] = v end
    return out
end

-- One head part: set the layers that have a choice, once the game has the head's materials, and read back what the engine says. A layer that was
-- changed is put back when the box for all of this is unticked. Only called for a part that has joined the body.
function CFG.body.face_materials(rec, now)
    local B, F, MP = CFG.body, CFG.body.face, CFG.mprobe
    rec.mat_at = now
    local active = F.mats and not F.mats_broken
    local n = MP.try(rec.mc, { "get_MaterialNum" })
    if type(n) ~= "number" or n < 1 then -- the game has not made the head's materials yet: asked again soon
        rec.mat_tries = (rec.mat_tries or 0) + 1
        if rec.mat_tries >= F.TRIES then
            rec.mat_gave_up = true
            F.last_layers = rec.name .. ": the game reported no materials, so no layer was switched"
        end
        return
    end
    n = math.min(n, F.MAX_LAYERS)
    pcall(tracer.crumb, "face", string.format("layers of %s (%d materials)", rec.name, n))
    if not rec.mat_names then
        rec.mat_names = {}
        for i = 0, n - 1 do
            local mn = MP.try(rec.mc, { "getMaterialName" }, i)
            rec.mat_names[i] = mn ~= nil and (as_text(mn) or tostring(mn)) or ("material " .. i)
        end
    end
    local rows, changed = {}, 0
    for i = 0, n - 1 do
        local name = rec.mat_names[i]
        local before = MP.try(rec.mc, { "getMaterialsEnable" }, i)
        if type(before) ~= "boolean" then before = nil end
        F.seen[name] = before == nil and "?" or before
        local want
        if active then
            want = B.face_wanted(name)
            if want == nil and rec.orig and rec.orig[i] ~= nil then want = rec.orig[i] end -- (10.4) a layer this switched off and nothing asks for any more (the VR rule unticked): back as it was
        elseif rec.orig then want = rec.orig[i] end
        local row = { i = i, name = name, was = before, want = want, now = before }
        rec.stuck = rec.stuck or {}
        -- (a layer the engine took the call for but did not keep is not written again until a choice changes)
        if want ~= nil and before ~= want and rec.stuck[i] ~= F.mat_ver then
            if active and before ~= nil then
                rec.orig = rec.orig or {}
                if rec.orig[i] == nil then rec.orig[i] = before end
            end
            local ok = pcall(function() rec.mc:call("setMaterialsEnable", i, want) end)
            F.writes, changed, row.set = F.writes + 1, changed + 1, ok
            local after = MP.try(rec.mc, { "getMaterialsEnable" }, i)
            if type(after) == "boolean" then row.now = after else row.now = nil end
            if not ok then
                F.set_errors = F.set_errors + 1
                if F.set_errors >= 3 then F.mats_broken = "setMaterialsEnable failed " .. F.set_errors .. " times" end
            elseif row.now ~= nil and row.now ~= want then
                F.mismatch = F.mismatch + 1
                rec.stuck[i] = F.mat_ver
            end
        end
        rows[#rows + 1] = row
    end
    if not active then rec.orig = nil end -- (everything that was changed has been put back)
    rec.mat_ver = F.mat_ver
    if changed > 0 or not F.rows[rec.name] then F.rows[rec.name] = rows end -- the pass that changed something (the first, until a choice changes)
    F.rows_now[rec.name] = rows -- the latest pass
    F.last_layers = string.format("%s: %d layers read, %d changed%s", rec.name, n, changed, active and "" or " back (the box is off)")
    if changed > 0 then
        local ch = {}
        for _, rw in ipairs(rows) do
            if rw.set ~= nil then ch[#ch + 1] = string.format("%s %s->%s", tostring(rw.name), rw.was == nil and "?" or (rw.was and "on" or "off"), rw.now == nil and "?" or (rw.now and "on" or "off")) end
        end
        B.note("Face: " .. F.last_layers .. " (" .. table.concat(ch, ", "):sub(1, 200) .. ")", true) -- (10.9) which ones
    end
    if not rec.layers_told then -- (10.9) every layer of the part once, with its state: "a hole in her chest" can be read off this
        rec.layers_told = true
        local all = {}
        for _, rw in ipairs(rows) do all[#all + 1] = string.format("%s=%s", tostring(rw.name), rw.now == nil and "?" or (rw.now and "on" or "off")) end
        B.note("Face: " .. tostring(rec.name) .. " layers: " .. table.concat(all, ", "):sub(1, 300), true)
    end
    pcall(tracer.crumb, "clean", "head layers set")
end

-- Every frame (B.apply): a head with layers gets them set when it has joined the body (and again when a choice changes, and now and then in
-- case the game changed them back).
function CFG.body.face_materials_tick(now)
    local B, F = CFG.body, CFG.body.face
    local active = F.mats and not F.mats_broken
    local function one(rec)
        if rec.layered and rec.mc and rec.joined and not rec.waiting and not rec.mat_gave_up and (active or rec.orig) then
            local due = rec.mat_ver ~= F.mat_ver and 0.25 or F.RECHECK
            if now - (rec.mat_at or -100) >= due then
                local ok, err = pcall(B.face_materials, rec, now)
                if not ok then
                    rec.mat_at, F.errors, F.last_error = now, F.errors + 1, tostring(err):sub(1, 100)
                    if F.errors >= 3 then F.mats_broken = "errors: " .. F.last_error end
                end
            end
        end
    end
    -- (10.4) the body's own mesh first (its VR hands are one of its materials), then the parts
    if B.mc and B.go then
        local rr = B.root_rec
        if rr == nil or rr.mc ~= B.mc then
            rr = { name = "body", mc = B.mc, layered = true, joined = true }
            B.root_rec = rr
        end
        one(rr)
    else
        B.root_rec = nil
    end
    for _, rec in ipairs(B.kids) do one(rec) end
end

----------------------------------------------------------------------------------------------
-- (9.35) MIA'S HEAD AND HAIR ON HER PLAYABLE BODY. The playable characters have no head that is drawn (the game keeps pl2050 as a shadow-only
-- head, and it drew black in 9.32), so Mia made from her own files (Pl2000: body, hands, legs, which "works better" and has its textures) stood
-- there headless. The head with a face and her hair belong to the corrupted Mia's files (Em2000): em2050 (253 joints; its Eye / Skin / Hair
-- layers are the ones switched by name, "the right Mia settings") and em2070 (the chain hair, 179 joints). They are put on her body as parts,
-- like the hands: the scene's own Em2000Head / Em2000ChainHair when the scene has them (they share the textures the game has loaded), else from
-- their files (CFG.load, when loading by path is on). The hair parts em2071 L/R are not added: they are GpuCloth meshes that draw as flat white
-- shards without the cloth (the 9.34 screenshot).
-- The skeleton check comes first: a part follows the body only through the joints they share by NAME (Chest, Neck, Head and the shoulders: 7
-- for both pl2001 and em2000 in the 9.34 data), so a part that shares fewer than SHARED_MIN joints with the body is taken away again and the
-- body goes on without it (the debug file lists the counts). Unverified in the real game.
----------------------------------------------------------------------------------------------
CFG.body.DONORS = {
    pl2000 = {
        { name = "Em2000Head", mesh = "Character/Enemy/em2000/em2050/em2050.mesh", role = "head" },
        { name = "Em2000ChainHair", mesh = "Character/Enemy/em2000/em2070/em2070.mesh", role = "hair" },
    },
}
CFG.body.DONORS.pl2100 = CFG.body.DONORS.pl2000
CFG.body.donor = { on = true, made = 0, joined = 0, refused = 0, from_scene = 0, from_file = 0, missing = 0, last = "not used yet", SHARED_MIN = 4, rows = {}, log = {}, MAX_LOG = 12 }

-- What happened to one donor part: the latest in D.last, every one in D.log (the debug file), in the order it happened.
function CFG.body.donor_note(text)
    local D = CFG.body.donor
    D.last = tostring(text):sub(1, 240)
    D.log[#D.log + 1] = D.last
    while #D.log > D.MAX_LOG do table.remove(D.log, 1) end
end

-- The panel's line: the counts first (a part taken away for its skeleton must not be hidden by the next part's message), then the latest event.
function CFG.body.donor_line()
    local D = CFG.body.donor
    return string.format("%s. Made %d, joined %d, taken away for their skeleton %d, not added %d. %s", D.on and "On" or "Off", D.made, D.joined, D.refused, D.missing, D.last)
end

-- The joint names of a transform as a set, and how many joints it has.
function CFG.body.joint_set(xf)
    local MP = CFG.mprobe
    local els = MP.joint_els(xf)
    local set, n = {}, 0
    for _, j in ipairs(els or {}) do
        n = n + 1
        local nm = MP.text(MP.try(j, { "get_Name", "getName" }))
        if nm then set[nm] = true end
    end
    return set, n
end

-- How many joint names the part and the body have in common (nil when a list can not be read), then their joint counts.
function CFG.body.shared_joints(part_xf, body_xf)
    local ok1, a, na = pcall(CFG.body.joint_set, part_xf)
    local ok2, b, nb = pcall(CFG.body.joint_set, body_xf)
    if not (ok1 and ok2) then return nil end
    local shared = 0
    for nm in pairs(a) do if b[nm] then shared = shared + 1 end end
    return shared, na, nb
end

-- The scene's own objects by exact name -> part records (B.part: mesh holder, material holder ...), in ONE walk. Only objects that carry a mesh.
function CFG.body.scene_parts(names)
    local B = CFG.body
    local want, left, found = {}, 0, {}
    for _, n in ipairs(names) do
        if not want[n] then want[n], left = true, left + 1 end
    end
    pcall(each_gameobject, function(go, path)
        local okn, nm = pcall(function() return go:call("get_Name") end)
        if okn and want[nm] and not found[nm] then
            local p = B.part(go, path)
            if p.mc and p.holder ~= nil then
                found[nm] = p
                left = left - 1
                if left <= 0 then return true end
            end
        end
        return false
    end, 20000)
    return found
end

-- One donor part: the scene's own when the scene has it, else made from its file. Returns the part record, or nil and why.
function CFG.body.donor_part(d, scene)
    local D = CFG.body.donor
    local p = scene and scene[d.name]
    if p then
        D.from_scene = D.from_scene + 1
        return p, "the scene's own " .. d.name
    end
    if CFG.load and CFG.load.on then
        local part, why = CFG.load.part(d.mesh, d.name)
        if part and part.material ~= nil then
            D.from_file = D.from_file + 1
            return part, "its file " .. d.mesh
        end
        return nil, "its file did not load (" .. tostring(why or "no material file") .. ")"
    end
    return nil, "it is not in this scene and loading by path is off"
end

-- Called from add_parts for a model that has donors (Mia's playable body). Returns how many parts were made.
function CFG.body.add_donors(src, now)
    local B, D = CFG.body, CFG.body.donor
    if not D.on then D.last = "off (the box in the panel)" return 0 end
    if src and src.from_pack then D.last = "not needed: the full model pack's body has its own head and hair" return 0 end -- (10.1)
    local fam = CFG.ids.family(src and src.name or "")
    local list = fam and B.DONORS[fam]
    if not list then return 0 end
    local names = {}
    for _, d in ipairs(list) do names[#names + 1] = d.name end
    local scene = B.scene_parts(names)
    local n = 0
    for _, d in ipairs(list) do
        local have = false
        for _, k in ipairs(B.kids) do if k.name == d.name then have = true end end
        if not have then
            local part, how = B.donor_part(d, scene)
            if part then
                B.donor_note(d.name .. " made from " .. how) -- (before: a part taken away for its skeleton says so after this, in the order it happened)
                local rec = B.make_part(part, now, nil, d)
                if rec then n, D.made = n + 1, D.made + 1 end
            else
                D.missing = D.missing + 1
                B.donor_note(d.name .. " not added: " .. tostring(how))
                B.note("Parts: " .. d.name .. " (Mia's head / hair) not added: " .. tostring(how), true)
            end
        end
    end
    return n
end

-- Called when a donor part is about to join the body: does its skeleton fit? If not, the part is destroyed and false is returned.
function CFG.body.donor_check(rec)
    local B, D = CFG.body, CFG.body.donor
    local shared, np, nb = B.shared_joints(rec.xf, B.xf)
    D.rows[rec.name] = { shared_joints = shared, part_joints = np, body_joints = nb }
    if shared ~= nil and shared >= D.SHARED_MIN then return true end
    D.refused = D.refused + 1
    B.donor_note(string.format("%s taken away: it shares %s joint names with the body (the part has %s joints, the body %s)", rec.name, tostring(shared), tostring(np), tostring(nb)))
    B.note("Parts: " .. D.last, true)
    pcall(function() sdk.find_type_definition("via.GameObject"):get_method("destroy(via.GameObject)"):call(nil, rec.go) end)
    for i = #B.kids, 1, -1 do
        if B.kids[i] == rec then table.remove(B.kids, i) end
    end
    return false
end

function CFG.body.donor_report()
    local D = CFG.body.donor
    local names = {}
    for _, d in ipairs(CFG.body.DONORS.pl2000) do names[#names + 1] = d.name .. " = " .. d.mesh end
    return { on = D.on, last = D.last, parts = names, made = D.made, joined = D.joined, taken_away_for_a_bad_skeleton = D.refused, from_the_scene = D.from_scene,
        from_files = D.from_file, not_added = D.missing, shared_joints_needed = D.SHARED_MIN, per_part = D.rows, log = D.log }
end

-- (10.23) Mia's hair physics was removed (EXPERIMENTAL, it shipped unticked: a via.motion.Chain copied onto the copy of her chain hair). The real
-- Mia can now be moved to where she is wanted (enemy mode 3), so a copy no longer needs hair of its own. Her chain hair is still added as a still
-- mesh by the head parts above. 'Hide hair parts' (the real body's box) is a different thing and stays.

function CFG.body.add_parts()
    local B = CFG.body
    if not B.go or not B.xf then B.note("Parts: make the body first") return end
    if #B.kids > 0 then B.note("Parts: they are already added") return end
    -- 9.32: never onto a body that is not ready (no mesh loaded, no joints)
    local okr, ready, why = pcall(B.ready)
    if not okr or not ready then
        B.note("Parts: not added: the body is not ready (" .. tostring(okr and why or ready) .. "). Parts attached to a body whose mesh was not loaded took the game down in 9.31.", true)
        return false
    end
    local src = B.find()
    local now = os.clock()
    local saw_head = false
    for _, k in ipairs(src.kids) do
        if k.holder ~= nil then
            if tostring(k.mesh or ""):lower():find("/em%d%d50/") then saw_head = true end
            local own = B.face_for(k) -- (9.32) Mia's own head, or nil: the scene's part is made as it always was
            if own then B.make_part(own, now, k) else B.make_part(k, now) end
        end
    end
    pcall(B.add_donors, src, now) -- (9.35) her playable body gets the corrupted Mia's head and chain hair (the skeleton is checked when they join)
    if saw_head then pcall(B.face_scan) end -- (read-only) what the heads of this scene are made of, for the debug file
    B.note("Parts: " .. #B.kids .. " added", true)
end

-- Step 6: take everything down again (children first). Also what the script reset does.
function CFG.body.remove()
    local B = CFG.body
    B.follow, B.hold = false, false
    if CFG.wmesh then pcall(CFG.wmesh.drop, "the body is being taken down") end -- (10.15) the weapon on its hand goes first (a copy left behind stays stuck on the next body)
    if B.joint_obj and B.base then pcall(function() B.joint_obj:call("set_LocalEulerAngle", Vector3f.new(B.base[1], B.base[2], B.base[3])) end) end
    B.joint_obj, B.joint_name, B.base = nil, nil, nil
    local function destroy(go, label)
        local ok, err = pcall(function()
            sdk.find_type_definition("via.GameObject"):get_method("destroy(via.GameObject)"):call(nil, go)
        end)
        B.note("Remove: " .. label .. (ok and " destroyed" or (" not destroyed: " .. tostring(err):sub(1, 80))), true)
    end
    for _, k in ipairs(B.kids) do destroy(k.go, k.name) end
    if B.go then destroy(B.go, B.NAME) end
    B.go, B.xf, B.mc, B.kids, B.scene = nil, nil, nil, {}, nil
    if B.from_file then B.from_file = nil CFG.load.clear("the body was taken down") end -- (9.32) a body made from files is no longer up
end

-- The scene changed under me: the game took the objects down with it, so the references are dropped and never used.
function CFG.body.guard()
    local B = CFG.body
    if not B.go or not B.scene then return end
    local now_key = B.scene_key()
    if now_key ~= nil and now_key ~= B.scene then
        B.note("The scene changed: the game took my objects down with it, so I let go of them (nothing is destroyed by me)")
        if CFG.wmesh then pcall(CFG.wmesh.forget, "the scene changed") end -- (10.15)
        B.go, B.xf, B.mc, B.kids, B.scene = nil, nil, nil, {}, nil
        B.follow, B.hold, B.joint_obj, B.joint_name, B.base = false, false, nil, nil, nil
        B.dropped = B.dropped + 1
        if B.from_file then B.from_file = nil CFG.load.clear("the scene changed") end
    end
end

-- 9.28: the body's size. Only written when it changed (and once after the body is made).
function CFG.body.apply_scale()
    local B = CFG.body
    if not B.xf then return end
    local v = B.scale
    if type(v) ~= "number" or v ~= v then v = 1 end
    v = math.max(B.SCALE_MIN, math.min(B.SCALE_MAX, v))
    B.scale_applied = B.scale
    local ok, err = pcall(function() B.xf:call("set_LocalScale", Vector3f.new(v, v, v)) end)
    if ok then
        B.scale_shown = v
    else
        B.errors = B.errors + 1
        B.note("Size: the game would not take a scale of " .. string.format("%.2f", v) .. " (" .. tostring(err):sub(1, 80) .. ")", true)
    end
end

-- 9.28: how tall a model is: the height of its Head (or Neck) joint above the object's own position, with its scale taken out.
function CFG.body.height_of(xf)
    local out
    pcall(function()
        local feet = xf:call("get_Position").y
        local sc = 1
        pcall(function()
            local s = xf:call("get_LocalScale")
            if s and type(s.y) == "number" and s.y > 0.05 then sc = s.y end
        end)
        for _, nm in ipairs({ "Head", "Neck" }) do
            local j = xf:call("getJointByName", nm)
            if j then
                local y = j:call("get_Position").y - feet
                if type(y) == "number" and y > 0.3 and y < 4 then
                    out = { h = y / sc, joint = nm }
                    return
                end
            end
        end
    end)
    return out
end

-- 9.28: set the scale so the copy is as tall as Ethan (he must be in the scene and standing). 9.29: returns true when the size was set.
function CFG.body.match_height()
    local B = CFG.body
    if not (B.go and B.xf) then B.note("Height: make the body first") return false end
    local src = CFG.clip.sources()
    local ex = src.body and src.body.xf
    if not ex then B.note("Height: Ethan's object was not found here (are you in the game, not in a menu?)") return false end
    local he, hm = B.height_of(ex), B.height_of(B.xf)
    if not he then B.note("Height: could not read Ethan's Head height; use the slider") return false end
    if not hm then B.note("Height: could not read the copy's Head height; use the slider") return false end
    local v = math.max(B.SCALE_MIN, math.min(B.SCALE_MAX, he.h / hm.h))
    B.scale = math.floor(v * 1000 + 0.5) / 1000
    B.note(string.format("Height: Ethan's %s is %.2f m up, the copy's %s %.2f m (at size 1): size set to %.3f. Stand up straight first; crouching gives a smaller number.",
        he.joint, he.h, hm.joint, hm.h, B.scale))
    return true
end

-- 9.29: the rest pose of the body I made: every joint's local angles BEFORE a clip is played on it. The copy has no animation of its own,
-- so this is the model's own bind pose. Ethan's clips are absolute angles by joint name; if a model's bind pose differs from Ethan's (Mia's
-- may), the clips pull it out of shape. Read it for Ethan and for Mia and the two can be compared (re7mp/rest_<model>.json, and the
-- debug file's real_body section).
function CFG.body.read_rest()
    local B, C = CFG.body, CFG.clip
    if not (B.go and B.xf) then B.note("Rest pose: make the body first") return nil end
    local model = (type(B.model_src) == "string" and B.model_src ~= "") and B.model_src or B.SRC
    local rest = { model = model, build = CFG.BUILD, joints = {}, missing = {}, n = 0, scale = B.scale }
    for _, nm in ipairs(C.names(nil)) do -- (one joint at a time: a joint the model lacks must not stop the others)
        local okj, j, e = pcall(function()
            local jj = B.xf:call("getJointByName", nm)
            return jj, jj and jj:call("get_LocalEulerAngle")
        end)
        if okj and e and type(e.x) == "number" then
            rest.joints[nm] = { C.q(e.x), C.q(e.y), C.q(e.z) }
            rest.n = rest.n + 1
            if nm == "Hip" then
                local okp, p = pcall(function() return j:call("get_LocalPosition") end)
                if okp and p and type(p.x) == "number" then rest.hip = { C.q(p.x), C.q(p.y), C.q(p.z) } end
            end
        else
            rest.missing[#rest.missing + 1] = nm
        end
    end
    local h = B.height_of(B.xf)
    if h then rest.head_height = math.floor(h.h * 1000 + 0.5) / 1000 rest.head_joint = h.joint end
    B.rest = rest
    local rname = "rest_" .. model:gsub("[^%w_]", "_"):sub(1, 40) .. ".json"
    local ok, file = CFG.save_json("re7mp/" .. rname, "re7mp_" .. rname, rest)
    B.note(string.format("Rest pose: %d of %d joints read for %s%s; written as %s%s", rest.n, #C.names(nil), model,
        h and string.format(" (head %.2f m up at size 1)", h.h) or "", ok and file or ("re7mp/" .. rname),
        ok and "" or (" (NOT written: " .. tostring(file):sub(1, 50) .. ")")))
    return rest
end

-- 9.28: show or hide one part of the body (set_Enabled on its mesh component, or DrawDefault if that is refused).
function CFG.body.set_shown(mc, on)
    local ok = pcall(function() mc:call("set_Enabled", on) end)
    if not ok then ok = pcall(function() mc:call("set_DrawDefault", on) end) end
    return ok
end

function CFG.body.apply_hidden()
    local B = CFG.body
    if B.mc then
        local want = not B.hidden[B.MAIN]
        if B.main_shown == nil then B.main_shown = true end
        if B.main_shown ~= want then
            B.main_shown = want
            if not B.set_shown(B.mc, want) then B.errors = B.errors + 1 B.note("Parts: could not " .. (want and "show" or "hide") .. " the main body", true) end
        end
    end
    for _, k in ipairs(B.kids) do
        if k.mc then
            local want = not B.hidden[k.name]
            if k.shown == nil then k.shown = true end
            if k.shown ~= want then
                k.shown = want
                if not B.set_shown(k.mc, want) then B.errors = B.errors + 1 B.note("Parts: could not " .. (want and "show" or "hide") .. " " .. k.name, true) end
            end
        end
    end
end

-- The names that are hidden, sorted (settings and the debug file).
function CFG.body.hidden_list()
    local out = {}
    for n, v in pairs(CFG.body.hidden) do if v then out[#out + 1] = n end end
    table.sort(out)
    return out
end

-- 9.28: hair is cloth. Writes down the cloth / dynamics components of the original's parts and their fields, so the next build can
-- copy them. (A copy made of mesh components has none of this, which is why Mia's hair hangs still and is shaded wrongly.)
function CFG.body.cloth_probe(parts)
    local B = CFG.body
    local n, total = 0, 0
    for _, p in ipairs(parts) do
        if p and p.go then
            pcall(function()
                for _, c in ipairs(p.go:call("get_Components"):get_elements()) do
                    local tn = c:get_type_definition():get_full_name()
                    local low = tn:lower()
                    if low:find("cloth", 1, true) or low:find("dynamics.", 1, true) or low:find("spring", 1, true) or low:find("chain", 1, true) then
                        total = total + 1
                        if n < 8 then
                            n = n + 1
                            B.note(string.format("Look: cloth: %s has %s (the copy gets none of this)", tostring(p.name), tn))
                            pcall(dump_fields, c, "        ", 24)
                        end
                    end
                end
            end)
        end
    end
    B.note(string.format("Look: %d cloth / dynamics component(s) found on the original's parts%s", total, total > n and (" (" .. n .. " written out)") or ""))
end

-- Every frame of the chosen game phase: follow the other player; hold the chosen joint turned by the chosen angle.
-- 9.30 ("crouching animation puts player too far into floor"): the body stood at (camera height - 1.6 m) whatever they did. A crouch sinks the
-- camera by about CROUCH_DROP, and a clip that carries the Hip's position (every clip recorded since 9.26) lowers the hips by itself: the
-- crouch clip's Hip is 0.38 m up against 0.99 m standing, so the hips ended up 0.12 m BELOW the floor. While such a clip plays, the body is
-- stood back up by how far the camera sank, so its feet stay on the floor. A clip without a hip position (the legs only bend) keeps the old rule.
-- (10.4) metres a body is stood up per character (the other developer's mod found Zoe's feet in the ground by 0.04)
CFG.body.LIFT = { pl3400 = 0.04 }
function CFG.body.model_lift()
    local fam = CFG.ids.family((CFG.real and CFG.real.built_model) or "")
    return fam and CFG.body.LIFT[fam] or 0
end

function CFG.body.crouch_lift()
    local B = CFG.body
    local C = CFG.clip
    local P = C and C.P
    local clip = P and P.clip
    if not (C and C.play and clip and clip.body and clip.body.hip and P.hipj and not P.hip_off) then return 0 end
    local cr = math.max(0, math.min(1, (state.pose and state.pose.crouch) or 0))
    -- (10.9) Ethan's friend: its camera is pinned at the STANDING height above its floor (CFG.friend.body.adjust), so nothing sank and nothing has to be put back:
    -- the 10.8 build stood it up by CROUCH_DROP (0.5 m) + the slider anyway, which is why it floated ("he is still flying a bit"). Its own slider adds to nothing.
    local FBl = CFG.friend and CFG.friend.body
    if FBl and FBl.own_on() then
        -- (10.10) ... and the 10.9 number was too small ("the model goes into the ground"): the friend's feet are measured and put on the floor; the slider is a fine tune on top
        local lift = (CFG.friend.crouch_lift or 0) * cr
        local G = CFG.friend.ground
        if G and G.on and B.xf then
            local okg, g = pcall(G.update, B.xf, cr, os.clock())
            if okg and type(g) == "number" then lift = lift + g end
        end
        return lift
    end
    return (CFG.CROUCH_DROP + (B.crouch_extra or 0)) * cr
end

function CFG.body.apply(now)
    local B = CFG.body
    if not B.go or not B.xf then return end
    if B.scale_applied ~= B.scale then B.apply_scale() end
    pcall(B.join_pending, now) -- 9.32: parts made from files join when their meshes are loaded
    pcall(B.apply_hidden)
    pcall(B.face_materials_tick, now) -- 9.33: the layers of Mia's head
    if B.follow then
        local pos, fwd = state.render_pos, state.render_fwd
        if pos and fwd and state.remote then
            local ok, err = pcall(function()
                local hidden = remote_hidden(now) ~= nil or state.show_figure == false -- (9.29: "Show other player" off hides the real body too)
                local lowh = CFG.low and CFG.low.remote(now) or nil -- (10.12) crawling / lying: stood on the floor the sender measured
                local by
                if lowh then
                    by = pos.y - lowh + B.model_lift()
                    CFG.low.applied = CFG.low.applied + 1
                else
                    by = pos.y - CFG.EYE_HEIGHT + B.crouch_lift() + B.model_lift()
                end
                B.xf:call("set_Position", Vector3f.new(pos.x, hidden and -10000 or by, pos.z))
                B.xf:call("set_EulerAngle", Vector3f.new(0, math.atan(fwd[1], fwd[3]) + CFG.MODEL_YAW_OFFSET, 0))
            end)
            if not ok then B.follow = false B.errors = B.errors + 1 B.note("Follow stopped: " .. tostring(err):sub(1, 100), true) end
        end
    end
    if B.hold then
        local ok, err = pcall(function()
            if B.joint_obj == nil or B.joint_name ~= B.joint then
                B.joint_name, B.joint_obj, B.base = B.joint, B.xf:call("getJointByName", B.joint), nil
                if B.joint_obj then
                    local e = B.joint_obj:call("get_LocalEulerAngle")
                    B.base = { e.x, e.y, e.z }
                    B.note("Pose: joint " .. B.joint .. " found; its local angles are " .. string.format("%.2f %.2f %.2f", e.x, e.y, e.z), true)
                else
                    B.note("Pose: no joint named " .. B.joint, true)
                    B.hold = false
                end
            end
            if B.joint_obj and B.base then
                local a = { B.base[1], B.base[2], B.base[3] }
                a[B.axis] = a[B.axis] + math.rad(B.deg)
                B.joint_obj:call("set_LocalEulerAngle", Vector3f.new(a[1], a[2], a[3]))
            end
        end)
        if not ok then B.hold = false B.errors = B.errors + 1 B.note("Pose stopped: " .. tostring(err):sub(1, 100), true) end
    elseif B.joint_obj and B.base then -- unticked: put the joint back
        pcall(function() B.joint_obj:call("set_LocalEulerAngle", Vector3f.new(B.base[1], B.base[2], B.base[3])) end)
        B.joint_obj, B.joint_name, B.base = nil, nil, nil
    end
end

-- Steps wait here for the chosen game phase; a phase that never comes is reported after WAIT seconds.
function CFG.body.later(label, fn)
    local B = CFG.body
    B.queue[#B.queue + 1] = { label = label, fn = fn, at = os.clock() }
    B.register()
    B.note(string.format("%s: waiting for the game phase %s", label, B.PHASES[B.phase]))
end

function CFG.body.tick(phase)
    local B = CFG.body
    if B.PHASES[B.phase] ~= phase then return end
    B.ticks = B.ticks + 1
    local t0 = os.clock()
    CFG.perf.lap_t = t0
    if #B.queue > 0 then
        local q = B.queue
        B.queue = {}
        for _, w in ipairs(q) do
            local ok, err = pcall(w.fn)
            if not ok then B.errors = B.errors + 1 B.note(w.label .. ": error " .. tostring(err):sub(1, 120), true) end
        end
        pcall(CFG.perf.lap, "phase: queued steps") -- (10.20: the game-phase tick in laps, so a file says which of its six parts is slow)
    end
    pcall(B.guard)
    pcall(B.apply, os.clock())
    pcall(CFG.perf.lap, "phase: body guard + apply")
    if CFG.gmot then pcall(CFG.gmot.tick, os.clock()) end -- (10.2: the game's own clips, before the recorded one would be played)
    pcall(CFG.perf.lap, "phase: the game's clips")
    pcall(CFG.clip.tick, os.clock())
    pcall(CFG.perf.lap, "phase: recorded clips")
    if CFG.pup then pcall(CFG.pup.tick, os.clock()) end -- (9.31: the enemy models stand where their enemies are)
    pcall(CFG.perf.lap, "phase: enemy models")
    if CFG.wmesh then pcall(CFG.wmesh.tick, os.clock()) end -- (10.15: the other player's weapon on their body)
    pcall(CFG.perf.lap, "phase: weapon mesh")
    -- (9.36: the game-phase work is timed on its own; the "UI frame" choice runs inside the frame callback, which times it as "body frame")
    if phase ~= "UI frame" then pcall(CFG.perf.add, "game-phase tick (" .. tostring(phase) .. ")", os.clock() - t0) end
end

-- Called from the render frame: the "UI frame" choice runs here, and every choice gives up on a step whose phase never comes.
function CFG.body.frame(now)
    local B = CFG.body
    if #B.queue > 0 then
        for i = #B.queue, 1, -1 do
            if now - B.queue[i].at > B.WAIT then
                B.note(B.queue[i].label .. ": the game phase " .. B.PHASES[B.phase] .. " did not come within " .. B.WAIT .. " s; giving up on it")
                table.remove(B.queue, i)
            end
        end
    end
    B.tick("UI frame")
end

function CFG.body.register()
    local B = CFG.body
    if B.registered then return end
    B.registered = true
    if not re.on_pre_application_entry then
        B.note("this REFramework has no re.on_pre_application_entry: only the \"UI frame\" choice can work")
        return
    end
    for _, nm in ipairs({ "UpdateBehavior", "LockScene" }) do
        local ok = pcall(re.on_pre_application_entry, nm, function() CFG.body.tick(nm) end)
        if not ok then B.note("could not register for the game phase " .. nm) end
    end
end

function CFG.body.report()
    local B = CFG.body
    return { enabled = B.enabled, copying = (type(B.model_src) == "string" and B.model_src ~= "") and B.model_src or B.SRC,
        made = B.go ~= nil, parts = #B.kids, follow = B.follow, hold = B.hold, joint = B.joint, axis = B.AXES[B.axis], deg = B.deg,
        phase = B.PHASES[B.phase], ticks = B.ticks, errors = B.errors, dropped_with_scene = B.dropped, queued = #B.queue, lines = B.lines, parts_made_again_after_s = B.PART_RETRY, parts_made_again = B.part_retried or 0,
        size = B.scale, size_in_game = B.scale_shown, hidden_parts = B.hidden_list(), rest_joints = B.rest and B.rest.n or nil,
        face = B.face_report(), -- (9.32) Mia's own head, and what the heads of the scene are made of
        mia_head_parts = B.donor_report() } -- (9.35) her corrupted head and chain hair on the playable body, and the skeleton check
end

----------------------------------------------------------------------------------------------
-- The real body in one box (9.29). The body lab above is a set of buttons; this does them in order, by itself, while the box is
-- ticked: make the body (the model's mesh on an object of my own), add its parts, match its height to Ethan's, make it follow the other
-- player and play the recorded clips on it. While it is up the debug model (the green man) is not drawn, and the game's own depth test
-- hides the real body behind walls and doors, so the wall probes are not needed for it. If any step fails the body is taken down, the green
-- man comes back and the panel says which step failed (and "Try again" starts over). A new scene takes the body with it; it is made again.
-- Flip CFG.REAL_BODY_DEFAULT to true to have it ticked from the first start.
----------------------------------------------------------------------------------------------
CFG.real = { on = CFG.REAL_BODY_DEFAULT == true, touched = false, model = "Pl0000_Chapter1", debug = false, hide_hair = false,
    status = "off", why = "", stage = "off", pending = nil, pending_at = 0, tries = 0, stalls = 0, misses = 0, try_at = 0, next_at = 0,
    body = nil, owns = false, set_follow = false, set_play = false, parts_done = false, sized = false, size_tries = 0, size_at = 0,
    err_b = 0, err_c = 0, restarts = 0, failures = 0, errors = 0, last_error = nil, since = 0, clips_ok = false, clip_at = 0, built_model = nil,
    TICK = 0.2, SIZE_TRIES = 3,
    READY_WAIT = 30,    -- 9.32: seconds a body's mesh may take to load (made from files) before the body is given up (10.9: 10 -> 30: Pete's mesh needed longer the first time)
    ready_since = nil, load_failed = nil } -- load_failed: the model whose FILE body failed (the character module then moves on to the next model)

function CFG.real.note(text) CFG.body.note("Real body: " .. text, true) end

-- The status line: written to the journal only when it changes (the panel shows it every frame).
function CFG.real.set_status(status, why)
    local R = CFG.real
    why = why or ""
    if R.status ~= status or R.why ~= why then
        R.status, R.why = status, why
        R.note(status .. (why ~= "" and (": " .. why) or ""))
    end
end

-- A fresh start of the steps (switched on, tried again, or the scene took the body away).
function CFG.real.reset_run()
    local R = CFG.real
    R.stage, R.pending, R.tries, R.stalls, R.misses, R.try_at = "make", nil, 0, 0, 0, 0
    R.body, R.parts_done, R.sized, R.size_tries, R.size_at = nil, false, false, 0, 0
    R.ready_since, R.load_failed = nil, nil
end

-- Takes the body down: stops what this module started, and removes the body if this module made it (a body made by hand in the lab stays).
function CFG.real.take_down(why)
    local R, B, C = CFG.real, CFG.body, CFG.clip
    if R.set_follow then B.follow, R.set_follow = false, false end
    if R.set_play then C.play, R.set_play = false, false end
    if R.owns and B.go then
        R.owns = false
        B.later("Remove (real body)", B.remove)
    end
    R.body, R.pending, R.built_model = nil, nil, nil
    R.note("taken down (" .. tostring(why) .. ")")
end

function CFG.real.fail(why)
    local R = CFG.real
    R.failures = R.failures + 1
    R.take_down(why)
    R.stage = "failed"
    R.set_status("failed", why)
end

function CFG.real.set_on(v)
    local R = CFG.real
    R.on, R.touched = v == true, true
    if R.on then
        R.reset_run()
        R.set_status("waiting", "starting")
        CFG.body.register()
    end
end

-- "Try again" and "Rebuild": take the body down if it is up and start the steps over (with the model named in the box).
function CFG.real.retry()
    local R = CFG.real
    if not R.on then return end
    if R.stage ~= "failed" and R.stage ~= "off" then R.take_down("rebuilding") end
    R.reset_run()
    R.try_at = os.clock() + 1 -- after the removal has run
    R.set_status("waiting", "starting again")
end

function CFG.real.set_model(name)
    local R = CFG.real
    if type(name) ~= "string" then return end
    name = name:gsub("%s", "")
    if name == "" or #name > 40 or not name:match("^[%w_]+$") then return end
    R.model = name
end

-- Hair is cloth, which the copy does not have: hide the parts named hair (or show them again). Only touches parts named "hair".
function CFG.real.set_hair(v)
    local R, B = CFG.real, CFG.body
    R.hide_hair = v == true
    for _, k in ipairs(B.kids) do
        if k.name:lower():find("hair", 1, true) then B.hidden[k.name] = R.hide_hair or nil end
    end
end

-- The queued steps run in the game phase; this is what each does. pending is cleared FIRST, so a step that throws cannot block the rest.
function CFG.real.run_make()
    local R, B = CFG.real, CFG.body
    R.pending = nil
    local had = B.go ~= nil
    B.allow_load = true -- (9.31) a model that is not in the scene may be made from its files
    local ok, res, why = pcall(B.make)
    B.allow_load = false
    if not ok then R.fail("making the body threw an error: " .. tostring(res):sub(1, 80)) return end
    if B.go and not had then R.owns = true end
    if res == true then
        R.built_model = R.model
        R.ready_since = nil
        -- (9.32) the rest pose needs joints: a body made from a scene object has them at once; one made from files has them when its mesh is loaded
        -- (the wait for that is in R.update, which reads the pose then)
        local okr, ready = pcall(B.ready)
        if okr and ready then pcall(B.read_rest) end
    elseif why == "missing" then
        R.misses = R.misses + 1
        if B.ETHAN_NAMES[R.model] == true then
            -- 9.35: Ethan is only copied from the scene (never made from his files: that body had no textures). He is in the car, the forest and the
            -- houses and not in Mia's flashback or a tape, so the scene is looked at again every few seconds (1, 2, 3 ... 10 s). This also runs while
            -- the new-game hide timer is counting down, so his copy is already there when the timer ends.
            R.try_at = os.clock() + math.min(10, R.misses)
            R.set_status("waiting", "Ethan is not in this scene yet (his body is copied from the scene, never made from files); looking again in a few seconds")
        else
            R.try_at = os.clock() + math.min(30, 3 * 2 ^ (R.misses - 1)) -- 3, 6, 12, 24, 30 s
            R.set_status("waiting", "can't find " .. R.model .. " in this scene yet")
        end
    else
        local from_file = B.from_file
        local was_pack = from_file and CFG.pack and CFG.pack.active(from_file)
        if from_file and why == "mesh" then
            CFG.load.mark_bad(from_file, "the game would not take the mesh made from its file")
            R.load_failed = R.model
        end
        R.fail("making the body failed at step " .. tostring(why) .. " (see the lines below)")
        if was_pack and why == "mesh" then pcall(CFG.pack.failed, R.model, "the game would not take the mesh") end -- (10.1)
    end
end

function CFG.real.run_parts()
    local R, B = CFG.real, CFG.body
    R.pending, R.parts_done = nil, true
    B.allow_load = true
    local ok, err = pcall(B.add_parts)
    B.allow_load = false
    if not ok then R.note("parts: error " .. tostring(err):sub(1, 80)) end
    if R.hide_hair then R.set_hair(true) end
    if #B.kids == 0 then R.note("no extra parts were found for " .. R.model .. " (hands / lower body); the body may be incomplete") end
end

function CFG.real.run_size()
    local R, B = CFG.real, CFG.body
    R.pending = nil
    R.size_tries = R.size_tries + 1
    local ok, res = pcall(B.match_height)
    if ok and res == true then
        R.sized = true
    elseif R.size_tries >= R.SIZE_TRIES then
        R.sized = true
        R.note(string.format("could not match Ethan's height after %d tries; the size stays at %.3f (the slider in the lab changes it)", R.size_tries, B.scale))
    else
        R.size_at = os.clock() + 4
    end
end

-- A step that was queued but whose game phase never came (the lab gives up on it after WAIT seconds).
function CFG.real.stuck(now)
    local R, B = CFG.real, CFG.body
    if R.pending and now - R.pending_at > B.WAIT + 2 then
        local what = R.pending
        R.pending, R.stalls = nil, R.stalls + 1
        if R.stalls >= 3 then R.fail("the game phase for the " .. what .. " step never came (try another phase in the body lab)") return true end
    end
    return R.pending ~= nil
end

-- 9.35: a body made from FILES (a model that is not in the scene: Mia's Pl2000, Clancy's Pl3000) is made while the other player is drawn, not while
-- they are parked out of sight (the new-game timer, "Show other player" off): a parked body is not drawn, and a body that is not drawn may not
-- get its textures (Ethan's file body "spawned with no textures"; Clancy's hands and shirt were see-through). Made when it is drawn, the game loads
-- the textures while it is in view. A body that is COPIED from the scene shares the scene object's own, already loaded textures, so it is made at
-- once, even during the timer, and is ready when the timer ends. Returns the reason to wait, or nil.
function CFG.real.file_body_waits(now)
    local R, B = CFG.real, CFG.body
    local packed = CFG.pack and CFG.pack.active(R.model) -- (10.1) from the full model pack: made from files, Ethan too
    if B.ETHAN_NAMES[R.model] == true and not packed then return nil end -- Ethan is never made from files (without the pack): nothing to wait for
    if not (CFG.load and CFG.load.on) then return nil end
    local why
    if now < state.hidden_until then
        why = string.format("the other player is hidden after the new game (%d s)", math.ceil(state.hidden_until - now))
    elseif state.show_figure == false then
        why = "'Show other player' is off"
    else
        return nil
    end
    local ok, src = pcall(B.find_one, R.model, true) -- the scene only
    if not packed and ok and type(src) == "table" and src.object ~= nil and src.root ~= nil and src.root.holder ~= nil then return nil end -- it is in the scene: copied at once
    return "the body of " .. R.model .. " would be made from its files, which is done when the other player is drawn (" .. why .. ")"
end

function CFG.real.update(now)
    local R, B, C = CFG.real, CFG.body, CFG.clip
    pcall(CFG.load.tick, now) -- 9.32: a body made from files that has run fine for a while is trusted (loadstate.json is cleared)
    if not R.on then
        if R.stage ~= "off" then
            R.take_down("switched off")
            R.stage = "off"
            R.set_status("off", "")
        end
        return
    end
    if R.stage == "off" then R.reset_run() end
    if R.stage == "failed" then return end
    -- the body I was using is gone (a new scene took it, or the lab's Remove): start over after a short wait
    if R.body ~= nil and B.go ~= R.body then
        R.restarts = R.restarts + 1
        R.set_follow, R.owns = false, false
        R.reset_run()
        R.try_at = now + 2
        R.set_status("waiting", "the body went away (a new scene?); making it again")
        return
    end
    if R.stage ~= "make" and B.errors > R.err_b then
        R.fail("a step reported an error (see the lines below)")
        return
    end
    -- the clip player switches itself off when a joint write fails: that is a failure; the lab's own Play box being unticked is not
    if R.stage == "running" and R.set_play and C.play == false and C.errors > R.err_c then
        R.fail("the clip player stopped (see the lines below)")
        return
    end
    if R.stage == "make" then
        if now < R.try_at or R.stuck(now) then return end
        if B.go then
            if not B.mc then R.fail("the body object has no mesh component") return end
            -- (9.32) wait until the body is a body: its mesh loaded and its joints there. From the scene that is at once; from files it takes
            -- the game a moment, and the parts, the size and the clips must not touch it before (the 9.31 Clancy crash).
            local okr, ready, why = pcall(B.ready)
            if not (okr and ready) then
                R.ready_since = R.ready_since or now
                if now - R.ready_since > R.READY_WAIT then
                    local reason = tostring(okr and why or ready)
                    local was_pack = B.from_file and CFG.pack and CFG.pack.active(B.from_file)
                    if B.from_file then
                        CFG.load.mark_bad(B.from_file, "its mesh was still not loaded after " .. R.READY_WAIT .. " s", 6) -- (10.9) 25 -> 6 s: the game goes on loading it, so the next try soon finds it
                        R.load_failed = R.model
                    end
                    R.fail("the model's mesh was not ready after " .. R.READY_WAIT .. " s (" .. reason .. ")")
                    if was_pack then pcall(CFG.pack.failed, R.model, "the mesh was not loaded after " .. R.READY_WAIT .. " s") end -- (10.1) the old models take over
                    return
                end
                R.set_status("working", "waiting for the game to load the model's mesh")
                return
            end
            if R.ready_since then -- it had to be waited for: read the rest pose now that there are joints
                R.note(string.format("the mesh is ready after %.1f s", now - R.ready_since))
                R.ready_since = nil
                pcall(B.read_rest)
            end
            R.body, R.built_model = B.go, R.built_model or R.model
            -- errors count from when the box started (the new body's first size write happens in the very tick that made it); a body made by hand counts from now
            if not R.owns then R.err_b, R.err_c = B.errors, C.errors end
            R.stage = "parts"
            R.set_status("working", "body made; adding its parts")
        else
            if not peer_present(now) then R.set_status("waiting", "no other player (or Ethan's friend) yet") return end
            if not B.scene_key() then R.set_status("waiting", "not in a game scene") return end
            local wait_why = R.file_body_waits(now)
            if wait_why then
                R.set_status("waiting", wait_why)
                R.try_at = now + 2
                return
            end
            R.pending, R.pending_at, R.tries = "make", now, R.tries + 1
            R.err_b, R.err_c = B.errors, C.errors
            B.model_src = R.model
            R.set_status("working", "making the body of " .. R.model)
            B.later("Make (real body)", R.run_make)
        end
    elseif R.stage == "parts" then
        if R.stuck(now) then return end
        if R.parts_done then
            R.stage = "size"
        else
            R.pending, R.pending_at = "parts", now
            B.later("Parts (real body)", R.run_parts)
        end
    elseif R.stage == "size" then
        if R.stuck(now) then return end
        if B.ETHAN_NAMES[R.model] == true then
            B.scale, R.sized = 1.0, true -- his own copy is his own size
        end
        if R.sized then
            R.stage = "go"
        elseif now >= R.size_at then
            local lp = state.local_pose or {}
            if lp.crouch == true then
                R.set_status("working", "waiting for you to stand up, so Ethan's height can be matched")
            else
                R.set_status("working", "matching the body's height to Ethan's")
                R.pending, R.pending_at = "size", now
                B.later("Size (real body)", R.run_size)
            end
        end
    elseif R.stage == "go" then
        B.follow, R.set_follow = true, true
        B.register()
        if not C.scanned then pcall(C.scan) end
        if not C.play then C.play, R.set_play = true, true end
        R.stage, R.since = "running", now
        R.set_status("running", "")
    elseif R.stage == "running" then
        -- no idle clip yet: look for the file again every 5 s (a clip recorded or copied in while the game runs is picked up)
        if not R.clips_ok and now >= R.clip_at then
            R.clip_at = now + 5
            C.lib.idle = nil
        end
        R.clips_ok = C.get("idle") ~= nil
        R.set_status("running", R.clips_ok and "" or "there is no idle clip (none recorded, and the built-in set re7mp/defaults.json is missing or has none), so the debug model stays visible")
    end
end

-- Called every render frame: its own pcall, so a bug here can only switch the real body off, never stop the rest of the script.
function CFG.real.frame(now)
    local R = CFG.real
    if now < R.next_at then return end
    R.next_at = now + R.TICK
    local ok, err = pcall(R.update, now)
    if not ok then
        R.errors = R.errors + 1
        R.last_error = tostring(err):sub(1, 160)
        if R.errors <= 3 then say("real body error: " .. R.last_error) end
    end
end

-- True while the real body is standing in for the debug model (the green man is not drawn then).
function CFG.real.hides_green()
    local R, B, C = CFG.real, CFG.body, CFG.clip
    -- (B.mc is set and cleared together with B.go: the scene guard drops both, and a half-made body never gets this far)
    return R.on == true and R.stage == "running" and R.debug ~= true and B.mc ~= nil and B.follow == true and C.play == true and R.clips_ok == true
end

function CFG.real.line()
    local R, B = CFG.real, CFG.body
    if not R.on then return "Real body: off (the debug model, the green man, is drawn)." end
    local text = "Real body: " .. R.status .. (R.why ~= "" and (" - " .. R.why) or "")
    if R.stage == "running" then
        text = text .. string.format(" (%s copy, %d part(s), size %.3f; %s)", tostring(R.built_model or R.model), #B.kids, B.scale or 1,
            R.hides_green() and "debug model hidden" or "debug model still drawn")
    elseif R.stage ~= "failed" and R.tries > 1 then
        text = text .. string.format(" [try %d]", R.tries)
    end
    return text
end

function CFG.real.report()
    local R, B = CFG.real, CFG.body
    return { on = R.on, default_on = CFG.REAL_BODY_DEFAULT == true, ticked_by_you = R.touched, status = R.status, why = R.why, stage = R.stage,
        model = R.model, built_model = R.built_model, debug_model_also_shown = R.debug, hides_debug_model_now = R.hides_green(),
        hide_hair = R.hide_hair, made_by_this_box = R.owns, parts = #B.kids, size = B.scale, tries = R.tries, stalls = R.stalls, model_not_found_count = R.misses,
        restarts = R.restarts, failures = R.failures, idle_clip = R.clips_ok, errors = R.errors, last_error = R.last_error,
        rest_pose = B.rest, crouch_lift_m = math.floor(B.crouch_lift() * 100 + 0.5) / 100 } -- (9.30: how far the body is stood up while a crouch clip with hips plays)
end

----------------------------------------------------------------------------------------------
-- Built-in defaults (9.30). re7mp/defaults.json ships with the release (tools/build_defaults.py builds it from the developer's own
-- recordings and settings) and holds the animation clips and the default settings. Without any clip the other player's real body
-- stays in its T pose, so a fresh install must not depend on recordings it does not have. The script never writes this file.
-- A player's own files always win: their own clip for a label (re7mp/clips/<label>.json, or the older re7mp_clip_<label>.json) and
-- every key their settings file has (a key it lacks takes the shipped value).
----------------------------------------------------------------------------------------------
CFG.defaults = { FILE = "re7mp/defaults.json", data = nil, tried = false, error = nil }

function CFG.defaults.get()
    local D = CFG.defaults
    if D.tried then return D.data end
    D.tried = true
    local ok, d = pcall(json.load_file, D.FILE)
    if not ok then D.error = tostring(d):sub(1, 80) return nil end
    if d == nil then D.error = "file not found" return nil end
    if type(d) ~= "table" or d.format ~= 1 then D.error = "not usable (wrong shape)" return nil end
    D.data = d
    return d
end

function CFG.defaults.clip(label)
    local ok, d = pcall(CFG.defaults.get)
    if ok and type(d) == "table" and type(d.clips) == "table" then return d.clips[label] end
    return nil
end

-- The player's settings win key by key; a key their file does not have takes the shipped default; no file at all gives the defaults.
function CFG.defaults.merge_settings(user)
    local ok, d = pcall(CFG.defaults.get)
    local base = ok and type(d) == "table" and d.settings or nil
    if type(base) ~= "table" then return user end
    if type(user) ~= "table" then return base end
    local out = {}
    for k, v in pairs(base) do out[k] = v end
    for k, v in pairs(user) do out[k] = v end
    return out
end

function CFG.defaults.report()
    local D = CFG.defaults
    local n = 0
    if D.data and type(D.data.clips) == "table" then for _ in pairs(D.data.clips) do n = n + 1 end end
    return { file = D.FILE, loaded = D.data ~= nil, error = D.error, clips = n, build = D.data and D.data.build or nil }
end

-- Writes a JSON file into re7mp/ (its own folder under reframework/data); if the game refuses that path, into the old flat name next
-- to the bridge files. Returns true and the path used, or false and the reason.
function CFG.save_json(path, flat, data)
    local ok, res = pcall(json.dump_file, path, data)
    if ok and res ~= false then return true, path end
    local ok2, res2 = pcall(json.dump_file, flat, data)
    if ok2 and res2 ~= false then return true, flat end
    return false, ok and ("the game refused to write " .. path) or tostring(res)
end

----------------------------------------------------------------------------------------------
-- Animation clips (9.24, experimental): record how Ethan's joints move while you play, and play the recordings on the body lab's
-- body. The body lab showed that a joint of my own body can be turned from the script (set_LocalEulerAngle in the game phase), so a
-- recording is simply the local angles of his joints, 20 times a second, kept per label (idle, walk, run, crouch, guard, heal,
-- inventory ...) in re7mp/clips/<label>.json (older builds: re7mp_clip_<label>.json). It also writes down the game's own motion ids (bank / motion / frame of the first
-- layers) next to the joints, so each label can be tied to the ids the game uses for it. Only reads Ethan; changes nothing in him.
-- The player picks a clip from what the other player is doing (the pose flags and the speed that are already sent) and eases from
-- one clip to the next. No network message is needed: both players need the same clip files.
----------------------------------------------------------------------------------------------
-- (10.12) LOW (crawling, lying down: "the leg cutoff animations play but it is too far down into the ground to see, like the crawling"). The other player's body
-- stands at (their camera height - 1.6 m), right for standing and (with the clip's own hips) for a crouch. Crawling, or lying after the legs are cut off, puts the
-- camera some 0.4-0.8 m above the floor: the body ended up a metre in the ground. The sender knows its own floor (the player object's y), so it says how high its camera
-- is above it ("low", in centimetres, only while it is under LOW m, and "0" when it is not) and the body is stood on THAT floor.
CFG.low = { on = true, EVERY = 0.25, SEND_EVERY = 1.5, TTL = 4.0, LOW = 0.9, MIN = 0.15, NEAR = 0.8, read_at = -100, mine_h = nil, sent_key = nil, sent_at = -100, sent = 0,
    received = 0, remote_h = nil, remote_at = -100, reads = 0, failures = 0, last_error = nil, applied = 0, last = "has not run yet" }

-- My camera's height above my own feet while it is low (the player object's y), or nil. Called every frame; reads about 4 times a second.
function CFG.low.mine(now)
    local L = CFG.low
    if not L.on then return nil end
    if now - L.read_at < L.EVERY then return L.mine_h end
    L.read_at = now
    local lp = state.local_pos
    L.mine_h = nil
    if not lp then return nil end
    local ok, v = pcall(function()
        local om = sdk.get_managed_singleton("app.ObjectManager")
        local p = om and om:get_field("PlayerObj")
        if p == nil then return nil end
        local xf = p:call("get_Transform")
        local pos = xf and xf:call("get_Position")
        return pos and { x = tonumber(pos.x), y = tonumber(pos.y), z = tonumber(pos.z) }
    end)
    if not ok then
        L.failures, L.last_error = L.failures + 1, tostring(v):sub(1, 100)
        return nil
    end
    if type(v) ~= "table" or v.y == nil or v.x == nil or v.z == nil then return nil end
    L.reads = L.reads + 1
    local h = lp.y - v.y
    local flat = math.sqrt((lp.x - v.x) ^ 2 + (lp.z - v.z) ^ 2)
    -- a camera that is not on the player (a cutscene camera) says nothing about lying down
    if flat <= L.NEAR and h >= L.MIN and h <= L.LOW then L.mine_h = h end
    return L.mine_h
end

-- Tell the other player (when it changes by 4 cm or more, now and then while it lasts, and once more when it ends).
function CFG.low.tick(now)
    local L = CFG.low
    if not L.on then return end
    local h = L.mine(now)
    local arg = h and tostring(math.floor(h * 100 + 0.5)) or "0"
    if L.sent_key == nil and arg == "0" then return end -- never been low: nothing to say
    local was_low = L.sent_key ~= nil and L.sent_key ~= "0"
    local changed = (arg ~= "0") ~= was_low or (arg ~= "0" and math.abs(tonumber(arg) - tonumber(L.sent_key)) >= 4)
    if peer_present(now) and L.send and (changed or (h and now - L.sent_at >= L.SEND_EVERY)) and now - L.sent_at >= 0.2 then
        L.sent_key, L.sent_at, L.sent = arg, now, L.sent + 1
        pcall(L.send, "low", arg) -- (L.send is H.send_event, set where the health module is defined: it is a local further down)
    end
end

function CFG.low.on_remote(arg, now)
    local L = CFG.low
    local cm = tonumber(arg)
    if not cm then return end
    L.received = L.received + 1
    if cm <= 0 then L.remote_h = nil return end
    L.remote_h, L.remote_at = math.max(L.MIN, math.min(L.LOW, cm / 100)), now
end

-- How high the other player's camera is above their floor while they are low, or nil (standing, crouching: the old rules). Not for Ethan's friend (it has its own body).
function CFG.low.remote(now)
    local L = CFG.low
    if not L.on or L.remote_h == nil then return nil end
    if now - L.remote_at > L.TTL then L.remote_h = nil return nil end
    local FB = CFG.friend and CFG.friend.body
    if FB and FB.own_on() then return nil end
    return L.remote_h
end

function CFG.low.report()
    local L = CFG.low
    return { on = L.on, my_height_m = L.mine_h, sent = L.sent, received = L.received, their_height_m = L.remote_h, applied_frames = L.applied, reads = L.reads,
        failures = L.failures, last_error = L.last_error, about = "10.12: a camera lower than 0.9 m above the floor (crawling, lying) is sent as 'low' and the other player's body is stood on that floor" }
end

-- (10.12) RUN OR WALK. "When another player is running, the walk animation plays" (10.11 notes). The clips recorded from the real Ethan say why it was
-- fragile: walk 2.54 m/s, run 4.02 m/s, and the script switched at 2.4, i.e. below the walking speed, so the label depended on camera noise. Now:
--   * the sender says "running" in the flags (POSE_RUN, bit 13): its own speed (over 0.2 s steps, smoothed) against ON, and it stays running until OFF;
--   * the receiver runs the run clip when that bit is set, or when its own estimate of the other player's speed is above ON (older build on the other side);
--   * ON / OFF are the middle of the two recorded clips' speeds when both exist (3.28), 3.3 / 2.9 otherwise.
CFG.run = { ON = 3.3, OFF = 2.9, EVERY = 0.2, mine_speed = 0, mine_running = false, mine_pos = nil, mine_at = nil, rem_running = false, rem_flag = false,
    n = { flag_seen = 0, from_speed = 0, switched_run = 0, switched_walk = 0, sent_run = 0 } }

function CFG.run.limits()
    local R = CFG.run
    local on, off = R.ON, R.OFF
    local okc, ws, rs = pcall(function()
        local w, r = CFG.clip.get("walk"), CFG.clip.get("run")
        return w and tonumber(w.speed), r and tonumber(r.speed)
    end)
    if okc and ws and rs and ws > 0.5 and rs > ws + 0.5 then
        local mid = (ws + rs) / 2
        on, off = mid, mid - 0.4
    end
    return on, off
end

-- My own speed (called with every flags build, about 25 times a second; works in 0.2 s steps). Crouched: never running.
function CFG.run.mine(now, crouched)
    local R = CFG.run
    local lp = state.local_pos
    if not lp then
        R.mine_pos, R.mine_at, R.mine_speed, R.mine_running = nil, nil, 0, false
        return false
    end
    if R.mine_pos == nil or R.mine_at == nil or now - R.mine_at > 1.0 then
        R.mine_pos, R.mine_at = { x = lp.x, z = lp.z }, now
        return R.mine_running
    end
    local dt = now - R.mine_at
    if dt >= R.EVERY then
        local v = math.sqrt((lp.x - R.mine_pos.x) ^ 2 + (lp.z - R.mine_pos.z) ^ 2) / dt
        if v >= 12 then v = R.mine_speed end -- a teleport, not running
        R.mine_speed = R.mine_speed + (v - R.mine_speed) * 0.5
        R.mine_pos, R.mine_at = { x = lp.x, z = lp.z }, now
        local on, off = CFG.run.limits()
        if R.mine_running then R.mine_running = R.mine_speed >= off else R.mine_running = R.mine_speed >= on end
    end
    if crouched then return false end
    if R.mine_running then R.n.sent_run = R.n.sent_run + 1 end
    return R.mine_running
end

-- The other player: running or not (their bit, or their speed from where they were seen).
function CFG.run.remote(now, speed)
    local R = CFG.run
    local flag = false
    local okf, rf = pcall(remote_flags_now, now)
    if okf and type(rf) == "number" then flag = has(rf, CFG.POSE_RUN) end
    if flag and not R.rem_flag then R.n.flag_seen = R.n.flag_seen + 1 end
    R.rem_flag = flag
    local on, off = CFG.run.limits()
    local was = R.rem_running
    if flag then
        R.rem_running = true
    elseif (speed or 0) >= on then
        R.rem_running = true
        if not was then R.n.from_speed = R.n.from_speed + 1 end
    elseif (speed or 0) < off then
        R.rem_running = false
    end
    if R.rem_running and not was then R.n.switched_run = R.n.switched_run + 1 end
    if was and not R.rem_running then R.n.switched_walk = R.n.switched_walk + 1 end
    return R.rem_running
end

function CFG.run.report()
    local R = CFG.run
    pcall(CFG.run.remote, os.clock(), state.speed) -- (what the other player is doing right now, even when no body asked)
    local on, off = CFG.run.limits()
    local function r(x) return math.floor((tonumber(x) or 0) * 100 + 0.5) / 100 end
    return { on = r(on), off = r(off), my_speed = r(R.mine_speed), i_am_running = R.mine_running, their_speed = r(state.speed), they_run_flag = R.rem_flag,
        they_are_running = R.rem_running, counts = R.n }
end

CFG.clip = { enabled = false, rec = nil, lib = {}, src = {}, builtin_only = false, lines = {}, errors = 0, saved = 0, ticks = 0, scanned = false,
    label = 1, memo = "", secs = 8, hands = true, hotkey = 0x79, key_was_down = false, -- F10
    play = false, preview = 1, P = { joints = {}, cand = nil, label = nil, clip = nil, t = 0 },
    RATE = 20, XFADE = 0.25, BLEND = 0.25, IDS_EVERY = 0.25, MAX_IDS = 120,
    LABELS = { "auto (from what you are doing)", "idle", "walk", "run", "crouch", "crouch_walk", "guard", "heal", "inventory",
        "aim", "shoot", "reload", "melee", "other",
        -- 9.28: with a gun out (the other player's gun / aim / shot bits pick these)
        "gun_idle", "gun_walk", "gun_run", "gun_crouch", "gun_aim", "gun_shoot", "gun_reload" },
    FALLBACK = { crouch_walk = "walk", crouch = "idle", run = "walk", walk = "idle", guard = "idle", heal = "idle", inventory = "idle",
        gun_shoot = "gun_aim", gun_aim = "gun_idle", gun_idle = "idle", gun_walk = "walk", gun_run = "gun_walk", gun_crouch = "crouch", gun_reload = "gun_idle" } }

CFG.clip.PREVIEWS = { "automatic (what the other player does)" }
for i = 2, #CFG.clip.LABELS do CFG.clip.PREVIEWS[i] = CFG.clip.LABELS[i] end

function CFG.clip.note(text, risky)
    local C = CFG.clip
    text = tostring(text):gsub("[\r\n]+", " "):sub(1, 240)
    C.lines[#C.lines + 1] = text
    if #C.lines > 40 then table.remove(C.lines, 1) end
    if risky then give.trail("clip: " .. text) else say("clip: " .. text) end
end

-- Joint names of Ethan's skeleton (from the model probe): side = nil is the whole body, "R" / "L" is one arm with its hand.
function CFG.clip.names(side)
    local out = {}
    if not side then for _, n in ipairs({ "Hip", "Waist", "Stomach", "Chest", "Neck", "Head" }) do out[#out + 1] = n end end
    for _, s in ipairs(side and { side } or { "R", "L" }) do
        local part = { "Shoulder", "UpperArm", "Forearm", "Hand", "Palm" }
        if not side then for _, n in ipairs({ "Thigh", "Shin", "Foot", "Toe" }) do part[#part + 1] = n end end
        for _, f in ipairs({ "Thumb", "IndexF", "MiddleF", "RingF", "PinkyF" }) do
            for i = 1, 3 do part[#part + 1] = f .. i end
        end
        for _, n in ipairs(part) do out[#out + 1] = s .. "_" .. n end
    end
    return out
end

-- An angle (radians) or a length (metres) as a whole number of thousandths; a number the game garbled becomes 0.
function CFG.clip.q(x)
    if type(x) ~= "number" or x ~= x or x > 1e6 or x < -1e6 then return 0 end
    return math.floor(x * 1000 + 0.5)
end

function CFG.clip.int(v)
    v = tonumber(v)
    if v == nil or v ~= v or v > 1e9 or v < -1e9 then return "?" end
    return tostring(math.floor(v))
end

-- Between two frames (flat arrays of thousandths). The first na values are angles: they go the short way round the circle, and a
-- jump of more than 1.5 rad in one step (an angle flipping over) is not blended but taken from the nearer frame.
function CFG.clip.lerp(a, b, u, na, n)
    local out = {}
    for i = 1, n do
        local x, y = a[i], b[i]
        local d = y - x
        if i <= na then
            if d > 3141.6 then d = d - 6283.2 elseif d < -3141.6 then d = d + 6283.2 end
            if d > 1500 or d < -1500 then out[i] = (u < 0.5) and x or y else out[i] = x + d * u end
        else
            out[i] = x + d * u
        end
    end
    return out
end

-- Ethan's object and his two hand objects, by their paths.
function CFG.clip.sources()
    local B = CFG.body
    local out
    -- 9.27: "Pl0000_Chapter1" early in the game, "Pl0000" in the main house: the first name is tried first, the second only when he is not there
    for _, nm in ipairs({ B.SRC, "Pl0000" }) do
        local want = { ["/" .. nm] = "body", ["/" .. nm .. "/Pl0000HandL"] = "L", ["/" .. nm .. "/Pl0000HandR"] = "R" }
        local found = 0
        out = {}
        pcall(each_gameobject, function(go, path)
            local key = want[path]
            if key and not out[key] then
                out[key] = { go = go, path = path }
                pcall(function() out[key].xf = go:call("get_Transform") end)
                found = found + 1
            end
            return found >= 3
        end, 20000)
        if out.body then break end
    end
    return out
end

-- The first layers of an object's Motion component as text: "L0=bank/motion/frame L1=...".
function CFG.clip.ids(go)
    local C, out = CFG.clip, {}
    pcall(function()
        local m = go:call("getComponent(System.Type)", sdk.typeof("via.motion.Motion"))
        if not m then return end
        local n = tonumber(m:call("getLayerCount")) or 0
        for i = 0, math.min(n, 4) - 1 do
            local layer = m:call("getLayer", i)
            if layer then
                local fr = tonumber(layer:call("get_Frame"))
                out[#out + 1] = string.format("L%d=%s/%s/%s", i, C.int(layer:call("get_MotionBankID")), C.int(layer:call("get_MotionID")),
                    (fr and fr == fr and math.abs(fr) < 1e7) and string.format("%.1f", fr) or "?")
            end
        end
    end)
    return table.concat(out, " ")
end

-- (9.32) The FIRST animation layer of an object's Motion component as numbers: bank, id, frame (nil when it can't be read).
-- (It was made for the cutscene recorder, taken out in 10.22; nothing calls it now. It reads only.)
function CFG.clip.motion0(go)
    if go == nil then return nil end
    local ok, bank, id, fr = pcall(function()
        local m = go:call("getComponent(System.Type)", sdk.typeof("via.motion.Motion"))
        if not m then return nil end
        if (tonumber(m:call("getLayerCount")) or 0) < 1 then return nil end
        local layer = m:call("getLayer", 0)
        if not layer then return nil end
        return layer:call("get_MotionBankID"), layer:call("get_MotionID"), layer:call("get_Frame")
    end)
    if not ok then return nil end
    local b, i = CFG.clip.int(bank), CFG.clip.int(id)
    if b == "?" or i == "?" then return nil end
    fr = tonumber(fr)
    if fr ~= nil and (fr ~= fr or math.abs(fr) > 1e7) then fr = nil end
    return tonumber(b), tonumber(i), fr
end

-- Starts a recording (runs in the chosen game phase; see CFG.body.later).
-- 9.28: `opt` { label = file label, secs = length, ignore_scene = true, note = text }: the keys the cutscene recorder used (taken out in 10.22; the recorder panel passes none). Returns true when it started.
function CFG.clip.start(opt)
    local C, B = CFG.clip, CFG.body
    if type(opt) ~= "table" then opt = nil end -- (the body lab's queue calls this with nothing)
    if C.rec then C.note("Record: already recording") return false end
    local src = C.sources()
    if not (src.body and src.body.xf) then
        C.note("Record: no object named " .. B.SRC .. " (or Pl0000) here (are you in the game, not in a menu?)")
        return false
    end
    local rec = { t0 = os.clock(), last = nil, last_ids = -1, blocks = {}, ids = {}, path = {}, scene = B.scene_key(), want = C.label,
        note = tostring(opt and opt.note or C.memo or ""), missing = {}, go = {}, stop = false,
        file_label = opt and opt.label or nil, secs = opt and opt.secs or nil, ignore_scene = opt and opt.ignore_scene == true }
    local lp = state.local_pose or {}
    rec.flags = { guard = lp.guard == true, heal = lp.heal == true, crouch = lp.crouch == true, menu = lp.menu == true,
        gun = lp.gun == true, aim = lp.aim == true, shoot = lp.shoot == true }
    local wanted = { { "body", C.names(nil) } }
    if C.hands then
        wanted[#wanted + 1] = { "L", C.names("L") }
        wanted[#wanted + 1] = { "R", C.names("R") }
    end
    C.note(string.format("Record: starting (%s); reading the joints of Ethan's object%s", rec.file_label or C.LABELS[C.label], C.hands and " and his hand objects" or ""), true)
    for _, w in ipairs(wanted) do
        local key, names = w[1], w[2]
        local s = src[key]
        if s and s.xf then
            local blk = { key = key, names = {}, joints = {}, frames = {} }
            for _, nm in ipairs(names) do
                local ok, j = pcall(function() return s.xf:call("getJointByName", nm) end)
                if ok and j ~= nil then
                    blk.names[#blk.names + 1] = nm
                    blk.joints[#blk.joints + 1] = j
                    if key == "body" and nm == "Hip" then blk.hip = j end
                else
                    rec.missing[#rec.missing + 1] = key .. ":" .. nm
                end
            end
            blk.na = 3 * #blk.names
            if #blk.names > 0 then
                rec.blocks[key] = blk
                rec.go[key] = s.go
                if key == "body" then rec.root_xf = s.xf end
            end
        else
            rec.missing[#rec.missing + 1] = key .. " (object)"
        end
    end
    if not rec.blocks.body then C.note("Record: none of his joints could be read, so nothing is recorded", true) return false end
    if rec.blocks.body.hip then -- (the hip's position is read with every frame, so find out now whether it can be)
        local okh, errh = pcall(function() return rec.blocks.body.hip:call("get_LocalPosition").x end)
        if not okh then
            rec.blocks.body.hip = nil
            C.note("Record: the hip's position can't be read (" .. tostring(errh):sub(1, 60) .. "); angles only", true)
        end
    end
    C.note(string.format("Record: %d body joints%s%s", #rec.blocks.body.names,
        (rec.blocks.L and rec.blocks.R) and string.format(", %d + %d hand-object joints", #rec.blocks.L.names, #rec.blocks.R.names) or "",
        #rec.missing > 0 and (" (not found: " .. table.concat(rec.missing, " ", 1, math.min(#rec.missing, 8)) .. (#rec.missing > 8 and " ..." or "") .. ")") or ""), true)
    C.rec = rec
    dbg.dirty = true -- (the debug file shows a recording is running)
    pcall(function() C.sample(os.clock()) end)
    return true
end

-- One reading of every joint of one block.
function CFG.clip.read_block(blk, el)
    local C = CFG.clip
    local f = { t = el }
    for i, j in ipairs(blk.joints) do
        local e = j:call("get_LocalEulerAngle")
        local a = 3 * i - 2
        f[a], f[a + 1], f[a + 2] = C.q(e.x), C.q(e.y), C.q(e.z)
    end
    if blk.hip then
        local hp = blk.hip:call("get_LocalPosition")
        f[blk.na + 1], f[blk.na + 2], f[blk.na + 3] = C.q(hp.x), C.q(hp.y), C.q(hp.z)
    end
    blk.frames[#blk.frames + 1] = f
end

-- Every tick of the chosen game phase while recording.
function CFG.clip.sample(now)
    local C, B = CFG.clip, CFG.body
    local rec = C.rec
    if not rec then return end
    local el = now - rec.t0
    local key = B.scene_key()
    if rec.scene ~= nil and key ~= nil and key ~= rec.scene and not rec.ignore_scene then
        C.note("Record: the scene changed, so the recording is dropped")
        C.rec = nil
        return
    end
    if rec.last == nil or el - rec.last >= 1 / C.RATE then
        rec.last = el
        for k, blk in pairs(rec.blocks) do
            local ok, err = pcall(C.read_block, blk, el)
            if not ok then
                C.errors = C.errors + 1
                if k == "body" then
                    C.note("Record: reading his joints failed: " .. tostring(err):sub(1, 100) .. " (recording dropped)", true)
                    C.rec = nil
                    return
                end
                C.note("Record: the " .. k .. " hand object failed (" .. tostring(err):sub(1, 60) .. "); carrying on without it", true)
                rec.blocks[k] = nil
            end
        end
        local okp, p = pcall(function() return rec.root_xf:call("get_Position") end)
        if okp and p then rec.path[#rec.path + 1] = { el, p.x, p.z } end
    end
    if el - rec.last_ids >= C.IDS_EVERY and #rec.ids < C.MAX_IDS then
        rec.last_ids = el
        for _, k in ipairs({ "body", "L", "R" }) do
            if rec.go[k] and (k == "body" or rec.blocks[k]) then
                local t = C.ids(rec.go[k])
                if t ~= "" then rec.ids[#rec.ids + 1] = string.format("%.2f %s %s", el, k, t) end
            end
        end
    end
    if rec.stop or el >= (rec.secs or C.secs) then C.finish() end
end

-- Frames at irregular times -> frames at the fixed rate (a plain array of flat arrays).
function CFG.clip.uniform(blk, dur)
    local C = CFG.clip
    local frames, out, j = blk.frames, {}, 1
    local n = #frames[1]
    for k = 0, math.floor(dur * C.RATE + 0.5) do
        local t = math.min(k / C.RATE, dur)
        while j < #frames and frames[j + 1].t <= t do j = j + 1 end
        local a, b = frames[j], frames[math.min(j + 1, #frames)]
        local u = (b.t > a.t) and math.max(0, math.min(1, (t - a.t) / (b.t - a.t))) or 0
        local f = C.lerp(a, b, u, blk.na, n)
        for i = 1, n do f[i] = math.floor(f[i] + 0.5) end
        out[#out + 1] = f
    end
    return out
end

-- The label a recording gets when "auto" was chosen: the pose flags at the start, then how fast I moved.
function CFG.clip.auto_label(flags, speed)
    if flags.menu then return "inventory" end
    if flags.heal then return "heal" end
    if flags.guard then return "guard" end
    if flags.shoot then return "gun_shoot" end
    if flags.aim then return "gun_aim" end
    -- (10.12) the run / walk bar is the middle of the two recorded speeds (CFG.run.limits), not 2.4 (which was below the recorded walk, 2.54)
    local run_on = CFG.run.limits()
    if flags.gun then
        if flags.crouch then return "gun_crouch" end
        if speed < 0.3 then return "gun_idle" end
        return speed < run_on and "gun_walk" or "gun_run"
    end
    if flags.crouch then return speed > 0.3 and "crouch_walk" or "crouch" end
    if speed < 0.3 then return "idle" end
    if speed < run_on then return "walk" end
    return "run"
end

-- Stops, builds the clip, writes re7mp/clips/<label>.json.
-- (9.32) Cuts a recording off at `t` seconds: the frames, the id lines and the path after it are dropped (the cutscene recorder trimmed the
-- idle / walking that came after the cutscene; it is gone since 10.22 and nothing calls this now).
function CFG.clip.trim(rec, t)
    for _, blk in pairs(rec.blocks) do
        local keep = {}
        for _, f in ipairs(blk.frames) do
            if f.t <= t then keep[#keep + 1] = f end
        end
        blk.frames = keep
    end
    local ids = {}
    for _, line in ipairs(rec.ids) do
        local lt = tonumber(line:match("^([%d%.]+) "))
        if lt == nil or lt <= t + 0.3 then ids[#ids + 1] = line end
    end
    rec.ids = ids
    local path = {}
    for _, pt in ipairs(rec.path) do
        if pt[1] <= t then path[#path + 1] = pt end
    end
    rec.path = path
end

function CFG.clip.finish()
    local C = CFG.clip
    local rec = C.rec
    C.rec = nil
    if not rec then return end
    -- (9.32) how it ended is remembered: "time" = the length ran out (the cutscene recorder read it; it is gone since 10.22)
    C.ended = { label = rec.file_label, why = rec.stop_why or "time", at = os.clock() }
    if rec.discard then
        C.note("Record: " .. tostring(rec.discard_why or "nothing worth keeping") .. ": nothing saved", true)
        return
    end
    if rec.trim_to then C.trim(rec, rec.trim_to) end
    local body = rec.blocks.body
    if not body or #body.frames < 4 then C.note("Record: too short, nothing saved") return end
    local dur = body.frames[#body.frames].t
    if dur < 0.3 then C.note("Record: too short, nothing saved") return end
    local dist = 0
    for i = 2, #rec.path do
        local a, b = rec.path[i - 1], rec.path[i]
        local d = math.sqrt((b[2] - a[2]) ^ 2 + (b[3] - a[3]) ^ 2)
        if d < 3 then dist = dist + d end -- (a jump of metres in one step is a teleport or a load, not walking)
    end
    local speed = dist / dur
    local label = rec.file_label or (rec.want > 1 and C.LABELS[rec.want] or C.auto_label(rec.flags, speed))
    local clip = { format = 1, build = CFG.BUILD, label = label, note = rec.note, rate = C.RATE, dur = dur, speed = math.floor(speed * 100 + 0.5) / 100,
        flags = rec.flags, ids = rec.ids, missing = rec.missing, ended_because = rec.stop_why, trimmed_to = rec.trim_to and math.floor(rec.trim_to * 100 + 0.5) / 100 or nil }
    clip.body = { names = body.names, na = body.na, hip = body.hip ~= nil, frames = C.uniform(body, dur) }
    for _, k in ipairs({ "L", "R" }) do
        local blk = rec.blocks[k]
        if blk and #blk.frames >= 4 then
            clip.hands = clip.hands or {}
            clip.hands[k] = { names = blk.names, na = blk.na, hip = false, frames = C.uniform(blk, dur) }
        end
    end
    -- which joints really moved (the range in thousandths of a radian): this is how to tell where the animation lives
    local ranges = {}
    local function note_ranges(prefix, blk)
        for i, nm in ipairs(blk.names) do
            local lo, hi = { 1e9, 1e9, 1e9 }, { -1e9, -1e9, -1e9 }
            for _, f in ipairs(blk.frames) do
                for c = 1, 3 do
                    local v = f[3 * i - 3 + c]
                    if v < lo[c] then lo[c] = v end
                    if v > hi[c] then hi[c] = v end
                end
            end
            local r = math.max(hi[1] - lo[1], hi[2] - lo[2], hi[3] - lo[3])
            if r >= 50 then ranges[#ranges + 1] = { prefix .. nm, r } end
        end
    end
    note_ranges("", body)
    for k, blk in pairs(rec.blocks) do if k ~= "body" and #blk.frames >= 4 then note_ranges(k .. ":", blk) end end
    table.sort(ranges, function(a, b) return a[2] > b[2] end)
    clip.moving = {}
    for i = 1, math.min(#ranges, 20) do clip.moving[i] = ranges[i][1] .. " " .. ranges[i][2] end
    clip.moving_count = #ranges
    local ok, where = CFG.save_json(C.path(label), "re7mp_clip_" .. label .. ".json", clip)
    C.lib[label] = clip
    C.src[label] = ok and where or nil
    C.saved = C.saved + 1
    C.note(string.format("Record: %s saved%s as %s: %.1f s, %d frames, %.2f m/s, %d joints turned more than 0.05 rad%s",
        label, ok and "" or " (NOT written: " .. tostring(where):sub(1, 60) .. ")", ok and where or C.path(label), dur, #clip.body.frames, clip.speed, #ranges,
        #ranges > 0 and (" - most: " .. table.concat(clip.moving, ", ", 1, math.min(#clip.moving, 5))) or ""), true)
end

-- A clip from the library (read from its file the first time), or nil.
function CFG.clip.valid(d)
    if type(d) ~= "table" or type(d.body) ~= "table" or type(d.rate) ~= "number" or d.rate <= 0 or type(d.dur) ~= "number" or d.dur <= 0.2 then return nil end
    local b = d.body
    if type(b.names) ~= "table" or type(b.frames) ~= "table" or type(b.na) ~= "number" or b.na ~= 3 * #b.names or #b.frames < 4 then return nil end
    local want = b.na + (b.hip and 3 or 0)
    for _, i in ipairs({ 1, #b.frames }) do
        local f = b.frames[i]
        if type(f) ~= "table" or #f ~= want then return nil end
        for _, v in ipairs(f) do if type(v) ~= "number" then return nil end end
    end
    return d
end

-- Where a recording of this label is written (the data folder's re7mp/clips/ folder).
function CFG.clip.path(label)
    return "re7mp/clips/" .. (tostring(label):gsub("[^%w_%-]", "_")) .. ".json"
end

-- 9.30: the player's own recording first (re7mp/clips/<label>.json, then the flat re7mp_clip_<label>.json older builds wrote), then the
-- built-in clip from re7mp/defaults.json. C.src[label] says which one was used ("built-in" or the file's path).
function CFG.clip.get(label)
    local C = CFG.clip
    if C.lib[label] ~= nil then return C.lib[label] or nil end
    local clip, src
    if not C.builtin_only then
        for _, path in ipairs({ C.path(label), "re7mp_clip_" .. label .. ".json" }) do
            local ok, d = pcall(json.load_file, path)
            local c = ok and C.valid(d) or nil
            if ok and d ~= nil and not c then C.note("Clip file " .. path .. " is not usable (wrong shape); ignored") end
            if c then clip, src = c, path break end
        end
    end
    if not clip then
        local c = C.valid(CFG.defaults.clip(label))
        if c then clip, src = c, "built-in" end
    end
    C.lib[label] = clip or false
    C.src[label] = clip and src or nil
    return clip
end

-- Reads every label's file once (so the debug file lists what is on disk), or again after "Read the clip files again".
function CFG.clip.scan(again)
    local C = CFG.clip
    if again then C.lib, C.src, CFG.defaults.tried, CFG.defaults.data = {}, {}, false, nil end
    for i = 2, #C.LABELS do C.get(C.LABELS[i]) end
    C.scanned = true
end

-- What the other player is doing: a label.
function CFG.clip.choose()
    local P, sp = state.pose or {}, state.speed or 0
    local C = CFG.clip
    C.arms = nil
    local act = CFG.mbank and CFG.mbank.action_label(os.clock()) -- (10.1) a reload or a melee swing: the flags cannot say them, Ethan's own clip pair can
    if act then return act end
    -- (10.7) crouched, a block or the inventory shows the crouch (there is no crouched block or inventory clip; the pose is what counts)
    -- (10.8) ...with the ARMS of the saved block / inventory clip over it (C.arms; the legs and back stay the crouch's)
    if (P.crouch or 0) > 0.5 and (P.heal or 0) <= 0.5 and (P.gun or 0) <= 0.5 and (P.aim or 0) <= 0.5 and (P.shoot or 0) <= 0.5
        and ((P.menu or 0) > 0.5 or (P.guard or 0) > 0.5) then
        C.arms = (P.guard or 0) > 0.5 and "guard" or "inventory"
        return sp > 0.3 and "crouch_walk" or "crouch"
    end
    if (P.menu or 0) > 0.5 then return "inventory" end
    if (P.heal or 0) > 0.5 then return "heal" end
    if (P.guard or 0) > 0.5 then return "guard" end
    if (P.shoot or 0) > 0.5 then return "gun_shoot" end -- (9.28)
    if (P.aim or 0) > 0.5 then return "gun_aim" end
    if (P.gun or 0) > 0.5 then
        if (P.crouch or 0) > 0.5 then return "gun_crouch" end
        if sp < 0.3 then return "gun_idle" end
        return CFG.run.remote(os.clock(), sp) and "gun_run" or "gun_walk"
    end
    if (P.crouch or 0) > 0.5 then return sp > 0.3 and "crouch_walk" or "crouch" end
    if sp < 0.3 then return "idle" end
    return CFG.run.remote(os.clock(), sp) and "run" or "walk" -- (10.12) their running bit, or their speed with a bar to stay running
end

-- The pose of a block at time t of a looping clip, as thousandths: the last XFADE seconds are blended into the first so it has no seam.
function CFG.clip.pose_at(blk, rate, dur, t)
    local C = CFG.clip
    local frames = blk.frames
    local n = #frames[1]
    local function at(tt)
        local x = math.max(0, tt * rate)
        local i = math.floor(x)
        return C.lerp(frames[math.min(i + 1, #frames)], frames[math.min(i + 2, #frames)], x - i, blk.na, n)
    end
    local X = math.min(C.XFADE, dur * 0.25)
    local L = dur - X
    if L < 0.1 then return at(0) end
    t = t % L
    local p = at(t)
    if t < X then p = C.lerp(at(t + L), p, t / X, blk.na, n) end
    return p
end

-- (10.8) THE ARMS OF ANOTHER SAVED CLIP OVER THE ONE THAT PLAYS (a crouched block, a crouched inventory: the legs and back are the crouch clip's, the arms and
-- hands the saved block / inventory clip's, both recorded from the owner's Ethan). `p` is the pose about to be written (flat thousandths, `blk.names` order); the
-- arm joints of it are blended towards the same joints of the other clip by a weight that rises in 0.25 s and falls the same way when the state ends.
CFG.clip.ARM_PARTS = { Shoulder = true, UpperArm = true, Forearm = true, Hand = true, Palm = true, Thumb = true, IndexF = true, MiddleF = true, RingF = true, PinkyF = true }
function CFG.clip.arm_joint(nm)
    local part = type(nm) == "string" and nm:match("^[LR]_(%a+)%d?$")
    return part ~= nil and CFG.clip.ARM_PARTS[part] == true
end

function CFG.clip.arms_over(blk, p, dt)
    local C, P = CFG.clip, CFG.clip.P
    local want = C.arms
    if want then P.arm_label = want end
    local target = want and 1 or 0
    P.arm_w = P.arm_w or 0
    if P.arm_w < target then P.arm_w = math.min(target, P.arm_w + dt / C.BLEND) elseif P.arm_w > target then P.arm_w = math.max(target, P.arm_w - dt / C.BLEND) end
    if P.arm_w <= 0 then
        P.arm_label, P.arm_t = nil, 0
        C.arms_active = nil
        return
    end
    local ac = P.arm_label and C.get(P.arm_label) or nil
    if not (ac and ac.body and ac.body.names and ac.body.frames and #ac.body.frames > 0) then C.arms_active = nil return end
    P.arm_t = (P.arm_t or 0) + dt
    local q = C.pose_at(ac.body, ac.rate, ac.dur, P.arm_t)
    local idx = blk._idx
    if not idx then
        idx = {}
        for i, nm in ipairs(blk.names) do idx[nm] = i end
        blk._idx = idx
    end
    local n = 0
    for j, nm in ipairs(ac.body.names) do
        local i = idx[nm]
        if i and C.arm_joint(nm) then
            for k = 0, 2 do
                local a, b = p[3 * i - 2 + k], q[3 * j - 2 + k]
                if a ~= nil and b ~= nil then
                    local d = b - a
                    if d > 3141.6 then d = d - 6283.2 elseif d < -3141.6 then d = d + 6283.2 end
                    p[3 * i - 2 + k] = a + d * P.arm_w
                end
            end
            n = n + 1
        end
    end
    C.arms_active = { label = P.arm_label, joints = n, weight = math.floor(P.arm_w * 100) / 100 }
    C.arms_count = (C.arms_count or 0) + 1
end

-- Every tick of the chosen game phase while playing: pick the clip, move along it, ease from the old pose, write the joints.
function CFG.clip.play_tick(now)
    local C, B = CFG.clip, CFG.body
    local P = C.P
    if not (B.go and B.xf) then P.clip, P.last, P.label, P.joints, P.xf, P.last_at = nil, nil, nil, {}, nil, nil return end
    if P.xf ~= B.xf then P.xf, P.joints, P.hipj, P.warned, P.hip_off = B.xf, {}, nil, nil, nil end
    if CFG.gmot and CFG.gmot.drives() then P.clip, P.last, P.last_at = nil, nil, now return end -- (10.2) the game's own clip animates the body now
    local dt = P.last_at and math.max(0, math.min(now - P.last_at, 0.1)) or 0
    P.last_at = now
    if C.preview > 1 then C.arms = nil end
    local want = C.preview > 1 and C.LABELS[C.preview] or C.choose()
    if want ~= P.cand then P.cand, P.cand_at = want, now end
    if P.label == nil or now - P.cand_at >= 0.2 or C.preview > 1 then P.label = P.cand end
    local lab, clip = P.label, nil
    for _ = 1, 4 do
        clip = C.get(lab)
        if clip or not C.FALLBACK[lab] then break end
        lab = C.FALLBACK[lab]
    end
    if not clip then
        if P.warned ~= P.label then P.warned = P.label C.note("Play: no clip for " .. tostring(P.label) .. " (record one); the body keeps its pose") end
        return
    end
    if clip ~= P.clip then P.from, P.blend, P.t, P.clip = P.last, P.last and 0 or 1, 0, clip end
    if P.noted ~= P.label then
        P.noted = P.label
        C.note(string.format("Play: %s%s", lab, lab ~= P.label and (" (instead of " .. tostring(P.label) .. ")") or ""))
    end
    local k = 1
    if clip.speed and clip.speed > 0.3 and (lab == "walk" or lab == "run" or lab == "crouch_walk" or lab == "gun_walk" or lab == "gun_run") then
        k = math.max(0.6, math.min(1.6, (state.speed or 0) / clip.speed))
    end
    P.t = P.t + dt * k
    local blk = clip.body
    local p = C.pose_at(blk, clip.rate, clip.dur, P.t)
    if P.blend < 1 and P.from and #P.from == #p then
        P.blend = math.min(1, P.blend + dt / C.BLEND)
        p = C.lerp(P.from, p, P.blend, blk.na, #p)
    end
    pcall(C.arms_over, blk, p, dt) -- (10.8) the arms of the saved block / inventory clip over a crouch
    P.last = p
    local ok, err = pcall(function()
        for i, nm in ipairs(blk.names) do
            local j = P.joints[nm]
            if j == nil then
                j = B.xf:call("getJointByName", nm) or false
                P.joints[nm] = j
                if nm == "Hip" then P.hipj = j or nil end
            end
            if j then j:call("set_LocalEulerAngle", Vector3f.new(p[3 * i - 2] / 1000, p[3 * i - 1] / 1000, p[3 * i] / 1000)) end
        end
    end)
    if ok and blk.hip and P.hipj and not P.hip_off then
        local okh, errh = pcall(function() P.hipj:call("set_LocalPosition", Vector3f.new(p[blk.na + 1] / 1000, p[blk.na + 2] / 1000, p[blk.na + 3] / 1000)) end)
        if not okh then
            P.hip_off, C.errors = true, C.errors + 1
            C.note("Play: the hip's position can't be set (" .. tostring(errh):sub(1, 60) .. "); angles only", true)
        end
    end
    if not ok then
        C.play, C.errors = false, C.errors + 1
        C.note("Play stopped: " .. tostring(err):sub(1, 100), true)
    end
end

function CFG.clip.tick(now)
    local C = CFG.clip
    C.ticks = C.ticks + 1
    if C.rec then C.sample(now) end
    if C.play then C.play_tick(now) end
end

-- Every render frame: the F10 key. (9.32) F10 STOPS a running recording whatever started it; it STARTS one only while the recorder is switched on.
function CFG.clip.update()
    local C, B = CFG.clip, CFG.body
    local okk, down = pcall(function() return reframework:is_key_down(C.hotkey) end)
    down = okk and down == true
    if down and not C.key_was_down then
        if C.rec then
            C.rec.stop = true
            C.rec.stop_why = C.rec.stop_why or "you pressed F10"
            C.f10_stops = (C.f10_stops or 0) + 1
        elseif C.enabled then
            B.later("Record", C.start)
        end
    end
    C.key_was_down = down
end

function CFG.clip.draw(now)
    local C = CFG.clip
    if C.rec then
        pcall(draw.text, string.format("REC %s  %.1f / %d s   (F10 stops)", C.rec.file_label or C.LABELS[C.rec.want], now - C.rec.t0, C.rec.secs or C.secs), 24, 44, 0xFF0000FF)
    end
end

function CFG.clip.report()
    local C = CFG.clip
    local lib = {}
    for label, clip in pairs(C.lib) do
        if clip then
            lib[label] = { source = C.src[label], dur = clip.dur, speed = clip.speed, frames = #clip.body.frames, joints = #clip.body.names, hands = clip.hands ~= nil,
                note = clip.note, flags = clip.flags, moving = clip.moving, moving_count = clip.moving_count, missing = clip.missing, ids = clip.ids }
        end
    end
    return { enabled = C.enabled, recording = C.rec ~= nil, play = C.play, playing = C.P.label, saved = C.saved, errors = C.errors,
        builtin_only = C.builtin_only, defaults = CFG.defaults.report(), ticks = C.ticks, library = lib, lines = C.lines,
        arms_over_the_crouch = { about = "10.8: a crouched block / inventory shows the crouch clip with the ARMS of the saved block / inventory clip (recorded from your Ethan) over it", now = C.arms_active, ticks = C.arms_count or 0 } }
end

give.id_getters = { "getItemDataId", "get_ItemDataId", "getItemId", "get_ItemId", "getName", "get_Name", "getItemName", "get_ItemName" }

-- (9.33) REFramework writes a warning to its log for every call of a method with the wrong number of arguments, and app.Item.getItemDataId takes
-- one: the pointing hook made 34,000 of those in 50 minutes. How many arguments a method takes is looked up once per type and name; a getter that
-- is known to take some is not called. (When it cannot be told, the call is made as before.)
give.arity_cache = {}
function give.arity(obj, name)
    local okt, td = pcall(function() return obj:get_type_definition() end)
    if not okt or td == nil then return nil end
    local okn, tn = pcall(function() return td:get_full_name() end)
    local key = tostring(okn and tn or "?") .. "." .. name
    local c = give.arity_cache[key]
    if c == nil then
        c = -1
        local okm, m = pcall(function() return td:get_method(name) end)
        if okm and m ~= nil then
            local okp, np = pcall(function() return m:get_num_params() end)
            if okp and type(np) == "number" then c = np end
        end
        give.arity_cache[key] = c
    end
    if c < 0 then return nil end
    return c
end

function give.callable(obj, name)
    local n = give.arity(obj, name)
    return n == nil or n == 0
end
items.callable = give.callable
give.count_getters = { "getTotalStackNum", "get_StackNum", "getStackNum", "get_Num", "getNum" }

-- Item names are letters, digits and underscores ("Herb", "ChemicalS", "CylinderKey"). The same check guards the
-- network messages, so anything else is refused.
local function plausible_id(t)
    return type(t) == "string" and #t >= 2 and #t <= 40 and t:match("^[%w_]+$") ~= nil and t:match("^%d+$") == nil
end

-- Text fields of obj that look like an item name, id-ish field names first: { {field, text}, ... }
local function id_strings(obj)
    local out = {}
    for _, f in ipairs(fields_of_type(obj, "System.String")) do
        local t = as_text(f[2])
        if plausible_id(t) then
            local low = f[1]:lower()
            out[#out + 1] = { f[1], t, (low:find("id", 1, true) or low:find("name", 1, true)) and 1 or 2 }
        end
    end
    table.sort(out, function(a, b) return a[3] < b[3] end)
    return out
end

-- Learns an item's name. The 2026-11 test showed getItemDataId on its own is not enough (the pointed-at item was
-- seen but its name came back unusable), so this tries, in order: the id getters (as text, or as an object with a
-- text field), text fields on the item, the item's save data, and the GameObject's name.
-- Returns id, where-it-came-from; or nil, nil, a note on what each attempt returned.
local function resolve_item_id(item)
    local notes = {}
    local function note(t) notes[#notes + 1] = t end
    for _, g in ipairs(give.id_getters) do
        local ok, v
        if give.callable(item, g) then
            ok, v = pcall(function() return item:call(g) end)
        else
            ok, v = false, "takes arguments"
        end
        if not ok then
            note(g .. (v == "takes arguments" and ": takes arguments, not called" or ": no such method"))
        elseif v == nil then
            note(g .. ": nil")
        else
            local t = as_text(v)
            if plausible_id(t) then return t, g end
            if type(v) == "number" then
                note(g .. ": the number " .. tostring(v))
            elseif type(v) == "string" then
                note(g .. ": text \"" .. v:sub(1, 30) .. "\" (not usable)")
            else
                local inner = id_strings(v)
                if inner[1] then return inner[1][2], g .. "." .. inner[1][1] end
                note(g .. ": an object " .. dump_value(v) .. " with no name inside")
            end
        end
    end
    local own = id_strings(item)
    if own[1] then return own[1][2], "item field " .. own[1][1] end
    local oks, sd = pcall(function() return item:call("getItemSaveData") end)
    if oks and sd ~= nil and type(sd) ~= "number" and type(sd) ~= "string" then
        local inner = id_strings(sd)
        if inner[1] then return inner[1][2], "getItemSaveData." .. inner[1][1] end
        note("getItemSaveData: an object with no name inside")
    end
    local okg, go = pcall(function() return item:call("get_GameObject") end)
    if okg and go ~= nil then
        local okn, nm = pcall(function() return go:call("get_Name") end)
        nm = okn and as_text(nm) or nil
        if nm then nm = nm:gsub("%(Clone%)$", ""):gsub("^%s+", ""):gsub("%s+$", "") end
        if plausible_id(nm) then return nm, "GameObject name" end
        note("GameObject name: " .. tostring(nm))
    end
    return nil, nil, table.concat(notes, "; ")
end

local function item_id_of(item)
    return resolve_item_id(item)
end
items.id_of = item_id_of -- (9.32: the pickup hook is defined further up and reads the item's name the same way the inventory list does)

-- count, known. known is false when no getter answered and the count is just assumed to be 1.
local function item_count_of(item)
    for _, getter in ipairs(give.count_getters) do
        local ok, n = pcall(function() return item:call(getter) end)
        if ok and type(n) == "number" and n >= 1 and n < 100000 then return math.floor(n), true end
    end
    return 1, false
end

-- Runs when the game asks whether the highlighted item can be used/discarded (the inventory menu does this
-- when the cursor lands on an item), so `this` is the item under the cursor. The item is remembered even if
-- its name can't be read; then the diagnostics are written to the debug file by themselves.
local function on_item_focus(args)
    local item = sdk.to_managed_object(args[2])
    if not item then return end
    give.hover_seen = (give.hover_seen or 0) + 1
    local id, src, why = item_id_of(item)
    local count, known = item_count_of(item)
    give.focus = { item = item, id = id, src = src, why = why, count = count, count_known = known, at = os.clock() }
    if id and items.cat_cache[id] == nil then pcall(items.category_of, item, id) end -- (10.12: so a drop of it can be refused if it is a key item or a weapon)
    if not id and os.clock() - give.auto_dump_at > 120 then give.want_dump = "the pointed-at item's name could not be read" end
end

-- Everything in the inventory: { { item, id, count }, ... }. The inventory object has a List of
-- app.Inventory.ItemInfo (field _ItemList, seen in your dump); each entry holds an app.Item.
local function list_elements(list)
    local out = {}
    local okc, n = pcall(function() return list:call("get_Count") end)
    if okc and type(n) == "number" then
        for i = 0, math.min(n, 200) - 1 do
            local ok, v = pcall(function() return list:call("get_Item", i) end)
            if ok and v ~= nil then out[#out + 1] = v end
        end
        if #out > 0 then return out end
    end
    local oka, arr = pcall(function() return list:get_field("_items") end)
    if oka and arr then
        local oke, els = pcall(function() return arr:get_elements() end)
        if oke and els then
            for _, v in ipairs(els) do
                if v ~= nil then out[#out + 1] = v end
            end
        end
    end
    return out
end

local function item_of_info(info)
    local ok, tn = pcall(function() return info:get_type_definition():get_full_name() end)
    if ok and tn == "app.Item" then return info end
    for _, f in ipairs(fields_of_type(info, "app.Item")) do return f[2] end
    for _, m in ipairs({ "get_Item", "getItem" }) do
        local okc, v = pcall(function() return info:call(m) end)
        if okc and v ~= nil and type(v) ~= "number" then return v end
    end
    return nil
end

-- Number fields of an inventory entry that look like a stack size (used if the item has no count getter).
local function entry_count(info)
    for _, f in ipairs(fields_of_type(info, "System.Int32")) do
        local low = f[1]:lower()
        if (low:find("num", 1, true) or low:find("count", 1, true) or low:find("stack", 1, true)) and type(f[2]) == "number"
            and f[2] >= 1 and f[2] < 100000 then
            return math.floor(f[2])
        end
    end
    return nil
end

local function inventory_items()
    local inv = inventory_object()
    if not inv then
        local t = mgr.inv_log.tried
        return nil, "inventory object not found" .. (t and #t > 0 and (" (" .. table.concat(t, "; "):sub(1, 160) .. ")") or "")
    end
    local ok, list = pcall(function() return inv:get_field("_ItemList") end)
    if not ok or list == nil then
        -- (9.30) it answered a moment ago and does not now: look for the live one at once, once
        mgr.inv_lost(ok and "its _ItemList is nil" or "reading its _ItemList raised an error")
        inv = inventory_object()
        if not inv then return nil, "the inventory stopped answering and no other was found" end
        ok, list = pcall(function() return inv:get_field("_ItemList") end)
        if not ok or list == nil then return nil, "the inventory has no _ItemList" end
    end
    local entries = list_elements(list)
    local out, noitem, noid, first_why = {}, 0, 0, nil
    for _, info in ipairs(entries) do
        local item = item_of_info(info)
        local id, src, why, count, known
        if item then
            id, src, why = item_id_of(item)
            count, known = item_count_of(item)
        else
            noitem = noitem + 1
        end
        if not id then
            local own = id_strings(info) -- the entry itself may carry the name
            if own[1] then id, src = own[1][2], "entry field " .. own[1][1] end
        end
        if id then
            if not known then count = entry_count(info) or count or 1 end
            out[#out + 1] = { item = item, id = id, count = count or 1, src = src }
        elseif item then
            noid = noid + 1
            first_why = first_why or why
        end
        if #out >= 40 then break end
    end
    local note
    if #entries == 0 then
        note = "the list is empty"
    elseif noitem + noid > 0 then
        note = string.format("%d of %d entries unreadable: %d without an app.Item, %d whose name I can't read%s", noitem + noid,
            #entries, noitem, noid, first_why and (" [" .. first_why .. "]") or "")
        if #out == 0 and os.clock() - give.auto_dump_at > 120 then give.want_dump = "the inventory list could not be read" end
    end
    return out, note
end

-- (10.5) ETHAN'S FRIEND (the "loopback bot" until 10.4): an AI helper you play the game with, alone. It is NOT a network player: no real peer is
-- involved, re7mp.exe plays it over 127.0.0.1 in its "Ethan's friend" mode (the old exe calls it "Loopback Bot": both names are accepted), and
-- nothing in this module runs while a real player is connected (CFG.friend.present() is false then).
--   * Its look is chosen in re7mp.exe ("Appear as", the exe says "char" for it); your own character is not touched.
--   * (10.8) IT HAS ITS OWN WEAPONS AND AMMO. Before 10.8 weapons and ammo were shared with you and it had none; now a weapon or ammo you give it (F7,
--     within 3 m) leaves your inventory and is kept by it, like everything else, and it shoots with them (CFG.friend.fight below).
--   * It has its OWN inventory: what you give it (F7, or the panel) leaves yours and is kept here, in re7mp/friend.json, so a restart does not lose it.
--     It uses healing items on itself and on you; weapons and ammo go into its shots. Nothing comes back out yet (it does not hand items back: later).
CFG.friend = {
    NAME = "Ethan's friend", OLD_NAME = "Loopback Bot",
    SHARED = {}, -- (10.8) was { [1] = true, [2] = true, [8] = true }: weapons and ammo were shared with you and refused as gifts. Now it carries and uses its own: nothing is shared
    inv = {}, loaded = false, taken = 0, refused_shared = 0, refused_unread = 0, last = "nothing given to it yet", last_refused = nil, saves = 0, save_errors = 0,
    MAX_KINDS = 60,
    -- (10.9) its crouching body: how high it stands above its floor (m, -2 .. 0.6; its camera is pinned at the standing height, so 0 = feet on the floor) and how fast it gets down
    crouch_lift = 0.0, CROUCH_BLEND = 16.0,
}

function CFG.friend.is_name(n) return n == CFG.friend.NAME or n == CFG.friend.OLD_NAME end

-- Is the other player Ethan's friend right now (and not a real player)?
function CFG.friend.present() return CFG.friend.is_name(state.remote_name) end

-- (10.10) "the crouch is in the ground again; it works for a second or 2 when I start crouching but then the model goes into the ground".
-- A fixed number of metres cannot be right: how deep a crouch clip puts the feet below the root depends on the clip, the model and the size (10.8 stood
-- the body up 0.5 m + the slider and it floated; 10.9 stood it up by the slider alone, 0 m, and it sank; your 0.4 in the old slider no longer reached the
-- friend). So the friend now MEASURES its own feet: while it is crouched, the lowest of its toe joints is read (world height, from the body I made) and the body
-- is stood up until that toe is as high above the floor as it was when the friend was standing (the median of its last standing readings; 0.03 m before
-- there is one). The slider is added on top as a fine tune. The numbers are in friend.json / debug.json (crouch.feet).
CFG.friend.ground = {
    on = true, MAX_UP = 1.2, MAX_DOWN = -0.3, SMOOTH = 14.0, RING_EVERY = 0.25, RING_N = 24, SOLE_TOES = 0.03, SOLE_FEET = 0.08, CR_MIN = 0.05,
    SETS = { { key = "toes", names = { "R_Toe", "L_Toe" } }, { key = "feet", names = { "R_Foot", "L_Foot" } } },
    xf = nil, set = nil, joints = nil, ring = {}, ring_at = -10, ref = nil, low = nil, need = 0, lift = 0, at = -10, reads = 0, failures = 0,
    standing_samples = 0, crouch_logged = false, why = "no reading yet", last_err = nil, notes = 0,
}

do
    local G = CFG.friend.ground

    local function median(t)
        local c = {}
        for i, v in ipairs(t) do c[i] = v end
        table.sort(c)
        local n = #c
        if n == 0 then return nil end
        if n % 2 == 1 then return c[(n + 1) / 2] end
        return (c[n / 2] + c[n / 2 + 1]) / 2
    end
    G.median = median

    -- The lowest foot joint of the body, in metres above the body object's own position (world metres: the size is in it). Returns the number and the joint set used.
    function G.read(xf)
        if G.xf ~= xf then -- a new body: nothing of the old one is kept
            G.xf, G.set, G.joints, G.ring, G.ref, G.ring_at = xf, nil, nil, {}, nil, -10
        end
        if G.joints == nil then
            for _, S in ipairs(G.SETS) do
                local js = {}
                for _, nm in ipairs(S.names) do
                    local ok, j = pcall(function() return xf:call("getJointByName", nm) end)
                    if ok and j then js[#js + 1] = j end
                end
                if #js > 0 then G.joints, G.set = js, S.key break end
            end
            if G.joints == nil then return nil, "none" end
        end
        local root = xf:call("get_Position")
        local low
        for _, j in ipairs(G.joints) do
            local y = j:call("get_Position").y - root.y
            if type(y) == "number" and y == y and (low == nil or y < low) then low = y end
        end
        return low, G.set
    end

    function G.sole()
        return G.set == "feet" and G.SOLE_FEET or G.SOLE_TOES
    end

    -- Every frame the friend's body is placed (from CFG.body.crouch_lift): cr is 0 standing .. 1 crouched. Returns the lift (m) that is wanted now.
    function G.update(xf, cr, now)
        if not G.on or not xf then G.need, G.lift, G.why = 0, 0, G.on and "no body" or "switched off" return 0 end
        if now - G.at < 0.004 then return G.lift end -- already read this frame (the report asks too)
        local dt = math.max(0.001, math.min(0.1, now - G.at))
        G.at = now
        local ok, low, set = pcall(G.read, xf)
        if not ok then
            G.failures = G.failures + 1
            G.last_err = tostring(low):sub(1, 90)
            G.xf, G.joints = nil, nil -- the joints may be gone with the old mesh: look them up again
            G.need, G.why = 0, "the feet could not be read (" .. G.last_err .. ")"
            G.lift = G.lift + (0 - G.lift) * (1 - math.exp(-G.SMOOTH * dt))
            return G.lift
        end
        if low == nil then
            G.need, G.why = 0, "the body has no foot joints (yet)"
            G.lift = G.lift + (0 - G.lift) * (1 - math.exp(-G.SMOOTH * dt))
            return G.lift
        end
        G.reads, G.low = G.reads + 1, low
        local need = 0
        if cr >= G.CR_MIN then
            local ref = G.ref or G.sole()
            need = math.max(G.MAX_DOWN, math.min(G.MAX_UP, ref - low))
            G.why = string.format("crouched: lowest %s %.2f m above its place, %.2f m where it stood: lifting %.2f m", set, low, ref, need)
            if not G.crouch_logged and cr > 0.6 then
                G.crouch_logged = true
                G.notes = G.notes + 1
                pcall(CFG.body.note, string.format("Friend crouch: its lowest %s is %.2f m above the body's origin (%.2f m when it stood%s): the body is stood up %.2f m so its feet are on the floor",
                    set, low, ref, G.ref and "" or ", the default: no standing reading yet", need), true)
            end
        else
            G.crouch_logged = false
            G.why = "standing: its feet are read for the place of the floor"
            if now - G.ring_at >= G.RING_EVERY then -- a standing reading: what the lowest toe is when it is on the floor (walking too: the foot that is down)
                G.ring_at = now
                G.ring[#G.ring + 1] = low
                if #G.ring > G.RING_N then table.remove(G.ring, 1) end
                G.standing_samples = G.standing_samples + 1
                G.ref = median(G.ring)
            end
        end
        G.need = need
        G.lift = G.lift + (need - G.lift) * (1 - math.exp(-G.SMOOTH * dt))
        return G.lift
    end

    function G.report()
        local function r(v) return v and math.floor(v * 100 + 0.5) / 100 or nil end
        return { on = G.on, joints = G.set, lowest_above_origin_m = r(G.low), standing_value_m = r(G.ref), wanted_lift_m = r(G.need), lift_m = r(G.lift),
            readings = G.reads, standing_readings = G.standing_samples, failures = G.failures, last_error = G.last_err, now = G.why }
    end
end

function CFG.friend.load()
    local F = CFG.friend
    if F.loaded then return end
    F.loaded = true
    local ok, d = pcall(FILES.read, "friend")
    if not ok or type(d) ~= "table" or type(d.inventory) ~= "table" then return end
    for id, n in pairs(d.inventory) do
        if type(id) == "string" and id:match("^[%w_]+$") and #id <= 48 and tonumber(n) and tonumber(n) >= 1 and tonumber(n) <= 9999 then F.inv[id] = math.floor(tonumber(n)) end
    end
end

function CFG.friend.save()
    local F = CFG.friend
    local ok, err = pcall(json.dump_file, FILES.path("friend"), { build = CFG.BUILD,
        about = "re7mp: what Ethan's friend carries (items you gave it: weapons and ammo it shoots with, healing items it uses). They left your inventory when you gave them.", inventory = F.inv })
    if ok then F.saves = F.saves + 1 else F.save_errors, F.last_error = F.save_errors + 1, tostring(err):sub(1, 100) end
end

-- Is this item a weapon or ammo (shared with the friend)? true and the kind's name, or false (and the name, when it could be read).
-- A kind that can't be read is NOT refused: the friend simply carries it.
function CFG.friend.shared_kind(id)
    local n = items.cat_cache[id]
    if n == nil then
        local list = inventory_items()
        if list then
            for _, e in ipairs(list) do
                if e.id == id and e.item ~= nil then n = items.category_of(e.item, id) break end
            end
        end
    end
    if n ~= nil and CFG.friend.SHARED[n] then return true, items.category_name(n) end
    return false, n ~= nil and items.category_name(n) or nil
end

-- A gift of `id`: should it be refused because it is shared? Returns true and the words for the screen.
function CFG.friend.refuse_gift(id)
    local F = CFG.friend
    local ok, shared, kind = pcall(F.shared_kind, id)
    if not ok then F.refused_unread = F.refused_unread + 1 return false end
    if not shared then return false end
    F.refused_shared, F.last_refused = F.refused_shared + 1, string.format("%s (%s)", id, tostring(kind))
    return true, string.format("%s is %s: weapons and ammo are shared with %s, which uses yours, so there is nothing to give. You keep it", id, tostring(kind), F.NAME)
end

-- The friend confirmed a gift and it left your inventory: it is in the friend's inventory now.
function CFG.friend.take(id, n)
    local F = CFG.friend
    F.load()
    local kinds = 0
    for _ in pairs(F.inv) do kinds = kinds + 1 end
    if F.inv[id] == nil and kinds >= F.MAX_KINDS then F.last = string.format("%s x%d: the friend's list is full (%d kinds)", id, n, F.MAX_KINDS) return false end
    F.inv[id] = (F.inv[id] or 0) + n
    F.taken = F.taken + n
    F.last = string.format("took %s x%d (now %d)", id, n, F.inv[id])
    F.save()
    return true
end

function CFG.friend.report()
    local F = CFG.friend
    F.load()
    local list = {}
    for id, n in pairs(F.inv) do list[#list + 1] = { id = id, count = n } end
    table.sort(list, function(a, b) return a.id < b.id end)
    local okh, helps = pcall(function() return F.ai and F.ai.report() or nil end)
    if not okh then helps = { error = tostring(helps):sub(1, 120) } end
    local okb, body = pcall(function() return F.body and F.body.report() or nil end)
    if not okb then body = { error = tostring(body):sub(1, 120) } end
    local okf, fights = pcall(function() return F.fight and F.fight.report() or nil end)
    if not okf then fights = { error = tostring(fights):sub(1, 120) } end
    local okv, after_over = pcall(function() return F.over and F.over.report() or nil end)
    if not okv then after_over = { error = tostring(after_over):sub(1, 120) } end
    return { name = F.NAME, is_here_now = F.present(), about = "the friend is not a network player; everything it carries is listed here (10.8: its own weapons and ammo too; nothing is shared with you)",
        fights = fights, -- (10.8) its shooting, its ammo, its health and what it did about it
        after_game_over = after_over, -- (10.9) it gets up at full health and is put next to you once the reload after a game over has finished
        body = body, -- (10.7) what its body does for itself: block, facing, the height it stands at, the trail it reads it from
        helps = helps, -- (10.6) revive and heal: the switches, the threshold, what it is doing, the healing items it carries, what it did
        carries = list, items_taken = F.taken, gifts_refused_as_shared = F.refused_shared, last_refused = F.last_refused, gifts_with_unreadable_kind = F.refused_unread,
        last = F.last, file_saves = F.saves, file_errors = F.save_errors, last_error = F.last_error }
end

local function raw_int(v)
    v = sdk.to_int64(v) % 4294967296
    if v >= 2147483648 then v = v - 4294967296 end
    return v
end

-- The journal says what every discard-like call was taken for (25 lines at most): the 0.8 file had a discard that dropped
-- nothing and left no line at all, so it was impossible to tell which condition had failed.
function give.discard_note(msg)
    give.discard_lines = (give.discard_lines or 0) + 1
    if give.discard_lines <= 25 then say("discard: " .. msg) end
end

-- A drop to be spawned a moment later, after the game has finished the discard. Once per discard: two hooks see the same one.
function give.queue_drop(id, n, now, how)
    if not give.ground then -- the ground route is off: the game's own discard stands; nothing is created for the ground
        give.discard_note(string.format("%s: %s x%d discarded as the game does it (the ground route is off, so it is not put on the ground)", how, id, n))
        return
    end
    local q = give.dropq
    if q and q.id == id and now - q.at < 3 then
        give.discard_note(string.format("%s: %s x%d is already queued for the ground", how, id, n))
        return
    end
    give.dropq = { id = id, at = now }
    give.pending_drop = { id = id, n = n, at = now }
    give.discard_note(string.format("%s: %s x%d will be put on the ground", how, id, n))
end

-- Runs just before app.Item.reduceNum(count, player): the inventory's Discard (also used when something is consumed).
local function on_item_reduce(args)
    local now = os.clock()
    give.reduce_seen = (give.reduce_seen or 0) + 1
    local item = sdk.to_managed_object(args[2])
    local who = sdk.to_managed_object(args[4])
    local id = item and item_id_of(item)
    local n = raw_int(args[3])
    local function skip(why) give.discard_note(string.format("reduceNum(%s x%s) is not a discard I drop: %s", tostring(id), tostring(n), why)) end
    -- Moving an item into the item box is also a reduceNum, and the inventory menu was in use, so it looked like a discard: the
    -- 9.18 files have "drop: making Gunpowder / CylinderKey / ShotgunBullet / HandgunBullet / RemedyM for the ground" for item box moves
    -- (and the other player was told about drops that never happened). The real discard was proven to be InventoryMenu.discardItem
    -- (9.14 file: menu_discard_calls 1, reduceNum_calls 0), so while that hook is installed reduceNum is never taken for a discard.
    if give.discard_hooked then
        give.reduce_ignored = (give.reduce_ignored or 0) + 1
        return skip("the item box, crafting and using items call reduceNum too; a real discard comes from InventoryMenu.discardItem")
    end
    if not give.drop_on_discard then return skip("'Discard drops the item' is switched off") end
    local f = give.focus
    if not f or not f.id or now - f.at > 30 then return skip("the inventory menu was not used in the last 30 s") end
    if not item or not who then return skip("the item or the player could not be read") end
    if not is_player_name(who:call("get_Name")) then return skip("the second argument is not the player") end
    mgr.player = who
    if not id or id ~= f.id or n < 1 or n > 999 then return skip("it is not the item the menu was on (" .. tostring(f.id) .. ") or the count is odd") end
    give.queue_drop(id, n, now, "reduceNum")
end

-- The inventory menu's own discard, app.InventoryMenu.discardItem(app.Item) -> Boolean (it is in the file's method list):
-- the item comes with the call, no "highlighted item" is needed, and the answer says whether it was discarded.
function give.on_discard_item(args)
    local item = sdk.to_managed_object(args[3])
    local id = item and item_id_of(item)
    local n = item and item_count_of(item) or 1
    give.discard_calls = (give.discard_calls or 0) + 1
    if item and id and items.cat_cache[id] == nil then pcall(items.category_of, item, id) end -- (10.12: the category is read while the item is still in the inventory)
    give.discarding = { id = id, n = n, at = os.clock() }
end

function give.after_discard_item(retval)
    local d = give.discarding
    give.discarding = nil
    if not d then return end
    local okv, v = pcall(sdk.to_int64, retval)
    local yes = okv and type(v) == "number" and v % 256 ~= 0
    if not yes then return give.discard_note(string.format("the menu's discardItem(%s) answered no: nothing dropped", tostring(d.id))) end
    if not give.drop_on_discard then return give.discard_note("the menu discarded " .. tostring(d.id) .. "; 'Discard drops the item' is switched off") end
    if not d.id then return give.discard_note("the menu discarded an item whose name I can't read: nothing dropped") end
    give.queue_drop(d.id, math.max(1, math.min(d.n or 1, 999)), os.clock(), "discardItem")
end

local function remember_item_manager(args)
    if CFG.pick and CFG.pick.on then pcall(CFG.pick.on_create, args) end -- (9.31: the item journal)
    local im = sdk.to_managed_object(args[2])
    if im then
        mgr.captured_im = im
        -- Taken over only when the copy in use does not know the items and this one does. This hook runs for every item
        -- the game creates, so a copy that knows the items is never replaced, and nothing is asked of it once one is in use.
        if not mgr.item_manager_ok and mgr.im_knows(im) then
            mgr.item_manager, mgr.item_manager_how, mgr.item_manager_ok = im, "the one the game's own createItemInstance call used", true
        end
    end
    local p = sdk.to_managed_object(args[3])
    if p and is_player_name(p:call("get_Name")) then mgr.player = p end
end

local function remember_inventory(args)
    -- getExtendLevelState is a static call in this game: args[2] is its number, not an inventory (that error filled the journal)
    if mgr.inv_hook_dead then return end
    local ok, inv = pcall(sdk.to_managed_object, args[2])
    if not ok or not inv then
        mgr.inv_hook_dead = true
        return
    end
    mgr.captured_inv = inv -- (9.30: only a last resort for inventory_object(); it no longer replaces the one in use, which may be the right one)
end

local function install_give_hooks()
    local n = 0
    if hook_method("app.Item", "isCanDiscard", on_item_focus) then n = n + 1 end
    if hook_method("app.Item", "reduceNum", on_item_reduce) then n = n + 1 end
    if hook_method("app.ItemManager", "createItemInstance", remember_item_manager) then n = n + 1 end
    if hook_method("app.Inventory", "getExtendLevelState", remember_inventory) then n = n + 1 end
    if hook_method("app.InventoryMenu", "discardItem", give.on_discard_item, give.after_discard_item) then give.discard_hooked = true end
    if hook_method("app.Inventory", "reOpenRequestInventoryMenu", give.on_reopen_request) then give.reopen_hooked = true end
    return n >= 2
end

local function game_object_of(obj)
    if obj == nil then return nil end
    local go
    pcall(function()
        local td = obj:get_type_definition()
        if td and td:get_full_name() == "via.GameObject" then
            go = obj
        else
            go = obj:call("get_GameObject")
        end
    end)
    return go
end

-- The game's creation calls answered nothing in the real file ("createItemInstance failed: nil", and a "drop" that was
-- reported but never appeared: the call had not failed, it had returned nil, which was taken for success). So: every way the
-- call might be meant is tried (the player object, then the owner the inventory's own entries carry; the name as a plain Lua
-- string, then as a managed string), the first one that returns an object wins and is remembered, and when none does the
-- answer says what was tried. Nothing is ever reported as done unless an object came back.
give.create_log = {}   -- the last attempts, for the debug file
local function item_owner_candidates()
    local out = {}
    local player = player_object()
    local pname
    if player then
        pname = as_text(player:call("get_Name"))
        out[#out + 1] = { name = "player", go = player }
    end
    -- Only the player. 9.12 and 9.13 also tried "the owner an inventory entry carries", which is an item's own object
    -- (sm1852_AntisepticSolutionMedium_Item in the file): handing that to the game's creation code is the likely crash.
    return out
end

-- Calls im:method(owner, id [, extra]) the ways described above. Returns the object, or nil plus the text of what was tried.
local function create_item_object(method, id, extra)
    local im = item_manager()
    if not im then return nil, "ItemManager not found" end
    local owners = item_owner_candidates()
    if #owners == 0 then return nil, "player object (Pl0000) not found" end
    local tried = {}
    for _, ow in ipairs(owners) do
        for _, form in ipairs({ "plain", "managed" }) do
            local sid = form == "plain" and id or managed_string(id)
            local ok, res = pcall(function()
                if extra ~= nil then return im:call(method, ow.go, sid, extra) end
                return im:call(method, ow.go, sid)
            end)
            local how = ow.name .. ", " .. form .. " name"
            if ok and res ~= nil then
                give.create_how = method .. ": " .. how
                return res
            end
            tried[#tried + 1] = how .. (ok and ": nothing came back" or (": " .. tostring(res):sub(1, 50)))
        end
    end
    local text = method .. " gave nothing (" .. table.concat(tried, "; ") .. ")"
    give.create_log[#give.create_log + 1] = string.format("%.0f  %s %s: %s", os.clock(), method, id, text)
    if #give.create_log > 12 then table.remove(give.create_log, 1) end
    return nil, text
end

-- What the game says about this item name, once a minute at most, into the debug file: is the name known, what does its item
-- data hold (maybe the prefab to create it from). Read-only.
local function item_probe(id, why)
    local now = os.clock()
    if now - (give.probe_at or -1e9) < 60 then return end
    give.probe_at = now
    local im = item_manager()
    if not im then return end
    say("give probe (" .. tostring(why) .. "): item " .. id)
    for i, c in ipairs(mgr.im_candidates(true)) do -- every copy of the manager the game has, and what each one knows
        local okf, d = pcall(function() return c.obj:call("findItemData", id) end)
        local okn, names = pcall(function() return c.obj:call("get_ItemDataIDNames") end)
        local cnt = okn and names ~= nil and #list_elements(names) or nil
        say(string.format("    give probe: copy %d, %s%s: findItemData -> %s, name list -> %s", i, c.how, c.obj == im and " (in use)" or "",
            okf and (d ~= nil and "an item" or "nil") or "error", cnt and (cnt .. " names") or "nil"))
    end
    local function try(label, f)
        local ok, v = pcall(f)
        say("    give probe: " .. label .. ": " .. (ok and (as_text(v) or tostring(v)) or ("error " .. tostring(v):sub(1, 80))))
        return ok and v or nil
    end
    local data = try("findItemData", function() return im:call("findItemData", id) end)
    if data ~= nil and type(data) ~= "number" and type(data) ~= "string" then pcall(dump_fields, data, "        ", 24) end
    local names = try("get_ItemDataIDNames", function() return im:call("get_ItemDataIDNames") end)
    if names ~= nil then
        local els = list_elements(names)
        local found, sample = false, {}
        for _, v in ipairs(els) do
            local t = as_text(v) or tostring(v)
            if t == id then found = true end
            if #sample < 12 then sample[#sample + 1] = t end
        end
        say(string.format("    give probe: the game lists %d item names, %s in it; first ones: %s", #els,
            found and ("'" .. id .. "' is") or ("'" .. id .. "' is NOT"), table.concat(sample, ", ")))
    end
end

-- Journal lines about adding an item to the inventory, 12 at most.
function give.add_note(msg)
    give.add_lines = (give.add_lines or 0) + 1
    if give.add_lines <= 12 then say("add: " .. msg) end
end

-- Crumbs around the calls that make or place items: if the game crashes in one, the next session names it.
function give.crumb(what) pcall(tracer.crumb, "give", what) end
function give.clean() pcall(tracer.crumb, "clean", "item call finished") end

-- THE BLACK BOX. The 9.15 and 9.16 sessions that tried to create an item ended with a crash 0.1 s after the last step, before
-- the journal (written every 2 s) or the debug file reached the disk, so the files said nothing about the attempt. Now every step of
-- anything that creates or places an item is written at once to its own small file (re7mp/trail.json, the last 80 steps), and the
-- debug file is written too. The next start reads the trail back: the debug file has it as health.items.previous_item_trail and the
-- first journal lines name the last step. The crumb file only names the step that was running; this one has what each step answered.
give.trail_list = {}
give.previous_trail = nil
function give.trail(what)
    local text = tostring(what):gsub("[\r\n]+", " "):sub(1, 400)
    give.trail_list[#give.trail_list + 1] = { t = math.floor(os.clock() * 1000) / 1000, w = text }
    if #give.trail_list > 120 then table.remove(give.trail_list, 1) end
    pcall(json.dump_file, FILES.path("trail"), { session = tracer.session, entries = give.trail_list })
    say("trail: " .. text)
    -- (9.36: no forced debug-file write here any more. 9.35 wrote the whole 380 KB file for EVERY trail line (221 times in one session) and the tester's
    -- game hitched and then closed. The trail has its own small file just above, written at once, and every line is in REFramework's own log too.)
end

mgr.inv_note = function(text) give.trail(text) end -- (9.30: the inventory lookup's own events go into the black box too)

-- Start of a session: what did the last one write before it ended?
-- The sessions before that: the trails of the last 6 sessions are kept in their own file, so a crash followed by a short
-- session does not wipe the evidence of the crash before it (the debug file lists them as earlier_item_trails).
give.history = {}
function give.load_history()
    local d = FILES.read("trail_history")
    if type(d) == "table" and type(d.sessions) == "table" then give.history = d.sessions end
end

function give.report_trail()
    pcall(give.load_history)
    local d = FILES.read("trail")
    if type(d) ~= "table" or d.session == tracer.session then return end
    local entries = type(d.entries) == "table" and d.entries or {}
    if #entries == 0 then return end
    give.previous_trail = entries
    local last = entries[#entries]
    do
        local keep = {}
        for i = math.max(1, #entries - 59), #entries do keep[#keep + 1] = entries[i] end
        give.history[#give.history + 1] = { ended_at_s = last.t, ended_with = tostring(last.w):sub(1, 200), entries = keep }
        while #give.history > 6 do table.remove(give.history, 1) end
        pcall(json.dump_file, FILES.path("trail_history"), { sessions = give.history })
    end
    say(string.format("previous session's item trail: %d steps, the last at %s s: %s", #entries, tostring(last.t), tostring(last.w)))
    pcall(json.dump_file, FILES.path("trail"), { session = tracer.session, entries = {} }) -- (so the same trail is not reported at every start)
end

-- What the INVENTORY's own entry for a kind looks like (state, stack, slot, object). give.snap only ever looked at the object the
-- script made; addItem works on a copy, and the copy is what the game keeps drawing, counting and saving. A state other than 2
-- (INVENTRY_IN), a slot of -1 or a stack of 0 would explain a crash a moment later. Read-only.
function give.copy_text(id)
    local okl, list = pcall(inventory_items)
    if not okl or list == nil then return "the inventory can't be read" end
    local out = {}
    for _, e in ipairs(list) do
        if e.id == id and e.item then
            local parts = {}
            local function try(k, f)
                local ok, v = pcall(f)
                parts[#parts + 1] = k .. "=" .. (not ok and "error" or (v == nil and "nil" or tostring(as_text(v) or v)))
            end
            try("state", function()
                local v = e.item:call("getItemState")
                local nm = type(v) == "number" and give.enum_names("app.Item.ITEMSTATE")[v] or nil
                return nm and (tostring(v) .. " " .. nm) or v
            end)
            try("stack", function() return e.item:call("getStackNum") end)
            pcall(function()
                local sd = e.item:call("getItemSaveData")
                if sd ~= nil and type(sd) ~= "number" and type(sd) ~= "string" then
                    try("slot", function() return sd:get_field("SlotNo") end)
                end
            end)
            try("object", function() return give.info_text(give.go_info(game_object_of(e.item))) end)
            out[#out + 1] = table.concat(parts, ", ")
        end
    end
    if #out == 0 then return "no entry for " .. tostring(id) end
    return table.concat(out, " | "):sub(1, 300)
end

-- After an add: a line in the trail at 0.05 s, 0.15 s, ... so a crash is dated to the moment it happened. Run from give_update.
give.watch = nil
function give.watch_start(label, id)
    give.watch = { label = label, id = id, t0 = os.clock(), i = 1, frames = 0, marks = { 0.05, 0.15, 0.3, 0.6, 1, 2, 4 } }
    give.crumb(label .. ": done, watching whether the game survives the next seconds")
end
function give.watch_update(now)
    local w = give.watch
    if not w then return end
    w.frames = w.frames + 1
    local m = w.marks[w.i]
    if m and now - w.t0 >= m then
        w.i = w.i + 1
        local held, readable
        if w.id then held, readable = give.total_of(w.id) end
        give.trail(string.format("%s: alive %.2f s later (frame %d)%s%s", w.label, now - w.t0, w.frames,
            readable and string.format(", you hold %d %s", held, w.id) or "",
            (readable and held > 0 and (w.i == 3 or w.i == 5 or w.i == 8)) and (", copy: " .. give.copy_text(w.id)) or "")) -- at 0.15 s, 0.6 s and the end
    end
    if not w.marks[w.i] then
        give.watch = nil
        give.clean()
    end
end

-- What a GameObject looks like to the engine: its name, parent, position, and whether it is drawn / updated. Read-only.
function give.go_info(go)
    local info = {}
    pcall(function() info.name = as_text(go:call("get_Name")) end)
    pcall(function()
        local xf = go:call("get_Transform")
        local p = xf:call("get_Position")
        info.x, info.y, info.z = p.x, p.y, p.z
        local par = xf:call("get_Parent")
        if par ~= nil then
            local pgo = par:call("get_GameObject")
            info.parent = pgo and as_text(pgo:call("get_Name")) or "?"
        end
    end)
    pcall(function() info.draw = go:call("get_DrawSelf") end)
    pcall(function() info.update = go:call("get_UpdateSelf") end)
    return info
end

function give.info_text(i)
    return string.format("%s parent=%s drawn=%s updating=%s at %s", tostring(i.name), tostring(i.parent), tostring(i.draw), tostring(i.update),
        i.x and string.format("(%.2f, %.2f, %.2f)", i.x, i.y, i.z) or "?")
end

-- Journal lines about the drop object, 12 at most: the 0.9 file had a drop that was "created" but never seen.
function give.drop_note(msg)
    give.drop_lines = (give.drop_lines or 0) + 1
    if give.drop_lines <= 12 then say("drop: " .. msg) end
end

-- Where the player stands and which way they face (the camera's pose is not the player's, so the player object is used).
function give.player_pose(player)
    local px, py, pz, fx, fz
    pcall(function()
        local xf = player:call("get_Transform")
        local p = xf:call("get_Position")
        px, py, pz = p.x, p.y, p.z
        local q = xf:call("get_Rotation")
        if q then
            fx = 2 * (q.x * q.z + q.w * q.y)
            fz = 1 - 2 * (q.x * q.x + q.y * q.y)
        end
    end)
    return px, py, pz, fx, fz
end

-- Puts an item on the ground (at x, y, z, or just in front of the player's feet if they are nil).
-- Returns true plus where it ended up, or nil plus the reason. Only an object that came back, and is drawn, counts as done.
-- (10.12) "key item crashed the game when dropped in the main house". createDropItemInstance only makes a proper pickup for the consumables (ammo, healing, materials);
-- for a key item or a weapon it makes a bare item object (the other mod found the same and refuses them), and the game fell over on it. So only what is KNOWN to be a
-- consumable is put on the ground: by the category the game gave when such an item was last picked up here, else by its name. A key item, a weapon, a file, a map, or
-- anything unknown is left to the game's own discard (nothing is made, nothing is sent).
give.DROP_CATEGORIES = { [0] = true, [2] = true, [3] = true, [7] = true } -- other, ammo, heal, material
-- Names that are never made for the ground whatever the category says (the other player's older build sends everything; a key item's category is learned only
-- when the item has been seen here). A name that is on neither list is left to its category, and with no category it goes through.
give.KEEP_WORDS = { "key", "fuse", "cutter", "crank", "valve", "handle", "bolt", "card", "dog", "head", "file", "map", "gem", "shard", "mail", "license", "lisence", "note", "memo",
    "photo", "tape", "disc", "statue" } -- (a weapon is refused by its category once that is known: the names of guns are too many to list)
function give.droppable(id)
    local c = items and items.cat_cache and items.cat_cache[id]
    if c ~= nil then
        if give.DROP_CATEGORIES[c] then return true end
        return false, "a " .. tostring(items.CATEGORY[c] or ("category " .. tostring(c)))
    end
    local low = tostring(id):lower()
    if low:find("bullet", 1, true) or low:find("shell", 1, true) or low:find("powder", 1, true) or low:find("herb", 1, true) then return true end
    for _, w in ipairs(give.KEEP_WORDS) do
        if low:find(w, 1, true) then return false, "a key item by its name" end
    end
    return true
end

local function spawn_world_item(id, n, x, y, z)
    local okd, whyd = give.droppable(id)
    if not okd then
        give.drops_refused = give.drops_refused + 1
        give.last_refused_drop = string.format("%s x%d: %s", tostring(id), tonumber(n) or 0, tostring(whyd))
        give.drop_note(string.format("%s x%d is not put on the ground: %s (the game's own discard stands)", tostring(id), tonumber(n) or 0, tostring(whyd)))
        return nil, "not put on the ground: " .. tostring(whyd)
    end
    if not give.ground then -- the ground route is off: nothing is created, so nothing can be put on the ground
        give.refused = give.refused + 1
        return nil, "the ground route is switched off"
    end
    give.crumb("looking for the ItemManager (for the ground)")
    local im = item_manager()
    give.clean()
    if not im then give.trail(string.format("drop: no ItemManager found for %s x%d", id, n)) return nil, "ItemManager not found" end
    local player = player_object()
    if not player then return nil, "player object (Pl0000) not found" end
    give.trail(string.format("drop: making %s x%d for the ground (createDropItemInstance)", id, n))
    give.crumb(string.format("making %s x%d for the ground (createDropItemInstance)", id, n))
    local obj, why = create_item_object("createDropItemInstance", id, n)
    give.clean()
    if obj == nil then
        give.trail("drop: createDropItemInstance gave nothing: " .. tostring(why))
        item_probe(id, "the item could not be put on the ground")
        give.ground_failed = give.ground_failed + 1
        return nil, why
    end
    local go = game_object_of(obj)
    if not go then give.ground_failed = give.ground_failed + 1 return nil, "the dropped object has no GameObject" end
    give.crumb(string.format("placing the dropped %s", id))
    local before = give.go_info(go)
    local ppx, ppy, ppz, pfx, pfz = give.player_pose(player)
    local tx, ty, tz = x, y, z
    if tx == nil and ppx then
        -- the game puts a dropped item where its owner is (a drawer, in its own use); the player is the owner here, so the
        -- item may sit inside the player, or be a child of the player and follow them. Put it down in front of the feet.
        local len = math.sqrt((pfx or 0) ^ 2 + (pfz or 0) ^ 2)
        local ox, oz = 0, 0
        if len > 0.01 then ox, oz = pfx / len * 0.8, pfz / len * 0.8 end
        tx, ty, tz = ppx + ox, ppy + 0.1, ppz + oz
    end
    pcall(function()
        local xf = go:call("get_Transform")
        if before.parent and is_player_name(before.parent) then pcall(function() xf:call("set_Parent", nil) end) end -- (let go of the player)
        if tx then xf:call("set_Position", Vector3f.new(tx, ty, tz)) end
    end)
    pcall(function() go:call("set_DrawSelf", true) end)
    pcall(function() go:call("set_UpdateSelf", true) end)
    local after = give.go_info(go)
    give.clean()
    give.drop_note(string.format("%s x%d: object was %s; now %s; player at %s", id, n, give.info_text(before), give.info_text(after),
        ppx and string.format("(%.2f, %.2f, %.2f)", ppx, ppy, ppz) or "?"))
    give.last_drop = { id = id, before = before, after = after }
    give.trail(string.format("drop: %s x%d placed: was %s; now %s", id, n, give.info_text(before), give.info_text(after)))
    give.watch_start("drop " .. id, nil)
    pcall(give.ground_record, id, n, obj, go, before, after, after.x or tx, after.y or ty, after.z or tz)
    if after.draw == false then give.ground_failed = give.ground_failed + 1 return nil, "the object that was made is hidden (not drawn), so nobody would see it" end
    return true, after.x or tx, after.y or ty, after.z or tz
end

-- (9.32) What a ground drop looked like when it was made, and 2 s later (the last 8 are kept): what it is made of, its item state and stack, whether it
-- is drawn and updating, where it is, whether it is still there, and whether the game's own pickup was seen working on it. This is the data that says
-- why a drop does (not) show up for the other player. Nothing here keeps a pointer: the object is found again by name and place.
function give.ground_record(id, n, obj, go, before, after, x, y, z)
    local function r1(v) return v and math.floor(v * 10 + 0.5) / 10 or nil end
    local rec = { id = id, n = n, at = os.clock(), by = "the ground route", name = before.name or after.name,
        placed = x and { r1(x), r1(y), r1(z) } or nil, before = give.info_text(before), after = give.info_text(after), drawn = after.draw, updating = after.update }
    pcall(function() rec.components = component_names(go) end)
    local comp = obj
    pcall(function() -- the app.Item: the object that came back, or a component of its GameObject
        local tn = obj:get_type_definition():get_full_name()
        if tn ~= "app.Item" then comp = go:call("getComponent(System.Type)", sdk.typeof("app.Item")) end
    end)
    if comp then
        pcall(function()
            local st = comp:call("getItemState")
            local nm = give.enum_names("app.Item.ITEMSTATE")[st]
            rec.item_state = nm and (nm .. "=" .. tostring(st)) or tostring(st)
        end)
        pcall(function() rec.item_stack = comp:call("getStackNum") end)
    end
    give.ground_drops[#give.ground_drops + 1] = rec
    if #give.ground_drops > give.GROUND_KEEP then table.remove(give.ground_drops, 1) end
    give.ground_made = give.ground_made + 1
    give.drop_note(string.format("%s x%d is made of: %s; item state %s, stack %s", id, n, rec.components and table.concat(rec.components, ", ") or "?",
        tostring(rec.item_state), tostring(rec.item_stack)))
end

-- Called by the pickup hook for every pickup: true (and the id) when the object is one of those drops. The game's own pickup worked on it.
function give.ground_check(name, p)
    if not (name and p) then return nil end
    for i = #give.ground_drops, 1, -1 do
        local d = give.ground_drops[i]
        if not d.picked and d.name == name and d.placed and d.placed[1] then
            local dx, dy, dz = p.x - d.placed[1], p.y - d.placed[2], p.z - d.placed[3]
            if dx * dx + dy * dy + dz * dz < 4 then
                d.picked = true
                give.ground_picked = give.ground_picked + 1
                say(string.format("give: you picked up the %s the script put on the ground: the game's own pickup works on it", d.id))
                return d.id
            end
        end
    end
    return nil
end
items.drop_check = give.ground_check

-- Every frame: 2 s after a drop, look for it again (by name and place, never by a kept pointer).
function give.ground_update(now)
    for _, d in ipairs(give.ground_drops) do
        if not d.later and now - d.at >= give.GROUND_LOOK_AFTER then
            if d.picked then
                d.later = "picked up (the pickup hook saw it)"
                d.still_there = false
            else
                local go, dist = items.find_near(d.name, d.placed and d.placed[1], d.placed and d.placed[2], d.placed and d.placed[3], 1.5)
                if go then
                    d.later = "still there: " .. give.info_text(give.go_info(go))
                    d.still_there = true
                else
                    d.later = "not found within 1.5 m of where it was put (" .. tostring(dist) .. "): picked up, destroyed or moved away"
                    d.still_there = false
                    give.ground_gone = give.ground_gone + 1
                end
            end
            give.drop_note(string.format("%s %.0f s after it was made: %s", d.id, give.GROUND_LOOK_AFTER, d.later))
        end
    end
end

function give.ground_report()
    local drops = {}
    for i, d in ipairs(give.ground_drops) do
        local c = {}
        for k, v in pairs(d) do c[k] = v end
        c.seconds_ago = math.floor(os.clock() - d.at)
        c.at = nil
        drops[i] = c
    end
    return { on = give.ground, made = give.ground_made, failed = give.ground_failed, refused_not_consumable = give.drops_refused, last_refused = give.last_refused_drop, picked_up_by_me = give.ground_picked,
        not_found_after_2s = give.ground_gone, look_again_after_s = give.GROUND_LOOK_AFTER, drops = drops }
end

-- The last way in when the game won't create an item: if an item of that name is already in the inventory, its stack grows.
-- Only when the whole amount fits. Returns true, or false plus why.
local function bump_existing_stack(id, n)
    local list = inventory_items()
    for _, e in ipairs(list or {}) do
        if e.id == id and e.item then
            local okc, cur = pcall(function() return e.item:call("getStackNum") end)
            local okm, max = pcall(function() return e.item:call("getMaxStackNum") end)
            if okc and okm and type(cur) == "number" and type(max) == "number" then
                if cur + n <= max then
                    local oks = pcall(function() e.item:call("setStackNum", cur + n) end)
                    local okr, now = pcall(function() return e.item:call("getStackNum") end)
                    if oks and okr and now == cur + n then
                        give.bumped = (give.bumped or 0) + 1
                        return true
                    end
                    return false, "the stack of " .. id .. " would not change"
                end
                return false, "your stack of " .. id .. " is full (" .. cur .. "/" .. max .. ")"
            end
        end
    end
    return false, "no " .. id .. " in the inventory to add it to"
end

-- The name of an enum value ("app.Inventory.AddItemResult" and the like), read once from the type: { [value] = name }.
function give.enum_names(typename)
    give.enums = give.enums or {}
    if give.enums[typename] then return give.enums[typename] end
    local map = {}
    pcall(function()
        local td = sdk.find_type_definition(typename)
        for _, f in ipairs(td and td:get_fields() or {}) do
            if f:is_static() then
                local v = f:get_data(nil)
                if type(v) == "number" then map[v] = f:get_name() end
            end
        end
    end)
    give.enums[typename] = map
    return map
end

function give.result_text(v)
    if v == nil then return "nothing" end
    if type(v) == "number" then
        local nm = give.enum_names("app.Inventory.AddItemResult")[v]
        return nm and (nm .. "=" .. v) or tostring(v)
    end
    return as_text(v) or tostring(v)
end

-- How many of `id` the inventory holds now, and whether the list could be read at all.
function give.total_of(id)
    local list = inventory_items()
    if list == nil then return 0, false end
    local total = 0
    for _, e in ipairs(list) do
        if e.id == id then total = total + (e.count or 1) end
    end
    return total, true
end

-- true when taking n of `id` would remove an inventory entry altogether (n is at least the smallest stack of that kind; the game
-- takes from the smallest stack first, as far as the crafting trace shows), false when every stack would only get smaller, nil when the
-- inventory can't be read or has none of that kind. 9.26: nil comes with a second value, "unreadable" (the list itself can't be read,
-- third value: why) or "absent" (it was read and has no such item, third value: the ids it does have): the 0.8 test refused six gives in
-- the main house with the same "can't read how many you hold", and the file could not say which of the two it was.
function give.would_empty_entry(id, n)
    local list, lnote = inventory_items()
    if list == nil then
        give.last_unread = { id = id, why = "the list can't be read", detail = tostring(lnote), at = os.clock() }
        return nil, "unreadable", lnote
    end
    local smallest
    local have = {}
    for _, e in ipairs(list) do
        if #have < 24 then have[#have + 1] = tostring(e.id) .. " x" .. tostring(e.count or 1) end
        if e.id == id then
            local c = e.count or 1
            if not smallest or c < smallest then smallest = c end
        end
    end
    if not smallest then
        local text = #have > 0 and table.concat(have, ", ") or "(nothing)"
        give.last_unread = { id = id, why = "read, but it has no " .. id, detail = text, entries = #list, note = lnote and tostring(lnote) or nil, at = os.clock() }
        return nil, "absent", text
    end
    return n >= smallest, smallest
end

-- The game's own reduceItem(id, n, TRUE) that removes an entry (door keys, a used Remedy) is followed by
-- Inventory.reOpenRequestInventoryMenu(); crafting, which passes FALSE, has none. This hook is only there to see whether our call asks for it.
-- It writes the trail file only (no debug flush: this runs inside the game's own call).
function give.on_reopen_request(args)
    give.reopen_seen = give.reopen_seen + 1
    local now = os.clock()
    if now - give.last_call_at < 5 then
        give.reopen_after_ours = give.reopen_after_ours + 1
        local text = string.format("the game asked for the inventory menu to be re-opened %.2f s after my reduceItem call%s", now - give.last_call_at, give.giving and " (inside the call)" or "")
        give.trail_list[#give.trail_list + 1] = { t = math.floor(now * 1000) / 1000, w = text }
        if #give.trail_list > 120 then table.remove(give.trail_list, 1) end
        pcall(json.dump_file, FILES.path("trail"), { session = tracer.session, entries = give.trail_list })
    end
end

-- How a gift becomes part of my inventory (9.33: ONE way). An item of that name is already in the inventory, so its stack grows (proven in the real
-- game, 9.12 ammo). Anything else is not made for the inventory: createItemInstance + addItem crashed the real game every time it produced an
-- object, and that code was taken out in 9.33. The caller puts such a gift on the ground at my feet instead (the ground route, spawn_world_item:
-- createDropItemInstance, the call the game uses for what lies on the ground), and I pick it up with the game's own pickup.
-- Returns true plus how, or false plus why. A stack only counts as grown when the inventory really holds more of it than before (checked in
-- bump_existing_stack: the stack is read back).
local function add_to_inventory(id, n)
    local player, inv = player_object(), inventory_object()
    if not player then return false, "player object not found" end
    if not inv then return false, "inventory object not found" end
    local okb, whyb = bump_existing_stack(id, n)
    if okb then return true, "added to the stack you already have" end
    -- an inventory that can't be read is not a place to put anything (9.30: the Logs 1 file: the object was dead)
    do
        local list0, note0 = inventory_items()
        if list0 == nil then
            local why0 = "your inventory can't be read (" .. tostring(note0) .. ")"
            give.last_unread = { id = id, why = "the list can't be read", detail = tostring(note0), at = os.clock() }
            give.add_note(string.format("%s x%d refused: %s", id, n, why0))
            give.trail(string.format("gift: %s x%d: %s, so %s", id, n, why0, give.ground and "it goes on the ground" or "it is refused"))
            give.refused_unread = (give.refused_unread or 0) + 1
            return false, why0
        end
    end
    if give.ground then
        give.add_note(string.format("%s x%d: no stack to grow (%s); it goes on the ground", id, n, tostring(whyb)))
        return false, tostring(whyb) .. "; ground route"
    end
    give.refused = give.refused + 1
    give.add_note(string.format("%s x%d refused: %s; the ground route is switched off", id, n, tostring(whyb)))
    return false, tostring(whyb) .. "; the ground route is switched off"
end

-- Hands n of item `id` to the other player.
local function give_item(id, n)
    local now = os.clock()
    if not peer_present(now) then
        give.failed = give.failed + 1
        give_note("nobody to give to (the other player is not connected)")
        return false
    end
    if not id or n < 1 then return false end
    -- (10.5) Ethan's friend shares your weapons and ammo: nothing to hand over, you keep them
    if CFG.friend.present() then
        local refused, why = CFG.friend.refuse_gift(id)
        if refused then
            give_note(why)
            return false
        end
    end
    -- (9.32) the 3 m rule
    do
        local dist = give.distance()
        local who = state.remote_name or CFG.DEFAULT_NAME
        if dist == nil then
            give.refused_far = give.refused_far + 1
            give.last_far = { id = id, distance = nil, at = now }
            give_note(string.format("I can't tell how far away %s is, so nothing was given (an item can only be given within %.0f m of each other)", who, give.RANGE))
            return false
        elseif dist > give.RANGE then
            give.refused_far = give.refused_far + 1
            give.last_far = { id = id, distance = math.floor(dist * 10 + 0.5) / 10, at = now }
            give_note(string.format("%s is %.1f m away: an item can only be given within %.0f m of each other. Walk up to them and try again", who, dist, give.RANGE))
            return false
        end
    end
    local inv = inventory_object()
    if not inv then
        give.failed = give.failed + 1
        local tried = table.concat(mgr.inv_log.tried or {}, "; "):sub(1, 200)
        give.last_unread = { id = id, why = "the list can't be read", detail = "no inventory object: " .. tried, at = os.clock() }
        give_note(string.format("%s: I can't read how many you hold, because I can't reach your inventory object (%s): nothing was given", id,
            tried ~= "" and tried or "nothing was tried yet"))
        return false
    end
    -- a give that would take a whole entry out of the inventory crashed the game in every test: refused unless the box in the items panel is ticked
    -- (9.35: with the box on by default, an inventory that can't be read, or one without that item, is STILL refused: with no count there is no telling
    -- which value of the third argument the removal needs, and the wrong one is the one that crashed)
    local empties, smallest, extra = give.would_empty_entry(id, n)
    if empties == nil or (empties and not give.last_ok) then
        give.refused_last = give.refused_last + 1
        if empties == nil and smallest == "absent" then
            give_note(string.format("%s: your inventory (which I can read) has no %s: it holds %s. If you are pointing at it in the item box or in a menu that is not your inventory, nothing is given from there", id, id, tostring(extra)))
        elseif empties == nil then
            give_note(string.format("%s: I can't read how many you hold, so I can't tell whether this would take your last one out of the inventory; that crashed the game in every test, so nothing was given", id))
        else
            give_note(string.format("%s x%d is your last %s (or a whole stack of it): taking a whole entry out of your inventory crashed the game in every test, so it stays with you. Give fewer than %d, or tick the 'last one' box under Items: give and drop to try the crafting way", id, n, id, smallest))
        end
        return false
    end
    -- Nothing leaves your inventory yet: the other game answers first (give_ack) and the item is taken out when it says
    -- "ok". The versions before this took it at once, and an item the other game could not create was simply gone.
    give.trail(string.format("give: offering %s x%d%s", id, n, empties and " (the whole entry: the 'last one' box is ticked)" or ""))
    net_send(GIVE_MSG, id .. "|" .. n)
    give.out[#give.out + 1] = { kind = "g", id = id, n = n, at = now }
    give.focus = nil -- the highlighted item just changed
    give_note(string.format("you offered %s x%d to %s: it leaves your inventory when they confirm they have it", id, n,
        state.remote_name or CFG.DEFAULT_NAME))
    return true
end

local function give_focused(all)
    local f = give.focus
    if not f then
        give_note("highlight an item in the inventory first (or use the list in the panel)")
        return
    end
    if not f.id then
        give_note("I can see the highlighted item but can't read its name: use the list in the panel, and press button 7")
        return
    end
    local n = all and f.count or 1
    give_item(f.id, math.min(n, f.count))
end

-- The receiver tells the sender what happened ("g|id|n|ok|how" for a gift, "d|..." for a drop), so a gift that could
-- not be delivered is handed back instead of being lost, and the reason is on the sender's screen and in its journal.
local function give_ack(kind, id, n, ok, how)
    local text = tostring(how or ""):gsub("[|\r\n]", " ")
    net_send(GIVE_ACK_MSG, string.format("%s|%s|%d|%s|%s", kind, id, n, ok and "ok" or "fail", text:sub(1, 90)))
end

-- One try at putting a gift in my inventory, else on the ground at my feet. Returns done, ok, how.
-- A missing player object is only a "not yet": it is tried again for a few seconds (final = false).
local function give_try(id, n, final)
    local who = state.remote_name or CFG.DEFAULT_NAME
    items.suppress_until = os.clock() + 2 -- creating the item must not look like a world pickup
    local ok, why, later = add_to_inventory(id, n)
    if later then return false end
    if ok then
        local how = (type(why) == "string" and why ~= "") and why or "in the inventory"
        give_note(string.format("%s gave you %s x%d (%s)", who, id, n, how))
        return true, true, how
    end
    if not give.ground then
        -- the ground route is off: refused, so it stays with the sender (unless the game only wasn't ready: that is tried again)
        if not final and tostring(why):find("not found", 1, true) then return false end
        give.failed = give.failed + 1
        give_note(string.format("%s offered you %s x%d but I can't take it: %s", who, id, n, tostring(why)))
        return true, false, tostring(why)
    end
    local okd, px = spawn_world_item(id, n)
    if okd then
        give_note(string.format("%s gave you %s x%d: %s, so it is on the ground at your feet", who, id, n, tostring(why)))
        return true, true, "on the ground (" .. tostring(why) .. ")"
    end
    if not final and (tostring(why):find("not found", 1, true) or tostring(px):find("not found", 1, true)) then return false end
    give.failed = give.failed + 1
    give_note(string.format("%s gave you %s x%d but I could not add it (%s) or drop it (%s)", who, id, n,
        tostring(why), tostring(px)))
    return true, false, tostring(why) .. "; " .. tostring(px)
end

net_on(GIVE_MSG, function(payload)
    local id, n = payload:match("^([%w_]+)|(%d+)$")
    n = tonumber(n)
    if not id or not n or n < 1 or n > 999 then return end
    give.received = give.received + 1
    -- (9.32) the 3 m rule, checked here too (a modified or older copy of the script on the other side may not do it): a gift from further
    -- away is not taken, and the sender is told so it keeps the item
    if not give.skip_range then
        local dist = give.distance()
        if dist ~= nil and dist > give.RANGE_RECV then
            local who = state.remote_name or CFG.DEFAULT_NAME
            give.refused_far_recv = give.refused_far_recv + 1
            give.last_far = { id = id, distance = math.floor(dist * 10 + 0.5) / 10, at = os.clock(), received = true }
            give_note(string.format("%s offered you %s x%d from %.1f m away: too far (an item can only be given within %.0f m): it stays with them", who, id, n, dist, give.RANGE))
            give_ack("g", id, n, false, string.format("too far apart (%.1f m; the limit is %.0f m)", dist, give.RANGE))
            return
        end
    end
    local done, ok, how = give_try(id, n, false)
    if done then
        give_ack("g", id, n, ok, how)
    else
        give.inbox[#give.inbox + 1] = { id = id, n = n, tries = 1, next_at = os.clock() + 1 }
    end
end)

net_on(DROP_MSG, function(payload)
    local id, n, x, y, z = payload:match("^([%w_]+)|(%d+)|(-?[%d%.]+)|(-?[%d%.]+)|(-?[%d%.]+)$")
    n, x, y, z = tonumber(n), tonumber(x), tonumber(y), tonumber(z)
    if not (id and n and x and y and z) or n < 1 or n > 999 then return end
    give.received = give.received + 1
    local who = state.remote_name or CFG.DEFAULT_NAME
    local ok, px, py, pz = spawn_world_item(id, n, x, y, z)
    if ok then
        give_note(string.format("%s dropped %s x%d: it is on the ground here too", who, id, n))
        give_ack("d", id, n, true, "on the ground")
    else
        give.failed = give.failed + 1
        give_note(string.format("%s dropped %s x%d but I could not show it (%s)", who, id, n, tostring(px)))
        give_ack("d", id, n, false, tostring(px))
    end
end)

net_on(GIVE_ACK_MSG, function(payload)
    local kind, id, n, res, how = payload:match("^(%a)|([%w_]+)|(%d+)|(%a+)|(.*)$")
    n = tonumber(n)
    if not kind or not id or not n then return end
    local who = state.remote_name or CFG.DEFAULT_NAME
    for i, o in ipairs(give.out) do
        if o.kind == kind and o.id == id and o.n == n then
            table.remove(give.out, i)
            if res == "ok" and kind == "g" then
                -- they have it: now it leaves my inventory (the health module must not take this reduceItem for "you used a healing item")
                local inv = inventory_object()
                local okr, resr = false, nil
                local whole = give.would_empty_entry(id, n) -- read again now: the inventory may have changed since the offer
                local blocked = inv and (whole == nil or (whole and not give.last_ok))
                if blocked then
                    give.refused_last = give.refused_last + 1
                    if whole == nil then
                        give.trail(string.format("give: %s has %s x%d, but my inventory can't be read (or no longer holds it) now, so I can't tell whether it is a whole entry: not done", who, id, n))
                    else
                        give.trail(string.format("give: %s has %s x%d, but taking it out would remove a whole entry from my inventory: not done (see the 'last one' box)", who, id, n))
                    end
                elseif inv then
                    -- written BEFORE the call (the file is flushed at once): a crash inside reduceItem leaves this as the last line
                    give.trail(string.format("give: %s has %s x%d; taking it out of my inventory with reduceItem%s", who, id, n,
                        whole and " (the whole entry: third argument false, the way crafting calls it)" or ""))
                    give.crumb(string.format("giving %s x%d: Inventory.reduceItem", id, n))
                    give.giving, give.last_call_at = true, os.clock()
                    if whole then give.whole_entry_removals = give.whole_entry_removals + 1 end
                    okr, resr = call_str(inv, "reduceItem", id, n, not whole)
                    give.giving = false
                    give.clean()
                    give.trail(string.format("give: reduceItem %s (it answered %s)", okr and "went through" or "failed", tostring(resr)))
                end
                if blocked then
                    give.failed = give.failed + 1
                    if whole == nil then
                        give_note(string.format("%s has %s x%d, but I can't read your inventory now to tell whether it is your last one, so it was not taken out: you both have it now", who, id, n))
                    else
                        give_note(string.format("%s has %s x%d, but it is your last one and taking it out crashed the game in the tests: you both have it now", who, id, n))
                    end
                elseif okr and resr ~= false then
                    give.sent = give.sent + 1
                    give_note(string.format("%s has %s x%d (%s): it left your inventory", who, id, n, how))
                    if CFG.friend.present() then pcall(CFG.friend.take, id, n) end -- (10.5) Ethan's friend carries it now
                else
                    give.failed = give.failed + 1
                    give_note(string.format("%s has %s x%d (%s) but the game would not take it out of your inventory: you both have it now", who, id, n, how))
                end
            elseif res == "ok" then
                give_note(string.format("%s has %s x%d (%s)", who, id, n, how))
            elseif kind == "g" then
                -- their game could not take it: it never left my inventory
                give.failed = give.failed + 1
                give_note(string.format("%s could not take %s x%d (%s): you keep it", who, id, n, how))
            else
                give.failed = give.failed + 1
                give_note(string.format("%s could not show the %s x%d you dropped (%s)", who, id, n, how))
            end
            return
        end
    end
end)

-- Every frame: the Give hotkey, and the delayed spawn after a discard.
local function give_update(now)
    pcall(give.watch_update, now) -- the trail's "still alive" lines after an item step
    pcall(give.ground_update, now) -- (9.32) the second look at each ground drop
    -- gifts waiting for the player object; and my own gifts and drops nobody has answered
    for i = #give.inbox, 1, -1 do
        local g = give.inbox[i]
        if now >= g.next_at and not g.queued then
            g.tries = g.tries + 1
            local done, ok, how = give_try(g.id, g.n, g.tries >= 5)
            if done then
                for j = #give.inbox, 1, -1 do
                    if give.inbox[j] == g then table.remove(give.inbox, j) end
                end
                give_ack("g", g.id, g.n, ok, how)
            else
                g.next_at = os.clock() + 1
            end
        end
    end
    for i = #give.out, 1, -1 do
        local o = give.out[i]
        if now - o.at > 10 then
            table.remove(give.out, i)
            give_note(string.format("no answer from %s about %s x%d: it stays in your inventory (if it did arrive they have a copy; their script may be older than build 9.12)",
                state.remote_name or CFG.DEFAULT_NAME, o.id, o.n))
        end
    end
    if give.want_dump and now - give.auto_dump_at >= 1 then
        local why = give.want_dump
        give.want_dump, give.auto_dump_at = nil, now
        say("give: writing item diagnostics to the debug file by itself (" .. why .. ")")
        dump_focused_item()
    end
    local okk, down = pcall(function() return reframework:is_key_down(give.hotkey) end)
    down = okk and down == true
    if down and not give.key_was_down then give_focused(false) end
    give.key_was_down = down

    local d = give.pending_drop
    if d and now - d.at >= 0.2 then
        give.pending_drop = nil
        local ok, px, py, pz = spawn_world_item(d.id, d.n)
        if ok then
            give.dropped = give.dropped + 1
            if px == nil and state.local_pos then
                local lp = state.local_pos
                px, py, pz = lp.x, lp.y - CFG.EYE_HEIGHT, lp.z
            end
            if px ~= nil and peer_present(os.clock()) then
                net_send(DROP_MSG, string.format("%s|%d|%.2f|%.2f|%.2f", d.id, d.n, px, py, pz))
                give.out[#give.out + 1] = { kind = "d", id = d.id, n = d.n, at = os.clock() }
            end
            give.last = string.format("you dropped %s x%d on the ground%s", d.id, d.n,
                peer_present(os.clock()) and " (the other player sees it too)" or "")
            say("give: " .. give.last)
        else
            give.failed = give.failed + 1
            give_note(string.format("could not drop %s x%d on the ground: %s", d.id, d.n, tostring(px)))
        end
    end
end

local function draw_give_hint(now)
    if not give.hint or not give.focus or not give.focus.id or not peer_present(now) then return end
    if now - give.focus.at > 6 then return end
    pcall(draw.text, string.format("[F7] give %s to %s", give.focus.id, state.remote_name or CFG.DEFAULT_NAME),
        24, 110, 0xFF00D7FF)
end

-- 9.36: "when the inventory is open, say that discarding an item drops it on the ground for the other player". Shown only while an inventory-like menu is
-- open (CFG.menu.in_inventory), another player (or Ethan's friend) is there and the ground route is on, i.e. when a discard really is put on the ground for them.
-- It follows the same box as the [F7] hint ("Show the [F7] give hint while the inventory is open").
function give.inventory_note(now)
    if not give.hint or not give.ground or not give.drop_on_discard then return end
    if not (CFG.menu and CFG.menu.in_inventory()) or not peer_present(now) then return end
    local sz = { x = 1920, y = 1080 }
    pcall(function() local d = imgui.get_display_size() if d and d.x and d.x > 100 then sz = d end end)
    local x, y = math.floor(sz.x * 0.5 - 330), 24 -- (10.3: at the top of the screen, in the middle; it was at the bottom)
    local gold = 0xFF00D7FF
    pcall(draw.text, "Discarding an item here DROPS it on the ground for the other player too (they can pick it up).", x, y, gold)
    pcall(draw.text, "To hand an item over instead, click the item to select it, then press [F7].", x, y + 22, gold)
end

----------------------------------------------------------------------------------------------
-- Enemy sync. The TCP host's game is the authority.
--
-- The scene scan showed the enemies are root objects named Em#### (Em2000 ... Em6100), each with its own
-- Think/Status/Order components. Every 0.1 s the HOST reads those objects' position, rotation, health (if a
-- health field can be found) and animation ids, and sends them as one text blob through re7mp.exe
-- (TCP only, latest wins). The JOINER draws them as red ghosts and (mode 3, the default since 10.22) the joiner's own
-- enemies with the same names are moved onto the host's positions each frame.
-- Not built yet: damage dealt by the joiner reaching the host, enemy deaths, spawning, animation mirroring.
-- The "Enemy details" button in the debug section writes what is needed to build those.
-- Blob format (one entry per enemy, separated by ';'):  name,x,y,z,qx,qy,qz,qw,hp,flags,bank,motion,frame
----------------------------------------------------------------------------------------------
local ENEMY_MODES = {
    "Off",
    "Show the host's enemies as red ghosts",
    "Ghosts, and move my own enemies onto the host's",
}
local enemy = {
    mode = 3,           -- (10.22: the third mode is the default: ghosts, and my own enemies are moved onto the host's. It was 2, ghosts only, until 0.10)
    drive_ai = false,   -- mode 3 only: also switch off my enemies' own AI components
    seq = 0, last_scan = 0, last_send = 0, last_read = 0,
    roots = {},         -- host: { name, go, xf }
    sent = 0, received = 0,
    last = "No enemy data yet.",
    remote = {},        -- joiner: name -> latest snapshot and the smoothed position being drawn
    remote_seq = nil,
    remote_at = 0,
    test_ghosts = false, -- draw the received enemies even if I am the host (loopback test)
    show_parked = false, -- draw parked / placeholder Em#### objects too (grey), to find out what they are
    hide_walls = true,  -- 9.26: do not draw a red box that has a wall between it and the camera (the same test as for the other player)
    wall = {}, wall_at = -10, wall_checks = 0, wall_hidden_checks = 0, -- name -> { hide, hs, cs } for the 6 nearest boxes
    driven = {},        -- joiner: name -> { go, xf, disabled = { component, ... } }
    local_roots = {}, local_scan = 0,
    hp_logged = {},
    -- what is carried from one scan's record of an enemy to the next (found by the health search; see find_enemy_roots)
    FAST_EVERY = 1 / 15, FAST_MAX = 8, -- (10.12) the host's snapshot interval with few / many enemies
    KEEP = { "dmg_comp", "status", "no_is_dead", "no_dc_dead", "hp_checked", "hp_tries", "hp_retry_at", "hp_field", "hp_comp", "hp_call", "hp_where", "hp_fail",
        "max_val", "max_at" },
}

local function enemy_note(text)
    enemy.last = text
    say("enemy sync: " .. text)
end

-- (10.12) THE JOINER'S TIMELINE ("the enemy sync could be better"). The 10.11 joiner chased the newest snapshot (a = 1 - exp(-12 dt)): at 10 snapshots a second
-- an enemy moved in steps and slowed down before every one. Now every snapshot is a point on a timeline and the enemies are drawn a short, adaptive time BEHIND
-- the host (the other mod's "playback delay": the gap between snapshots plus a little for the network), always between two real positions, so the motion is
-- the host's own: constant speed, no steps, the right facing. The host puts its clock in the snapshot ("T<seconds>" as its first entry; an older joiner skips it,
-- an older host simply sends none and the arrival time is used). The clock offset is the smallest "arrived - sent" seen (the best delivery), drifting up slowly.
enemy.tl = { off = nil, last_ht = nil, iv = 0.1, delay = 0.24, MIN_DELAY = 0.15, MAX_DELAY = 0.5, EXTRAP = 0.2, MAX_SAMPLES = 10, SNAP = 8.0, DRIFT = 0.01,
    snapshots = 0, with_clock = 0, without_clock = 0, resets = 0, jumps = 0, extrapolated = 0, held = 0, interpolated = 0, host_every = 0.1 }

function enemy.tl.clock(ht, now)
    local T = enemy.tl
    T.snapshots = T.snapshots + 1
    if not ht then
        T.without_clock = T.without_clock + 1
        if T.last_arrival then
            local iv = now - T.last_arrival
            if iv > 0.001 and iv < 1 then T.iv = T.iv + (iv - T.iv) * 0.1 end
        end
        T.last_arrival = now
        T.delay = T.delay + (math.max(T.MIN_DELAY, math.min(T.MAX_DELAY, 2 * T.iv + 0.1)) - T.delay) * 0.1
        return now
    end
    T.with_clock = T.with_clock + 1
    local o = now - ht
    if T.last_ht and (ht < T.last_ht - 0.5 or ht > T.last_ht + 30) then -- the host's clock jumped (a restarted game): start the timeline again
        T.off, T.resets = nil, T.resets + 1
        for _, e in pairs(enemy.remote) do e.buf = nil end
    end
    if T.off == nil or o < T.off then T.off = o else T.off = T.off + (o - T.off) * T.DRIFT end
    if T.last_ht and ht > T.last_ht then
        local iv = ht - T.last_ht
        if iv < 1 then T.iv = T.iv + (iv - T.iv) * 0.2 end
    end
    T.last_ht = ht
    T.delay = T.delay + (math.max(T.MIN_DELAY, math.min(T.MAX_DELAY, 2 * T.iv + 0.04)) - T.delay) * 0.1
    return ht + T.off
end

-- A new point for this enemy at local time `st`.
function enemy.tl.push(e, st, x, y, z, qx, qy, qz, qw)
    local T = enemy.tl
    local b = e.buf
    if not b then b = {} e.buf = b end
    local last = b[#b]
    if last then
        if st <= last.t then st = last.t + 0.001 end
        if (x - last.x) ^ 2 + (z - last.z) ^ 2 > T.SNAP ^ 2 or math.abs(y - last.y) > T.SNAP then -- a spawn or a warp: nothing to slide through
            for i = #b, 1, -1 do b[i] = nil end
            T.jumps = T.jumps + 1
        end
    end
    b[#b + 1] = { t = st, x = x, y = y, z = z, qx = qx, qy = qy, qz = qz, qw = qw }
    while #b > T.MAX_SAMPLES do table.remove(b, 1) end
end

-- Where the enemy is at timeline time rt: x, y, z and the facing quaternion, or nil with no samples.
function enemy.tl.sample(e, rt)
    local T = enemy.tl
    local b = e.buf
    local n = b and #b or 0
    if n == 0 then return nil end
    local c = b[n]
    if n == 1 or rt <= b[1].t then
        T.held = T.held + 1
        local f = b[1]
        return f.x, f.y, f.z, f.qx, f.qy, f.qz, f.qw
    end
    if rt >= c.t then -- ahead of the newest point (late data): carry on at the last speed for a moment, then stand
        local a = b[n - 1]
        local span = c.t - a.t
        local dt = math.min(rt - c.t, T.EXTRAP)
        T.extrapolated = T.extrapolated + 1
        if span > 1e-4 and dt > 0 then
            local k = dt / span
            return c.x + (c.x - a.x) * k, c.y + (c.y - a.y) * k, c.z + (c.z - a.z) * k, c.qx, c.qy, c.qz, c.qw
        end
        return c.x, c.y, c.z, c.qx, c.qy, c.qz, c.qw
    end
    for i = n - 1, 1, -1 do
        local a = b[i]
        if rt >= a.t then
            local d = b[i + 1]
            local span = d.t - a.t
            local u = span > 1e-6 and (rt - a.t) / span or 1
            T.interpolated = T.interpolated + 1
            local sgn = (a.qx * d.qx + a.qy * d.qy + a.qz * d.qz + a.qw * d.qw) < 0 and -1 or 1
            local qx, qy, qz, qw = a.qx + (sgn * d.qx - a.qx) * u, a.qy + (sgn * d.qy - a.qy) * u, a.qz + (sgn * d.qz - a.qz) * u, a.qw + (sgn * d.qw - a.qw) * u
            local l = math.sqrt(qx * qx + qy * qy + qz * qz + qw * qw)
            if l > 1e-6 then qx, qy, qz, qw = qx / l, qy / l, qz / l, qw / l else qx, qy, qz, qw = d.qx, d.qy, d.qz, d.qw end
            return a.x + (d.x - a.x) * u, a.y + (d.y - a.y) * u, a.z + (d.z - a.z) * u, qx, qy, qz, qw
        end
    end
    local f = b[1]
    return f.x, f.y, f.z, f.qx, f.qy, f.qz, f.qw
end

function enemy.tl.report()
    local T = enemy.tl
    local function r(x, k) k = k or 1000 return x and math.floor(x * k + 0.5) / k or nil end
    return { about = "10.12: the joiner draws the host's enemies a short time behind, between two real snapshots (position and facing); the host's clock rides in the snapshot",
        delay_s = r(T.delay), snapshot_gap_s = r(T.iv), host_sends_every_s = r(T.host_every), clock_offset_s = r(T.off), snapshots = T.snapshots, with_host_clock = T.with_clock,
        without_host_clock = T.without_clock, timeline_restarts = T.resets, jumps_snapped = T.jumps, frames_interpolated = T.interpolated, frames_extrapolated = T.extrapolated,
        frames_held = T.held }
end

----------------------------------------------------------------------------------------------
-- (10.15) THE MOLDED ("lets make sure the molded enemies are synced too from the research"). Molded Together (the other mod) found why a walk over the
-- top level of the scene never sees the Molded: every Molded body sits in a pool, a child of /MoldedGenerator/MoldedPool, so only the game's spawn points
-- know which body is out: app.EnemySpawnInfo has the body (field EnemyInstance) and a GUID (field MyGUID) that is the same in both games. (The five Em4000
-- of Chapter 3's "Moldeads" folder have no EnemySave, so "folder path / name" gave them all one id.) So here:
--   * every second the spawn points are read (scene:findComponents(app.EnemySpawnInfo), the call their scan makes once a second). A point that has a
--     body which is an Em#### object gives an enemy record named <Em4000>_<12 hex characters of the GUID>, e.g. Em4000_3fa91c2e9b4d. That name is the
--     wire name: the joiner keys its enemies, models, boxes and hits by it, and CFG.molded can ask its own spawn point with the same 12 characters.
--   * a body whose object is asleep (get_Update false) is not an enemy to fight: the game puts a Molded to sleep when no player is near its zone. It is
--     not sent, so it is drawn nowhere. (A body the scene-root walk found too keeps its record: its flags say what it is.)
--   * two scene-root objects with one name (any enemy) are told apart by a suffix from their address: one no longer overwrites the other on the joiner
--     (a parked placeholder with a live enemy's name used to hide the live one).
-- Reading only. At most MAX bodies from the spawn points per scan. A scan that cannot read the spawn points keeps the list it had.
----------------------------------------------------------------------------------------------
CFG.mold = {
    on = true,
    MAX = 14, POINTS_EVERY = 0.9, SAY_MAX = 30,
    points = {}, points_at = -100, points_err = nil,
    said = 0, seen = {},
    n = { scans = 0, unreadable = 0, points = 0, with_body = 0, bodies = 0, asleep_skipped = 0, capped = 0, renamed_duplicates = 0 },
    last = "no Molded looked for yet",
}

-- The model family an enemy's wire name stands for: "Em4000_3fa91c2e9b4d" and "Em4000" are both "Em4000".
function enemy.base(name)
    local s = tostring(name)
    return s:match("^([Ee][Mm]%d%d%d%d)") or s
end

-- (10.21) Does THIS game have its own real body of the host's enemy `name`, standing on the host's right now? Two ways it can: mode 3 moved my own enemy of that name onto the
-- host's (enemy.driven, put there within the last 1.5 s: a stale entry does not count), or a Molded body of this game is the copy of it (CFG.molded). Your 22 Nov screenshot of the
-- Mia fight: the real Mia stood on the host's and the stand-in model (a T-pose, no animation) was drawn a second time beside her, because nothing asked this question.
enemy.REAL_FRESH_S = 1.5
function enemy.real_body(name, now)
    now = now or os.clock()
    local d = enemy.driven[name]
    if d and type(d.moved_at) == "number" and now - d.moved_at <= enemy.REAL_FRESH_S then return true end
    return CFG.molded ~= nil and CFG.molded.copies ~= nil and CFG.molded.copies[name] ~= nil
end

-- The elements of a managed array: get_elements, else get_Count / get_Item (about one array in 50 has no get_elements, and every one on the title screen).
function CFG.mold.items(arr)
    if arr == nil then return nil end
    local ok, list = pcall(function() return arr:get_elements() end)
    if ok and type(list) == "table" then return list end
    local okn, n = pcall(function() return arr:call("get_Count") end)
    if not okn or type(n) ~= "number" then return nil end
    local out = {}
    for i = 0, math.min(n, 400) - 1 do
        local oki, it = pcall(function() return arr:call("get_Item", i) end)
        if oki and it ~= nil then out[#out + 1] = it end
    end
    return out
end

-- 12 hex characters of a GUID (its first two fields): enough to tell the spawn points of one scene apart, short enough for the wire. nil for an empty GUID.
function CFG.mold.id_of(g)
    if g == nil then return nil end
    local ok, a, b = pcall(function() return g:get_field("mData1"), g:get_field("mData2") end)
    if not ok or type(a) ~= "number" or type(b) ~= "number" then return nil end
    local ia, ib = math.tointeger(a), math.tointeger(b)
    if ia == nil or ib == nil or (ia == 0 and ib == 0) then return nil end
    return string.format("%08x%04x", ia & 0xFFFFFFFF, ib & 0xFFFF)
end

-- The spawn points of the scene: { { id, s, inst } } (inst = the body that is out, or nil). At most every POINTS_EVERY seconds; an unreadable answer keeps the old list.
function CFG.mold.read_points(scene, now)
    local M = CFG.mold
    if now - M.points_at < M.POINTS_EVERY then return M.points end
    M.points_at = now
    M.n.scans = M.n.scans + 1
    local okf, arr = pcall(function() return scene:call("findComponents(System.Type)", sdk.typeof("app.EnemySpawnInfo")) end)
    local list = okf and M.items(arr) or nil
    if list == nil then
        M.n.unreadable = M.n.unreadable + 1
        M.points_err = okf and "the list had no readable elements" or tostring(arr):sub(1, 80)
        return M.points
    end
    M.points_err = nil
    local out = {}
    for _, s in ipairs(list) do
        local okg, g = pcall(function() return s:get_field("MyGUID") end)
        local id = okg and M.id_of(g) or nil
        if id then
            local oki, inst = pcall(function() return s:get_field("EnemyInstance") end)
            out[#out + 1] = { id = id, s = s, inst = oki and inst or nil }
        end
    end
    M.points, M.n.points = out, #out
    return out
end

-- Adds the bodies the spawn points name to the records the root walk made (out), and renames a spawn body to <Em4000>_<id>.
function CFG.mold.add(scene, out, old, now)
    local M = CFG.mold
    if not M.on then return end
    if CFG.busy and CFG.busy.busy then return end -- a load: the game is moving objects about, nothing is touched
    local by_addr = {}
    for _, r in ipairs(out) do if r.addr then by_addr[r.addr] = r end end
    local with_body, added = 0, 0
    for _, p in ipairs(M.read_points(scene, now)) do
        local inst = p.inst
        if inst ~= nil then
            with_body = with_body + 1
            local okn, base = pcall(function() return inst:call("get_Name") end)
            local oka, addr = pcall(inst.get_address, inst)
            if okn and oka and type(base) == "string" and type(addr) == "number" and base:match("^[Ee][Mm]%d%d%d%d$") then
                local rec = by_addr[addr]
                local okup, up = pcall(function() return inst:call("get_Update") end)
                if rec == nil and okup and up == false then
                    M.n.asleep_skipped = M.n.asleep_skipped + 1
                elseif rec == nil and added >= M.MAX then
                    M.n.capped = M.n.capped + 1
                else
                    if rec == nil then
                        local okx, xf = pcall(function() return inst:call("get_Transform") end)
                        if okx and xf ~= nil then
                            rec = { name = base, go = inst, xf = xf, addr = addr }
                            local prev = old and old[addr]
                            if prev and (prev.family or prev.name) == base then
                                for _, k in ipairs(enemy.KEEP) do rec[k] = prev[k] end
                            end
                            out[#out + 1] = rec
                            by_addr[addr] = rec
                            added = added + 1
                        end
                    end
                    if rec then
                        rec.spawn, rec.family = p.id, base
                        if base:match("^[Ee][Mm]4%d%d%d$") then rec.name = base .. "_" .. p.id end
                        if not M.seen[rec.name] then
                            M.seen[rec.name] = now
                            M.last = string.format("%s is out (spawn point %s)", rec.name, p.id)
                            if M.said < M.SAY_MAX then
                                M.said = M.said + 1
                                say("molded: " .. M.last)
                            end
                        end
                    end
                end
            end
        end
    end
    M.n.with_body, M.n.bodies = with_body, added
end

-- Scene roots that share a name get a suffix from their address (the same object has the same name at every scan).
function CFG.mold.rename_duplicates(out)
    local M = CFG.mold
    local count = {}
    for _, r in ipairs(out) do
        if not r.spawn then count[r.name] = (count[r.name] or 0) + 1 end
    end
    for _, r in ipairs(out) do
        if not r.spawn and (count[r.name] or 0) > 1 and type(r.addr) == "number" then
            r.family = r.family or r.name
            r.name = r.name .. "_" .. string.format("%x", r.addr % 0x1000000)
            M.n.renamed_duplicates = M.n.renamed_duplicates + 1
        end
    end
end

function CFG.mold.report()
    local M = CFG.mold
    local names = {}
    for name in pairs(M.seen) do names[#names + 1] = name end
    table.sort(names)
    while #names > 40 do table.remove(names) end
    return { about = "10.15: the Molded sit in a pool, so the scene-root walk never saw them. The spawn points (app.EnemySpawnInfo: EnemyInstance, MyGUID) name the bodies that are out; each gets the wire name <Em4000>_<12 hex characters of the GUID>. Asleep bodies are not sent.",
        on = M.on, counts = M.n, points_error = M.points_err, last = M.last, names_seen = names }
end

-- Root objects named Em#### in the current scene (they sit at the top of the scene, so only the roots are visited), and (10.15) the Molded bodies
-- the spawn points name (CFG.mold.add), with every enemy that shares a name with another given a name of its own.
local function find_enemy_roots(prev_list)
    local out = {}
    local scene = scene_object()
    if not scene then return out end
    -- the records are rebuilt on every scan, so what was learned about an enemy's health is carried over by the
    -- object's address; before this, the whole health search ran again for every enemy every second
    local old = {}
    for _, o in ipairs(prev_list or enemy.roots or {}) do
        if o.addr then old[o.addr] = o end
    end
    local xf = scene:call("get_FirstTransform")
    local visited = 0
    while xf and visited < 6000 do
        visited = visited + 1
        local go = xf:call("get_GameObject")
        if go then
            local name = go:call("get_Name")
            if type(name) == "string" and name:match("^[Ee][Mm]%d%d%d%d$") then
                local rec = { name = name, go = go, xf = xf }
                local oka, addr = pcall(go.get_address, go)
                if oka and type(addr) == "number" then
                    rec.addr = addr
                    local prev = old[addr]
                    if prev and (prev.family or prev.name) == name then
                        for _, k in ipairs(enemy.KEEP) do rec[k] = prev[k] end
                    end
                end
                out[#out + 1] = rec
            end
        end
        xf = xf:call("get_Next")
    end
    pcall(CFG.mold.add, scene, out, old, os.clock())
    pcall(CFG.mold.rename_duplicates, out)
    return out
end

-- Health: your 2026-11 enemy dump showed the Status components have no HP field. The health lives in an
-- app.HealthInfo object held by the enemy's DamageController (field "HealthInfo"; the same controller also
-- has <defaultMaxHealth> = 8000 / 10000). I have not seen HealthInfo's own fields yet, so this looks for the
-- most health-like number in it and logs what it found; "Enemy details" dumps the whole object.
local find_health -- assigned inside the block below (keeps the main chunk under Lua's 200-local limit)
do
local HP_BAD = { "max", "default", "rate", "ratio", "regen", "recover", "limit", "scale", "damage", "time", "anger", "stun", "rank" }

-- Lower is better; nil means "not a health number".
local function hp_score(name, inside_health)
    local n = field_label(name):lower()
    for _, bad in ipairs(HP_BAD) do
        if n:find(bad, 1, true) then return nil end
    end
    local healthy = n:find("health", 1, true) or n:find("hp", 1, true) or n:find("life", 1, true)
    if n:find("current", 1, true) and (healthy or inside_health) then return 1 end
    if healthy then return 2 end
    if inside_health and (n == "value" or n == "_value" or n == "now" or n == "_now" or n == "cur" or n == "_cur") then return 3 end
    return nil
end

-- Best numeric field of obj (and its app.* parents) by hp_score. Returns field name, score.
local function best_health_field(obj, inside_health)
    local best, best_score
    pcall(function()
        local t = obj:get_type_definition()
        while t do
            local tn = t:get_full_name()
            if tn:find("^System%.") or tn:find("^via%.Component") or tn:find("^via%.Behavior") then break end
            for _, f in ipairs(t:get_fields() or {}) do
                if not f:is_static() then
                    local ft = f:get_type()
                    local ftn = ft and ft:get_full_name() or ""
                    if ftn == "System.Single" or ftn == "System.Int32" or ftn == "System.Double" then
                        local sc = hp_score(f:get_name(), inside_health)
                        if sc and (not best_score or sc < best_score) then
                            local okv, v = pcall(function() return obj:get_field(f:get_name()) end)
                            if okv and type(v) == "number" then best, best_score = f:get_name(), sc end
                        end
                    end
                end
            end
            t = t:get_parent_type()
        end
    end)
    return best, best_score
end

-- Runs once per enemy object: finds its Status component and a health number.
find_health = function(e)
    e.hp_checked = true
    e.hp_tries = (e.hp_tries or 0) + 1
    e.hp_retry_at = os.clock() + 3 -- an enemy that has not started yet has no HealthInfo: look again a few times
    pcall(function()
        local comps = e.go:call("get_Components")
        local best_sc
        local dmg_comp
        for _, c in ipairs(comps:get_elements()) do
            local full = c:get_type_definition():get_full_name()
            if full:find("^app%.Em%d+Status$") or full == "app.EnemyStatus" then
                e.status = e.status or c
                local fname, sc = best_health_field(c, false)
                if fname and (not best_sc or sc < best_sc) then e.hp_comp, e.hp_field, best_sc = c, fname, sc end
            end
            if full:find("DamageController$") then
                dmg_comp = dmg_comp or c
                e.dmg_comp = e.dmg_comp or c -- the joiner's hits are applied through it
            end
            if full:find("DamageController$") or full:find("^app%.Em%d+Status$") then
                for _, hv in ipairs(fields_of_type(c, "app.HealthInfo")) do
                    local fname, sc = best_health_field(hv[2], true)
                    if fname and (not best_sc or sc < best_sc) then
                        e.hp_comp, e.hp_field, best_sc = hv[2], fname, sc
                        e.hp_where = full .. "." .. hv[1]
                    end
                end
            end
        end
        -- 9.9: every enemy's DamageController is an app.DamageController, which has get_health() / get_maxHealth() (your
        -- 2026-11 enemy scan listed them); it works for the enemies whose HealthInfo field could not be found
        if not e.hp_field and dmg_comp then
            local okh, hv = pcall(dmg_comp.call, dmg_comp, "get_health")
            if okh and type(hv) == "number" then
                e.hp_comp, e.hp_call = dmg_comp, "get_health"
                e.hp_where = dmg_comp:get_type_definition():get_full_name()
            end
        end
    end)
    local found = e.hp_field ~= nil or e.hp_call ~= nil
    local nm = e.family or e.name -- (10.15: the model's name, not the wire name: one line for every Molded, not one for each)
    local logged = enemy.hp_logged[nm]
    if logged == nil or (logged == "none" and found) then
        enemy.hp_logged[nm] = found and "found" or "none"
        say(found and ("enemy sync: health of " .. nm .. " is read from " .. (e.hp_where and (e.hp_where .. ".") or "") .. (e.hp_field or (e.hp_call .. "()")))
            or ("enemy sync: no health field found for " .. nm .. " (use 'Enemy details' to list its fields)"))
    end
end
enemy.best_health_field = best_health_field -- the player health module (below) looks for health the same way
end -- do

local function read_health(e)
    if not e.hp_checked then
        find_health(e)
    elseif not e.hp_field and not e.hp_call and (e.hp_tries or 0) < 6 and os.clock() >= (e.hp_retry_at or 0) then
        find_health(e)
    end
    local ok, v
    if e.hp_comp and e.hp_field then
        ok, v = pcall(function() return e.hp_comp:get_field(e.hp_field) end)
    elseif e.hp_comp and e.hp_call then
        ok, v = pcall(e.hp_comp.call, e.hp_comp, e.hp_call)
    else
        return -1
    end
    if ok and type(v) == "number" then
        e.hp_fail = 0
        return v
    end
    -- the object this was learned from has gone (a new enemy at the same address): after three misses look again
    e.hp_fail = (e.hp_fail or 0) + 1
    if e.hp_fail >= 3 then
        e.hp_comp, e.hp_field, e.hp_call, e.hp_where, e.status, e.dmg_comp = nil, nil, nil, nil, nil, nil
        e.hp_checked, e.hp_tries, e.hp_fail = false, 0, 0
        e.no_is_dead, e.no_dc_dead = nil, nil -- (10.15: the components are looked for again, so the death questions are asked again too)
    end
    return -1
end

-- Why an Em#### object should not be shown as a live enemy (flag bits 2, 4, 8 of the snapshot):
--   2  parked: its Status says isStarted = false, or no animation is playing (motion id 4294967295).
--      Em8000 (a Jack boss variant) sat like this at y = -7.8 in your dump.
--   4  no app.Em####Status component: a placeholder or cutscene prop, not something you can fight (Em6190, Em3300).
--   8  at the world origin (0, 0, 0): a placeholder that was never placed.
local function inactive_flags(e, motion, p)
    local f = 0
    if not e.status then f = f + 4 end
    local parked = motion == 4294967295
    if e.status then
        local ok, started = pcall(function() return e.status:get_field("<isStarted>k__BackingField") end)
        if ok and started == false then parked = true end
    end
    if e.spawn and not parked then -- (10.15) a Molded the game has put to sleep (no player near its zone): its object does not update, it is not there to fight
        local oku, up = pcall(function() return e.go:call("get_Update") end)
        if oku and up == false then parked = true end
    end
    if parked then f = f + 2 end
    if math.abs(p.x) < 0.01 and math.abs(p.y) < 0.01 and math.abs(p.z) < 0.01 then f = f + 8 end
    return f
end

local function flags_reason(flags)
    local why = {}
    if math.floor(flags / 2) % 2 == 1 then why[#why + 1] = "parked" end
    if math.floor(flags / 4) % 2 == 1 then why[#why + 1] = "no Status component" end
    if math.floor(flags / 8) % 2 == 1 then why[#why + 1] = "at the origin" end
    return table.concat(why, ", ")
end

-- true when the game says the enemy is dead (Em2000Status / Em3000Status have get_IsDead)
local function enemy_is_dead(e)
    if e.status and not e.no_is_dead then
        local ok, dead = pcall(function() return e.status:call("get_IsDead") end)
        if ok then return dead == true end
        e.no_is_dead = true -- this Status type has no such method (only Em2000Status / Em3000Status were seen): stop asking
    end
    -- (10.15) every enemy has a DamageController, and the other mod reads "get_isDead" from it for all of them (the Molded included, whose Status has
    -- no get_IsDead: until now a dead Molded was sent as alive for good). Not answered (an error): asked no more for this record.
    local dc = e.dmg_comp
    if dc and not e.no_dc_dead then
        local ok, dead = pcall(function() return dc:call("get_isDead") end)
        if ok and type(dead) == "boolean" then return dead end
        e.no_dc_dead = true
    end
    return false
end

-- bank, motion id and frame of the first animation layer (diagnostic: sent along, not applied yet)
local function read_motion(e)
    local bank, motion, frame = 0, 0, 0
    pcall(function()
        local m = e.go:call("getComponent(System.Type)", sdk.typeof("via.motion.Motion"))
        local layer = m and m:call("getLayer", 0)
        if layer then
            bank = tonumber(layer:call("get_MotionBankID")) or 0
            motion = tonumber(layer:call("get_MotionID")) or 0
            frame = tonumber(layer:call("get_Frame")) or 0
        end
    end)
    return math.floor(bank), math.floor(motion), frame
end

local function snapshot_one(e)
    local p = e.xf:call("get_Position")
    local q = e.xf:call("get_Rotation")
    local hp = read_health(e)
    if hp ~= hp or hp > 1e9 or hp < -1e9 then hp = -1 end
    local bank, motion, frame = read_motion(e)
    if frame ~= frame or frame > 1e7 or frame < -1e7 then frame = 0 end
    if CFG.eanim then pcall(CFG.eanim.seen, e.family or e.name, e.go, bank, motion, frame, "host") end -- (9.41: the table of banks and clips; 10.15: per model, not per Molded)
    local flags = inactive_flags(e, motion, p) + (enemy_is_dead(e) and 0 or 1) -- bit 0: alive
    e.last_flags = flags
    -- (10.15) the enemy's maximum health goes along as a 14th field (an older joiner reads 13 and ignores it): the joiner shows "health / maximum" and keeps its own copy's
    -- SHARE of the pool equal when the two games run different difficulties. Not sent when the game gave none.
    local okm, mx = pcall(CFG.pool.max_of, e, os.clock())
    if not okm then mx = nil end
    e.last_hp, e.last_max, e.last_x, e.last_y, e.last_z = hp, mx, p.x, p.y, p.z -- (the host's own boss bar reads these)
    return string.format("%s,%.2f,%.2f,%.2f,%.3f,%.3f,%.3f,%.3f,%d,%d,%d,%d,%.1f%s", e.name, p.x, p.y, p.z,
        q.x, q.y, q.z, q.w, math.floor(hp), flags, bank, motion, frame, mx and string.format(",%d", math.floor(mx + 0.5)) or "")
end

-- HOST: scan once a second, send ten times a second.
local function enemy_host_update(now)
    if enemy.mode < 2 or state.role ~= "host" or state.transport ~= "tcp" then return end
    if not peer_present(now) then return end
    if CFG.limb then pcall(CFG.limb.update, now) end -- (10.21) the host's Molded: a head or limb lost here is told to the joiner, and the joiner's are removed here (every 0.5 s)
    if now - enemy.last_scan >= 1.0 then
        enemy.last_scan = now
        CFG.perf.mark("enemy host: before the scan") -- (10.20: the scene scan on its own, so a file says whether it or the snapshots are the cost)
        local ok, roots = pcall(find_enemy_roots)
        if ok then enemy.roots = roots else enemy_note("scan failed: " .. tostring(roots)) end
        CFG.perf.mark("enemy host: scene scan (once a second)")
    end
    -- (10.12) 15 snapshots a second while there are few enemies to read (the reading is the cost), 10 with many
    local every = (#enemy.roots <= enemy.FAST_MAX) and enemy.FAST_EVERY or 0.1
    enemy.tl.host_every = every
    if now - enemy.last_send < every - 0.004 then return end -- (a little early is fine: at 60 frames a second four frames are 66.7 ms, and a float of that is just short of 1/15)
    enemy.last_send = now
    local parts = {}
    for i = #enemy.roots, 1, -1 do
        if (CFG.own and CFG.own.peer[enemy.roots[i].name]) or (CFG.carsync and CFG.carsync.jack_held(enemy.roots[i].name)) then
            -- (10.18) an enemy the joiner runs (the hand-over): the joiner's own game sends its state, not mine
        else
            local ok, text = pcall(snapshot_one, enemy.roots[i])
            if ok then
                parts[#parts + 1] = text
            else
                table.remove(enemy.roots, i) -- gone or unreadable: the next scan will find it again if it is real
            end
        end
    end
    if CFG.carsync then -- (10.19) the garage car's line goes FIRST, so the size cut below never takes it
        local okx, ex = pcall(CFG.carsync.extra_parts, now)
        if okx and ex then for i = #ex, 1, -1 do table.insert(parts, 1, ex[i]) end end
    end
    local payload = #parts > 0 and table.concat(parts, ";") or ""
    if #payload > 2880 then
        local cut = payload:find(";[^;]*$")
        if cut then payload = payload:sub(1, cut - 1) end
    end
    -- (10.12) the host's clock first ("T12.345"): an older joiner finds no enemy in an entry with no commas and skips it
    payload = string.format("T%.3f", now) .. (payload ~= "" and (";" .. payload) or "")
    enemy.seq = enemy.seq + 1
    enemy.sent = enemy.sent + 1
    json.dump_file(FILES.STATE_OUT_FILE, { seq = enemy.seq, p = payload })
end

local function finite(v)
    return type(v) == "number" and v == v and v > -1e7 and v < 1e7
end

-- JOINER: read the latest snapshot from re7mp.exe.
local function enemy_read(now)
    enemy.last_read = now
    local d = json.load_file(FILES.STATE_IN_FILE)
    if type(d) ~= "table" or d.seq == nil or type(d.p) ~= "string" then return end
    if d.seq == enemy.remote_seq then return end
    enemy.remote_seq = d.seq
    enemy.received = tonumber(d.n) or (enemy.received + 1)
    enemy.remote_at = now
    local seen, count = {}, 0
    local ht = tonumber(d.p:match("^T(%-?[%d%.]+)")) -- (10.12) the host's clock, when it sends one
    local st = enemy.tl.clock(ht, now)
    if CFG.carsync then pcall(CFG.carsync.on_payload, d.p, st, now) end -- (10.19) the garage car line, when the host runs the car
    if d.p ~= "-" then
        for entry in d.p:gmatch("[^;]+") do
            local f = {}
            for field in entry:gmatch("[^,]+") do f[#f + 1] = field end
            local name = f[1]
            local v = {}
            for i = 2, 14 do v[i] = tonumber(f[i]) end -- (10.15: field 14 is the maximum health; an older host sends 13 fields)
            if name and #f >= 13 and name:match("^[%w_]+$") and finite(v[2]) and finite(v[3]) and finite(v[4]) and not (CFG.own and CFG.own.mine[name]) and not (CFG.carsync and CFG.carsync.jack_held(name)) then -- (10.18: not an enemy I run myself; 10.19: nor Jack while I run the car)
                count = count + 1
                if count > 40 then break end
                local e = enemy.remote[name]
                if not e then
                    e = { rx = v[2], ry = v[3], rz = v[4] }
                    enemy.remote[name] = e
                end
                e.x, e.y, e.z = v[2], v[3], v[4]
                e.qx, e.qy, e.qz, e.qw = v[5] or 0, v[6] or 0, v[7] or 0, v[8] or 1
                pcall(enemy.tl.push, e, st, e.x, e.y, e.z, e.qx, e.qy, e.qz, e.qw) -- (10.12) a point on this enemy's timeline
                local fl = math.floor(v[10] or 1)
                e.hp, e.alive = v[9] or -1, fl % 2 == 1
                e.max = (finite(v[14]) and v[14] > 0) and v[14] or nil -- (10.15) the host's maximum health for this enemy, when it sent one
                -- a snapshot sent just before the host applied our hit still carries the old health: for a moment the host's answer wins
                if e.ack_hp and now < (e.ack_until or 0) and e.hp > e.ack_hp then e.hp = e.ack_hp end
                e.inactive = fl >= 2 and flags_reason(fl) or nil -- parked / placeholder objects (see inactive_flags)
                e.bank, e.motion, e.frame = v[11] or 0, v[12] or 0, v[13] or 0
                e.frame_at = now -- (9.41: when that frame was read, so the clip can be started where the host's is by now)
                seen[name] = true
            end
        end
    end
    for name in pairs(enemy.remote) do
        if not seen[name] then enemy.remote[name] = nil end
    end
    enemy.count = count
    enemy.last = string.format("%d enemies from the host", count)
end

local function receiving_enemies()
    return enemy.mode >= 2 and (state.role == "join" or enemy.test_ghosts)
end

local function enemy_release_all()
    if CFG.eanim then pcall(CFG.eanim.release_all, "driving stopped") end -- (9.41: their own animation controllers back first)
    for name, d in pairs(enemy.driven) do
        for _, comp in ipairs(d.disabled or {}) do pcall(function() comp:call("set_Enabled", true) end) end
        enemy.driven[name] = nil
    end
end

local start_driving
do
local DRIVE_OFF = {
    "^app%.Em%d+Think$", "^app%.Em%d+Order$", "^app%.Em%d+%.Em%d+ActionController$", "^app%.MovementController$",
    "^via%.physics%.CharacterController$", "^app%.CommandActionController$", "^app%.Command%.CommandUpdater$",
    "^app%.Command%.CommandRequester$",
}

-- (10.18) the components that run an enemy's own AI, switched off; returns the ones that were (the hand-over uses it for the host's body of an enemy the joiner runs)
enemy.drive_off = function(root)
    local disabled = {}
    pcall(function()
        local comps = root.go:call("get_Components")
        for _, c in ipairs(comps:get_elements()) do
            local full = c:get_type_definition():get_full_name()
            for _, pat in ipairs(DRIVE_OFF) do
                if full:find(pat) then
                    local ok = pcall(function() c:call("set_Enabled", false) end)
                    if ok then disabled[#disabled + 1] = c end
                    break
                end
            end
        end
    end)
    return disabled
end

start_driving = function(name, root)
    local d = { go = root.go, xf = root.xf, disabled = enemy.drive_ai and enemy.drive_off(root) or {} }
    enemy.driven[name] = d
    say(string.format("enemy sync: now moving my %s onto the host's (%d components switched off)", name, #d.disabled))
end
end -- do

-- 9.26 (your note "an enemy block option like with hide other player, same rules"): 4 times a second the nearest 6 boxes are tested
-- against walls from the camera (chest, and the head if the chest is covered), with the same physics test the other player and the
-- joiner's shots use (HIT.wall_between), and a change needs two tests in a row both ways. A hidden box is not drawn, label included.
-- If the test cannot run (no calibration yet, switched off), every box is drawn as before.
local function enemy_walls_update(now)
    if not enemy.hide_walls or not state.occlude then
        if next(enemy.wall) then enemy.wall = {} end
        return
    end
    if now - enemy.wall_at < 0.25 then return end
    enemy.wall_at = now
    local lp = state.local_pos
    if not lp then return end
    local near = {}
    for name, e in pairs(enemy.remote) do
        if e.x and e.alive and not e.inactive and e.rx then
            near[#near + 1] = { name = name, e = e, d2 = (e.rx - lp.x) ^ 2 + (e.rz - lp.z) ^ 2 }
        end
    end
    table.sort(near, function(a, b) if a.d2 ~= b.d2 then return a.d2 < b.d2 end return a.name < b.name end)
    local keep = {}
    for i = 1, math.min(#near, 6) do
        local it = near[i]
        local e = it.e
        local chest = enemy.hit.wall_between(lp, e.rx, e.ry + 0.95, e.rz)
        if chest == nil then
            enemy.wall = {}
            return
        end
        local seen = chest == false
        if not seen then
            local head = enemy.hit.wall_between(lp, e.rx, e.ry + 1.65, e.rz)
            seen = head == false
        end
        local w = enemy.wall[it.name] or { hide = false, hs = 0, cs = 0 }
        enemy.wall_checks = enemy.wall_checks + 1
        if seen then
            w.cs, w.hs = w.cs + 1, 0
            if w.cs >= 2 then w.hide = false end
        else
            w.hs, w.cs = w.hs + 1, 0
            enemy.wall_hidden_checks = enemy.wall_hidden_checks + 1
            if w.hs >= 2 then w.hide = true end
        end
        keep[it.name] = w
    end
    enemy.wall = keep
end

-- JOINER, every frame: smooth the received positions; in mode 3 also put my own matching enemies there.
local function enemy_update(now, dt)
    if enemy.mode < 2 or not receiving_enemies() then
        if next(enemy.driven) then enemy_release_all() end
        if CFG.molded and next(CFG.molded.copies) then pcall(CFG.molded.release_all, "the enemy data is off") end -- (10.15)
        return
    end
    if now - enemy.last_read >= 0.05 then enemy_read(now) end
    -- (10.12) the timeline: every enemy is where the host's was `delay` seconds ago (between two real snapshots); with no timeline (nothing sampled) the old chase
    local rt = now - enemy.tl.delay
    local a = 1 - math.exp(-12 * dt)
    for _, e in pairs(enemy.remote) do
        if e.x then
            local ok, x, y, z, qx, qy, qz, qw = pcall(enemy.tl.sample, e, rt)
            if ok and x then
                e.rx, e.ry, e.rz = x, y, z
                e.rqx, e.rqy, e.rqz, e.rqw = qx, qy, qz, qw
            else
                local dx, dz = e.x - e.rx, e.z - e.rz
                if dx * dx + dz * dz > 64 then
                    e.rx, e.ry, e.rz = e.x, e.y, e.z
                else
                    e.rx = e.rx + (e.x - e.rx) * a
                    e.ry = e.ry + (e.y - e.ry) * a
                    e.rz = e.rz + (e.z - e.rz) * a
                end
            end
        end
    end
    pcall(enemy_walls_update, now)
    if CFG.molded then pcall(CFG.molded.update, now, dt) end -- (10.15) copies of the host's Molded in this game (off unless ticked)
    if CFG.kill then pcall(CFG.kill.update, now) end -- (10.21) my copy died while the host's lives: ask the host to kill it (CFG.kill; also in mode 2, where Molded copies work)
    if CFG.limb then pcall(CFG.limb.update, now) end -- (10.21) a head or limb lost on a copy here is told to the host, and the host's are removed here (CFG.limb)
    if enemy.mode < 3 or now - enemy.remote_at > 3 then
        if next(enemy.driven) then enemy_release_all() end
        return
    end
    if now - enemy.local_scan >= 1.0 then
        enemy.local_scan = now
        local ok, roots = pcall(find_enemy_roots)
        if ok then enemy.local_roots = roots end
    end
    for _, root in ipairs(enemy.local_roots) do
        local e = enemy.remote[root.name]
        -- (10.15) a Molded out of its pool (root.spawn) is not moved here: a position set on a pooled body is undone, and switching its components off broke
        -- the Molded for the other mod. CFG.molded (its own switch) takes those out of the pool first.
        if e and e.alive and not e.inactive and not root.spawn then
            if not enemy.driven[root.name] then start_driving(root.name, root) end
            local d = enemy.driven[root.name]
            local ok, err = pcall(function()
                d.xf:call("set_Position", Vector3f.new(e.rx, e.ry, e.rz))
                local f = rotate({ x = e.rqx or e.qx, y = e.rqy or e.qy, z = e.rqz or e.qz, w = e.rqw or e.qw }, { 0, 0, 1 })
                d.xf:call("set_EulerAngle", Vector3f.new(0, math.atan(f[1], f[3]), 0))
            end)
            if not ok then
                enemy.driven[root.name] = nil
                enemy_note("could not move " .. root.name .. ": " .. tostring(err))
            else
                d.moved_at, d.hx, d.hy, d.hz = now, e.rx, e.ry, e.rz -- (10.15) when and where it was last put on the host's enemy
                pcall(CFG.pool.follow, root, e, now) -- (10.15) and its health becomes the host's
            end
        elseif e and not e.alive and not e.inactive and not root.spawn and enemy.driven[root.name] then
            pcall(CFG.pool.finish, root, e, now) -- (10.15) the host's enemy is dead: so is my copy of it
        end
    end
end

local function unit_quat(e)
    local qx, qy, qz, qw = e.rqx or e.qx, e.rqy or e.qy, e.rqz or e.qz, e.rqw or e.qw -- (10.12) the facing of the timeline, else the newest snapshot's
    local l = math.sqrt(qx * qx + qy * qy + qz * qz + qw * qw)
    if l < 1e-6 then return { x = 0, y = 0, z = 0, w = 1 } end
    return { x = qx / l, y = qy / l, z = qz / l, w = qw / l }
end

local function draw_enemies(now)
    if not receiving_enemies() or now - enemy.remote_at > 3 then return end
    local lp = state.local_pos
    if not lp then return end
    local cam = { lp.x, lp.y, lp.z }
    for name, e in pairs(enemy.remote) do
        local walled = enemy.wall[name] and enemy.wall[name].hide
        if e.x and e.alive and (not e.inactive or enemy.show_parked) and not walled then
            local q = unit_quat(e)
            local ax, ay, az = rotate(q, { 1, 0, 0 }), rotate(q, { 0, 1, 0 }), rotate(q, { 0, 0, 1 })
            local foot = { e.rx, e.ry, e.rz }
            local center = vadd(foot, vscale(ay, 0.95))
            local modelled = (CFG.pup and CFG.pup.covers(name)) or (CFG.molded and CFG.molded.copies[name] ~= nil) -- (9.31) its model is there: the box is only the fallback; (10.15) or this game's own body of it
                or enemy.real_body(name, now) -- (10.21) mode 3 has put my own enemy of that name on it: that body is the picture, no box over it
            if modelled then
                -- no box, no nose: the model shows where it is and which way it faces
            elseif e.inactive then -- only drawn when "show parked" is on: grey, with the reason in the label
                draw_box(make_box(center, ax, ay, az, 0.32, 0.95, 0.22), cam, { 150, 150, 150 }, 90, rgba(50, 50, 50, 200))
            else
                draw_box(make_box(center, ax, ay, az, 0.32, 0.95, 0.22), cam, { 255, 70, 70 }, 140, rgba(90, 0, 0, 230))
            end
            if not modelled then -- a bright block on the front of the head shows which way it faces
                local nose = vadd(vadd(foot, vscale(ay, 1.65)), vscale(az, 0.2))
                draw_box(make_box(nose, ax, ay, az, 0.08, 0.05, 0.05), cam, { 255, 230, 120 }, 230, rgba(90, 60, 0, 230))
            end
            local tag = project({ e.rx, e.ry + 2.05, e.rz })
            if tag then
                local who = CFG.ids and CFG.ids.label(name)
                local shown = enemy.base(name) -- (10.15: "Em4000", not the whole wire name of one Molded of several)
                local label = e.hp and e.hp >= 0 and string.format("%s  HP %d", shown, e.hp) or shown
                if e.hp and e.hp >= 0 and e.max then label = string.format("%s  HP %d/%d", shown, e.hp, e.max) end -- (10.15)
                if e.inactive then label = label .. "  (" .. e.inactive .. ")" end
                if who then label = label .. "  - " .. who end -- (9.31: what the id is)
                draw.text(label, tag.x - #label * 3.5, tag.y - 14, e.inactive and 0xFFB0B0B0 or 0xFF4040FF)
            end
        end
    end
end

----------------------------------------------------------------------------------------------
-- (10.16) THE QUIET CHECK (CFG.guard). Your 20 Nov report: "crash after mia fight, crash when fighting jack". The journal of the Mia crash (10.15) shows the pool code writing the boss's
-- health (setHealth) 1.4 s after the cutscene c01e04_00 started and again at 3.7 s, a health number that did not even match (host maximum 2000, mine 700: "700 -> 245"), and
-- three damage calls of 3000 at a boss the game's own script was about to take away ("mine would not die after 3 hits", then "Enemy model gone: Em2000"). The other mod's notes (its
-- v0.36: "scripted damage 1300 + requestDamageAction on Em2000 during c01e04_00, 'VMContext was already corrupted', c0000005 18 s later") record the same kind of crash and the same
-- fix: nothing is written to a boss while a scripted moment plays. This is the check the pool, the weapon model and the boss hits use. It only reads. A "scripted moment" is:
--   * the loading gate (CFG.busy) is shut;
--   * the story hook saw a requestEvent less than EVENT_S seconds ago (any event, the game's own too; only while the hook is installed);
--   * a cutscene is running: GameManager._GameEventMan.RunningEventControllers has entries AND MenuManager.isPlayingEvent is not false (the other mod's notes: a long background event
--     such as c01e01_01 stays "running" during the Mia fight and only counts when isPlayingEvent says so), read every READ_EVERY s;
--   * a cutscene ended less than ENDED_S seconds ago.
-- UNVERIFIED in this script's own game session: whether those two fields read here as they did there. `health.guard` says what was readable, so the next file tells.
----------------------------------------------------------------------------------------------
CFG.guard = {
    EVENT_S = 4, ENDED_S = 4, READ_EVERY = 0.25,
    read_at = -100, running = nil, playing = nil, was_running = false, ended_at = nil, source = "not read yet", last_why = nil, last_at = nil,
    n = { checks = 0, quiet = 0, loading = 0, event_started = 0, cutscene = 0, just_ended = 0, reads = 0, read_ok = 0, read_failed = 0, cutscene_starts = 0 },
}

do
local G = CFG.guard

-- Is a cutscene running? true / false, or nil when the game would not say. Read at most every READ_EVERY seconds.
function G.cutscene(now)
    if now - G.read_at < G.READ_EVERY then return G.running end
    G.read_at = now
    G.n.reads = G.n.reads + 1
    local ok, count, why = pcall(function()
        local gm = sdk.get_managed_singleton("app.GameManager")
        if gm == nil then return nil, "no GameManager" end
        local em
        local okf, v = pcall(function() return gm:get_field("_GameEventMan") end)
        if okf and v ~= nil then em = v end
        if em == nil then
            local td = sdk.find_type_definition("app.GameManager")
            local fd = td and td:get_field("_GameEventMan")
            local okd, d = pcall(function() return fd and fd:get_data(nil) end)
            if okd and d ~= nil then em = d end
        end
        if em == nil then return nil, "no _GameEventMan" end
        local list = em:get_field("RunningEventControllers")
        if list == nil then return nil, "no RunningEventControllers" end
        local okc, c = pcall(function() return list:call("get_Count") end)
        if okc and type(c) == "number" then return c end
        local oks, s = pcall(function() return list:get_field("_size") end)
        if oks and type(s) == "number" then return s end
        return nil, "the list has no count"
    end)
    local running
    if ok and type(count) == "number" then
        running = count > 0
        if running then -- (a background event is not a cutscene: the game says so with isPlayingEvent)
            local okp, pv = pcall(function()
                local mm = sdk.get_managed_singleton("app.MenuManager")
                if mm == nil then return nil end
                local r = mm:call("isPlayingEvent")
                if r == nil then r = mm:call("get_isPlayingEvent") end
                return r
            end)
            G.playing = okp and pv or nil
            if okp and pv == false then running = false end
        end
        G.n.read_ok = G.n.read_ok + 1
        G.source = "RunningEventControllers.Count = " .. count .. (G.playing ~= nil and (", isPlayingEvent " .. tostring(G.playing)) or "")
    else
        G.n.read_failed = G.n.read_failed + 1
        G.source = "unreadable: " .. tostring(ok and why or count):sub(1, 60)
        running = nil
    end
    if running == true and not G.was_running then G.n.cutscene_starts = G.n.cutscene_starts + 1 end
    if G.was_running and running ~= true then G.ended_at = now end
    G.was_running = running == true
    G.running = running
    return running
end

-- Why this is NOT a quiet moment ("loading", "an event just started", "a cutscene is playing", "a cutscene just ended"), or nil when it is.
function G.why(now)
    now = now or os.clock()
    G.n.checks = G.n.checks + 1
    local w
    if CFG.busy and CFG.busy.busy then
        w = "loading"
        G.n.loading = G.n.loading + 1
    else
        local S = CFG.story
        if S and S.hooked and type(S.last_event_at) == "number" and now - S.last_event_at < G.EVENT_S and now >= S.last_event_at then
            w = "an event just started"
            G.n.event_started = G.n.event_started + 1
        elseif G.cutscene(now) == true then
            w = "a cutscene is playing"
            G.n.cutscene = G.n.cutscene + 1
        elseif G.ended_at and now - G.ended_at < G.ENDED_S then
            w = "a cutscene just ended"
            G.n.just_ended = G.n.just_ended + 1
        end
    end
    if w then G.last_why, G.last_at = w, now else G.n.quiet = G.n.quiet + 1 end
    return w
end

function G.report()
    return { about = "10.16: the quiet check the pool, the weapon model and the boss hits wait for (the loading gate, an event that just started, a running cutscene, a cutscene that just ended). It only reads.",
        source = G.source, running = G.running, is_playing_event = G.playing, counts = G.n, last_not_quiet = G.last_why,
        last_not_quiet_s_ago = G.last_at and math.floor((os.clock() - G.last_at) * 10) / 10 or nil, event_quiet_s = G.EVENT_S, ended_quiet_s = G.ENDED_S }
end
end -- do

----------------------------------------------------------------------------------------------
-- The garage car probe (10.16; READS ONLY, nothing is sent, nothing is written to the game).
-- The notes of the other mod say "Garage fight: CarInGarage not synced; a friend driving shows as their character moving at seat height", and nothing records what the type
-- is. This writes it down: the type definition of app.CarInGarage (every field with its type, every method with its parameter count and return type), and, while an object of
-- it exists in the scene (the garage), three readings of its plain fields (numbers, booleans, text, vectors; an object field only says what type it is and whether it is set),
-- the game object it sits on (name, position, component types) and which fields CHANGED between the readings (the candidates for "where the car is" and "who drives it").
-- Off at every start (a box in the panel, not remembered). One scene look every 2 s while it waits; three readings (now, +5 s, +15 s); then it stops until "Probe again".
-- Result: re7mp/car_probe.json and health.car_probe.
----------------------------------------------------------------------------------------------
CFG.car = {
    -- (10.27) The 10.26 dump stopped at exactly 220 fields (its cap), 12 short of the end of the car's list: IsEnemyDriving, IsPlayerDriving, FlagWindowBroken, the crash counters and
    -- the tyre flags were all beyond it. The cap is 520 now. The other three types are the car's two controllers (Strike = hits on the car, Damage = its damage; both are on the car) and
    -- the delegate type of CurrentAction / NextAction; they only get their type dumped (small caps) and, for the two controllers, their fields read.
    TYPES = { "app.CarInGarage", "app.CarDamageControllerInGarage", "app.CarStrikeControllerInGarage", "app.CarInGarage.Action" },
    CONTROLLERS = { "app.CarDamageControllerInGarage", "app.CarStrikeControllerInGarage" }, SMALL_FIELDS = 120, SMALL_METHODS = 120,
    EVERY = 2, READ_AT = { 0, 5, 15 }, MAX_FIELDS = 520, MAX_METHODS = 400, MAX_INSTANCES = 3, MAX_COMPONENTS = 40,
    on = false, status = "off", look_at = -100, first_at = nil, readings = 0, started_at = nil,
    result = nil, n = { looks = 0, instances_seen = 0, type_reads = 0, writes = 0, errors = 0 }, last_error = nil,
}
do
local C = CFG.car

local function tname(t)
    if t == nil then return nil end
    local ok, v = pcall(function() return t:get_full_name() end)
    return ok and v or nil
end

-- The type: fields (name, type, static), methods (name, parameter count, return type), up to the first System. / via.Component parent
function C.type_dump(tn, max_fields, max_methods)
    max_fields, max_methods = max_fields or C.MAX_FIELDS, max_methods or C.MAX_METHODS
    local td = sdk.find_type_definition(tn)
    if td == nil then return { type = tn, found = false } end
    local out = { type = tn, found = true, parent = nil, fields = {}, methods = {} }
    local okp, par = pcall(function() return td:get_parent_type() end)
    if okp and par then out.parent = tname(par) end
    local t, hops = td, 0
    while t and hops < 4 do
        local name = tname(t) or "?"
        if hops > 0 and (name:find("^System%.") or name:find("^via%.Component") or name:find("^via%.Behavior")) then break end
        local okf, fl = pcall(function() return t:get_fields() end)
        for _, f in ipairs(okf and fl or {}) do
            if #out.fields < max_fields then
                local okn, fname = pcall(function() return f:get_name() end)
                if okn then
                    local oks, st = pcall(function() return f:is_static() end)
                    out.fields[#out.fields + 1] = { name = fname, type = tname(select(2, pcall(function() return f:get_type() end))), static = oks and st or nil, declared_in = name }
                end
            end
        end
        local okm, ml = pcall(function() return t:get_methods() end)
        for _, m in ipairs(okm and ml or {}) do
            if #out.methods < max_methods then
                local okn, mname = pcall(function() return m:get_name() end)
                if okn then
                    local okc, np = pcall(function() return m:get_num_params() end)
                    local okr, rt = pcall(function() return m:get_return_type() end)
                    out.methods[#out.methods + 1] = { name = mname, params = okc and np or nil, returns = okr and tname(rt) or nil, declared_in = name }
                end
            end
        end
        local okq, up = pcall(function() return t:get_parent_type() end)
        t = okq and up or nil
        hops = hops + 1
    end
    out.fields_total, out.methods_total = #out.fields, #out.methods
    out.cut = (#out.fields >= max_fields or #out.methods >= max_methods) or nil -- (10.27) true when a cap was hit: the list may go on
    return out
end

-- The plain fields of one object (at most max of them; the cap of the car itself by default)
function C.read_fields(obj, max)
    max = max or C.MAX_FIELDS
    local out = {}
    local okt, td = pcall(function() return obj:get_type_definition() end)
    if not okt or td == nil then return out end
    local t, hops = td, 0
    while t and hops < 4 and #out < max do
        local name = tname(t) or "?"
        if hops > 0 and (name:find("^System%.") or name:find("^via%.Component") or name:find("^via%.Behavior")) then break end
        local okf, fl = pcall(function() return t:get_fields() end)
        for _, f in ipairs(okf and fl or {}) do
            if #out < max then
                local okn, fname = pcall(function() return f:get_name() end)
                local oks, st = pcall(function() return f:is_static() end)
                if okn and not (oks and st) then
                    local ft = tname(select(2, pcall(function() return f:get_type() end))) or "?"
                    local okv, v = pcall(function() return obj:get_field(fname) end)
                    local entry = { name = fname, type = ft }
                    if not okv then
                        entry.error = true
                    elseif v == nil then
                        entry.set = false
                    elseif type(v) == "number" or type(v) == "boolean" then
                        entry.value = v
                    elseif type(v) == "string" then
                        entry.value = v:sub(1, 80)
                    elseif type(v) == "userdata" or type(v) == "table" then
                        local okx, x, y, z = pcall(function() return v.x, v.y, v.z end)
                        if okx and type(x) == "number" and type(y) == "number" and type(z) == "number" then
                            entry.value = string.format("%.3f %.3f %.3f", x, y, z)
                        else
                            entry.set = true
                        end
                    end
                    out[#out + 1] = entry
                end
            end
        end
        local okq, up = pcall(function() return t:get_parent_type() end)
        t = okq and up or nil
        hops = hops + 1
    end
    return out
end

-- (10.27) What an object is, without assuming: its type, its text (ToString) and, when it is a delegate, which method it holds (get_Method().get_Name()), the type that method is in and
-- the type it is bound to (get_Target). CurrentAction of the car is such a thing (the 10.26 probe only said "set"); the car has a process<Mode> method for each of its modes.
function C.describe(obj)
    if obj == nil then return { set = false } end
    local d = { set = true }
    local okt, td = pcall(function() return obj:get_type_definition() end)
    if okt and td ~= nil then d.type = tname(td) end
    local oks, txt = pcall(function() return obj:call("ToString()") end)
    if oks and txt ~= nil then d.text = tostring(as_text(txt) or txt):sub(1, 120) end
    local okm, mi = pcall(function() return obj:call("get_Method") end)
    if okm and mi ~= nil then
        local okn, nm = pcall(function() return mi:call("get_Name") end)
        if okn and nm ~= nil then d.method = tostring(as_text(nm) or nm):sub(1, 80) end
        local okd, dt = pcall(function() return mi:call("get_DeclaringType") end)
        if okd and dt ~= nil then
            local okf, fname = pcall(function() return dt:call("get_FullName") end)
            if okf and fname ~= nil then d.method_in = tostring(as_text(fname) or fname):sub(1, 80) end
        end
    end
    local okg, tg = pcall(function() return obj:call("get_Target") end)
    if okg and tg ~= nil then
        local okx, tdx = pcall(function() return tg:get_type_definition() end)
        d.target = okx and tname(tdx) or "set"
    end
    return d
end

-- (10.27) The state machine's current state, read both ways: through the car's own Fsm field and through the game object's getComponent. The 10.26 car module read the field's one and got
-- nothing all session while the actor probe, reading the other, saw 19 changes. Each answer is written with its text or the reason it gave none, and whether the two are the same object.
function C.read_state(comp, go)
    local out = {}
    local function ask(fsm)
        if fsm == nil then return { got = "no object" } end
        local a = {}
        local okt, td = pcall(function() return fsm:get_type_definition() end)
        if okt and td ~= nil then a.type = tname(td) end
        local oka, addr = pcall(function() return fsm:get_address() end)
        if oka then a.address = addr end
        local ok, v = pcall(function() return fsm:call("getCurrentState(System.UInt32)", 0) end)
        if not ok then a.got = "error: " .. tostring(v):sub(1, 80)
        elseif v == nil then a.got = "nothing"
        else
            a.got = "text"
            a.state = tostring(as_text(v) or ""):sub(1, 60)
            a.lua_type = type(v)
        end
        return a
    end
    local okf, f1 = pcall(function() return comp:get_field("Fsm") end)
    out.field = ask(okf and f1 or nil)
    local okc, f2 = pcall(function() return go:call("getComponent(System.Type)", sdk.typeof("via.fsm.Fsm")) end)
    out.component = ask(okc and f2 or nil)
    if out.field.address and out.component.address then out.same_object = out.field.address == out.component.address end
    return out
end

-- One object of the type: its game object (name, position, component types) and its fields
function C.read_instance(obj)
    local rec = { fields = {} }
    pcall(tracer.crumb, "recorder", "car probe: reading an object of " .. tostring(tname((select(2, pcall(function() return obj:get_type_definition() end))))))
    local okg, go = pcall(function() return obj:call("get_GameObject") end)
    if okg and go ~= nil then
        local okn, nm = pcall(function() return go:call("get_Name") end)
        if okn then rec.game_object = as_text(nm) end
        local okp, pos = pcall(function() return go:call("get_Transform"):call("get_Position") end)
        if okp and pos and type(pos.x) == "number" then rec.position = string.format("%.3f %.3f %.3f", pos.x, pos.y, pos.z) end
        local okc, comps = pcall(function() return go:call("get_Components") end)
        local list = okc and CFG.mold.items(comps) or nil
        if list then
            rec.components = {}
            for _, c in ipairs(list) do
                if #rec.components < C.MAX_COMPONENTS then
                    local okt, td = pcall(function() return c:get_type_definition() end)
                    rec.components[#rec.components + 1] = okt and tname(td) or "?"
                end
            end
        end
    end
    rec.fields = C.read_fields(obj)
    -- (10.27) the things the 10.26 file could not tell: the delegates described, the state machine read both ways, the car's two controllers (fields only; they are on the car's game object)
    local function field_of(name)
        local ok, v = pcall(function() return obj:get_field(name) end)
        return ok and v or nil
    end
    rec.current_action = C.describe(field_of("CurrentAction"))
    rec.next_action = C.describe(field_of("NextAction"))
    if okg and go ~= nil then
        rec.state = C.read_state(obj, go)
        rec.controllers = {}
        for _, tn in ipairs(C.CONTROLLERS) do
            local okc, comp = pcall(function() return go:call("getComponent(System.Type)", sdk.typeof(tn)) end)
            rec.controllers[#rec.controllers + 1] = (okc and comp ~= nil) and { type = tn, fields = C.read_fields(comp, C.SMALL_FIELDS) } or { type = tn, found = false }
        end
    end
    return rec
end

-- The objects of the type in the scene (at most MAX_INSTANCES); nil when the scene would not say
function C.instances(tn, max)
    local scene = scene_object()
    if not scene then return nil end
    local okf, arr = pcall(function() return scene:call("findComponents(System.Type)", sdk.typeof(tn)) end)
    if not okf then return nil, tostring(arr):sub(1, 80) end
    local list = CFG.mold.items(arr)
    if list == nil then return {} end
    local out = {}
    for _, o in ipairs(list) do
        if #out < (max or C.MAX_INSTANCES) then out[#out + 1] = o end
    end
    return out, nil, #list
end

-- Which fields' values differ between the first and the last reading of the first object
function C.changed(res)
    local first, last = res.readings[1], res.readings[#res.readings]
    if not first or not last or #res.readings < 2 then return nil end
    local a, b = first.instances[1], last.instances[1]
    if not a or not b then return nil end
    local by = {}
    for _, f in ipairs(a.fields) do by[f.name] = f.value end
    local out = {}
    for _, f in ipairs(b.fields) do
        if f.value ~= nil and by[f.name] ~= nil and by[f.name] ~= f.value and #out < 80 then
            out[#out + 1] = { name = f.name, type = f.type, first = by[f.name], last = f.value }
        end
    end
    if a.position and b.position and a.position ~= b.position then out[#out + 1] = { name = "(game object position)", first = a.position, last = b.position } end
    return out
end

function C.save()
    local res = C.result
    if not res then return end
    res.changed_between_first_and_last = C.changed(res)
    res.written_at = os.time()
    local ok, where = CFG.save_json(FILES.MAP.car_probe[1], FILES.MAP.car_probe[2], res)
    C.n.writes = C.n.writes + 1
    if not ok then C.n.errors = C.n.errors + 1 C.last_error = tostring(where):sub(1, 100) end
end

-- A new probe: the type now (written at once), the readings as soon as an object exists
function C.start(why)
    C.n.type_reads = C.n.type_reads + 1
    C.readings, C.first_at, C.started_at = 0, nil, os.clock()
    C.result = { about = "re7mp 10.16 garage car probe: reads only. Send this file.", build = CFG.BUILD, why = why, types = {}, readings = {}, scene = nil }
    for i, tn in ipairs(C.TYPES) do
        local small = i > 1 -- (10.27) the car itself gets the big caps, the helper types the small ones
        local ok, d = pcall(C.type_dump, tn, small and C.SMALL_FIELDS or nil, small and C.SMALL_METHODS or nil)
        C.result.types[#C.result.types + 1] = ok and d or { type = tn, error = tostring(d):sub(1, 100) }
    end
    local t = C.result.types[1]
    C.status = (t and t.found) and "the type is read; waiting for a CarInGarage object in the scene (go to the garage)" or "the game has no type app.CarInGarage"
    C.save()
    say("garage car probe: " .. C.status)
end

function C.set_on(v)
    C.on = v == true
    if C.on then
        C.start("the box was ticked")
    else
        C.status = "off"
    end
end

function C.update(now)
    if not C.on or not C.result then return end
    if C.readings >= #C.READ_AT then return end
    local t1 = C.result.types and C.result.types[1]
    if t1 and t1.found == false then return end -- (no such type in this game: there is nothing to look for)
    if C.first_at and now - C.first_at < C.READ_AT[C.readings + 1] then return end
    if now - C.look_at < C.EVERY then return end
    C.look_at = now
    C.n.looks = C.n.looks + 1
    local list, err, total = C.instances(C.TYPES[1])
    if list == nil then
        C.status = "the scene would not say" .. (err and (": " .. err) or "")
        return
    end
    if #list == 0 then
        if C.first_at then C.status = "the object is gone (scene changed); " .. C.readings .. " of " .. #C.READ_AT .. " readings" end
        return
    end
    C.n.instances_seen = math.max(C.n.instances_seen, total or #list)
    C.first_at = C.first_at or now
    local reading = { at_s = math.floor((now - C.first_at) * 10) / 10, instances = {}, total = total or #list }
    for _, o in ipairs(list) do
        local ok, rec = pcall(C.read_instance, o)
        reading.instances[#reading.instances + 1] = ok and rec or { error = tostring(rec):sub(1, 100) }
        if not ok then C.n.errors = C.n.errors + 1 C.last_error = tostring(rec):sub(1, 100) end
    end
    C.result.readings[#C.result.readings + 1] = reading
    C.readings = C.readings + 1
    C.status = string.format("reading %d of %d done (%d object(s) of the type)", C.readings, #C.READ_AT, reading.total)
    C.save()
    say("garage car probe: " .. C.status)
    if C.readings >= #C.READ_AT then
        C.status = "done: " .. C.readings .. " readings written to re7mp/car_probe.json (tick the box or press Probe again to repeat)"
    end
end

function C.report()
    local t = C.result and C.result.types and C.result.types[1]
    return { about = "10.16: the garage car probe (reads only; off at every start; result in re7mp/car_probe.json)", on = C.on, status = C.status,
        type_found = t and t.found or nil, fields = t and t.fields_total or nil, methods = t and t.methods_total or nil,
        readings = C.readings, counts = C.n, last_error = C.last_error }
end
end -- do

----------------------------------------------------------------------------------------------
-- One health pool for both players (10.15: "both players boss health pool should be the same too, just to make sure they sync").
--
-- The HOST's game runs the enemies, so the host's health number IS the pool: every hit the joiner makes goes to the host (kind 9) and lowers it
-- there, and the host's snapshots carry it back (field 9; from 10.15 the enemy's maximum is field 14). What was missing:
--   1. The JOINER's own copy of the enemy (mode 3, "move my own enemies onto the host's") kept a health number of its own: a shot that landed on
--      it lowered that one, and nothing lowered it when the host's enemy lost health, or finished it when the host's died. Now, for every copy
--      that is being moved onto a host enemy, every EVERY seconds (CFG.pool.follow):
--        - mine is higher than the host's -> mine is set to the host's at once with setHealth(health, max), the call the other mod uses;
--        - mine is lower (my own shot landed a moment before the host's answer came back) -> the host's number is put back only after the
--          difference has stood for RAISE_AFTER seconds, so a hit that was just sent is not undone before the host has applied it;
--        - the two maxima differ (a different difficulty) -> the same SHARE of the pool, not the same number;
--        - never below 1: setHealth(0) marks an enemy dead without the death (the other mod: "sets isDead but the enemy keeps walking"). The host's
--          death is finished the way their kills are: one hit far above the health through the game's damage call, up to three times (finish).
--   2. A boss health bar at the top of the screen on BOTH screens (name, health / maximum, share), from the host's reading, so that the two
--      numbers can be seen to be the same. A boss is a family of CFG.pool.BOSS, or anything with a maximum of BOSS_MAX or more.
-- Nothing is written to an enemy that is not being moved (mode 3), and a copy is only finished within KILL_WINDOW seconds of the last time it was
-- put on the host's enemy, so another enemy of the same name in the joiner's own scene is left alone.
-- UNVERIFIED in the real game: setHealth(System.Single, System.Single) is the other mod's call (coop_enemies.lua on_ehp); the kill is theirs too.
----------------------------------------------------------------------------------------------
CFG.pool = {
    on = true,                -- JOINER: my copy of the host's enemy takes the host's health, and dies with it (remembered)
    bar = true,               -- both: the boss health bar (remembered)
    bosses = false,           -- (10.16) JOINER: also write the host's health into my copy of a BOSS (EXPERIMENTAL; off at every start, not remembered; see "THE QUIET CHECK")
    EVERY = 0.25,             -- the most often one copy's health is written
    TOL_FRAC = 0.004,         -- a difference under this share of the maximum (and under 2 points) is left alone
    RAISE_AFTER = 1.5,        -- a copy that is LOWER than the host's waits this long (seconds) for the host's answer before it is raised
    KILL_AFTER = 1.0,         -- the host's enemy must have been dead this long before mine is finished
    KILL_EVERY = 0.6, KILL_TRIES = 3, KILL_WINDOW = 20, KILL_NEAR = 8,
    MAX_EVERY = 2,            -- host: how often an enemy's maximum is read
    BOSS_MAX = 2000, BAR_RANGE = 70, BAR_MAX = 2,
    BOSS = { em2000 = true, em2100 = true, em3000 = true, em3100 = true, em3200 = true, em3300 = true, em3600 = true, em6000 = true,
        em8000 = true, em8100 = true, em8500 = true, em8900 = true },
    recs = {},                -- copy name -> { set_at, low_since, max, max_at, fails, dead_since, tries, tried_at, finished }
    n = { lowered = 0, raised = 0, same = 0, unread = 0, errors = 0, killed = 0, kill_tries = 0, kill_failed = 0, finish_far = 0, no_max = 0, scaled = 0,
        held_not_quiet = 0, boss_not_written = 0, boss_max_differs = 0, boss_raise_skipped = 0, boss_finish_skipped = 0, host_boss_hits_refused = 0 },
    said = 0, SAY_MAX = 40, say_at = {},
    last = "nothing to follow yet", shown = 0, rects = 0,
}

do
local P = CFG.pool

function P.rec(name)
    local r = P.recs[name]
    if not r then
        r = {}
        P.recs[name] = r
    end
    return r
end

function P.is_boss(name, max)
    local fam = CFG.ids and CFG.ids.family(name)
    if fam and P.BOSS[fam] then return true end
    return type(max) == "number" and max >= P.BOSS_MAX
end

-- HOST: an enemy's maximum health (its DamageController's get_maxHealth), read every MAX_EVERY seconds and kept on the record. nil when not known.
function P.max_of(e, now)
    now = now or os.clock()
    if e.max_at and now - e.max_at < P.MAX_EVERY then return e.max_val end
    e.max_at = now
    local dc = e.dmg_comp
    if not dc then return e.max_val end -- (the health search has not found one yet)
    local ok, v = pcall(dc.call, dc, "get_maxHealth")
    if ok and type(v) == "number" and v == v and v > 0 and v < 1e9 then
        e.max_val = v
    elseif not ok then
        e.max_val = nil
    end
    return e.max_val
end

-- JOINER: the maximum health of my own copy, read every 2 seconds.
function P.local_max(root, r, now)
    if r.max_at and now - r.max_at < 2 then return r.max end
    r.max_at = now
    local dc = root.dmg_comp
    if dc then
        local ok, v = pcall(dc.call, dc, "get_maxHealth")
        if ok and type(v) == "number" and v == v and v > 0 and v < 1e9 then r.max = v end
    end
    return r.max
end

local function note(name, text, now, force)
    P.last = text
    -- (force: the end of a story, a kill or a give-up, is always said; the repeating lines wait two seconds)
    if P.said < P.SAY_MAX and (force or now - (P.say_at[name] or -10) >= 2) then
        P.say_at[name] = now
        P.said = P.said + 1
        say("health pool: " .. text)
    end
end

-- Write a health number into my copy. Returns how (nil when nothing worked).
function P.write(root, target, lmax)
    local dc = root.dmg_comp
    if dc and lmax then
        local ok = pcall(function() return dc:call("setHealth(System.Single, System.Single)", target + 0.0, lmax + 0.0) end)
        if ok then return "setHealth" end
    end
    if dc then
        local ok = pcall(function() dc:call("getHealthInfo"):call("set_health", target + 0.0) end)
        if ok then return "set_health" end
    end
    if root.hp_comp and root.hp_field then
        local ok = pcall(function() root.hp_comp:set_field(root.hp_field, target + 0.0) end)
        if ok then return "health field" end
    end
    return nil
end

-- JOINER, called for every copy that was just put on the host's enemy `e` (an entry of enemy.remote, alive).
function P.follow(root, e, now)
    if not P.on or tracer.pool_suspect then return end
    local r = P.rec(root.name)
    r.dead_since, r.tries, r.finished = nil, 0, nil -- (alive on the host again: a later death starts afresh)
    if r.give_up then return end
    local host_hp = e.hp
    if type(host_hp) ~= "number" or host_hp < 0 then return end -- the host could not read it
    local boss = P.is_boss(root.name, e.max)
    -- (10.16) a boss is only written when the box says so (EXPERIMENTAL, off at every start): its health is run by the game's own script, and the 10.15 crash after the Mia fight
    -- came right after writes to it during a cutscene
    if boss and not P.bosses then
        P.n.boss_not_written = P.n.boss_not_written + 1
        r.host_hp, r.at = host_hp, now
        return
    end
    if r.set_at and now - r.set_at < P.EVERY then return end
    -- (10.16) nothing is written while the game loads, plays a cutscene or has just started an event
    local quiet = CFG.guard and CFG.guard.why(now)
    if quiet then
        P.n.held_not_quiet = P.n.held_not_quiet + 1
        r.held, r.held_why = now, quiet
        return
    end
    local mine = read_health(root)
    if type(mine) ~= "number" or mine < 0 then
        P.n.unread = P.n.unread + 1
        return
    end
    if enemy_is_dead(root) then return end -- (a dead copy is not brought back; the host's own death is finish()'s)
    local lmax = P.local_max(root, r, now)
    local target = host_hp
    if e.max and lmax and lmax > 0 and math.abs(e.max - lmax) > 0.01 * lmax then
        if boss then
            -- (10.16) two games that disagree on a BOSS's maximum are in different phases of the fight (the journal of the Mia crash: host 700 of 2000, mine 700: "700 -> 245"),
            -- not on two difficulties: nothing is written
            P.n.boss_max_differs = P.n.boss_max_differs + 1
            r.host_hp, r.mine, r.at, r.max_differs = host_hp, mine, now, string.format("host %.0f, mine %.0f", e.max, lmax)
            return
        end
        target = host_hp / e.max * lmax -- two difficulties: the same share of the pool
        P.n.scaled = P.n.scaled + 1
    elseif not e.max then
        P.n.no_max = P.n.no_max + 1
    end
    if target < 1 then target = 1 end -- 0 would mark it dead without the death
    if lmax and lmax > 0 and target > lmax then target = lmax end
    local tol = math.max(2, (lmax or mine) * P.TOL_FRAC)
    local diff = mine - target
    r.host_hp, r.mine, r.target, r.at = host_hp, mine, target, now
    if math.abs(diff) <= tol then
        r.low_since = nil
        P.n.same = P.n.same + 1
        return
    end
    local how
    if diff > 0 then
        how = "lowered"
    else
        if boss then -- (10.16) a boss's health is never raised (the journal: "raised 1 -> 350" on a boss the game's script had brought down)
            P.n.boss_raise_skipped = P.n.boss_raise_skipped + 1
            return
        end
        r.low_since = r.low_since or now
        if now - r.low_since < P.RAISE_AFTER then return end
        how = "raised"
    end
    r.set_at, r.low_since = now, nil
    pcall(tracer.crumb, "pool", string.format("%s %s %.0f -> %.0f", root.name, how, mine, target))
    local via = P.write(root, target, lmax)
    pcall(tracer.crumb, "clean", "health pool: written")
    if via then
        r.fails = 0
        P.n[how] = P.n[how] + 1
        note(root.name, string.format("%s %s %.0f -> %.0f (the host's %.0f%s) by %s", root.name, how, mine, target, host_hp, e.max and string.format(" of %.0f", e.max) or "", via), now)
    else
        P.n.errors = P.n.errors + 1
        r.fails = (r.fails or 0) + 1
        if r.fails >= 3 then
            r.give_up = true
            note(root.name, root.name .. ": nothing could write its health three times; left alone from now on", now, true)
        end
    end
end

-- JOINER, called for a copy whose host enemy is dead (and not parked): finish my copy, up to KILL_TRIES times.
function P.finish(root, e, now)
    if not P.on or tracer.pool_suspect then return end
    local d = enemy.driven[root.name]
    if not d and CFG.own and CFG.own.peer[root.name] then d = CFG.own.peer[root.name].d end -- (10.18: the host's body of an enemy the joiner runs)
    if not d or not d.moved_at or now - d.moved_at > P.KILL_WINDOW then return end -- not a copy I put on that enemy a moment ago
    local r = P.rec(root.name)
    if r.finished then return end
    -- (10.16) NEVER a damage call on a boss: the game's own script takes the boss away after its death (journal of the Mia crash: three hits of 3000 on the copy, then "Enemy model gone"
    -- and the game closed). My copy is left to the story, which the other game's progress (and the story sync) moves on.
    if P.is_boss(root.name, e.max) then
        r.finished = true
        P.n.boss_finish_skipped = P.n.boss_finish_skipped + 1
        note(root.name, root.name .. ": the host's boss is dead; mine is left to the game's own story (no damage call on a boss)", now, true)
        return
    end
    local quiet = CFG.guard and CFG.guard.why(now)
    if quiet then
        P.n.held_not_quiet = P.n.held_not_quiet + 1
        r.held, r.held_why = now, quiet
        return
    end
    r.dead_since = r.dead_since or now
    if now - r.dead_since < P.KILL_AFTER then return end
    if r.tried_at and now - r.tried_at < P.KILL_EVERY then return end
    -- the copy has to be where I put it (the host's enemy's last place), or it is some other enemy with the same name
    local okp, p = pcall(function() return root.xf:call("get_Position") end)
    if okp and p and d.hx and ((p.x - d.hx) ^ 2 + (p.z - d.hz) ^ 2) > P.KILL_NEAR ^ 2 then
        r.finished = true
        P.n.finish_far = P.n.finish_far + 1
        note(root.name, root.name .. ": the host's is dead but mine is not where I put it; left alone", now, true)
        return
    end
    if enemy_is_dead(root) then
        r.finished = true
        P.n.killed = P.n.killed + 1
        note(root.name, root.name .. ": dead on the host, and mine is dead too", now, true)
        return
    end
    if (r.tries or 0) >= P.KILL_TRIES then
        r.finished = true
        P.n.kill_failed = P.n.kill_failed + 1
        note(root.name, root.name .. ": the host's is dead, mine would not die after " .. P.KILL_TRIES .. " hits", now, true)
        return
    end
    r.tried_at, r.tries = now, (r.tries or 0) + 1
    local hp = read_health(root)
    local dmg = math.max((type(hp) == "number" and hp > 0 and hp or 0) * 4 + 1000, 3000)
    pcall(tracer.crumb, "pool", root.name .. " finish hit " .. dmg)
    local ok, okc, how = pcall(enemy.hit.apply, root, dmg)
    pcall(tracer.crumb, "clean", "health pool: hit done")
    P.n.kill_tries = P.n.kill_tries + 1
    note(root.name, string.format("%s: the host's is dead; hit mine for %d (try %d): %s", root.name, dmg, r.tries, ok and tostring(how) or tostring(okc)), now)
end

-- The boss rows to show: { name, hp, max, d2 }, the nearest first.
function P.rows(now)
    local rows = {}
    local lp = state.local_pos
    local function add(name, hp, max, x, z)
        if type(hp) ~= "number" or hp < 0 or not P.is_boss(name, max) then return end
        local d2 = (lp and x and z) and ((x - lp.x) ^ 2 + (z - lp.z) ^ 2) or 0
        if d2 > P.BAR_RANGE ^ 2 then return end
        rows[#rows + 1] = { name = name, hp = hp, max = max, d2 = d2 }
    end
    if state.role == "host" and not enemy.test_ghosts then
        if enemy.mode >= 2 and peer_present(now) then
            for _, r in ipairs(enemy.roots) do
                if r.last_flags == 1 and r.last_hp then add(r.name, r.last_hp, r.last_max, r.last_x, r.last_z) end -- (flags 1 = alive and not parked; a dead boss has no bar)
            end
        end
    elseif receiving_enemies() and now - enemy.remote_at <= 3 then
        for name, e in pairs(enemy.remote) do
            if e.alive and not e.inactive and e.rx then add(name, e.hp, e.max, e.rx, e.rz) end
        end
    end
    table.sort(rows, function(a, b) if a.d2 ~= b.d2 then return a.d2 < b.d2 end return a.name < b.name end)
    while #rows > P.BAR_MAX do table.remove(rows) end
    return rows
end

function P.draw(now)
    if not P.bar then
        P.shown = 0
        return
    end
    local rows = P.rows(now)
    P.shown = #rows
    if #rows == 0 then return end
    local sz = { x = 1920, y = 1080 }
    pcall(function() local d = imgui.get_display_size() if d and d.x and d.x > 100 then sz = d end end)
    local w, h = 360, 10
    local x, y = math.floor(sz.x * 0.5 - w * 0.5), 74
    for _, r in ipairs(rows) do
        local label = CFG.ids and CFG.ids.label(r.name) or enemy.base(r.name)
        local frac = (r.max and r.max > 0) and math.max(0, math.min(1, r.hp / r.max)) or nil
        local text = frac and string.format("%s   %d / %d   (%d%%)", label, math.floor(r.hp), math.floor(r.max), math.floor(frac * 100 + 0.5))
            or string.format("%s   %d", label, math.floor(r.hp))
        pcall(draw.text, text, x, y - 18, 0xFFFFFFFF)
        if frac then
            local okb = pcall(draw.filled_rect, x - 1, y - 1, w + 2, h + 2, 0xC0101010)
            if okb then
                pcall(draw.filled_rect, x, y, math.max(1, math.floor(w * frac)), h, 0xFF3030E0)
                P.rects = P.rects + 1
            end
        end
        y = y + 36
    end
end

function P.report()
    local copies = {}
    for name, r in pairs(P.recs) do
        copies[#copies + 1] = { name = name, host_hp = r.host_hp, mine = r.mine, target = r.target, max = r.max, finished = r.finished, tries = r.tries, gave_up = r.give_up or nil,
            held_for = r.held_why, maxima = r.max_differs }
    end
    table.sort(copies, function(a, b) return a.name < b.name end)
    while #copies > 12 do table.remove(copies) end
    return { about = "10.15: one health pool. The host's number is the pool (field 9 of the enemy snapshot, the maximum is field 14). My own copy of a host enemy (mode 3) takes it: lowered at once, raised after "
            .. P.RAISE_AFTER .. " s, never below 1, finished (one hit far above its health, up to " .. P.KILL_TRIES .. " times) when the host's is dead. The boss bar shows the host's reading on both screens. "
            .. "10.16: a BOSS is only written when 'bosses_written' is on (a box, off at every start); then never raised, never written while the maxima differ, never hit; and nothing is written while the game loads or plays a cutscene (health.guard).",
        follow_on = P.on, bar_on = P.bar, bosses_written = P.bosses, previous_session_ended_inside_it = tracer.pool_suspect == true,
        counts = P.n, last = P.last, bar_rows_now = P.shown, bar_rects_drawn = P.rects, copies = copies }
end

end -- do

----------------------------------------------------------------------------------------------
-- Damage dealt by the joiner . The joiner sees the host's enemies as red boxes, and its bullets pass through them.
-- JOINER: when a shot is fired (see "shot signal" below) a ray from the camera is tested against the red boxes (and against
--   walls, with the same physics test the stand-in uses); the nearest box hit sends message kind 9, "x|Em2000|30|x|y|z".
-- HOST: the message is applied to the host's real enemy through the game's own damage call, so the enemy flinches or dies as
--   if the host had shot it: app.DamageController.newFakeDamageInfo(damage, attacker, target) and addManualDamage(info)
--   (both are in the enemy scan), falling back to addHitDamage and then to lowering the health value directly. The host
--   answers "a|name|how|before|after" so the joiner's box shows the new health at once.
-- Shot signal: nobody knows which field of the gun means "a bullet was fired", so button "Learn the shot signal" watches the
--   whole-number fields of the weapon components (app.WeaponGun, app.PlayerGun) while you fire three shots, and keeps the
--   one that went down by exactly one three times. Nothing is hooked. Until it is learned, the test button (aim at a box
--   and press it) sends the same message, so the whole path can be tried without a shot signal.
----------------------------------------------------------------------------------------------
enemy.hit = {
    MSG = 9,
    on = true,        -- joiner: send hits
    accept = true,    -- host: apply hits from the other player
    -- 9.25: 210, not 30. The damage trace showed ONE real pistol shot doing 210 to Jack (DamageInfo.Damage 100, CalculatedDamage 210, of
    -- 10000 health); 30 was a guess and the owner found it far too small. The number is the damage the joiner MEANS; the host measures what a
    -- hit really does to the enemy's health and corrects for the game's own multipliers (HIT.ratio below).
    damage = 210,     -- joiner: damage per hit (sent with the hit; the host clamps it to 1..1500)
    MAX = 1500,       -- the most one hit may carry (9.25: was 500)
    -- 10.21: ON by default (your 22 Nov request: "since we can tell which gun does what damage we can sync the damage of each gun"). The table (CFG.wpn.DAMAGE) has been in the script since
    -- 9.31 and the joiner's hit already took the held gun's number from it, but the box was off, so every shot was the flat number above. The gun in hand is read once a second
    -- (CFG.wpn.held); a gun that is not in the table (or no gun known) still sends the flat number. Saved under hit_by_gun2: the old key held "false" for everybody.
    by_gun = true,    -- the damage follows the gun in hand (table damage x gun_scale) when it is known; otherwise the number above
    gun_sent = {},    -- 10.21: gun id -> { shots = n, damage = the last number sent }: what each gun really sent (the debug file's enemy_hits.sent_by_gun)
    flat_shots = 0, unknown_gun_shots = 0, last_gun = nil,
    gun_scale = 2.1,  -- 9.31: the one real pistol shot measured 210 for a 100-damage bullet (9.25)
    ratio = nil,      -- host: (health lost) / (damage handed to the game) for the last measured hits, any enemy; nil until one was measured
    ratios = {},      -- 9.26: the same, per enemy name. The 0.8 test: Em2000 lost exactly what it was handed (x1.00, 8 hits), Em8000 lost 77 of each 110 (x0.70, 2 hits)
    measured = 0, pending = {}, ratio_last = "-",
    sent = 0, acked = 0, received = 0, applied = 0, refused = 0, failed = 0,
    shots = 0, misses = 0, walled = 0, fire_at = -10,
    last = "No hits yet.", host_last = "-", marks = {}, recent = {}, history = {},
    signal = nil,     -- { type = "app.WeaponGun", field = "..." }: learned, saved in the settings
    objs = {}, objs_at = -10, prev = {}, poll_at = -10, signal_hits = 0,
    BOX = { hx = 0.32, hy = 0.95, hz = 0.22, pad = 0.12 }, -- the red box that is drawn, plus a little slack
    TYPES = { "app.WeaponGun", "app.PlayerGun" },
    learn = { on = false, status = "not learned yet", t0 = 0, shots = 0, events = {}, prev = {}, seen = {}, candidates = {} },
    -- the gun's own shot methods (app.PlayerGun.shoot / shootStart: they run once per shot, not every frame). The 0.7 file
    -- showed no whole-number FIELD of the weapon components goes down when you fire (the loaded bullets are a property of
    -- PlayerGun), so the shot is taken from the game calling these.
    hook = { on = true, tried = false, installed = {}, missing = {}, counts = {}, pending = nil, error = nil, used = 0,
        merged = 0, open_name = nil, open_t = 0, open = false, gap_min = nil, gap_max = nil, first_call = nil },
}

do
local HIT = enemy.hit

local function clampn(v, lo, hi) return math.max(lo, math.min(hi, v)) end

-- The nearest alive red box on the line o + t*d (t in 0..maxd), or nil. The box is the one draw_enemies draws.
function HIT.aim(o, d, maxd)
    local B = HIT.BOX
    local best
    for name, e in pairs(enemy.remote) do
        if e.x and e.alive and not e.inactive and e.rx then
            local q = unit_quat(e)
            local ax, ay, az = rotate(q, { 1, 0, 0 }), rotate(q, { 0, 1, 0 }), rotate(q, { 0, 0, 1 })
            local cx, cy, cz = e.rx + ay[1] * B.hy, e.ry + ay[2] * B.hy, e.rz + ay[3] * B.hy
            local ox, oy, oz = o.x - cx, o.y - cy, o.z - cz
            local lo = { ox * ax[1] + oy * ax[2] + oz * ax[3], ox * ay[1] + oy * ay[2] + oz * ay[3], ox * az[1] + oy * az[2] + oz * az[3] }
            local ld = { d[1] * ax[1] + d[2] * ax[2] + d[3] * ax[3], d[1] * ay[1] + d[2] * ay[2] + d[3] * ay[3], d[1] * az[1] + d[2] * az[2] + d[3] * az[3] }
            local h = { B.hx + B.pad, B.hy + B.pad, B.hz + B.pad }
            local tmin, tmax, hit = 0, maxd, true
            for i = 1, 3 do
                if math.abs(ld[i]) < 1e-9 then
                    if math.abs(lo[i]) > h[i] then hit = false break end
                else
                    local t1, t2 = (-h[i] - lo[i]) / ld[i], (h[i] - lo[i]) / ld[i]
                    if t1 > t2 then t1, t2 = t2, t1 end
                    if t1 > tmin then tmin = t1 end
                    if t2 < tmax then tmax = t2 end
                    if tmin > tmax then hit = false break end
                end
            end
            if hit and (not best or tmin < best.t) then
                best = { name = name, e = e, t = tmin, x = o.x + d[1] * tmin, y = o.y + d[2] * tmin, z = o.z + d[3] * tmin }
            end
        end
    end
    return best
end

-- true = solid level geometry between the camera and the point, false = clear, nil = cannot tell (no working physics test)
function HIT.wall_between(o, px, py, pz)
    local O = state.occ
    if not O or O.dead or not state.occlude then return nil end
    if not O.setup_done then O.setup() end
    if not O.ready or O.dead or not O.calibrated or #O.layers == 0 then return nil end
    local dx, dy, dz = px - o.x, py - o.y, pz - o.z
    local l = math.sqrt(dx * dx + dy * dy + dz * dz)
    if l < 0.8 then return false end
    dx, dy, dz = dx / l, dy / l, dz / l
    local any_ok = false
    for _, layer in ipairs(O.layers) do
        local r = O.cast(layer, o.x + dx * 0.3, o.y + dy * 0.3, o.z + dz * 0.3, px - dx * 0.1, py - dy * 0.1, pz - dz * 0.1)
        if r == true then return true end
        if r == false then any_ok = true end
    end
    if any_ok then return false end
    return nil
end

-- JOINER: one shot. why = "ammo" / "test button".
function HIT.fire(now, why)
    if not HIT.on then HIT.last = "hits are switched off" return end
    if not receiving_enemies() then HIT.last = "no enemies from the host to hit" return end
    if now - HIT.fire_at < 0.12 then return end
    HIT.fire_at = now
    HIT.shots = HIT.shots + 1
    local ok, pos, quat = pcall(get_local_pose)
    if not ok or not pos then HIT.last = "shot (" .. why .. "): no camera" return end
    local fx, fy, fz = forward_of(quat)
    local best = HIT.aim(pos, { fx, fy, fz }, 80)
    if not best then
        HIT.misses = HIT.misses + 1
        HIT.last = string.format("shot (%s): no red box in the line of fire", why)
        return
    end
    local walled = HIT.wall_between(pos, best.x, best.y, best.z)
    if walled == true then
        HIT.walled = HIT.walled + 1
        HIT.last = string.format("shot (%s): %s is behind a wall", why, best.name)
        return
    end
    local dmg = clampn(math.floor(HIT.damage + 0.5), 1, HIT.MAX)
    local from_gun
    if HIT.by_gun and CFG.wpn.held and CFG.wpn.held.damage then -- (9.31) the gun in hand decides
        dmg = clampn(math.floor(CFG.wpn.held.damage * HIT.gun_scale + 0.5), 1, HIT.MAX)
        from_gun = CFG.wpn.held.id
        local g = HIT.gun_sent[from_gun] or { shots = 0 } -- (10.21) what each gun really sent, for the debug file
        g.shots, g.damage = g.shots + 1, dmg
        HIT.gun_sent[from_gun] = g
    elseif HIT.by_gun then
        HIT.unknown_gun_shots = HIT.unknown_gun_shots + 1 -- (10.21) by gun is on but no gun with a known damage is in hand: the flat number goes (the debug file says how often)
    else
        HIT.flat_shots = HIT.flat_shots + 1
    end
    HIT.last_gun = from_gun or (CFG.wpn.held and CFG.wpn.held.id) or "no gun known"
    local e = best.e
    net_send(HIT.MSG, string.format("x|%s|%d|%.2f|%.2f|%.2f", best.name, dmg, e.x, e.y, e.z))
    HIT.sent = HIT.sent + 1
    HIT.marks[#HIT.marks + 1] = { x = best.x, y = best.y, z = best.z, text = "-" .. dmg, at = now }
    while #HIT.marks > 8 do table.remove(HIT.marks, 1) end
    HIT.last = string.format("shot (%s): hit %s at %.1f m, sent %d damage%s%s", why, best.name, best.t, dmg,
        walled == nil and " (walls not checked)" or "", from_gun and (" (" .. from_gun .. ")") or "")
end

-- HOST: apply damage to a real enemy. Returns ok, how, health before, health after.
function HIT.apply(e, dmg)
    local before = read_health(e)
    if enemy_is_dead(e) then return false, "already dead", before, before end
    local dc = e.dmg_comp
    local attacker = player_object()
    local how, why
    if dc then
        local ok, info = pcall(dc.call, dc, "newFakeDamageInfo", dmg + 0.0, attacker, e.go)
        if ok and info then
            local ok2, rec = pcall(dc.call, dc, "addManualDamage", info)
            if ok2 and rec ~= nil then
                how = "addManualDamage"
            else
                why = "addManualDamage: " .. tostring(ok2 and "returned nothing" or rec)
                local ok3, rec3 = pcall(dc.call, dc, "addHitDamage", info)
                if ok3 and rec3 ~= nil then how = "addHitDamage" else why = why .. "; addHitDamage: " .. tostring(ok3 and "returned nothing" or rec3) end
            end
        else
            why = "newFakeDamageInfo: " .. tostring(ok and "returned nothing" or info)
        end
    else
        why = "no DamageController found"
    end
    if not how then -- the game's damage call did not work: lower the number directly (no flinch, and death may not play)
        local target = math.max((before >= 0 and before or 0) - dmg, 0)
        local done = false
        if dc then
            done = pcall(function() dc:call("getHealthInfo"):call("set_health", target + 0.0) end)
            if done then how = "set_health" end
        end
        if not done and e.hp_comp and e.hp_field then
            done = pcall(function() e.hp_comp:set_field(e.hp_field, target + 0.0) end)
            if done then how = "health field" end
        end
        if not done then return false, why or "nothing worked", before, before end
    end
    return true, how, before, read_health(e)
end

-- HOST: a hit arrived from the other player.
function HIT.receive_hit(rest, now)
    HIT.received = HIT.received + 1
    local name, dmg, x, y, z = rest:match("^([%w_]+)|(%d+)|([%-%d%.]+)|([%-%d%.]+)|([%-%d%.]+)$")
    if not name then
        HIT.refused = HIT.refused + 1
        HIT.host_last = "a damaged hit message was ignored"
        return
    end
    local function refuse(reason)
        HIT.refused = HIT.refused + 1
        HIT.host_last = string.format("%s: refused (%s)", name, reason)
        net_send(HIT.MSG, string.format("a|%s|refused|-1|-1", name))
    end
    if state.role ~= "host" then return refuse("I am not the host") end
    if not HIT.accept then return refuse("hits from the other player are switched off") end
    if CFG.own and CFG.own.peer[name] then return refuse("the joiner runs it (the hand-over): their own hits land in their game") end -- (10.18)
    -- (10.16) no damage call on a boss while a cutscene plays or the game loads (the other mod's v0.36: scripted damage on Em2000 during c01e04_00, then a crash 18 s later)
    if CFG.pool and CFG.pool.is_boss(name) then
        local quiet = CFG.guard and CFG.guard.why(now)
        if quiet then
            CFG.pool.n.host_boss_hits_refused = CFG.pool.n.host_boss_hits_refused + 1
            return refuse("not now: " .. quiet)
        end
    end
    for i = #HIT.recent, 1, -1 do
        if now - HIT.recent[i] > 1 then table.remove(HIT.recent, i) end
    end
    if #HIT.recent >= 10 then return refuse("more than 10 hits a second") end
    HIT.recent[#HIT.recent + 1] = now
    dmg = clampn(tonumber(dmg) or 1, 1, HIT.MAX)
    if #enemy.roots == 0 then
        local okr, roots = pcall(find_enemy_roots)
        if okr then enemy.roots = roots end
    end
    local px, py, pz = tonumber(x), tonumber(y), tonumber(z)
    local pick, pick_d
    for _, e in ipairs(enemy.roots) do
        if e.name == name then
            local okp, p = pcall(function() return e.xf:call("get_Position") end)
            local d = okp and p and ((p.x - px) ^ 2 + (p.y - py) ^ 2 + (p.z - pz) ^ 2) or 1e9
            if not pick or d < pick_d then pick, pick_d = e, d end
        end
    end
    if not pick then return refuse("no enemy called " .. name .. " here") end
    if (pick.last_flags or 1) >= 2 then return refuse(name .. " is not a live enemy (" .. flags_reason(pick.last_flags) .. ")") end
    -- 9.25: hand the game the number that should give the damage the joiner meant, given what earlier hits really did
    local meant, handed = dmg, dmg
    local rr = HIT.ratios[name] or HIT.ratio -- this enemy's own multiplier when it has been measured, else the last one measured on any enemy
    if rr and rr > 0 then handed = clampn(math.floor(dmg / rr + 0.5), 1, 3 * HIT.MAX) end
    local ok, okc, how, before, after = pcall(HIT.apply, pick, handed)
    if not ok then okc, how, before, after = false, tostring(okc), -1, -1 end
    if okc then
        HIT.applied = HIT.applied + 1
        HIT.host_last = string.format("%s: %d damage meant, %d handed to the game, by %s, health %s -> %s", name, meant, handed, how, tostring(before), tostring(after))
        if (how == "addManualDamage" or how == "addHitDamage") and type(before) == "number" and before > 0 then
            -- the game may apply the damage a frame later: measure again shortly (HIT.settle)
            HIT.pending[#HIT.pending + 1] = { e = pick, name = name, before = before, handed = handed, at = now }
            while #HIT.pending > 4 do table.remove(HIT.pending, 1) end
        end
    else
        HIT.failed = HIT.failed + 1
        HIT.host_last = string.format("%s: could not damage (%s)", name, tostring(how))
    end
    HIT.history[#HIT.history + 1] = { name = name, damage = meant, handed = handed, ok = okc, how = how, before = before, after = after }
    while #HIT.history > 12 do table.remove(HIT.history, 1) end
    say("enemy hit: " .. HIT.host_last)
    net_send(HIT.MSG, string.format("a|%s|%s|%d|%d", name, okc and how or "failed", math.floor(before or -1), math.floor(after or -1)))
end

-- HOST (9.25): a moment after a hit went through the game's own damage call, read the enemy's health again. The game runs a shot through
-- its multipliers (parts, difficulty, weapon), so what the health lost is not the number handed over. HIT.ratio = lost / handed
-- (averaged over the measurements), and the next hit hands over (meant / ratio). An enemy that died, or lost nothing, or lost far more or
-- less than any multiplier would explain (the host shot it too, it healed) is not used.
function HIT.settle(now)
    local keep = {}
    for _, p in ipairs(HIT.pending) do
        if now - p.at >= 0.4 then
            local after = p.e and read_health(p.e) or -1
            local lost = type(after) == "number" and after >= 0 and (p.before - after) or -1
            if after > 0 and lost >= 1 and lost >= 0.1 * p.handed and lost <= 10 * p.handed then
                local r = lost / p.handed
                HIT.ratio = HIT.ratio and (0.5 * HIT.ratio + 0.5 * r) or r
                HIT.ratio = clampn(HIT.ratio, 0.05, 20)
                local mine = p.name and HIT.ratios[p.name]
                local use = HIT.ratio
                if p.name then -- (9.26) the enemy's own number: not blended with other enemies'
                    mine = mine and (0.5 * mine + 0.5 * r) or r
                    mine = clampn(mine, 0.05, 20)
                    HIT.ratios[p.name] = mine
                    use = mine
                end
                HIT.measured = HIT.measured + 1
                HIT.ratio_last = string.format("%shanded %d, health lost %d (x%.2f); using x%.2f", p.name and (p.name .. ": ") or "", p.handed, math.floor(lost + 0.5), r, use)
                say("enemy hit: " .. HIT.ratio_last)
            else
                HIT.ratio_last = string.format("handed %d, could not tell what it did (health %s -> %s)", p.handed, tostring(p.before), tostring(after))
            end
        elseif now - p.at < 5 then
            keep[#keep + 1] = p
        end
    end
    HIT.pending = keep
end

-- JOINER: the host's answer.
function HIT.receive_ack(rest)
    local name, how, before, after = rest:match("^([%w_]+)|([^|]*)|([%-%d]+)|([%-%d]+)$")
    if not name then return end
    HIT.acked = HIT.acked + 1
    HIT.host_last = string.format("host: %s %s (health %s -> %s)", name, how, before, after)
    local e = enemy.remote[name]
    local hp = tonumber(after)
    if e and hp and hp >= 0 and how ~= "refused" and how ~= "failed" then
        e.hp, e.ack_hp, e.ack_until = hp, hp, os.clock() + 0.6
    end
end

net_on(HIT.MSG, function(payload)
    local kind, rest = tostring(payload):match("^(%a)|(.*)$")
    if kind == "x" then HIT.receive_hit(rest, os.clock()) elseif kind == "a" then HIT.receive_ack(rest) end
end)

-- ---- the shot signal ----
-- The whole-number fields of one component: { field name -> value }. (Counters of bullets are whole numbers.)
function HIT.number_fields(obj)
    local out, n = {}, 0
    pcall(function()
        local t = obj:get_type_definition()
        while t and n < 120 do
            local tn = t:get_full_name()
            if tn:find("^System%.") or tn:find("^via%.Component") or tn:find("^via%.Behavior") or tn:find("^via%.Object") then break end
            for _, f in ipairs(t:get_fields() or {}) do
                if not f:is_static() then
                    local nm = f:get_name()
                    local okv, v = pcall(function() return obj:get_field(nm) end)
                    if okv and type(v) == "number" and v == math.floor(v) and math.abs(v) < 1e6 then
                        out[nm] = v
                        n = n + 1
                    end
                end
            end
            t = t:get_parent_type()
        end
    end)
    return out
end

-- The weapon components in the scene: { { key, obj, type } }, looked up at most once a second.
function HIT.weapons(now)
    if now - HIT.objs_at < 1 then return HIT.objs end
    HIT.objs_at = now
    local list = {}
    local scene = scene_object()
    if scene then
        for _, tn in ipairs(HIT.TYPES) do
            local ok, arr = pcall(function() return scene:call("findComponents(System.Type)", sdk.typeof(tn)) end)
            if ok and arr then
                local oke, elems = pcall(function() return arr:get_elements() end)
                if oke then
                    for i, c in ipairs(elems) do
                        if i > 12 then break end
                        local oka, addr = pcall(c.get_address, c)
                        list[#list + 1] = { key = tn .. "@" .. (oka and tostring(addr) or tostring(i)), obj = c, type = tn }
                    end
                end
            end
        end
    end
    HIT.objs = list
    return list
end

-- One shot of the handgun runs BOTH calls (shootStart, then shoot a moment later, in another frame), and each one was a shot:
-- two hits per bullet (your note 2). The first call of a shot opens it; the OTHER method within 0.45 s is the same shot and is only
-- written down (how far apart, which came first), so the next file shows the real order and gap. The same method twice is two shots.
function HIT.shot_call(name)
    local K = HIT.hook
    K.counts[name] = (K.counts[name] or 0) + 1
    state.gun_shot_at = os.clock() -- (9.28) the "I just fired" pose bit, whatever the hit sync does with the shot
    if not K.on then return end
    local t = os.clock()
    if K.open and K.open_name ~= name and t - K.open_t < 0.45 then
        K.open = false
        K.merged = K.merged + 1
        local gap = t - K.open_t
        K.gap_min = K.gap_min and math.min(K.gap_min, gap) or gap
        K.gap_max = K.gap_max and math.max(K.gap_max, gap) or gap
        K.first_call = K.first_call or K.open_name
        return
    end
    K.pending = t
    K.open, K.open_name, K.open_t = true, name, t
end

function HIT.install_hook()
    local K = HIT.hook
    if K.tried or not K.on then return end
    K.tried = true
    local td = sdk.find_type_definition("app.PlayerGun")
    if not td then
        K.error = "app.PlayerGun not found"
        return
    end
    local CALL_ORIGINAL = sdk.PreHookResult and sdk.PreHookResult.CALL_ORIGINAL
    for _, name in ipairs({ "shoot", "shootStart" }) do
        local okm, m = pcall(function() return td:get_method(name) end)
        if okm and m then
            tracer.crumb("hooking", "app.PlayerGun." .. name)
            local ok = pcall(sdk.hook, m, function(args)
                HIT.shot_call(name)
                return CALL_ORIGINAL
            end, function(retval) return retval end)
            tracer.crumb("clean", "hook installed: app.PlayerGun." .. name)
            if ok then K.installed[#K.installed + 1] = name else K.missing[#K.missing + 1] = name end
        else
            K.missing[#K.missing + 1] = name
        end
    end
    say("shot signal: hooked the gun's " .. (#K.installed > 0 and table.concat(K.installed, ", ") or "nothing") .. (#K.missing > 0 and (" (not found: " .. table.concat(K.missing, ", ") .. ")") or ""))
end

function HIT.learn_start(now)
    local L = HIT.learn
    L.on, L.t0, L.shots, L.events, L.prev, L.candidates = true, now, 0, {}, {}, {}
    L.hook_shots = 0
    HIT.install_hook()
    L.status = "fire three shots now (15 s)"
    HIT.objs_at = -10
    say("shot signal: watching the weapon components; fire three shots")
end

function HIT.learn_finish(now, why)
    local L = HIT.learn
    L.on = false
    local best, best_n, best_score
    local keys = {}
    for tf in pairs(L.events) do keys[#keys + 1] = tf end
    table.sort(keys) -- the same answer every time when two fields tie
    for _, tf in ipairs(keys) do
        local ev = L.events[tf]
        local n = #ev
        L.candidates[#L.candidates + 1] = { field = tf, drops_of_one = n }
        if n >= 3 and n <= 6 then
            local nm = tf:lower()
            local score = -math.abs(n - 3) * 10 + ((nm:find("bullet") or nm:find("ammo") or nm:find("remain") or nm:find("mag") or nm:find("load") or nm:find("num") or nm:find("count")) and 1 or 0)
            if not best_score or score > best_score then best, best_n, best_score = tf, n, score end
        end
    end
    table.sort(L.candidates, function(a, b) return a.drops_of_one > b.drops_of_one end)
    while #L.candidates > 15 do table.remove(L.candidates) end
    if best then
        local tn, field = best:match("^(.-)|(.*)$")
        HIT.signal = { type = tn, field = field }
        L.status = string.format("learned: %s.%s went down by one %d times", tn, field, best_n)
        HIT.prev = {}
    elseif (L.hook_shots or 0) >= 1 then
        L.status = string.format("the gun's own shoot call ran %d times while you fired: shots are taken from it (no field needed)", L.hook_shots)
    else
        L.status = (why or "finished") .. ": no field went down by exactly one 3 to 6 times and the gun's shoot call did not run (" .. #L.candidates .. " candidates, see the debug file)"
    end
    say("shot signal: " .. L.status)
end

-- every frame (joiner): the learner, and the learned signal
function HIT.update(now)
    if #HIT.pending > 0 then pcall(HIT.settle, now) end
    local L = HIT.learn
    if L.on then
        if now - L.t0 > 15 then
            HIT.learn_finish(now, "time is up")
        else
            if HIT.hook.pending then
                HIT.hook.pending = nil
                L.hook_shots = (L.hook_shots or 0) + 1
                if L.hook_shots >= 3 and now - L.t0 > 1 then L.done_at = L.done_at or (now + 1.0) end
            end
            for _, w in ipairs(HIT.weapons(now)) do
                local nums = HIT.number_fields(w.obj)
                local prev = L.prev[w.key]
                if prev then
                    for fname, v in pairs(nums) do
                        local pv = prev[fname]
                        if pv and pv - v == 1 then
                            local tf = w.type .. "|" .. fname
                            local ev = L.events[tf] or {}
                            if #ev == 0 or now - ev[#ev] > 0.1 then ev[#ev + 1] = now end
                            L.events[tf] = ev
                        end
                    end
                end
                L.prev[w.key] = nums
            end
            local most = L.hook_shots or 0
            for _, ev in pairs(L.events) do if #ev > most then most = #ev end end
            L.shots = most
            if most >= 3 and now - L.t0 > 1 then
                -- three drops seen: wait a moment for a fourth (a miscounted field would keep counting), then decide
                L.done_at = L.done_at or (now + 1.5)
                if now >= L.done_at then L.done_at = nil HIT.learn_finish(now, "three shots seen") end
            end
        end
        return
    end
    -- a shot the game itself reported (the hook only notes the time; the ray test runs here, in the frame)
    if HIT.hook.on and not HIT.hook.tried and ((HIT.on and receiving_enemies()) or CFG.ff.on) then HIT.install_hook() end
    local pend = HIT.hook.pending
    if pend then
        HIT.hook.pending = nil
        if CFG.ff.on then pcall(CFG.ff.fire, now) end -- (9.31: friendly fire, either role)
        if HIT.on and receiving_enemies() and not (state.role == "host" and not enemy.test_ghosts) then
            HIT.hook.used = HIT.hook.used + 1
            HIT.fire(now, "the gun's shoot call")
        end
    end
    local sig = HIT.signal
    if not sig or not HIT.on or not receiving_enemies() or state.role == "host" and not enemy.test_ghosts then return end
    if now - HIT.poll_at < 0.04 then return end
    HIT.poll_at = now
    for _, w in ipairs(HIT.weapons(now)) do
        if w.type == sig.type then
            local ok, v = pcall(function() return w.obj:get_field(sig.field) end)
            if ok and type(v) == "number" then
                local pv = HIT.prev[w.key]
                HIT.prev[w.key] = v
                if pv and pv > v and pv - v <= 3 then
                    HIT.signal_hits = HIT.signal_hits + 1
                    HIT.fire(now, "ammo")
                end
            end
        end
    end
end

-- floating damage numbers
function HIT.draw(now)
    for i = #HIT.marks, 1, -1 do
        local m = HIT.marks[i]
        local age = now - m.at
        if age > 0.9 then
            table.remove(HIT.marks, i)
        else
            local sp = project({ m.x, m.y + age * 0.6, m.z })
            if sp then draw.text(m.text, sp.x - 10, sp.y - 6, 0xFF40FFFF) end
        end
    end
end

function HIT.report()
    local L = HIT.learn
    local first = HIT.objs[1]
    local nums = {}
    if first then
        for k in pairs(HIT.number_fields(first.obj)) do nums[#nums + 1] = k end
        table.sort(nums)
        while #nums > 40 do table.remove(nums) end
    end
    local kinds = {}
    for _, w in ipairs(HIT.objs) do kinds[w.type] = (kinds[w.type] or 0) + 1 end
    local by_gun = {}
    for id, g in pairs(HIT.gun_sent) do by_gun[#by_gun + 1] = { gun = id, shots = g.shots, damage_sent = g.damage } end
    table.sort(by_gun, function(a, b) return a.gun < b.gun end)
    return { joiner_hits_on = HIT.on, host_accepts = HIT.accept, damage_per_hit = HIT.damage,
        by_gun = { on = HIT.by_gun, scale = HIT.gun_scale, sent_by_gun = by_gun, flat_number_shots = HIT.flat_shots, by_gun_on_but_no_known_gun_shots = HIT.unknown_gun_shots, last_gun = HIT.last_gun,
            note = "10.21: with 'by gun' on, a shot sends (table damage of the gun in hand) x scale; a gun not in the table (or none known) sends the flat damage_per_hit. The host divides by what it measured the enemy really loses per point handed (effective_ratio, ratio_by_enemy)." },
        effective_ratio = HIT.ratio and math.floor(HIT.ratio * 1000 + 0.5) / 1000 or nil, ratio_measured = HIT.measured, ratio_last = HIT.ratio_last,
        ratio_by_enemy = (function() local t = {} for k, v in pairs(HIT.ratios) do t[k] = math.floor(v * 1000 + 0.5) / 1000 end return next(t) and t or nil end)(),
        shots_tested = HIT.shots, no_box_in_line = HIT.misses, behind_wall = HIT.walled, sent = HIT.sent, answered = HIT.acked,
        received = HIT.received, applied = HIT.applied, refused = HIT.refused, failed = HIT.failed,
        last = HIT.last, host_last = HIT.host_last, host_history = HIT.history,
        signal = HIT.signal, signal_shots = HIT.signal_hits,
        gun_hook = { on = HIT.hook.on, installed = HIT.hook.installed, not_found = HIT.hook.missing, calls = HIT.hook.counts,
            shots_used = HIT.hook.used, error = HIT.hook.error,
            second_call_of_a_shot_merged = HIT.hook.merged, first_call_of_a_shot = HIT.hook.first_call,
            gap_between_the_two_calls_s = HIT.hook.gap_min and { min = HIT.hook.gap_min, max = HIT.hook.gap_max } or nil },
        learner = { status = L.status, candidates = L.candidates },
        weapon_components = kinds, first_weapon_number_fields = nums }
end
end -- do

----------------------------------------------------------------------------------------------
-- (10.21) KILLS BOTH WAYS (CFG.kill, message kind 21). Your 22 Nov request: "killing one persons molded should kill both persons regardless of host or joiner status".
-- What already worked: the HOST's enemy dies -> its snapshot says dead -> the joiner's copy is finished (CFG.pool.finish for an ordinary enemy, CFG.molded.finish for a Molded).
-- What was missing: the JOINER's own copy dies FIRST. With mode 3 / Molded copies a joiner's shot lands on a real body in the joiner's game, which takes the game's real damage (a
-- headshot ...), while the host only ever got the table number (HIT.fire). The copy can be dead while the host's still has health, and nothing told the host: CFG.pool.follow
-- returns early for a dead copy ("a dead copy is not brought back"), and a dead Molded copy was still moved and given the host's clips.
-- JOINER (every 0.25 s): for each real body of mine that is the copy of a host enemy (an enemy mode 3 moved onto the host's, or a Molded copy): seen ALIVE first, then dead for
--   DEAD_FOR seconds while the host's snapshot still says alive -> "k|name|x|z" to the host (again every RESEND_S until answered, MAX_SENDS times). Never a boss (Mia, Jack: their
--   deaths belong to the game's script, and a kill written during a cutscene is what crashed the 10.15 build); never while the quiet check says loading / cutscene. A body that
--   is first seen DEAD (an older save, another body) is not a kill of mine and asks nothing.
-- HOST: only as host, with the hit box ticked; refuses a boss, an enemy the joiner runs (the hand-over has its own messages), a moment that is not quiet, more than HOST_PER_S a
--   second, no such enemy, a parked one; an already dead one is answered "ok, already dead"; otherwise the finishing blow CFG.molded.finish and CFG.pool.finish give a copy: one hit
--   far above the health through the game's own damage call, up to 3 times. Answers "a|name|ok|how" or "a|name|no|why". The host's snapshot then says dead, which is what ends the
--   resending (and finishes whatever is left of the joiner's copy, nothing: it is dead).
-- UNVERIFIED in the real game. A session that ended inside a kill switches this off (stage "kill").
----------------------------------------------------------------------------------------------
CFG.kill = {
    MSG = 21,
    on = true,               -- both players: the joiner asks, the host accepts (remembered as kill_sync)
    SCAN_EVERY = 0.25, DEAD_FOR = 0.7, RESEND_S = 2.5, MAX_SENDS = 4, HOST_PER_S = 6, TRIES = 3,
    recs = {},               -- joiner: copy name -> { addr, alive_seen, born_dead, dead_since, sends, sent_at, answer, why, final }
    scan_at = -100, recent = {}, history = {},
    n = { asked = 0, resent = 0, ok = 0, refused = 0, gave_up = 0, bosses_skipped = 0, born_dead = 0, not_quiet = 0, host_asked = 0, host_killed = 0, host_already_dead = 0,
        host_refused = 0, host_failed = 0, errors = 0 },
    last = "nothing yet",
}

do
local K = CFG.kill

local function note(text)
    K.last = text
    K.history[#K.history + 1] = string.format("%.0f s: %s", os.clock(), text)
    while #K.history > 14 do table.remove(K.history, 1) end
    say("kill sync: " .. text)
end

-- Is the game's own answer "dead"? true / false, nil when it could not be asked. read_health first: it finds the Status and DamageController the death question needs (once per record).
local function dead_of(rec)
    pcall(read_health, rec)
    local ok, dead = pcall(enemy_is_dead, rec)
    if not ok then return nil end
    return dead == true
end

-- JOINER: the bodies of this game that are copies of a host enemy: { name, rec, c = the Molded copy or nil }
function K.candidates()
    local out = {}
    for _, root in ipairs(enemy.local_roots or {}) do
        if enemy.driven[root.name] and not root.spawn then out[#out + 1] = { name = root.name, rec = root } end
    end
    local M = CFG.molded
    for name, c in pairs(M and M.copies or {}) do
        c.krec = c.krec or c.rec or { name = name, go = c.go, xf = c.xf, family = enemy.base(name) }
        out[#out + 1] = { name = name, rec = c.krec, c = c }
    end
    return out
end

-- JOINER: one body.
function K.look(cand, now)
    local name, rec = cand.name, cand.rec
    local r = K.recs[name]
    local addr = rec.addr or (cand.c and cand.c.addr)
    if r and addr and r.addr and r.addr ~= addr then r = nil end -- another body under that name: its history starts again
    if not r then
        r = { addr = addr, sends = 0 }
        K.recs[name] = r
    end
    local dead = dead_of(rec)
    if dead == nil then return end
    if not dead then
        r.alive_seen, r.dead_since, r.born_dead = true, nil, nil
        if cand.c then cand.c.dead_here = nil end
        return
    end
    if not r.alive_seen then -- dead the first time it was looked at: not a kill of mine (an older save, a body of another time)
        if not r.born_dead then
            r.born_dead = true
            K.n.born_dead = K.n.born_dead + 1
        end
        return
    end
    if cand.c then cand.c.dead_here = true end -- (CFG.molded.update no longer moves it or plays the host's clips on it)
    r.dead_since = r.dead_since or now
    local e = enemy.remote[name]
    if not e or not e.alive or e.inactive then
        r.final = "the host's is dead too"
        return
    end
    if r.final or r.answer == "ok" then return end
    if now - r.dead_since < K.DEAD_FOR then return end
    if CFG.pool.is_boss(name, e.max) then
        r.final = "a boss: the game's script decides"
        K.n.bosses_skipped = K.n.bosses_skipped + 1
        note(string.format("%s died here, but it is a boss: nothing is asked of the host", name))
        return
    end
    if r.sends >= K.MAX_SENDS then
        r.final = string.format("asked %d times, no answer that helped", r.sends)
        K.n.gave_up = K.n.gave_up + 1
        note(string.format("%s: %s", name, r.final))
        return
    end
    if r.sent_at and now - r.sent_at < K.RESEND_S then return end
    local quiet = CFG.guard and CFG.guard.why(now)
    if quiet then
        K.n.not_quiet = K.n.not_quiet + 1
        r.held = quiet
        return
    end
    r.sent_at, r.sends, r.held = now, r.sends + 1, nil
    net_send(K.MSG, string.format("k|%s|%.1f|%.1f", name, e.x or 0, e.z or 0))
    if r.sends == 1 then K.n.asked = K.n.asked + 1 else K.n.resent = K.n.resent + 1 end
    note(string.format("%s died here while the host's is alive (%s of health): asked the host to kill it (%d)", name, e.hp and e.hp >= 0 and tostring(math.floor(e.hp)) or "?", r.sends))
end

-- JOINER, every frame (called by enemy_update): every SCAN_EVERY seconds.
function K.update(now)
    if not K.on or tracer.kill_suspect then return end
    if now - K.scan_at < K.SCAN_EVERY then return end
    K.scan_at = now
    local seen = {}
    for _, cand in ipairs(K.candidates()) do
        seen[cand.name] = true
        local ok, err = pcall(K.look, cand, now)
        if not ok then
            K.n.errors = K.n.errors + 1
            K.last_error = tostring(err):sub(1, 100)
        end
    end
    for name in pairs(K.recs) do
        if not seen[name] then K.recs[name] = nil end
    end
end

-- JOINER: the host's answer: "a|name|ok|how" or "a|name|no|why"
function K.on_answer(rest)
    local name, verdict, why = rest:match("^a|([%w_]+)|(%a+)|?(.*)$")
    if not name then return end
    local r = K.recs[name]
    if verdict == "ok" then
        K.n.ok = K.n.ok + 1
        if r then r.answer, r.why = "ok", why end
        note(string.format("%s: the host killed its own (%s)", name, why ~= "" and why or "ok"))
    else
        K.n.refused = K.n.refused + 1
        if r then
            r.why = why
            if why:find("^not now") then r.answer = nil else r.final = "the host refused: " .. why end -- "not now" (a cutscene there) is asked again after RESEND_S
        end
        note(string.format("%s: the host did not kill it (%s)", name, why))
    end
end

-- HOST: the finishing blow, up to TRIES times. Returns dead, how, tries.
function K.host_kill(pick)
    pcall(tracer.crumb, "kill", "killing " .. pick.name .. " for the joiner")
    local dead, how, tries = false, nil, 0
    for _ = 1, K.TRIES do
        tries = tries + 1
        local hp = read_health(pick)
        local dmg = math.max((type(hp) == "number" and hp > 0 and hp or 0) * 4 + 1000, 3000)
        local ok, okc, h = pcall(enemy.hit.apply, pick, dmg)
        if ok and okc then how = h end
        local okd, d = pcall(enemy_is_dead, pick)
        if okd and d then dead = true break end
    end
    pcall(tracer.crumb, "clean", "kill done")
    return dead, how, tries
end

-- HOST: "k|name|x|z" from the joiner.
function K.on_ask(rest, now)
    K.n.host_asked = K.n.host_asked + 1
    local name, x, z = rest:match("^k|([%w_]+)|([%-%d%.]+)|([%-%d%.]+)$")
    if not name then
        K.n.host_refused = K.n.host_refused + 1
        return
    end
    local function refuse(why)
        K.n.host_refused = K.n.host_refused + 1
        K.last = name .. ": not killed for the joiner (" .. why .. ")"
        net_send(K.MSG, string.format("a|%s|no|%s", name, why))
    end
    if state.role ~= "host" then return refuse("I am not the host") end
    if not K.on then return refuse("kill sharing is off here") end
    if tracer.kill_suspect then return refuse("the last session ended inside a kill") end
    if not enemy.hit.accept then return refuse("hits from the other player are switched off") end
    if CFG.own and CFG.own.peer[name] then return refuse("the joiner runs it (the hand-over)") end
    for i = #K.recent, 1, -1 do
        if now - K.recent[i] > 1 then table.remove(K.recent, i) end
    end
    if #K.recent >= K.HOST_PER_S then return refuse("more than " .. K.HOST_PER_S .. " a second") end
    K.recent[#K.recent + 1] = now
    if #enemy.roots == 0 then
        local okr, roots = pcall(find_enemy_roots)
        if okr then enemy.roots = roots end
    end
    local px, pz = tonumber(x), tonumber(z)
    local pick, pick_d
    for _, e in ipairs(enemy.roots) do
        if e.name == name then
            local okp, p = pcall(function() return e.xf:call("get_Position") end)
            local d = okp and p and ((p.x - px) ^ 2 + (p.z - pz) ^ 2) or 1e9
            if not pick or d < pick_d then pick, pick_d = e, d end
        end
    end
    if not pick then return refuse("no enemy called " .. name .. " here") end
    if CFG.pool.is_boss(name, pick.last_max) then return refuse("a boss: the game's script decides") end
    if (pick.last_flags or 1) >= 2 then return refuse(name .. " is not a live enemy (" .. flags_reason(pick.last_flags) .. ")") end
    local quiet = CFG.guard and CFG.guard.why(now)
    if quiet then return refuse("not now: " .. quiet) end
    local okd, already = pcall(enemy_is_dead, pick)
    if okd and already then
        K.n.host_already_dead = K.n.host_already_dead + 1
        K.last = name .. ": already dead here"
        net_send(K.MSG, string.format("a|%s|ok|already dead", name))
        return
    end
    local dead, how, tries = K.host_kill(pick)
    if dead then
        K.n.host_killed = K.n.host_killed + 1
        K.last = string.format("%s: killed for the joiner (%s, %d hit%s)", name, tostring(how), tries, tries == 1 and "" or "s")
        net_send(K.MSG, string.format("a|%s|ok|%s", name, tostring(how)))
    else
        K.n.host_failed = K.n.host_failed + 1
        K.last = string.format("%s: could not be killed for the joiner (%d hits)", name, tries)
        net_send(K.MSG, string.format("a|%s|no|would not die after %d hits", name, tries))
    end
    say("kill sync: " .. K.last)
end

net_on(K.MSG, function(payload)
    local now = os.clock()
    if payload:sub(1, 2) == "k|" then
        local ok, err = pcall(K.on_ask, payload, now)
        if not ok then K.n.errors, K.last_error = K.n.errors + 1, tostring(err):sub(1, 100) end
    elseif payload:sub(1, 2) == "a|" then
        pcall(K.on_answer, payload)
    end
end)

function K.report()
    local rows = {}
    for name, r in pairs(K.recs) do
        rows[#rows + 1] = { copy = name, seen_alive = r.alive_seen == true, dead_for_s = r.dead_since and math.floor((os.clock() - r.dead_since) * 10) / 10 or nil, asked = r.sends,
            answer = r.answer, why = r.why, final = r.final, born_dead = r.born_dead, held = r.held }
    end
    table.sort(rows, function(a, b) return a.copy < b.copy end)
    while #rows > 12 do table.remove(rows) end
    return { about = "10.21: a kill either way (message kind 21). The host's death already finished the joiner's copy; new: my copy dying first asks the host to kill its own. Never a boss, never during a cutscene or a load, a body first seen dead asks nothing.",
        on = K.on, crash_marker = tracer.kill_suspect or nil, counts = K.n, last = K.last, last_error = K.last_error, copies_watched = rows, history = K.history,
        waits = { dead_for_s = K.DEAD_FOR, resend_s = K.RESEND_S, max_sends = K.MAX_SENDS, host_per_second = K.HOST_PER_S, host_hits = K.TRIES } }
end
end -- do

-- =============================================================================================
-- (10.21) MOLDED LIMBS AND HEADS (CFG.limb, message kind 22). Your 22 Nov request: "the molded also have not got synced limb and head removal".
--
-- WHAT IS KNOWN: the game keeps, per Molded, which parts are lost: enum app.MoldedActionController.LostPartsUnit.Type (Head 0, LeftArm 1, RightArm 2, LeftLeg 3, RightLeg 4, Body 5,
-- Blade 6), a class ...LostPartsWork, a class app.EnemyLostPartsController, and per-family Em4000/4100/4200 LostPartsUserData. WHAT IS NOT KNOWN: the methods and fields of those
-- classes (the dump I have lists names of types, not their members). So this module does not guess names. It
--   1. reads the TYPE DEFINITIONS (reflection, no live object needed), one type per half second, and writes the members that matter to re7mp/limb_probe.json: send me that file;
--   2. finds on each Molded body the components that could own the lost parts, and looks for ONE exact shape of method: "takes one LostPartsUnit.Type / LostPartsType, returns
--      System.Boolean, has Lost in its name" (an "is this part lost" question), asked for the five parts Head, both arms, both legs;
--   3. when such a question exists it can READ the mask here; a part lost on this side is sent as "l|name|mask" (bit = 1 << type), once per change and again every 10 s;
--   4. the other side removes the part on its copy with a method of the shape "takes one LostPartsUnit.Type, has Lost in its name, is not is/has/get/can/check/set..." (up to
--      3 candidates, in order of how likely the name is, the next one only when the part did not read as lost 1.5 s after the call);
--   5. with no way to READ there is no way to know a part was lost, so nothing is sent or removed: the file and the debug section just say what was found.
-- Never a body that is dead, never during a cutscene or a load (CFG.guard), a crash marker (stage "limb") switches it off at the next start.
-- =============================================================================================
CFG.limb = {
    MSG = 22,
    on = true,               -- both players (remembered as limb_sync)
    SCAN_EVERY = 0.5, ANNOUNCE_S = 10, PENDING_S = 30, VERIFY_S = 1.5, PROBE_EVERY_S = 5, MAX_CANDIDATES = 3, HOST_PER_S = 20, CTL_RECHECK_S = 10,
    SYNC_PARTS = { 0, 1, 2, 3, 4 }, SYNC_MASK = 31,
    PART_NAMES = { [0] = "Head", [1] = "LeftArm", [2] = "RightArm", [3] = "LeftLeg", [4] = "RightLeg", [5] = "Body", [6] = "Blade" },
    TYPES = {
        "app.EnemyLostPartsController", "app.MoldedActionController", "app.MoldedActionController.LostPartsUnit", "app.MoldedActionController.LostPartsUnit.Type",
        "app.MoldedActionController.LostPartsWork", "app.Em4000ActionController", "app.Em4100ActionController", "app.Em4200ActionController",
        "app.AI.MoldedCommonBoard", "app.AI.MoldedCommonBoard.LostPartsUnit", "app.Em4000.Action.LostParts", "app.Em4000LostPartsUserData", "app.Em4000LostPartsUserData.Unit",
        "app.Em4100LostPartsUserData", "app.Em4200LostPartsUserData", "app.CH9MoldedActionController", "app.CH9MoldedActionController.LostPartsWork",
    },
    PATS = { "^app%.Em4[012]00ActionController$", "^app%.MoldedActionController$", "^app%.CH%dMoldedActionController$", "EnemyLostPartsController$" },
    recs = {},               -- body name -> { addr, ctls, ctls_at, mask, sent, sent_at, heard, apply = { [part] = state }, ... }
    pending = {},            -- body name -> { mask, at }: what the other side said is lost, not yet (all) done here
    how = {},                -- controller type name -> what was found in its definition
    types_done = 0, scan_at = -100, recent = {}, history = {}, events = {},
    probe = { types = {}, bodies = {} }, probe_dirty = false, probe_at = -100,
    n = { read_ok = 0, read_none = 0, sent = 0, resent = 0, heard = 0, applied = 0, apply_unverified = 0, apply_failed = 0, no_apply_method = 0, not_quiet = 0, pending_gave_up = 0,
        refused = 0, errors = 0, bodies_seen = 0 },
    last = "nothing yet",
}

do
local L = CFG.limb

local function note(text)
    L.last = text
    L.history[#L.history + 1] = string.format("%.0f s: %s", os.clock(), text)
    while #L.history > 16 do table.remove(L.history, 1) end
    say("limb sync: " .. text)
end

local function tname(t)
    if t == nil then return nil end
    local ok, v = pcall(function() return t:get_full_name() end)
    return ok and v or nil
end

local function event(text)
    L.events[#L.events + 1] = string.format("%.0f s: %s", os.clock(), text)
    while #L.events > 30 do table.remove(L.events, 1) end
    L.probe_dirty = true
end

local function bit_of(part) return 1 << part end
local function parts_text(mask)
    local out = {}
    for p = 0, 6 do if (mask >> p) & 1 == 1 then out[#out + 1] = L.PART_NAMES[p] end end
    return #out > 0 and table.concat(out, "+") or "none"
end

-- The type and its parents (up to 4 hops, stopping at System.* / via.*): fn(typedef, name)
local function walk_type(td, fn)
    local t, hops = td, 0
    while t and hops < 4 do
        local name = tname(t) or "?"
        if hops > 0 and (name:find("^System%.") or name:find("^via%.")) then break end
        fn(t, name)
        local ok, up = pcall(function() return t:get_parent_type() end)
        t = ok and up or nil
        hops = hops + 1
    end
end

-- The plain values (bool / number / string) of an object's fields, and the type of the others: { { name, type, value } ... } (at most `cap`)
function L.scalar_fields(obj, cap)
    local out = {}
    local okt, td = pcall(function() return obj:get_type_definition() end)
    if not okt or td == nil then return out end
    walk_type(td, function(t)
        local okf, fl = pcall(function() return t:get_fields() end)
        for _, f in ipairs(okf and fl or {}) do
            if #out >= (cap or 60) then return end
            local okn, fname = pcall(function() return f:get_name() end)
            local oks, st = pcall(function() return f:is_static() end)
            if okn and not (oks and st) then
                local ft = tname(select(2, pcall(function() return f:get_type() end)))
                local okv, v = pcall(function() return obj:get_field(fname) end)
                local row = { name = fname, type = ft }
                if okv and (type(v) == "boolean" or type(v) == "number" or type(v) == "string") then row.value = v end
                out[#out + 1] = row
            end
        end
    end)
    return out
end

-- The elements of an array / List the game gave: get_elements, else get_Count + get_Item (at most 16).
function L.elements(col)
    local ok, els = pcall(function() return col:get_elements() end)
    if ok and type(els) == "table" then return els end
    local okc, n = pcall(function() return col:call("get_Count") end)
    local out = {}
    if okc and type(n) == "number" and n > 0 then
        for i = 0, math.min(n, 16) - 1 do
            local oki, it = pcall(function() return col:call("get_Item", i) end)
            if oki and it ~= nil then out[#out + 1] = it end
        end
    end
    return out
end

-- The components of a body that could own its lost parts: { { obj, tn } } (at most 4)
function L.controllers(go)
    local out = {}
    local ok, comps = pcall(function() return go:call("get_Components"):get_elements() end)
    if not ok or not comps then return out end
    for _, c in ipairs(comps) do
        local okn, full = pcall(function() return c:get_type_definition():get_full_name() end)
        if okn and type(full) == "string" then
            for _, pat in ipairs(L.PATS) do
                if full:find(pat) then out[#out + 1] = { obj = c, tn = full } break end
            end
        end
        if #out >= 4 then break end
    end
    return out
end

local function rank_read(n) return n:find("^is") and 1 or (n:find("^has") and 2 or 3) end
local function rank_apply(n)
    if n:find("^request") then return 1 end
    if n:find("^[Ll]ost") then return 2 end
    if n:find("^break") or n:find("^cut") or n:find("^remove") or n:find("^dismember") then return 3 end
    if n:find("^start") or n:find("^exec") or n:find("^do") then return 4 end
    return 5
end

-- What one controller type offers (looked at once per type): the "is this part lost" methods, the "make it lost" methods, the work collections.
function L.learn(ctl)
    local h = L.how[ctl.tn]
    if h then return h end
    h = { type = ctl.tn, read_methods = {}, apply_methods = {}, other_lost_methods = {}, work_fields = {}, apply_errors = {} }
    L.how[ctl.tn] = h
    local okd, td = pcall(function() return ctl.obj:get_type_definition() end)
    if not okd or td == nil then h.error = "no type definition" return h end
    walk_type(td, function(t, owner)
        local okm, ml = pcall(function() return t:get_methods() end)
        for _, m in ipairs(okm and ml or {}) do
            local okn, mname = pcall(function() return m:get_name() end)
            if okn and type(mname) == "string" and mname:find("[Ll]ost") then
                local okc, np = pcall(function() return m:get_num_params() end)
                local okr, rt = pcall(function() return m:get_return_type() end)
                local rtn = okr and tname(rt) or nil
                local pt
                if okc and np == 1 then
                    local okp, ps = pcall(function() return m:get_param_types() end)
                    pt = okp and type(ps) == "table" and tname(ps[1]) or nil
                end
                if pt and (pt:find("LostPartsUnit%.Type$") or pt:find("LostPartsType$")) then
                    if rtn == "System.Boolean" and not mname:find("^set") then
                        h.read_methods[#h.read_methods + 1] = { name = mname, rank = rank_read(mname), owner = owner }
                    elseif not (mname:find("^is") or mname:find("^has") or mname:find("^get") or mname:find("^can") or mname:find("^check") or mname:find("^on")) then
                        h.apply_methods[#h.apply_methods + 1] = { name = mname, rank = rank_apply(mname), owner = owner, returns = rtn }
                    end
                elseif #h.other_lost_methods < 12 then
                    h.other_lost_methods[#h.other_lost_methods + 1] = string.format("%s(%s params) -> %s", mname, tostring(okc and np or "?"), tostring(rtn))
                end
            end
        end
        local okf, fl = pcall(function() return t:get_fields() end)
        for _, f in ipairs(okf and fl or {}) do
            local okn, fname = pcall(function() return f:get_name() end)
            local ft = okn and tname(select(2, pcall(function() return f:get_type() end))) or nil
            if okn and ft and ft:find("LostPartsWork") and #h.work_fields < 4 then h.work_fields[#h.work_fields + 1] = { name = fname, type = ft, owner = owner } end
        end
    end)
    local function by_rank(a, b) if a.rank ~= b.rank then return a.rank < b.rank end return a.name < b.name end
    table.sort(h.read_methods, by_rank)
    table.sort(h.apply_methods, by_rank)
    while #h.apply_methods > L.MAX_CANDIDATES do table.remove(h.apply_methods) end
    note(string.format("%s: %d 'is it lost' method(s) %s, %d 'make it lost' candidate(s) %s, %d lost-parts collection(s)", ctl.tn, #h.read_methods,
        #h.read_methods > 0 and ("(first: " .. h.read_methods[1].name .. ")") or "", #h.apply_methods, #h.apply_methods > 0 and ("(first: " .. h.apply_methods[1].name .. ")") or "", #h.work_fields))
    L.probe_dirty = true
    return h
end

-- The mask of lost parts (bit = 1 << type, Head..RightLeg) of one controller, how it was read, or nil and why.
function L.read_ctl(ctl)
    local h = L.learn(ctl)
    local m = h.read_methods[1]
    if m then
        local first = not h.read_crumbed
        if first then -- (the first call of a method nobody has seen answer: named by a crash marker before it runs, cleared right after; the later calls are the same call)
            h.read_crumbed = true
            pcall(tracer.crumb, "limb", "first reading of lost parts: " .. ctl.tn .. "." .. m.name)
        end
        local mask, asked = 0, 0
        for _, p in ipairs(L.SYNC_PARTS) do
            local ok, v = pcall(function() return ctl.obj:call(m.name, p) end)
            if ok and type(v) == "boolean" then
                asked = asked + 1
                if v then mask = mask | bit_of(p) end
            end
        end
        if first then pcall(tracer.crumb, "clean", "limb first reading done") end
        if asked == #L.SYNC_PARTS then return mask, "method " .. m.name end
        return nil, "method " .. m.name .. " did not answer yes/no for every part"
    end
    for _, wf in ipairs(h.work_fields) do
        local okv, col = pcall(function() return ctl.obj:get_field(wf.name) end)
        if okv and col ~= nil then
            local els = L.elements(col)
            local mask, any_flag = 0, false
            for idx, el in ipairs(els) do
                local part, lost = idx - 1, nil
                for _, row in ipairs(L.scalar_fields(el, 30)) do
                    if row.type and row.type:find("LostPartsUnit%.Type$") and type(row.value) == "number" then part = row.value end
                    if type(row.value) == "boolean" and row.name:find("[Ll]ost") then any_flag = true lost = lost or row.value end
                end
                if lost and part >= 0 and part <= 4 then mask = mask | bit_of(part) end
            end
            if any_flag then return mask, "collection " .. wf.name end
        end
    end
    return nil, "no way found to ask which parts are lost"
end

-- Of a body (a record with .go): the mask, the controller it came from and how; cached controllers, looked for again every CTL_RECHECK_S.
function L.read_body(r, rec, now)
    if not r.ctls or now - (r.ctls_at or -100) >= L.CTL_RECHECK_S then
        r.ctls, r.ctls_at = L.controllers(rec.go), now
    end
    local why
    for _, ctl in ipairs(r.ctls) do
        local mask, how = L.read_ctl(ctl)
        if mask ~= nil then return mask, ctl, how end
        why = how
    end
    return nil, nil, why or (#r.ctls == 0 and "no component that could own the lost parts" or "?")
end

-- The bodies of this game that are Molded of the host's world: { name, rec }
function L.candidates()
    local out = {}
    if state.role == "host" then
        for _, e in ipairs(enemy.roots or {}) do
            if e.go and type(e.name) == "string" and e.name:match("^Em4[012]00_") and not (CFG.own and CFG.own.peer[e.name]) then out[#out + 1] = { name = e.name, rec = e } end
        end
    else
        for name, c in pairs(CFG.molded and CFG.molded.copies or {}) do
            if c.go and not c.dead_here then
                c.krec = c.krec or c.rec or { name = name, go = c.go, xf = c.xf, family = enemy.base(name) } -- (the record read_health / enemy_is_dead want; shared with CFG.kill)
                out[#out + 1] = { name = name, rec = c.krec }
            end
        end
    end
    return out
end

local function dead_body(rec)
    pcall(read_health, rec)
    local ok, d = pcall(enemy_is_dead, rec)
    return ok and d == true
end

-- A part that was asked for on this body and now reads as lost: the method that was called worked (counted once).
function L.verify(r, mask)
    for part, st in pairs(r.apply) do
        if st.at and not st.done and not st.failed and (mask >> part) & 1 == 1 then
            st.done, st.how = true, "verified: " .. tostring(st.method)
            L.n.applied = L.n.applied + 1
            note(string.format("%s of %s removed with %s (it reads as lost now)", L.PART_NAMES[part], r.name, tostring(st.method)))
            event(string.format("%s %s: removed with %s, verified", r.name, L.PART_NAMES[part], tostring(st.method)))
        end
    end
end

-- One step of removing `part` on this body, from the candidates in order. State per part: { i = candidates tried, at = when the last was called, done, failed, how }
function L.apply_step(r, ctl, part, now)
    local h = L.learn(ctl)
    local st = r.apply[part]
    if not st then st = { i = 0 } r.apply[part] = st end
    if st.done or st.failed then return end
    local mask = L.read_ctl(ctl)
    if mask ~= nil and (mask >> part) & 1 == 1 then return end -- (it reads as lost: L.verify has counted it, or it was lost here already)
    if mask == nil then
        L.n.no_apply_method = L.n.no_apply_method + 1
        st.failed, st.how = true, "cannot read the lost parts, so it cannot be checked"
        return
    end
    if st.at and now - st.at < L.VERIFY_S then return end
    if st.at then -- called, and the part still does not read as lost: this candidate did not work
        h.apply_errors[st.method] = "called without error, but the part did not read as lost after " .. L.VERIFY_S .. " s"
        st.at = nil
    end
    local m = h.apply_methods[st.i + 1]
    if not m or st.i >= L.MAX_CANDIDATES then
        st.failed, st.how = true, (#h.apply_methods == 0) and "no method takes a part type and has Lost in its name" or "none of the candidates made the part read as lost"
        L.n.apply_failed = L.n.apply_failed + 1
        if #h.apply_methods == 0 then L.n.no_apply_method = L.n.no_apply_method + 1 end
        note(string.format("%s of %s could not be removed here: %s (see re7mp/limb_probe.json)", L.PART_NAMES[part], r.name, st.how))
        event(string.format("%s %s: not removed: %s", r.name, L.PART_NAMES[part], st.how))
        return
    end
    st.i = st.i + 1
    pcall(tracer.crumb, "limb", string.format("removing %s of %s with %s", L.PART_NAMES[part], r.name, m.name))
    local ok, err = pcall(function() ctl.obj:call(m.name, part) end)
    pcall(tracer.crumb, "clean", "limb done")
    if ok then
        st.at, st.method = now, m.name
    else
        h.apply_errors[m.name] = tostring(err):sub(1, 90)
        L.n.errors = L.n.errors + 1
    end
end

-- One body, every SCAN_EVERY: read, send what is new, remove what the other side lost.
function L.look(cand, now)
    local name, rec = cand.name, cand.rec
    local okd, addr = pcall(function() return rec.go:get_address() end)
    local r = L.recs[name]
    if r and okd and r.addr and r.addr ~= addr then r = nil end -- another body under that name: its history starts again
    if not r then
        r = { name = name, addr = okd and addr or nil, sent = 0, heard = 0, apply = {}, family = name:match("^(Em4[012]00)_") }
        L.recs[name] = r
        L.n.bodies_seen = L.n.bodies_seen + 1
        local pend = L.pending[name]
        if pend then r.heard = r.heard | pend.mask end
    end
    if dead_body(rec) then r.dead = true return end
    r.dead = nil
    local mask, ctl, how = L.read_body(r, rec, now)
    r.read_how = how
    if mask == nil then
        L.n.read_none = L.n.read_none + 1
        r.mask = nil
    else
        L.n.read_ok = L.n.read_ok + 1
        if r.mask ~= mask then
            event(string.format("%s reads as lost: %s (%s)", name, parts_text(mask), how))
        end
        r.mask = mask
        L.verify(r, mask)
    end
    if not r.described and r.ctls and #r.ctls > 0 then
        r.described = true
        L.describe(name, r.family, rec, r.ctls)
    end
    local quiet = CFG.guard and CFG.guard.why(now)
    -- 1. what the other side lost, here
    local pend = L.pending[name]
    if pend and mask ~= nil and ctl then
        local missing = pend.mask & ~mask & L.SYNC_MASK
        if missing == 0 then
            L.pending[name] = nil
        elseif quiet then
            L.n.not_quiet = L.n.not_quiet + 1
        else
            for _, p in ipairs(L.SYNC_PARTS) do
                if (missing >> p) & 1 == 1 then L.apply_step(r, ctl, p, now) end
            end
        end
    end
    if pend and now - pend.at > L.PENDING_S and L.pending[name] then
        L.n.pending_gave_up = L.n.pending_gave_up + 1
        note(string.format("%s: the other player's lost parts (%s) could not be applied in %d s: given up", name, parts_text(pend.mask), L.PENDING_S))
        L.pending[name] = nil
    end
    -- 2. what was lost here, to the other side (not the bits it told me about: no echo)
    if mask ~= nil then
        local mine = mask & L.SYNC_MASK & ~r.heard
        local fresh = mine & ~r.sent
        local due = mine ~= 0 and r.sent_at and now - r.sent_at >= L.ANNOUNCE_S
        if fresh ~= 0 or due then
            if quiet then
                L.n.not_quiet = L.n.not_quiet + 1
            else
                net_send(L.MSG, string.format("l|%s|%d", name, mine))
                if fresh ~= 0 then L.n.sent = L.n.sent + 1 else L.n.resent = L.n.resent + 1 end
                r.sent, r.sent_at = r.sent | mine, now
                if fresh ~= 0 then note(string.format("%s lost %s here: told the other player", name, parts_text(fresh))) end
            end
        end
    end
end

-- BOTH players, every frame while enemy sync is on (the joiner from enemy_update, the host from enemy_host_update).
function L.update(now)
    if not L.on or tracer.limb_suspect then return end
    if now - L.scan_at < L.SCAN_EVERY then return end
    L.scan_at = now
    if L.types_done < #L.TYPES then -- the type definitions for the probe file, one per scan
        L.types_done = L.types_done + 1
        local tn = L.TYPES[L.types_done]
        local ok, d = pcall(CFG.car.type_dump, tn)
        L.probe.types[#L.probe.types + 1] = ok and L.slim(d) or { type = tn, error = tostring(d):sub(1, 100) }
        L.probe_dirty = true
    end
    local seen = {}
    for _, cand in ipairs(L.candidates()) do
        seen[cand.name] = true
        local ok, err = pcall(L.look, cand, now)
        if not ok then
            L.n.errors = L.n.errors + 1
            L.last_error = tostring(err):sub(1, 100)
        end
    end
    for name in pairs(L.recs) do
        if not seen[name] then L.recs[name] = nil end
    end
    for name, p in pairs(L.pending) do
        if not seen[name] and now - p.at > L.PENDING_S then
            L.n.pending_gave_up = L.n.pending_gave_up + 1
            L.pending[name] = nil
        end
    end
    if L.probe_dirty and now - L.probe_at >= L.PROBE_EVERY_S then L.save(now) end
end

-- THE OTHER PLAYER: "l|name|mask" (cumulative: everything lost there). Recorded at once, done by L.update (a body that is not there yet is waited for).
function L.on_message(rest, now)
    local name, m = rest:match("^l|([%w_]+)|(%d+)$")
    local mask = tonumber(m)
    if not name or not mask then L.n.refused = L.n.refused + 1 return end
    mask = mask & L.SYNC_MASK
    if not L.on or tracer.limb_suspect then L.n.refused = L.n.refused + 1 return end
    if state.role == "host" and not enemy.hit.accept then L.n.refused = L.n.refused + 1 return end -- (the box "hits from the other player" is off here)
    if not name:match("^Em4[012]00_") then L.n.refused = L.n.refused + 1 return end
    if CFG.own and CFG.own.peer[name] then L.n.refused = L.n.refused + 1 return end
    for i = #L.recent, 1, -1 do
        if now - L.recent[i] > 1 then table.remove(L.recent, i) end
    end
    if #L.recent >= L.HOST_PER_S then L.n.refused = L.n.refused + 1 return end
    L.recent[#L.recent + 1] = now
    L.n.heard = L.n.heard + 1
    local r = L.recs[name]
    if r then r.heard = r.heard | mask end
    local pend = L.pending[name]
    if pend then pend.mask = pend.mask | mask else L.pending[name] = { mask = mask, at = now } end
    L.last = string.format("%s: the other player says %s is lost there", name, parts_text(mask))
end

net_on(L.MSG, function(payload)
    local ok, err = pcall(L.on_message, payload, os.clock())
    if not ok then L.n.errors, L.last_error = L.n.errors + 1, tostring(err):sub(1, 100) end
end)

-- ---- the probe file ----
function L.slim(d)
    if type(d) ~= "table" or not d.found then return d end
    local total = (d.fields_total or 0) + (d.methods_total or 0)
    if total <= 60 then return d end
    local function keep(row) return row.name and (row.name:find("[Ll]ost") or row.name:find("[Pp]arts") or row.name:find("[Bb]reak") or row.name:find("[Dd]ismember") or row.name:find("[Ss]ever")) end
    local out = { type = d.type, found = true, parent = d.parent, fields = {}, methods = {}, fields_total = d.fields_total, methods_total = d.methods_total,
        note = "only members with lost / parts / break / dismember / sever in the name (the type has " .. total .. " members)" }
    for _, f in ipairs(d.fields or {}) do if keep(f) then out.fields[#out.fields + 1] = f end end
    for _, m in ipairs(d.methods or {}) do if keep(m) then out.methods[#out.methods + 1] = m end end
    return out
end

-- The first body of each family that has a controller: the fields of every controller and the first elements of its lost-parts collections.
function L.describe(name, family, rec, ctls)
    local key = (family or name) .. "@" .. tostring(state.role)
    if L.probe.bodies[key] then return end
    local out = { body = name, controllers = {} }
    for _, ctl in ipairs(ctls or {}) do
        local row = { type = ctl.tn, fields = L.scalar_fields(ctl.obj, 80), collections = {} }
        local h = L.how[ctl.tn]
        for _, wf in ipairs(h and h.work_fields or {}) do
            local okv, col = pcall(function() return ctl.obj:get_field(wf.name) end)
            local c = { field = wf.name, type = wf.type, elements = {} }
            if okv and col ~= nil then
                for i, el in ipairs(L.elements(col)) do
                    if i > 8 then break end
                    c.elements[#c.elements + 1] = L.scalar_fields(el, 30)
                end
            end
            row.collections[#row.collections + 1] = c
        end
        out.controllers[#out.controllers + 1] = row
    end
    L.probe.bodies[key] = out
    L.probe_dirty = true
end

function L.save(now)
    L.probe_at, L.probe_dirty = now, false
    local copy = {}
    for tn, h in pairs(L.how) do
        copy[#copy + 1] = { type = tn, read_methods = h.read_methods, apply_methods = h.apply_methods, other_lost_methods = h.other_lost_methods, lost_collections = h.work_fields,
            apply_errors = h.apply_errors, error = h.error }
    end
    table.sort(copy, function(a, b) return a.type < b.type end)
    local res = { about = "re7mp 10.21 Molded limb probe: reads the type definitions and, on the first Molded body of each family, the lost-parts fields. Send this file.",
        build = CFG.BUILD, role = state.role, types = L.probe.types, bodies = L.probe.bodies, what_was_found = copy, events = L.events, written_at = os.time() }
    local ok, where = CFG.save_json(FILES.MAP.limb_probe[1], FILES.MAP.limb_probe[2], res)
    if not ok then L.n.errors = L.n.errors + 1 L.last_error = tostring(where):sub(1, 100) end
end

function L.report()
    local rows = {}
    for name, r in pairs(L.recs) do
        local apply = {}
        for p, st in pairs(r.apply) do apply[#apply + 1] = L.PART_NAMES[p] .. ": " .. (st.done and st.how or st.failed and ("failed: " .. tostring(st.how)) or ("trying " .. tostring(st.method))) end
        table.sort(apply)
        rows[#rows + 1] = { body = name, lost_here = r.mask and parts_text(r.mask) or "cannot be read", read_how = r.read_how, told_other = parts_text(r.sent), told_by_other = parts_text(r.heard),
            removing = apply, dead = r.dead }
    end
    table.sort(rows, function(a, b) return a.body < b.body end)
    while #rows > 10 do table.remove(rows) end
    local pend = {}
    for name, p in pairs(L.pending) do pend[#pend + 1] = name .. ": " .. parts_text(p.mask) end
    table.sort(pend)
    local how = {}
    for tn, h in pairs(L.how) do
        how[#how + 1] = { type = tn, is_lost_methods = #h.read_methods, first_is_lost = h.read_methods[1] and h.read_methods[1].name or nil, make_lost_candidates = #h.apply_methods,
            first_make_lost = h.apply_methods[1] and h.apply_methods[1].name or nil, collections = #h.work_fields, apply_errors = h.apply_errors, error = h.error }
    end
    table.sort(how, function(a, b) return a.type < b.type end)
    return { about = "10.21: limbs and heads of the Molded, both ways (message kind 22). Partly GUESSWORK until a debug file shows the game's real methods: it only acts through a method with an exact shape (see CHANGELOG) and "
        .. "writes re7mp/limb_probe.json with what the game offers. Nothing here has run in the real game.",
        on = L.on, crash_marker = tracer.limb_suspect or nil, counts = L.n, last = L.last, last_error = L.last_error, found = how, bodies = rows, waiting_for_a_body = pend,
        type_definitions_read = string.format("%d of %d", L.types_done, #L.TYPES), history = L.history, events = L.events,
        waits = { scan_s = L.SCAN_EVERY, announce_s = L.ANNOUNCE_S, verify_s = L.VERIFY_S, pending_s = L.PENDING_S, candidates = L.MAX_CANDIDATES } }
end
end -- do


-- ---- what to send me for the next step ----
local ENEMY_DBG = {}
ENEMY_DBG.key_types = {
    "app.Em2000Status", "app.Em3000Status", "app.EnemySave", "app.Em2000Think", "app.Em2000Order",
    "app.Em2000.Em2000DamageController", "app.Em3000.Em3000DamageController", "app.Collision.CalculateDamage",
    "app.EnemySceneSurveillance", "app.EnemyExistZone", "app.AI.MansionAISetController", "app.AI.Em3000MansionAISetInfo",
    "app.AI.MansionAI", "app.AI.AIWorldBlackBoard", "app.EnemyRankManager",
    "app.DamageController", "app.EnemyDamageController", "app.EnemyStatus", "app.Em3100Status", "app.Em3100DamageController",
}
-- Small types whose every method is listed (the health and damage records)
ENEMY_DBG.list_all = { "app.HealthInfo", "app.DamageController.DamageRecord", "app.Collision.HitController.DamageInfo" }
ENEMY_DBG.method_words = { "hp", "damage", "dead", "die", "kill", "life", "health", "alive", "spawn", "set", "create", "active", "hit" }
ENEMY_DBG.dump_components = {
    "^app%.Em%d+Status$", "^app%.EnemySave$", "^app%.Em%d+Think$", "^app%.Em%d+Order$", "^app%.Em%d+%.Em%d+DamageController$",
    "^app%.EnemyRankManager$", "^app%.Humanoid$", "^app%.MovementController$",
}

local function enemy_details()
    pinned(function()
        say("=== enemy details ===")
        local ok, roots = pcall(find_enemy_roots)
        if not ok then
            say("enemy details: scan failed: " .. tostring(roots))
            roots = {}
        end
        say(#roots .. " enemy root objects")
        for _, e in ipairs(roots) do
            pcall(function()
                local p = e.xf:call("get_Position")
                say(string.format("-- %s at %.2f, %.2f, %.2f", e.name, p.x, p.y, p.z))
                local bank, motion, frame = read_motion(e)
                say(string.format("   animation layer 0: bank %d, motion %d, frame %.1f", bank, motion, frame))
                if not e.hp_checked then find_health(e) end
                local fl = inactive_flags(e, motion, p)
                say(string.format("   Status component: %s; health read from: %s; looks like: %s",
                    e.status and "yes" or "NO", e.hp_field and ((e.hp_where and (e.hp_where .. ".") or "") .. e.hp_field) or "nothing found",
                    fl == 0 and "a live enemy" or flags_reason(fl)))
                for _, c in ipairs(e.go:call("get_Components"):get_elements()) do
                    local full = c:get_type_definition():get_full_name()
                    for _, pat in ipairs(ENEMY_DBG.dump_components) do
                        if full:find(pat) then
                            say("   component " .. full)
                            dump_fields(c, "      ", 90)
                            if full:find("DamageController$") or full:find("^app%.Em%d+Status$") then
                                for _, hv in ipairs(fields_of_type(c, "app.HealthInfo")) do
                                    say("      HealthInfo object in field " .. hv[1] .. ":")
                                    dump_fields(hv[2], "         ", 40)
                                end
                            end
                            break
                        end
                    end
                end
            end)
        end
        say("=== enemy methods (hp / damage / dead / spawn related) ===")
        for _, n in ipairs(ENEMY_DBG.key_types) do probe_type(n, false, ENEMY_DBG.method_words, 70) end
        for _, n in ipairs(ENEMY_DBG.list_all) do probe_type(n, true, nil, 60) end
        say("=== enemy details done ===")
    end)
end

