----------------------------------------------------------------------------------------------
-- Death sync. "Shared fate": when one player dies the other dies too.
-- Death is detected when the game switches to its game-over GameMode (found by name in the enum, see
-- build_mode_map); the other game is put into the same mode. Both parts are untested guesses until a
-- real death has been tried, so the default is "Independent" and the choice is in the panel.
----------------------------------------------------------------------------------------------
local DEATH_MSG = 4
local DEATH_MODES = {
    "Independent (nothing happens)",
    "Shared fate: both players die",
    "Dead player waits for the other (not built yet)",
    "Downed and revive (needs the other player)",
}
-- the default is "Downed and revive" (4). It only acts while the other player is connected; alone, nothing changes.
-- 9.27 (your idea): an execution is a death the game does not let anyone hold at 1 health ("I think its hard coded to work this way"),
-- so while the other player is up it ends the game for BOTH: the executed player's game over is sent as "exec" and the other player's
-- game goes game over too (a team wipe), instead of leaving one player alone at the checkpoint of the other. Switch: exec_wipe.
local death = { mode = 4, suppress_until = 0, last = "No deaths yet.", sent = 0, received = 0,
    exec_wipe = true, exec_sent = 0, exec_received = 0, exec_last = "No execution deaths yet.", exec_skipped = 0 }

-- Was the game over that just came an execution (a scripted kill) and not a hit that took the health to 0? A hit that would kill is held
-- at 1 (then you are down and there is no game over), so a game over that comes while you are not down and your health is above 1 is a
-- scripted kill. (10.23: a game over that followed a grab call used to count too, but only while the execution test's log was ticked; that log is gone.)
function death.looks_like_execution(now)
    if pstat.downed then return false, "you were down already" end
    if pstat.hp ~= nil and pstat.hp > 1.5 then return true, string.format("health was %.0f, not 0 or 1", pstat.hp) end
    return false, pstat.hp == nil and "your health can't be read" or "health was 1 or less: a death by damage"
end

local function apply_remote_death(who, kind)
    death.received = death.received + 1
    if death.mode == 4 then -- downed mode: the other player really died, which only matters if I am down too (team wipe)
        local executed = kind == "exec" and death.exec_wipe
        if kind == "exec" and not death.exec_wipe then death.exec_skipped = death.exec_skipped + 1 end
        if executed and not pstat.downed and os.clock() < death.suppress_until then
            death.last = who .. " was executed (you are already dying)."
            chat_add("Death", death.last)
            return
        end
        if pstat.downed or executed then
            if executed then
                death.exec_received = death.exec_received + 1
                death.last = who .. " was executed: the team is wiped, you go down with them (game over)."
                death.exec_last = death.last
            else
                death.last = who .. " died while you were down: you die too."
            end
            chat_add("Death", death.last)
            death.suppress_until = os.clock() + 30
            pstat.no_hold_until = os.clock() + 20 -- a debug file showed the hold writing 1 back ten times a second for six seconds
            local ok, err = RE7.kill_local_player()
            if not ok then death.last = death.last .. " (could not kill you: " .. tostring(err) .. ")" end
        else
            death.last = who .. " died (you are not down, so nothing happens to you)."
            chat_add("Death", death.last)
        end
        return
    end
    if death.mode ~= 2 then
        death.last = who .. " died (shared fate is off, nothing happens)."
        chat_add("Death", death.last)
        return
    end
    local now = os.clock()
    if now < death.suppress_until then
        death.last = who .. " died (you are already dying)."
        return
    end
    death.suppress_until = now + 30 -- our own game-over must not bounce back
    local ok, err = RE7.kill_local_player()
    death.last = ok and (who .. " died: you die with them (shared fate).")
        or (who .. " died but I could not kill you: " .. tostring(err))
    chat_add("Death", death.last)
    say(death.last)
end

net_on(DEATH_MSG, function(payload)
    apply_remote_death(state.remote_name or CFG.DEFAULT_NAME, payload)
end)

-- Called for every setGamemode(value) the game makes.
RE7.on_death_signal = function(source)
    if pstat.reset_down then pstat.reset_down("the game ended", true) end
    local now = os.clock()
    if CFG.friend and CFG.friend.over then pcall(CFG.friend.over.arm, source, now) end -- (10.9) Ethan's friend gets up and comes to you after the reload
    if now < death.suppress_until then return end
    say("death signal: " .. tostring(source))
    death.suppress_until = now + 30 -- the game-over screen can set the mode more than once
    if death.mode == 4 and now - state.remote_changed_at < CFG.STALE_AFTER then
        local exec, exec_why = death.looks_like_execution(now)
        if exec and death.exec_wipe then
            net_send(DEATH_MSG, "exec")
            death.sent = death.sent + 1
            death.exec_sent = death.exec_sent + 1
            death.last = "You were executed (" .. exec_why .. "): told the other player, who goes game over with you (team wipe)."
            death.exec_last = death.last
        else
            net_send(DEATH_MSG, "died")
            death.sent = death.sent + 1
            death.last = "You died for real (told the other player: they die too if they are down)."
            if exec then death.last = death.last .. " (this looks like an execution, but team wipe on execution is switched off)" end
        end
        if not exec and pstat.clamped > 0 and not (pstat.remote and pstat.remote.downed) then
            death.last = death.last .. " NOTE: I held your health at 1 " .. pstat.clamped
                .. " time(s) and the game still ended: holding the health up is not enough, see button 8."
        end
    elseif death.mode == 2 and now - state.remote_changed_at < CFG.STALE_AFTER then
        net_send(DEATH_MSG, "died")
        death.sent = death.sent + 1
        death.last = "You died: told the other player (shared fate)."
    else
        death.last = "You died (nothing sent: " .. (death.mode == 2 and "nobody is connected" or "shared fate is off") .. ")."
    end
    chat_add("Death", death.last)
    say(death.last)
end

RE7.on_gamemode = function(value)
    say("game mode set to " .. tostring(value))
    if RE7.death_value == nil or value ~= RE7.death_value then return end
    RE7.on_death_signal("game mode " .. tostring(RE7.death_name))
end

-- (10.23) The execution test was removed: a log of the grab / finisher / game-over calls, and an opt-in 'block the game over and go down
-- instead'. It was a developer experiment. The part that is kept is "Executions end the game for BOTH players" (above): it decides from the
-- health, with no extra hooks.

-- Other ways a death can start. Your notes say the finishers (Jack's grab, Mia in the attic) never reached the game-over
-- mode switch above. So any method of the game manager or of the player's damage controller that is named like a game over or
-- a death is watched too (never getters; at most 8 in all; one that fires more than 50 times is ignored as too busy), and
-- every firing goes into the journal, so the next file shows which call a finisher really makes.
RE7.death_hooks = {}
function RE7.install_death_extras()
    local want = {
        { "app.GameManager", { "setgameover", "requestgameover", "startgameover", "dogameover", "ongameover" } },
        { "app.PlayerDamageController", { "dodie", "ondie", "die", "dokill", "kill", "setdead", "dodead", "ondead", "setdie" } },
    }
    for _, w in ipairs(want) do
        local tn, prefixes = w[1], w[2]
        local td = sdk.find_type_definition(tn)
        local done = {}
        for _, m in ipairs(td and td:get_methods() or {}) do
            local name = m:get_name()
            local low = name:lower()
            if not done[name] and #RE7.death_hooks < 8 then
                for _, pre in ipairs(prefixes) do
                    if low:find("^" .. pre) then
                        done[name] = true
                        local fired = 0
                        if hook_method(tn, name, function(args)
                            fired = fired + 1
                            if fired > 50 then return end
                            if fired <= 5 then say(string.format("death hook fired: %s.%s (#%d)", tn, name, fired)) end
                            if tn == "app.GameManager" and low:find("flag", 1, true) then -- a flag being cleared is not a death
                                local okv, v = pcall(function() return sdk.to_int64(args[3]) end)
                                if okv and type(v) == "number" and v % 256 == 0 then return end
                            end
                            RE7.on_death_signal(name)
                        end) then
                            RE7.death_hooks[#RE7.death_hooks + 1] = tn .. "." .. name
                        end
                        break
                    end
                end
            end
        end
    end
    say("death detection also watches: " .. (#RE7.death_hooks > 0 and table.concat(RE7.death_hooks, ", ") or "nothing else was found"))
end

----------------------------------------------------------------------------------------------
-- Player health (v9.3): reads your health, tells the other player, and works out events from it.
--  * Your health is looked for in the components of the player object (Pl0000): an app.HealthInfo held by the
--    player's DamageController (the class the enemies use too: Health / MaxHealth). The panel and the debug
--    file say where it was found, or that it was not.
--  * Changes are sent as message kind 7: "h|hp|max|down" (at most twice a second, plus a heartbeat every 3 s).
--    The other player sees "HP 65%" over your head.
--  * A heal is a rise in health. When it follows a healing item being used (app.Inventory.reduceItem on a
--    Herb / Chem Fluid / Remedy) the other player is told "e|heal|Herb|x|y|z".
--  * Death mode 4, "Downed and revive" (EXPERIMENTAL, needs the other player connected): a hit that would take
--    your health to 0 is held at 1 instead (a hook after HealthInfo.set_health, plus a check ten times a
--    second). You are then "down" and cannot heal yourself; the other player gets you up by using a healing
--    item next to you (their own Herb / Chem Fluid use), or stays next to you for a few seconds with F8 (no item, the wait
--    is the cost). Because the game never
--    saw you die it never reloads a checkpoint, so you get up where you fell. If both of you are down, or the
--    hold does not work, the game ends as usual. Nothing here has been tried in the real game yet.
----------------------------------------------------------------------------------------------
do
local H = {}
H.PH_MSG = 7
H.BOT_MSG = 11 -- a command only Ethan's friend understands ("down" / "up"); a real player's script has no handler for it
H.CALL_ORIGINAL = sdk.PreHookResult and sdk.PreHookResult.CALL_ORIGINAL

H.PLAYER_WORDS = { "damage", "guard", "block", "heal", "recover", "health", "hp", "die", "dead", "death", "down", "dying",
    "revive", "knock", "kill", "faint", "life", "grapple", "caught", "stun", "parry", "shield", "defen", "hit", "avoid",
    "item", "use" }
-- components of Pl0000 looked at first (the rest of the app.Player* ones follow)
H.PLAYER_FIRST = { "app.PlayerDamageController", "app.PlayerStatus", "app.PlayerOrder", "app.PlayerStrikeController",
    "app.PlayerLArmDamage", "app.PlayerExternalRequestController", "app.PlayerGrappleEm2000", "app.PlayerGrappleEm3000",
    "app.PlayerItem", "app.PlayerEventActionManager", "app.PlayerSequenceManager", "app.PlayerBreathController",
    "app.PlayerCommandUpdater", "app.PlayerHands", "app.PlayerMelee" }
H.PLAYER_DUMP = { ["app.PlayerDamageController"] = true, ["app.PlayerStatus"] = true, ["app.PlayerOrder"] = true,
    ["app.PlayerLArmDamage"] = true, ["app.PlayerBreathController"] = true, ["app.PlayerStrikeController"] = true,
    ["app.PlayerExternalRequestController"] = true, ["app.PlayerCommandUpdater"] = true }
-- event / cutscene / flow classes from your component census, and the method names worth watching in them
H.EVENT_TYPES = { "app.GameEventManager", "app.GameEventController", "app.GameEventActionController", "app.GameEventAction",
    "app.GameEventSetting", "app.EventActionController", "app.SequenceController", "app.TimeLineContainer",
    "app.TimeLineKicker", "app.TimeLineKickerContainer", "app.TimeLinePlayStateControlManager", "app.TimeLineStateInfo",
    "app.GameFlowFsmManager", "app.GameFlowActiveControl", "app.ChapterLoadTempManager", "app.ChapterJumpData",
    "app.PlayerEventActionManager", "app.InteractEventAction", "app.DoorEventAction", "app.FadeControl",
    "app.NowLoadingScreen", "app.TriggerInAction" }
-- Opt-in extras . The 9.5 button 9 hooked 77 DoorPush, 15 InteractObjectBase, 13 GameManager and 75 SaveDataManager
-- methods at once and the game crashed a few seconds later while a door was closing; the log cannot say which hook did it.
-- So these are hand-picked, off by default and ticked one at a time. "=" in front of a name means exactly that method.
-- The player's doors are app.DoorPush (the 8 DoorEventActions in the scene are monsters' doors and never fired); the
-- names below are the ones the 9.5 trace saw fire for a door, plus a few likely ones that are simply skipped if absent.
H.EVENT_EXTRAS = {
    doors = { label = "doors (app.DoorPush and app.InteractObjectBase, hand-picked methods only)", types = {
        { "app.DoorPush", { "=setInteract", "=playAutoOpen", "=playLittleOpen", "=playOpened", "=playAutoClose", "=playClosed",
            "=closeDoorCore", "=lockDoor", "=lockDoorCore", "=unlockDoor", "=unlockDoorCore", "=openDoor", "=closeDoor" } },
        { "app.InteractObjectBase", { "=successInteract", "=failInteract", "=failedInteract" } } } },
    flags = { label = "story flags and chapter jumps (app.GameManager)", types = {
        { "app.GameManager", { "=setFsmGlobalBoolValue", "=setFsmGlobalIntValue", "=addFsmGlobalIntValue", "=chapterJumpRequest",
            "=nextChapterJumpRequest", "=requestEvent", "=setGameOverFlag", "=setTitleReturnFlag" } } } },
    saves = { label = "save and load calls (app.SaveDataManager)", types = {
        { "app.SaveDataManager", { "=saveFileGameSaveData", "=loadFileAutoRequest", "=loadFileGameSaveData", "=saveFileAutoRequest",
            "=newGameInit" } } } },
}
H.EXTRA_ORDER = { "doors", "flags", "saves" }
H.extra_on = { doors = false, flags = false, saves = false }
H.EVENT_WORDS = { "start", "end", "play", "stop", "begin", "finish", "trigger", "kick", "skip", "execute", "enter", "exit",
    "request", "unlock", "chapter", "load", "fade", "complete", "jump", "event", "cutscene", "demo", "movie", "scene" }

function H.note(text)
    pstat.last = text
    say("health: " .. text)
end

function H.who_is_there() return state.remote_name or CFG.DEFAULT_NAME end

function H.read_num(obj, field)
    local ok, v = pcall(function() return obj:get_field(field) end)
    if ok and type(v) == "number" then return v end
    return nil
end

function H.address_of(obj)
    local ok, a = pcall(function() return obj:get_address() end)
    if ok and type(a) == "number" then return a end
    return nil
end

-- Numeric fields of obj and its app.* parents: { {name, type name}, ... }
function H.numeric_fields(obj)
    local out = {}
    pcall(function()
        local t = obj:get_type_definition()
        while t do
            local tn = t:get_full_name()
            if tn:find("^System%.") or tn:find("^via%.Component") or tn:find("^via%.Behavior") then break end
            for _, f in ipairs(t:get_fields() or {}) do
                if not f:is_static() then
                    local ft = f:get_type()
                    local ftn = ft and ft:get_full_name() or ""
                    if ftn == "System.Single" or ftn == "System.Int32" or ftn == "System.Double" then
                        out[#out + 1] = { f:get_name(), ftn }
                    end
                end
            end
            t = t:get_parent_type()
        end
    end)
    return out
end

-- The field next to the current health that holds the maximum ("MaxHealth", "_MaxHp"). The enemies'
-- "defaultMaxHealth" is not taken: it is a starting value, not the current maximum.
function H.find_max_field(obj, inside_health)
    local best, best_rank
    for _, f in ipairs(H.numeric_fields(obj)) do
        local n = field_label(f[1]):lower()
        if n:find("max", 1, true) and not n:find("default", 1, true) and not n:find("rate", 1, true) then
            local healthy = n:find("health", 1, true) or n:find("hp", 1, true) or n:find("life", 1, true)
            local rank = healthy and 1 or (inside_health and 2 or nil)
            if rank and (not best_rank or rank < best_rank) and H.read_num(obj, f[1]) then best, best_rank = f[1], rank end
        end
    end
    return best
end

-- Looks through the player object's components for the health number. Returns true if found.
function H.scan()
    pstat.scanned_at = os.clock()
    local go = player_object()
    if not go then return false end
    pstat.go_addr = H.address_of(go)
    local best
    pcall(function()
        for _, c in ipairs(go:call("get_Components"):get_elements()) do
            local full = c:get_type_definition():get_full_name()
            local bonus = full:find("DamageController$") and 0 or (full:find("Status$") and 5 or 10)
            for _, hv in ipairs(fields_of_type(c, "app.HealthInfo")) do
                local fname, sc = enemy.best_health_field(hv[2], true)
                if fname and (not best or sc + bonus < best.rank) then
                    best = { rank = sc + bonus, obj = hv[2], field = fname, inside = true, where = full .. "." .. hv[1] }
                end
            end
            local fname, sc = enemy.best_health_field(c, false)
            if fname and (not best or sc + bonus + 20 < best.rank) then
                best = { rank = sc + bonus + 20, obj = c, field = fname, inside = false, where = full }
            end
        end
    end)
    if not best then
        if not pstat.logged_fail then
            pstat.logged_fail = true
            say("health: no health found on the player object (button 8 in the debug section lists what it has)")
        end
        return false
    end
    pstat.logged_fail = nil
    if pstat.downed then H.reset_down("the player object was replaced (a reload?)") end
    pstat.alive_seen = false
    pstat.hi, pstat.field, pstat.where = best.obj, best.field, best.where
    pstat.hi_addr = H.address_of(best.obj)
    pstat.max_field = H.find_max_field(best.obj, best.inside)
    pstat.int_field = false
    for _, f in ipairs(H.numeric_fields(best.obj)) do
        if f[1] == best.field and f[2] == "System.Int32" then pstat.int_field = true end
    end
    pstat.read_fail = 0
    pstat.hp, pstat.max = nil, nil -- so the first reading is not mistaken for a heal
    pstat.mute_until = os.clock() + 1
    if pstat.logged_where ~= pstat.where then
        pstat.logged_where = pstat.where
        say(string.format("health: your health is read from %s.%s (maximum from %s)%s", pstat.where, pstat.field,
            pstat.max_field or "nothing: the highest value seen is used",
            pstat.hi_addr and "" or " (object address unreadable: the hold-at-1 hook cannot recognise it, only the per-frame check works)"))
    end
    return true
end

function H.read_health()
    local hp = H.read_num(pstat.hi, pstat.field)
    if hp == nil then return nil end
    local mx = pstat.max_field and H.read_num(pstat.hi, pstat.max_field) or nil
    if hp > pstat.seen_max then pstat.seen_max = hp end
    if mx and mx > pstat.seen_max then pstat.seen_max = mx end
    return hp, (mx and mx > 0) and mx or pstat.seen_max
end

function H.write_health(v)
    if not pstat.hi then return false end
    if pstat.int_field then v = math.floor(v + 0.5) else v = v + 0.0 end
    pstat.writing = true
    local ok = pcall(function() pstat.hi:set_field(pstat.field, v) end)
    pstat.writing = false
    if not ok then return false end
    pstat.hp = v
    return true
end

-- 9.31 (friendly fire): take damage off my health, never below 1. Returns true, { before, after } or false, why.
function H.apply_damage(dmg)
    if pstat.downed then return false, "already down" end
    if not pstat.hi then return false, "no health object" end
    local hp = H.read_num(pstat.hi, pstat.field)
    if type(hp) ~= "number" then return false, "health not readable" end
    local target = math.max(1, hp - dmg)
    if target >= hp then return false, "nothing to take (health " .. tostring(hp) .. ")" end
    if not H.write_health(target) then return false, "the game would not take the new health" end
    return true, { before = hp, after = target }
end
pstat.apply_damage = H.apply_damage
pstat.write_health, pstat.note = H.write_health, H.note -- (10.6: the friend's panel section, outside this block, writes your health and leaves a note through these)

-- 9.28 (testing): invincible. A hit that lowers the health is undone at once (in the set_health hook and in the 10-a-second
-- check), so enemies can be tried out. NOT for real play: it is off at every start and is not remembered. It does not stop an
-- execution or any other instant game over (those do not go through the health).
function H.god_fill()
    if not pstat.god or pstat.downed or not pstat.hi or pstat.writing then return false end
    local hp = H.read_num(pstat.hi, pstat.field)
    local top = pstat.max
    if type(top) ~= "number" or top <= 0 then top = pstat.seen_max end
    if type(hp) ~= "number" or type(top) ~= "number" or top <= 0 or hp >= top - 0.5 then return false end
    if hp <= 0.5 and not pstat.alive_seen then return false end -- (no health read yet: do not write into an unknown state)
    if H.write_health(top) then
        pstat.god_writes = (pstat.god_writes or 0) + 1
        return true
    end
    return false
end

function H.send_state(now)
    if not peer_present(now) or pstat.hp == nil then return end
    pstat.sent_at, pstat.sent_hp = now, pstat.hp
    net_send(H.PH_MSG, string.format("h|%.0f|%.0f|%d", pstat.hp, pstat.max or 0, pstat.downed and 1 or 0))
    pstat.sent = pstat.sent + 1
end

function H.send_event(kind, arg)
    local lp = state.local_pos
    if not lp or not peer_present() then return end
    net_send(H.PH_MSG, string.format("e|%s|%s|%.2f|%.2f|%.2f", kind, arg or "", lp.x, lp.y, lp.z))
    pstat.sent = pstat.sent + 1
end
pstat.send_event = H.send_event -- (the character, weapon and friendly-fire code, outside this block, sends its events through it)
CFG.low.send = H.send_event -- (10.12: the "low" event)

function H.is_heal_item(name)
    local low = name:lower()
    for _, w in ipairs(pstat.heal_words) do
        if low:find(w, 1, true) then return true end
    end
    return false
end

-- How far the other player is from you in metres (nil if unknown).
function H.remote_distance()
    local lp, r = state.local_pos, state.remote
    if not (lp and r and r.pos) then return nil end
    local p = r.pos
    return math.sqrt((p.x - lp.x) ^ 2 + (p.y - lp.y) ^ 2 + (p.z - lp.z) ^ 2)
end

-- Is holding your health at 1 allowed right now? Only in mode 4, only with the other player there, and not when they
-- are down already (then it is a wipe and the game ends as it normally would).
function H.clamp_active(now)
    now = now or os.clock()
    if death.mode ~= 4 or not peer_present(now) then return false end
    if now < (pstat.no_hold_until or 0) then return false end -- we are killing the player on purpose (team wipe): don't undo it
    local r = pstat.remote
    if r and r.downed and now - r.at < 10 then return false end
    return true
end
-- The game reloaded or ended without our help: forget that we were down (nothing to write, the new player is whole).
function H.reset_down(why, silent)
    if not pstat.downed then return end
    pstat.downed, pstat.pending_down = false, false
    H.note("down state cleared: " .. why)
    if not silent then H.send_event("up", "") end
end
pstat.reset_down = H.reset_down

function H.go_down(why)
    if pstat.downed then return end
    local now = os.clock()
    pstat.downed, pstat.pending_down = true, false
    pstat.down_at = now
    local who = H.who_is_there()
    H.note(string.format("you are DOWN (%s): %s has to use a Herb or Chem Fluid next to you", why, who))
    chat_add("Health", "You are down! " .. who .. " has to use a Herb or Chem Fluid next to you.")
    H.send_event("down", "")
    H.send_state(now)
end

function H.get_up(why)
    if not pstat.downed then return end
    local now = os.clock()
    pstat.downed, pstat.pending_down = false, false
    pstat.revives = pstat.revives + 1
    local target = math.max(2, (pstat.max or pstat.seen_max or 0) * pstat.revive_pct / 100)
    pstat.grace_until = now + 1.5
    H.write_health(target)
    H.note(string.format("you are back up (%s), health %.0f, right where you were", why, target))
    chat_add("Health", "You are back up.")
    H.send_event("up", "")
    H.send_state(now)
end

function H.on_heal(amount, now)
    pstat.heals = pstat.heals + 1
    local u = pstat.last_use
    if u and now - u.at < 4 then
        pstat.last_use = nil
        H.note(string.format("you healed +%.0f (%s)", amount, u.name))
        H.send_event("heal", u.name)
    else
        H.note(string.format("your health rose by %.0f (no healing item was used)", amount))
    end
end

-- The game consumed an item. A healing item is remembered; if the health then rises it is a heal. If your
-- health can't be read at all the use itself is reported.
-- 9.30 ("can still use items and heal while downed"): a downed player used a Herb and the animation ran, the Herb was spent and only the
-- hold-at-1 below put the health back. The game's own call that spends a healing item (Inventory.reduceItem, which runs at the END of the
-- animation) is refused while you are down, so the item stays in the inventory. (The animation itself still plays: no gate for it is known.)
-- Your own gives are not touched (give.giving), and only items whose name says they heal (heal_words) are.
H.ITEMLOCK = { on = true, blocked = 0, last = nil }
pstat.itemlock = H.ITEMLOCK
function H.item_blocked(name)
    local L = H.ITEMLOCK
    if not L.on or not pstat.downed or give.giving then return false end
    if not name or not plausible_id(name) or not H.is_heal_item(name) then return false end
    L.blocked = L.blocked + 1
    L.last = { name = name, at = os.clock() }
    H.note("you can't use " .. name .. " while you are down: it stays in your inventory; only the other player can get you up")
    return true
end

function H.on_item_used(name)
    if not name or give.giving or not plausible_id(name) or not H.is_heal_item(name) then return end
    pstat.last_use = { name = name, at = os.clock() }
    local rec = H.rec
    if rec and rec.on and rec.ph and rec.ph.heal then -- the recorder's report must not depend on the heal code that consumes last_use
        rec.ph.item_name, rec.ph.item_at = name, pstat.last_use.at
    end
    if not pstat.hi then H.send_event("use", name) end
end

-- Is a revive possible right now? Returns the healing item entry plus the inventory, or nil plus the reason.
-- skip_items: only the cheap checks (somebody is down, close enough), for the every-frame check while counting down.
function pstat.revive_ready(now)
    local r = pstat.remote
    local who = H.who_is_there()
    if not (peer_present(now) and r and r.downed and now - r.at < 10) then return nil, "nobody is down right now" end
    local d = H.remote_distance()
    if d == nil or d > pstat.revive_radius then
        return nil, string.format("%s is down but %s: get within %.0f m", who, d and string.format("%.1f m away", d) or "I can't tell where they are",
            pstat.revive_radius)
    end
    return true
end

-- F8 / the panel button: start reviving the downed player next to you. It uses NO item: the time is the price. You have to stay
-- within the revive distance for revive_hold seconds; walking off, going down yourself, them getting up or Cancel stops it. (9.14 took a
-- Herb / Chem Fluid / Remedy out of the inventory at the end and the game crashed right there, so the inventory is not touched at all
-- now.) Using a Herb from the inventory menu yourself (the other way to revive) is still immediate, and costs the Herb.
function pstat.revive_other()
    local now = os.clock()
    local who = H.who_is_there()
    if pstat.reviving then
        H.note(string.format("already reviving %s: %.1f of %.0f s", who, now - pstat.reviving.since, pstat.revive_hold))
        return false
    end
    local ok, why = pstat.revive_ready(now)
    if not ok then
        H.note(why)
        return false
    end
    pstat.reviving = { since = now }
    pstat.revive_stats.started = pstat.revive_stats.started + 1
    H.note(string.format("reviving %s: stay within %.0f m for %.0f s (no item is used, the wait is the cost)", who, pstat.revive_radius,
        pstat.revive_hold))
    return true
end

function pstat.revive_cancel(why)
    if not pstat.reviving then return end
    pstat.reviving = nil
    pstat.revive_stats.cancelled = pstat.revive_stats.cancelled + 1
    H.note("revive stopped: " .. tostring(why))
end

-- The end of the countdown: tell the other player (nothing is taken from the inventory). A crumb names this step if the game dies here.
function pstat.revive_finish()
    local who = H.who_is_there()
    pcall(tracer.crumb, "revive", "finishing the F8 revive of " .. tostring(who))
    H.send_event("revive", "")
    pstat.revive_stats.done = pstat.revive_stats.done + 1
    H.note(string.format("you helped %s up (%.0f s, no item used)", who, pstat.revive_hold))
    chat_add("Health", string.format("You helped %s up.", who))
    pcall(tracer.crumb, "clean", "F8 revive finished")
    return true
end

-- Every frame while an F8 revive is counting down: stops if they got up or you walked out of range or went down yourself; finishes when
-- the time is up. (Only your position and theirs are looked at: no game object is touched.)
function pstat.revive_tick(now)
    local rv = pstat.reviving
    if not rv then return end
    if pstat.downed then return pstat.revive_cancel("you are down yourself") end
    local ok, why = pstat.revive_ready(now)
    if not ok then return pstat.revive_cancel(why) end
    if now - rv.since >= pstat.revive_hold then
        pstat.reviving = nil
        pstat.revive_finish()
    end
end

net_on(H.PH_MSG, function(payload)
    local now = os.clock()
    local hp, mx, dn = payload:match("^h|(-?[%d%.]+)|(-?[%d%.]+)|([01])$")
    if hp then
        local r = pstat.remote or {}
        pstat.remote = r
        r.hp, r.max, r.at, r.downed = tonumber(hp), tonumber(mx), now, dn == "1"
        pstat.received = pstat.received + 1
        return
    end
    local kind, arg, x, y, z = payload:match("^e|(%a+)|([%w_%.%-]*)|(-?[%d%.]+)|(-?[%d%.]+)|(-?[%d%.]+)$")
    if not kind then return end
    pstat.received = pstat.received + 1
    local r = pstat.remote or {}
    pstat.remote = r
    r.at = now
    local who = H.who_is_there()
    if kind == "heal" or kind == "use" then state.remote_heal_until = now + 2.4 end
    if kind == "down" then
        r.downed = true
        chat_add("Health", string.format("%s is down! Get within %.0f m and use a Herb or Chem Fluid on them, or hold F8 next to them for %.0f s (no item needed).",
            who, pstat.revive_radius, pstat.revive_hold))
        H.note(who .. " is down")
    elseif kind == "up" then
        r.downed = false
        chat_add("Health", who .. " is back up.")
        H.note(who .. " is back up")
    elseif kind == "char" then
        pcall(CFG.who.on_remote, arg, now) -- (9.31: which character they are shown as)
    elseif kind == "mot" then
        pcall(CFG.mbank.on_remote, arg, now) -- (10.1: which bank / clip they play, and what it is)
    elseif kind == "mol" then
        pcall(CFG.mbank.on_remote_overlay, arg, now) -- (10.4: the clip on their overlay layer: a block, a heal)
    elseif kind == "act" then
        pcall(CFG.mbank.on_remote_act, arg, now) -- (10.10: a small action on one of their layers: touching a door, the codex ...)
    elseif kind == "actb" then
        pcall(CFG.mbank.on_remote_act, arg, now, 2) -- (10.14: the second one, on another of their layers)
    elseif kind == "low" then
        pcall(CFG.low.on_remote, arg, now) -- (10.12: how high their camera is above their floor while they crawl or lie down)
    elseif kind == "wpn" then
        pcall(CFG.wpn.on_remote, arg, now) -- (9.31: which weapon they hold)
    elseif kind == "ff" then
        pcall(CFG.ff.receive, arg, now) -- (9.31: friendly fire: they shot me)
    elseif kind == "heal" or kind == "use" or kind == "revive" then
        local lp = state.local_pos
        local dist = lp and math.sqrt((tonumber(x) - lp.x) ^ 2 + (tonumber(y) - lp.y) ^ 2 + (tonumber(z) - lp.z) ^ 2) or nil
        local helped = (kind == "revive" and arg == "") -- F8: they stayed next to you, no item
        local what = helped and "helped you up" or string.format("used a %s", arg ~= "" and arg or "healing item")
        if not pstat.downed then
            if not helped then chat_add("Health", string.format("%s used a %s.", who, arg ~= "" and arg or "healing item")) end
        elseif dist and dist <= pstat.revive_radius * 1.25 then -- a little slack for lag
            H.get_up(string.format("%s %s %.1f m away", who, what, dist))
        else
            H.note(string.format("%s %s but %s: they must be within %.0f m of you", who, what,
                dist and string.format("they were %.1f m away", dist) or "I can't tell how far", pstat.revive_radius))
        end
    end
end)

-- Called every frame.
function pstat.update(now)
    local present = peer_present(now)
    if present and not pstat.peer_was then pstat.sent_at = -10 end -- just connected: tell them at once
    pstat.peer_was = present

    local okk, down = pcall(function() return reframework:is_key_down(pstat.hotkey) end)
    down = okk and down == true
    if down and not pstat.key_was_down then pstat.revive_other() end
    pstat.key_was_down = down
    pstat.revive_tick(now)
    local oka, erra = pcall(CFG.friend.ai.tick, now) -- (10.6) what Ethan's friend does for you (only while it is the friend)
    if not oka and now - (pstat.friend_err_at or 0) > 5 then
        pstat.friend_err_at = now
        say("friend helper error: " .. tostring(erra))
    end
    local okb, errb = pcall(CFG.friend.body.update, now) -- (10.7) ...and what its body does (blocks near enemies, the heal pose)
    if not okb and now - (pstat.friend_body_err_at or 0) > 5 then
        pstat.friend_body_err_at = now
        say("friend body error: " .. tostring(errb))
    end
    local okf2, errf2 = pcall(CFG.friend.fight.update, now) -- (10.8) ...and its fighting: shoots near you, its ammo, heals itself, takes hits
    if not okf2 and now - (pstat.friend_fight_err_at or 0) > 5 then
        pstat.friend_fight_err_at = now
        say("friend fight error: " .. tostring(errf2))
    end
    local okov, errov = pcall(CFG.friend.over.tick, now) -- (10.9) after a game over: up at full health and next to you
    if not okov and now - (pstat.friend_over_err_at or 0) > 5 then
        pstat.friend_over_err_at = now
        say("friend game-over error: " .. tostring(errov))
    end

    if now - pstat.read_at < 0.1 then return end
    pstat.read_at = now
    local go = player_object()
    if not go then return end
    if pstat.hi == nil or (pstat.go_addr and H.address_of(go) ~= pstat.go_addr) then
        if now - pstat.scanned_at < 3 or not H.scan() then return end
    end
    local hp, mx = H.read_health()
    if hp == nil then
        pstat.read_fail = pstat.read_fail + 1
        if pstat.read_fail >= 5 then pstat.hi = nil end -- the object went away (new game, load): look again
        return
    end
    pstat.read_fail = 0
    local prev = pstat.hp
    pstat.hp, pstat.max = hp, mx
    if hp > 1.5 then pstat.alive_seen = true end
    if prev and now > pstat.mute_until then
        local d = hp - prev
        if d > 1.5 then -- (a rise of 1 is the hold fighting the game, not a heal)
            H.on_heal(d, now)
        elseif d < -0.5 then
            pstat.hurts = pstat.hurts + 1
        end
    end

    if pstat.god and H.god_fill() then hp = pstat.hp end -- 9.28: invincible (after the changes above were counted)

    if H.clamp_active(now) and now > pstat.mute_until and (pstat.pending_down or (hp <= 0.5 and pstat.alive_seen)) then
        if hp <= 0.5 and not pstat.downed then
            H.write_health(1)
            pstat.clamped = pstat.clamped + 1
        end
        H.go_down(pstat.pending_down and "a hit that would have killed you" or "your health reached 0")
    end

    if pstat.downed then
        if hp > 1.5 and now > pstat.grace_until and now >= (pstat.no_hold_until or 0) then -- no healing yourself while down
            H.write_health(1)
            if now - (pstat.block_note_at or 0) > 3 then
                pstat.block_note_at = now
                H.note("you can't heal yourself while down: only the other player can get you up")
            end
        end
        if present then
            pstat.alone_since = nil
        else
            pstat.alone_since = pstat.alone_since or now
            if now - pstat.alone_since > 10 then H.get_up("the other player is gone") end
        end
    end

    if present then
        local changed = pstat.sent_hp == nil or math.abs(hp - pstat.sent_hp) >= 1
        if (changed and now - pstat.sent_at >= 0.5) or now - pstat.sent_at >= 3 then H.send_state(now) end
    end
end

-- (10.6) THE FRIEND HELPS: the first part of Ethan's friend's brain. It runs only while the friend is the other player (CFG.friend.present()),
-- never for a real player. re7mp.exe keeps the friend walking after you and stopping 2 m away (10.26: or staying put, when you press F5; there is no "Beside you" any more),
-- so it is normally inside the revive distance (3 m) already; this part decides what it does for you from there:
--   * REVIVE: you are down and it has been within the revive distance for the revive time (3 s, the same two sliders as F8) -> you get up with the
--     usual "health after being revived". No item is used (the wait is the price, as with F8), and it shows its use pose while it works on you.
--   * HEAL: your health is at or below `below` percent (default 40) for a moment (REACT_SECS), it is within the revive distance and it carries a
--     healing item -> it uses one on you: the use takes USE_SECS (its heal pose shows), then the item leaves ITS inventory (re7mp/friend.json)
--     and your health goes up by that item's share of your maximum. Stopped (nothing spent) if you walk out of its reach, go down, or your
--     health is up already. It picks the WEAKEST item that lifts you back over the threshold, else the strongest it has.
-- How much an item gives back (percent of your maximum health) is an estimate from RE7 guides: Herb about 1/4, First Aid Med about 1/3, Strong
-- First Aid Med everything. Nothing here touches the game's own inventory: the items are the friend's own, kept by this script.
CFG.friend.ai = {
    on = true, revive = true, heal = true, below = 40,
    USE_SECS = 2.4,     -- the time its use takes (the script shows a remote player's heal pose for 2.4 s too)
    REACT_SECS = 1.2,   -- your health has to stay low this long before it starts (a single bite does not make it dig for a Herb)
    COOLDOWN = 3.0,     -- after a heal: no new one for this long
    HEAL_PCT = { herb = 25, med = 33, strong = 100 },
    reviving = nil, using = nil, low_since = nil, last_heal_at = -100, no_item_told = false,
    stats = { revives = 0, revives_stopped = 0, heals = 0, heals_stopped = 0, no_item = 0 },
    last = "nothing yet", last_heal = nil, status = "waiting",
}

do
    local A = CFG.friend.ai

    function A.note(text)
        A.last = text
        H.note("Ethan's friend: " .. text)
    end

    -- How much of your maximum health an item gives back (percent), or nil when it is not a healing item. The game's own category wins when this
    -- script has seen the item (category 3 = heal; Chem Fluid is a material); an item never seen is judged by its name.
    function A.heal_pct(id)
        if type(id) ~= "string" then return nil end
        local n, low = items.cat_cache[id], id:lower()
        if n ~= nil and n ~= 3 then return nil end
        if n == nil and not (low:find("herb", 1, true) or low:find("remedy", 1, true) or low:find("firstaid", 1, true) or low:find("first_aid", 1, true)
            or low:find("medic", 1, true)) then return nil end
        if low:find("strong", 1, true) then return A.HEAL_PCT.strong end
        if low:find("herb", 1, true) and not low:find("chem", 1, true) and not low:find("mix", 1, true) then return A.HEAL_PCT.herb end
        return A.HEAL_PCT.med
    end

    -- The healing items it carries: { { id, pct, count }, ... } weakest first.
    function A.carried_heals()
        local F, list = CFG.friend, {}
        F.load()
        for id, n in pairs(F.inv) do
            local p = n >= 1 and A.heal_pct(id) or nil
            if p then list[#list + 1] = { id = id, pct = p, count = n } end
        end
        table.sort(list, function(a, b) if a.pct ~= b.pct then return a.pct < b.pct end return a.id < b.id end)
        return list
    end

    -- Which one would it use at this health (percent)? The weakest that lifts you back over the threshold, else the strongest.
    function A.pick_item(health_pct)
        local list = A.carried_heals()
        if #list == 0 then return nil end
        for _, e in ipairs(list) do
            if health_pct + e.pct > A.below then return e end
        end
        return list[#list]
    end

    function A.stop_all()
        A.reviving, A.using, A.low_since = nil, nil, nil
    end

    -- The end of a use: the health goes up first; only when the game took it does the item leave the friend's inventory.
    function A.finish_heal(u, now)
        local F = CFG.friend
        A.using = nil
        if (F.inv[u.id] or 0) < 1 then
            A.stats.heals_stopped = A.stats.heals_stopped + 1
            A.note("it no longer carries a " .. u.id .. ": nothing used")
            return
        end
        local hp, mx = pstat.hp, pstat.max or pstat.seen_max
        if type(hp) ~= "number" or type(mx) ~= "number" or mx <= 0 then return end
        local target = math.min(mx, hp + mx * u.pct / 100)
        if not H.write_health(target) then
            A.stats.heals_stopped = A.stats.heals_stopped + 1
            A.note("the game would not take the new health: the " .. u.id .. " is not used up")
            return
        end
        F.inv[u.id] = F.inv[u.id] - 1
        if F.inv[u.id] <= 0 then F.inv[u.id] = nil end
        F.save()
        A.stats.heals = A.stats.heals + 1
        A.last_heal_at = now
        A.last_heal = { item = u.id, from = math.floor(hp), to = math.floor(target), left = F.inv[u.id] or 0, at = math.floor(now * 10) / 10 }
        A.note(string.format("used a %s on you: health %.0f -> %.0f of %.0f (it has %d left)", u.id, hp, target, mx, F.inv[u.id] or 0))
        chat_add("Health", string.format("%s used a %s on you.", F.NAME, u.id))
    end

    -- Every frame (from pstat.update): what it is doing for you right now.
    function A.tick(now)
        local F = CFG.friend
        if not A.on or not F.present() or not peer_present(now) then
            if A.reviving or A.using then A.stop_all() end
            A.status = A.on and "it is not here" or "switched off"
            return
        end
        local r = pstat.remote
        if r and r.downed and now - r.at < 10 then -- it is down itself (the panel's test button): it can't help
            A.stop_all()
            A.status = "it is down itself"
            return
        end
        local d = H.remote_distance()
        local near = d ~= nil and d <= pstat.revive_radius
        if pstat.downed then
            A.using, A.low_since = nil, nil
            if not A.revive then A.status = "revive is switched off" return end
            if not near then
                if A.reviving then
                    A.reviving = nil
                    A.stats.revives_stopped = A.stats.revives_stopped + 1
                    A.note(string.format("stopped helping you up: it is %s away (it has to stay within %.0f m)", d and string.format("%.1f m", d) or "somewhere", pstat.revive_radius))
                end
                A.status = string.format("you are down and it is %s away", d and string.format("%.1f m", d) or "somewhere")
                return
            end
            if not A.reviving then
                A.reviving = { since = now }
                A.note(string.format("is helping you up: it stays within %.0f m for %.0f s", pstat.revive_radius, pstat.revive_hold))
            end
            state.remote_heal_until = now + 0.3 -- its use pose shows while it works on you
            A.status = string.format("helping you up %.1f / %.0f s", math.min(now - A.reviving.since, pstat.revive_hold), pstat.revive_hold)
            if now - A.reviving.since >= pstat.revive_hold then
                A.reviving = nil
                A.stats.revives = A.stats.revives + 1
                chat_add("Health", F.NAME .. " helped you up.")
                H.get_up(string.format("%s helped you up, %.1f m away, no item used", F.NAME, d))
                A.last = string.format("helped you up (%.1f m away)", d)
            end
            return
        end
        A.reviving = nil
        local hp, mx = pstat.hp, pstat.max or pstat.seen_max
        if not A.heal then A.using, A.low_since = nil, nil A.status = "heal is switched off" return end
        if type(hp) ~= "number" or type(mx) ~= "number" or mx <= 0 then
            A.using, A.low_since = nil, nil
            A.status = "your health is not readable yet"
            return
        end
        local pct = hp / mx * 100
        local low = pct <= A.below and hp > 0.5
        if not low then A.no_item_told = false end
        if A.using then
            local u, why = A.using, nil
            if not near then why = string.format("you are out of its reach (%s)", d and string.format("%.1f m", d) or "no position")
            elseif not low then why = "your health is up already" end
            if why then
                A.using = nil
                A.stats.heals_stopped = A.stats.heals_stopped + 1
                A.note(string.format("stopped using the %s: %s (nothing spent)", u.id, why))
                return
            end
            state.remote_heal_until = now + 0.3
            A.status = string.format("using a %s on you %.1f / %.1f s", u.id, math.min(now - u.since, A.USE_SECS), A.USE_SECS)
            if now - u.since >= A.USE_SECS then A.finish_heal(u, now) end
            return
        end
        if not low then
            A.low_since = nil
            A.status = string.format("your health is %.0f%% (it helps at %d%% or less)", pct, A.below)
            return
        end
        if not near then
            A.low_since = nil
            A.status = string.format("your health is %.0f%% but it is %s away (it has to be within %.0f m)", pct, d and string.format("%.1f m", d) or "somewhere", pstat.revive_radius)
            return
        end
        A.low_since = A.low_since or now
        if now - A.last_heal_at < A.COOLDOWN then
            A.status = "it has just used one on you"
            return
        end
        if now - A.low_since < A.REACT_SECS then
            A.status = string.format("your health is %.0f%%: it is about to help", pct)
            return
        end
        local e = A.pick_item(pct)
        if e then
            A.using = { id = e.id, pct = e.pct, since = now }
            A.note(string.format("is using a %s on you (your health %.0f%%, it gives %d%%, %.1f s)", e.id, pct, e.pct, A.USE_SECS))
        else
            A.status = string.format("your health is %.0f%% and it carries no healing item", pct)
            if not A.no_item_told then
                A.no_item_told = true
                A.stats.no_item = A.stats.no_item + 1
                A.note(string.format("your health is %.0f%% but it carries no healing item: give it a Herb or First Aid Med (F7 next to it)", pct))
                chat_add("Health", F.NAME .. " has nothing to heal you with. Give it a Herb or First Aid Med.")
            end
        end
    end

    function A.report()
        local carried = {}
        for _, e in ipairs(A.carried_heals()) do carried[#carried + 1] = { id = e.id, gives_percent = e.pct, count = e.count } end
        local d = H.remote_distance()
        return { on = A.on, revive = A.revive, heal = A.heal, heals_you_at_percent_or_less = A.below, status = A.status, last = A.last,
            distance_m = d and math.floor(d * 10) / 10 or nil, reach_m = pstat.revive_radius, revive_seconds = pstat.revive_hold,
            helping_you_up = A.reviving ~= nil, using_item = A.using and A.using.id or nil, healing_items = carried,
            percent_given = { herb = A.HEAL_PCT.herb, first_aid_med = A.HEAL_PCT.med, strong_first_aid_med = A.HEAL_PCT.strong },
            use_seconds = A.USE_SECS, react_seconds = A.REACT_SECS, cooldown_seconds = A.COOLDOWN,
            revived_you = A.stats.revives, revive_stopped = A.stats.revives_stopped, healed_you = A.stats.heals, heal_stopped = A.stats.heals_stopped,
            low_health_without_item = A.stats.no_item, last_heal = A.last_heal }
    end
end

-- (10.7) ETHAN'S FRIEND ACTS FOR ITSELF (the "Ethan's friend does" choice "Acts for itself", the default now; "Copies me" is still there). re7mp.exe only
-- moves the friend (it walks after you); everything the body shows comes from here:
--   * POSE: the flags the exe copies from you (crouch, gun, block ...) are dropped. The friend blocks when an enemy is close to it, shows the heal pose
--     while it helps you (CFG.friend.ai), and otherwise walks, runs or stands by how fast it really moves. Your clips are no longer fed to its body.
--   * FACING: the way it LAST MOVED (it kept your camera's direction before, so the model looked outwards all the time); at a block it faces the enemy.
--   * HEIGHT: it stands where YOU stood. The exe puts it at your height, so on stairs or any step it hung in the air. The script keeps a trail of the
--     places you walked (a point every 0.25 m, the floor under the camera) and takes the friend's height from the nearest point of that trail, the way the other
--     co-op mod keeps its bot on real ground (no ray casts: they are not reliable in this game). Nothing is read from the game for it.
CFG.friend.body = {
    TRAIL_MAX = 500, STEP = 0.25, NEAR = 2.0, FAR = 6.0,   -- the trail: a point every STEP metres (500 = 125 m of path); look within NEAR m, else the nearest within FAR m
    BLOCK_DIST = 1.0, BLOCK_MIN = 0.5, BLOCK_MAX = 5.0, BLOCK_GAP = 0.4, THREAT_EVERY = 0.25, -- (10.9) it blocks only when an enemy is within 1 m (was 5 m); lets go at BLOCK_DIST + BLOCK_GAP
    LET_GO_SECS = 1.0, OVERLAY_EVERY = 1.5,
    GUARD_PAIR = "0_2300_guard.0", HEAL_PAIR = "0_2790_heal.0", -- Hands_Guard_Loop and Hands_Recovery of Ethan's bank
    roots = {}, scan_at = -10, scans = 0, trail = {}, trail_n = 0, heading = nil, last_target = nil, ground = nil, adjusted = 0, from_trail = 0, from_player = 0, resets = 0,
    threat = nil, threat_at = -10, blocking = false, block_seen_at = -10, blocks = 0, enemies_seen = 0, enemy_note = "no enemy read yet",
    overlay_key = "none", overlay_at = -10, overlay_fed = 0, last_ground_note = nil,
}

do
    local B = CFG.friend.body

    function B.own_on()
        return CFG.friend.present() and CFG.who ~= nil and CFG.who.bot_act == "own"
    end

    -- (10.10) "I dont think its telling the ground height below it very well": the trail took the floor as the camera height minus a GUESS (1.6 m standing, 0.5 m less crouched), so a
    -- crouched stretch of the path was 0.2 m off (the real camera drop is about 0.7 m) and a jump, a landing or the camera bob moved the floor with it. Now the floor under me is read
    -- from my OWN player object (the object manager's PlayerObj: its position is where its feet are). A reading is used only when the camera is a believable height above it (standing
    -- 1.3 to 1.9 m, crouched 0.7 to 1.7 m): an object whose origin is not at the feet cannot slip in, and the guess is used for that point as before.
    B.root = { on = true, at = -10, y = nil, reads = 0, used = 0, rejected = 0, failures = 0, last_error = nil, last_off = nil, standing_off = nil, crouched_off = nil, LO = { 1.3, 0.7 }, HI = { 1.9, 1.7 } }
    function B.player_floor(cam_y, crouching)
        local R = B.root
        if not R.on or type(cam_y) ~= "number" then return nil end
        local now = os.clock()
        if R.y == nil or now - R.at >= 0.1 then
            R.at = now
            local ok, y = pcall(function()
                local om = sdk.get_managed_singleton("app.ObjectManager")
                local p = om and om:get_field("PlayerObj")
                if p == nil then return nil end
                local xf = p:call("get_Transform")
                local v = xf and xf:call("get_Position")
                return v and tonumber(v.y)
            end)
            if not ok then
                R.failures, R.last_error, R.y = R.failures + 1, tostring(y):sub(1, 100), nil
                return nil
            end
            R.y = y
            if y ~= nil then R.reads = R.reads + 1 end
        end
        if R.y == nil then return nil end
        local off = cam_y - R.y
        R.last_off = off
        local k = crouching and 2 or 1
        if off < R.LO[k] or off > R.HI[k] then R.rejected = R.rejected + 1 return nil end
        if crouching then R.crouched_off = off else R.standing_off = off end
        R.used = R.used + 1
        return R.y
    end

    -- A point of the trail: where the floor was under my camera. Only while the friend is here.
    function B.note_player(pos, crouching)
        if not CFG.friend.present() or type(pos) ~= "table" then return end
        local fy = B.player_floor(pos.y, crouching) or (pos.y - (CFG.EYE_HEIGHT - CFG.CROUCH_DROP * (crouching and 1 or 0)))
        local T, n = B.trail, #B.trail
        local last = T[n]
        if last then
            local dx, dz = pos.x - last.x, pos.z - last.z
            if dx * dx + dz * dz < B.STEP * B.STEP and math.abs(fy - last.y) < 0.12 then return end
            if dx * dx + dz * dz > 400 then -- a jump of 20 m (a load, a teleport): the old path is not this place any more
                B.trail, B.resets, n = {}, B.resets + 1, 0
                T = B.trail
            end
        end
        T[n + 1] = { x = pos.x, z = pos.z, y = fy }
        if n + 1 > B.TRAIL_MAX then table.remove(T, 1) end
        B.trail_n = B.trail_n + 1
    end

    -- The floor height for the friend at (x, z): the nearest crumb within NEAR m (nearest in height to where it stood when several floors overlap), else the
    -- nearest within FAR m, else the floor under me now. Returns the height and where it came from.
    function B.ground_y(x, z, cur)
        local T = B.trail
        local best, bs, near_any, nd = nil, 1e9, nil, 1e9
        for i = #T, math.max(1, #T - B.TRAIL_MAX), -1 do
            local c = T[i]
            local dx, dz = c.x - x, c.z - z
            local d2 = dx * dx + dz * dz
            if d2 <= B.NEAR * B.NEAR then
                local dy = cur and (c.y - cur) or 0
                local score = d2 + 0.25 * dy * dy
                if score < bs then best, bs = c, score end
            end
            if d2 < nd then near_any, nd = c, d2 end
        end
        if best then return best.y, "trail" end
        if near_any and nd <= B.FAR * B.FAR then return near_any.y, "trail (far)" end
        return nil, "player"
    end

    -- Every new position of the friend from the exe (read_remote): its height from the trail, and the way it moved.
    function B.adjust(target, now)
        local lp = state.local_pos
        local fy, how = B.ground_y(target.x, target.z, B.ground)
        if fy == nil and lp then
            local cr = (state.local_pose and state.local_pose.crouch) and true or false
            fy = B.player_floor(lp.y, cr) or (lp.y - (CFG.EYE_HEIGHT - CFG.CROUCH_DROP * (cr and 1 or 0)))
        end
        if fy ~= nil then
            B.ground = fy
            target.y = fy + CFG.EYE_HEIGHT
            B.adjusted = B.adjusted + 1
            if how == "trail" or how == "trail (far)" then B.from_trail = B.from_trail + 1 else B.from_player = B.from_player + 1 end
        end
        local lt = B.last_target
        if lt then
            local dx, dz = target.x - lt.x, target.z - lt.z
            local len = math.sqrt(dx * dx + dz * dz)
            if len >= 0.015 and len < CFG.TELEPORT_DISTANCE then B.heading = { dx / len, dz / len } end
        end
        B.last_target = { x = target.x, z = target.z }
    end

    -- Which way the body faces (x, z) or nil to leave it to the camera quaternion. At a block it faces the enemy it blocks.
    function B.facing(pos)
        if B.blocking and B.threat and pos then
            local dx, dz = B.threat.x - pos.x, B.threat.z - pos.z
            local len = math.sqrt(dx * dx + dz * dz)
            if len > 0.2 then return dx / len, dz / len end
        end
        local FT = CFG.friend.fight
        if FT and FT.aiming and FT.target and pos then -- (10.8) it faces what it shoots at
            local dx, dz = FT.target.x - pos.x, FT.target.z - pos.z
            local len = math.sqrt(dx * dx + dz * dz)
            if len > 0.2 then return dx / len, dz / len end
        end
        if B.heading then return B.heading[1], B.heading[2] end
        local lp = state.local_pos
        if lp and pos then
            local dx, dz = lp.x - pos.x, lp.z - pos.z
            local len = math.sqrt(dx * dx + dz * dz)
            if len > 0.2 then return dx / len, dz / len end
        end
        return nil
    end

    -- The pose bits of the friend's flags: yours are dropped, its own are added (the ready bits and the rest stay).
    function B.own_flags(f, now)
        local low = f % 64
        local high = f - (f % 16384) -- (10.12: bit 13 is "running", the friend's own)
        local out = low + high
        if B.blocking then out = out + CFG.POSE_GUARD end
        -- (10.8) it crouches when you crouch (so you can both hide from the same thing, though it does not know it is hiding)
        if state.local_pose and state.local_pose.crouch then out = out + CFG.POSE_CROUCH end
        -- (10.8) the fighting friend: a gun in hand while it has a target, aiming at it, and the shot pose for a moment after each shot
        local FT = CFG.friend.fight
        if FT and FT.drawn then
            out = out + CFG.POSE_GUN
            if FT.aiming then out = out + CFG.POSE_AIM end
            if now < FT.shot_until then out = out + CFG.POSE_SHOOT end
        end
        return out
    end

    -- The nearest live enemy to the friend: { name, x, y, z, dist } or nil. The list is the enemy sync's (enemy.roots, scanned once a second); with no
    -- enemy sync running the friend scans for itself on the same timer. Only enemies that are close are looked at closely: the ones the game parks
    -- (not started, no animation, at the origin, no Status component) and the dead do not count.
    -- The list of enemies to look at: the enemy sync's, or (when that is not scanning) one the friend keeps itself, scanned once a second.
    function B.enemy_list(now)
        local list = enemy.roots
        if not (now - enemy.last_scan < 2.0) then
            if now - B.scan_at >= 1.0 then
                B.scan_at = now
                local ok, roots = pcall(find_enemy_roots, B.roots)
                if ok then B.roots, B.scans = roots, B.scans + 1 end
            end
            list = B.roots
        end
        return list or {}
    end

    -- Is this enemy alive and playing (not parked by the game, not dead)? p is its position.
    function B.is_live(e, p)
        pcall(read_health, e) -- (finds its Status component the first time)
        local okm, _, motion = pcall(read_motion, e)
        local okf, inactive = pcall(inactive_flags, e, okm and motion or 0, p)
        local okd, dead = pcall(enemy_is_dead, e)
        return okf and inactive == 0 and not (okd and dead)
    end

    function B.nearest_enemy(now)
        local r = state.remote
        if not (r and r.pos) then return nil end
        local list = B.enemy_list(now)
        local gy = B.ground or (r.pos.y - CFG.EYE_HEIGHT)
        local best, bd, n = nil, 1e9, 0
        for _, e in ipairs(list or {}) do
            local okp, p = pcall(function() return e.xf:call("get_Position") end)
            if okp and p ~= nil and finite(p.x) and finite(p.y) and finite(p.z) then
                local dx, dz = p.x - r.pos.x, p.z - r.pos.z
                local d = math.sqrt(dx * dx + dz * dz)
                if d <= B.BLOCK_DIST + B.BLOCK_GAP + 0.5 and math.abs(p.y - gy) < 3.5 then
                    if B.is_live(e, p) then
                        n = n + 1
                        if d < bd then best, bd = { name = e.name, x = p.x, y = p.y, z = p.z, dist = d }, d end
                    end
                end
            end
        end
        B.enemies_seen = n
        return best
    end

    local function feed(key, now)
        local M = CFG.mbank
        if key == B.overlay_key and now - B.overlay_at < B.OVERLAY_EVERY then return end
        B.overlay_key, B.overlay_at = key, now
        B.overlay_fed = B.overlay_fed + 1
        pcall(M.on_remote_overlay, key == "none" and "0_0_none" or key, now)
    end

    -- Every frame (from pstat.update, after the helper): look for enemies four times a second, block while one is close, and tell the body what to play.
    function B.update(now)
        if not B.own_on() or not peer_present(now) then
            B.blocking, B.threat = false, nil
            B.enemy_note = "the friend is not acting for itself"
            return
        end
        if now - B.threat_at >= B.THREAT_EVERY then
            B.threat_at = now
            local ok, e = pcall(B.nearest_enemy, now)
            B.threat = ok and e or nil
            if not ok then B.enemy_note = "enemy read failed: " .. tostring(e):sub(1, 80) end
            if B.threat then
                B.block_seen_at = now
                B.enemy_note = string.format("nearest enemy %s, %.1f m from it", tostring(B.threat.name), B.threat.dist)
            elseif ok then
                B.enemy_note = string.format("no live enemy near it (%d read)", B.enemies_seen)
            end
        end
        -- (10.9) how long its body takes to get down after you crouch (the debug file says it: "it takes a second")
        do
            local lc = state.local_pose and state.local_pose.crouch == true
            if lc ~= B.cr_want then B.cr_want, B.cr_since, B.cr_lag = lc, now, nil end
            local pc = (state.pose and state.pose.crouch) or 0
            if B.cr_since and B.cr_lag == nil and ((lc and pc >= 0.9) or (not lc and pc <= 0.1)) then B.cr_lag = now - B.cr_since end
        end
        local A = CFG.friend.ai
        local FT = CFG.friend.fight
        local busy = (A and (A.using ~= nil or A.reviving ~= nil)) or (FT and FT.healing ~= nil) or false
        local r = pstat.remote
        local down = r and r.downed and now - r.at < 10
        local t = B.threat
        local want = false
        -- (10.8) with a gun and ammo it shoots instead of blocking; it blocks when it cannot shoot (no gun, no ammo, reloading)
        local shooting = FT and FT.aiming and FT.can_shoot
        if not busy and not down and not shooting and t then
            want = t.dist <= (B.blocking and (B.BLOCK_DIST + B.BLOCK_GAP) or B.BLOCK_DIST)
        end
        if want then
            if not B.blocking then
                B.blocking, B.blocks = true, B.blocks + 1
                say(string.format("health: Ethan's friend blocks: %s is %.1f m from it", tostring(t.name), t.dist))
            end
        elseif B.blocking and now - B.block_seen_at >= B.LET_GO_SECS or (B.blocking and (busy or down or shooting)) then
            B.blocking = false
            say("health: Ethan's friend lowers its guard")
        end
        -- its clips: the heal while it helps you, the block while it blocks (the receiving side plays them or, with no such clip, its recorded clips)
        local key = "none"
        if busy then key = B.HEAL_PAIR elseif B.blocking then key = B.GUARD_PAIR end
        feed(key, now)
    end

    function B.report()
        return { acting_for_itself = B.own_on(), blocking = B.blocking, blocks = B.blocks, nearest_enemy = B.threat and { name = B.threat.name, metres = math.floor(B.threat.dist * 10) / 10 } or nil,
            enemies = B.enemy_note, block_within_m = B.BLOCK_DIST, block_lets_go_at_m = B.BLOCK_DIST + B.BLOCK_GAP, enemy_scans = B.scans, trail_points = #B.trail, trail_points_written = B.trail_n, trail_resets = B.resets,
            heading = B.heading and { x = math.floor(B.heading[1] * 100) / 100, z = math.floor(B.heading[2] * 100) / 100 } or nil,
            crouch = { you_crouching = B.cr_want == true, body_down_after_s = B.cr_lag and math.floor(B.cr_lag * 100) / 100 or nil, body_lift_m = math.floor(CFG.body.crouch_lift() * 100) / 100, slider_m = CFG.friend.crouch_lift,
                feet = CFG.friend.ground.report(), camera_drop_seen_m = CFG.friend.ground.cam_drop and math.floor(CFG.friend.ground.cam_drop * 100 + 0.5) / 100 or nil },
            floor_y = B.ground and math.floor(B.ground * 100) / 100 or nil, heights_set = B.adjusted, from_trail = B.from_trail, from_my_floor = B.from_player,
            floor_under_me = { read_from_my_own_object = B.root.on, readings = B.root.reads, used_for_the_trail = B.root.used, rejected_as_unbelievable = B.root.rejected, failures = B.root.failures, last_error = B.root.last_error,
                camera_above_it_m_last = B.root.last_off and math.floor(B.root.last_off * 100 + 0.5) / 100 or nil, standing_m = B.root.standing_off and math.floor(B.root.standing_off * 100 + 0.5) / 100 or nil,
                crouched_m = B.root.crouched_off and math.floor(B.root.crouched_off * 100 + 0.5) / 100 or nil, believable_standing_m = B.root.LO[1] .. " to " .. B.root.HI[1], believable_crouched_m = B.root.LO[2] .. " to " .. B.root.HI[2] },
            overlay_now = B.overlay_key, overlay_sent = B.overlay_fed }
    end
end

----------------------------------------------------------------------------------------------
-- (10.8) THE FIGHTING FRIEND. While it acts for itself (CFG.friend.body) it shoots at the enemies that are NEAR YOU, with its own weapons and its own
-- ammo (what you gave it, F7 within 3 m: they left your inventory), takes ammo out of its own inventory shot by shot and tells you when it runs out.
--   * TARGET: a live enemy within NEAR_YOU m of YOU and within REACH m of the friend, the one nearest to you. Line of sight is IGNORED (the ray casts
--     are not reliable in this game, and the friend stands close to you anyway).
--   * WEAPON: the carried gun with ammo that does the most damage per second; it keeps it until its ammo is gone. The ammo is the gun's own kind
--     (HandgunBullet for a handgun, ShotgunBullet for a shotgun, ...).
--   * DAMAGE: the gun's table damage (CFG.wpn.DAMAGE) x the same scale the other player's shots use (HIT.gun_scale), handed to the game's own damage call
--     (HIT.apply) with the same correction for what the game really takes off. One shot every gap seconds, a reload after every magazine.
--   * SELF-HEAL: below heal_below % of its own health it uses a healing item from its own inventory on itself (2.4 s), unless it is busy with you.
--   * DAMAGE TAKEN: SIMULATED. The enemies' own AI does not know the friend exists, so an enemy that gets within HURT_REACH m of it takes hurt_pct % of its
--     health off every HURT_EVERY s (less while it blocks); the hit goes to the exe as the same "ff" event a friendly-fire hit uses, and at 1 health it goes down
--     and you get it up the usual way (F8 within 3 m, or a heal). The health lives in the exe; "hp:<n>" (exe 10.8) sets it for a heal.
-- None of it runs unless the friend is here and acts for itself.
----------------------------------------------------------------------------------------------
CFG.friend.fight = {
    on = true, heal_self = true, heal_below = 40, hurt_pct = 8,
    NEAR_YOU = 5.0, NEAR_MIN = 2.0, NEAR_MAX = 25.0, REACH = 25.0,
    SCAN_EVERY = 0.25, HURT_REACH = 1.6, HURT_EVERY = 1.2, HURT_BLOCKED = 0.4,
    -- (10.10) "ethans friend should shoot slower, 300ms delay minimum": the shortest time between two of its shots, whatever the gun (a slider, 100-2000 ms)
    MIN_GAP = 0.3, MIN_GAP_LO = 0.1, MIN_GAP_HI = 2.0,
    USE_SECS = 2.4, HEAL_COOLDOWN = 4.0, LOW_AMMO = 5, OUT_TELL_EVERY = 25, NO_GUN_TELL_EVERY = 60, NO_HEAL_TELL_EVERY = 60,
    SAVE_EVERY = 2.0, SHOT_POSE_SECS = 0.4, DRAWN_SECS = 3.0, VERIFY_SECS = 2.0, WPN_EVERY = 10,
    -- per kind of gun: seconds between shots, rounds in a magazine, seconds to reload, the damage when the gun is not in CFG.wpn.DAMAGE
    FAMILY = {
        handgun = { gap = 0.55, mag = 15, reload = 1.7, dmg = 100 },
        shotgun = { gap = 1.1, mag = 6, reload = 2.4, dmg = 90 },
        machinegun = { gap = 0.14, mag = 30, reload = 2.0, dmg = 50 },
        magnum = { gap = 1.3, mag = 6, reload = 2.6, dmg = 1200 },
        other = { gap = 0.8, mag = 10, reload = 2.0, dmg = 100 },
    },
    target = nil, targets_near = 0, hurters = {}, scan_at = -10, scans = 0,
    weapon = nil, mag_left = 0, next_shot_at = 0, reload_until = 0, reloading = false,
    aiming = false, drawn = false, can_shoot = false, draw_until = 0, shot_until = 0,
    healing = nil, last_heal_at = -100, verify = nil, exe_old = false,
    hurt_at = setmetatable({}, { __mode = "k" }), dead = setmetatable({}, { __mode = "k" }), DEAD_SKIP = 8, was_down = false,
    out_told_at = -100, no_gun_told_at = -100, no_heal_told_at = -100, low_told = nil,
    dirty = false, saved_at = -10, wpn_told = nil, wpn_told_at = -100,
    state = "not here", last = "nothing yet", last_tell = nil,
    stats = { shots = 0, hits = 0, failed = 0, damage_dealt = 0, kills = 0, ammo_used = 0, reloads = 0, out_of_ammo = 0, no_gun = 0, low_ammo = 0,
        heals = 0, heals_stopped = 0, no_heal_item = 0, hurts = 0, damage_taken = 0, times_down = 0, exe_old_hits = 0 },
}

do
    local FT = CFG.friend.fight
    local B = CFG.friend.body
    local function clampn(v, lo, hi) return math.max(lo, math.min(hi, v)) end

    function FT.note(text)
        FT.last = text
        H.note("Ethan's friend: " .. text)
    end

    -- Something it says to you: the chat's top-left lines and the journal.
    function FT.tell(text)
        FT.last_tell = text
        chat_add(CFG.friend.NAME, text)
        say("friend: " .. text)
    end

    function FT.key(id) return (tostring(id):lower():gsub("[^%w]", "")) end

    local FAMILIES = { "shotgun", "machinegun", "magnum", "handgun" }

    function FT.weapon_family(id)
        local k = FT.key(id)
        for _, f in ipairs(FAMILIES) do
            if k:find(f, 1, true) then return f end
        end
        return "other"
    end

    -- The kind of gun this ammunition fits ("handgun", ...), or nil when the item is not ammunition. The game's own category (2 = ammo) wins when it is known.
    function FT.ammo_family(id)
        if type(id) ~= "string" then return nil end
        local k, cat = FT.key(id), items.cat_cache[id]
        if cat ~= nil and cat ~= 2 then return nil end
        if cat == nil and not (k:find("bullet", 1, true) or k:find("ammo", 1, true) or k:find("shell", 1, true) or k:find("cartridge", 1, true)) then return nil end
        for _, f in ipairs(FAMILIES) do
            if k:find(f, 1, true) then return f end
        end
        if k:find("shell", 1, true) then return "shotgun" end
        return "other"
    end

    function FT.is_gun(id)
        if FT.ammo_family(id) then return false end
        local kind = CFG.wpn.kind_of(id)
        if kind == "gun" then return true end
        return kind == nil and items.cat_cache[id] == 1 and not FT.key(id):find("knife", 1, true)
    end

    -- What it carries that matters here: guns { id, family }, and the ammo per kind { total, ids = { id, ... } }.
    function FT.arsenal()
        local F = CFG.friend
        F.load()
        local guns, ammo = {}, {}
        local ids = {}
        for id, n in pairs(F.inv) do
            if n >= 1 then ids[#ids + 1] = id end
        end
        table.sort(ids)
        for _, id in ipairs(ids) do
            local n = F.inv[id]
            local af = FT.ammo_family(id)
            if af then
                local a = ammo[af] or { total = 0, ids = {} }
                ammo[af] = a
                a.total = a.total + n
                a.ids[#a.ids + 1] = id
            elseif FT.is_gun(id) then
                guns[#guns + 1] = { id = id, family = FT.weapon_family(id) }
            end
        end
        return guns, ammo
    end

    function FT.damage_of(gun)
        local d = CFG.wpn.damage_of(gun.id)
        return d or FT.FAMILY[gun.family].dmg
    end

    -- The gun it shoots with: the one it already has while it still has ammo, else the best it can load (most damage per second).
    function FT.pick_weapon()
        local guns, ammo = FT.arsenal()
        local W = FT.weapon
        if W then
            for _, g in ipairs(guns) do
                if g.id == W.id and ((ammo[g.family] and ammo[g.family].total >= 1) or (ammo.other and ammo.other.total >= 1)) then
                    return W, #guns, ammo
                end
            end
        end
        local best, best_dps
        for _, g in ipairs(guns) do
            local af = (ammo[g.family] and ammo[g.family].total >= 1) and g.family or ((ammo.other and ammo.other.total >= 1) and "other" or nil) -- (ammo whose kind the name does not tell fits any gun)
            if af then
                local fam = FT.FAMILY[g.family]
                local dmg = FT.damage_of(g)
                local dps = dmg / fam.gap
                if not best or dps > best_dps then best, best_dps = { id = g.id, family = g.family, ammo_family = af, damage = dmg }, dps end
            end
        end
        if best and (not W or W.id ~= best.id) then
            FT.mag_left, FT.reloading, FT.reload_until = math.min(FT.FAMILY[best.family].mag, ammo[best.ammo_family].total), false, 0
            say(string.format("friend: it takes up its %s (%s, %d damage a shot, %d rounds)", best.id, best.family, best.damage, ammo[best.ammo_family].total))
        end
        return best, #guns, ammo
    end

    function FT.ammo_left(family)
        local _, ammo = FT.arsenal()
        return ammo[family] and ammo[family].total or 0
    end

    -- One round out of its inventory (the first ammunition item of the gun's kind). Returns the id or nil.
    function FT.use_round(family)
        local F = CFG.friend
        local _, ammo = FT.arsenal()
        local a = ammo[family]
        if not a then return nil end
        local id = a.ids[1]
        F.inv[id] = (F.inv[id] or 0) - 1
        if F.inv[id] <= 0 then F.inv[id] = nil end
        FT.dirty = true
        FT.stats.ammo_used = FT.stats.ammo_used + 1
        return id
    end

    function FT.flush(now)
        if FT.dirty and now - FT.saved_at >= FT.SAVE_EVERY then
            FT.dirty, FT.saved_at = false, now
            CFG.friend.save()
        end
    end

    -- The friend's own health as the exe reports it: hp, max, down. nil when nothing was heard lately.
    function FT.health(now)
        local r = pstat.remote
        if not (r and r.hp and r.at and now - r.at < 15) then return nil end
        return r.hp, (r.max and r.max > 0) and r.max or 1000, r.downed == true
    end

    -- Look at the enemies: the one to shoot at (nearest to YOU within NEAR_YOU, and within REACH of the friend) and the ones that reach the friend.
    function FT.scan(now)
        FT.scan_at, FT.scans = now, FT.scans + 1
        local lp, r = state.local_pos, state.remote
        FT.target, FT.targets_near, FT.hurters = nil, 0, {}
        if not (lp and r and r.pos) then return end
        local gy = lp.y - CFG.EYE_HEIGHT
        local bd
        for _, e in ipairs(B.enemy_list(now)) do
            local okp, p = pcall(function() return e.xf:call("get_Position") end)
            if okp and p ~= nil and finite(p.x) and finite(p.y) and finite(p.z) and math.abs(p.y - gy) < 4 then
                local dp = math.sqrt((p.x - lp.x) ^ 2 + (p.z - lp.z) ^ 2)
                local df = math.sqrt((p.x - r.pos.x) ^ 2 + (p.z - r.pos.z) ^ 2)
                if ((dp <= FT.NEAR_YOU and df <= FT.REACH) or df <= FT.HURT_REACH) and not (FT.dead[e] and now - FT.dead[e] < FT.DEAD_SKIP) then
                    if B.is_live(e, p) then
                        if dp <= FT.NEAR_YOU and df <= FT.REACH then
                            FT.targets_near = FT.targets_near + 1
                            if not bd or dp < bd then
                                bd = dp
                                FT.target = { e = e, name = e.name, x = p.x, y = p.y, z = p.z, dist_you = dp, dist_it = df }
                            end
                        end
                        if df <= FT.HURT_REACH then FT.hurters[#FT.hurters + 1] = e end
                    end
                end
            end
        end
    end

    -- (10.10) the seconds between two shots of a kind of gun: the gun's own gap, never shorter than the minimum (300 ms unless the slider says otherwise)
    function FT.gap_of(family)
        local fam = FT.FAMILY[family] or FT.FAMILY.other
        return math.max(fam.gap, FT.MIN_GAP)
    end

    -- One shot at the target. Returns true when a round was fired.
    function FT.shoot(now, t, W)
        local st = FT.stats
        local HIT = enemy.hit -- (the enemy hit code's table)
        if not HIT then return false end
        local hp0 = read_health(t.e)
        if type(hp0) == "number" and hp0 == 0 then -- already at 0: no round is wasted (the game may take a while to say the enemy is dead)
            FT.dead[t.e], FT.target = now, nil
            return false
        end
        local id = FT.use_round(W.ammo_family or W.family)
        if not id then return false end
        FT.mag_left = FT.mag_left - 1
        FT.next_shot_at = now + FT.gap_of(W.family)
        FT.shot_until = now + FT.SHOT_POSE_SECS
        st.shots = st.shots + 1
        local scale = HIT.gun_scale or 2.1
        local meant = clampn(math.floor(W.damage * scale + 0.5), 1, HIT.MAX)
        local handed = meant
        local rr = HIT.ratios[t.name] or HIT.ratio -- the game's own multiplier for this enemy, when earlier hits measured it
        if rr and rr > 0 then handed = clampn(math.floor(meant / rr + 0.5), 1, 3 * HIT.MAX) end
        local ok, okc, how, before, after = pcall(HIT.apply, t.e, handed)
        if not ok then okc, how, before, after = false, tostring(okc), -1, -1 end
        if okc then
            st.hits = st.hits + 1
            if type(before) == "number" and type(after) == "number" and before >= 0 and after >= 0 and before > after then st.damage_dealt = st.damage_dealt + (before - after) end
            if (how == "addManualDamage" or how == "addHitDamage") and type(before) == "number" and before > 0 then
                HIT.pending[#HIT.pending + 1] = { e = t.e, name = t.name, before = before, handed = handed, at = now }
                while #HIT.pending > 4 do table.remove(HIT.pending, 1) end
            end
            local dead = false
            if type(after) == "number" and after <= 0 then dead = true else
                local okd, d = pcall(enemy_is_dead, t.e)
                dead = okd and d == true
            end
            if dead then
                st.kills = st.kills + 1
                FT.dead[t.e], FT.target = now, nil
            end
            FT.last = string.format("shot %s at %s (%.1f m from you): %d meant, %d handed, by %s, health %s -> %s%s", W.id, tostring(t.name), t.dist_you,
                meant, handed, tostring(how), tostring(before), tostring(after), dead and " (dead)" or "")
        else
            st.failed = st.failed + 1
            FT.last = string.format("shot %s at %s: the game would not take the damage (%s)", W.id, tostring(t.name), tostring(how))
        end
        say("friend: " .. FT.last)
        local af = W.ammo_family or W.family
        local left = FT.ammo_left(af)
        if left > 0 and left <= FT.LOW_AMMO and FT.low_told ~= af then
            FT.low_told = af
            st.low_ammo = st.low_ammo + 1
            FT.tell(string.format("Running low on %s ammo: %d left.", af == "other" and "its" or af, left))
        elseif left > FT.LOW_AMMO then
            if FT.low_told == af then FT.low_told = nil end
        end
        if left <= 0 then
            FT.mag_left = 0
        elseif FT.mag_left <= 0 then
            FT.reloading, FT.reload_until = true, now + FT.FAMILY[W.family].reload
            st.reloads = st.reloads + 1
        end
        return true
    end

    -- Tells the other side's script which gun it holds, so the body can show it (the same event a real player sends). Only when it changes (and every WPN_EVERY s).
    function FT.show_weapon(now)
        local arg = (FT.drawn and FT.weapon) and CFG.wpn.arg_of(FT.weapon.id) or "none"
        if arg ~= FT.wpn_told or now - FT.wpn_told_at >= FT.WPN_EVERY then
            FT.wpn_told, FT.wpn_told_at = arg, now
            pcall(CFG.wpn.on_remote, arg, now)
        end
    end

    function FT.set_hp(n)
        n = math.max(2, math.min(1000, math.floor(n + 0.5)))
        pcall(net_send, CFG.who.BOT_MSG, "hp:" .. n)
        return n
    end

    function FT.stop_heal(why)
        local u = FT.healing
        FT.healing = nil
        if u then
            FT.stats.heals_stopped = FT.stats.heals_stopped + 1
            FT.note(string.format("stopped using the %s on itself: %s (nothing spent)", u.id, why))
        end
    end

    function FT.finish_heal(u, now, hp, mx)
        local F, A = CFG.friend, CFG.friend.ai
        FT.healing = nil
        if (F.inv[u.id] or 0) < 1 then
            FT.stats.heals_stopped = FT.stats.heals_stopped + 1
            FT.note("it no longer carries a " .. u.id .. ": nothing used")
            return
        end
        local target = FT.set_hp(math.min(mx, hp + mx * u.pct / 100))
        F.inv[u.id] = F.inv[u.id] - 1
        if F.inv[u.id] <= 0 then F.inv[u.id] = nil end
        F.save()
        FT.last_heal_at = now
        FT.stats.heals = FT.stats.heals + 1
        FT.verify = { want = target, at = now, max = mx }
        FT.note(string.format("used a %s on itself: health %.0f -> %d of %.0f (%d left)", u.id, hp, target, mx, F.inv[u.id] or 0))
        chat_add(F.NAME, string.format("Used a %s on myself.", u.id))
    end

    -- Did the exe take the new health? An exe from before 10.8 does not know "hp:<n>": then only "up" works, and it gives back all of it.
    function FT.check_verify(now, hp, mx)
        local v = FT.verify
        if not v or now - v.at < FT.VERIFY_SECS then return end
        FT.verify = nil
        if hp and hp >= v.want - 5 then return end
        FT.stats.exe_old_hits = FT.stats.exe_old_hits + 1
        FT.exe_old = true
        if v.want >= 0.9 * v.max then
            pcall(net_send, CFG.who.BOT_MSG, "up")
            FT.note("the exe did not take the exact health (it is older than 10.8: rebuild re7mp.exe): used \"up\" instead, which gives back all of it")
        else
            FT.note("the exe did not take the exact health (it is older than 10.8: rebuild re7mp.exe), so its health stays where it was")
        end
    end

    function FT.heal_tick(now, hp, mx, down)
        local A = CFG.friend.ai
        if FT.healing then
            local u = FT.healing
            if down then FT.stop_heal("it went down") return end
            if not FT.heal_self then FT.stop_heal("self-heal was switched off") return end
            if hp and mx and hp / mx * 100 > 99 then FT.stop_heal("its health is full already") return end
            state.remote_heal_until = now + 0.3
            if now - u.since >= FT.USE_SECS then FT.finish_heal(u, now, hp or 0, mx or 1000) end
            return
        end
        if not FT.heal_self or down or not hp or not mx or mx <= 0 then return end
        if (A and (A.using or A.reviving)) or pstat.downed then return end -- you come first
        local pct = hp / mx * 100
        if pct > FT.heal_below then FT.no_heal_told_at = -100 return end
        if now - FT.last_heal_at < FT.HEAL_COOLDOWN then return end
        local list = A.carried_heals()
        if #list == 0 then
            if now - FT.no_heal_told_at >= FT.NO_HEAL_TELL_EVERY then
                FT.no_heal_told_at = now
                FT.stats.no_heal_item = FT.stats.no_heal_item + 1
                FT.tell(string.format("I'm hurt (%.0f%%) and I have nothing to heal with.", pct))
            end
            return
        end
        local pick = list[#list]
        for _, e in ipairs(list) do -- the weakest that lifts it back over the threshold, else the strongest
            if pct + e.pct > FT.heal_below then pick = e break end
        end
        FT.healing = { id = pick.id, pct = pick.pct, since = now }
        FT.note(string.format("is using a %s on itself (its health %.0f%%, it gives %d%%, %.1f s)", pick.id, pct, pick.pct, FT.USE_SECS))
    end

    -- The simulated damage: an enemy within reach takes health off every HURT_EVERY s.
    function FT.hurt_tick(now, hp, mx, down)
        if down or FT.hurt_pct <= 0 then return end
        mx = mx or 1000 -- (the exe has not reported its health yet: its health is 1000 at the start)
        for _, e in ipairs(FT.hurters) do
            if now - (FT.hurt_at[e] or -100) >= FT.HURT_EVERY then
                FT.hurt_at[e] = now
                local dmg = mx * FT.hurt_pct / 100 * (B.blocking and FT.HURT_BLOCKED or 1)
                dmg = math.max(1, math.min(600, math.floor(dmg + 0.5)))
                if pstat.send_event then pcall(pstat.send_event, "ff", tostring(dmg)) end
                FT.stats.hurts, FT.stats.damage_taken = FT.stats.hurts + 1, FT.stats.damage_taken + dmg
                FT.note(string.format("%s reached it: it takes %d damage%s", tostring(e.name), dmg, B.blocking and " (blocking)" or ""))
                break -- one hit per tick, however many are on it
            end
        end
    end

    function FT.update(now)
        FT.flush(now)
        local active = B.own_on() and peer_present(now)
        if not active then
            FT.target, FT.aiming, FT.drawn, FT.can_shoot, FT.hurters = nil, false, false, false, {}
            if FT.healing then FT.healing = nil end
            FT.state = CFG.friend.present() and "it is not acting for itself" or "not here"
            return
        end
        local hp, mx, down = FT.health(now)
        if down and not FT.was_down then
            FT.stats.times_down = FT.stats.times_down + 1
            FT.note("it is down")
        end
        FT.was_down = down == true
        FT.check_verify(now, hp, mx)
        if now - FT.scan_at >= FT.SCAN_EVERY then
            local ok, err = pcall(FT.scan, now)
            if not ok then FT.target, FT.hurters, FT.state = nil, {}, "enemy read failed: " .. tostring(err):sub(1, 80) end
        end
        FT.heal_tick(now, hp, mx, down)
        FT.hurt_tick(now, hp, mx, down)
        local A = CFG.friend.ai
        local busy = FT.healing ~= nil or (A and (A.using ~= nil or A.reviving ~= nil))
        FT.can_shoot, FT.aiming = false, false
        if down then
            FT.drawn, FT.state = false, "down"
        elseif not FT.on then
            FT.drawn, FT.state = false, "shooting is switched off"
        else
            local t = FT.target
            local W, ngun, ammo = FT.pick_weapon()
            FT.weapon = W
            if t then FT.draw_until = now + FT.DRAWN_SECS end
            if busy then
                FT.state = "busy with a heal"
            elseif not t then
                FT.state = W and "ready: nothing near you to shoot at" or (ngun > 0 and "no ammo" or "no gun")
            elseif not W then
                if ngun > 0 then
                    FT.state = "out of ammo"
                    if now - FT.out_told_at >= FT.OUT_TELL_EVERY then
                        FT.out_told_at = now
                        FT.stats.out_of_ammo = FT.stats.out_of_ammo + 1
                        FT.tell("I'm out of ammo!")
                    end
                else
                    FT.state = "no gun"
                    if now - FT.no_gun_told_at >= FT.NO_GUN_TELL_EVERY then
                        FT.no_gun_told_at = now
                        FT.stats.no_gun = FT.stats.no_gun + 1
                        FT.tell("I have nothing to shoot with. Give me a gun and ammo.")
                    end
                end
            else
                FT.aiming = true
                if FT.reloading and now >= FT.reload_until then
                    FT.reloading = false
                    FT.mag_left = math.min(FT.FAMILY[W.family].mag, FT.ammo_left(W.ammo_family or W.family))
                end
                if FT.reloading then
                    FT.state = string.format("reloading (%.1f s)", math.max(0, FT.reload_until - now))
                elseif now >= FT.next_shot_at then
                    FT.can_shoot = true
                    FT.state = "shooting"
                    FT.shoot(now, t, W)
                else
                    FT.can_shoot = true
                    FT.state = "aiming at " .. tostring(t.name)
                end
                if FT.reloading then FT.can_shoot = false end
            end
            FT.drawn = FT.weapon ~= nil and (FT.aiming or now < FT.draw_until)
        end
        FT.show_weapon(now)
    end

    function FT.report()
        local guns, ammo = FT.arsenal()
        local hp, mx, down = FT.health(os.clock())
        local ammo_out = {}
        for fam, a in pairs(ammo) do ammo_out[fam] = a.total end
        local gl = {}
        for _, g in ipairs(guns) do gl[#gl + 1] = { id = g.id, kind = g.family, damage = FT.damage_of(g) } end
        return { shoots = FT.on, state = FT.state, target = FT.target and { name = FT.target.name, metres_from_you = math.floor(FT.target.dist_you * 10) / 10,
                metres_from_it = math.floor(FT.target.dist_it * 10) / 10 } or nil,
            enemies_in_reach = FT.targets_near, line_of_sight = "ignored", near_you_m = FT.NEAR_YOU, reach_m = FT.REACH, shortest_gap_ms = math.floor(FT.MIN_GAP * 1000 + 0.5),
            weapon = FT.weapon and { id = FT.weapon.id, kind = FT.weapon.family, damage = FT.weapon.damage, rounds_in_magazine = FT.mag_left, reloading = FT.reloading, ms_between_shots = math.floor(FT.gap_of(FT.weapon.family) * 1000 + 0.5) } or nil,
            guns = gl, ammo = ammo_out, drawn = FT.drawn, aiming = FT.aiming,
            health = hp and { hp = hp, max = mx, percent = math.floor(hp / mx * 100), down = down } or nil,
            heals_itself = FT.heal_self, heals_below_percent = FT.heal_below, healing_now = FT.healing and FT.healing.id or nil, exe_older_than_10_8 = FT.exe_old,
            enemies_hurt_it_by_percent = FT.hurt_pct, stats = FT.stats, last = FT.last, last_said = FT.last_tell, scans = FT.scans }
    end
end

----------------------------------------------------------------------------------------------
-- (10.9) AFTER A GAME OVER Ethan's friend gets up at full health and is put next to you ("after a game over, ethans friend should revive and teleport to me").
-- The game over is the game's own signal (RE7.on_death_signal: the game mode changing to game over). The reload that follows puts you at the last
-- checkpoint, somewhere else: a friend that was down stays where it fell and one that is closer than 40 m would only walk after you. So when the reload has
-- FINISHED (the loading gate, CFG.busy, was shut and has been open for WAIT_AFTER_LOAD s; or GIVE_UP s after the game over when no load was seen) the script
-- sends the exe the command "revive" (kind 11; exe 10.9: up at full health, put next to you, "up" + a health report come back) and, for an exe from before
-- 10.9 that does not know it, "up" (it gets up where it is). Nothing happens unless the friend is here. A switch in the panel, and a button to try it.
----------------------------------------------------------------------------------------------
CFG.friend.over = {
    on = true, WAIT_AFTER_LOAD = 2.0, GIVE_UP = 45, GIVE_UP_ABSENT = 120,
    armed_at = nil, why = nil, saw_load = false, load_end = nil, armed_n = 0, sent_n = 0, last = "no game over yet", last_at = nil,
}
do
    local O = CFG.friend.over

    -- A game over was signalled (RE7.on_death_signal; it can be signalled more than once while the screen is up: only the first arms).
    function O.arm(why, now)
        now = now or os.clock()
        if O.armed_at then return end
        O.armed_n = O.armed_n + 1
        if not O.on then O.last = "game over (" .. tostring(why) .. "): the switch 'after a game over it gets up and comes to me' is off" return end
        if not CFG.friend.present() then O.last = "game over (" .. tostring(why) .. "): Ethan's friend is not here, nothing to do" return end
        O.armed_at, O.why, O.saw_load, O.load_end = now, tostring(why), false, nil
        O.last = "game over (" .. tostring(why) .. "): waiting for the reload to finish"
    end

    -- Revive it and bring it to you now (the end of the wait, and the panel's button).
    function O.fire(now, why)
        now = now or os.clock()
        O.armed_at = nil
        O.sent_n = O.sent_n + 1
        pcall(net_send, CFG.who.BOT_MSG, "revive")
        pcall(net_send, CFG.who.BOT_MSG, "up") -- (an exe from before 10.9 ignores "revive": it at least gets up, where it is)
        pcall(function()
            local FT = CFG.friend.fight
            if FT.healing and FT.stop_heal then FT.stop_heal("game over") end
            if FT.tell then FT.tell("I'm back. Coming to you.") end
        end)
        O.last, O.last_at = "told Ethan's friend to revive and come to you (" .. tostring(why) .. ")", now
        say("friend: " .. O.last)
    end

    function O.tick(now)
        if not O.armed_at then return end
        if not O.on then O.armed_at = nil O.last = "switched off while waiting" return end
        if not CFG.friend.present() then
            if now - O.armed_at > O.GIVE_UP_ABSENT then O.armed_at = nil O.last = "game over: Ethan's friend was not here for " .. O.GIVE_UP_ABSENT .. " s, dropped" end
            return
        end
        if CFG.busy and CFG.busy.busy then
            O.saw_load, O.load_end = true, nil
        elseif O.saw_load and not O.load_end then
            O.load_end = now
        end
        if O.saw_load and O.load_end and now - O.load_end >= O.WAIT_AFTER_LOAD then
            O.fire(now, "the reload after the game over has finished")
        elseif not O.saw_load and now - O.armed_at >= O.GIVE_UP then
            O.fire(now, "no reload seen " .. O.GIVE_UP .. " s after the game over")
        end
    end

    function O.report()
        return { on = O.on, waiting = O.armed_at ~= nil, waiting_s = O.armed_at and math.floor((os.clock() - O.armed_at) * 10) / 10 or nil, load_seen = O.saw_load,
            game_overs_seen = O.armed_n, revives_sent = O.sent_n, last = O.last, wait_after_load_s = O.WAIT_AFTER_LOAD, give_up_s = O.GIVE_UP }
    end
end

-- On screen: the red tint and text when you are down, and what the helper can do.
function pstat.draw(now)
    local who = H.who_is_there()
    if pstat.downed then
        pcall(function()
            local sz = imgui.get_display_size()
            draw.filled_rect(0, 0, sz.x, sz.y, 0x300000FF)
        end)
        pcall(draw.text, "YOU ARE DOWN: " .. who .. " has to use a Herb or Chem Fluid next to you", 24, 200, 0xFF3030FF)
    end
    local FA = CFG.friend.ai
    if FA and (FA.reviving or FA.using) then pcall(draw.text, "Ethan's friend: " .. FA.status, 24, 250, 0xFF00D7FF) end -- (10.6)
    local r = pstat.remote
    if r and r.downed and peer_present(now) and now - r.at < 10 then
        local d = H.remote_distance()
        if pstat.reviving then
            pcall(draw.text, string.format("Reviving %s... %.1f / %.0f s  (stay within %.0f m)", who,
                math.min(now - pstat.reviving.since, pstat.revive_hold), pstat.revive_hold, pstat.revive_radius), 24, 220, 0xFF00D7FF)
        elseif d and d <= pstat.revive_radius then
            pcall(draw.text, string.format("[F8] revive %s (stay put %.0f s, no item needed)", who, pstat.revive_hold), 24, 220, 0xFF00D7FF)
        else
            pcall(draw.text, string.format("%s is down%s: get within %.0f m", who, d and string.format(" (%.0f m away)", d) or "",
                pstat.revive_radius), 24, 220, 0xFF3030FF)
        end
    end
end

state.tag_extra = function()
    local r = pstat.remote
    if not r or os.clock() - r.at > 10 then return nil end
    if r.downed then return " [downed]", 0xFF3030FF, true end -- (9.13: in the same style as [healing] / [crouching])
    if r.hp and r.hp >= 0 and r.max and r.max > 0 then return string.format("  HP %d%%", math.floor(r.hp / r.max * 100 + 0.5)) end
    return nil
end

-- A summary of the health state goes into every debug file.
dbg.extra = function()
    return {
        read_from = pstat.hi and (pstat.where .. "." .. pstat.field) or "not found",
        max_from = pstat.max_field or "none",
        health = pstat.hp, max = pstat.max, downed = pstat.downed,
        ping = { mode = pings.mode, find_shown = pings.finder.shown, find_last = pings.finder.last, find_active = pings.finder.active(os.clock()), keep = pings.finder.keep },
        gun_poses = (function()
            local G = pstat.gun
            if not G then return nil end
            local hk = enemy.hit.hook
            return { gun_out = G.gun, aiming = G.aim, shot_now = G.shoot, gun_from = G.gun_src, aim_from = G.aim_src, use_learned = G.use_learned,
                learned_gun = G.text(G.signals.gun), learned_aim = G.text(G.signals.aim),
                packets_with = { gun = G.sent.gun, aim = G.sent.aim, shoot = G.sent.shoot },
                shot_hook = { installed = hk.installed, not_found = hk.missing, shoot_calls = hk.counts.shoot or 0, shootStart_calls = hk.counts.shootStart or 0 },
                last_shot_s_ago = state.gun_shot_at and math.floor((os.clock() - state.gun_shot_at) * 10) / 10 or nil,
                -- 9.30: the pose is let go after `hold_seconds` without aiming or firing (0 = never); seconds and changes for the next file
                hold_seconds = G.hold, let_go_now = G.timed_out, learned_signal_vetoed_by_PlayerGun_actionID_0 = G.vetoed or 0, signal_value_now = G.gun_value ~= nil and dump_value(G.gun_value) or nil,
                aim_value_now = G.aim_value ~= nil and dump_value(G.aim_value) or nil,
                seconds = { signal_on = math.floor(G.secs.signal_on), shown = math.floor(G.secs.shown), let_go = math.floor(G.secs.let_go) },
                changes = G.changes }
        end)(),
        testing = { face_me = CFG.face_me == true, invincible = pstat.god == true, health_put_back = pstat.god_writes or 0,
            facing = state.render_fwd and { x = math.floor(state.render_fwd[1] * 100 + 0.5) / 100, z = math.floor(state.render_fwd[3] * 100 + 0.5) / 100 } or nil },
        death_mode = death.mode, execution_wipe = { on = death.exec_wipe, sent = death.exec_sent, received = death.exec_received, ignored = death.exec_skipped, last = death.exec_last },
        held_at_1 = pstat.clamped, heals_seen = pstat.heals, hits_seen = pstat.hurts, revives = pstat.revives,
        revive = { radius = pstat.revive_radius, hold = pstat.revive_hold, started = pstat.revive_stats.started, done = pstat.revive_stats.done,
            cancelled = pstat.revive_stats.cancelled },
        hold_hook = pstat.hooked, use_hook = pstat.use_hooked, address_readable = pstat.hi_addr ~= nil,
        coop_saves = (function()
            local sv = CFG.saves -- (the co-op saves table is a local further down; this is the same table)
            if not sv then return nil end
            local out = { enabled = sv.enabled, last = sv.last, folder = sv.dir, occupied = sv.occupied, entries = {},
                account = sv.account, partner_account = sv.partner_account, accounts = sv.accounts_line() }
            for _, e in ipairs(sv.entries) do
                if type(e) == "table" then
                    out.entries[#out.entries + 1] = { slot = e.slot, role = e.role, from = e.from, partner = e.partner, from_slot = e.from_slot,
                        why = e.why, size = e.size, crc = e.crc, tag = e.tag, partner_account = e.partner_account, game_lists_the_slot = sv.game_sees(tonumber(e.slot) or -1, os.clock()) }
                end
            end
            local okg, gset, glist = pcall(function() return CFG.lm.game_slots(10, sv.SCAN_TO) end) -- (10.20: a scan up to 10 s old, 21 questions, not 61 calls into the game on every write)
            out.game_says_slots_exist = okg and glist or nil
            local st = CFG.lm.scan_stats
            out.slot_scans = { about = "10.20: how often and how long the game was asked which save slots exist (isExistData); slow = scans that took 30 ms or more",
                scans = st.scans, calls = st.calls, avg_ms = st.scans > 0 and math.floor(st.total_ms / st.scans * 100) / 100 or 0, max_ms = math.floor(st.max_ms * 10) / 10,
                served_from_cache = st.served_from_cache, slow = st.slow, exe_file_reads = sv.read_stats and sv.read_stats.reads or nil }
            out.label_status = CFG.lm.status
            out.labels_written = CFG.lm.written
            out.played_with = {}
            for sl, p in pairs(sv.played or {}) do out.played_with[#out.played_with + 1] = { slot = sl, partner = p.partner, when = p.when } end
            table.sort(out.played_with, function(a, b) return a.slot < b.slot end)
            return out
        end)(),
        story = CFG.story.report(), -- 
        enemy_timeline = enemy.tl and enemy.tl.report() or nil, -- 10.12: how the joiner plays the host's enemies back (delay, clock, interpolation counts)
        enemy_clips = CFG.eanim and CFG.eanim.report() or nil, -- 9.41: enemy clip playback, the bank fetch, and the table of every bank and clip id seen
        doors = CFG.door and CFG.door.report() or nil, -- 9.40: door sync (what was sent and got, why a door was ignored, the loading gate)
        item_sync = items.report(), -- 9.32: the pickup hook (every addItem overload), what it saw, and the take / both-players mode
        item_data = CFG.idata.report(), -- 9.32: the kinds held (stack sizes, records), the item classes' fields and methods
        items = { create_worked_with = give.create_how, bumped_stacks = give.bumped or 0, failed_creations = give.create_log,
            sent_ok = give.sent, received = give.received, dropped = give.dropped, failed = give.failed,
            item_manager = { in_use = mgr.item_manager_how, knows_items = mgr.item_manager_ok, copies = mgr.item_manager_list },
            -- 9.30: how the inventory object was found, how often it was lost and found again, and what the last failed search tried
            inventory = { object_in_hand = mgr.inventory ~= nil, found_how = mgr.inv_log.how, found = mgr.inv_log.found, lost = mgr.inv_log.lost,
                switched_to_a_new_one = mgr.inv_log.switched, searches = mgr.inv_log.searches, failed_searches = mgr.inv_log.failed_searches,
                last_lost_because = mgr.inv_log.why, last_search_tried = mgr.inv_log.tried, gifts_refused_unreadable = give.refused_unread or 0 },
            -- what the last dropped object looked like (9.33: nothing is created for the inventory any more, so there is no addItem answer to report)
            last_drop = give.last_drop,
            -- the black box: every step of the last item attempts, and the last session's, which survives a crash
            item_trail = give.trail_list, previous_item_trail = give.previous_trail, earlier_item_trails = give.history,
            last_count_unreadable = give.last_unread, -- 9.26: the last give refused for lack of a count: the list can't be read, or it was read and lacks that item (and what it holds)
            whole_entry = { giving_allowed = give.last_ok, refused = give.refused_last, removed_with_false = give.whole_entry_removals,
                menu_reopen_hooked = give.reopen_hooked == true, menu_reopen_requests_seen = give.reopen_seen, menu_reopen_within_5s_of_my_call = give.reopen_after_ours },
            -- (9.32) the 3 m rule: the distance now, the limits, and how many gifts it refused (mine, and the ones that arrived from too far away)
            range_rule = (function()
                local dist = give.distance()
                local la = give.last_far
                return { limit_m = give.RANGE, receiver_limit_m = give.RANGE_RECV, distance_now_m = dist and math.floor(dist * 10 + 0.5) / 10 or nil,
                    refused_to_give = give.refused_far, refused_to_receive = give.refused_far_recv,
                    last_refusal = la and { id = la.id, distance_m = la.distance, received = la.received or false, seconds_ago = math.floor(os.clock() - la.at) } or nil }
            end)(),
            -- the ground route (the only way to give a kind I don't hold, 9.33): the switch, the counts, and what each of the last 8 drops looked like
            -- (made of, state, still there 2 s later, picked up); refused_when_off = gifts and drops refused because the switch was off
            ground = give.ground_report(),
            refused_when_ground_is_off = give.refused,
            add_item_result_names = (function() local o = {} for v, nm in pairs(give.enum_names("app.Inventory.AddItemResult")) do o[tostring(v)] = nm end return o end)(),
            -- what the item states are called (the 9.17 file: a new object is 6 LOST, the game's own entries are 2)
            item_state_names = (function() local o = {} for v, nm in pairs(give.enum_names("app.Item.ITEMSTATE")) do o[tostring(v)] = nm end return o end)(),
            discard = { menu_discard_hooked = give.discard_hooked, menu_discard_calls = give.discard_calls or 0,
                reduceNum_calls = give.reduce_seen or 0, reduceNum_ignored = give.reduce_ignored or 0, focus_hook_calls = give.hover_seen or 0, switched_on = give.drop_on_discard } },
        item_lock = { on = H.ITEMLOCK.on, refused_while_down = H.ITEMLOCK.blocked, last = H.ITEMLOCK.last }, -- 9.30
        weapon_lock = { on = H.LOCK.on, status = H.LOCK.status, writes = H.LOCK.writes, rewritten_by_game = H.LOCK.rewritten,
            failed = H.LOCK.fails, restored = H.LOCK.restored,
            -- 9.9: per place in the frame: how often the lock ran there, and how often it found the gate open again
            places = H.LOCK.phase, places_registered = H.LOCK.registered, hook_on = H.LOCK.hooks.on,
            hooked_after = H.LOCK.hooks.installed, hook_error = H.LOCK.hooks.error,
            sequence_manager_methods = H.LOCK.hooks.methods, other_methods = H.LOCK.hooks.dump,
            -- 9.12: what each part did while you were down (hooks: how often each fired; gun: calls refused; move: gate / put back)
            hooks = { installed = H.LOCK.hooks.installed, not_found = H.LOCK.hooks.missing, fired_while_down = H.LOCK.hooks.calls, muted = H.LOCK.hooks.muted },
            gun = { on = H.LOCK.guns.on, installed = H.LOCK.guns.installed, not_found = H.LOCK.guns.missing, refused = H.LOCK.guns.skipped, error = H.LOCK.guns.error },
            move = { on = H.LOCK.move.on, installed = H.LOCK.move.installed, not_found = H.LOCK.move.missing, error = H.LOCK.move.error,
                gate_asked_while_down = H.LOCK.move.getter_calls, gate_said_no = H.LOCK.move.blocked, put_back = H.LOCK.move.pinned,
                put_back_failed = H.LOCK.move.pin_fails, put_back_where = H.LOCK.move.pin_places, new_place_taken = H.LOCK.move.reanchored } },
        poses = { guard = H.POSE.guard, guard_from = H.POSE.guard_src, heal = H.POSE.heal, hands_action = H.POSE.hands_id,
            gun_action = H.POSE.gun_id, guard_cancel_flag = H.POSE.cancel, reads = H.POSE.reads, unreadable = H.POSE.fails,
            guard_readings = H.POSE.guard_reads, heal_readings = H.POSE.heal_reads,
            -- 9.9: how many position packets carried each bit, and what the action ids were (id -> readings)
            heal_ignored_because_a_menu_was_open = H.POSE.heal_blocked or 0, packets = H.POSE.sent.packets, packets_with_guard = H.POSE.sent.guard, packets_with_heal = H.POSE.sent.heal,
            packets_with_crouch = H.POSE.sent.crouch, hands_ids_seen = H.strkeys(H.POSE.hist_hands), gun_ids_seen = H.strkeys(H.POSE.hist_gun) },
        crouch = { now = H.POSE.crouch, from = H.POSE.crouch_src, eye_above_feet = H.POSE.eye, standing_eye = H.POSE.stand_eye,
            drop = H.POSE.eye_drop, readings_crouched = H.POSE.crouch_reads, game_fields = H.crouch_report() },
        occlusion = state.occ and state.occ.report and state.occ.report() or nil,
        enemy_hits = enemy.hit and enemy.hit.report and enemy.hit.report() or nil,
        enemy_walls = { on = enemy.hide_walls, needs_wall_box = state.occlude == true, tests = enemy.wall_checks, behind_a_wall = enemy.wall_hidden_checks,
            hidden_now = (function() local t = {} for k, w in pairs(enemy.wall) do if w.hide then t[#t + 1] = k end end table.sort(t) return t end)() },
        menus = CFG.menu and CFG.menu.report and CFG.menu.report() or nil,
        who = CFG.who and CFG.who.report() or nil, -- 9.31
        weapons = CFG.wpn and CFG.wpn.report() or nil, friendly_fire = CFG.ff and CFG.ff.report() or nil,
        pickups = CFG.pick and CFG.pick.report() or nil, inventory_changes = CFG.inv and CFG.inv.report() or nil, -- 9.31
        loader = CFG.load and CFG.load.report() or nil, enemy_models = CFG.pup and CFG.pup.report() or nil, kill_sync = CFG.kill and CFG.kill.report() or nil, limb_sync = CFG.limb and CFG.limb.report() or nil, -- 9.31; 10.21
        enemy_motions = CFG.mot and CFG.mot.report() or nil, -- 9.33: the .motlist files of the enemies near the last press
        bridge_reads = CFG.bridge and CFG.bridge.report() or nil, -- 9.33: reads of the exe's files that failed (and how often the script waited instead)
        reset_to_defaults = CFG.reset and { times = CFG.reset.done, last = CFG.reset.last } or nil, -- 9.33
        model_probe = CFG.mprobe and CFG.mprobe.result or nil,
        model_collection = CFG.mprobe and CFG.mprobe.report() or nil,
        model_types = CFG.mprobe and CFG.mprobe.types or nil,
        body_lab = CFG.body and CFG.body.report and CFG.body.report() or nil,
        real_body = CFG.real and CFG.real.report and CFG.real.report() or nil,
        perf = CFG.perf and CFG.perf.report() or nil, -- 9.36: where the frame time goes, the slowest frames, what writing this file costs
        model_check = CFG.verify and CFG.verify.report and CFG.verify.report() or nil, -- 9.36: the every-5-seconds check that enemy models are whole
        reframework = CFG.fw and CFG.fw.report() or nil, -- 10.1: which REFramework build wrote this file
        model_settle = CFG.settle and CFG.settle.report() or nil, -- 10.1: the look at a new body after 4 s, the rebuilds and what was said
        model_pack = CFG.pack and CFG.pack.report() or nil, -- 10.1: the full character models (Nexus RE7 mod 86)
        motion_banks = CFG.mbank and CFG.mbank.report() or nil, -- 10.1: Ethan's bank / clip pairs, their names and labels
        weapon_models = CFG.wmesh and CFG.wmesh.report() or nil, -- 10.15: the other player's weapon on their body (the mesh / material / grip that went over, the copy, what failed)
        boss_pool = CFG.pool and CFG.pool.report() or nil, -- 10.15: one health pool: the copies that took the host's number, the kills, the boss bar
        car_probe = CFG.car and CFG.car.report() or nil, -- 10.16: the garage car probe (reads only)
        story_flow = CFG.flow and CFG.flow.report() or nil, -- 10.18: the game's story flow numbers, mine and the other player's (reads only)
        story_match = CFG.match and CFG.match.report() or nil, -- 10.18: matching the story steps (experimental)
        enemy_targets = CFG.tgt and CFG.tgt.report() or nil, -- 10.18: who the enemies target and how far they are from each player (reads only)
        enemy_handover = CFG.own and CFG.own.report() or nil, -- 10.18: the enemy hand-over (experimental)
        enemy_sync_tick = CFG.esync and CFG.esync.report() or nil, -- 10.19: re7mp.exe's box "Sync enemies and the Molded"
        channel_tick = CFG.chan and CFG.chan.report() or nil, -- (10.24) which channel and build re7mp.exe says it is
        garage_car = CFG.carsync and CFG.carsync.report() or nil, -- 10.19: Jack's car in the garage: who runs it, the other player's get-in, the puppet, damage
        actor_probe = CFG.actors and CFG.actors.report() or nil, -- 10.19: scene objects that run their own script (reads only)
        guard = CFG.guard and CFG.guard.report() or nil, -- 10.16: the quiet check (loading, events, cutscenes) the pool, the weapon model and the boss hits wait for
        molded_spawn_points = CFG.mold and CFG.mold.report() or nil, -- 10.15: the Molded the spawn points say are out, by their unique wire names
        molded_copies = CFG.molded and CFG.molded.report() or nil, -- 10.15: (opt-in) the host's Molded brought out in this game
        friend = CFG.friend and CFG.friend.report() or nil, -- 10.5: Ethan's friend: its inventory, the shared weapons and ammo, what was refused
        low_body = CFG.low and CFG.low.report() or nil, -- 10.12: crawling / lying: the floor the other body is stood on
        run_or_walk = CFG.run and CFG.run.report() or nil, -- 10.12: the run bit, the speeds and the bars
        game_motion = CFG.gmot and CFG.gmot.report() or nil, -- 10.2: the other player's body animated from the motion bank: every step and what it said
        model_table = CFG.bm and CFG.bm.report() or nil, -- 9.36: per model: collected, files known, made / failed and why, what the check found
        clips = CFG.clip and CFG.clip.report and CFG.clip.report() or nil,
        other_player = pstat.remote and { hp = pstat.remote.hp, max = pstat.remote.max, downed = pstat.remote.downed } or nil,
        last = pstat.last,
    }
end

-- Marks calls on the player's own HealthInfo in the tracer's output.
tracer.owner_hint = function(args)
    if not pstat.hi_addr then return nil end
    local a = sdk.to_int64(args[2])
    if a == pstat.hi_addr then return "  [on the PLAYER's HealthInfo]" end
    return nil
end

----------------------------------------------------------------------------------------------
-- Hooks
----------------------------------------------------------------------------------------------
function pstat.install()
    pcall(function()
        local td = sdk.find_type_definition("app.HealthInfo")
        local m = td and td:get_method("set_health")
        if not m then
            say("health: app.HealthInfo.set_health not found (the check ten times a second still works)")
            return
        end
        sdk.hook(m, function(args)
            pstat.this = nil
            if pstat.hi_addr then
                local ok, a = pcall(sdk.to_int64, args[2])
                if ok then pstat.this = a end
            end
            return H.CALL_ORIGINAL
        end, function(retval)
            local a = pstat.this
            pstat.this = nil
            -- the hit has just lowered the health: if it would be lethal, put it back to 1 before the game looks
            if a ~= nil and a == pstat.hi_addr and pstat.hi and not pstat.writing and pstat.god and H.god_fill() then
                -- (invincible: the health is back at its top before the game looks at it)
            elseif a ~= nil and a == pstat.hi_addr and pstat.hi and not pstat.writing and H.clamp_active() then
                local hp = H.read_num(pstat.hi, pstat.field)
                if hp and hp <= 0 then
                    H.write_health(1)
                    pstat.clamped = pstat.clamped + 1
                    if not pstat.downed then pstat.pending_down = true end -- (already down: just held at 1 again)
                end
            end
            return retval
        end)
        pstat.hooked = true
    end)
    pstat.use_hooked = hook_method("app.Inventory", "reduceItem", function(args)
        local name
        pcall(function() name = as_text(sdk.to_managed_object(args[3])) end)
        if H.item_blocked(name) then return "skip" end -- (9.30) a downed player can't spend a healing item
        H.on_item_used(name)
    end)
end

----------------------------------------------------------------------------------------------
-- Debug collectors (buttons 8 and 9)
----------------------------------------------------------------------------------------------
function H.player_components()
    local out = {}
    local go = player_object()
    if not go then return out, nil end
    pcall(function()
        for _, c in ipairs(go:call("get_Components"):get_elements()) do
            out[#out + 1] = { full = c:get_type_definition():get_full_name(), obj = c }
        end
    end)
    return out, go
end

-- Button 8: what the player object has, where health was found, and a trace of the damage / guard / heal / death calls.
function pstat.details()
    pinned(function()
        say("=== player details ===")
        local comps, go = H.player_components()
        if not go then
            say("player object (Pl0000) NOT found: load into the game first")
            return
        end
        local names = {}
        for _, c in ipairs(comps) do names[#names + 1] = c.full end
        say("components on Pl0000: " .. table.concat(names, ", "))
        H.scan()
        if pstat.hi then
            say(string.format("health: %s.%s = %s, maximum %s (field %s)", pstat.where, pstat.field, tostring(H.read_num(pstat.hi, pstat.field)),
                tostring(pstat.max), tostring(pstat.max_field)))
            say("the object that holds it:")
            dump_fields(pstat.hi, "   ", 30)
        else
            say("NO health field found on Pl0000 (looked for an app.HealthInfo field and for health/hp/life numbers)")
        end
        say(string.format("hold-at-1 hook %s, item-use hook %s, object address %s", pstat.hooked and "installed" or "NOT installed",
            pstat.use_hooked and "installed" or "NOT installed", pstat.hi_addr and "readable" or "NOT readable"))
        for _, c in ipairs(comps) do
            if H.PLAYER_DUMP[c.full] then
                say("component " .. c.full .. ":")
                dump_fields(c.obj, "      ", 40)
            end
        end
        for _, c in ipairs(comps) do
            if H.PLAYER_DUMP[c.full] then probe_type(c.full, false, H.PLAYER_WORDS, 70) end
        end
        say("=== player details done ===")
    end)
    -- then trace the calls while you get hit, block, heal and (with a partner) go down
    local comps = H.player_components()
    local present, order = {}, {}
    for _, c in ipairs(comps) do present[c.full] = true end
    for _, n in ipairs(H.PLAYER_FIRST) do
        if present[n] then order[#order + 1] = n end
    end
    for _, c in ipairs(comps) do
        if c.full:find("^app%.Player") then
            local listed = false
            for _, n in ipairs(order) do if n == c.full then listed = true end end
            if not listed then order[#order + 1] = c.full end
        end
    end
    order[#order + 1] = "app.HealthInfo"
    for _, n in ipairs(order) do trace_type(n, H.PLAYER_WORDS, false) end
    trace_type("app.GameManager", { "gameover", "dead", "die", "death", "continue", "retry", "restart", "load", "chapter" }, false)
    tracer_add("player trace: " .. #order .. " types. Now get hit once, hold the block button, use a Herb, then send the debug file")
end

-- A few live instances of the event classes, with their fields, so the ids that identify an event are visible.
H.EVENT_DUMP = { "app.GameEventSetting", "app.GameEventAction", "app.GameEventActionController", "app.TimeLineKicker",
    "app.TimeLineContainer", "app.TriggerInAction", "app.InteractEventAction", "app.DoorEventAction", "app.ChapterJumpData",
    "app.SequenceController" }
H.EVENT_SINGLETONS = { "app.GameEventManager", "app.GameFlowFsmManager", "app.TimeLinePlayStateControlManager",
    "app.ChapterLoadTempManager", "app.SaveDataManager" }
function H.events_dump()
    pinned(function()
        say("=== event objects ===")
        local wanted, count, shown = {}, {}, {}
        for _, n in ipairs(H.EVENT_DUMP) do wanted[n] = true end
        local okw, errw = pcall(each_gameobject, function(go, path)
            local okc, comps = pcall(function() return go:call("get_Components"):get_elements() end)
            if not okc then return end
            for _, c in ipairs(comps) do
                local okt, full = pcall(function() return c:get_type_definition():get_full_name() end)
                if okt and wanted[full] then
                    count[full] = (count[full] or 0) + 1
                    if (shown[full] or 0) < 2 then
                        shown[full] = (shown[full] or 0) + 1
                        say(string.format("%s on %s", full, path))
                        dump_fields(c, "      ", 25)
                    end
                end
            end
        end, 20000)
        if not okw then say("event dump scan error: " .. tostring(errw)) end
        for _, n in ipairs(H.EVENT_DUMP) do say(string.format("%s: %d in the scene", n, count[n] or 0)) end
        for _, n in ipairs(H.EVENT_SINGLETONS) do
            local ok, obj = pcall(sdk.get_managed_singleton, n)
            if ok and obj then
                say(n .. " (singleton):")
                dump_fields(obj, "      ", 40)
            else
                say(n .. ": no singleton")
            end
        end
        say("=== event objects done ===")
    end)
end

-- Button 9: watch cutscene / event / flow classes while you play through one.
function pstat.events_trace()
    H.events_dump()
    for _, n in ipairs(H.EVENT_TYPES) do trace_type(n, H.EVENT_WORDS, false) end
    local extra = {}
    for _, k in ipairs(H.EXTRA_ORDER) do
        if H.extra_on[k] then
            extra[#extra + 1] = k
            for _, t in ipairs(H.EVENT_EXTRAS[k].types) do trace_type(t[1], t[2], false) end
        end
    end
    tracer_add("event trace: " .. #H.EVENT_TYPES .. " types" .. (#extra > 0 and (" + " .. table.concat(extra, ", ")) or "")
        .. ". Now walk into a cutscene, open a door, pick up a key item or load a chapter, then send the debug file")
end

-- The options under button 9 and what the breadcrumb said about the last session.
function pstat.extras_panel()
    for _, k in ipairs(H.EXTRA_ORDER) do
        local c, v = imgui.checkbox("    9+ also trace " .. H.EVENT_EXTRAS[k].label .. "##x" .. k, H.extra_on[k])
        if c then H.extra_on[k] = v end
    end
    imgui.text("    The 9+ options hook more of the game and may crash it: tick ONE, press 9, and tell me what happened.")
    if tracer.previous then imgui.text("    " .. tracer.previous) end
end

----------------------------------------------------------------------------------------------
-- Panel
----------------------------------------------------------------------------------------------
function pstat.panel()
    local now = os.clock()
    local who = H.who_is_there()
    if pstat.hi then
        imgui.text(string.format("Your health: %.0f / %.0f   (read from %s.%s)", pstat.hp or 0, pstat.max or 0, pstat.where, pstat.field))
    else
        imgui.text("Your health: not found yet (load into the game; button 8 in the debug section lists what the player has)")
    end
    local r = pstat.remote
    if r and now - r.at < 10 and r.hp then
        imgui.text(string.format("%s: %.0f / %.0f%s", who, r.hp, r.max or 0, r.downed and "   DOWN" or ""))
    else
        imgui.text(who .. ": no health received yet")
    end
    if CFG.friend.present() then -- the pretend player can be told to go down, so a revive can be tried alone
        imgui.text(string.format("Ethan's friend can go down: walk within %.0f m of it and press F8, then stay put for %.0f s (no item needed), or use a heal from the inventory next to it.",
            pstat.revive_radius, pstat.revive_hold))
        if imgui.button("Ethan's friend: make it go down") then
            net_send(H.BOT_MSG, "down")
            H.note("told Ethan's friend to go down")
        end
        if imgui.button("Ethan's friend: make it get up") then
            net_send(H.BOT_MSG, "up")
            H.note("told Ethan's friend to get up")
        end
        if imgui.button("Ethan's friend: revive it and bring it to me (what happens after a game over)") then
            CFG.friend.over.fire(os.clock(), "the button")
            H.note("told Ethan's friend to revive and come to me")
        end
    end
    imgui.text(pstat.last)
    imgui.text(string.format("Heals seen %d   hits taken %d   times held at 1: %d   revived %d   sent %d   received %d",
        pstat.heals, pstat.hurts, pstat.clamped, pstat.revives, pstat.sent, pstat.received))
    imgui.text(string.format("Hooks: hold-at-1 %s   item use %s", pstat.hooked and "on" or "off", pstat.use_hooked and "on" or "off"))
    if death.mode == 4 then
        imgui.text(H.clamp_active(now) and "Downed mode is ACTIVE: a lethal hit leaves you at 1 health and down."
            or "Downed mode is on but not active (needs the other player connected and not down).")
    else
        imgui.text("Downed mode is off. Choose \"Downed and revive\" under When a player dies (Death section).")
    end
    if pstat.downed then
        imgui.text("YOU ARE DOWN: waiting for " .. who .. " to use a Herb or Chem Fluid next to you.")
        if imgui.button("Test: get up now") then H.get_up("test button") end
    elseif imgui.button("Test: go down now (sets your health to 1)") then
        if death.mode ~= 4 then
            H.note("switch on \"Downed and revive\" in the Death section first")
        elseif not peer_present(now) then
            H.note("the other player has to be connected to go down")
        elseif not pstat.hi then
            H.note("your health can't be found, so I can't set it")
        else
            H.write_health(1)
            H.go_down("test button")
        end
    end
    if r and r.downed and imgui.button("Revive " .. who .. " (stay put until the countdown ends; no item needed)  [F8]") then pstat.revive_other() end
    if pstat.reviving then
        imgui.text(string.format("Reviving %s: %.1f / %.0f s", who, math.min(os.clock() - pstat.reviving.since, pstat.revive_hold), pstat.revive_hold))
        if imgui.button("Cancel the revive") then pstat.revive_cancel("you cancelled it") end
    end
    if imgui.button("Test: pretend " .. who .. " used a Herb right next to me") then
        local lp = state.local_pos or { x = 0, y = 0, z = 0 }
        netmsg.handlers[H.PH_MSG](string.format("e|heal|Herb|%.2f|%.2f|%.2f", lp.x, lp.y, lp.z))
    end
    local ok2, ch2, val2 = pcall(imgui.slider_float, "Revive distance (m)", pstat.revive_radius, 1, 10)
    if ok2 and ch2 and type(val2) == "number" then pstat.revive_radius = math.max(1, math.min(10, val2)) end
    local okh, chh, valh = pcall(imgui.slider_float, "F8 revive: seconds to stay within that distance", pstat.revive_hold, 1, 10)
    if okh and chh and type(valh) == "number" then pstat.revive_hold = math.max(1, math.min(10, math.floor(valh * 2 + 0.5) / 2)) end
    local ok3, ch3, val3 = pcall(imgui.slider_float, "Health after being revived (% of maximum)", pstat.revive_pct, 5, 100)
    if ok3 and ch3 and type(val3) == "number" then pstat.revive_pct = math.max(5, math.min(100, math.floor(val3 + 0.5))) end
    do
        local okc, cc, vc = pcall(imgui.checkbox, "A downed player can't aim or shoot until revived", H.LOCK.on)
        if okc and cc and type(vc) == "boolean" then H.LOCK.on = vc end
        local oki, ci, vi = pcall(imgui.checkbox, "A downed player can't use healing items (the item stays in the inventory)", H.ITEMLOCK.on)
        if oki and ci and type(vi) == "boolean" then H.ITEMLOCK.on = vi end
        if H.ITEMLOCK.blocked > 0 then imgui.text(string.format("    refused %d use(s) while down; the last was %s", H.ITEMLOCK.blocked, tostring(H.ITEMLOCK.last and H.ITEMLOCK.last.name))) end
        imgui.text("    weapon lock: " .. H.LOCK.status)
        local okk, ck, vk = pcall(imgui.checkbox, "    also close it right after the sequence manager's own update (hooks it the first time you go down)", H.LOCK.hooks.on)
        if okk and ck and type(vk) == "boolean" then H.LOCK.hooks.on = vk end
        if H.LOCK.hooks.error then imgui.text("    hook: " .. H.LOCK.hooks.error) end
        local okg, cg, vg = pcall(imgui.checkbox, "    also refuse the gun's own attack and aim calls while down (hooks app.PlayerGun.tryAttack ...)", H.LOCK.guns.on)
        if okg and cg and type(vg) == "boolean" then H.LOCK.guns.on = vg end
        if H.LOCK.guns.error then imgui.text("    gun hook: " .. H.LOCK.guns.error) end
        local okv, cv, vv = pcall(imgui.checkbox, "    also stop a downed player moving (the move gate says no; if the game moves you anyway you are put back where you fell)", H.LOCK.move.on)
        if okv and cv and type(vv) == "boolean" then H.LOCK.move.on = vv end
        if H.LOCK.move.error then imgui.text("    move gate: " .. H.LOCK.move.error) end
    end
    imgui.text("Revive: the other player uses a Herb / Chem Fluid / Remedy within that distance (at once, costs the item), or stays next to you with F8 (takes the time below, costs nothing).")
    imgui.text("You stay where you fell: the game never sees you die, so it does not reload a checkpoint.")
    imgui.text("If the game still ends when you are hit to 0, send me the debug file (button 8).")
end

----------------------------------------------------------------------------------------------
-- Poses from MY body. local_flags() asks this what to send. 9.8: the signals are the REAL ones, taken from two guided
-- recordings (button 11) done with and without a gun:
--   block: app.PlayerSequenceManager.IsGuardCancelAccepted is false at rest and true from the moment the raise starts until
--          the lowering starts (4 of 4 blocks, with and without a gun, and it does not move while healing).
--          Fallbacks if that field can't be read: PlayerHands.actionID 35 (raise) / 36 (hold), PlayerGun.actionID 107 / 108.
--   heal:  app.PlayerHands.<actionID>k__BackingField is 16 then 17 for the whole heal animation (about 3.6 s), with and
--          without a gun. (The game takes the item out of the inventory at the END of the animation, so reduceItem is no
--          trigger for the pose; it is still the trigger for the heal event.)
-- Only plain field reads (twenty a second at most): no hooks, nothing written.
----------------------------------------------------------------------------------------------
H.POSE = {
    HEAL_HANDS = { [16] = true, [17] = true },
    GUARD_HANDS = { [35] = true, [36] = true },
    GUARD_GUN = { [107] = true, [108] = true },
    next_at = -1, comps_at = -10, go_addr = nil, seq = nil, hands = nil, gun = nil,
    guard = false, heal = false, heal_raw = false, guard_src = "-", heal_until = 0,
    hands_id = nil, gun_id = nil, cancel = nil,
    reads = 0, fails = 0, fail_run = 0, guard_reads = 0, heal_reads = 0,
    -- 9.9: crouch. The signal is how far the camera sits above the player object (the feet): it drops about half a metre
    -- when you crouch. "Standing" is the highest value seen in the last two minutes, so nothing has to be calibrated.
    crouch = false, crouch_h = false, crouch_src = "-", eye = nil, stand_eye = nil, eye_drop = 0, crouch_reads = 0,
    eye_buckets = {}, comp_by_name = {}, cands = {}, cands_addr = nil,
    -- 9.9: what the hands / gun action ids do (id -> readings), so a heal that does not look like 16/17 shows up in the file
    hist_hands = {}, hist_gun = {}, hist_keys = 0,
    sent = { guard = 0, heal = 0, crouch = 0, packets = 0 }, -- position packets that carried each pose bit
}
pstat.pose = H.POSE -- (the panel, outside this block, reads it from here)

-- 9.28: gun poses. THREE bits are sent: a gun is out, I am aiming, I just fired.
--   shot:  the gun's own shoot / shootStart call (the same hook the hit sync uses), kept on for 0.4 s.
--   gun:   a signal learned by the guided gun recording (button 11); until then PlayerGun.actionID is not 0 (a guess from the
--          files: it is 0 for the whole of the early game, before there is a gun, and mostly 91 when a gun is out).
--   aim:   a signal learned by the same recording; until then nothing (no field of the files is known to mean "aiming").
-- A learned signal is { comp, path = { field [, subfield] }, vals = { the values that mean "yes" }, text }.
H.GUN = { signals = {}, use_learned = true, gun = false, aim = false, shoot = false, gun_src = "-", aim_src = "-", SHOT_TAIL = 0.4,
    sent = { gun = 0, aim = 0, shoot = 0 }, hook_tried = false,
    -- 9.30 ("the gun animation trigger is playing too much"): the learned gun-out signal in the 9.29 settings is a PrevWeaponActionID, the
    -- PREVIOUS weapon's action, which can stay set once the gun is lowered or put away. So the gun pose is only kept while something shows
    -- the gun is in use: it was just taken out (the reading turned on), I am aiming, or I fired within the last `hold` seconds (0 = never let go).
    hold = 12, HOLD_MIN = 0, HOLD_MAX = 120, active_at = nil, raw_out = nil, timed_out = false,
    gun_value = nil, aim_value = nil, last_t = nil, secs = { signal_on = 0, shown = 0, let_go = 0 }, changes = {}, change_key = nil }

pstat.gun = H.GUN -- (the panel, outside this block, reads it from here)

function H.GUN.read_signal(sig)
    local comp = H.POSE.comp_by_name[sig.comp]
    if comp == nil then return nil end
    local v = comp
    for _, name in ipairs(sig.path) do
        local ok, nv = pcall(function() return v:get_field(name) end)
        if not ok or nv == nil then return nil end
        v = nv
    end
    if type(v) == "userdata" or type(v) == "table" then v = as_text(v) end
    return v
end

function H.GUN.matches(sig, v)
    if v == nil then return nil end
    for _, x in ipairs(sig.vals) do
        if type(x) == "number" and type(v) == "number" then
            if math.abs(x - v) < 1e-4 then return true end
        elseif x == v then
            return true
        end
    end
    return false
end

-- One line for the settings key / the debug file.
function H.GUN.text(sig)
    if not sig then return "none" end
    local v = {}
    for _, x in ipairs(sig.vals) do v[#v + 1] = tostring(x) end
    return tostring(sig.text) .. " = " .. table.concat(v, "/")
end

function H.GUN.update(now)
    local G, P = H.GUN, H.POSE
    if not G.hook_tried and enemy.hit.hook.on and not enemy.hit.hook.tried and peer_present(now) then
        G.hook_tried = true
        pcall(enemy.hit.install_hook) -- (the shot hook was only installed for a joiner who receives enemies; the pose needs it too)
    end
    local gun, aim = nil, false
    G.gun_src, G.aim_src = "-", "-"
    G.gun_value, G.aim_value = nil, nil
    local gs = G.use_learned and G.signals.gun
    if gs then
        local rv = G.read_signal(gs)
        G.gun_value = rv
        local m = G.matches(gs, rv)
        if m ~= nil then gun, G.gun_src = m, "learned: " .. tostring(gs.text) end
        -- (9.30) the game's own gun component must agree: the learned PrevWeaponActionID was 2 during a block WITHOUT a gun (the 9.7
        -- recording: 0 -> 2 unarmed, 700 -> 702 with the handgun), and the gun pose showed whenever the player blocked with empty hands.
        -- PlayerGun.actionID is 0 while no gun action is running (before there is a gun, and while it is put away).
        if gun == true and P.gun_id == 0 then
            gun, G.gun_src = false, "the learned signal says gun, but PlayerGun.actionID is 0: ignored"
            G.vetoed = (G.vetoed or 0) + 1
        end
    end
    if gun == nil then
        gun, G.gun_src = P.gun_id ~= nil and P.gun_id ~= 0, "PlayerGun.actionID is not 0 (a guess)"
    end
    local as = G.use_learned and G.signals.aim
    if as then
        local rv = G.read_signal(as)
        G.aim_value = rv
        local m = G.matches(as, rv)
        if m ~= nil then aim, G.aim_src = m, "learned: " .. tostring(as.text) end
    end
    G.shoot = now - (state.gun_shot_at or -100) < G.SHOT_TAIL
    -- (9.30) the signal says "gun out"; the pose is shown only while the gun is in use (see the comment at H.GUN)
    local out = gun == true
    if out ~= G.raw_out then
        G.raw_out = out
        if out then G.active_at = now end -- (just taken out)
    end
    if aim == true or G.shoot then G.active_at = now end
    G.timed_out = false
    if out and G.hold > 0 and now - (G.active_at or -1e9) > G.hold then out, G.timed_out = false, true end
    G.gun = out or G.shoot
    G.aim = (aim == true) and G.gun
    -- what the next file needs to see: how long the signal was on, how long the pose was shown, how long it was let go, and every change
    local dt = G.last_t and math.max(0, math.min(now - G.last_t, 1)) or 0
    G.last_t = now
    if G.raw_out then G.secs.signal_on = G.secs.signal_on + dt end
    if G.gun then G.secs.shown = G.secs.shown + dt end
    if G.timed_out then G.secs.let_go = G.secs.let_go + dt end
    local key = table.concat({ tostring(G.raw_out), tostring(aim == true), tostring(G.shoot), tostring(G.timed_out) }, "|")
    if key ~= G.change_key then
        G.change_key = key
        G.changes[#G.changes + 1] = { t = math.floor(now * 10) / 10, signal_on = G.raw_out, aiming = aim == true, shot = G.shoot, let_go = G.timed_out,
            gun_value = G.gun_value ~= nil and dump_value(G.gun_value) or nil, aim_value = G.aim_value ~= nil and dump_value(G.aim_value) or nil }
        if #G.changes > 60 then table.remove(G.changes, 1) end
    end
end

function H.pose_field(obj, name)
    if obj == nil then return nil end
    local ok, v = pcall(function() return obj:get_field(name) end)
    if ok then return v end
    return nil
end

function H.pose_hist(tbl, id)
    if id == nil then return end
    local P = H.POSE
    if tbl[id] == nil then
        if P.hist_keys >= 80 then return end
        P.hist_keys = P.hist_keys + 1
        tbl[id] = 0
    end
    tbl[id] = tbl[id] + 1
end

-- How high the camera is above the player object, and from that whether they are crouching.
function H.pose_eye(go, now)
    local P = H.POSE
    local cam = state.local_pos
    P.eye = nil
    if not cam then return end
    local ok, y = pcall(function() return go:call("get_Transform"):call("get_Position").y end)
    if not ok or type(y) ~= "number" or y ~= y then return end
    local eye = cam.y - y
    if eye < 0.5 or eye > 2.6 then return end -- the camera is not on the player (a cutscene, a loading screen)
    P.eye = eye
    local bucket = math.floor(now / 10)
    local b = P.eye_buckets
    if b[bucket] == nil or eye > b[bucket] then b[bucket] = eye end
    local top
    for k, v in pairs(b) do
        if k < bucket - 12 then b[k] = nil elseif top == nil or v > top then top = v end
    end
    P.stand_eye = top or eye
    P.eye_drop = P.stand_eye - eye
    if P.crouch_h then
        if P.eye_drop < CFG.CROUCH_EXIT then P.crouch_h = false end
    elseif P.eye_drop > CFG.CROUCH_ENTER then
        P.crouch_h = true
    end
    P.crouch_reads = P.crouch_reads + (P.crouch_h and 1 or 0)
    -- (10.10) the deepest the camera sank in a crouch so far (shown in the friend's crouch report: the value CROUCH_DROP, 0.5 m, was a guess)
    local GF = CFG.friend and CFG.friend.ground
    if GF and P.crouch_h and P.eye_drop > (GF.cam_drop or 0) and P.eye_drop < 1.2 then GF.cam_drop = P.eye_drop end
end

-- Once per player object: every field of every player component whose name hints at crouching or a stance. They are only
-- READ (and compared with the camera-height crouch), so the file can say which one is the game's own crouch flag.
function H.pose_scan_candidates(comps, addr)
    local P = H.POSE
    P.cands, P.cands_addr = {}, addr
    for _, c in ipairs(comps) do
        pcall(function()
            local t = c.obj:get_type_definition()
            while t and #P.cands < 14 do
                local tn = t:get_full_name()
                if tn:find("^System%.") or tn:find("^via%.Component") or tn:find("^via%.Behavior") then break end
                for _, f in ipairs(t:get_fields() or {}) do
                    if #P.cands >= 14 then break end
                    if not f:is_static() then
                        local fname = f:get_name()
                        local low = fname:lower()
                        if low:find("crouch", 1, true) or low:find("squat", 1, true) or low:find("sneak", 1, true)
                            or low:find("duck", 1, true) or low:find("stoop", 1, true) or low:find("stance", 1, true)
                            or low:find("posture", 1, true) then
                            local ft = f:get_type()
                            P.cands[#P.cands + 1] = { comp = c.full, name = fname, ftype = ft and ft:get_full_name() or "?",
                                n = 0, agree = 0, ntrue = 0, vals = {}, nvals = 0, last = nil }
                        end
                    end
                end
                t = t:get_parent_type()
            end
        end)
    end
end

-- Returns true when this call actually took a new reading (the recorder counts those).
function H.pose_read(now)
    local P = H.POSE
    local gap = P.fail_run >= 20 and 1.0 or CFG.POSE_SAMPLE -- an unreadable player: only look once a second
    if now - P.next_at < gap then return false end
    P.next_at = now
    local go = player_object()
    if not go then
        P.guard, P.heal, P.heal_raw, P.guard_src = false, false, false, "-"
        P.crouch, P.crouch_h, P.crouch_src, P.eye = false, false, "-", nil
        P.seq, P.hands, P.gun, P.go_addr = nil, nil, nil, nil
        P.hands_id, P.gun_id, P.cancel = nil, nil, nil
        H.GUN.gun, H.GUN.aim, H.GUN.shoot = false, false, false
        return false
    end
    local addr = H.address_of(go)
    if addr ~= P.go_addr or now - P.comps_at > 3 then
        if addr ~= P.go_addr then
            P.seq, P.hands, P.gun = nil, nil, nil
            P.eye_buckets, P.stand_eye, P.crouch_h = {}, nil, false -- a new player object: measure the standing height again
        end
        P.go_addr, P.comps_at = addr, now
        local seq, hands, gun
        local comps = H.player_components()
        P.comp_by_name = {}
        for _, c in ipairs(comps) do
            P.comp_by_name[c.full] = c.obj
            if c.full == "app.PlayerSequenceManager" then seq = c.obj
            elseif c.full == "app.PlayerHands" then hands = c.obj
            elseif c.full == "app.PlayerGun" then gun = c.obj end
        end
        P.seq, P.hands, P.gun = seq, hands, gun
        if P.cands_addr ~= addr and #comps > 0 then pcall(H.pose_scan_candidates, comps, addr) end
    end
    P.reads = P.reads + 1

    local cancel = H.pose_field(P.seq, "IsGuardCancelAccepted")
    local hid = H.pose_field(P.hands, "<actionID>k__BackingField")
    local gid = H.pose_field(P.gun, "<actionID>k__BackingField")
    if type(cancel) == "boolean" then P.cancel = cancel else P.cancel = nil end -- (not `and/or`: false must stay false)
    P.hands_id = type(hid) == "number" and hid or nil
    P.gun_id = type(gid) == "number" and gid or nil
    H.pose_hist(P.hist_hands, P.hands_id)
    H.pose_hist(P.hist_gun, P.gun_id)
    if P.cancel == nil and P.hands_id == nil then
        P.fails, P.fail_run = P.fails + 1, P.fail_run + 1
    else
        P.fail_run = 0
    end

    local guard, src = false, "-"
    if P.cancel ~= nil then
        guard, src = P.cancel, "IsGuardCancelAccepted"
    elseif P.hands_id and P.GUARD_HANDS[P.hands_id] then
        guard, src = true, "PlayerHands.actionID"
    elseif P.gun_id and P.GUARD_GUN[P.gun_id] then
        guard, src = true, "PlayerGun.actionID"
    end
    P.guard, P.guard_src = guard, src
    P.heal_raw = P.hands_id ~= nil and P.HEAL_HANDS[P.hands_id] == true
    -- hands 16/17 also play while you look at the inventory (your 9.9 notes: "healing animation shows when checking
    -- inventory"). Not a heal while a menu is open, nor for a pose that was already running behind one for half a second.
    if P.heal_raw then
        if CFG.menu and CFG.menu.shown_now == true then
            P.inv_since = P.inv_since or now
            if now - P.inv_since > 0.5 then P.inv_pose = true end
            P.heal_raw = false
            P.heal_blocked = (P.heal_blocked or 0) + 1
        elseif P.inv_pose then
            P.heal_raw = false
            P.heal_blocked = (P.heal_blocked or 0) + 1
        end
    else
        P.inv_since, P.inv_pose = nil, false
    end
    if P.heal_raw then P.heal_until = now + CFG.HEAL_POSE_TAIL end
    P.heal = now < P.heal_until
    if P.guard then P.guard_reads = P.guard_reads + 1 end
    if P.heal_raw then P.heal_reads = P.heal_reads + 1 end

    H.pose_eye(go, now)
    -- the game has its own flag: app.PlayerMovement.IsCrouch. In the 9.9 file it was true for 12 % of the readings and
    -- CrouchRate was 1 in the same readings, while the camera-height guess said "crouched" for half of them.
    local isc = H.pose_field(P.comp_by_name["app.PlayerMovement"], "IsCrouch")
    if type(isc) == "boolean" then
        P.crouch, P.crouch_src = isc, "PlayerMovement.IsCrouch"
    else
        P.crouch = P.eye ~= nil and P.crouch_h == true
        P.crouch_src = P.eye ~= nil and "camera height" or "-"
    end
    if P.eye ~= nil then
        for _, c in ipairs(P.cands) do
            local v = H.pose_field(P.comp_by_name[c.comp], c.name)
            if v ~= nil then
                c.n, c.last = c.n + 1, v
                if type(v) == "boolean" then
                    if v then c.ntrue = c.ntrue + 1 end
                    if v == P.crouch_h then c.agree = c.agree + 1 end
                elseif type(v) == "number" then
                    local e = c.vals[v]
                    if e == nil and c.nvals < 8 then e = { n = 0, crouched = 0 }; c.vals[v] = e; c.nvals = c.nvals + 1 end
                    if e then
                        e.n = e.n + 1
                        if P.crouch_h then e.crouched = e.crouched + 1 end
                    end
                end
            end
        end
    end
    pcall(H.GUN.update, now)
    return true
end

state.pose_source = function(now)
    H.pose_read(now)
    local P = H.POSE
    local guard, heal = P.guard, P.heal
    if H.rec.use_signal and H.rec.signal and H.rec.guard_now(now) then guard = true end -- (an extra, learned signal the player ticked)
    if CFG.mbank then -- (10.4) the clip on Ethan's overlay layers: a block / heal the flags did not see
        if CFG.mbank.overlay_is("guard", now) then guard = true end
        if CFG.mbank.overlay_is("heal", now) then heal = true end
    end
    -- 9.9: a downed player's body still does what it does (the 9.8 build hid it); the other player sees the truth.
    local crouch = P.crouch
    P.sent.packets = P.sent.packets + 1
    if guard then P.sent.guard = P.sent.guard + 1 end
    if heal then P.sent.heal = P.sent.heal + 1 end
    if crouch then P.sent.crouch = P.sent.crouch + 1 end
    local G = H.GUN
    if G.gun then G.sent.gun = G.sent.gun + 1 end
    if G.aim then G.sent.aim = G.sent.aim + 1 end
    if G.shoot then G.sent.shoot = G.sent.shoot + 1 end
    return guard, heal, crouch, G.gun, G.aim, G.shoot
end

-- A table keyed by numbers, as one keyed by text (the debug file's JSON turns number keys into a list full of holes).
function H.strkeys(t)
    local out = {}
    for k, v in pairs(t) do out[tostring(k)] = v end
    return out
end

-- Fields that might be the game's own crouch flag, with how often each agreed with the camera-height crouch.
function H.crouch_report()
    local out = {}
    for _, c in ipairs(H.POSE.cands) do
        local e = { field = c.comp .. "." .. c.name, type = c.ftype, readings = c.n, last = c.last }
        if c.ftype == "System.Boolean" then
            e.true_readings = c.ntrue
            e.agrees_with_camera_height_percent = c.n > 0 and math.floor(c.agree / c.n * 100 + 0.5) or nil
        else
            local vals = {}
            for v, r in pairs(c.vals) do vals[tostring(v)] = { readings = r.n, while_camera_says_crouched = r.crouched } end
            e.values = vals
        end
        out[#out + 1] = e
    end
    return out
end

----------------------------------------------------------------------------------------------
-- Weapon lock and movement lock while down (9.8, rebuilt in 9.9 and again in 9.12). A downed player could still aim, shoot
-- and walk about. The recordings show the game's own gate for aiming and shooting: app.PlayerSequenceManager.IsAimAccepted
-- and IsAttackAccepted are TRUE normally and the game itself sets them FALSE while you block. While you are down (and only then)
-- this holds both at false and puts them back to true when you are up (not in the middle of a block, where the game puts them
-- back itself).
-- 9.8 wrote them once per frame; 9.9 at the start and end of each of the game's update phases. The real file (0.6) then said:
-- the game opens them again INSIDE its UpdateBehavior phase (found open after it 706 times in 5,241 frames, never anywhere
-- else), i.e. between our write before the phase and the moment the gun reads them. 9.12 therefore hooks the sequence
-- manager's own update methods that really exist (updateActionTrack, updateMovementTrack, onMotionUpdated ...: the file listed
-- them; there is no `update`, which is what 9.9 looked for) and closes the gates right after each. As a second line it refuses the
-- gun's own tryAttack / tryAimStart / trySemiAimStart while you are down. For movement it makes the sequence manager's
-- isMoveAccepted answer "no" and, if the game moves you anyway, puts you back where you fell (the report counts both).
-- Every route counts how often it fired and how often it found a gate open again, so the file says which of them works.
-- UNTESTED in the game: it WRITES two booleans of the player's sequence manager, skips a few gun calls and may set the player's
-- position. The checkboxes turn each part off.
----------------------------------------------------------------------------------------------
H.LOCK = {
    on = true, wrote = false, comp = nil, comp_at = -10, go_addr = nil, want = false,
    writes = 0, fails = 0, rewritten = 0, restored = 0, holds = 0, status = "idle",
    FIELDS = { "IsAimAccepted", "IsAttackAccepted" },
    PHASES = { "UpdateHID", "UpdateBehavior", "LateUpdateBehavior", "UpdatePhysics", "UpdateMotion", "UpdateGUI",
        "BeginRendering", "EndRendering" },
    -- where in the frame a downed player who has moved is put back (the movement itself happens somewhere in these)
    PIN_AT = { frame = true, ["post:UpdateBehavior"] = true, ["post:UpdatePhysics"] = true, ["post:LateUpdateBehavior"] = true,
        ["pre:BeginRendering"] = true },
    -- the sequence manager's own methods that exist (from the real file) and, as a fallback for other builds, the usual names
    -- (the generic update / lateUpdate / doUpdate names were in this list as a guess for other builds; get_method found an inherited
    -- one that fires for every object, 2.4 million calls in one session, so they are out. The real file showed the gates open
    -- again right after updateActionTrack, 1229 times, and nowhere else.)
    SEQ_AFTER = { "updateActionTrack", "updateMovementTrack", "updateDeadTrack", "updateJogTrack", "updateTurnTrack",
        "updateCodexTrack", "updateLaserSightTrack", "onMotionUpdated" },
    GUN_TRY = { "tryAttack", "tryAimStart", "trySemiAimStart" },
    HOT_PER_SECOND = 6000, -- a hook that fires more often than this is muted (it is on something much hotter than a per-frame method)
    phase = {}, phase_order = {}, registered = {},
    hooks = { on = true, tried = false, installed = {}, missing = {}, error = nil, methods = {}, dump = {}, calls = {}, muted = {}, win_at = 0, win = {} },
    guns = { on = true, tried = false, installed = {}, missing = {}, skipped = 0, error = nil },
    move = { on = true, tried = false, installed = {}, missing = {}, error = nil, getter_calls = 0, blocked = 0,
        pinned = 0, pin_fails = 0, reanchored = 0, anchor = nil, tolerance = 0.05, teleport = 4, pin_places = {}, fields = {}, xf = nil },
}

-- True if this hook is firing absurdly often (a second's worth over the limit): it is then ignored from now on.
function H.lock_hot(tag)
    local K = H.LOCK.hooks
    K.calls[tag] = (K.calls[tag] or 0) + 1
    if K.muted[tag] then return true end
    local now = os.clock()
    if now - K.win_at >= 1 then K.win_at, K.win = now, {} end
    K.win[tag] = (K.win[tag] or 0) + 1
    if K.win[tag] > H.LOCK.HOT_PER_SECOND then
        K.muted[tag] = true
        say("weapon lock: " .. tag .. " fires more than " .. H.LOCK.HOT_PER_SECOND .. " times a second: ignored from now on")
        return true
    end
    return false
end

-- A downed player who has moved from where they fell is put back (only sideways: gravity and stairs are left alone). A jump
-- of several metres is the game moving them (a cutscene, a new scene): that is the new place, not a walk.
function H.lock_pin(tag)
    local L = H.LOCK
    local M = L.move
    if not L.want or not M.on or not M.xf then return end
    local ok, p = pcall(function() return M.xf:call("get_Position") end)
    if not ok or not p then return end
    if not M.anchor then
        M.anchor = { x = p.x, y = p.y, z = p.z }
        return
    end
    local dx, dz = p.x - M.anchor.x, p.z - M.anchor.z
    local d = math.sqrt(dx * dx + dz * dz)
    if d > M.teleport then
        M.anchor = { x = p.x, y = p.y, z = p.z }
        M.reanchored = M.reanchored + 1
    elseif d > M.tolerance then
        local okp = pcall(function() M.xf:call("set_Position", Vector3f.new(M.anchor.x, p.y, M.anchor.z)) end)
        if okp then
            M.pinned = M.pinned + 1
            M.pin_places[tag] = (M.pin_places[tag] or 0) + 1
        else
            M.pin_fails = M.pin_fails + 1
        end
    end
end

-- Closes the gate if it is open. `tag` says where in the frame this happened (frame, pre:UpdateBehavior, hook:updateActionTrack ...).
function H.lock_close(tag)
    local L = H.LOCK
    if not L.want or not L.comp then return end
    local rec = L.phase[tag]
    if rec == nil then
        rec = { calls = 0, open = 0 }
        L.phase[tag] = rec
        L.phase_order[#L.phase_order + 1] = tag
    end
    rec.calls = rec.calls + 1
    for _, f in ipairs(L.FIELDS) do
        if H.pose_field(L.comp, f) == true then -- the game (or the start of the lock) has it on: take it away
            rec.open = rec.open + 1
            if L.wrote and tag == "frame" then L.rewritten = L.rewritten + 1 end -- we had it false at the last frame and the game put it back
            local ok = pcall(function() L.comp:set_field(f, false) end)
            if ok then
                L.writes = L.writes + 1
                L.wrote = true
            else
                L.fails = L.fails + 1
            end
        end
    end
    if L.PIN_AT[tag] then H.lock_pin(tag) end
end

-- Callbacks at the start and end of the game's update phases (a name the game does not have simply never fires).
function H.lock_register_phases()
    local L = H.LOCK
    for _, name in ipairs(L.PHASES) do
        if re.on_pre_application_entry then
            local ok = pcall(re.on_pre_application_entry, name, function() H.lock_close("pre:" .. name) end)
            if ok then L.registered[#L.registered + 1] = "pre:" .. name end
        end
        if re.on_application_entry then
            local ok = pcall(re.on_application_entry, name, function() H.lock_close("post:" .. name) end)
            if ok then L.registered[#L.registered + 1] = "post:" .. name end
        end
    end
end

-- Hooks one method by name: returns true if it was hooked. A crash while hooking is named by the next start's report.
function H.lock_hook(tn, td, name, pre, post)
    local okm, m = pcall(function() return td:get_method(name) end)
    if not okm or not m then return false end
    tracer.crumb("hooking", tn .. "." .. name)
    local okh = pcall(sdk.hook, m, pre or function() return H.CALL_ORIGINAL end, post or function(retval) return retval end)
    tracer.crumb("clean", "hook installed: " .. tn .. "." .. name) -- otherwise this stayed as "the suspect" for ever: the 0.9 file's first line blamed a hook that had long been installed)
    return okh
end

function H.lock_methods_of(tn)
    local out, td = {}, sdk.find_type_definition(tn)
    if not td then return out, nil end
    pcall(function()
        for _, m in ipairs(td:get_methods() or {}) do
            if #out < 160 then out[#out + 1] = m:get_name() end
        end
    end)
    return out, td
end

-- The first time you go down (each part only if its box is ticked): list the methods of the player's sequence manager / gun /
-- weapon change (for the file) and install the hooks. A box ticked later installs its part then.
function H.lock_install_hooks()
    local L = H.LOCK
    local K, G, M = L.hooks, L.guns, L.move
    local td_seq
    if (K.on and not K.tried) or (M.on and not M.tried) then
        local names, td = H.lock_methods_of("app.PlayerSequenceManager")
        if #K.methods == 0 then K.methods = names end
        if next(K.dump) == nil then
            for _, tn in ipairs({ "app.PlayerGun", "app.PlayerWeaponChange", "app.PlayerReticleController", "app.PlayerHands" }) do
                K.dump[tn] = (H.lock_methods_of(tn))
            end
        end
        td_seq = td
    end
    -- 1. close the gates right after the sequence manager's own updates
    if K.on and not K.tried then
        K.tried = true
        for i, name in ipairs(td_seq and L.SEQ_AFTER or {}) do
            local tag = "hook:" .. name
            local ok = H.lock_hook("app.PlayerSequenceManager", td_seq, name, nil, function(retval)
                if L.want and K.on and not H.lock_hot(tag) then pcall(H.lock_close, tag) end
                return retval
            end)
            if ok then K.installed[#K.installed + 1] = name
            else K.missing[#K.missing + 1] = name end
        end
        if not td_seq then K.error = "app.PlayerSequenceManager type not found"
        elseif #K.installed == 0 then K.error = "no update method found on app.PlayerSequenceManager (see the method list)" end
        say("weapon lock: gates closed after " .. (#K.installed > 0 and table.concat(K.installed, ", ") or "nothing") .. " of the sequence manager")
    end
    -- 2. the gun's own "may I shoot / aim" calls answer no
    if G.on and not G.tried then
        G.tried = true
        local td = sdk.find_type_definition("app.PlayerGun")
        local skip = sdk.PreHookResult and sdk.PreHookResult.SKIP_ORIGINAL
        if not td then
            G.error = "app.PlayerGun type not found"
        elseif skip == nil then
            G.error = "this REFramework can't skip a call"
        else
            for _, name in ipairs(L.GUN_TRY) do
                local tag = "gun:" .. name
                local skipped_now = false
                local ok = H.lock_hook("app.PlayerGun", td, name, function(args)
                    skipped_now = false
                    if L.want and G.on and not H.lock_hot(tag) then
                        skipped_now = true
                        G.skipped = G.skipped + 1
                        return skip
                    end
                    return H.CALL_ORIGINAL
                end, function(retval)
                    if skipped_now then -- the game's own answer was never computed: say "no"
                        skipped_now = false
                        local okz, z = pcall(sdk.to_ptr, 0)
                        if okz and z ~= nil then return z end
                    end
                    return retval
                end)
                if ok then G.installed[#G.installed + 1] = name else G.missing[#G.missing + 1] = name end
            end
        end
        say("weapon lock: gun calls refused while down: " .. (#G.installed > 0 and table.concat(G.installed, ", ") or "nothing hooked"))
    end
    -- 3. the sequence manager says "you may not move"
    if M.on and not M.tried then
        M.tried = true
        if not td_seq then M.error = "app.PlayerSequenceManager type not found" end
        for _, name in ipairs(td_seq and { "get_isMoveAccepted" } or {}) do
            local tag = "move:" .. name
            local ok = H.lock_hook("app.PlayerSequenceManager", td_seq, name, nil, function(retval)
                if L.want and M.on and not H.lock_hot(tag) then
                    M.getter_calls = M.getter_calls + 1
                    local okz, z = pcall(sdk.to_ptr, 0)
                    if okz and z ~= nil then
                        M.blocked = M.blocked + 1
                        return z
                    end
                end
                return retval
            end)
            if ok then M.installed[#M.installed + 1] = name else M.missing[#M.missing + 1] = name end
        end
        say("weapon lock: movement gate: " .. (#M.installed > 0 and table.concat(M.installed, ", ") or "nothing hooked") .. " (you are also put back where you fell if you move)")
    end
    pcall(tracer.crumb, "clean", "weapon lock hooks installed") -- the last word of the install, whatever came before
end

function H.lock_leaks()
    local L = H.LOCK
    local out = {}
    for _, tag in ipairs(L.phase_order) do
        local r = L.phase[tag]
        if r.open > 0 then out[#out + 1] = string.format("%s %d/%d", tag, r.open, r.calls) end
    end
    return #out > 0 and table.concat(out, ", ") or "none"
end

function H.lock_update(now)
    local L = H.LOCK
    local want = L.on and pstat.downed == true
    if not want and not L.wrote then
        L.want = false
        L.move.anchor = nil
        L.status = L.on and "idle (you are not down)" or "switched off"
        return
    end
    local go = player_object()
    if not go then -- a reload: the new player starts whole, nothing of ours is left on it
        L.comp, L.go_addr, L.wrote, L.want = nil, nil, false, false
        L.move.anchor, L.move.xf = nil, nil
        L.status = "idle (no player object)"
        return
    end
    local addr = H.address_of(go)
    if addr ~= L.go_addr then
        L.comp, L.go_addr, L.comp_at, L.want = nil, addr, -10, false
        L.move.anchor, L.move.xf = nil, nil
    end
    if not L.move.xf then
        local okx, xf = pcall(function() return go:call("get_Transform") end)
        if okx and xf then L.move.xf = xf end
    end
    if not L.comp and now - L.comp_at > 1 then
        L.comp_at = now
        for _, c in ipairs(H.player_components()) do
            if c.full == "app.PlayerSequenceManager" then
                L.comp = c.obj
                break
            end
        end
    end
    if not L.comp then
        L.want = false
        L.status = "app.PlayerSequenceManager not found: the weapon is NOT locked"
        return
    end
    if want then
        L.want = true
        pcall(H.lock_install_hooks)
        H.lock_close("frame")
        L.holds = L.holds + 1
        local M = L.move
        L.status = string.format("HOLDING aim and attack off (%d writes, %d failed writes; the game opened them again before: %s)%s%s",
            L.writes, L.fails, H.lock_leaks(),
            L.guns.on and string.format("; gun calls refused: %d", L.guns.skipped) or "",
            M.on and string.format("; movement: gate said no %d times, put back %d times", M.blocked, M.pinned) or "")
    else -- up again: give the gate back, unless a block is in the middle of it (the game does that itself at the end of the block)
        L.want = false
        L.move.anchor = nil
        H.pose_read(now)
        local blocking = H.POSE.cancel == true
        if not blocking then
            for _, f in ipairs(L.FIELDS) do
                if H.pose_field(L.comp, f) == false then pcall(function() L.comp:set_field(f, true) end) end
            end
            L.restored = L.restored + 1
        end
        L.wrote = false
        L.status = blocking and "released (the block in progress ends it)" or "released: aim and attack are back"
        say("weapon lock: " .. L.status)
    end
end
pstat.lock_update = H.lock_update
pstat.lock = H.LOCK -- (the settings read and write the switches through this)
pcall(H.lock_register_phases)

----------------------------------------------------------------------------------------------
-- Button 11 : "Record my player". It NEVER hooks anything. Ten times a second it reads the fields of the player's
-- app.Player* components (and one level of the objects they hold) plus a few values of the animation layers, and writes
-- down every change. Steady noise (anything that changes while you stand still) is muted. The guided script has you
-- block twice and use a healing item; the report then lists the fields that flipped on both blocks and came back after
-- (the block signal) and everything that changed while you healed (the animation). The best block candidate is then used
-- to drive the stand-in's block pose, and everything is in the debug file for me to read.
-- Reading is done through the same get_field calls the dumps in buttons 7/8 use. The animation values are the only calls
-- of the game's own methods, limited to zero-argument getters with plain return types; a breadcrumb is written before the
-- first call of each, so a crash names its cause on the next start.
----------------------------------------------------------------------------------------------
H.rec = {
    on = false, mode = nil, steps = nil, step = 0, step_end = 0, hotkey = 0x75, key_was_down = false, -- F6
    last_sample = -10, prev = nil, last_n = 0, targets = {}, motions = {}, targets_at = -10,
    field_cache = {}, getter_cache = {}, getter_seen = {}, crumbed = {}, meta = {}, muted = {}, muted_n = 0,
    ph = nil, phases = {}, events = 0, marks = 0, samples = 0,
    signal = nil, use_signal = false, sig_obj = nil, sig_obj_at = -10, sig_at = -10, sig_val = false, sig_raw = nil,
    report = {},
}
local R = H.rec
pstat.rec = R
R.MAX_KEYS, R.MAX_SUBS, R.MAX_EVENTS, R.PER_KEY_LOG, R.SAMPLE_EVERY = 1600, 40, 900, 6, 0.1
R.PRIM = { ["System.Boolean"] = true, ["System.Int32"] = true, ["System.UInt32"] = true, ["System.Int16"] = true,
    ["System.UInt16"] = true, ["System.Int64"] = true, ["System.UInt64"] = true, ["System.Byte"] = true,
    ["System.SByte"] = true, ["System.Single"] = true, ["System.Double"] = true, ["System.String"] = true }
-- animation getters worth reading (zero arguments, plain return type), and names never to call
R.GETTER_WORDS = { "motion", "frame", "node", "bank", "id", "name", "state", "speed", "blend", "weight", "current", "mode",
    "status", "priority", "loop", "play", "end", "guard", "heal" }
R.GETTER_SKIP = { "instance", "resource", "component", "joint", "transform", "gameobject", "owner", "parent", "child", "handle",
    "pointer", "address", "delegate", "callback" }

R.GUIDED = {
    { key = "prep", secs = 6, quiet = true, text = "Starting. Close this menu (Insert) and stand still in the game." },
    { key = "idle", secs = 4, text = "Stand still. Press nothing." },
    { key = "block1", secs = 4, text = "HOLD the block button now and keep holding it." },
    { key = "rest1", secs = 3, text = "Let go. Stand still." },
    { key = "block2", secs = 4, text = "HOLD the block button again." },
    { key = "rest2", secs = 3, text = "Let go. Stand still." },
    { key = "heal", secs = 45, heal = true, text = "Use a Herb / Chem Fluid now: open the inventory, use it, close it, wait for the animation to end. [F6] = done." },
    { key = "rest3", secs = 3, text = "Last moment: stand still." },
}
-- 9.28: the guided GUN recording. Each step with `vals` collects, for every field, which values it had in that step (after the first
-- second); the analysis then looks for fields whose values while the gun is out / while aiming never occur in the other steps.
R.GUN = {
    { key = "prep", secs = 6, quiet = true, text = "Starting. Close this menu (Insert) and stand still in the game. You need a gun you can aim and fire." },
    { key = "idle", secs = 4, vals = true, text = "Put the gun AWAY (empty hands) and stand still." },
    { key = "gun", secs = 5, vals = true, text = "Take the gun OUT. Do NOT aim. Stand still." },
    { key = "aim1", secs = 5, vals = true, text = "HOLD aim now and keep holding it." },
    { key = "rest1", secs = 4, vals = true, text = "Let go of aim. The gun stays out. Stand still." },
    { key = "aim2", secs = 5, vals = true, text = "HOLD aim again." },
    { key = "rest2", secs = 4, vals = true, text = "Let go of aim. Stand still." },
    { key = "shoot", secs = 40, vals = true, text = "AIM and fire THREE shots, one at a time, then press [F6]." },
    { key = "walk", secs = 6, vals = true, text = "Walk about with the gun out, NOT aiming." },
    { key = "rest3", secs = 3, quiet = true, text = "Last moment: stand still." },
}
R.GUN_POS = {
    gun = { "gun", "aim1", "rest1", "aim2", "rest2", "walk", "shoot" },
    aim = { "aim1", "aim2" },
}
R.GUN_NEG = {
    gun = { "idle" },
    aim = { "idle", "gun", "rest1", "rest2", "walk" },
}
R.GUN_WORDS = {
    gun = { "gun", "weapon", "equip", "hold", "draw", "ready", "arm" },
    aim = { "aim", "ads", "zoom", "reticle", "scope", "sight" },
}
R.FREE = {
    { key = "prep", secs = 6, quiet = true, text = "Starting. Close this menu (Insert) and stand still in the game." },
    { key = "idle", secs = 4, text = "Stand still for a moment (this learns what changes by itself)." },
    { key = "free", secs = 180, text = "Do it now. Press [F6] each time you START (it drops a numbered mark). Stop from the panel." },
}

function R.is_obj(v) return type(v) == "userdata" or type(v) == "table" end -- (managed objects are userdata in the game)

function R.say(msg)
    local old = dbg.pin
    dbg.pin = true
    say(msg)
    dbg.pin = old
end

function R.fmt(v)
    if type(v) == "number" then
        if v == math.floor(v) and math.abs(v) < 1e9 then return string.format("%d", v) end
        return string.format("%.4g", v)
    elseif type(v) == "string" then
        return '"' .. v:sub(1, 40) .. '"'
    end
    return tostring(v)
end

function R.differs(a, b)
    if type(a) == "number" and type(b) == "number" then return math.abs(a - b) > 1e-4 end
    return a ~= b
end

-- "prim": read the value. "obj": an app.* object whose own plain fields are read too. nil: ignored (arrays, structs, ...).
function R.kind_of(ft)
    if not ft then return nil end
    local tn = ft:get_full_name()
    if R.PRIM[tn] then return "prim" end
    local isenum = false
    pcall(function() isenum = ft:is_a("System.Enum") == true end)
    if not isenum then
        pcall(function()
            local par = ft:get_parent_type()
            isenum = par ~= nil and par:get_full_name() == "System.Enum"
        end)
    end
    if isenum then return "prim" end
    if tn:find("^app%.") and not tn:find("[%[`<]") then
        local okv, isval = pcall(function() return ft:is_value_type() end)
        if okv and isval == false then return "obj" end
        if okv and isval == true then return "val" end -- an enum the checks above did not recognise, or a struct: only numbers / flags are kept
    end
    return nil
end

function R.type_fields(td)
    local tn = td:get_full_name()
    local list = R.field_cache[tn]
    if list then return list end
    tracer.crumb("recorder", "fields of " .. tn)
    list = {}
    pcall(function()
        local t = td
        while t and #list < 140 do
            local n = t:get_full_name()
            if n:find("^System%.") or n:find("^via%.Component") or n:find("^via%.Behavior") then break end
            for _, f in ipairs(t:get_fields() or {}) do
                if not f:is_static() and #list < 140 then
                    local kind = R.kind_of(f:get_type())
                    if kind then list[#list + 1] = { name = f:get_name(), kind = kind } end
                end
            end
            t = t:get_parent_type()
        end
    end)
    R.field_cache[tn] = list
    return list
end

-- Reads the plain fields of obj into cur[key]. `comp` is the component's type name, `parent` the field it was reached through.
function R.read_obj(obj, comp, parent, cur, budget)
    local where = parent and (comp .. "." .. parent) or comp
    if not R.crumbed[where] then
        R.crumbed[where] = true
        tracer.crumb("recorder", "reading " .. where) -- the first read of each object: a crash names it
    end
    local okt, td = pcall(function() return obj:get_type_definition() end)
    if not okt or not td then return end
    for _, f in ipairs(R.type_fields(td)) do
        if budget.n >= R.MAX_KEYS then return end
        local okv, v = pcall(function() return obj:get_field(f.name) end)
        if okv and v ~= nil then
            if f.kind == "prim" or f.kind == "val" then
                if f.kind == "prim" and R.is_obj(v) then v = as_text(v) end
                local tv = type(v)
                if tv == "number" or tv == "boolean" or (tv == "string" and f.kind == "prim") then
                    local key = parent and (comp .. "." .. parent .. "." .. f.name) or (comp .. "." .. f.name)
                    cur[key] = v
                    budget.n = budget.n + 1
                    if not R.meta[key] then R.meta[key] = { comp = comp, path = parent and { parent, f.name } or { f.name } } end
                end
            elseif f.kind == "obj" and not parent and R.is_obj(v) and budget.subs < R.MAX_SUBS then
                budget.subs = budget.subs + 1
                R.read_obj(v, comp, f.name, cur, budget)
            end
        end
    end
end

function R.getter_ok(low)
    for _, w in ipairs(R.GETTER_SKIP) do
        if low:find(w, 1, true) then return false end
    end
    for _, w in ipairs(R.GETTER_WORDS) do
        if low:find(w, 1, true) then return true end
    end
    return false
end

function R.layer_getters(td)
    local tn = td:get_full_name()
    local list = R.getter_cache[tn]
    if list then return list end
    list = {}
    pcall(function()
        for _, m in ipairs(td:get_methods() or {}) do
            local name = m:get_name()
            local low = name:lower()
            if #list < 40 and (low:find("^get") or low:find("^is") or low:find("^has")) and R.getter_ok(low) then
                local params = m:get_param_types() or {}
                local ret = m:get_return_type()
                if #params == 0 and ret and (R.PRIM[ret:get_full_name()] or R.kind_of(ret) == "prim") then list[#list + 1] = name end
            end
        end
    end)
    R.getter_cache[tn] = list
    return list
end

function R.read_getters(obj, prefix, cur)
    local okt, td = pcall(function() return obj:get_type_definition() end)
    if not okt or not td then return end
    local tn = td:get_full_name()
    for _, name in ipairs(R.layer_getters(td)) do
        local id = tn .. "." .. name
        if not R.getter_seen[id] then
            R.getter_seen[id] = true
            tracer.crumb("recorder", id) -- before the first call of each getter: a crash names it
        end
        local ok, v = pcall(function() return obj:call(name) end)
        if ok and v ~= nil then
            if R.is_obj(v) then v = as_text(v) end
            local tv = type(v)
            if tv == "number" or tv == "boolean" or tv == "string" then cur[prefix .. "." .. name] = v end
        end
    end
end

function R.read_motion(m, prefix, cur)
    local okc, cnt = pcall(function() return m:call("getLayerCount") end)
    if not okc or type(cnt) ~= "number" then return end
    for i = 0, math.min(cnt, 8) - 1 do
        local okl, layer = pcall(function() return m:call("getLayer", i) end)
        if okl and R.is_obj(layer) then R.read_getters(layer, prefix .. ".layer" .. i, cur) end
    end
end

function R.refresh_targets(now)
    R.targets_at = now
    local comps = H.player_components()
    local t, motions = {}, {}
    for _, c in ipairs(comps) do
        if c.full:find("^app%.Player") then
            t[#t + 1] = c
        elseif c.full == "via.motion.Motion" then
            motions[#motions + 1] = c.obj
        end
    end
    if #motions == 0 then
        for _, m in ipairs(R.child_motions or {}) do motions[#motions + 1] = m end
    end
    R.targets, R.motions = t, motions
end

-- The animation component may sit on a child object of Pl0000 instead of on Pl0000: look once, when a recording starts.
function R.find_child_motions()
    R.child_motions = {}
    local shown = 0
    pcall(each_gameobject, function(go, path)
        if path:find("/Pl0000", 1, true) and shown < 12 then
            shown = shown + 1
            local okc, names = pcall(component_names, go)
            R.say("   player object: " .. path .. "  [" .. (okc and table.concat(names, ", ") or "?") .. "]")
            pcall(function()
                for _, c in ipairs(go:call("get_Components"):get_elements()) do
                    if c:get_type_definition():get_full_name() == "via.motion.Motion" and #R.child_motions < 3 then
                        R.child_motions[#R.child_motions + 1] = c
                    end
                end
            end)
        end
    end, 20000)
end

function R.sample()
    local cur, budget = {}, { n = 0, subs = 0 }
    for _, c in ipairs(R.targets) do R.read_obj(c.obj, c.full, nil, cur, budget) end
    local nplain = budget.n
    for i, m in ipairs(R.motions) do R.read_motion(m, "motion" .. i, cur) end
    return cur, nplain
end

function R.begin_step(i, now)
    R.close_phase(now)
    R.step = i
    local st = R.steps[i]
    R.step_end = now + st.secs
    local hc = enemy.hit.hook.counts
    R.ph = { key = st.key, t0 = now, keys = {}, quiet = st.quiet, heal = st.heal, vals = st.vals and {} or nil,
        shot0 = (hc.shoot or 0) + (hc.shootStart or 0) }
    R.say(string.format("--- step %d/%d  %s: %s", i, #R.steps, st.key, st.text))
end

function R.close_phase(now)
    local ph = R.ph
    if not ph then return end
    ph.t1 = now
    do
        local hc = enemy.hit.hook.counts
        ph.shot_calls = (hc.shoot or 0) + (hc.shootStart or 0) - (ph.shot0 or 0)
    end
    R.phases[#R.phases + 1] = ph
    R.ph = nil
    if ph.key == "idle" then -- whatever changed by itself while you stood still is noise from here on
        local names = {}
        for key, rec in pairs(ph.keys) do
            if rec.n >= 2 then
                R.muted[key] = true
                R.muted_n = R.muted_n + 1
                names[#names + 1] = key
            end
        end
        table.sort(names)
        R.say(string.format("   idle: %d fields change by themselves and are ignored from now on%s", #names,
            #names > 0 and (": " .. table.concat(names, ", ", 1, math.min(#names, 25)) .. (#names > 25 and ", ..." or "")) or ""))
    elseif not ph.quiet then
        local busy = {}
        for key, rec in pairs(ph.keys) do
            if rec.n > R.PER_KEY_LOG and not R.muted[key] then busy[#busy + 1] = { key, rec } end
        end
        table.sort(busy, function(a, b) return a[1] < b[1] end)
        for i = 1, math.min(#busy, 20) do
            local key, rec = busy[i][1], busy[i][2]
            R.say(string.format("   %s changed %d times in total: %s -> %s", key, rec.n, R.fmt(rec.first_from), R.fmt(rec.last)))
        end
    end
end

function R.on_change(now, key, pv, v)
    local ph = R.ph
    if not ph or R.muted[key] then return end
    local rec = ph.keys[key]
    if not rec then
        rec = { n = 0, first_from = pv, first_to = v, last = v, t_first = now - ph.t0 }
        ph.keys[key] = rec
    end
    rec.n = rec.n + 1
    rec.last = v
    rec.t_last = now - ph.t0
    if ph.quiet or ph.key == "idle" then return end
    if rec.n <= R.PER_KEY_LOG and R.events < R.MAX_EVENTS then
        R.events = R.events + 1
        R.say(string.format("  +%.2f s  %s : %s -> %s", now - ph.t0, key, R.fmt(pv), R.fmt(v)))
        if R.events == R.MAX_EVENTS then R.say("  (too many changes: no more are listed, the summaries at the end of each step still count them)") end
    end
end

function R.mark(now)
    R.marks = R.marks + 1
    R.say(string.format("  MARK %d at +%.2f s of step %s", R.marks, R.ph and (now - R.ph.t0) or 0, R.ph and R.ph.key or "?"))
end

function R.key_pressed(now)
    if not R.on then return end
    R.mark(now)
    if R.mode ~= "free" or R.steps[R.step].key == "prep" or R.steps[R.step].key == "idle" then
        if R.step < #R.steps then R.begin_step(R.step + 1, now) else R.stop("finished") end
    end
end

function R.start(mode)
    if R.on then return end
    R.report = {}
    local now = os.clock()
    if not player_object() then
        R.report = { "Load into the game first: your player object (Pl0000) was not found." }
        say("recorder: " .. R.report[1])
        return
    end
    R.on, R.mode = true, mode
    R.steps = mode == "free" and R.FREE or (mode == "gun" and R.GUN or R.GUIDED)
    R.prev, R.last_n, R.last_sample = nil, 0, -10
    R.muted, R.muted_n, R.phases, R.events, R.marks, R.samples = {}, 0, {}, 0, 0, 0
    R.ph, R.step = nil, 0
    R.say("=== recorder started (" .. mode .. ") ===")
    tracer.crumb("recorder", "start")
    R.find_child_motions()
    R.refresh_targets(now)
    local names = {}
    for _, c in ipairs(R.targets) do names[#names + 1] = c.full end
    R.say(string.format("   reading %d components: %s", #R.targets, table.concat(names, ", ")))
    R.say(string.format("   animation components found: %d", #R.motions))
    for i, m in ipairs(R.motions) do
        pcall(function()
            local okc, cnt = pcall(function() return m:call("getLayerCount") end)
            R.say(string.format("   motion%d: %s, getLayerCount -> %s", i, m:get_type_definition():get_full_name(), okc and tostring(cnt) or "failed"))
            if okc and type(cnt) == "number" and cnt > 0 then
                local layer = m:call("getLayer", 0)
                if R.is_obj(layer) then
                    local ln = layer:get_type_definition():get_full_name()
                    R.say("   layer type: " .. ln .. ", getters read: " .. table.concat(R.layer_getters(layer:get_type_definition()), ", "))
                    dbg.pin = true
                    probe_type(ln, false, { "frame", "motion", "node", "bank", "speed", "blend", "weight", "state" }, 60)
                    dbg.pin = false
                end
            end
        end)
        dbg.pin = true
        probe_type("via.motion.Motion", false, { "layer", "node", "motion", "bank" }, 50)
        dbg.pin = false
    end
    R.begin_step(1, now)
end

-- The report: block candidates, then what happened while healing.
function R.analyse()
    local lines = {}
    local function add(t) lines[#lines + 1] = t end
    local by = {}
    for _, p in ipairs(R.phases) do by[p.key] = p end
    add(string.format("recorder: %d samples, %d fields tracked, %d ignored as noise, %d changes listed", R.samples, R.last_n, R.muted_n, R.events))

    local b1, b2, r1, r2 = by.block1, by.block2, by.rest1, by.rest2
    if b1 and b2 and r1 and r2 then
        local cands = {}
        for key, a in pairs(b1.keys) do
            local b, ra, rb = b2.keys[key], r1.keys[key], r2.keys[key]
            local meta = R.meta[key]
            if b and ra and rb and meta and a.last ~= a.first_from and a.first_from == b.first_from and a.last == b.last
                and ra.last == a.first_from and rb.last == a.first_from then
                local kind = type(a.last) == "boolean" and 3
                    or ((type(a.last) == "number" and a.last == math.floor(a.last) and math.abs(a.last - a.first_from) <= 16) and 2)
                    or (type(a.last) == "string" and 2) or 0
                if kind > 0 then
                    -- a field that ALSO flips to the same value while healing is not a block signal (isBothHands was one)
                    local hk = by.heal and by.heal.keys[key]
                    local heal_too = hk ~= nil and (hk.first_to == a.last or hk.last == a.last)
                    cands[#cands + 1] = { key = key, off = a.first_from, on = a.last, kind = kind, heal_too = heal_too,
                        changes = a.n + b.n + ra.n + rb.n, meta = meta }
                end
            end
        end
        table.sort(cands, function(x, y)
            if x.heal_too ~= y.heal_too then return not x.heal_too end
            local sx, sy = x.kind * 10 - x.changes, y.kind * 10 - y.changes
            if sx ~= sy then return sx > sy end
            return x.key < y.key
        end)
        if #cands == 0 then
            add("BLOCK: no field switched on in both holds and back off after. Did the block really happen both times?")
            add("   (the lines above show what did change; send me the debug file)")
        else
            add("BLOCK candidates (on in both holds, off after, still while idle):")
            for i = 1, math.min(#cands, 10) do
                local c = cands[i]
                add(string.format("   %d. %s : %s -> %s  (%d changes)%s", i, c.key, R.fmt(c.off), R.fmt(c.on), c.changes,
                    c.heal_too and "  [also does this while healing: not a block signal]" or ""))
            end
            local best = cands[1]
            -- 9.8: the stand-in's block pose uses the built-in signal (see H.POSE). The best candidate is kept for the panel's
            -- checkbox as an EXTRA signal, never switched on by itself.
            R.signal = { comp = best.meta.comp, path = best.meta.path, on = best.on, off = best.off, text = best.key }
            R.use_signal = false
            add("The block pose uses the built-in signal (IsGuardCancelAccepted). #1 is only kept as an optional extra: tick it in the panel to add it.")
        end
    else
        add("BLOCK: the guided steps were not all done, so no block signal was worked out.")
    end

    -- the built-in signals checked against what you really did (so a different game version or setup shows up here)
    local function share(p)
        local pc = p and p.pose
        if not pc or pc.n == 0 then return nil, 0 end
        return pc.g, pc.n
    end
    do
        local g1, n1 = share(by.block1)
        local g2, n2 = share(by.block2)
        local gr1, nr1 = share(by.rest1)
        local gr2, nr2 = share(by.rest2)
        local gi, ni = share(by.idle)
        if n1 > 0 or n2 > 0 then
            local rest_on = (gr1 or 0) + (gr2 or 0)
            local ok = (g1 or 0) >= 3 and (g2 or 0) >= 3 and rest_on <= 16 and (gi or 0) == 0
            add(string.format("BUILT-IN BLOCK SIGNAL (%s): on in %d/%d readings of block 1, %d/%d of block 2; on in %d/%d while resting, %d/%d while idle: %s",
                H.POSE.guard_src, g1 or 0, n1, g2 or 0, n2, rest_on, nr1 + nr2, gi or 0, ni, ok and "WORKS" or "CHECK THIS (it did not follow your blocks)"))
        end
    end

    local hp = by.heal
    if hp then
        local pc = hp.pose
        if pc and pc.h > 0 then
            add(string.format("HEAL ANIMATION (PlayerHands.actionID 16/17): from +%.2f s to +%.2f s, %.1f s long.",
                pc.heal_first or 0, pc.heal_last or 0, (pc.heal_last or 0) - (pc.heal_first or 0)))
        else
            add("HEAL ANIMATION: PlayerHands.actionID never became 16/17 during that step, so the heal pose would not show. Did the character really use an item?")
        end
        if hp.item_name then
            add(string.format("   item: %s taken out of the inventory %.2f s into the step (%s the animation).", hp.item_name, hp.item_at - hp.t0,
                (pc and pc.heal_last and (hp.item_at - hp.t0) >= pc.heal_last - 0.5) and "at the end of" or "during"))
        else
            add("   no healing item left the inventory during that step (use a Herb, Chem Fluid or Remedy, not a different item).")
        end
        local list = {}
        for key, rec in pairs(hp.keys) do list[#list + 1] = { key = key, rec = rec } end
        table.sort(list, function(a, b)
            if a.rec.t_first ~= b.rec.t_first then return a.rec.t_first < b.rec.t_first end
            return a.key < b.key
        end)
        add(string.format("   %d fields changed during the heal (in time order, the ones that came back to where they started marked *):", #list))
        for i = 1, math.min(#list, 22) do
            local e = list[i]
            local back = not R.differs(e.rec.first_from, e.rec.last)
            add(string.format("   %s +%.2f..%.2f s  %s : %s -> %s%s  (%d)", back and "*" or " ", e.rec.t_first, e.rec.t_last or e.rec.t_first, e.key,
                R.fmt(e.rec.first_from), back and (R.fmt(e.rec.first_to) .. " -> ") or "", R.fmt(e.rec.last), e.rec.n))
        end
    end
    return lines
end

-- 9.28: fields whose values in the `pos` steps never occur in the `neg` steps (a step is only used when it was recorded).
function R.gun_candidates(by, pos, neg, words)
    local out = {}
    for key, meta in pairs(R.meta) do
        if not R.muted[key] then
            local pv, nv, ok = {}, {}, true
            local function take(names, into)
                for _, nm in ipairs(names) do
                    local ph = by[nm]
                    if ph and ph.vals then
                        local set = ph.vals[key]
                        if not set or set.n == 0 or set.n >= 7 then ok = false return end
                        for i = 1, set.n do
                            local dup = false
                            for _, x in ipairs(into) do if not R.differs(x, set[i]) then dup = true break end end
                            if not dup then into[#into + 1] = set[i] end
                        end
                    else
                        ok = false
                        return
                    end
                end
            end
            take(pos, pv)
            take(neg, nv)
            if ok and #pv >= 1 and #pv <= 4 and #nv >= 1 and #nv <= 6 then
                local overlap = false
                for _, a in ipairs(pv) do
                    for _, b in ipairs(nv) do if not R.differs(a, b) then overlap = true end end
                end
                if not overlap then
                    local low = table.concat(meta.path, "."):lower() -- (the field's own name: every PlayerGun field would fit "gun" if the type name counted)
                    local hit = 0
                    for _, w in ipairs(words) do if low:find(w, 1, true) then hit = 1 break end end
                    local t1 = type(pv[1])
                    out[#out + 1] = { key = key, pos = pv, neg = nv, meta = meta, hit = hit, kind = t1 == "boolean" and 1 or (t1 == "number" and 2 or 3) }
                end
            end
        end
    end
    table.sort(out, function(a, b)
        if a.hit ~= b.hit then return a.hit > b.hit end
        if a.kind ~= b.kind then return a.kind < b.kind end
        if #a.pos ~= #b.pos then return #a.pos < #b.pos end
        if #a.neg ~= #b.neg then return #a.neg < #b.neg end
        return a.key < b.key
    end)
    return out
end

function R.fmt_list(t)
    local o = {}
    for _, x in ipairs(t) do o[#o + 1] = R.fmt(x) end
    return table.concat(o, ", ")
end

function R.analyse_gun()
    local lines = {}
    local function add(t) lines[#lines + 1] = t end
    local by = {}
    for _, p in ipairs(R.phases) do by[p.key] = p end
    add(string.format("gun recording: %d samples, %d fields tracked, %d ignored as noise", R.samples, R.last_n, R.muted_n))
    local G = H.GUN
    for _, what in ipairs({ "gun", "aim" }) do
        local label = what == "gun" and "GUN OUT" or "AIMING"
        local need = {}
        for _, k in ipairs(R.GUN_POS[what]) do need[#need + 1] = k end
        for _, k in ipairs(R.GUN_NEG[what]) do need[#need + 1] = k end
        local missing = {}
        for _, k in ipairs(need) do if what == "gun" and k == "shoot" then -- (the shooting step is allowed to be skipped for the gun-out signal)
            elseif not (by[k] and by[k].vals) then missing[#missing + 1] = k end end
        if what == "gun" and not (by.shoot and by.shoot.vals) then
            local pos = {}
            for _, k in ipairs(R.GUN_POS.gun) do if k ~= "shoot" then pos[#pos + 1] = k end end
            R.GUN_POS_USED = pos
        else
            R.GUN_POS_USED = R.GUN_POS[what]
        end
        if #missing > 0 then
            add(label .. ": these steps were not recorded: " .. table.concat(missing, ", ") .. ", so no signal was worked out.")
        else
            local cands = R.gun_candidates(by, R.GUN_POS_USED, R.GUN_NEG[what], R.GUN_WORDS[what])
            if #cands == 0 then
                add(label .. ": no field had values in the steps with it that it never had in the other steps. Did it really happen in each step?")
            else
                add(label .. " candidates (values with it / values without it):")
                for i = 1, math.min(#cands, 8) do
                    local c = cands[i]
                    add(string.format("   %d. %s : %s  /  %s%s", i, c.key, R.fmt_list(c.pos), R.fmt_list(c.neg), c.hit == 1 and "  [name fits]" or ""))
                end
                local best = cands[1]
                G.signals[what] = { comp = best.meta.comp, path = best.meta.path, vals = best.pos, text = best.key }
                add(string.format("   -> #1 is now used for the %s pose (untick 'use the learned gun signals' in the panel to go back).", what == "gun" and "gun-out" or "aiming"))
            end
        end
    end
    -- the shot
    local sp = by.shoot
    if sp then
        local calls = sp.shot_calls or 0
        local installed = #enemy.hit.hook.installed
        add(string.format("SHOT: the gun's own shoot call ran %d times in the shooting step (you fired three shots; a shot runs one or two calls)%s", calls,
            installed == 0 and "  [the shot hook is not installed: the shooting pose cannot work]" or (calls >= 3 and ": OK" or ": CHECK THIS (fewer calls than shots)")))
        if sp.vals and by.aim1 and by.aim2 then
            local extra = {}
            for key, set in pairs(sp.vals) do
                local a, b = by.aim1.vals and by.aim1.vals[key], by.aim2.vals and by.aim2.vals[key]
                if set.n > 0 and set.n < 7 and a and b and not R.muted[key] then
                    local novel = {}
                    for i = 1, set.n do
                        local known = false
                        for _, src in ipairs({ a, b }) do
                            for j = 1, src.n do if not R.differs(src[j], set[i]) then known = true end end
                        end
                        if not known then novel[#novel + 1] = set[i] end
                    end
                    if #novel > 0 and #novel <= 3 then extra[#extra + 1] = string.format("%s : %s", key, R.fmt_list(novel)) end
                end
            end
            table.sort(extra)
            if #extra > 0 then
                add("while shooting these fields had values they never had while only aiming (what a shot or reload looks like, for a later build):")
                for i = 1, math.min(#extra, 12) do add("   " .. extra[i]) end
            end
        end
    else
        add("SHOT: the shooting step was not reached.")
    end
    return lines
end

function R.stop(why)
    if not R.on then return end
    local now = os.clock()
    R.close_phase(now)
    R.on = false
    R.say("=== recorder " .. tostring(why or "stopped") .. " ===")
    local ok, lines = pcall(R.mode == "gun" and R.analyse_gun or R.analyse)
    if ok then
        R.report = lines
        for _, l in ipairs(lines) do R.say(l) end
    else
        R.report = { "recorder: analysis failed: " .. tostring(lines) }
        R.say(R.report[1])
    end
    R.say("=== recorder done: send me the debug file ===")
    tracer.crumb("clean", "recorder finished")
end

-- Every frame: the F6 key, the steps, the ten-per-second reading.
function pstat.rec_update(now)
    local okk, down = pcall(function() return reframework:is_key_down(R.hotkey) end)
    down = okk and down == true
    if down and not R.key_was_down then R.key_pressed(now) end
    R.key_was_down = down
    if not R.on then return end

    local st = R.steps[R.step]
    if st then
        local ended = now >= R.step_end
        local P = H.POSE
        H.pose_read(now)
        if P.reads ~= R.pose_reads_seen then -- a new reading of my block / heal signals: count it against the step it happened in
            R.pose_reads_seen = P.reads
            local ph = R.ph
            if ph then
                local pc = ph.pose
                if not pc then
                    pc = { n = 0, g = 0, h = 0 }
                    ph.pose = pc
                end
                pc.n = pc.n + 1
                if P.guard then pc.g = pc.g + 1 end
                if P.heal_raw then
                    pc.h = pc.h + 1
                    pc.heal_first = pc.heal_first or (now - ph.t0)
                    pc.heal_last = now - ph.t0
                    ph.last_event_at = now
                    if not ph.anim_seen then
                        ph.anim_seen = true
                        R.say(string.format("  MARK heal animation started (PlayerHands.actionID %s) at +%.2f s", tostring(P.hands_id), now - ph.t0))
                    end
                elseif ph.anim_seen and not ph.anim_end_said then
                    ph.anim_end_said = true
                    R.say(string.format("  MARK heal animation over (PlayerHands.actionID %s) at +%.2f s", tostring(P.hands_id), now - ph.t0))
                end
            end
        end
        if st.heal and R.ph then
            local ph = R.ph
            if ph.item_name and not ph.item_said then
                ph.item_said = true
                R.say(string.format("  MARK item used: %s at +%.2f s (the game takes it at the END of the animation)", ph.item_name, ph.item_at - ph.t0))
            end
            if ph.item_at and (not ph.last_event_at or ph.item_at > ph.last_event_at) then ph.last_event_at = ph.item_at end
            -- the animation and the gun coming back up have had their time: 6 s after the last sign of the heal
            if ph.last_event_at and now >= ph.last_event_at + 6 then ended = true end
        end
        if ended then
            if R.step < #R.steps then R.begin_step(R.step + 1, now) else R.stop("finished") end
            if not R.on then return end
        end
    end

    if now - R.last_sample < R.SAMPLE_EVERY then return end
    R.last_sample = now
    if not player_object() then R.prev = nil return end
    if now - R.targets_at > 3 then R.refresh_targets(now) end
    local cur, nplain = R.sample()
    local n = 0
    for _ in pairs(cur) do n = n + 1 end
    R.samples = R.samples + 1
    if R.last_n > 0 and n < R.last_n * 0.5 then -- the player object was replaced (a loading screen): start over rather than log everything as changed
        R.prev = nil
        R.last_n = n
        R.refresh_targets(now)
        R.say("  (player objects changed at +" .. string.format("%.1f", R.ph and (now - R.ph.t0) or 0) .. " s: skipped a reading)")
        return
    end
    R.last_n = math.max(R.last_n, n)
    local vph = R.ph
    if vph and vph.vals and now - vph.t0 >= 1.0 then -- (9.28) the values each field has in this step, once the pose has settled
        for key, v in pairs(cur) do
            if R.meta[key] then
                local set = vph.vals[key]
                if not set then
                    set = { n = 0 }
                    vph.vals[key] = set
                end
                if set.n < 7 then
                    local seen = false
                    for i = 1, set.n do
                        if not R.differs(set[i], v) then seen = true break end
                    end
                    if not seen then
                        set.n = set.n + 1
                        set[set.n] = v
                    end
                end
            end
        end
    end
    local prev = R.prev
    R.prev = cur
    if not prev then return end
    local changed = {}
    for key, v in pairs(cur) do
        local pv = prev[key]
        if pv ~= nil and R.differs(pv, v) then changed[#changed + 1] = key end
    end
    table.sort(changed)
    for _, key in ipairs(changed) do R.on_change(now, key, prev[key], cur[key]) end
end

function pstat.rec_draw(now)
    if not R.on then return end
    local st = R.steps[R.step]
    if not st then return end
    pcall(draw.text, string.format("RE7MP RECORDER (%s)  step %d/%d", R.mode, R.step, #R.steps), 24, 120, 0xFF3030FF)
    pcall(draw.text, st.text, 24, 140, 0xFF00FFFF)
    pcall(draw.text, string.format("%.0f s left   [F6] %s", math.max(0, R.step_end - now), R.mode == "free" and "mark" or "next step"), 24, 160, 0xFFFFFFFF)
end

-- ---- the learned block signal ----
function R.signal_text()
    local s = R.signal
    if not s then return "none" end
    return s.text or (s.comp .. "." .. table.concat(s.path, "."))
end

function R.signal_component(full, now)
    if R.sig_obj and R.sig_obj_full == full and now - R.sig_obj_at < 3 then return R.sig_obj end
    R.sig_obj_at = now
    R.sig_obj, R.sig_obj_full = nil, full
    for _, c in ipairs(H.player_components()) do
        if c.full == full then
            R.sig_obj = c.obj
            break
        end
    end
    return R.sig_obj
end

-- Is the learned block signal on right now? Read at most ten times a second.
function R.guard_now(now)
    local sig = R.signal
    if not sig then return false end
    if now - R.sig_at < 0.1 then return R.sig_val end
    R.sig_at = now
    local v = R.signal_component(sig.comp, now)
    if v ~= nil then
        for _, name in ipairs(sig.path) do
            local ok, nv = pcall(function() return v:get_field(name) end)
            if not ok or nv == nil then
                v = nil
                break
            end
            v = nv
        end
    end
    if R.is_obj(v) then v = as_text(v) end
    R.sig_raw = v
    R.sig_val = v ~= nil and v == sig.on
    return R.sig_val
end

function pstat.rec_panel()
    local now = os.clock()
    if R.on then
        local st = R.steps[R.step]
        imgui.text(string.format("    RECORDING (%s): step %d/%d  %s", R.mode, R.step, #R.steps, st and st.text or ""))
        if imgui.button("    11. " .. (R.mode == "free" and "Mark now" or "Next step") .. "   [F6]##recnext") then R.key_pressed(now) end
        if imgui.button("    11. Stop and write the report##recstop") then R.stop("stopped from the panel") end
    else
        if imgui.button("11. Record my player, guided (block twice, then use a Herb)") then R.start("guided") end
        if imgui.button("11. Record my player, free (you mark what you do with F6)") then R.start("free") end
        if imgui.button("11. Record my player with a GUN (gun out, aim twice, fire three shots)") then R.start("gun") end
        imgui.text("    Only reads fields and writes down what changed: no hooks, so it can't crash the game like tracing can.")
    end
    for i = math.max(1, #R.report - 30), #R.report do imgui.text("    " .. R.report[i]) end
    do -- (9.28) the gun signals this recording learned
        local G = H.GUN
        if G.signals.gun or G.signals.aim then
            local cg, vg = imgui.checkbox("    Use the learned gun signals for the gun / aim pose##recgun", G.use_learned)
            if cg and type(vg) == "boolean" then G.use_learned = vg end
            imgui.text("    gun out: " .. G.text(G.signals.gun) .. "   (now: " .. (G.gun and "yes" or "no") .. ", from " .. G.gun_src .. ")")
            imgui.text("    aiming: " .. G.text(G.signals.aim) .. "   (now: " .. (G.aim and "yes" or "no") .. ", from " .. G.aim_src .. ")")
            if imgui.button("    Forget the learned gun signals##recgunforget") then G.signals = {} end
        end
    end
    if R.signal then
        local c, v = imgui.checkbox("    Use the learned block signal for my block pose##recsig", R.use_signal)
        if c then R.use_signal = v end
        imgui.text(string.format("    signal: %s   now: %s", R.signal_text(), R.use_signal and (R.guard_now(now) and "ON" or "off") or "(not used)"))
        if imgui.button("    Forget the learned block signal##recforget") then R.signal, R.use_signal, R.sig_val = nil, false, false end
    end
end
end -- do

----------------------------------------------------------------------------------------------
-- Version check (release 0.8). Each script tells the other which release it is (message kind 8,
-- "v|release|build|exe|protocol") when the other player appears and every 20 s after. A different
-- release is flagged in the panel and the chat. A script older than this feature sends nothing, so
-- "no version after 8 s" means an older release. Also checks that re7mp.exe and this script agree.
----------------------------------------------------------------------------------------------
do
local V = CFG.ver
local VER_MSG = 8
V.remote = nil        -- { release, build, exe, proto, at } from the other player's script
V.summary = nil       -- one line for the panel and the debug file
V.problem = nil       -- text if something is wrong (shown in red)
V.sent_at, V.peer_was, V.seen_at = -100, false, nil

local function mine()
    return string.format("v|%s|%s|%s|%s", CFG.RELEASE, CFG.BUILD, state.exe_version or "?", tostring(state.exe_proto or "?"))
end

net_on(VER_MSG, function(payload)
    local rel, build, exe, proto = payload:match("^v|([%w%.%-]+)|([%w%.%-]+)|([%w%.%-%?]*)|([%w%?]*)$")
    if not rel then return end
    local first = V.remote == nil or V.remote.release ~= rel
    V.remote = { release = rel, build = build, exe = exe, proto = proto, at = os.clock() }
    local who = state.remote_name or CFG.DEFAULT_NAME
    V.summary = string.format("%s runs release v%s (script build %s, re7mp.exe v%s)", who, rel, build, exe)
    if rel ~= CFG.RELEASE then
        V.problem = string.format("%s is on release v%s but you are on v%s: update so you both run the same version", who, rel, CFG.RELEASE)
    else
        V.problem = nil
    end
    -- (10.24) the same release but another BUILD (the alpha builds share a release number): only a note, never a problem, since two nearby builds may well work together
    if rel == CFG.RELEASE and build ~= CFG.BUILD then
        V.build_note = string.format("%s runs script build %s and you run %s (the same release): changes between builds can change what is synced, so for a test both of you should run the same build", who, build, CFG.BUILD)
    else
        V.build_note = nil
    end
    if first then
        say("version: " .. V.summary)
        if V.problem then chat_add("Version", V.problem) end
    end
    if V.build_note and V.build_noted ~= build then
        V.build_noted = build
        say("version: " .. V.build_note)
    end
end)

function V.update(now)
    local present = peer_present(now)
    if present and not V.peer_was then V.seen_at, V.intro_due = now, true end
    if not present then V.seen_at, V.intro_due = nil, false end
    V.peer_was = present
    -- (re)introduce ourselves when they appear, and every 20 s (their script may have been reloaded). The first time waits a
    -- moment (at most 2 s) until re7mp.exe's release is known, so the other player is not told "re7mp.exe v?".
    if present and V.intro_due and (state.exe_version or now - V.seen_at >= 2) then
        V.intro_due = false
        V.sent_at = now
        net_send(VER_MSG, mine())
    elseif present and not V.intro_due and now - V.sent_at >= 20 then
        V.sent_at = now
        net_send(VER_MSG, mine())
    end
    -- they never said which version they run: an older script (Ethan's friend is not a script)
    local who = state.remote_name or CFG.DEFAULT_NAME
    if present and not V.remote and V.seen_at and now - V.seen_at > 8 and not CFG.friend.is_name(who) then
        V.summary = who .. " runs a script older than release v" .. CFG.RELEASE .. " (it reports no version)"
        if not V.problem then
            V.problem = who .. "'s script is older than release v" .. CFG.RELEASE .. ": update so you both run the same version"
            say("version: " .. V.summary)
            chat_add("Version", V.problem)
        end
    end
    -- the exe and this script should be the same release (the exe installs its own copy of the script)
    -- (not latched: the warning goes away as soon as the exe reports the same release, e.g. after it was updated and started)
    if state.exe_version and state.exe_version ~= CFG.RELEASE then
        V.exe_problem = string.format("re7mp.exe is v%s but this script is v%s: use \"Install Lua script\" in the exe, or update both", state.exe_version, CFG.RELEASE)
        if V.exe_warned ~= state.exe_version then
            V.exe_warned = state.exe_version
            say("version: " .. V.exe_problem)
        end
    else
        V.exe_problem, V.exe_warned = nil, nil
    end
end

function V.panel()
    pcall(imgui.text, string.format("Release v%s   (script build %s%s)", CFG.RELEASE, CFG.BUILD,
        state.exe_version and (", re7mp.exe v" .. state.exe_version) or ""))
    local function warn(text)
        if not pcall(imgui.text_colored, text, 0xFF3030FF) then imgui.text(text) end
    end
    if V.exe_problem then warn(V.exe_problem) end
    if V.problem then warn(V.problem)
    elseif V.summary then imgui.text(V.summary) end
    if V.build_note and not V.problem then imgui.text(V.build_note) end
    -- (10.24) a tester on the public alpha: said at the top of the panel, so a screenshot or a debug file shows it
    if CFG.chan and CFG.chan.value == "alpha" then
        imgui.text("ALPHA channel (re7mp.exe build " .. tostring(CFG.chan.exe_build or "?") .. "): expect things to break; send debug.json from both players with what you were doing.")
    end
end
end -- do

----------------------------------------------------------------------------------------------
-- Co-op saves: re7mp.exe shares saves made while connected (TCP) and lists what it installed in
-- reframework/data/re7mp_coop_saves.json. This reads that file and announces new arrivals.
----------------------------------------------------------------------------------------------
local saves = { enabled = false, last = "", entries = {}, occupied = {}, dir = "", last_read = 0, notified = nil }
CFG.saves = saves

-- Does the game itself say a save exists in this slot (SaveDataManager.isExistData)? true / false / nil when it can't be asked.
-- Asked at most every 2 s: it is one call for each of 60 slots.
function saves.game_sees(slot, now)
    if now - (saves.seen_at or -100) > 2 then -- (10.20: still every 2 s, but only while the panel or a debug file asks, and 21 questions, not 61, from a scan that is up to 2 s old)
        saves.seen_at = now
        local ok, set = pcall(function() return CFG.lm.game_slots(2, saves.SCAN_TO) end)
        saves.seen = ok and set or nil
    end
    if saves.seen == nil then return nil end
    return saves.seen[slot] == true
end

-- 9.28: the saves I make myself while connected to someone. The exe only knows the copy that was sent at the start ("sent") and
-- the ones received; a save made later in a normal slot was not marked, so the host could not tell afterwards who a save was
-- played with. This watches which slots the game says exist (SaveDataManager.isExistData, every 5 s): a slot that is NEW while a
-- partner is connected, and that the exe does not list, is written down as played with that partner and labelled "[CO-OP with Bob]"
-- in the Load screen. A save written over an existing slot looks the same as before, so it can NOT be told (see the README).
saves.played, saves.pending, saves.prev_set, saves.watch_at, saves.played_loaded = {}, {}, nil, -100, false
-- (10.20) How often the script looks at things around the saves. Before: the exe's save file every 1 s, and the game's 61 save slots (isExistData 0 to 60) every 5 s whether or
-- anybody was connected or not, and again for the panel and for every debug file. In the 10.15 host file the five slowest frames (400 to 600 ms) were all in that part of the
-- frame, and the game's own autosave writes into the same folder. Now: the exe's file every 5 s (every 2 s while the REFramework menu is open, every 15 s while nothing is
-- shared and nobody is connected), the slots only to 20 (the game lists 15 at most; the exe never installs past 15), every 5 s only while someone is connected and every
-- 60 s otherwise, and one scan serves the panel and the debug file. (RE7MP_TEST_SAVES_S: only the test harness sets it; it keeps the old 1 s file read.)
saves.READ_S, saves.READ_IDLE_S, saves.READ_UI_S = 5, 15, 2
saves.WATCH_S, saves.WATCH_IDLE_S, saves.SCAN_TO = 5, 60, 20
saves.TEST_READ_S = tonumber(rawget(_G, "RE7MP_TEST_SAVES_S"))
saves.read_stats = { reads = 0 }
function saves.read_gap(now)
    if saves.TEST_READ_S then return saves.TEST_READ_S end
    if state.ui_at ~= nil and now - state.ui_at < 1.5 then return saves.READ_UI_S end -- the REFramework menu is open: somebody may be looking at the panel
    if saves.enabled or peer_present(now) then return saves.READ_S end
    return saves.READ_IDLE_S
end
function saves.played_load()
    saves.played_loaded = true
    local d = FILES.read("coop_played")
    if type(d) ~= "table" or type(d.slots) ~= "table" then return end
    local n = 0
    for _, e in ipairs(d.slots) do
        if type(e) == "table" and tonumber(e.slot) and type(e.partner) == "string" and n < 60 then
            local sl = math.floor(tonumber(e.slot))
            if sl >= 1 and sl <= 99 then
                saves.played[sl] = { partner = e.partner:sub(1, 40), when = type(e.when) == "string" and e.when:sub(1, 20) or "" }
                n = n + 1
            end
        end
    end
end

function saves.played_save()
    local list = {}
    for sl, p in pairs(saves.played) do list[#list + 1] = { slot = sl, partner = p.partner, when = p.when } end
    table.sort(list, function(a, b) return a.slot < b.slot end)
    pcall(json.dump_file, FILES.path("coop_played"), { slots = list, about = "re7mp: saves made while playing with someone (labelled in the Load screen)" })
end

function saves.watch(now)
    if not saves.played_loaded then saves.played_load() end
    local who = state.remote_name
    local with = peer_present(now) and type(who) == "string" and who ~= ""
    -- 10.20: with nobody connected only a slow look is needed (a deleted slot is forgotten); the first look after somebody appears only takes the picture, so a save that
    -- was made before they came is not taken for one made with them (before, the picture was never more than 5 s old).
    local fresh = with and not saves.watch_with
    local fast = with or next(saves.pending) ~= nil
    if not fresh and now - saves.watch_at < (fast and saves.WATCH_S or saves.WATCH_IDLE_S) then saves.watch_with = with return end
    -- (10.27) a look is due, but the game is writing a save: 61 isExistData questions into the folder it is writing to took 626, 499 and 222 ms in the 10.26 file. Wait for the save to end
    -- (and 1.5 s after). Nothing is lost by it: watch_with and watch_at are left alone, so a "fresh" look stays fresh and a due look stays due, and the new slot is seen right after.
    if CFG.perf.saving_quiet(now, "slot_watch") then return end
    saves.watch_with = with
    saves.watch_at = now
    local ok, set = pcall(function() return CFG.lm.game_slots(nil, saves.SCAN_TO) end)
    if not ok or type(set) ~= "table" then return end
    local mine = {}
    for _, e in ipairs(saves.entries) do
        if type(e) == "table" and tonumber(e.slot) then mine[math.floor(tonumber(e.slot))] = true end
    end
    local changed = false
    if saves.prev_set and not fresh then
        for sl in pairs(set) do
            if not saves.prev_set[sl] and with and not mine[sl] and not saves.played[sl] and not saves.pending[sl] then
                saves.pending[sl] = { at = now, partner = who }
            end
        end
    end
    for sl, p in pairs(saves.pending) do
        if not set[sl] or mine[sl] then
            saves.pending[sl] = nil -- gone again, or the exe turned out to know it (a save that was received)
        elseif now - p.at >= 6 then -- the exe has had time to list it
            saves.pending[sl] = nil
            local okd, when = pcall(os.date, "%Y-%m-%d %H:%M")
            saves.played[sl] = { partner = tostring(p.partner):sub(1, 40), when = okd and when or "" }
            changed = true
            say(string.format("co-op saves: slot %d was saved while playing with %s", sl, tostring(p.partner)))
        end
    end
    for sl in pairs(saves.played) do
        if not set[sl] or mine[sl] then saves.played[sl] = nil changed = true end -- deleted, or now a sent / received save
    end
    saves.prev_set = set
    if changed then saves.played_save() end
end

local function read_saves(now)
    saves.last_read = now
    saves.read_stats.reads = saves.read_stats.reads + 1
    local d = json.load_file("re7mp_coop_saves.json")
    if type(d) ~= "table" then return end
    saves.enabled = d.enabled == true
    local last = tostring(d.last or "")
    if saves.notified == nil then
        saves.notified = last -- the first read is old news
    elseif last ~= saves.notified then
        saves.notified = last
        chat_add("Co-op saves", last)
    end
    saves.last = last
    saves.entries = type(d.entries) == "table" and d.entries or {}
    saves.occupied = type(d.occupied) == "table" and d.occupied or {}
    saves.dir = type(d.dir) == "string" and d.dir or ""
    -- (9.42) the Steam32 account ids re7mp.exe published: this PC's watched folder, and the other player's (told by their re7mp.exe). 0 = not known.
    saves.account = math.floor(tonumber(d.account) or 0)
    saves.partner_account = math.floor(tonumber(d.partner_account) or 0)
end

-- (9.42) One line naming both Steam accounts, for the panel and the load-screen scan.
function saves.accounts_line()
    local mine, theirs = saves.account or 0, saves.partner_account or 0
    if mine == 0 then
        return "Steam accounts: not known (re7mp.exe older than 9.42, or its save folder is not a userdata\\<id> path), so none is shared."
    end
    local s = "Steam accounts: your saves are in account " .. mine .. "'s folder; "
    if theirs == 0 then
        return s .. "the other player's account is not known yet (their re7mp.exe 9.42 or newer tells it once connected)."
    elseif theirs == mine then
        return s .. "the other player's account is the SAME (Ethan's friend, or you both use one Steam account)."
    end
    return s .. "the other player's account is " .. theirs .. "."
end

----------------------------------------------------------------------------------------------
-- Load screen labels (EXPERIMENTAL; the layout below was read from a real scan, the writing itself is untested in the game).
-- The Load list is a GUI (SystemObject/MenuManager/SaveMenuGUI, component app.SaveMenu) that the game fills in while it
-- runs, so its text can be changed from here. This puts [CO-OP: <name>] in front of the objective text (m_objective) of
-- every co-op save (the ones you sent AND the ones you received; <name> is the other player it was last shared with).
-- Each row of the list shows its slot number in m_number ("1", "2" ... or "Autosave") and the game re-uses nine row
-- controls for all your saves, rewriting them as you scroll, so rows are matched to save files by that number (never
-- by position) and the labels are put back ten times a second. Row N is the file dataNNNSlot.bin (found by looking at a
-- real save folder: the file times match the rows); the "Autosave" row is data000.bin, which is never shared, so it never
-- gets a label. Before writing anything the script asks the game which slots exist (SaveDataManager.isExistData) and
-- compares that with the folder re7mp.exe watches: if they differ, the exe is probably looking at another Steam account's
-- saves and nothing is written. Button 10 records what the screen is made of.
----------------------------------------------------------------------------------------------
do
local LM = CFG.lm
LM.enabled = false
LM.fast_at = -100
LM.status = "Off."
LM.written = 0              -- labels written this session
LM.last_scan, LM.guis_at = -100, -100
LM.guis = {}
LM.api = {}                 -- which GUI method names worked (for the debug file)

-- Calls the first method of `names` that works on obj and returns something.
function LM.try(obj, names)
    for _, n in ipairs(names) do
        local ok, v = pcall(obj.call, obj, n)
        if ok and v ~= nil then
            LM.api[names[1]] = n
            return v
        end
    end
    return nil
end

function LM.kids(ctl)
    local out = {}
    local c = LM.try(ctl, { "get_Child", "get_FirstChild" })
    while c ~= nil and #out < 300 do
        out[#out + 1] = c
        c = LM.try(c, { "get_Next", "get_NextSibling" })
    end
    return out
end

function LM.roots(gui)
    local r
    local view = LM.try(gui, { "get_View" })
    if view then r = LM.try(view, { "get_RootWindow", "get_Root", "get_Window", "get_FirstChild", "get_Child" }) end
    if r == nil then r = LM.try(gui, { "get_RootWindow", "get_Child" }) end
    if r == nil then return {} end
    local out = { r }
    local n = LM.try(r, { "get_Next" })
    while n ~= nil and #out < 20 do
        out[#out + 1] = n
        n = LM.try(n, { "get_Next" })
    end
    return out
end

-- Every control under the GUI as a flat list: { ctl, name, type, depth, parent (index), visible, text (Text controls only) }.
function LM.walk(gui, limit)
    local nodes = {}
    local function visit(ctl, depth, parent)
        if #nodes >= limit or depth > 14 then return end
        local okt, tn = pcall(function() return ctl:get_type_definition():get_full_name() end)
        local node = { ctl = ctl, name = as_text(LM.try(ctl, { "get_Name" })) or "", type = okt and tn or "?",
            depth = depth, parent = parent }
        if node.type:find("^via%.gui%.Text") then node.text = as_text(LM.try(ctl, { "get_Message" })) or "" end
        node.visible = LM.try(ctl, { "get_Visible" }) ~= false
        nodes[#nodes + 1] = node
        local idx = #nodes
        for _, k in ipairs(LM.kids(ctl)) do visit(k, depth + 1, idx) end
    end
    for _, r in ipairs(LM.roots(gui)) do visit(r, 0, 0) end
    return nodes
end

function LM.go_path(go)
    local names = {}
    pcall(function()
        names[1] = tostring(go:call("get_Name"))
        local xf = go:call("get_Transform")
        for _ = 1, 6 do
            xf = xf and xf:call("get_Parent")
            if not xf then break end
            table.insert(names, 1, tostring(xf:call("get_GameObject"):call("get_Name")))
        end
    end)
    return table.concat(names, "/")
end

-- Every via.gui.GUI component in the scene: { gui, path, comps }. findComponents is a single native call; the slow
-- walk of the whole scene is only the fallback for the manual scan (button 10).
function LM.all_guis(allow_slow)
    local out = {}
    local function add(c)
        local okg, go = pcall(c.call, c, "get_GameObject")
        if not okg or not go then return end
        local comps = {}
        pcall(function()
            for _, cc in ipairs(go:call("get_Components"):get_elements()) do
                comps[#comps + 1] = cc:get_type_definition():get_full_name()
            end
        end)
        out[#out + 1] = { gui = c, path = LM.go_path(go), comps = comps }
    end
    local scene = scene_object()
    if not scene then return out, "no scene" end
    for _, method in ipairs({ "findComponents(System.Type)", "findComponents" }) do
        local ok, arr = pcall(function() return scene:call(method, sdk.typeof("via.gui.GUI")) end)
        if ok and arr then
            local oke, elems = pcall(function() return arr:get_elements() end)
            if oke then
                for _, c in ipairs(elems) do add(c) end
                return out, "scene:" .. method
            end
        end
    end
    if not allow_slow then return out, "findComponents failed" end
    pcall(each_gameobject, function(go)
        local okc, comps = pcall(function() return go:call("get_Components"):get_elements() end)
        if not okc then return end
        for _, c in ipairs(comps) do
            local okt, tn = pcall(function() return c:get_type_definition():get_full_name() end)
            if okt and tn == "via.gui.GUI" then add(c) end
        end
    end, 20000)
    return out, "walked the scene"
end

function LM.looks_like_save_screen(g)
    local low = g.path:lower() .. " " .. table.concat(g.comps, " "):lower()
    return low:find("save", 1, true) ~= nil or low:find("load", 1, true) ~= nil or low:find("slot", 1, true) ~= nil
end

-- Finds the list: the control whose children are the most rows of one identical shape. A row's shape is its type
-- plus the name and type of everything below it; the row's own name is left out because the game numbers them
-- (item1, item2 ...). Returns { parent, rows = {node index...}, texts = {row -> text node indexes},
-- number = {row -> the text node with the slot number}, goal = {row -> the objective text node} }.
function LM.find_rows(nodes)
    local kids = {}
    for i, n in ipairs(nodes) do
        if n.parent > 0 then
            kids[n.parent] = kids[n.parent] or {}
            table.insert(kids[n.parent], i)
        end
    end
    local function shape(i)
        local parts = { nodes[i].type }
        local function go(j)
            parts[#parts + 1] = nodes[j].name .. ":" .. nodes[j].type
            for _, c in ipairs(kids[j] or {}) do go(c) end
        end
        for _, c in ipairs(kids[i] or {}) do go(c) end
        return table.concat(parts, ",")
    end
    local function texts(i, acc)
        local n = nodes[i]
        if n.text and n.text ~= "" and n.visible then acc[#acc + 1] = i end
        for _, c in ipairs(kids[i] or {}) do texts(c, acc) end
        return acc
    end
    -- the first node below row i whose name contains `word` (and is a text)
    local function named(i, word)
        local n = nodes[i]
        if n.text and n.name:lower():find(word, 1, true) then return i end
        for _, c in ipairs(kids[i] or {}) do
            local f = named(c, word)
            if f then return f end
        end
        return nil
    end
    local best
    for parent, ks in pairs(kids) do
        local groups = {}
        for _, c in ipairs(ks) do
            local sh = shape(c)
            groups[sh] = groups[sh] or {}
            table.insert(groups[sh], c)
        end
        for _, g in pairs(groups) do
            if #g >= 2 then
                local tx, any, numbered = {}, false, 0
                local number, goal = {}, {}
                for _, r in ipairs(g) do
                    tx[r] = texts(r, {})
                    if #tx[r] > 0 then any = true end
                    number[r], goal[r] = named(r, "number"), named(r, "objective")
                    if number[r] then numbered = numbered + 1 end
                end
                local score = #g + (numbered > 0 and 1000 or 0)
                if any and (not best or score > best.score or (score == best.score and parent < best.parent)) then
                    best = { parent = parent, rows = g, texts = tx, number = number, goal = goal, score = score }
                end
            end
        end
    end
    return best
end

local function tag_of(e)
    -- 9.28: a save I made myself while playing with someone: "who did I play this with"
    if e.role == "played" then return "[CO-OP with " .. tostring(e.partner or "Player") .. "]" end
    if type(e.tag) == "string" and e.tag ~= "" then return e.tag end
    -- a save you made and sent says so: his name is never written on a save that is not his
    if e.role == "sent" then return "[CO-OP: sent to " .. tostring(e.partner or e.from or "Player") .. "]" end
    return "[CO-OP: " .. tostring(e.partner or e.from or "Player") .. "]"
end

-- The slot number the game prints on a row, or nil ("Autosave", empty, anything that is not a plain number).
function LM.row_number(text)
    return tonumber((text or ""):match("^%s*(%d+)%s*$"))
end

-- The manual slots the game itself says exist (SaveDataManager.isExistData: true for 0 = the Autosave and for each manual
-- save). Returns a set {slot = true} and a sorted list, or nil if the game can't be asked.
-- 10.20: game_slots(max_age, limit): `limit` is the highest slot asked (60 when not given); an answer from the last `max_age` seconds that covered at least that many slots is
-- given again instead of asking the game again (nil = always ask). Every real scan is timed: LM.scan_stats goes in the debug file (a scan that took 30 ms or more is listed).
LM.scan_stats = { scans = 0, calls = 0, total_ms = 0, max_ms = 0, slow = {}, served_from_cache = 0 }
function LM.game_slots(max_age, limit)
    limit = limit or 60
    local t0 = os.clock()
    local c = LM.slots_cache
    if c and max_age and t0 - c.at <= max_age and c.limit >= limit then
        LM.scan_stats.served_from_cache = LM.scan_stats.served_from_cache + 1
        return c.set, c.list
    end
    local okm, sm = pcall(sdk.get_managed_singleton, "app.SaveDataManager")
    if not okm or not sm then return nil end
    local set, list, asked = {}, {}, false
    for i = 0, limit do
        local ok, v = pcall(function() return sm:call("isExistData", i) end)
        if ok and v ~= nil then asked = true end
        if ok and v == true and i >= 1 then
            set[i] = true
            list[#list + 1] = i
        end
    end
    local dt = os.clock() - t0
    local st = LM.scan_stats
    st.scans, st.calls, st.total_ms = st.scans + 1, st.calls + limit + 1, st.total_ms + dt * 1000
    if dt * 1000 > st.max_ms then st.max_ms = dt * 1000 end
    if dt >= 0.03 then
        st.slow[#st.slow + 1] = { at = math.floor(t0 * 10) / 10, ms = math.floor(dt * 10000) / 10, slots = limit + 1 }
        while #st.slow > 12 do table.remove(st.slow, 1) end
    end
    if not asked then return nil end
    LM.slots_cache = { at = t0, limit = limit, set = set, list = list }
    return set, list
end

-- {1,2,3,5,6} -> "1-3, 5-6"
function LM.fmt_slots(list)
    if #list == 0 then return "none" end
    local parts, i = {}, 1
    while i <= #list do
        local j = i
        while list[j + 1] == list[j] + 1 do j = j + 1 end
        parts[#parts + 1] = (j > i) and (list[i] .. "-" .. list[j]) or tostring(list[i])
        i = j + 1
    end
    return table.concat(parts, ", ")
end

local function sorted_keys(set)
    local out = {}
    for k in pairs(set) do out[#out + 1] = k end
    table.sort(out)
    return out
end

-- The folder re7mp.exe watches should hold exactly the saves the game lists. One slot of difference is a save that was
-- just made (or just received) and not yet seen by the other side; more than that means another Steam account's folder.
-- Returns true and a note, or false and the message for the panel.
function LM.slot_check(game_set, exe_set)
    local only_game, only_exe = {}, {}
    for s in pairs(game_set) do if not exe_set[s] then only_game[#only_game + 1] = s end end
    for s in pairs(exe_set) do if not game_set[s] then only_exe[#only_exe + 1] = s end end
    table.sort(only_game)
    table.sort(only_exe)
    local diff = #only_game + #only_exe
    if diff == 0 then return true, "the game's saves match re7mp.exe's" end
    if diff == 1 then return true, "a save was just added or removed; re7mp.exe will catch up" end
    local who = (saves.dir or ""):match("userdata[/\\]([^/\\]+)")
    return false, string.format("The game has saves in slots %s but re7mp.exe is watching a folder with slots %s%s. That is probably another Steam account's folder: set 'Save folder' in re7mp.exe to the one for the account you play on (press Detect, or pick the folder by hand).",
        LM.fmt_slots(sorted_keys(game_set)), LM.fmt_slots(sorted_keys(exe_set)), who and (" (Steam account " .. who .. ")") or "")
end

-- Writes (or removes) the tag on one row. rec = { num = control with the slot number, goal = control with the objective }.
-- Returns true if it changed the text.
function LM.apply_row(rec, by_slot)
    local num_text = rec.num and as_text(LM.try(rec.num, { "get_Message" }))
    local cur = as_text(LM.try(rec.goal, { "get_Message" }))
    if cur == nil then return false end
    local n = LM.row_number(num_text)
    local e = n and by_slot[n]
    local plain = cur:match("^%[CO%-OP[: ][^%]]*%] (.*)$") or cur
    local want = e and (tag_of(e) .. " " .. plain) or plain
    if want == cur then return false end
    if pcall(rec.goal.call, rec.goal, "set_Message", want) then
        if e then LM.written = LM.written + 1 end
        return true
    end
    return false
end

-- Labels the rows of a freshly scanned list and remembers their controls so the next checks are cheap.
-- Returns true if the rows could be matched to save slots.
function LM.label_rows(nodes, best, by_slot)
    local occ_set, n_occ = {}, 0
    for _, s in ipairs(saves.occupied or {}) do
        if tonumber(s) then occ_set[math.floor(tonumber(s))] = true n_occ = n_occ + 1 end
    end
    if n_occ == 0 then
        LM.cache = nil
        LM.status = "The exe has not listed the save files yet (re7mp.exe needs 'Share saves' ticked)."
        return false
    end
    local recs, has_number = {}, false
    for _, row in ipairs(best.rows) do
        local ni, gi = best.number[row], best.goal[row]
        if not gi then -- no field called objective: the longest visible text of the row
            for _, ti in ipairs(best.texts[row]) do
                if not gi or #nodes[ti].text > #nodes[gi].text then gi = ti end
            end
        end
        if ni then has_number = true end
        if gi then
            recs[#recs + 1] = { num = ni and nodes[ni].ctl or nil, goal = nodes[gi].ctl }
        end
    end
    if not has_number then
        LM.cache = nil
        LM.status = "The list rows don't show a slot number, so I can't tell which row is which save: nothing labelled. Press button 10 and send me the file."
        return false
    end
    local note = "row N is dataNNNSlot.bin"
    local game_set = LM.game_slots()
    if game_set then
        local ok, why = LM.slot_check(game_set, occ_set)
        if not ok then
            LM.cache = nil
            LM.status = why .. " Nothing labelled."
            return false
        end
        note = note .. "; " .. why
    else
        note = note .. "; the game could not be asked which saves exist, so this is not checked"
    end
    LM.cache = { recs = recs, by_slot = by_slot, note = note, at = os.clock() }
    local wrote = 0
    for _, rec in ipairs(recs) do
        if LM.apply_row(rec, by_slot) then wrote = wrote + 1 end
    end
    LM.status = string.format("Load list found: %d rows, %s. %d label(s) written so far.", #recs, note, LM.written)
    return true
end

-- Between full scans: only the rows already found are looked at, ten times a second. The game rewrites a row's
-- text whenever the list scrolls (it re-uses nine row controls for all your saves), so the labels are put back at once.
function LM.refresh()
    local c = LM.cache
    if not c then return end
    for _, rec in ipairs(c.recs) do LM.apply_row(rec, c.by_slot) end
    LM.status = string.format("Load list found: %d rows, %s. %d label(s) written so far.", #c.recs, c.note, LM.written)
end

-- Is the GUI showing? (A closed menu is not walked: walking a hundred controls is a few thousand calls.)
function LM.is_open(gui)
    for _, r in ipairs(LM.roots(gui)) do
        if LM.try(r, { "get_Visible" }) ~= false then return true end
    end
    return false
end

function LM.update(now)
    if not LM.enabled then return end
    if LM.cache and now - LM.cache.at < 3 then -- a list was found a moment ago: just keep its labels in place
        if now - LM.fast_at < 0.1 then return end
        LM.fast_at = now
        if not pcall(LM.refresh) then LM.cache, LM.last_scan = nil, -100 end
        return
    end
    if now - LM.last_scan < 0.5 then return end
    LM.last_scan = now
    local by_slot, n = {}, 0
    for _, e in ipairs(saves.entries) do
        local slot = type(e) == "table" and tonumber(e.slot)
        if slot then
            by_slot[math.floor(slot)] = e
            n = n + 1
        end
    end
    for sl, p in pairs(saves.played) do -- (9.28) saves I made while playing with someone
        if not by_slot[sl] then
            by_slot[sl] = { slot = sl, role = "played", partner = p.partner }
            n = n + 1
        end
    end
    if n == 0 then
        LM.cache = nil
        LM.status = "No co-op saves yet: nothing to label."
        return
    end
    if #LM.guis == 0 and now - LM.guis_at >= 5 then -- finding the GUIs is the costly part: once, then again only if none was found
        LM.guis_at = now
        local all, how = LM.all_guis(false)
        LM.how = how
        for _, g in ipairs(all) do
            if LM.looks_like_save_screen(g) then LM.guis[#LM.guis + 1] = g end
        end
    end
    if #LM.guis == 0 then
        if LM.how and LM.how:find("^scene:") then
            LM.status = "Waiting: no save/load screen is open."
        else
            LM.status = "Can't list the game's GUIs from here (" .. tostring(LM.how) .. "). Press button 10 and send me the file."
        end
        return
    end
    local unmatched = false
    for _, g in ipairs(LM.guis) do
        local ok, found = pcall(function()
            if not LM.is_open(g.gui) then return nil end
            local nodes = LM.walk(g.gui, 1500)
            local best = LM.find_rows(nodes)
            if not best then return nil end
            return LM.label_rows(nodes, best, by_slot) and "labelled" or "unmatched"
        end)
        if not ok then
            LM.guis, LM.guis_at, LM.cache = {}, -100, nil -- that GUI is gone; look again next time
            LM.status = "Waiting: the save/load screen went away."
            return
        end
        if found == "labelled" then return end
        if found == "unmatched" then unmatched = true end -- a list was found but not matched: label_rows said why
    end
    if not unmatched then
        LM.cache = nil
        LM.status = "Waiting: no save/load screen is open (open the Load Game screen; if it is open and nothing happens, press button 10 and send me the file)."
    end
end

-- Types behind the Load screen: app.SaveMenu is the component on SaveMenuGUI. (The game's own save code, app.SaveDataManager,
-- was listed by the first scans; its slot numbers are plain integers, see LM.game_slots.)
LM.TYPES = { "app.SaveMenu" }

function LM.list_type(name)
    local td = sdk.find_type_definition(name)
    if not td then
        say(name .. ": not found")
        return
    end
    say(name .. ": found")
    local n = 0
    for _, m in ipairs(td:get_methods() or {}) do
        n = n + 1
        if n <= 120 then say("    " .. m:get_name() .. method_signature(m)) end
    end
    local f = 0
    for _, fd in ipairs(td:get_fields() or {}) do
        f = f + 1
        if f <= 60 then
            local okf, line = pcall(function() return fd:get_name() .. " : " .. fd:get_type():get_full_name() end)
            say("    field " .. (okf and line or "?"))
        end
    end
end

-- Button 10: open the Load screen first, then press this.
function LM.dump()
    pinned(function()
        say("=== load screen scan ===")
        local occ = saves.occupied or {}
        say("manual saves in the folder re7mp.exe watches (dataNNNSlot.bin): " .. (#occ > 0 and table.concat(occ, ", ") or "none listed"))
        say("that folder: " .. ((saves.dir or "") ~= "" and saves.dir or "(not reported: update re7mp.exe)"))
        say(saves.accounts_line())
        do
            local gset, glist = LM.game_slots()
            if gset then
                say("manual saves the game says exist (SaveDataManager.isExistData): " .. table.concat(glist, ", "))
                local exe_set = {}
                for _, x in ipairs(occ) do if tonumber(x) then exe_set[math.floor(tonumber(x))] = true end end
                local ok, why = LM.slot_check(gset, exe_set)
                say((ok and "check: " or "MISMATCH: ") .. why)
            else
                say("the game could not be asked which saves exist")
            end
        end
        for _, e in ipairs(saves.entries) do
            if type(e) == "table" then say(string.format("co-op slot %s  %s  %s", tostring(e.slot), tostring(e.role), tag_of(e))) end
        end
        local guis, how = LM.all_guis(true)
        say(string.format("%d via.gui.GUI components (%s)", #guis, how))
        for _, g in ipairs(guis) do
            say(string.format("  %s   [%s]%s", g.path, table.concat(g.comps, ", "), LM.looks_like_save_screen(g) and "   <- looks like a save/load screen" or ""))
        end
        for _, g in ipairs(guis) do
            if LM.looks_like_save_screen(g) then
                local ok, err = pcall(function()
                    local nodes = LM.walk(g.gui, 600)
                    say(string.format("controls of %s (%d shown):", g.path, #nodes))
                    for _, n in ipairs(nodes) do
                        say(string.format("%s%s : %s%s%s", string.rep("  ", n.depth + 1), n.name, n.type, n.visible and "" or " (hidden)",
                            n.text and ('  "' .. n.text:sub(1, 80) .. '"') or ""))
                    end
                    local best = LM.find_rows(nodes)
                    if best then
                        say(string.format("-> list found: %d identical rows under node %d (%s)", #best.rows, best.parent, nodes[best.parent].name))
                        local occ_set = {}
                        for _, s in ipairs(occ) do occ_set[math.floor(tonumber(s) or -1)] = true end
                        local by_slot = {}
                        for _, e in ipairs(saves.entries) do
                            if type(e) == "table" and tonumber(e.slot) then by_slot[math.floor(tonumber(e.slot))] = e end
                        end
                        for _, row in ipairs(best.rows) do
                            local ni, gi = best.number[row], best.goal[row]
                            local numtxt = ni and nodes[ni].text or "?"
                            local k = LM.row_number(numtxt)
                            local file
                            if k then
                                file = string.format("data%03dSlot.bin", k)
                            elseif numtxt == "Autosave" then
                                file = "data000.bin (the Autosave: never shared, never labelled)"
                            else
                                file = "no file"
                            end
                            say(string.format("   row %s%s: number \"%s\" -> %s%s   \"%s\"", nodes[row].name, nodes[row].visible and "" or " (hidden)",
                                numtxt, file,
                                (k and by_slot[k]) and ("  CO-OP " .. tag_of(by_slot[k])) or (k and occ_set[k] and "  single-player" or ""),
                                gi and nodes[gi].text:gsub("^%[CO%-OP: [^%]]*%] ", ""):sub(1, 40) or ""))
                        end
                    else
                        say("-> no list of identical rows found")
                    end
                end)
                if not ok then say("scan error: " .. tostring(err)) end
            end
        end
        local api = {}
        for k, v in pairs(LM.api) do api[#api + 1] = k .. " -> " .. v end
        table.sort(api)
        say("GUI methods that worked: " .. (#api > 0 and table.concat(api, "; ") or "none"))
        say("=== candidate types ===")
        for _, n in ipairs(LM.TYPES) do pcall(LM.list_type, n) end
        local okm, sm = pcall(sdk.get_managed_singleton, "app.SaveDataManager")
        if okm and sm then
            local have = {}
            for i = 0, 40 do
                local oke, v = pcall(function() return sm:call("isExistData", i) end)
                if oke and v == true then have[#have + 1] = i end
            end
            say("SaveDataManager.isExistData(n) is true for n = " .. (#have > 0 and table.concat(have, ", ") or "(none)"))
            say("app.SaveDataManager (singleton):")
            dump_fields(sm, "      ", 40)
        end
        say("=== load screen scan done ===")
    end)
end

function LM.panel()
    local c1, v1 = imgui.checkbox("Label co-op saves in the Load screen (experimental)", LM.enabled)
    if c1 then LM.enabled = v1 LM.last_scan, LM.cache = -100, nil if not v1 then LM.status = "Off." end end
    imgui.text(LM.status)
    if imgui.button("Scan the Load screen (open it first, then press)") then LM.dump() end
end
end -- do

