                        for _, m in ipairs(list) do
                            local verdict, n, _, known = M.verdict(m.fam)
                            imgui.text(string.format("%s  %s: %s  [collected meshes %d, files known %s]", m.name, m.label, verdict, n, known and "yes" or "no"))
                        end
